function supplier_products_db_selected_offer_ids(array $params, string $supplierCode): array
{
    if (function_exists('supplier_push_offer_ids_from_params')) {
        return supplier_products_selected_offer_id_set(supplier_push_offer_ids_from_params($params), $supplierCode);
    }

    $raw = [];
    foreach (['offer_ids', 'selected_offer_ids'] as $key) {
        if (!empty($params[$key]) && is_array($params[$key])) {
            foreach ($params[$key] as $value) {
                $raw[] = $value;
            }
        }
    }
    $json = trim((string)($params['offer_ids_json'] ?? ''));
    if ($json !== '') {
        $decoded = json_decode($json, true);
        if (is_array($decoded)) {
            foreach ($decoded as $value) {
                $raw[] = $value;
            }
        }
    }
    return supplier_products_selected_offer_id_set($raw, $supplierCode);
}

function supplier_products_db_product_is_selected(array $product, array $selectedIds, string $supplierCode): bool
{
    if (!$selectedIds) {
        return true;
    }
    return supplier_products_existing_product_is_selected($product, $selectedIds, $supplierCode);
}

function supplier_products_db_selected_offer_query_candidates(array $selectedIds, string $supplierCode): array
{
    $out = [];
    $supplierCode = suppliers_normalize_code($supplierCode);
    foreach (array_keys($selectedIds) as $offerId) {
        $offerId = trim((string)$offerId);
        if ($offerId === '') {
            continue;
        }
        $out[$offerId] = true;
        if ($supplierCode !== '') {
            $suffix = '__' . $supplierCode;
            if (str_ends_with($offerId, $suffix)) {
                $base = substr($offerId, 0, -strlen($suffix));
                if ($base !== '') {
                    $out[$base] = true;
                }
            }
        }
    }
    return array_keys($out);
}

function supplier_products_db_load_products(int $supplierId, array $params, int $maxItems = 0): array
{
    supplier_products_tables_ensure();
    $supplier = suppliers_get($supplierId);
    if (!is_array($supplier)) {
        throw new RuntimeException('Поставщик не найден.');
    }
    $supplierCode = suppliers_normalize_code((string)($supplier['supplier_code'] ?? ''));
    $selectedIds = supplier_products_db_selected_offer_ids($params, $supplierCode);

    if ($selectedIds) {
        $rows = [];
        $seen = [];
        $candidates = supplier_products_db_selected_offer_query_candidates($selectedIds, $supplierCode);
        foreach (array_chunk($candidates, 500) as $chunk) {
            if (!$chunk) {
                continue;
            }
            $placeholders = implode(',', array_fill(0, count($chunk), '?'));
            $st = db()->prepare("
                SELECT *
                FROM feedtools_supplier_products
                WHERE supplier_id = ?
                  AND offer_id IN ({$placeholders})
                ORDER BY sort_order ASC, id ASC
            ");
            $st->execute(array_merge([$supplierId], $chunk));
            while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
                $productId = (int)($row['id'] ?? 0);
                if ($productId <= 0 || isset($seen[$productId])) {
                    continue;
                }
                if (!supplier_products_db_product_is_selected($row, $selectedIds, $supplierCode)) {
                    continue;
                }
                $seen[$productId] = true;
                $rows[] = $row;
            }
        }
        usort($rows, static function (array $a, array $b): int {
            $sort = (int)($a['sort_order'] ?? 0) <=> (int)($b['sort_order'] ?? 0);
            return $sort !== 0 ? $sort : ((int)($a['id'] ?? 0) <=> (int)($b['id'] ?? 0));
        });
        return $maxItems > 0 ? array_slice($rows, 0, $maxItems) : $rows;
    }

    $st = db()->prepare("
        SELECT *
        FROM feedtools_supplier_products
        WHERE supplier_id = ?
        ORDER BY sort_order ASC, id ASC
    ");
    $st->execute([$supplierId]);

    $rows = [];
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
        if (!supplier_products_db_product_is_selected($row, $selectedIds, $supplierCode)) {
            continue;
        }
        $rows[] = $row;
        if ($maxItems > 0 && count($rows) >= $maxItems) {
            break;
        }
    }
    return $rows;
}

function supplier_products_db_product_ids(array $products): array
{
    $ids = [];
    foreach ($products as $product) {
        $productId = (int)($product['id'] ?? 0);
        if ($productId > 0) {
            $ids[$productId] = true;
        }
    }
    return array_keys($ids);
}

function supplier_products_db_fields_for_products(array $productIds): array
{
    $productIds = array_values(array_unique(array_filter(array_map('intval', $productIds))));
    if (!$productIds) {
        return [];
    }

    supplier_products_tables_ensure();
    $out = [];
    foreach ($productIds as $productId) {
        $out[$productId] = [];
    }

    foreach (array_chunk($productIds, 500) as $chunk) {
        $placeholders = implode(',', array_fill(0, count($chunk), '?'));
        $st = db()->prepare("
            SELECT *
            FROM feedtools_supplier_product_fields
            WHERE product_id IN ({$placeholders})
            ORDER BY product_id ASC, sort_order ASC, id ASC
        ");
        $st->execute($chunk);
        while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
            $productId = (int)($row['product_id'] ?? 0);
            if ($productId > 0) {
                $out[$productId][] = $row;
            }
        }
    }

    return $out;
}

function supplier_products_db_finish_changed_products(int $supplierId, array $changedProductIds, array $cfg, int $opId, bool $updateProgress = true): array
{
    $changedProductIds = array_values(array_unique(array_filter(array_map('intval', $changedProductIds))));
    foreach ($changedProductIds as $productId) {
        supplier_products_sync_product_summary_from_db($productId, $cfg);
    }
    $dataset = supplier_products_update_dataset_row_from_db($supplierId, $cfg);
    if ($updateProgress && function_exists('ops_update_progress')) {
        ops_update_progress($opId, (int)$dataset['offers_count'], (int)$dataset['offers_count'], 'done', 'DB dataset updated');
    }
    return $dataset;
}

function supplier_products_db_report_output(array $cfg, int $datasetId, int $opId, array $report): array
{
    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    $reportAbs = $outDir . '/report.json';
    file_put_contents($reportAbs, json_encode($report, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT));
    return [
        'report_json' => rel_to_outputs($cfg, $reportAbs),
        'summary_json_inline' => $report,
    ];
}

function supplier_products_db_cost_label(array $cfg, string $model, float $amount): string
{
    return openai_format_cost($amount, openai_cost_currency_for_model($cfg, $model));
}

function supplier_products_db_cost_fields(array $cfg, string $model, float $amount): array
{
    $amount = round($amount, 6);
    $currency = openai_cost_currency_for_model($cfg, $model);
    return [
        'cost' => $amount,
        'cost_currency' => $currency,
        'cost_label' => openai_format_cost($amount, $currency),
        // Legacy key kept because old reports and dashboards still read it.
        'cost_usd' => $amount,
    ];
}

function supplier_products_db_estimate_text_tokens(string $text): int
{
    $len = max(0, mb_strlen($text, 'UTF-8'));
    if ($len <= 0) {
        return 0;
    }
    $bytes = strlen($text);
    return max(1, (int)ceil($len / 4), (int)ceil($bytes / 5));
}

function supplier_products_db_estimate_llm_request_usage(
    array $cfg,
    string $model,
    string $systemPrompt,
    string $userMessage,
    int $maxOutputTokens,
    float $expectedOutputRatio = 0.45
): array {
    $inputTokens = supplier_products_db_estimate_text_tokens($systemPrompt . "\n\n" . $userMessage);
    $maxOutputTokens = max(0, $maxOutputTokens);
    $expectedOutputTokens = $maxOutputTokens > 0
        ? max(1, min($maxOutputTokens, (int)ceil($maxOutputTokens * max(0.05, min(1.0, $expectedOutputRatio)))))
        : 0;
    $expectedCost = openai_cost_breakdown($cfg, $model, $inputTokens, 0, $expectedOutputTokens);
    $maxCost = openai_cost_breakdown($cfg, $model, $inputTokens, 0, $maxOutputTokens);
    return [
        'estimated' => true,
        'input_tokens' => $inputTokens,
        'cached_input_tokens' => 0,
        'expected_output_tokens' => $expectedOutputTokens,
        'max_output_tokens' => $maxOutputTokens,
        'expected_cost' => (float)($expectedCost['cost'] ?? 0.0),
        'expected_cost_label' => (string)($expectedCost['cost_label'] ?? ''),
        'max_cost' => (float)($maxCost['cost'] ?? 0.0),
        'max_cost_label' => (string)($maxCost['cost_label'] ?? ''),
        'currency' => (string)($maxCost['currency'] ?? openai_cost_currency_for_model($cfg, $model)),
    ];
}

function supplier_products_db_merge_llm_usage_with_estimate(
    array $cfg,
    string $model,
    ?array $raw,
    string $systemPrompt,
    string $userMessage,
    string $outputText,
    int $maxOutputTokens
): array {
    $currency = openai_cost_currency_for_model($cfg, $model);
    if (is_array($raw) && !empty($raw['_feedtools_cache']['hit'])) {
        return [
            'input' => 0,
            'cached_input' => 0,
            'output' => 0,
            'cost' => 0.0,
            'cost_usd' => 0.0,
            'cost_currency' => $currency,
            'cost_label' => openai_format_cost(0.0, $currency),
            'estimated' => false,
            'local_cache_hit' => true,
        ];
    }

    $usage = supplier_products_db_extract_openai_usage(is_array($raw) ? $raw : null);
    $input = max(0, (int)($usage['input'] ?? 0));
    $cachedInput = max(0, min($input, (int)($usage['cached_input'] ?? 0)));
    $output = max(0, (int)($usage['output'] ?? 0));
    $estimated = false;

    if (($input + $output) <= 0) {
        $estimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $systemPrompt, $userMessage, $maxOutputTokens);
        $input = (int)$estimate['input_tokens'];
        $cachedInput = 0;
        $output = supplier_products_db_estimate_text_tokens($outputText);
        if ($output <= 0 && trim($outputText) !== '') {
            $output = 1;
        }
        $estimated = true;
    }

    $cost = openai_cost_usd($cfg, $model, $input, $cachedInput, $output);
    return [
        'input' => $input,
        'cached_input' => $cachedInput,
        'output' => $output,
        'cost' => $cost,
        'cost_usd' => $cost,
        'cost_currency' => $currency,
        'cost_label' => supplier_products_db_cost_label($cfg, $model, $cost),
        'estimated' => $estimated,
        'local_cache_hit' => false,
    ];
}

function supplier_products_db_pack_quantity_from_number(string $value): ?int
{
    $digits = preg_replace('~[^\d]+~u', '', $value);
    if (!is_string($digits) || $digits === '' || strlen($digits) > 6) {
        return null;
    }
    $qty = (int)$digits;
    if ($qty < 2 || $qty > 100000) {
        return null;
    }
    return $qty;
}

function supplier_products_db_extract_unit_quantity_from_title(string $title): ?int
{
    $title = trim($title);
    if ($title === '') {
        return null;
    }

    $patterns = [
        '~(?:^|(?<=[\s\(\[\{,;:]))(?:уп\.?|уп-?ка|упак\.?|упаковк[аеуы]?)\s*(?:[:№#-]\s*)?(\d[\d\s\x{00A0}]{0,10})\s*(?:шт\.?|штук|ед\.?|pcs?)?(?=$|[\s\)\]\},;:.!?])~iu',
        '~(?:^|(?<=[\s\(\[\{,;:]))(?:в\s+)?упаковк[аеуы]?\s*(?:[:№#-]\s*)?(\d[\d\s\x{00A0}]{0,10})\s*(?:шт\.?|штук|ед\.?|pcs?)?(?=$|[\s\)\]\},;:.!?])~iu',
        '~(?:^|(?<=[\s\(\[\{,;:]))(\d[\d\s\x{00A0}]{0,10})\s*(?:шт\.?|штук|ед\.?|pcs?)\s*(?:в\s+)?(?:уп\.?|уп-?ка|упак\.?|упаковк[аеуы]?)(?=$|[\s\)\]\},;:.!?])~iu',
        '~(?:^|(?<=[\s\(\[\{,;:]))(\d[\d\s\x{00A0}]{0,10})\s*(?:шт\.?|штук|ед\.?|pcs?)(?=$|[\s\)\]\},;:.!?])~iu',
    ];

    foreach ($patterns as $pattern) {
        if (preg_match($pattern, $title, $m)) {
            $qty = supplier_products_db_pack_quantity_from_number((string)($m[1] ?? ''));
            if ($qty !== null) {
                return $qty;
            }
        }
    }

    return null;
}

function supplier_products_db_normalize_unit_pack_in_title(string $title): string
{
    $title = trim($title);
    if ($title === '') {
        return $title;
    }

    $replace = static function (array $m): string {
        $qty = supplier_products_db_pack_quantity_from_number((string)($m['qty'] ?? $m[2] ?? $m[1] ?? ''));
        if ($qty === null) {
            return (string)($m[0] ?? '');
        }
        return (string)($m['prefix'] ?? '') . $qty . ' шт';
    };

    $patterns = [
        '~(?P<prefix>^|[\s\(\[\{,;:])(?:уп\.?|уп-?ка|упак\.?|упаковк[аеуы]?)\s*(?:[:№#-]\s*)?(?P<qty>\d[\d\s\x{00A0}]{0,10})\s*(?:шт\.?|штук|ед\.?|pcs?)?(?=$|[\s\)\]\},;:.!?])~iu',
        '~(?P<prefix>^|[\s\(\[\{,;:])(?:в\s+)?упаковк[аеуы]?\s*(?:[:№#-]\s*)?(?P<qty>\d[\d\s\x{00A0}]{0,10})\s*(?:шт\.?|штук|ед\.?|pcs?)?(?=$|[\s\)\]\},;:.!?])~iu',
        '~(?P<prefix>^|[\s\(\[\{,;:])(?P<qty>\d[\d\s\x{00A0}]{0,10})\s*(?:шт\.?|штук|ед\.?|pcs?)\s*(?:в\s+)?(?:уп\.?|уп-?ка|упак\.?|упаковк[аеуы]?)(?=$|[\s\)\]\},;:.!?])~iu',
    ];

    $out = $title;
    foreach ($patterns as $pattern) {
        $next = preg_replace_callback($pattern, $replace, $out);
        if (is_string($next)) {
            $out = $next;
        }
    }

    $out = preg_replace('~\s+([\)\]\},;:.!?])~u', '$1', $out);
    $out = preg_replace('~([\(\[\{])\s+~u', '$1', (string)$out);
    $out = preg_replace('~\s{2,}~u', ' ', (string)$out);
    return trim((string)$out);
}

function supplier_products_db_wb_title_limit(): int
{
    return 200;
}

function supplier_products_db_title_norm_spaces(string $value): string
{
    $value = trim((string)$value);
    if ($value === '') {
        return '';
    }
    $value = str_replace(["\r", "\n", "\t", "\xC2\xA0", "\xE2\x80\x8B"], ' ', $value);
    $value = preg_replace('/\s+/u', ' ', (string)$value);
    return trim((string)$value);
}

function supplier_products_db_title_cleanup_after_remove(string $value): string
{
    $value = supplier_products_db_title_norm_spaces($value);
    if ($value === '') {
        return '';
    }

    $value = preg_replace('/\s*([,;:\/\-])\s*/u', '$1 ', $value);
    $value = preg_replace('/([\(\[])\s+/u', '$1', (string)$value);
    $value = preg_replace('/\s*([\)\]])\s*/u', '$1 ', (string)$value);
    $value = preg_replace('~(?<=\p{L}|\p{N})-\s+(?=\p{L}|\p{N})~u', '-', (string)$value);
    $value = preg_replace('/(?:^| )[,;:\/\-]+(?= )/u', ' ', (string)$value);
    $value = preg_replace('/[\(\[]\s*[\)\]]/u', ' ', (string)$value);
    $value = preg_replace('~\s+([\)\]\},;:.!?])~u', '$1', (string)$value);
    $value = preg_replace('~([\(\[\{])\s+~u', '$1', (string)$value);
    $value = preg_replace('/\s+/u', ' ', (string)$value);
    return trim((string)$value, " \t\n\r\0\x0B-–—,;:/()[]");
}

function supplier_products_db_title_remove_token(string $name, string $token): string
{
    $name = supplier_products_db_title_norm_spaces($name);
    $token = supplier_products_db_title_norm_spaces($token);
    if ($name === '' || $token === '') {
        return $name;
    }
    if (mb_strlen($token, 'UTF-8') < 3) {
        return $name;
    }

    $pattern = preg_quote($token, '/');
    $clean = preg_replace('/(?<!\p{L}|\p{N})' . $pattern . '(?!\p{L}|\p{N})/iu', ' ', $name);
    $clean = (string)$clean;
    if ($clean === $name) {
        return $name;
    }
    $clean = supplier_products_db_title_cleanup_after_remove($clean);
    return $clean !== '' ? $clean : $name;
}

function supplier_products_db_title_article_tokens(string $offerId, string $vendorCode): array
{
    $tokens = [];
    $add = static function (string $token) use (&$tokens): void {
        $token = supplier_products_db_title_norm_spaces($token);
        if ($token === '' || mb_strlen($token, 'UTF-8') < 3) {
            return;
        }
        $key = mb_strtolower($token, 'UTF-8');
        $tokens[$key] = $token;
    };

    foreach ([$offerId, $vendorCode] as $raw) {
        $raw = supplier_products_db_title_norm_spaces($raw);
        if ($raw === '') {
            continue;
        }
        $add($raw);

        $bundlePos = mb_strrpos($raw, '##', 0, 'UTF-8');
        $withoutBundle = $bundlePos !== false
            ? trim((string)mb_substr($raw, $bundlePos + 2, null, 'UTF-8'))
            : $raw;
        if ($withoutBundle !== $raw) {
            $add($withoutBundle);
        }

        $supplierPos = strpos($withoutBundle, '__');
        if ($supplierPos !== false) {
            $add((string)substr($withoutBundle, 0, $supplierPos));
        }
        $supplierPosRaw = strpos($raw, '__');
        if ($supplierPosRaw !== false) {
            $add((string)substr($raw, 0, $supplierPosRaw));
        }
    }

    $out = array_values($tokens);
    usort($out, static fn(string $a, string $b): int => mb_strlen($b, 'UTF-8') <=> mb_strlen($a, 'UTF-8'));
    return $out;
}

function supplier_products_db_title_strip_article(
    string $title,
    string $offerId,
    string $vendorCode
): string {
    $original = supplier_products_db_title_norm_spaces($title);
    $clean = $original;
    if ($clean === '') {
        return '';
    }

    foreach (supplier_products_db_title_article_tokens($offerId, $vendorCode) as $token) {
        $clean = supplier_products_db_title_remove_token($clean, $token);
    }

    $clean = supplier_products_db_title_cleanup_after_remove($clean);
    return $clean !== '' ? $clean : $original;
}

function supplier_products_db_title_trim_to_wb_limit(string $title, int $limit = 200): string
{
    $title = supplier_products_db_title_norm_spaces($title);
    if ($title === '' || $limit <= 0) {
        return '';
    }
    if (mb_strlen($title, 'UTF-8') <= $limit) {
        return $title;
    }

    $slice = trim((string)mb_substr($title, 0, $limit, 'UTF-8'));
    $spacePos = mb_strrpos($slice, ' ', 0, 'UTF-8');
    if ($spacePos !== false && $spacePos >= (int)floor($limit * 0.55)) {
        $slice = trim((string)mb_substr($slice, 0, $spacePos, 'UTF-8'));
    }
    $slice = rtrim($slice, " \t\n\r\0\x0B,;:-/()");
    return $slice !== '' ? $slice : trim((string)mb_substr($title, 0, $limit, 'UTF-8'));
}

function supplier_products_db_prepare_canonical_title(
    string $title,
    string $brand,
    string $vendor,
    string $offerId,
    string $vendorCode
): string {
    $original = supplier_products_db_title_norm_spaces($title);
    $title = supplier_products_db_clean_title_for_prompt($original, $brand, $vendor, $offerId, $vendorCode);
    if ($title === '' && $original !== '') {
        $title = $original;
    }
    return $title;
}

function supplier_products_db_clean_title_for_prompt(
    string $title,
    string $brand,
    string $vendor,
    string $offerId,
    string $vendorCode
): string {
    $original = supplier_products_db_title_norm_spaces($title);
    $title = supplier_products_db_normalize_unit_pack_in_title($original);
    $title = supplier_products_db_title_strip_article($title, $offerId, $vendorCode);
    $title = supplier_products_db_normalize_unit_pack_in_title($title);
    $title = supplier_products_db_title_norm_spaces($title);
    return $title !== '' ? $title : $original;
}

function supplier_products_db_title_guard_normalize(string $value): string
{
    $value = trim($value);
    if ($value === '') {
        return '';
    }
    $value = str_replace(['Ё', 'ё'], ['Е', 'е'], $value);
    $value = mb_strtolower($value, 'UTF-8');
    $value = preg_replace('~[^\p{L}\p{N}]+~u', '', $value);
    return trim((string)$value);
}

function supplier_products_db_title_guard_is_noise_token(string $norm): bool
{
    if ($norm === '') {
        return true;
    }
    static $noise = [
        'new' => true,
        'hot' => true,
        'original' => true,
        'orig' => true,
        'top' => true,
        'best' => true,
        'sale' => true,
        'скидка' => true,
        'новинка' => true,
        'лучший' => true,
        'топ' => true,
        '100' => true,
    ];
    return isset($noise[$norm]);
}

function supplier_products_db_title_guard_add_token(array &$tokens, string $token, string $originalNorm): void
{
    $token = trim($token);
    if ($token === '') {
        return;
    }
    $norm = supplier_products_db_title_guard_normalize($token);
    if ($norm === '' || supplier_products_db_title_guard_is_noise_token($norm)) {
        return;
    }
    $normLen = mb_strlen($norm, 'UTF-8');
    $hasDigit = (bool)preg_match('~\d~u', $norm);
    if ($normLen < 3 && (!$hasDigit || $normLen < 2)) {
        return;
    }
    if ($originalNorm !== '' && strpos($originalNorm, $norm) === false) {
        return;
    }
    $tokens[$norm] = $token;
}

function supplier_products_db_title_guard_color_patterns(): array
{
    return [
        'черный' => '~(?<!\p{L})черн(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'белый' => '~(?<!\p{L})бел(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'серый' => '~(?<!\p{L})сер(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'красный' => '~(?<!\p{L})красн(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'синий' => '~(?<!\p{L})син(?:ий|яя|ее|ие|его|ему|им|их|юю)?(?!\p{L})~u',
        'голубой' => '~(?<!\p{L})голуб(?:ой|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'зеленый' => '~(?<!\p{L})зелен(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'желтый' => '~(?<!\p{L})желт(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'оранжевый' => '~(?<!\p{L})оранжев(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'фиолетовый' => '~(?<!\p{L})фиолетов(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'розовый' => '~(?<!\p{L})розов(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'коричневый' => '~(?<!\p{L})коричнев(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'бежевый' => '~(?<!\p{L})бежев(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'золотой' => '~(?<!\p{L})золот(?:ой|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'серебристый' => '~(?<!\p{L})серебрист(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
        'прозрачный' => '~(?<!\p{L})прозрачн(?:ый|ая|ое|ые|ого|ому|ым|ых|ую)?(?!\p{L})~u',
    ];
}

function supplier_products_db_title_guard_color_present(string $token, string $text): bool
{
    $token = str_replace('ё', 'е', mb_strtolower(trim($token), 'UTF-8'));
    $text = str_replace('ё', 'е', mb_strtolower($text, 'UTF-8'));
    if ($token === '' || $text === '') {
        return false;
    }

    foreach (supplier_products_db_title_guard_color_patterns() as $canonical => $pattern) {
        if (($token === $canonical || preg_match($pattern, $token)) && preg_match($pattern, $text)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_title_guard_token_present(string $norm, string $token, string $newName, string $newNorm): bool
{
    if ($newNorm !== '' && $norm !== '' && strpos($newNorm, $norm) !== false) {
        return true;
    }
    if (supplier_products_db_title_guard_color_present($token, $newName)) {
        return true;
    }

    if (!preg_match('~[\s,;:/()\[\]{}]+~u', $token)) {
        return false;
    }
    if (!preg_match_all('~[\p{L}\p{N}]+~u', $token, $matches)) {
        return false;
    }

    $stop = [
        'для' => true,
        'и' => true,
        'или' => true,
        'с' => true,
        'со' => true,
        'на' => true,
        'в' => true,
        'от' => true,
        'до' => true,
        'без' => true,
    ];
    $required = [];
    foreach ((array)($matches[0] ?? []) as $word) {
        $word = trim((string)$word);
        $wordNorm = supplier_products_db_title_guard_normalize($word);
        if ($wordNorm === '' || isset($stop[$wordNorm]) || supplier_products_db_title_guard_is_noise_token($wordNorm)) {
            continue;
        }
        $wordLen = mb_strlen($wordNorm, 'UTF-8');
        $hasDigit = (bool)preg_match('~\d~u', $wordNorm);
        if ($wordLen < 3 && (!$hasDigit || $wordLen < 2)) {
            continue;
        }
        $required[] = [
            'word' => $word,
            'norm' => $wordNorm,
            'strict' => (bool)preg_match('~(?:\d|[A-Za-z])~u', $word),
        ];
    }
    if (count($required) < 2) {
        return false;
    }

    $present = 0;
    $strictTotal = 0;
    $strictPresent = 0;
    foreach ($required as $part) {
        $partPresent = $newNorm !== '' && strpos($newNorm, (string)$part['norm']) !== false;
        if (!$partPresent && supplier_products_db_title_guard_color_present((string)$part['word'], $newName)) {
            $partPresent = true;
        }
        if (!empty($part['strict'])) {
            $strictTotal++;
            if ($partPresent) {
                $strictPresent++;
            }
        }
        if ($partPresent) {
            $present++;
        }
    }

    if ($strictTotal > 0 && $strictPresent < $strictTotal) {
        return false;
    }
    return $present >= (int)ceil(count($required) * 0.75);
}

function supplier_products_db_title_guard_important_tokens(string $originalName, array $inputObj): array
{
    $originalNorm = supplier_products_db_title_guard_normalize($originalName);
    $tokens = [];
    $product = is_array($inputObj['product'] ?? null) ? $inputObj['product'] : [];

    foreach ((array)($product['must_keep_tokens'] ?? []) as $token) {
        supplier_products_db_title_guard_add_token($tokens, (string)$token, $originalNorm);
    }

    foreach (['vendor', 'brand', 'model'] as $key) {
        supplier_products_db_title_guard_add_token($tokens, (string)($product[$key] ?? ''), $originalNorm);
    }

    $fields = is_array($product['fields'] ?? null) ? $product['fields'] : [];
    foreach (['model', 'brand', 'vendor'] as $key) {
        supplier_products_db_title_guard_add_token($tokens, (string)($fields[$key] ?? ''), $originalNorm);
    }

    if (preg_match_all('~[\p{L}\p{N}]+(?:[.,_#+*\-][\p{L}\p{N}]+)+|[\p{L}]*\d[\p{L}\p{N}.,_#+*\-]*|[A-ZА-ЯЁ]{2,}\d*~u', $originalName, $m)) {
        foreach ((array)($m[0] ?? []) as $token) {
            supplier_products_db_title_guard_add_token($tokens, (string)$token, $originalNorm);
            if (count($tokens) >= 40) {
                break;
            }
        }
    }

    return $tokens;
}

function supplier_products_db_title_missing_important_tokens(string $originalName, string $newName, array $inputObj): array
{
    $newNorm = supplier_products_db_title_guard_normalize($newName);
    $missing = [];

    $originalQty = supplier_products_db_extract_unit_quantity_from_title($originalName);
    if ($originalQty !== null) {
        $newQty = supplier_products_db_extract_unit_quantity_from_title($newName);
        if ($newQty !== $originalQty) {
            $missing[] = $originalQty . ' шт';
        }
    }

    foreach (supplier_products_db_title_guard_important_tokens($originalName, $inputObj) as $norm => $token) {
        if (!supplier_products_db_title_guard_token_present((string)$norm, (string)$token, $newName, $newNorm)) {
            $missing[] = (string)$token;
            if (count($missing) >= 8) {
                break;
            }
        }
    }

    return array_values(array_unique($missing));
}

function supplier_products_db_title_repair_missing_important_tokens(
    string $newName,
    array $missingTokens,
    string $originalName,
    int $limit
): string {
    $base = supplier_products_db_title_norm_spaces($newName);
    $originalName = supplier_products_db_title_norm_spaces($originalName);
    if ($base === '' || $originalName === '' || !$missingTokens || $limit <= 0) {
        return '';
    }

    $missingNorms = [];
    foreach ($missingTokens as $token) {
        $norm = supplier_products_db_title_guard_normalize((string)$token);
        if ($norm !== '') {
            $missingNorms[$norm] = (string)$token;
        }
    }
    if (!$missingNorms) {
        return '';
    }

    $tokens = [];
    $coveredNorms = [];
    $addToken = static function (string $token) use (&$tokens, &$coveredNorms, $missingNorms): void {
        $token = trim($token);
        if ($token === '') {
            return;
        }
        $norm = supplier_products_db_title_guard_normalize($token);
        if ($norm === '') {
            return;
        }
        $relevant = false;
        foreach ($missingNorms as $missingNorm => $_missingToken) {
            if ($missingNorm !== '' && (str_contains($norm, $missingNorm) || str_contains($missingNorm, $norm))) {
                $coveredNorms[$missingNorm] = true;
                $relevant = true;
            }
        }
        if (!$relevant) {
            return;
        }
        $key = mb_strtolower($token, 'UTF-8');
        $tokens[$key] = $token;
    };

    $compositeSource = preg_replace('~(?<=\p{L}|\p{N})\s*([-_])\s*(?=\p{L}|\p{N})~u', '$1', $originalName);
    if (preg_match_all('~[\p{L}\p{N}]+(?:[-_][\p{L}\p{N}]+)+~u', (string)$compositeSource, $matches)) {
        foreach ((array)($matches[0] ?? []) as $token) {
            $addToken((string)$token);
        }
    }

    foreach ($missingNorms as $missingNorm => $token) {
        if (isset($coveredNorms[$missingNorm])) {
            continue;
        }
        $token = trim((string)$token);
        if ($token !== ''
            && mb_strlen($token, 'UTF-8') <= 24
            && preg_match('~(?:\d|[A-ZА-ЯЁ]{2,})~u', $token)
        ) {
            $addToken($token);
        }
    }

    $tokens = array_values($tokens);
    if (!$tokens) {
        return '';
    }

    $suffixes = [
        ' (' . implode(', ', $tokens) . ')',
        ' (' . implode('/', $tokens) . ')',
        ' ' . implode(' ', $tokens),
    ];
    foreach ($suffixes as $suffix) {
        $candidate = supplier_products_db_title_norm_spaces($base . $suffix);
        if ($candidate !== '' && mb_strlen($candidate, 'UTF-8') <= $limit) {
            return $candidate;
        }
    }

    return '';
}

function supplier_products_db_title_keep_requested(array $decoded): bool
{
    foreach (['action', 'decision'] as $key) {
        $value = mb_strtolower(trim((string)($decoded[$key] ?? '')), 'UTF-8');
        if (in_array($value, ['keep', 'skip', 'no_change', 'unchanged', 'оставить', 'не менять'], true)) {
            return true;
        }
    }
    if (array_key_exists('should_update', $decoded)) {
        $value = $decoded['should_update'];
        if ($value === false || $value === 0 || $value === '0') {
            return true;
        }
        if (is_string($value) && in_array(mb_strtolower(trim($value), 'UTF-8'), ['false', 'no', 'нет'], true)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_is_unit_quantity_attribute(string $name): bool
{
    if (function_exists('supplier_products_characteristic_group_key')) {
        return supplier_products_characteristic_group_key($name) === 'alias:unit_quantity';
    }
    $unitKeys = [
        'количество товара в уеи',
        'количество в единице товара',
        'количество в упаковке шт',
        'количество штук в упаковке',
        'количество товаров в упаковке',
        'количество единиц в товаре',
        'единиц в одном товаре',
    ];
    $nameKey = supplier_products_db_attr_norm($name);
    foreach ($unitKeys as $key) {
        if ($nameKey !== '' && $nameKey === supplier_products_db_attr_norm($key)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_unit_quantity_value_number(string $value): ?int
{
    $value = trim(str_replace("\xc2\xa0", ' ', $value));
    if ($value === '') {
        return null;
    }
    if (!preg_match('~^(\d[\d\s]{0,10})\s*(?:шт\.?|штук|ед\.?|pcs?|pieces?)?$~iu', $value, $m)) {
        return null;
    }
    return supplier_products_db_pack_quantity_from_number((string)($m[1] ?? ''));
}

function supplier_products_db_unit_quantity_text(string $value): string
{
    $value = html_entity_decode(strip_tags($value), ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $value = str_replace(["\xc2\xa0", "\xe2\x80\x8b"], ' ', $value);
    $value = mb_strtolower($value, 'UTF-8');
    $value = str_replace('ё', 'е', $value);
    $value = preg_replace('~\s+~u', ' ', (string)$value);
    return trim((string)$value);
}

function supplier_products_db_unit_quantity_battery_cell_signal(string $text, int $qty): bool
{
    if ($qty <= 1) {
        return false;
    }
    $text = supplier_products_db_unit_quantity_text($text);
    if ($text === '') {
        return false;
    }
    $q = preg_quote((string)$qty, '~');
    $hasBatteryContext = preg_match('~(?:аккумулятор|акб|батаре|lipo|li\s*po|lihv|li\s*hv|li-?ion|battery|fpv|дрон|квадрокоптер)~iu', $text) === 1;
    $hasCellSignal = preg_match('~(?:^|[^\p{L}\p{N}])' . $q . '\s*s\s*(?:\d+\s*p)?(?=$|[^\p{L}\p{N}])~iu', $text) === 1
        || preg_match('~(?:^|[^\p{L}\p{N}])' . $q . '\s*(?:ячее?к|ячейки|ячеек|cells?|бан(?:ок|ки|ка)?)(?=$|[^\p{L}\p{N}])~iu', $text) === 1
        || preg_match('~(?:ячее?к|ячейки|ячеек|cells?|бан(?:ок|ки|ка)?)\D{0,24}' . $q . '(?=$|[^\p{L}\p{N}])~iu', $text) === 1;
    return $hasCellSignal && ($hasBatteryContext || preg_match('~(?:ячее?к|ячейки|ячеек|cells?)~iu', $text) === 1);
}

function supplier_products_db_unit_quantity_source_identity_text(array $product): string
{
    $parts = [
        (string)($product['name'] ?? ''),
        (string)($product['source_line'] ?? ''),
        (string)($product['model'] ?? ''),
        (string)($product['category_path'] ?? ''),
        (string)($product['supplier_category_path'] ?? ''),
        (string)($product['category_name'] ?? ''),
    ];
    return implode("\n", array_values(array_filter($parts, static fn($part): bool => trim((string)$part) !== '')));
}

function supplier_products_db_unit_quantity_in_one_formula_signal(string $text, int $qty): bool
{
    if ($qty <= 1) {
        return false;
    }
    $text = supplier_products_db_unit_quantity_text($text);
    if ($text === '') {
        return false;
    }

    $q = preg_quote((string)$qty, '~');
    $hasInOneFormula = preg_match('~(?:^|[^\p{L}\p{N}])' . $q . '\s*(?:в|in)\s*1(?=$|[^\p{L}\p{N}])~iu', $text) === 1
        || preg_match('~(?:^|[^\p{L}\p{N}])' . $q . '\s*[-–—]\s*in\s*[-–—]\s*1(?=$|[^\p{L}\p{N}])~iu', $text) === 1
        || preg_match('~(?:^|[^\p{L}\p{N}])' . $q . '\s*в\s*1(?=$|[^\p{L}\p{N}])~iu', $text) === 1;
    if (!$hasInOneFormula) {
        return false;
    }

    return preg_match('~(?:защитн\p{L}*\s+(?:стекл|пленк)|(?:стекл|пленк)\p{L}*\s+(?:для|на)\s*(?:телефон|смартфон|экран)|screen\s+protector|tempered\s+glass|hydrogel|og\s+glass)~iu', $text) === 1;
}

function supplier_products_db_unit_quantity_in_one_false_pack_signal(array $product, int $qty): bool
{
    if ($qty <= 1) {
        return false;
    }

    $text = supplier_products_db_unit_quantity_source_identity_text($product);
    if (!supplier_products_db_unit_quantity_in_one_formula_signal($text, $qty)) {
        return false;
    }

    $explicitTitleQty = supplier_products_db_extract_unit_quantity_from_title($text);
    if ($explicitTitleQty !== null && $explicitTitleQty === $qty) {
        return false;
    }
    return !supplier_products_db_unit_quantity_has_pack_evidence($text, $qty);
}

function supplier_products_db_unit_quantity_has_pack_evidence(string $text, int $qty): bool
{
    if ($qty <= 1) {
        return true;
    }
    $text = supplier_products_db_unit_quantity_text($text);
    if ($text === '') {
        return false;
    }
    $q = preg_quote((string)$qty, '~');
    $patterns = [
        '~(?:комплект|набор|упаковк\p{L}*|пачк\p{L}*|pack|set|bundle|комплектац)\D{0,40}' . $q . '\D{0,28}(?:шт\.?|штук|ед\.?|pcs?|pieces?|товар|предмет|издел|детал|аккумулятор|батаре)~iu',
        '~(?:комплект|набор|упаковк\p{L}*|пачк\p{L}*|pack|set|bundle)\s*(?:из|of)?\s*' . $q . '(?=$|[^\p{L}\p{N}])~iu',
        '~(?:в\s+комплекте|в\s+наборе)\D{0,28}' . $q . '(?=$|[^\p{L}\p{N}])~iu',
        '~(?:^|[^\p{L}\p{N}])' . $q . '\s*(?:шт\.?|штук|ед\.?|pcs?|pieces?)\D{0,42}(?:комплект|набор|упаковк\p{L}*|пачк\p{L}*|pack|set|bundle|в\s+комплекте)~iu',
        '~(?:^|[^\p{L}\p{N}])' . $q . '\s*[xх]\D{0,30}(?:комплект|набор|упаковк\p{L}*|шт\.?|штук|pcs?)~iu',
        '~(?:комплект|набор|упаковк\p{L}*|pack|set)\D{0,18}[xх]\s*' . $q . '(?=$|[^\p{L}\p{N}])~iu',
    ];
    foreach ($patterns as $pattern) {
        if (preg_match($pattern, $text)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_unit_quantity_context_text(array $product, array $fields, bool $includeUnitQuantityFields = false): string
{
    $parts = [
        (string)($product['name'] ?? ''),
        (string)($product['source_line'] ?? ''),
        (string)($product['model'] ?? ''),
        (string)($product['description'] ?? ($product['description_html'] ?? '')),
    ];
    foreach ($fields as $field) {
        if (!is_array($field)) {
            continue;
        }
        $kind = (string)($field['field_kind'] ?? '');
        if ($kind !== 'param' && $kind !== 'wb_param' && $kind !== 'feature' && $kind !== 'tag' && $kind !== 'standard') {
            continue;
        }
        $name = trim((string)($field['field_name'] ?? ''));
        if (!$includeUnitQuantityFields && supplier_products_db_is_unit_quantity_attribute($name)) {
            continue;
        }
        $value = trim((string)($field['field_value'] ?? ''));
        if ($name !== '' || $value !== '') {
            $parts[] = trim($name . ': ' . $value);
        }
    }
    return implode("\n", array_values(array_filter($parts, static fn($part): bool => trim((string)$part) !== '')));
}

function supplier_products_db_detect_unit_quantity_from_text(string $text): ?int
{
    $text = supplier_products_db_unit_quantity_text($text);
    if ($text === '') {
        return null;
    }
    $patterns = [
        '~(?:комплект|набор|упаковк\p{L}*|пачк\p{L}*|pack|set|bundle)\s*(?:из|of)?\s*(\d{1,6})(?=$|[^\p{L}\p{N}])~iu',
        '~(?:в\s+комплекте|в\s+наборе)\D{0,28}(\d{1,6})(?=$|[^\p{L}\p{N}])~iu',
        '~(?:^|[^\p{L}\p{N}])(\d{1,6})\s*(?:шт\.?|штук|ед\.?|pcs?|pieces?)\D{0,42}(?:комплект|набор|упаковк\p{L}*|пачк\p{L}*|pack|set|bundle|в\s+комплекте)~iu',
    ];
    foreach ($patterns as $pattern) {
        if (!preg_match($pattern, $text, $m)) {
            continue;
        }
        $qty = supplier_products_db_pack_quantity_from_number((string)($m[1] ?? ''));
        if ($qty !== null && supplier_products_db_unit_quantity_has_pack_evidence($text, $qty)) {
            return $qty;
        }
    }
    return null;
}

function supplier_products_db_detect_unit_quantity_from_product(array $product, array $fields): ?int
{
    $offerId = trim((string)($product['offer_id'] ?? ($product['offer_key'] ?? '')));
    $parsed = function_exists('bundle_offer_parse') ? bundle_offer_parse($offerId) : [];
    if (!empty($parsed['is_bundle'])) {
        $qty = max(1, (int)($parsed['bundle_qty'] ?? 1));
        return $qty > 1 ? $qty : null;
    }

    $title = (string)($product['name'] ?? '');
    $fromTitle = supplier_products_db_extract_unit_quantity_from_title($title);
    if ($fromTitle !== null && $fromTitle > 1) {
        return $fromTitle;
    }

    $text = supplier_products_db_unit_quantity_context_text($product, $fields, false);
    $qty = supplier_products_db_detect_unit_quantity_from_text($text);
    if (
        $qty !== null
        && !supplier_products_db_unit_quantity_battery_cell_signal($text, $qty)
        && !supplier_products_db_unit_quantity_in_one_false_pack_signal($product, $qty)
    ) {
        return $qty;
    }
    return null;
}

function supplier_products_db_unit_quantity_allowed_for_product(array $product, array $fields, int $qty): bool
{
    if ($qty <= 1) {
        return true;
    }
    if (supplier_products_db_unit_quantity_in_one_false_pack_signal($product, $qty)) {
        return false;
    }
    $detected = supplier_products_db_detect_unit_quantity_from_product($product, $fields);
    if ($detected !== null && $detected === $qty) {
        return true;
    }
    $text = supplier_products_db_unit_quantity_context_text($product, $fields, false);
    if (supplier_products_db_unit_quantity_battery_cell_signal($text, $qty)) {
        return false;
    }
    return supplier_products_db_unit_quantity_has_pack_evidence($text, $qty);
}

function supplier_products_db_detected_unit_quantity_param_rows(array $job): array
{
    $qty = (int)($job['detected_unit_quantity'] ?? 0);
    if ($qty <= 1) {
        return [];
    }

    $rows = [];
    foreach ((array)($job['marketplace_contexts'] ?? []) as $ctx) {
        if (!is_array($ctx)) {
            continue;
        }
        $source = (string)($ctx['source'] ?? '');
        if ($source !== 'ozon' && $source !== 'wildberries') {
            continue;
        }
        $kind = $source === 'wildberries' ? 'wb_param' : 'param';
        foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
            if (!is_array($attr)) {
                continue;
            }
            $name = trim((string)($attr['name'] ?? ''));
            $nameKey = supplier_products_db_attr_norm($name);
            if ($name === '' || $nameKey === '' || !supplier_products_db_is_unit_quantity_attribute($name)) {
                continue;
            }
            $allowedValues = supplier_products_db_values_allowed_for_attr((string)$qty, $attr);
            foreach ($allowedValues as $value) {
                if ($value === '') {
                    continue;
                }
                $rows[$source . "\n" . $nameKey] = [
                    'marketplace' => $source,
                    'kind' => $kind,
                    'name' => $name,
                    'value' => (string)$value,
                    'detected_from_title' => true,
                ];
            }
        }
    }

    return array_values($rows);
}

function supplier_products_db_dimension_attribute_role(string $name): string
{
    $key = supplier_products_db_attr_norm($name);
    if ($key === '') {
        return '';
    }

    $exact = [
        'длина мм' => 'length_mm',
        'длина упаковки мм' => 'length_mm',
        'длина товара мм' => 'length_mm',
        'ширина мм' => 'width_mm',
        'ширина упаковки мм' => 'width_mm',
        'ширина товара мм' => 'width_mm',
        'высота мм' => 'height_mm',
        'высота упаковки мм' => 'height_mm',
        'высота товара мм' => 'height_mm',
        'размеры мм' => 'dimensions_mm',
        'размер мм' => 'dimensions_mm',
        'габариты мм' => 'dimensions_mm',
        'вес товара г' => 'weight_g',
        'вес в упаковке г' => 'weight_g',
        'вес товара с упаковкой г' => 'weight_g',
    ];
    if (isset($exact[$key])) {
        return $exact[$key];
    }

    if (str_contains($key, 'размер') && preg_match('~(?:^| )мм(?: |$)~u', $key)) {
        return 'dimensions_mm';
    }
    if (str_contains($key, 'габарит') && preg_match('~(?:^| )мм(?: |$)~u', $key)) {
        return 'dimensions_mm';
    }
    if (str_contains($key, 'ширин') && preg_match('~(?:^| )мм(?: |$)~u', $key)) {
        return 'width_mm';
    }
    if (str_contains($key, 'высот') && preg_match('~(?:^| )мм(?: |$)~u', $key)) {
        return 'height_mm';
    }
    if ((str_contains($key, 'длин') || str_contains($key, 'глубин')) && preg_match('~(?:^| )мм(?: |$)~u', $key)) {
        return 'length_mm';
    }
    if (str_contains($key, 'вес') && (preg_match('~(?:^| )г(?: |$)~u', $key) || str_contains($key, 'грам'))) {
        return 'weight_g';
    }

    return '';
}

function supplier_products_db_dimension_param_rows(array $job): array
{
    $standard = (array)($job['standard'] ?? []);
    $dims = supplier_push_dimensions(['standard' => $standard]);
    $mm = is_array($dims['mm'] ?? null) ? $dims['mm'] : [];
    $weightG = supplier_push_weight_g((string)($standard['weight'] ?? ''));

    $l = isset($mm[0]) && $mm[0] !== null && (int)$mm[0] > 0 ? (string)(int)$mm[0] : '';
    $w = isset($mm[1]) && $mm[1] !== null && (int)$mm[1] > 0 ? (string)(int)$mm[1] : '';
    $h = isset($mm[2]) && $mm[2] !== null && (int)$mm[2] > 0 ? (string)(int)$mm[2] : '';

    $valuesByRole = [
        'length_mm' => $l,
        'width_mm' => $w,
        'height_mm' => $h,
        'dimensions_mm' => ($l !== '' && $w !== '' && $h !== '') ? ($l . ' x ' . $w . ' x ' . $h) : '',
        'weight_g' => $weightG !== null && $weightG > 0 ? (string)$weightG : '',
    ];

    $rows = [];
    foreach ((array)($job['marketplace_contexts'] ?? []) as $ctx) {
        if (!is_array($ctx)) {
            continue;
        }
        $source = (string)($ctx['source'] ?? '');
        if ($source !== 'ozon' && $source !== 'wildberries') {
            continue;
        }
        $kind = $source === 'wildberries' ? 'wb_param' : 'param';
        foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
            if (!is_array($attr)) {
                continue;
            }
            $name = trim((string)($attr['name'] ?? ''));
            $nameKey = supplier_products_db_attr_norm($name);
            if ($name === '' || $nameKey === '') {
                continue;
            }
            $role = supplier_products_db_dimension_attribute_role($name);
            $rawValue = $role !== '' ? (string)($valuesByRole[$role] ?? '') : '';
            if ($rawValue === '') {
                continue;
            }
            foreach (supplier_products_db_values_allowed_for_attr($rawValue, $attr) as $value) {
                if ($value === '') {
                    continue;
                }
                $rows[$source . "\n" . $nameKey] = [
                    'marketplace' => $source,
                    'kind' => $kind,
                    'name' => $name,
                    'value' => (string)$value,
                    'detected_from_dimensions' => true,
                ];
                break;
            }
        }
    }

    return array_values($rows);
}

function supplier_products_db_operation_is_supported(string $opType, array $opMeta): bool
{
    return trim((string)($opMeta['supplier_products_db_handler'] ?? '')) !== '';
}

function supplier_products_db_supported_operations(array $registry): array
{
    $supported = [];
    foreach ($registry as $opType => $opMeta) {
        if (is_array($opMeta) && supplier_products_db_operation_is_supported((string)$opType, $opMeta)) {
            $supported[$opType] = $opMeta;
        }
    }
    return $supported;
}

function supplier_products_db_run_registered_handler(array $cfg, array $ds, int $opId, array $params, callable $log, string $opType, array $opMeta): array
{
    $handler = trim((string)($opMeta['supplier_products_db_handler'] ?? ''));
    if ($handler === '') {
        throw new RuntimeException("Операция {$opType} не подключена к DB-товарам поставщика.");
    }
    if (!function_exists($handler)) {
        throw new RuntimeException("DB-обработчик {$handler} для операции {$opType} не найден.");
    }
    $extraArgs = $opMeta['supplier_products_db_args'] ?? [];
    if (!is_array($extraArgs)) {
        $extraArgs = [];
    }
    return call_user_func_array($handler, array_merge([$cfg, $ds, $opId, $params, $log], $extraArgs));
}

function supplier_products_db_brand_is_empty_like(string $brand): bool
{
    $norm = marketplace_brand_dictionary_norm($brand);
    if ($norm === '') {
        return true;
    }
    return in_array($norm, [
        '-',
        'нет',
        'нет бренда',
        'без бренда',
        'no brand',
        'nobrand',
        'none',
        'unknown',
    ], true);
}

function supplier_products_db_brand_title_tokens(string $title): array
{
    $title = trim(str_replace(["\xC2\xA0", "\xE2\x80\x8B"], ' ', $title));
    if ($title === '') {
        return [];
    }
    if (!preg_match_all('~[\p{L}\p{N}]+~u', $title, $m, PREG_OFFSET_CAPTURE)) {
        return [];
    }
    $tokens = [];
    foreach ((array)($m[0] ?? []) as $match) {
        $text = trim((string)($match[0] ?? ''));
        if ($text === '') {
            continue;
        }
        $norm = marketplace_brand_dictionary_norm($text);
        if ($norm === '') {
            continue;
        }
        $upper = false;
        if (preg_match('~\p{L}~u', $text)) {
            $upperText = mb_strtoupper($text, 'UTF-8');
            $lowerText = mb_strtolower($text, 'UTF-8');
            $upper = ($text === $upperText && $text !== $lowerText);
        }
        $tokens[] = [
            'text' => $text,
            'norm' => $norm,
            'upper' => $upper,
        ];
    }
    return $tokens;
}

function supplier_products_db_brand_ngram_is_noise(string $norm, int $tokenCount): bool
{
    if ($norm === '' || preg_match('~^\d+$~', $norm)) {
        return true;
    }
    $compact = str_replace(' ', '', $norm);
    if ($compact === '' || strlen($compact) < 2) {
        return true;
    }
    if ($tokenCount === 1) {
        static $singleNoise = [
            'pro' => true,
            'max' => true,
            'mini' => true,
            'air' => true,
            'plus' => true,
            'ultra' => true,
            'original' => true,
            'orig' => true,
            'new' => true,
            'home' => true,
            'standard' => true,
            'standart' => true,
            'ios' => true,
            'type' => true,
            'usb' => true,
            'fpv' => true,
            'rc' => true,
            'hd' => true,
            'uhd' => true,
            'li' => true,
            'ion' => true,
            'lipo' => true,
            'для' => true,
            'без' => true,
            'под' => true,
            'уп' => true,
            'шт' => true,
            'аккумулятор' => true,
            'батарея' => true,
            'чехол' => true,
            'кейс' => true,
            'стекло' => true,
            'пленка' => true,
            'кабель' => true,
            'адаптер' => true,
            'комплект' => true,
            'набор' => true,
        ];
        if (isset($singleNoise[$norm])) {
            return true;
        }
    }
    if (preg_match('~^(аккумулятор|батарея|чехол|кейс|стекло|пленка|кабель|адаптер)\s+(для|под)\s+~u', $norm)) {
        return true;
    }
    return false;
}

function supplier_products_db_brand_title_ngrams(array $tokens, int $maxTokens = 6): array
{
    $count = count($tokens);
    $out = [];
    for ($start = 0; $start < $count; $start++) {
        $parts = [];
        for ($len = 1; $len <= $maxTokens && ($start + $len) <= $count; $len++) {
            $parts[] = (string)($tokens[$start + $len - 1]['text'] ?? '');
            $norm = marketplace_brand_dictionary_norm(implode(' ', $parts));
            if (supplier_products_db_brand_ngram_is_noise($norm, $len)) {
                continue;
            }
            if (mb_strlen($norm, 'UTF-8') > 80) {
                break;
            }
            $occurrence = [
                'start' => $start,
                'end' => $start + $len - 1,
                'tokens' => $len,
                'text' => implode(' ', $parts),
            ];
            $out[$norm][] = $occurrence;

            $compactNorm = str_replace(' ', '', $norm);
            if ($compactNorm !== $norm && !supplier_products_db_brand_ngram_is_noise($compactNorm, $len)) {
                $out[$compactNorm][] = $occurrence;
            }
        }
    }
    return $out;
}

function supplier_products_db_parse_supplier_brand_list(string $raw): array
{
    $raw = str_replace(["\r\n", "\r"], "\n", $raw);
    $parts = preg_split('~[\n;,]+~u', $raw) ?: [];
    $out = [];
    $seen = [];
    foreach ($parts as $part) {
        $name = trim((string)$part);
        $name = preg_replace('~^\s*(?:[-*•]|\d+[\).:-]?)\s*~u', '', $name) ?? $name;
        $name = trim($name, " \t\n\r\0\x0B\"'«»");
        if ($name === '' || supplier_products_db_brand_is_empty_like($name)) {
            continue;
        }
        $norm = marketplace_brand_dictionary_norm($name);
        if ($norm === '' || isset($seen[$norm])) {
            continue;
        }
        $seen[$norm] = true;
        $compactNorm = str_replace(' ', '', $norm);
        $out[] = [
            'name' => $name,
            'norm' => $norm,
            'compact_norm' => $compactNorm !== $norm ? $compactNorm : '',
        ];
    }
    return $out;
}

function supplier_products_db_brand_rows_for_norms(array $norms, string $ozonCategory, string $wbCategory): array
{
    marketplace_brand_dictionary_tables_ensure();
    $norms = array_values(array_unique(array_filter(array_map(static function ($value): string {
        return mb_substr((string)$value, 0, 255, 'UTF-8');
    }, $norms), static fn(string $value): bool => $value !== '')));
    if (!$norms) {
        return [];
    }

    $rowsByNorm = [];
    $addRow = static function (array $row, string $source, bool $categoryFit) use (&$rowsByNorm): void {
        $norm = (string)($row['brand_name_norm'] ?? '');
        $name = trim((string)($row['brand_name'] ?? ''));
        if ($norm === '' || $name === '' || supplier_products_db_brand_is_empty_like($name)) {
            return;
        }
        $key = $source . ':' . ($categoryFit ? 'category' : 'global');
        if (isset($rowsByNorm[$norm][$key])) {
            return;
        }
        $rowsByNorm[$norm][$key] = [
            'source' => $source,
            'name' => $name,
            'category_fit' => $categoryFit,
            'brand_id' => (int)($row['brand_id'] ?? 0),
        ];
    };

    $queryChunks = static function (string $sql, array $baseArgs, array $normList, callable $onRow): void {
        foreach (array_chunk($normList, 300) as $chunk) {
            $ph = implode(',', array_fill(0, count($chunk), '?'));
            $st = db()->prepare(str_replace('__NORMS__', $ph, $sql));
            $st->execute(array_merge($baseArgs, $chunk));
            while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
                $onRow($row);
            }
        }
    };

    $ozonIds = marketplace_brand_status_ozon_category_ids($ozonCategory);
    $ozonParentId = (int)($ozonIds['parent_id'] ?? 0);
    $ozonLeafId = (int)($ozonIds['leaf_id'] ?? 0);
    if ($ozonParentId > 0) {
        $typeSql = 'c.type_id = 0';
        $args = [$ozonParentId];
        if ($ozonLeafId > 0) {
            $typeSql = '(c.type_id = 0 OR c.type_id = ?)';
            $args[] = $ozonLeafId;
        }
        $queryChunks("
            SELECT DISTINCT b.brand_id, b.brand_name, b.brand_name_norm
            FROM feedtools_ozon_brands b
            JOIN feedtools_ozon_brand_categories c ON c.brand_id = b.brand_id
            WHERE c.description_category_id = ?
              AND {$typeSql}
              AND b.brand_name_norm IN (__NORMS__)
            ORDER BY b.brand_id ASC
        ", $args, $norms, static function (array $row) use ($addRow): void {
            $addRow($row, 'ozon', true);
        });
    }

    $wbSubjectId = marketplace_brand_status_wb_subject_id($wbCategory);
    if ($wbSubjectId > 0) {
        $wbParents = marketplace_brand_status_wb_parent_ids([$wbSubjectId]);
        $wbParentId = (int)($wbParents[$wbSubjectId] ?? 0);
        $where = 'c.subject_id = ?';
        $args = [$wbSubjectId];
        if ($wbParentId > 0) {
            $where = '(c.subject_id = ? OR (c.subject_id = 0 AND c.parent_id = ?))';
            $args[] = $wbParentId;
        }
        $queryChunks("
            SELECT DISTINCT b.brand_id, b.brand_name, b.brand_name_norm
            FROM feedtools_wb_brands b
            JOIN feedtools_wb_brand_categories c ON c.brand_id = b.brand_id
            WHERE {$where}
              AND b.brand_name_norm IN (__NORMS__)
            ORDER BY b.brand_id ASC
        ", $args, $norms, static function (array $row) use ($addRow): void {
            $addRow($row, 'wb', true);
        });
    }

    foreach (['ozon' => 'feedtools_ozon_brands', 'wb' => 'feedtools_wb_brands'] as $source => $table) {
        $queryChunks("
            SELECT brand_id, brand_name, brand_name_norm
            FROM {$table}
            WHERE brand_name_norm IN (__NORMS__)
            ORDER BY brand_id ASC
        ", [], $norms, static function (array $row) use ($addRow, $source): void {
            $addRow($row, (string)$source, false);
        });
    }

    return array_map(static fn(array $rows): array => array_values($rows), $rowsByNorm);
}

function supplier_products_db_brand_context_score(array $tokens, array $occurrence): array
{
    $start = (int)($occurrence['start'] ?? 0);
    $end = (int)($occurrence['end'] ?? $start);
    $total = count($tokens);
    $score = 0;
    $negative = false;
    $reasons = [];

    $normAt = static function (int $idx) use ($tokens): string {
        return $idx >= 0 && isset($tokens[$idx]) ? (string)($tokens[$idx]['norm'] ?? '') : '';
    };

    $prev = $normAt($start - 1);
    if (in_array($prev, ['бренд', 'марка', 'производитель', 'vendor', 'brand', 'by', 'от'], true)) {
        $score += 28;
        $reasons[] = 'positive_marker';
    }

    $compatWords = [
        'для' => true,
        'под' => true,
        'к' => true,
        'ко' => true,
        'на' => true,
        'совместим' => true,
        'совместима' => true,
        'совместимо' => true,
        'совместимые' => true,
        'совместимость' => true,
        'подходит' => true,
        'подходят' => true,
        'замена' => true,
        'аналог' => true,
        'replacement' => true,
        'compatible' => true,
        'compatibility' => true,
        'for' => true,
        'with' => true,
    ];
    for ($i = max(0, $start - 4); $i < $start; $i++) {
        $norm = $normAt($i);
        if (isset($compatWords[$norm])) {
            $negative = true;
            $score -= 105;
            $reasons[] = 'compat_context';
            break;
        }
    }

    $next = $normAt($end + 1);
    $productFamilyWords = [
        'iphone' => true,
        'ipad' => true,
        'macbook' => true,
        'imac' => true,
        'watch' => true,
        'airpods' => true,
        'galaxy' => true,
        'mavic' => true,
        'phantom' => true,
        'mini' => true,
        'avata' => true,
        'osmo' => true,
        'hero' => true,
        'eos' => true,
        'alpha' => true,
    ];
    $accessoryWords = [
        'аккумулятор' => true,
        'аккумулятора' => true,
        'батарея' => true,
        'батареи' => true,
        'чехол' => true,
        'кейс' => true,
        'стекло' => true,
        'пленка' => true,
        'кабель' => true,
        'шлейф' => true,
        'адаптер' => true,
        'зарядка' => true,
        'зарядное' => true,
        'объектив' => true,
        'линза' => true,
        'модуль' => true,
        'камера' => true,
        'крепление' => true,
        'ремешок' => true,
        'пропеллер' => true,
        'винт' => true,
        'запчасть' => true,
        'запчасти' => true,
    ];
    if ($start > 0 && isset($productFamilyWords[$next])) {
        for ($i = max(0, $start - 7); $i < $start; $i++) {
            $norm = $normAt($i);
            if (isset($accessoryWords[$norm])) {
                $negative = true;
                $score -= 85;
                $reasons[] = 'accessory_compat_family';
                break;
            }
        }
    }

    if ($start <= 1) {
        $score += 18;
        $reasons[] = 'title_start';
    }
    if ($end >= max(0, $total - 3)) {
        $score += 22;
        $reasons[] = 'title_end';
    }

    $allUpper = true;
    for ($i = $start; $i <= $end; $i++) {
        if (empty($tokens[$i]['upper'])) {
            $allUpper = false;
            break;
        }
    }
    if ($allUpper && ($end - $start + 1) <= 3) {
        $score += 10;
        $reasons[] = 'uppercase';
    }

    return [
        'score' => $score,
        'negative' => $negative,
        'reasons' => $reasons,
    ];
}

function supplier_products_db_pick_brand_name(array $brandRows): string
{
    foreach ([['ozon', true], ['wb', true], ['ozon', false], ['wb', false]] as $want) {
        foreach ($brandRows as $row) {
            if ((string)($row['source'] ?? '') === $want[0] && (bool)($row['category_fit'] ?? false) === $want[1]) {
                return trim((string)($row['name'] ?? ''));
            }
        }
    }
    $first = reset($brandRows);
    return is_array($first) ? trim((string)($first['name'] ?? '')) : '';
}

function supplier_products_db_detect_brand_from_supplier_list(array $product, float $minScore, array $supplierBrands): array
{
    $title = trim((string)($product['name'] ?? ''));
    if ($title === '') {
        return ['status' => 'no_title'];
    }
    $tokens = supplier_products_db_brand_title_tokens($title);
    $ngrams = supplier_products_db_brand_title_ngrams($tokens, 8);
    if (!$tokens || !$ngrams || !$supplierBrands) {
        return ['status' => 'no_candidates'];
    }

    $candidates = [];
    foreach ($supplierBrands as $brand) {
        $brandName = trim((string)($brand['name'] ?? ''));
        if ($brandName === '' || supplier_products_db_brand_is_empty_like($brandName)) {
            continue;
        }
        $aliases = array_values(array_unique(array_filter([
            (string)($brand['norm'] ?? ''),
            (string)($brand['compact_norm'] ?? ''),
        ], static fn(string $value): bool => $value !== '')));
        foreach ($aliases as $alias) {
            foreach ((array)($ngrams[$alias] ?? []) as $occurrence) {
                $context = supplier_products_db_brand_context_score($tokens, $occurrence);
                $score = 88
                    + min(28, (int)mb_strlen(str_replace(' ', '', $alias), 'UTF-8') * 2)
                    + (int)($context['score'] ?? 0);
                $candidates[] = [
                    'brand' => $brandName,
                    'norm' => (string)($brand['norm'] ?? $alias),
                    'score' => $score,
                    'category_fit' => false,
                    'sources' => ['supplier_list'],
                    'negative_context' => !empty($context['negative']),
                    'context_reasons' => (array)($context['reasons'] ?? []),
                    'matched_text' => (string)($occurrence['text'] ?? ''),
                    'start' => (int)($occurrence['start'] ?? 0),
                ];
            }
        }
    }
    if (!$candidates) {
        return ['status' => 'not_found_in_supplier_list'];
    }

    usort($candidates, static function (array $a, array $b): int {
        $cmp = ((int)($b['score'] ?? 0) <=> (int)($a['score'] ?? 0));
        if ($cmp !== 0) {
            return $cmp;
        }
        $cmp = (mb_strlen((string)($b['norm'] ?? ''), 'UTF-8') <=> mb_strlen((string)($a['norm'] ?? ''), 'UTF-8'));
        if ($cmp !== 0) {
            return $cmp;
        }
        return ((int)($b['start'] ?? 0) <=> (int)($a['start'] ?? 0));
    });

    $best = $candidates[0];
    $second = $candidates[1] ?? null;
    if (!empty($best['negative_context']) && (int)($best['score'] ?? 0) < ($minScore + 20)) {
        return ['status' => 'compat_context', 'candidate' => $best, 'candidates' => array_slice($candidates, 0, 6)];
    }
    if ((float)($best['score'] ?? 0) < $minScore) {
        return ['status' => 'low_score', 'candidate' => $best, 'candidates' => array_slice($candidates, 0, 6)];
    }
    if (is_array($second) && (string)($second['norm'] ?? '') !== (string)($best['norm'] ?? '') && ((int)$best['score'] - (int)$second['score']) < 10) {
        return ['status' => 'ambiguous', 'candidate' => $best, 'second' => $second, 'candidates' => array_slice($candidates, 0, 6)];
    }

    return ['status' => 'ok', 'candidate' => $best, 'candidates' => array_slice($candidates, 0, 6)];
}

function supplier_products_db_detect_brand_from_title(array $product, array $fields, float $minScore, array $supplierBrands = []): array
{
    if ($supplierBrands) {
        return supplier_products_db_detect_brand_from_supplier_list($product, $minScore, $supplierBrands);
    }

    $title = trim((string)($product['name'] ?? ''));
    if ($title === '') {
        return ['status' => 'no_title'];
    }
    $tokens = supplier_products_db_brand_title_tokens($title);
    $ngrams = supplier_products_db_brand_title_ngrams($tokens);
    if (!$ngrams) {
        return ['status' => 'no_candidates'];
    }

    $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
    $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
    $brandRowsByNorm = supplier_products_db_brand_rows_for_norms(array_keys($ngrams), $ozonCategory, $wbCategory);
    if (!$brandRowsByNorm) {
        return ['status' => 'not_found_in_dictionary'];
    }

    $candidates = [];
    foreach ($brandRowsByNorm as $norm => $brandRows) {
        $brandName = supplier_products_db_pick_brand_name($brandRows);
        if ($brandName === '') {
            continue;
        }
        $categoryFit = false;
        $sources = [];
        foreach ($brandRows as $row) {
            $source = (string)($row['source'] ?? '');
            if ($source !== '') {
                $sources[$source] = true;
            }
            if (!empty($row['category_fit'])) {
                $categoryFit = true;
            }
        }
        foreach ((array)($ngrams[$norm] ?? []) as $occurrence) {
            $context = supplier_products_db_brand_context_score($tokens, $occurrence);
            $score = ($categoryFit ? 84 : 46)
                + min(24, (int)mb_strlen(str_replace(' ', '', (string)$norm), 'UTF-8') * 2)
                + (count($sources) > 1 ? 8 : 0)
                + (int)($context['score'] ?? 0);
            $candidates[] = [
                'brand' => $brandName,
                'norm' => (string)$norm,
                'score' => $score,
                'category_fit' => $categoryFit,
                'sources' => array_keys($sources),
                'negative_context' => !empty($context['negative']),
                'context_reasons' => (array)($context['reasons'] ?? []),
                'matched_text' => (string)($occurrence['text'] ?? ''),
                'start' => (int)($occurrence['start'] ?? 0),
            ];
        }
    }
    if (!$candidates) {
        return ['status' => 'not_found_in_dictionary'];
    }

    usort($candidates, static function (array $a, array $b): int {
        $cmp = ((int)($b['score'] ?? 0) <=> (int)($a['score'] ?? 0));
        if ($cmp !== 0) {
            return $cmp;
        }
        $cmp = ((int)!empty($b['category_fit']) <=> (int)!empty($a['category_fit']));
        if ($cmp !== 0) {
            return $cmp;
        }
        $cmp = (mb_strlen((string)($b['norm'] ?? ''), 'UTF-8') <=> mb_strlen((string)($a['norm'] ?? ''), 'UTF-8'));
        if ($cmp !== 0) {
            return $cmp;
        }
        return ((int)($b['start'] ?? 0) <=> (int)($a['start'] ?? 0));
    });

    $best = $candidates[0];
    $second = $candidates[1] ?? null;
    if (!empty($best['negative_context']) && (int)($best['score'] ?? 0) < ($minScore + 20)) {
        return ['status' => 'compat_context', 'candidate' => $best, 'candidates' => array_slice($candidates, 0, 6)];
    }
    if ((float)($best['score'] ?? 0) < $minScore) {
        return ['status' => 'low_score', 'candidate' => $best, 'candidates' => array_slice($candidates, 0, 6)];
    }
    if (is_array($second) && (string)($second['norm'] ?? '') !== (string)($best['norm'] ?? '') && ((int)$best['score'] - (int)$second['score']) < 10) {
        return ['status' => 'ambiguous', 'candidate' => $best, 'second' => $second, 'candidates' => array_slice($candidates, 0, 6)];
    }

    return ['status' => 'ok', 'candidate' => $best, 'candidates' => array_slice($candidates, 0, 6)];
}

function supplier_products_db_op_detect_brand_from_title(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '0') !== '' && (string)($params['overwrite'] ?? '0') !== '0');
    $minScore = (float)str_replace(',', '.', trim((string)($params['min_score'] ?? '70')));
    if ($minScore < 20 || $minScore > 200) {
        $minScore = 70.0;
    }
    $supplierBrands = supplier_products_db_parse_supplier_brand_list((string)($params['brand_list'] ?? ''));

    $products = supplier_products_db_load_products($supplierId, $params, $maxItems);
    $productIds = supplier_products_db_product_ids($products);
    $fieldsByProduct = supplier_products_db_fields_for_products($productIds);
    $total = count($products);
    $log("supplier_db detect_brand_from_title: products={$total}, overwrite=" . ($overwrite ? '1' : '0') . ", min_score={$minScore}, supplier_brands=" . count($supplierBrands) . "\n");
    ops_update_progress($opId, 0, max(1, $total), 'brand', 'detecting brands');

    $pdo = db();
    $changedProducts = [];
    $examples = [];
    $statusCounts = [];
    $seen = 0;
    $skippedFilled = 0;
    $updated = 0;

    foreach ($products as $product) {
        $seen++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0) {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $currentBrand = trim(supplier_products_standard_field_value($pdo, $productId, 'brand'));
        if ($currentBrand === '') {
            $currentBrand = trim((string)($product['brand'] ?? ''));
        }
        $currentBrandOzon = trim(supplier_products_standard_field_value($pdo, $productId, 'brand_ozon'));
        $currentBrandWb = trim(supplier_products_standard_field_value($pdo, $productId, 'brand_wb'));
        $needsBrand = $overwrite || supplier_products_db_brand_is_empty_like($currentBrand);
        $needsBrandOzon = $overwrite || supplier_products_db_brand_is_empty_like($currentBrandOzon);
        $needsBrandWb = $overwrite || supplier_products_db_brand_is_empty_like($currentBrandWb);
        if (!$needsBrand && !$needsBrandOzon && !$needsBrandWb) {
            $skippedFilled++;
            $statusCounts['skipped_filled'] = ($statusCounts['skipped_filled'] ?? 0) + 1;
            continue;
        }

        $candidate = [];
        $brand = '';
        $status = 'existing_brand';
        if (!$needsBrand && !supplier_products_db_brand_is_empty_like($currentBrand)) {
            $brand = $currentBrand;
            $candidate = [
                'brand' => $brand,
                'score' => null,
                'matched_text' => '',
                'sources' => [],
                'category_fit' => false,
            ];
        } else {
            $detected = supplier_products_db_detect_brand_from_title($product, $fields, $minScore, $supplierBrands);
            $status = (string)($detected['status'] ?? 'unknown');
            if ($status !== 'ok') {
                $statusCounts[$status] = ($statusCounts[$status] ?? 0) + 1;
                if (count($examples) < 30 && isset($detected['candidate'])) {
                    $examples[] = [
                        'offer_id' => $offerId,
                        'status' => $status,
                        'name' => (string)($product['name'] ?? ''),
                        'candidate' => $detected['candidate'],
                    ];
                }
                continue;
            }
            $candidate = (array)($detected['candidate'] ?? []);
            $brand = trim((string)($candidate['brand'] ?? ''));
            if ($brand === '' || supplier_products_db_brand_is_empty_like($brand)) {
                continue;
            }
        }

        $fieldUpdates = [];
        foreach (['brand' => $needsBrand, 'brand_ozon' => $needsBrandOzon, 'brand_wb' => $needsBrandWb] as $fieldName => $shouldSet) {
            if ($shouldSet && supplier_products_set_standard_field_value($pdo, $supplierId, $productId, (string)$fieldName, $brand)) {
                $fieldUpdates[] = (string)$fieldName;
            }
        }
        if ($fieldUpdates) {
            $updated++;
            $changedProducts[$productId] = true;
            $statusCounts[$status] = ($statusCounts[$status] ?? 0) + 1;
            if (count($examples) < 30) {
                $example = [
                    'offer_id' => $offerId,
                    'status' => 'updated',
                    'brand' => $brand,
                    'fields' => $fieldUpdates,
                    'matched_text' => (string)($candidate['matched_text'] ?? ''),
                    'sources' => (array)($candidate['sources'] ?? []),
                    'category_fit' => !empty($candidate['category_fit']),
                    'name' => (string)($product['name'] ?? ''),
                ];
                if (array_key_exists('score', $candidate) && $candidate['score'] !== null) {
                    $example['score'] = (int)$candidate['score'];
                }
                $examples[] = $example;
            }
        } else {
            $statusCounts['unchanged'] = ($statusCounts['unchanged'] ?? 0) + 1;
        }

        if ($seen % 100 === 0) {
            ops_update_progress($opId, $seen, max(1, $total), 'brand', "detecting brands {$seen}/{$total}");
        }
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId);
    $report = [
        'title' => 'detect_brand_from_title',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_seen' => $seen,
            'updated' => $updated,
            'skipped_filled' => $skippedFilled,
            'products_changed' => count($changedProducts),
            'status_counts' => $statusCounts,
            'min_score' => $minScore,
            'overwrite' => $overwrite ? 1 : 0,
            'supplier_brand_list_count' => count($supplierBrands),
        ],
        'examples' => $examples,
        'dataset' => $dataset,
    ];
    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'detect_brand_from_title',
        'items' => [
            'Products seen: ' . $seen,
            'Brands updated: ' . $updated,
            'Skipped filled: ' . $skippedFilled,
            'Supplier brands in prompt: ' . count($supplierBrands),
            'Products changed: ' . count($changedProducts),
        ],
        'metrics' => $report['summary'],
    ];
    $log("done: seen={$seen}, updated={$updated}, skipped_filled={$skippedFilled}, changed=" . count($changedProducts) . "\n");
    return $outputs;
}

function supplier_products_db_brand_audit_marketplaces(string $raw): array
{
    $raw = mb_strtolower(trim($raw), 'UTF-8');
    if ($raw === '' || $raw === 'all' || $raw === 'both') {
        return ['ozon', 'wb'];
    }
    $out = [];
    foreach (preg_split('~[\s,;]+~u', $raw) ?: [] as $part) {
        $part = trim((string)$part);
        if ($part === 'wildberries' || $part === 'вб') {
            $part = 'wb';
        }
        if (in_array($part, ['ozon', 'wb'], true) && !in_array($part, $out, true)) {
            $out[] = $part;
        }
    }
    return $out ?: ['ozon', 'wb'];
}

function supplier_products_db_brand_audit_effective_brand(array $product, array $fields, string $marketplace): array
{
    $base = trim(supplier_products_db_standard_field_value_from_rows($fields, 'brand'));
    if ($base === '') {
        $base = trim((string)($product['brand'] ?? ''));
    }
    $fieldName = $marketplace === 'wb' ? 'brand_wb' : 'brand_ozon';
    $marketplaceBrand = trim(supplier_products_db_standard_field_value_from_rows($fields, $fieldName));
    if ($marketplaceBrand === '') {
        $marketplaceBrand = $base;
    }
    return [
        'brand' => $marketplaceBrand,
        'base_brand' => $base,
        'source_field' => $marketplaceBrand !== '' && $marketplaceBrand !== $base ? $fieldName : 'brand',
    ];
}

function supplier_products_db_brand_audit_category_context(string $marketplace, string $categoryValue): array
{
    if ($marketplace === 'wb') {
        $subjectId = marketplace_brand_status_wb_subject_id($categoryValue);
        $parents = $subjectId > 0 ? marketplace_brand_status_wb_parent_ids([$subjectId]) : [];
        $parentId = (int)($parents[$subjectId] ?? 0);
        return [
            'subject_id' => $subjectId,
            'parent_id' => $parentId,
            'valid' => $subjectId > 0,
        ];
    }

    $ids = marketplace_brand_status_ozon_category_ids($categoryValue);
    return [
        'parent_id' => (int)($ids['parent_id'] ?? 0),
        'leaf_id' => (int)($ids['leaf_id'] ?? 0),
        'valid' => (int)($ids['parent_id'] ?? 0) > 0,
    ];
}

function supplier_products_db_brand_audit_category_label(string $marketplace, string $categoryValue, array $ctx): string
{
    if ($marketplace === 'wb') {
        $subjectId = (int)($ctx['subject_id'] ?? 0);
        return $subjectId > 0 ? supplier_brand_ops_wb_category_name($subjectId) : $categoryValue;
    }
    $label = supplier_brand_ops_ozon_category_name($categoryValue);
    if ($label !== $categoryValue || !empty($ctx['leaf_id'])) {
        return $label;
    }
    $parentId = (int)($ctx['parent_id'] ?? 0);
    return $parentId > 0 ? supplier_brand_ops_ozon_parent_category_name($parentId) : $categoryValue;
}

function supplier_products_db_brand_audit_scope_fetch(string $marketplace, string $categoryValue, array $ctx): array
{
    if (empty($ctx['valid'])) {
        return [
            'status' => 'category_missing',
            'scope_key' => '',
            'values_count' => 0,
            'fetched_at' => '',
            'error_text' => '',
        ];
    }

    if ($marketplace === 'wb') {
        $scopeKey = supplier_brand_ops_wb_scope_key((int)($ctx['subject_id'] ?? 0));
    } else {
        $scopeKey = supplier_brand_ops_ozon_parent_scope_key((int)($ctx['parent_id'] ?? 0), 85);
    }
    $row = marketplace_brand_scope_fetch_row($marketplace, $scopeKey);
    if (!is_array($row)) {
        return [
            'status' => 'missing',
            'scope_key' => $scopeKey,
            'values_count' => 0,
            'fetched_at' => '',
            'error_text' => '',
        ];
    }
    return [
        'status' => trim((string)($row['status'] ?? '')) ?: 'unknown',
        'scope_key' => $scopeKey,
        'values_count' => (int)($row['values_count'] ?? 0),
        'fetched_at' => trim((string)($row['fetched_at'] ?? '')),
        'error_text' => trim((string)($row['error_text'] ?? '')),
    ];
}

function supplier_products_db_brand_audit_exact_name_differs(string $current, string $canonical): bool
{
    $current = trim($current);
    $canonical = trim($canonical);
    if ($current === '' || $canonical === '') {
        return false;
    }
    if ($current === $canonical) {
        return false;
    }
    return marketplace_brand_status_norm($current) === marketplace_brand_status_norm($canonical);
}

function supplier_products_db_brand_audit_escape_like(string $value): string
{
    return str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $value);
}

function supplier_products_db_brand_audit_mb_chars(string $value): array
{
    if ($value === '') {
        return [];
    }
    preg_match_all('/./us', $value, $m);
    return (array)($m[0] ?? []);
}

function supplier_products_db_brand_audit_distance(string $a, string $b): int
{
    if ($a === $b) {
        return 0;
    }
    $aa = supplier_products_db_brand_audit_mb_chars($a);
    $bb = supplier_products_db_brand_audit_mb_chars($b);
    $n = count($aa);
    $m = count($bb);
    if ($n === 0) {
        return $m;
    }
    if ($m === 0) {
        return $n;
    }
    $prev = range(0, $m);
    for ($i = 1; $i <= $n; $i++) {
        $curr = [$i];
        for ($j = 1; $j <= $m; $j++) {
            $cost = $aa[$i - 1] === $bb[$j - 1] ? 0 : 1;
            $curr[$j] = min(
                $prev[$j] + 1,
                $curr[$j - 1] + 1,
                $prev[$j - 1] + $cost
            );
        }
        $prev = $curr;
    }
    return (int)$prev[$m];
}

function supplier_products_db_brand_audit_similarity(string $a, string $b): int
{
    $a = marketplace_brand_status_norm($a);
    $b = marketplace_brand_status_norm($b);
    if ($a === '' || $b === '') {
        return 0;
    }
    if ($a === $b) {
        return 100;
    }
    $ac = str_replace(' ', '', $a);
    $bc = str_replace(' ', '', $b);
    if ($ac !== '' && $ac === $bc) {
        return 96;
    }
    if (str_contains($a, $b) || str_contains($b, $a)) {
        if (!supplier_products_db_brand_audit_containment_is_safe($a, $b)) {
            return 72;
        }
        $min = min(mb_strlen($a, 'UTF-8'), mb_strlen($b, 'UTF-8'));
        $max = max(mb_strlen($a, 'UTF-8'), mb_strlen($b, 'UTF-8'));
        return $max > 0 ? max(88, (int)round(($min / $max) * 100)) : 0;
    }
    $dist = supplier_products_db_brand_audit_distance($a, $b);
    $maxLen = max(mb_strlen($a, 'UTF-8'), mb_strlen($b, 'UTF-8'));
    $levScore = $maxLen > 0 ? (int)round((1 - ($dist / $maxLen)) * 100) : 0;

    $tokensA = array_values(array_unique(array_filter(explode(' ', $a))));
    $tokensB = array_values(array_unique(array_filter(explode(' ', $b))));
    $tokenScore = 0;
    if ($tokensA && $tokensB) {
        $intersect = count(array_intersect($tokensA, $tokensB));
        $union = count(array_unique(array_merge($tokensA, $tokensB)));
        $tokenScore = $union > 0 ? (int)round(($intersect / $union) * 100) : 0;
    }
    return max(0, min(100, max($levScore, min(78, $tokenScore))));
}

function supplier_products_db_brand_audit_containment_is_safe(string $a, string $b): bool
{
    $a = marketplace_brand_status_norm($a);
    $b = marketplace_brand_status_norm($b);
    if ($a === '' || $b === '') {
        return false;
    }
    $long = mb_strlen($a, 'UTF-8') >= mb_strlen($b, 'UTF-8') ? $a : $b;
    $short = $long === $a ? $b : $a;
    if ($short === '' || !str_contains($long, $short)) {
        return false;
    }
    $longTokens = array_values(array_filter(explode(' ', $long)));
    $shortTokens = array_values(array_filter(explode(' ', $short)));
    if (!$longTokens || !$shortTokens) {
        return false;
    }
    $remaining = $longTokens;
    foreach ($shortTokens as $shortToken) {
        $idx = array_search($shortToken, $remaining, true);
        if ($idx !== false) {
            unset($remaining[$idx]);
        }
    }
    $remaining = array_values($remaining);
    if (!$remaining) {
        return true;
    }

    static $qualifiers = [
        'запчасти' => true,
        'запчасть' => true,
        'аксессуары' => true,
        'аксессуар' => true,
        'комплектующие' => true,
        'комплектующая' => true,
        'деталь' => true,
        'детали' => true,
        'товар' => true,
        'товары' => true,
        'поставщик' => true,
        'original' => true,
        'оригинал' => true,
        'оригинальные' => true,
        'совместимый' => true,
        'совместимые' => true,
    ];
    foreach ($remaining as $token) {
        if (!isset($qualifiers[$token])) {
            return false;
        }
    }
    return true;
}

function supplier_products_db_brand_audit_like_patterns(string $norm): array
{
    $norm = marketplace_brand_status_norm($norm);
    if ($norm === '') {
        return [];
    }
    $patterns = [];
    $patterns[] = supplier_products_db_brand_audit_escape_like($norm) . '%';
    $patterns[] = '%' . supplier_products_db_brand_audit_escape_like($norm) . '%';
    $compact = str_replace(' ', '', $norm);
    if ($compact !== '' && $compact !== $norm) {
        $patterns[] = '%' . supplier_products_db_brand_audit_escape_like($compact) . '%';
    }
    foreach (explode(' ', $norm) as $token) {
        $token = trim($token);
        if (mb_strlen($token, 'UTF-8') >= 3) {
            $patterns[] = '%' . supplier_products_db_brand_audit_escape_like($token) . '%';
        }
    }
    if (mb_strlen($norm, 'UTF-8') >= 4) {
        $patterns[] = supplier_products_db_brand_audit_escape_like(mb_substr($norm, 0, 4, 'UTF-8')) . '%';
    }
    return array_values(array_unique($patterns));
}

function supplier_products_db_brand_audit_candidate_rows(string $marketplace, string $norm, string $categoryValue, int $limit, bool $categoryOnly): array
{
    $patterns = supplier_products_db_brand_audit_like_patterns($norm);
    if (!$patterns) {
        return [];
    }
    $limit = max(20, min(300, $limit));
    $likeSql = implode(' OR ', array_fill(0, count($patterns), "b.brand_name_norm LIKE ? ESCAPE '\\\\'"));
    $args = $patterns;

    if ($marketplace === 'wb') {
        $table = 'feedtools_wb_brands';
        $categoryTable = 'feedtools_wb_brand_categories';
        $ctx = supplier_products_db_brand_audit_category_context('wb', $categoryValue);
        if ($categoryOnly) {
            $subjectId = (int)($ctx['subject_id'] ?? 0);
            $parentId = (int)($ctx['parent_id'] ?? 0);
            if ($subjectId <= 0) {
                return [];
            }
            $where = 'c.subject_id = ?';
            $catArgs = [$subjectId];
            if ($parentId > 0) {
                $where = '(c.subject_id = ? OR (c.subject_id = 0 AND c.parent_id = ?))';
                $catArgs[] = $parentId;
            }
            $sql = "
                SELECT DISTINCT b.brand_id, b.brand_name, b.brand_name_norm
                FROM {$table} b
                JOIN {$categoryTable} c ON c.brand_id = b.brand_id
                WHERE {$where}
                  AND ({$likeSql})
                LIMIT {$limit}
            ";
            $args = array_merge($catArgs, $patterns);
        } else {
            $sql = "
                SELECT b.brand_id, b.brand_name, b.brand_name_norm
                FROM {$table} b
                WHERE {$likeSql}
                LIMIT {$limit}
            ";
        }
    } else {
        $table = 'feedtools_ozon_brands';
        $categoryTable = 'feedtools_ozon_brand_categories';
        $ctx = supplier_products_db_brand_audit_category_context('ozon', $categoryValue);
        if ($categoryOnly) {
            $parentId = (int)($ctx['parent_id'] ?? 0);
            $leafId = (int)($ctx['leaf_id'] ?? 0);
            if ($parentId <= 0) {
                return [];
            }
            $typeSql = 'c.type_id = 0';
            $catArgs = [$parentId];
            if ($leafId > 0) {
                $typeSql = '(c.type_id = 0 OR c.type_id = ?)';
                $catArgs[] = $leafId;
            }
            $sql = "
                SELECT DISTINCT b.brand_id, b.brand_name, b.brand_name_norm
                FROM {$table} b
                JOIN {$categoryTable} c ON c.brand_id = b.brand_id
                WHERE c.description_category_id = ?
                  AND {$typeSql}
                  AND ({$likeSql})
                LIMIT {$limit}
            ";
            $args = array_merge($catArgs, $patterns);
        } else {
            $sql = "
                SELECT b.brand_id, b.brand_name, b.brand_name_norm
                FROM {$table} b
                WHERE {$likeSql}
                LIMIT {$limit}
            ";
        }
    }

    $st = db()->prepare($sql);
    $st->execute($args);
    $rows = [];
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
        $brandName = trim((string)($row['brand_name'] ?? ''));
        $brandNorm = trim((string)($row['brand_name_norm'] ?? ''));
        if ($brandName === '' || $brandNorm === '') {
            continue;
        }
        $rows[$brandNorm] = [
            'brand_id' => (int)($row['brand_id'] ?? 0),
            'brand_name' => $brandName,
            'brand_name_norm' => $brandNorm,
        ];
    }
    return array_values($rows);
}

function supplier_products_db_brand_audit_best_suggestion(string $marketplace, string $brand, string $categoryValue, int $minSimilarity): array
{
    $norm = marketplace_brand_status_norm($brand);
    if ($norm === '') {
        return [];
    }
    $best = [];
    $rows = supplier_products_db_brand_audit_candidate_rows($marketplace, $norm, $categoryValue, 260, true);
    foreach ($rows as $row) {
        $candidateNorm = (string)($row['brand_name_norm'] ?? '');
        if ($candidateNorm === '' || $candidateNorm === $norm) {
            continue;
        }
        $score = supplier_products_db_brand_audit_similarity($norm, $candidateNorm);
        if ($score < $minSimilarity) {
            continue;
        }
        if (!$best || $score > (int)($best['similarity'] ?? 0)) {
            $best = [
                'brand_id' => (int)($row['brand_id'] ?? 0),
                'brand_name' => (string)($row['brand_name'] ?? ''),
                'brand_name_norm' => $candidateNorm,
                'similarity' => $score,
                'category_fit' => true,
            ];
        }
    }
    return $best;
}

function supplier_products_db_brand_audit_marketplace_title(string $marketplace): string
{
    return $marketplace === 'wb' ? 'Wildberries' : 'Ozon';
}

function supplier_products_db_brand_audit_status_title(string $status): string
{
    return [
        'ok' => 'В порядке',
        'missing_brand' => 'Нет бренда в товаре',
        'category_not_selected' => 'Категория не выбрана',
        'dictionary_missing' => 'Нет справочника категории',
        'fix_spelling' => 'Исправить написание',
        'add_category' => 'Добавить категорию к бренду',
        'fix_spelling_add_category' => 'Исправить написание и категорию',
        'create_brand' => 'Создать бренд',
    ][$status] ?? $status;
}

function supplier_products_db_brand_audit_resolve_group(array $group, array $existing, array $ozonFit, array $wbFit, array $wbParentBySubject, int $minSimilarity): array
{
    $marketplace = (string)($group['marketplace'] ?? 'ozon');
    $brand = trim((string)($group['brand'] ?? ''));
    $norm = (string)($group['brand_norm'] ?? '');
    $categoryValue = (string)($group['category_value'] ?? '');
    $ctx = (array)($group['category_context'] ?? []);
    $scope = (array)($group['scope_fetch'] ?? []);
    $scopeOk = (string)($scope['status'] ?? '') === 'ok';
    $scopeMissing = !$scopeOk;

    if ($brand === '' || supplier_products_db_brand_is_empty_like($brand) || $norm === '') {
        return [
            'status' => 'missing_brand',
            'canonical_brand' => '',
            'suggestion' => null,
            'action' => 'Заполнить бренд у товаров этой группы.',
        ];
    }
    if (empty($ctx['valid'])) {
        return [
            'status' => 'category_not_selected',
            'canonical_brand' => '',
            'suggestion' => null,
            'action' => 'Сначала назначить категорию ' . supplier_products_db_brand_audit_marketplace_title($marketplace) . '.',
        ];
    }

    $exact = $existing[$marketplace][$norm] ?? null;
    $canonical = is_array($exact) ? trim((string)($exact['brand_name'] ?? '')) : '';
    $fitsCategory = false;
    if (is_array($exact)) {
        if ($marketplace === 'wb') {
            $subjectId = (int)($ctx['subject_id'] ?? 0);
            $parentId = (int)($wbParentBySubject[$subjectId] ?? ($ctx['parent_id'] ?? 0));
            $fitsCategory = $subjectId > 0 && (
                isset($wbFit[$norm]['subject'][$subjectId])
                || ($parentId > 0 && isset($wbFit[$norm]['parent'][$parentId]))
            );
        } else {
            $parentId = (int)($ctx['parent_id'] ?? 0);
            $leafId = (int)($ctx['leaf_id'] ?? 0);
            $fitsCategory = $parentId > 0 && (
                isset($ozonFit[$norm][$parentId][0])
                || ($leafId > 0 && isset($ozonFit[$norm][$parentId][$leafId]))
            );
        }
    }

    if (is_array($exact)) {
        $spellingDiffers = supplier_products_db_brand_audit_exact_name_differs($brand, $canonical);
        if ($fitsCategory) {
            if ($spellingDiffers) {
                return [
                    'status' => 'fix_spelling',
                    'canonical_brand' => $canonical,
                    'suggestion' => null,
                    'action' => 'Исправить написание бренда "' . $brand . '" на "' . $canonical . '".',
                ];
            }
            return [
                'status' => 'ok',
                'canonical_brand' => $canonical,
                'suggestion' => null,
                'action' => 'Ничего делать не нужно.',
            ];
        }
        if ($scopeMissing) {
            return [
                'status' => 'dictionary_missing',
                'canonical_brand' => $canonical,
                'suggestion' => null,
                'action' => 'Обновить справочник брендов категории, затем проверить привязку бренда.',
            ];
        }
        if ($spellingDiffers) {
            return [
                'status' => 'fix_spelling_add_category',
                'canonical_brand' => $canonical,
                'suggestion' => null,
                'action' => 'Исправить написание бренда "' . $brand . '" на "' . $canonical . '" и добавить его к категории.',
            ];
        }
        return [
            'status' => 'add_category',
            'canonical_brand' => $canonical,
            'suggestion' => null,
            'action' => 'Добавить бренд "' . $canonical . '" к категории.',
        ];
    }

    if ($scopeMissing) {
        return [
            'status' => 'dictionary_missing',
            'canonical_brand' => '',
            'suggestion' => null,
            'action' => 'Обновить справочник брендов категории, затем повторить проверку.',
        ];
    }

    $suggestion = supplier_products_db_brand_audit_best_suggestion($marketplace, $brand, $categoryValue, max($minSimilarity, 86));
    if ($suggestion) {
        $suggested = (string)($suggestion['brand_name'] ?? '');
        return [
            'status' => 'fix_spelling',
            'canonical_brand' => $suggested,
            'suggestion' => $suggestion,
            'action' => 'Похоже, бренд уже есть в этой категории. Исправить написание "' . $brand . '" на "' . $suggested . '".',
        ];
    }

    return [
        'status' => 'create_brand',
        'canonical_brand' => '',
        'suggestion' => null,
        'action' => 'Создать бренд "' . $brand . '" на маркетплейсе и привязать его к категории.',
    ];
}

function supplier_products_db_brand_audit_html_value($value): string
{
    return htmlspecialchars((string)$value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

function supplier_products_db_brand_audit_write_csv(string $path, array $categoryRows): void
{
    $fh = fopen($path, 'wb');
    if (!$fh) {
        throw new RuntimeException('Не удалось создать CSV отчета по брендам.');
    }
    fputcsv($fh, ['marketplace', 'status', 'brand', 'canonical_brand', 'category', 'products_count', 'action', 'scope_status', 'scope_fetched_at', 'examples'], ';');
    foreach ($categoryRows as $row) {
        $examples = [];
        foreach ((array)($row['examples'] ?? []) as $example) {
            $examples[] = trim((string)($example['offer_id'] ?? '')) . ': ' . trim((string)($example['name'] ?? ''));
        }
        fputcsv($fh, [
            supplier_products_db_brand_audit_marketplace_title((string)($row['marketplace'] ?? '')),
            supplier_products_db_brand_audit_status_title((string)($row['status'] ?? '')),
            (string)($row['brand'] ?? ''),
            (string)($row['canonical_brand'] ?? ''),
            (string)($row['category_label'] ?? $row['category_value'] ?? ''),
            (string)($row['products_count'] ?? 0),
            (string)($row['action'] ?? ''),
            (string)($row['scope_fetch']['status'] ?? ''),
            (string)($row['scope_fetch']['fetched_at'] ?? ''),
            implode(' | ', $examples),
        ], ';');
    }
    fclose($fh);
}

function supplier_products_db_brand_audit_status_rank(string $status): int
{
    return [
        'create_brand' => 0,
        'missing_brand' => 1,
        'dictionary_missing' => 2,
        'fix_spelling_add_category' => 3,
        'add_category' => 4,
        'fix_spelling' => 5,
        'category_not_selected' => 6,
        'ok' => 9,
    ][$status] ?? 8;
}

function supplier_products_db_brand_audit_status_class(string $status): string
{
    if ($status === 'ok') {
        return 'ok';
    }
    if (in_array($status, ['create_brand', 'missing_brand', 'dictionary_missing'], true)) {
        return 'bad';
    }
    return 'warn';
}

function supplier_products_db_brand_audit_visible_brand(string $value): string
{
    $value = str_replace(["\xC2\xA0", "\xE2\x80\x8B"], ' ', $value);
    $value = preg_replace('/\s+/u', ' ', (string)$value);
    return trim((string)$value);
}

function supplier_products_db_brand_audit_variant_label(string $value, string $canonical = ''): string
{
    $value = trim($value);
    $visible = supplier_products_db_brand_audit_visible_brand($value);
    if ($visible === '') {
        return '';
    }
    $canonicalVisible = supplier_products_db_brand_audit_visible_brand($canonical);
    if ($canonicalVisible !== '' && $visible === $canonicalVisible && $value !== $canonical) {
        return $visible . ' (пробелы/невидимые символы)';
    }
    return $visible;
}

function supplier_products_db_brand_audit_action_variants(array $rows, string $canonical, int $limit = 4): array
{
    $canonicalVisible = supplier_products_db_brand_audit_visible_brand($canonical);
    $variants = [];
    foreach ($rows as $row) {
        foreach (array_merge([(string)($row['brand'] ?? '')], (array)($row['base_brand_variants'] ?? [])) as $raw) {
            $label = supplier_products_db_brand_audit_variant_label((string)$raw, $canonical);
            if ($label === '' || ($canonicalVisible !== '' && $label === $canonicalVisible)) {
                continue;
            }
            $variants[$label] = true;
        }
    }
    $out = array_keys($variants);
    usort($out, 'strnatcasecmp');
    if (count($out) > $limit) {
        $out = array_slice($out, 0, $limit);
        $out[] = '...';
    }
    return $out;
}

function supplier_products_db_brand_audit_action_variant_text(array $rows, string $canonical): string
{
    $variants = supplier_products_db_brand_audit_action_variants($rows, $canonical);
    if (!$variants) {
        return 'написание';
    }
    return count($variants) === 1
        ? '"' . $variants[0] . '"'
        : 'варианты "' . implode('", "', $variants) . '"';
}

function supplier_products_db_brand_audit_matrix_key(array $row): array
{
    $canonical = trim((string)($row['canonical_brand'] ?? ''));
    if ($canonical !== '' && !supplier_products_db_brand_is_empty_like($canonical)) {
        return [
            'key' => marketplace_brand_status_norm($canonical),
            'display' => $canonical,
        ];
    }
    foreach ((array)($row['base_brand_variants'] ?? []) as $variant) {
        $variant = trim((string)$variant);
        if ($variant !== '' && !supplier_products_db_brand_is_empty_like($variant)) {
            return [
                'key' => marketplace_brand_status_norm($variant),
                'display' => $variant,
            ];
        }
    }
    $brand = trim((string)($row['brand'] ?? ''));
    if ($brand !== '' && !supplier_products_db_brand_is_empty_like($brand)) {
        return [
            'key' => marketplace_brand_status_norm($brand),
            'display' => $brand,
        ];
    }
    return [
        'key' => '__missing_brand__',
        'display' => 'Без бренда',
    ];
}

function supplier_products_db_brand_audit_build_matrix_rows(array $categoryRows): array
{
    $rows = [];
    foreach ($categoryRows as $categoryRow) {
        if (!is_array($categoryRow)) {
            continue;
        }
        $identity = supplier_products_db_brand_audit_matrix_key($categoryRow);
        $key = (string)($identity['key'] ?? '');
        if ($key === '') {
            $key = '__missing_brand__';
        }
        if (!isset($rows[$key])) {
            $rows[$key] = [
                'brand' => (string)($identity['display'] ?? 'Без бренда'),
                'brand_key' => $key,
                'variants' => [],
                'variant_counts' => [],
                'products_count' => 0,
                'status_counts' => [],
                'markets' => [
                    'ozon' => [],
                    'wb' => [],
                ],
            ];
        }
        $brand = trim((string)($categoryRow['brand'] ?? ''));
        if ($brand !== '') {
            $rows[$key]['variants'][$brand] = true;
            $rows[$key]['variant_counts'][$brand] = ($rows[$key]['variant_counts'][$brand] ?? 0) + (int)($categoryRow['products_count'] ?? 0);
        }
        foreach ((array)($categoryRow['base_brand_variants'] ?? []) as $variant) {
            $variant = trim((string)$variant);
            if ($variant !== '') {
                $rows[$key]['variants'][$variant] = true;
                $rows[$key]['variant_counts'][$variant] = ($rows[$key]['variant_counts'][$variant] ?? 0) + (int)($categoryRow['products_count'] ?? 0);
            }
        }
        $marketplace = (string)($categoryRow['marketplace'] ?? '');
        if (!isset($rows[$key]['markets'][$marketplace])) {
            $rows[$key]['markets'][$marketplace] = [];
        }
        $rows[$key]['markets'][$marketplace][] = $categoryRow;
        $status = (string)($categoryRow['status'] ?? 'unknown');
        $rows[$key]['status_counts'][$status] = ($rows[$key]['status_counts'][$status] ?? 0) + 1;
        $rows[$key]['products_count'] += (int)($categoryRow['products_count'] ?? 0);
    }

    $out = array_values(array_map(static function (array $row): array {
        $variantCounts = (array)($row['variant_counts'] ?? []);
        arsort($variantCounts);
        $row['variants'] = array_values(array_keys($variantCounts ?: (array)$row['variants']));
        if ($row['variants']) {
            $row['brand'] = (string)$row['variants'][0];
        }
        unset($row['variant_counts']);
        $row['problem_count'] = array_sum(array_filter((array)($row['status_counts'] ?? []), static fn($count, $status): bool => $status !== 'ok', ARRAY_FILTER_USE_BOTH));
        return $row;
    }, $rows));

    usort($out, static function (array $a, array $b): int {
        $cmp = ((int)($b['problem_count'] ?? 0) <=> (int)($a['problem_count'] ?? 0));
        if ($cmp !== 0) {
            return $cmp;
        }
        return strnatcasecmp((string)($a['brand'] ?? ''), (string)($b['brand'] ?? ''));
    });
    return $out;
}

function supplier_products_db_brand_audit_category_list_html(array $rows, int $limit = 8): string
{
    $h = static fn($value): string => supplier_products_db_brand_audit_html_value($value);
    $categories = [];
    foreach ($rows as $row) {
        $label = trim((string)($row['category_label'] ?? $row['category_value'] ?? ''));
        if ($label === '') {
            $label = 'Категория не выбрана';
        }
        if (!isset($categories[$label])) {
            $categories[$label] = 0;
        }
        $categories[$label] += (int)($row['products_count'] ?? 0);
    }
    arsort($categories);
    $html = '<ul class="category-list">';
    $i = 0;
    foreach ($categories as $label => $count) {
        $i++;
        if ($i > $limit) {
            $left = count($categories) - $limit;
            $html .= '<li class="muted">и еще ' . $h((string)$left) . '</li>';
            break;
        }
        $html .= '<li>' . $h($label) . ' <span class="count">' . $h((string)$count) . '</span></li>';
    }
    $html .= '</ul>';
    return $html;
}

function supplier_products_db_brand_audit_market_cell_html(array $rows): string
{
    $h = static fn($value): string => supplier_products_db_brand_audit_html_value($value);
    if (!$rows) {
        return '<div class="muted">Нет товаров для маркетплейса.</div>';
    }
    usort($rows, static function (array $a, array $b): int {
        $cmp = supplier_products_db_brand_audit_status_rank((string)($a['status'] ?? '')) <=> supplier_products_db_brand_audit_status_rank((string)($b['status'] ?? ''));
        if ($cmp !== 0) {
            return $cmp;
        }
        return strnatcasecmp((string)($a['category_label'] ?? ''), (string)($b['category_label'] ?? ''));
    });

    $byStatus = [];
    foreach ($rows as $row) {
        $status = (string)($row['status'] ?? 'unknown');
        $canonical = trim((string)($row['canonical_brand'] ?? ''));
        $actionKey = $status . '|' . $canonical;
        if (!isset($byStatus[$actionKey])) {
            $byStatus[$actionKey] = [
                'status' => $status,
                'canonical' => $canonical,
                'rows' => [],
                'products_count' => 0,
                'suggestion' => $row['suggestion'] ?? null,
            ];
        }
        $byStatus[$actionKey]['rows'][] = $row;
        $byStatus[$actionKey]['products_count'] += (int)($row['products_count'] ?? 0);
    }

    uasort($byStatus, static function (array $a, array $b): int {
        $cmp = supplier_products_db_brand_audit_status_rank((string)($a['status'] ?? '')) <=> supplier_products_db_brand_audit_status_rank((string)($b['status'] ?? ''));
        if ($cmp !== 0) {
            return $cmp;
        }
        return strnatcasecmp((string)($a['canonical'] ?? ''), (string)($b['canonical'] ?? ''));
    });

    $parts = [];
    foreach ($byStatus as $group) {
        $status = (string)($group['status'] ?? '');
        $canonical = trim((string)($group['canonical'] ?? ''));
        $count = (int)($group['products_count'] ?? 0);
        $title = supplier_products_db_brand_audit_status_title($status);
        $action = '';
        if ($status === 'create_brand') {
            $brand = trim((string)($group['rows'][0]['brand'] ?? ''));
            $action = 'Создать бренд' . ($brand !== '' ? ' "' . $brand . '"' : '') . ' и добавить категории:';
        } elseif ($status === 'add_category') {
            $action = 'Добавить категории к бренду "' . ($canonical !== '' ? $canonical : trim((string)($group['rows'][0]['brand'] ?? ''))) . '":';
        } elseif ($status === 'fix_spelling') {
            $action = 'Исправить ' . supplier_products_db_brand_audit_action_variant_text((array)$group['rows'], $canonical) . ' на "' . $canonical . '" в категориях:';
        } elseif ($status === 'fix_spelling_add_category') {
            $action = 'Исправить ' . supplier_products_db_brand_audit_action_variant_text((array)$group['rows'], $canonical) . ' на "' . $canonical . '" и добавить категории:';
        } elseif ($status === 'dictionary_missing') {
            $action = 'Обновить справочник брендов для категорий:';
        } elseif ($status === 'category_not_selected') {
            $action = 'Назначить категорию у товаров.';
        } elseif ($status === 'missing_brand') {
            $action = 'Заполнить бренд у товаров.';
        } elseif ($status === 'ok') {
            $action = 'В порядке.';
        } else {
            $action = (string)($group['rows'][0]['action'] ?? '');
        }

        $suggestion = is_array($group['suggestion'] ?? null) ? (array)$group['suggestion'] : [];
        $hint = '';
        if ($suggestion && !empty($suggestion['category_fit'])) {
            $hint = '<div class="hint">совпадение в категории: ' . $h($suggestion['brand_name'] ?? '') . ' · ' . $h((string)($suggestion['similarity'] ?? '')) . '%</div>';
        }

        $parts[] = '<div class="market-action">'
            . '<div><span class="badge ' . $h(supplier_products_db_brand_audit_status_class($status)) . '">' . $h($title) . '</span> <span class="count">' . $h((string)$count) . '</span></div>'
            . '<div class="action-text">' . $h($action) . '</div>'
            . $hint
            . supplier_products_db_brand_audit_category_list_html((array)$group['rows'])
            . '</div>';
    }
    return implode('', $parts);
}

function supplier_products_db_brand_audit_write_html(string $path, array $report, bool $includeOk): void
{
    $h = static fn($value): string => supplier_products_db_brand_audit_html_value($value);
    $datasetId = (int)($report['dataset_id'] ?? 0);
    $sourceOpId = (int)($report['op_id'] ?? 0);
    $summary = (array)($report['summary'] ?? []);
    $statusCounts = (array)($summary['status_counts'] ?? []);
    $problemRows = array_values(array_filter((array)($report['category_rows'] ?? []), static fn(array $row): bool => (string)($row['status'] ?? '') !== 'ok'));
    $categoryRows = $includeOk ? (array)($report['category_rows'] ?? []) : $problemRows;
    $matrixRows = supplier_products_db_brand_audit_build_matrix_rows((array)($report['category_rows'] ?? []));
    $logoMarketplacesForRow = static function (array $row): array {
        $marketplaces = [];
        foreach (['ozon', 'wb'] as $marketplace) {
            if (!empty($row['markets'][$marketplace])) {
                $marketplaces[] = $marketplace;
            }
        }
        return $marketplaces ?: ['ozon', 'wb'];
    };
    $rowRenderer = static function (array $row) use ($h): string {
        $examples = [];
        foreach (array_slice((array)($row['examples'] ?? []), 0, 4) as $example) {
            $offerId = trim((string)($example['offer_id'] ?? ''));
            $name = trim((string)($example['name'] ?? ''));
            $examples[] = '<div><b>' . $h($offerId) . '</b> ' . $h($name) . '</div>';
        }
        $suggestion = (array)($row['suggestion'] ?? []);
        $hint = '';
        if ($suggestion) {
            $hint = '<div class="muted">совпадение: ' . $h($suggestion['brand_name'] ?? '') . ' · ' . $h((string)($suggestion['similarity'] ?? '')) . '%</div>';
        }
        $scope = (array)($row['scope_fetch'] ?? []);
        $scopeText = trim((string)($scope['status'] ?? ''));
        if (!empty($scope['fetched_at'])) {
            $scopeText .= ' · ' . trim((string)$scope['fetched_at']);
        }
        return '<tr>'
            . '<td>' . $h(supplier_products_db_brand_audit_marketplace_title((string)($row['marketplace'] ?? ''))) . '</td>'
            . '<td><span class="badge ' . $h(supplier_products_db_brand_audit_status_class((string)($row['status'] ?? ''))) . '">' . $h(supplier_products_db_brand_audit_status_title((string)($row['status'] ?? ''))) . '</span></td>'
            . '<td><b>' . $h($row['brand'] ?? '') . '</b>' . ($row['canonical_brand'] ?? '' ? '<div class="muted">как на МП: ' . $h($row['canonical_brand']) . '</div>' : '') . $hint . '</td>'
            . '<td>' . $h($row['category_label'] ?? $row['category_value'] ?? '') . '<div class="muted">' . $h($row['category_value'] ?? '') . '</div></td>'
            . '<td class="num">' . $h((string)($row['products_count'] ?? 0)) . '</td>'
            . '<td>' . $h($row['action'] ?? '') . '</td>'
            . '<td><span class="muted">' . $h($scopeText) . '</span></td>'
            . '<td class="examples">' . implode('', $examples) . '</td>'
            . '</tr>';
    };

    ob_start();
    ?>
<!doctype html>
<html lang="ru">
<head>
  <meta charset="utf-8">
  <title>Аудит брендов поставщика</title>
