  <script>
  (() => {
    const boxes = Array.from(document.querySelectorAll('[data-brand-logo]'));
    if (!boxes.length) return;

    const outputLabels = {
      ozon: 'Ozon PNG 500x500',
      wb: 'WB JPG 120x50',
      master: 'Master PNG'
    };

    function statusUrl(box) {
      return 'brand_logo_status.php?dataset_id=' + encodeURIComponent(box.dataset.datasetId || '0')
        + '&logo_key=' + encodeURIComponent(box.dataset.logoKey || '');
    }

    function setStatus(box, text, isBad = false) {
      const node = box.querySelector('[data-logo-status]');
      if (!node) return;
      node.textContent = text;
      node.classList.toggle('bad', !!isBad);
    }

    function setBusy(box, busy) {
      const button = box.querySelector('[data-logo-generate]');
      if (button) {
        button.disabled = !!busy;
        button.textContent = busy ? 'Генерирую...' : (button.dataset.ready === '1' ? 'Сгенерировать заново' : 'Сгенерировать логотип');
      }
    }

    function renderLinks(box, outputs) {
      const target = box.querySelector('[data-logo-links]');
      if (!target) return false;
      const keys = Object.keys(outputLabels).filter((key) => outputs && outputs[key] && outputs[key].url);
      if (!keys.length) {
        target.innerHTML = '';
        return false;
      }
      target.innerHTML = keys.map((key) => {
        const href = String(outputs[key].url || '#');
        return '<a href="' + href + '">' + outputLabels[key] + '</a>';
      }).join('');
      const button = box.querySelector('[data-logo-generate]');
      if (button) button.dataset.ready = '1';
      return true;
    }

    async function pollLogo(box, keepPolling = true) {
      try {
        const response = await fetch(statusUrl(box), {cache: 'no-store'});
        const data = await response.json();
        if (!response.ok || data.error) throw new Error(data.error || 'Не удалось проверить статус операции.');
        const status = String(data.status || '');
        if (status === 'done') {
          renderLinks(box, data.outputs || {});
          setStatus(box, 'Логотип готов и сохранён постоянно. Перед отправкой проверь точное написание бренда.');
          setBusy(box, false);
          return;
        }
        if (status === 'error' || status === 'cancelled') {
          setStatus(box, data.error_text || 'Генерация завершилась ошибкой.', true);
          setBusy(box, false);
          return;
        }
        if (status === 'not_found') {
          setBusy(box, false);
          return;
        }
        setBusy(box, true);
        const msg = data.msg || (status === 'queued' ? 'В очереди...' : 'Генерирую логотип...');
        setStatus(box, msg);
        if (keepPolling) window.setTimeout(() => pollLogo(box, true), 2200);
      } catch (err) {
        setStatus(box, (err && err.message) ? err.message : 'Не удалось проверить генерацию.', true);
        setBusy(box, false);
      }
    }

    async function startLogo(box) {
      const payload = {
        dataset_id: box.dataset.datasetId || '0',
        source_op_id: box.dataset.sourceOpId || '0',
        brand: box.dataset.brand || '',
        marketplaces: box.dataset.marketplaces || 'all'
      };
      setBusy(box, true);
      setStatus(box, 'Ставлю генерацию в очередь...');
      try {
        const response = await fetch('brand_logo_generate.php', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify(payload)
        });
        const data = await response.json();
        if (!response.ok || data.error) throw new Error(data.error || 'Не удалось запустить генерацию логотипа.');
        if (!data.op_id) throw new Error('Операция создана без id.');
        if (data.logo_key) box.dataset.logoKey = String(data.logo_key);
        pollLogo(box, true);
      } catch (err) {
        setStatus(box, (err && err.message) ? err.message : 'Не удалось запустить генерацию логотипа.', true);
        setBusy(box, false);
      }
    }

    boxes.forEach((box) => {
      pollLogo(box, true);
      const button = box.querySelector('[data-logo-generate]');
      if (button) button.addEventListener('click', () => startLogo(box));
    });
  })();
  </script>
</body>
</html>
