function supplier_products_db_brand_audit_latest_report_info(array $cfg, int $datasetId): ?array
{
    $info = brand_audit_recover_latest_report($cfg, $datasetId);
    if ($info === null) {
        return null;
    }
    $opId = (int)($info['op_id'] ?? 0);
    $htmlPath = brand_audit_report_path($cfg, $datasetId, $opId, 'html');
    $jsonPath = brand_audit_report_path($cfg, $datasetId, $opId, 'json');
    if ($htmlPath === null || $jsonPath === null) {
        return $info;
    }
    $html = (string)file_get_contents($htmlPath);
    if (str_contains($html, 'brand_logo_status.php')) {
        return $info;
    }
    $report = json_decode((string)file_get_contents($jsonPath), true);
    if (!is_array($report)) {
        return $info;
    }
    $tmp = $htmlPath . '.refresh.' . getmypid();
    supplier_products_db_brand_audit_write_html($tmp, $report, true);
    $refreshed = file_get_contents($tmp);
    @unlink($tmp);
    if (is_string($refreshed) && $refreshed !== '') {
        brand_audit_atomic_write($htmlPath, $refreshed);
    }
    return $info;
}

function supplier_products_db_brand_logo_safe_slug(string $brand): string
{
    $slug = preg_replace('~[^\p{L}\p{N}._-]+~u', '_', trim($brand));
    $slug = trim((string)$slug, "._- \t\n\r\0\x0B");
    if ($slug === '') {
        $slug = 'brand';
    }
    if (mb_strlen($slug, 'UTF-8') > 64) {
        $slug = trim(mb_substr($slug, 0, 64, 'UTF-8'), "._- \t\n\r\0\x0B");
    }
    return $slug !== '' ? $slug : 'brand';
}

function supplier_products_db_brand_logo_marketplaces(string $raw): array
{
    $raw = strtolower(trim($raw));
    if ($raw === '' || $raw === 'all') {
        return ['ozon', 'wb'];
    }
    $out = [];
    foreach (preg_split('~[,\s;]+~', $raw) ?: [] as $part) {
        $part = trim((string)$part);
        if ($part === 'wildberries') {
            $part = 'wb';
        }
        if (in_array($part, ['ozon', 'wb'], true)) {
            $out[$part] = true;
        }
    }
    return $out ? array_keys($out) : ['ozon', 'wb'];
}

function supplier_products_db_brand_logo_prompt(string $brand, array $marketplaces): string
{
    $marketplaceText = implode(', ', array_map(static function (string $marketplace): string {
        return $marketplace === 'wb' ? 'Wildberries' : 'Ozon';
    }, $marketplaces));

    return "Создай профессиональный оригинальный логотип бренда для карточек и регистрации бренда на маркетплейсах {$marketplaceText}.\n"
        . "Название бренда: \"{$brand}\".\n\n"
        . "Создай новый самостоятельный знак. Не копируй и не имитируй логотипы известных компаний или существующие товарные знаки.\n\n"
        . "Требования к изображению:\n"
        . "- чистый брендовый логотип, без фото товаров, без иконок маркетплейсов, без рекламных лозунгов и без лишних слов;\n"
        . "- точное читаемое написание бренда, без опечаток, без дополнительных символов;\n"
        . "- векторный, простой, премиальный вид; хорошо читается в маленьком размере;\n"
        . "- логотип должен быть по центру на белом или очень светлом фоне;\n"
        . "- оставь безопасные поля вокруг логотипа, чтобы он корректно поместился и в квадрат 500x500, и в узкий формат 120x50.\n\n"
        . "Верни только готовый логотип без пояснений.";
}

function supplier_products_db_brand_logo_fit_image(string $bytes, int $targetW, int $targetH, string $format, int $quality = 92): array
{
    $info = @getimagesizefromstring($bytes);
    if (!is_array($info)) {
        throw new RuntimeException('Не удалось распознать сгенерированный логотип.');
    }
    if (!extension_loaded('gd')) {
        throw new RuntimeException('Для подготовки логотипов требуется PHP GD.');
    }

    $srcW = max(1, (int)($info[0] ?? 0));
    $srcH = max(1, (int)($info[1] ?? 0));
    $source = @imagecreatefromstring($bytes);
    if (!$source instanceof GdImage) {
        throw new RuntimeException('Не удалось открыть сгенерированный логотип.');
    }

    $targetW = max(1, $targetW);
    $targetH = max(1, $targetH);
    $scale = min($targetW / $srcW, $targetH / $srcH) * 0.9;
    $dstW = max(1, (int)round($srcW * $scale));
    $dstH = max(1, (int)round($srcH * $scale));
    $dstX = (int)floor(($targetW - $dstW) / 2);
    $dstY = (int)floor(($targetH - $dstH) / 2);

    $canvas = imagecreatetruecolor($targetW, $targetH);
    if (!$canvas instanceof GdImage) {
        unset($source);
        throw new RuntimeException('Не удалось создать холст логотипа.');
    }
    imagealphablending($canvas, true);
    imagesavealpha($canvas, false);
    $white = imagecolorallocate($canvas, 255, 255, 255);
    imagefilledrectangle($canvas, 0, 0, $targetW, $targetH, $white);
    imagecopyresampled($canvas, $source, $dstX, $dstY, 0, 0, $dstW, $dstH, $srcW, $srcH);
    imageinterlace($canvas, true);

    ob_start();
    $format = strtolower(trim($format));
    if ($format === 'png') {
        $ok = imagepng($canvas, null, 6);
        $mime = 'image/png';
    } else {
        $ok = imagejpeg($canvas, null, max(1, min(100, $quality)));
        $mime = 'image/jpeg';
        $format = 'jpg';
    }
    $out = ob_get_clean();
    unset($source, $canvas);
    if (!$ok || !is_string($out) || $out === '') {
        throw new RuntimeException('Не удалось сохранить файл логотипа.');
    }

    return [
        'bytes' => $out,
        'meta' => [
            'format' => $format,
            'mime' => $mime,
            'width' => $targetW,
            'height' => $targetH,
            'source_width' => $srcW,
            'source_height' => $srcH,
            'scale' => $scale,
        ],
    ];
}

function supplier_products_db_op_gpt_generate_brand_logo(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $brand = trim((string)($params['brand'] ?? ''));
    if ($brand === '' || supplier_products_db_brand_is_empty_like($brand)) {
        throw new RuntimeException('Не указано нормальное название бренда для генерации логотипа.');
    }
    if (mb_strlen($brand, 'UTF-8') > 120) {
        throw new RuntimeException('Название бренда слишком длинное для генерации логотипа.');
    }

    $marketplaces = supplier_products_db_brand_logo_marketplaces((string)($params['marketplaces'] ?? 'all'));
    $imageQuality = strtolower(trim((string)($params['image_quality'] ?? 'medium')));
    if (!in_array($imageQuality, ['low', 'medium', 'high'], true)) {
        $imageQuality = 'medium';
    }
    $defaultImageModel = trim((string)($cfg['openai_image']['default_model'] ?? 'gpt-image-2'));
    if ($defaultImageModel === '') {
        $defaultImageModel = 'gpt-image-2';
    }
    $imageModel = strtolower(trim((string)($params['image_model'] ?? $defaultImageModel)));
    if ($imageModel === '') {
        $imageModel = $defaultImageModel;
    }
    $imageResponseModel = supplier_products_db_image_response_model($cfg, $params);
    $imagePricing = openai_image_pricing_for_model($cfg, $imageModel);
    if ((string)($imagePricing['source'] ?? 'unknown') === 'unknown') {
        throw new RuntimeException('Неизвестная GPT Image модель для расчета стоимости: ' . $imageModel);
    }
    $matchedImageModel = strtolower(trim((string)($imagePricing['matched_model'] ?? $imageModel)));
    $imageSize = supplier_products_db_normalize_gpt_image_size((string)($params['image_size'] ?? '1024x1024'), $matchedImageModel, '1024x1024');
    $timeoutSec = max(60, min(600, (int)trim((string)($params['timeout_sec'] ?? '180'))));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    $slug = supplier_products_db_brand_logo_safe_slug($brand);
    $log("supplier_db gpt_generate_brand_logo: brand={$brand}, marketplaces=" . implode(',', $marketplaces) . ", image_api=/responses:image_generation, response_model={$imageResponseModel}, image_model={$imageModel}, image_size={$imageSize}, image_quality={$imageQuality}, outputs=master_png,ozon_500_png,wb_120x50_jpg\n");
    $log('image pricing: ' . openai_image_pricing_debug_string($imagePricing) . "\n");
    ops_update_progress($opId, 0, 1, 'queued', 'готовлю генерацию логотипа');

    $clientConfig = $cfg['llm_providers']['openai'] ?? ($cfg['openai'] ?? []);
    if (!is_array($clientConfig) || trim((string)($clientConfig['api_key'] ?? '')) === '') {
        throw new RuntimeException('OPENAI_API_KEY не настроен для генерации логотипов через GPT Image.');
    }
    $clientConfig['provider'] = 'openai';
    $clientConfig['api_format'] = 'responses';
    $clientConfig['model_prefix'] = '';
    $clientConfig['timeout_sec'] = $timeoutSec;
    $clientConfig['response_cache_enabled'] = false;
    $client = new OpenAIClient($clientConfig);

    $prompt = supplier_products_db_brand_logo_prompt($brand, $marketplaces);
    $promptCacheKey = 'brand_logo:' . substr(hash('sha256', strtolower($brand) . '|' . implode(',', $marketplaces) . '|' . $imageModel . '|' . $imageSize . '|' . $imageQuality), 0, 48);
    ops_update_progress($opId, 0, 1, 'gpt', 'генерирую логотип бренда');
    $raw = $client->generateImageWithResponsesTool($imageResponseModel, $imageModel, $prompt, [
        'size' => $imageSize,
        'quality' => $imageQuality,
        'output_format' => 'png',
        'background' => 'opaque',
        'moderation' => 'auto',
        'prompt_cache_key' => $promptCacheKey,
    ]);
    $generatedBytes = supplier_products_db_cover_decode_image_api_result($raw);
    $imageUsage = supplier_products_db_cover_image_api_usage($raw);
    if ((int)($imageUsage['total_tokens'] ?? 0) <= 0) {
        $imageUsage = supplier_products_db_cover_estimate_image_usage($prompt, ['width' => 0, 'height' => 0], $generatedBytes, $imageModel, $imageQuality, $imageSize, $imagePricing, 'low');
    } elseif (!empty($imageUsage['input_details_missing'])) {
        $imageUsage = supplier_products_db_cover_refine_image_usage_split($imageUsage, $prompt, ['width' => 0, 'height' => 0], $generatedBytes, $imageModel, $imageQuality, $imageSize, $imagePricing, 'low');
    }
    $imageCost = openai_image_generation_cost_breakdown(
        $cfg,
        $imageModel,
        (int)($imageUsage['text_input_tokens'] ?? 0),
        (int)($imageUsage['text_cached_input_tokens'] ?? 0),
        (int)($imageUsage['text_output_tokens'] ?? 0),
        (int)($imageUsage['image_input_tokens'] ?? 0),
        (int)($imageUsage['image_cached_input_tokens'] ?? 0),
        (int)($imageUsage['image_output_tokens'] ?? 0)
    );
    $outputSizeKey = supplier_products_db_cover_output_size_key($imageSize, $generatedBytes);
    $outputQualityKey = supplier_products_db_cover_quality_key($imageQuality);
    $fixedOutputCost = supplier_products_db_cover_image_output_price($imageModel, $outputQualityKey, $outputSizeKey, $imagePricing);
    if ($matchedImageModel !== 'gpt-image-2' && $fixedOutputCost > 0.0) {
        $tokenOutputCost = (float)($imageCost['image_output_cost'] ?? 0.0);
        $adjustedCost = round(max(0.0, (float)($imageCost['cost'] ?? 0.0) - $tokenOutputCost + $fixedOutputCost), 6);
        $imageCost['image_output_pricing_mode'] = 'fixed_per_image';
        $imageCost['image_output_size'] = $outputSizeKey;
        $imageCost['image_output_quality'] = $outputQualityKey;
        $imageCost['image_output_cost_token_based'] = $tokenOutputCost;
        $imageCost['image_output_cost'] = round($fixedOutputCost, 6);
        $imageCost['cost'] = $adjustedCost;
        $imageCost['cost_usd'] = $adjustedCost;
        $imageCost['cost_label'] = openai_format_cost($adjustedCost, (string)($imageCost['currency'] ?? ($imagePricing['currency'] ?? 'USD')));
    } else {
        $imageCost['image_output_pricing_mode'] = 'token';
        $imageCost['image_output_size'] = $outputSizeKey;
        $imageCost['image_output_quality'] = $outputQualityKey;
    }

    $master = supplier_products_db_brand_logo_fit_image($generatedBytes, 1024, 1024, 'png', 92);
    $ozon = supplier_products_db_brand_logo_fit_image($generatedBytes, 500, 500, 'png', 92);
    $wb = supplier_products_db_brand_logo_fit_image($generatedBytes, 120, 50, 'jpg', 92);
    if (strlen((string)$ozon['bytes']) > 5 * 1024 * 1024) {
        throw new RuntimeException('Файл логотипа Ozon превышает допустимые 5 МБ.');
    }
    foreach ([85, 75, 65, 55, 45] as $quality) {
        if (strlen((string)$wb['bytes']) <= 100 * 1024) {
            break;
        }
        $wb = supplier_products_db_brand_logo_fit_image($generatedBytes, 120, 50, 'jpg', $quality);
    }
    if (strlen((string)$wb['bytes']) > 100 * 1024) {
        throw new RuntimeException('Файл логотипа WB превышает допустимые 100 КБ.');
    }

    $masterAbs = $outDir . '/brand_logo_' . $slug . '_master.png';
    $ozonAbs = $outDir . '/brand_logo_' . $slug . '_ozon_500x500.png';
    $wbAbs = $outDir . '/brand_logo_' . $slug . '_wb_120x50.jpg';
    if (file_put_contents($masterAbs, (string)$master['bytes']) === false
        || file_put_contents($ozonAbs, (string)$ozon['bytes']) === false
        || file_put_contents($wbAbs, (string)$wb['bytes']) === false) {
        throw new RuntimeException('Не удалось сохранить файлы логотипа.');
    }
    @chmod($masterAbs, 0664);
    @chmod($ozonAbs, 0664);
    @chmod($wbAbs, 0664);

    $metaAbs = $outDir . '/brand_logo_' . $slug . '_meta.json';
    $meta = [
        'brand' => $brand,
        'dataset_id' => $datasetId,
        'op_id' => $opId,
        'generated_at' => date('c'),
        'marketplaces' => $marketplaces,
        'source_op_id' => (int)($params['source_op_id'] ?? 0),
        'image_model' => $imageModel,
        'image_response_model' => $imageResponseModel,
        'image_size' => $imageSize,
        'image_quality' => $imageQuality,
        'usage' => $imageUsage,
        'cost' => $imageCost,
        'outputs' => [
            'master_png' => array_merge((array)($master['meta'] ?? []), ['bytes' => strlen((string)$master['bytes'])]),
            'ozon_png' => array_merge((array)($ozon['meta'] ?? []), ['bytes' => strlen((string)$ozon['bytes']), 'max_bytes' => 5 * 1024 * 1024]),
            'wb_jpg' => array_merge((array)($wb['meta'] ?? []), ['bytes' => strlen((string)$wb['bytes']), 'max_bytes' => 100 * 1024]),
        ],
    ];
    file_put_contents($metaAbs, json_encode($meta, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT));
    @chmod($metaAbs, 0664);
    brand_audit_persist_logo_files($cfg, $datasetId, $brand, $opId, [
        'master' => (string)$master['bytes'],
        'ozon' => (string)$ozon['bytes'],
        'wb' => (string)$wb['bytes'],
    ], $meta);

    ops_update_progress($opId, 1, 1, 'done', 'логотип готов');
    $log('done: logo files prepared for brand=' . $brand . ', cost=' . (string)($imageCost['cost_label'] ?? '') . "\n");

    return [
        'logo_master_png' => rel_to_outputs($cfg, $masterAbs),
        'logo_ozon_png' => rel_to_outputs($cfg, $ozonAbs),
        'logo_wb_jpg' => rel_to_outputs($cfg, $wbAbs),
        'logo_meta_json' => rel_to_outputs($cfg, $metaAbs),
        'summary_json_inline' => [
            'title' => 'gpt_generate_brand_logo',
            'items' => [
                'Brand: ' . $brand,
                'Marketplaces: ' . implode(', ', $marketplaces),
                'Image model: ' . $imageModel,
                'Ozon logo: PNG 500x500',
                'WB logo: JPG 120x50',
                'Cost: ' . (string)($imageCost['cost_label'] ?? openai_format_cost(0.0, 'USD')),
            ],
            'metrics' => [
                'brand' => $brand,
                'marketplaces' => $marketplaces,
                'image_model' => $imageModel,
                'image_response_model' => $imageResponseModel,
                'usage' => $imageUsage,
                'image_generation_cost' => (float)($imageCost['cost'] ?? 0.0),
                'image_generation_cost_label' => (string)($imageCost['cost_label'] ?? ''),
                'image_generation_cost_currency' => (string)($imageCost['currency'] ?? 'USD'),
            ],
        ],
    ];
}

function supplier_products_db_op_analyze_brand_category_map(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    marketplace_brand_dictionary_tables_ensure();
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $marketplaces = supplier_products_db_brand_audit_marketplaces((string)($params['marketplaces'] ?? 'all'));
    $includeOk = (string)($params['include_ok'] ?? '1') !== '0';
    $minSimilarity = max(55, min(98, (int)trim((string)($params['min_similarity'] ?? '86'))));

    $products = supplier_products_db_load_products($supplierId, $params, $maxItems);
    $productIds = supplier_products_db_product_ids($products);
    $fieldsByProduct = supplier_products_db_fields_for_products($productIds);
    $total = count($products);
    $log('supplier_db analyze_brand_category_map: products=' . $total . ', marketplaces=' . implode(',', $marketplaces) . ', min_similarity=' . $minSimilarity . "\n");
    ops_update_progress($opId, 0, max(1, $total), 'brand_audit_collect', "сбор товаров 0/{$total}");

    $groups = [];
    $allNorms = ['ozon' => [], 'wb' => []];
    $ozonParents = [];
    $ozonLeafs = [];
    $wbSubjects = [];

    $seen = 0;
    foreach ($products as $product) {
        $seen++;
        $productId = (int)($product['id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        $fields = $fieldsByProduct[$productId] ?? [];
        $name = trim((string)($product['name'] ?? ''));
        if (mb_strlen($name, 'UTF-8') > 140) {
            $name = rtrim(mb_substr($name, 0, 140, 'UTF-8'), " \t\n\r\0\x0B.,;:-") . '...';
        }
        foreach ($marketplaces as $marketplace) {
            $effective = supplier_products_db_brand_audit_effective_brand($product, $fields, $marketplace);
            $brand = trim((string)($effective['brand'] ?? ''));
            $norm = supplier_products_db_brand_is_empty_like($brand) ? '' : marketplace_brand_status_norm($brand);
            $categoryValue = supplier_products_db_product_category_value($product, $fields, $marketplace === 'wb' ? 'wildberries' : 'ozon');
            $ctx = supplier_products_db_brand_audit_category_context($marketplace, $categoryValue);
            $categoryLabel = supplier_products_db_brand_audit_category_label($marketplace, $categoryValue, $ctx);
            $key = $marketplace . '|' . ($norm !== '' ? $norm : '__missing_brand__') . '|' . ($brand !== '' ? $brand : '__empty__') . '|' . ($categoryValue !== '' ? $categoryValue : '__missing_category__');
            if (!isset($groups[$key])) {
                $groups[$key] = [
                    'marketplace' => $marketplace,
                    'brand' => $brand,
                    'brand_norm' => $norm,
                    'category_value' => $categoryValue,
                    'category_label' => $categoryLabel,
                    'category_context' => $ctx,
                    'scope_fetch' => supplier_products_db_brand_audit_scope_fetch($marketplace, $categoryValue, $ctx),
                    'products_count' => 0,
                    'product_ids' => [],
                    'examples' => [],
                    'base_brand_variants' => [],
                    'source_fields' => [],
                ];
            }
            $groups[$key]['products_count']++;
            $groups[$key]['product_ids'][$productId] = true;
            $baseBrand = trim((string)($effective['base_brand'] ?? ''));
            if ($baseBrand !== '') {
                $groups[$key]['base_brand_variants'][$baseBrand] = true;
            }
            $sourceField = (string)($effective['source_field'] ?? '');
            if ($sourceField !== '') {
                $groups[$key]['source_fields'][$sourceField] = true;
            }
            if (count($groups[$key]['examples']) < 8) {
                $groups[$key]['examples'][] = [
                    'product_id' => $productId,
                    'offer_id' => trim((string)($product['offer_id'] ?? '')),
                    'vendor_code' => trim((string)($product['vendor_code'] ?? '')),
                    'name' => $name,
                    'base_brand' => $baseBrand,
                ];
            }
            if ($norm !== '') {
                $allNorms[$marketplace][$norm] = true;
            }
            if ($marketplace === 'wb') {
                $subjectId = (int)($ctx['subject_id'] ?? 0);
                if ($subjectId > 0) {
                    $wbSubjects[$subjectId] = true;
                }
            } else {
                $parentId = (int)($ctx['parent_id'] ?? 0);
                $leafId = (int)($ctx['leaf_id'] ?? 0);
                if ($parentId > 0) {
                    $ozonParents[$parentId] = true;
                }
                if ($leafId > 0) {
                    $ozonLeafs[$leafId] = true;
                }
            }
        }
        if ($seen % 500 === 0) {
            ops_update_progress($opId, $seen, max(1, $total), 'brand_audit_collect', "сбор товаров {$seen}/{$total}");
        }
    }

    $groupsTotal = count($groups);
    ops_update_progress($opId, 0, max(1, $groupsTotal), 'brand_audit_groups', "загрузка справочников, групп {$groupsTotal}");
    $existing = [
        'ozon' => marketplace_brand_status_fetch_existing_norms('ozon', array_keys($allNorms['ozon'])),
        'wb' => marketplace_brand_status_fetch_existing_norms('wb', array_keys($allNorms['wb'])),
    ];
    $wbParentBySubject = marketplace_brand_status_wb_parent_ids(array_keys($wbSubjects));
    $ozonFit = marketplace_brand_status_fetch_ozon_fit(array_keys($allNorms['ozon']), array_keys($ozonParents), array_keys($ozonLeafs));
    $wbFit = marketplace_brand_status_fetch_wb_fit(array_keys($allNorms['wb']), array_keys($wbSubjects), array_values($wbParentBySubject));
    ops_update_progress($opId, 0, max(1, $groupsTotal), 'brand_audit_groups', "проверка групп 0/{$groupsTotal}");

    $categoryRows = [];
    $brandRowsByKey = [];
    $statusCounts = [];
    $problemGroups = 0;
    $idx = 0;
    foreach ($groups as $group) {
        $idx++;
        $resolved = supplier_products_db_brand_audit_resolve_group($group, $existing, $ozonFit, $wbFit, $wbParentBySubject, $minSimilarity);
        $status = (string)($resolved['status'] ?? 'unknown');
        $statusCounts[$status] = ($statusCounts[$status] ?? 0) + 1;
        if ($status !== 'ok') {
            $problemGroups++;
        }
        $row = [
            'marketplace' => (string)$group['marketplace'],
            'brand' => (string)$group['brand'],
            'brand_norm' => (string)$group['brand_norm'],
            'canonical_brand' => (string)($resolved['canonical_brand'] ?? ''),
            'category_value' => (string)$group['category_value'],
            'category_label' => (string)$group['category_label'],
            'category_context' => (array)$group['category_context'],
            'scope_fetch' => (array)$group['scope_fetch'],
            'products_count' => (int)$group['products_count'],
            'product_ids_count' => count((array)$group['product_ids']),
            'examples' => (array)$group['examples'],
            'base_brand_variants' => array_keys((array)$group['base_brand_variants']),
            'source_fields' => array_keys((array)$group['source_fields']),
            'status' => $status,
            'status_title' => supplier_products_db_brand_audit_status_title($status),
            'action' => (string)($resolved['action'] ?? ''),
            'suggestion' => $resolved['suggestion'] ?? null,
        ];
        $categoryRows[] = $row;

        $brandKey = $row['marketplace'] . '|' . ($row['brand_norm'] !== '' ? $row['brand_norm'] : '__missing__') . '|' . ($row['brand'] !== '' ? $row['brand'] : '__empty__');
        if (!isset($brandRowsByKey[$brandKey])) {
            $brandRowsByKey[$brandKey] = [
                'marketplace' => $row['marketplace'],
                'brand' => $row['brand'],
                'brand_norm' => $row['brand_norm'],
                'products' => [],
                'categories' => [],
                'status_counts' => [],
                'primary_action' => '',
                'worst_rank' => -1,
            ];
        }
        foreach ((array)$group['product_ids'] as $productId => $_) {
            $brandRowsByKey[$brandKey]['products'][(int)$productId] = true;
        }
        $brandRowsByKey[$brandKey]['categories'][$row['category_value'] !== '' ? $row['category_value'] : '__missing__'] = true;
        $brandRowsByKey[$brandKey]['status_counts'][$status] = ($brandRowsByKey[$brandKey]['status_counts'][$status] ?? 0) + 1;
        $rank = [
            'ok' => 0,
            'fix_spelling' => 1,
            'add_category' => 2,
            'fix_spelling_add_category' => 3,
            'category_not_selected' => 4,
            'dictionary_missing' => 5,
            'missing_brand' => 6,
            'create_brand' => 7,
        ][$status] ?? 8;
        if ($rank > (int)$brandRowsByKey[$brandKey]['worst_rank']) {
            $brandRowsByKey[$brandKey]['worst_rank'] = $rank;
            $brandRowsByKey[$brandKey]['primary_action'] = (string)$row['action'];
        }
        if ($idx === 1 || $idx % 25 === 0 || $idx >= $groupsTotal) {
            ops_update_progress($opId, $idx, max(1, $groupsTotal), 'brand_audit_groups', "проверка групп {$idx}/{$groupsTotal}");
        }
    }

    usort($categoryRows, static function (array $a, array $b): int {
        $rank = [
            'create_brand' => 0,
            'missing_brand' => 1,
            'dictionary_missing' => 2,
            'fix_spelling_add_category' => 3,
            'add_category' => 4,
            'fix_spelling' => 5,
            'category_not_selected' => 6,
            'ok' => 9,
        ];
        $cmp = (($rank[(string)($a['status'] ?? '')] ?? 8) <=> ($rank[(string)($b['status'] ?? '')] ?? 8));
        if ($cmp !== 0) {
            return $cmp;
        }
        $cmp = strnatcasecmp((string)($a['marketplace'] ?? ''), (string)($b['marketplace'] ?? ''));
        if ($cmp !== 0) {
            return $cmp;
        }
        $cmp = strnatcasecmp((string)($a['brand'] ?? ''), (string)($b['brand'] ?? ''));
        if ($cmp !== 0) {
            return $cmp;
        }
        return strnatcasecmp((string)($a['category_label'] ?? ''), (string)($b['category_label'] ?? ''));
    });

    $brandRows = [];
    foreach ($brandRowsByKey as $row) {
        $brandRows[] = [
            'marketplace' => (string)$row['marketplace'],
            'brand' => (string)$row['brand'],
            'brand_norm' => (string)$row['brand_norm'],
            'products_count' => count((array)$row['products']),
            'categories_count' => count((array)$row['categories']),
            'status_counts' => (array)$row['status_counts'],
            'primary_action' => (string)$row['primary_action'],
        ];
    }
    usort($brandRows, static function (array $a, array $b): int {
        $aProblems = array_sum(array_filter((array)($a['status_counts'] ?? []), static fn($count, $status): bool => $status !== 'ok', ARRAY_FILTER_USE_BOTH));
        $bProblems = array_sum(array_filter((array)($b['status_counts'] ?? []), static fn($count, $status): bool => $status !== 'ok', ARRAY_FILTER_USE_BOTH));
        $cmp = $bProblems <=> $aProblems;
        if ($cmp !== 0) {
            return $cmp;
        }
        return strnatcasecmp((string)($a['brand'] ?? ''), (string)($b['brand'] ?? ''));
    });

    $summary = [
        'products_seen' => $seen,
        'marketplaces' => $marketplaces,
        'brand_category_groups' => count($categoryRows),
        'brand_rows' => count($brandRows),
        'problem_groups' => $problemGroups,
        'status_counts' => $statusCounts,
        'min_similarity' => $minSimilarity,
        'max_items' => $maxItems,
    ];
    $report = [
        'title' => 'analyze_brand_category_map',
        'storage' => 'supplier_products_db',
        'dataset_id' => $datasetId,
        'op_id' => $opId,
        'summary' => $summary,
        'brand_rows' => $brandRows,
        'category_rows' => $categoryRows,
    ];

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    $reportAbs = $outDir . '/brand_category_audit.json';
    $htmlAbs = $outDir . '/brand_category_audit.html';
    $csvAbs = $outDir . '/brand_category_audit.csv';
    file_put_contents($reportAbs, json_encode($report, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT));
    supplier_products_db_brand_audit_write_html($htmlAbs, $report, $includeOk);
    supplier_products_db_brand_audit_write_csv($csvAbs, $categoryRows);
    brand_audit_persist_report($cfg, $datasetId, $opId, $reportAbs, $htmlAbs, $csvAbs, $summary);

    ops_update_progress($opId, max(1, $groupsTotal), max(1, $groupsTotal), 'done', 'brand audit completed');
    $log('permanent report saved: dataset=' . $datasetId . ', op=' . $opId . "\n");
    $log('done: groups=' . count($categoryRows) . ', problems=' . $problemGroups . ', statuses=' . json_encode($statusCounts, JSON_UNESCAPED_UNICODE) . "\n");

    return [
        'report_json' => rel_to_outputs($cfg, $reportAbs),
        'report_html' => rel_to_outputs($cfg, $htmlAbs),
        'brand_category_audit_csv' => rel_to_outputs($cfg, $csvAbs),
        'summary_json_inline' => [
            'title' => 'analyze_brand_category_map',
            'items' => [
                'Products seen: ' . $seen,
                'Brand/category groups: ' . count($categoryRows),
                'Problem groups: ' . $problemGroups,
                'Brands in products: ' . count($brandRows),
                'Min spelling similarity: ' . $minSimilarity,
            ],
            'metrics' => $summary,
        ],
    ];
}

function supplier_products_db_op_sanitize_description_links(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $products = supplier_products_db_load_products($supplierId, $params, $maxItems);
    $total = count($products);
    $log("supplier_db sanitize_description_links: products={$total}, max_items={$maxItems}\n");
    ops_update_progress($opId, 0, max(1, $total), 'db', 'sanitizing descriptions');

    $pdo = db();
    $updProduct = $pdo->prepare("UPDATE feedtools_supplier_products SET description_html = ?, pictures_json = ? WHERE id = ?");
    $updField = $pdo->prepare("UPDATE feedtools_supplier_product_fields SET field_value = ? WHERE id = ?");
    $fieldsStmt = $pdo->prepare("
        SELECT *
        FROM feedtools_supplier_product_fields
        WHERE product_id = ?
          AND field_kind = 'param'
        ORDER BY sort_order ASC, id ASC
    ");

    $changedProducts = [];
    $offersTouched = 0;
    $descriptionsProcessed = 0;
    $descriptionsChanged = 0;
    $paramsProcessed = 0;
    $paramsChanged = 0;
    $picturesAdded = 0;
    $done = 0;

    foreach ($products as $product) {
        $productId = (int)($product['id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        $changed = false;

        $description = (string)($product['description_html'] ?? '');
        $cleanDescription = $description;
        $foundPictures = [];
        if (trim($description) !== '') {
            $descriptionsProcessed++;
            foreach (ft_extract_urls($description) as $url) {
                $url = trim((string)$url);
                if ($url !== '' && ft_looks_like_image_url($url)) {
                    $foundPictures[$url] = true;
                }
            }
            $clean = ft_sanitize_markupish_text($description);
            $plainClean = ft_text_normalize_space(strip_tags($clean));
            if (mb_strlen($plainClean, 'UTF-8') > 6000) {
                $cut = mb_substr($plainClean, 0, 6000, 'UTF-8');
                $clean = '<p>' . htmlspecialchars(ft_text_normalize_space($cut), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</p>';
            }
            $cleanDescription = trim((string)$clean);
            if (ft_markup_to_plain_text($cleanDescription) !== ft_markup_to_plain_text($description)) {
                $descriptionsChanged++;
                $changed = true;
            }
        }

        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        $seenPictures = array_fill_keys($pictures, true);
        foreach (array_keys($foundPictures) as $url) {
            if (!isset($seenPictures[$url])) {
                $seenPictures[$url] = true;
                $pictures[] = $url;
                $picturesAdded++;
                $changed = true;
            }
        }

        if ($changed) {
            $updProduct->execute([
                $cleanDescription,
                json_encode($pictures, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
                $productId,
            ]);
        }

        $fieldsStmt->execute([$productId]);
        while ($field = $fieldsStmt->fetch(PDO::FETCH_ASSOC)) {
            $paramsProcessed++;
            $raw = (string)($field['field_value'] ?? '');
            $nameNorm = ft_text_sanitize_lc(trim((string)($field['field_name'] ?? '')));
            $preserveLinks = in_array($nameNorm, [
                ft_text_sanitize_lc('видео'),
                ft_text_sanitize_lc('Озон.Видео: ссылка'),
                ft_text_sanitize_lc('Озон.Видеообложка: ссылка'),
            ], true);
            $clean = $preserveLinks ? ft_text_normalize_inline($raw) : ft_sanitize_plain_text($raw);
            if ($clean !== ft_text_normalize_space($raw)) {
                $updField->execute([$clean, (int)$field['id']]);
                $paramsChanged++;
                $changed = true;
            }
        }

        if ($changed) {
            $offersTouched++;
            $changedProducts[] = $productId;
        }

        $done++;
        if ($done % 100 === 0) {
            ops_update_progress($opId, $done, max(1, $total), 'db', "processed={$done}, changed={$offersTouched}");
        }
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, $changedProducts, $cfg, $opId);
    $report = [
        'title' => 'sanitize_description_links',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_scanned' => $total,
            'products_changed' => $offersTouched,
            'descriptions_processed' => $descriptionsProcessed,
            'descriptions_changed' => $descriptionsChanged,
            'params_processed' => $paramsProcessed,
            'params_changed' => $paramsChanged,
            'pictures_added_total' => $picturesAdded,
        ],
        'dataset' => $dataset,
    ];

    return supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
}

function supplier_products_db_pixlab_ext_for_mime(string $mime): string
{
    $mime = strtolower(trim($mime));
    return match ($mime) {
        'image/jpeg', 'image/jpg', 'image/pjpeg' => 'jpg',
        'image/png', 'image/x-png' => 'png',
        'image/webp' => 'webp',
        default => '',
    };
}

function supplier_products_db_pixlab_detect_image(string $path): array
{
    if (!is_file($path)) {
        throw new RuntimeException('Файл фотографии не найден.');
    }

    $mime = '';
    if (class_exists('finfo')) {
        $finfo = new finfo(FILEINFO_MIME_TYPE);
        $mime = (string)($finfo->file($path) ?: '');
    }
    if ($mime === '' && function_exists('mime_content_type')) {
        $mime = (string)(mime_content_type($path) ?: '');
    }
    if ($mime === '' && function_exists('getimagesize')) {
        $info = @getimagesize($path);
        if (is_array($info) && !empty($info['mime'])) {
            $mime = (string)$info['mime'];
        }
    }

    $ext = supplier_products_db_pixlab_ext_for_mime($mime);
    if ($ext === '') {
        throw new RuntimeException('PixLab TXT-REMOVE поддерживает только JPG, PNG и WebP. MIME: ' . ($mime !== '' ? $mime : 'не определён'));
    }

    return [
        'path' => $path,
        'mime' => $mime,
        'ext' => $ext,
        'size' => (int)filesize($path),
    ];
}

function supplier_products_db_pixlab_download_to_temp(string $url, int $maxBytes, int $timeoutSec): array
{
    if (!function_exists('curl_init')) {
        throw new RuntimeException('PHP cURL не установлен: PixLab-операция не может скачать фото.');
    }

    $tmp = tempnam(sys_get_temp_dir(), 'ft_pixlab_');
    if ($tmp === false) {
        throw new RuntimeException('Не удалось создать временный файл для фото.');
    }

    $fh = fopen($tmp, 'wb');
    if (!is_resource($fh)) {
        @unlink($tmp);
        throw new RuntimeException('Не удалось открыть временный файл для фото.');
    }

    $bytes = 0;
    $tooLarge = false;
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_MAXREDIRS => 5,
        CURLOPT_CONNECTTIMEOUT => min(20, max(5, $timeoutSec)),
        CURLOPT_TIMEOUT => max(20, $timeoutSec),
        CURLOPT_USERAGENT => 'FeedTools PixLab TXT-REMOVE/1.0',
        CURLOPT_SSL_VERIFYPEER => true,
        CURLOPT_SSL_VERIFYHOST => 2,
        CURLOPT_WRITEFUNCTION => static function ($ch, string $chunk) use ($fh, &$bytes, &$tooLarge, $maxBytes): int {
            $len = strlen($chunk);
            $bytes += $len;
            if ($maxBytes > 0 && $bytes > $maxBytes) {
                $tooLarge = true;
                return 0;
            }
            $written = fwrite($fh, $chunk);
            return $written === false ? 0 : $written;
        },
    ]);

    $ok = curl_exec($ch);
    $err = (string)curl_error($ch);
    $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    fclose($fh);

    if ($tooLarge) {
        @unlink($tmp);
        throw new RuntimeException('Фото больше лимита PixLab-операции: ' . $maxBytes . ' байт.');
    }
    if ($ok === false || $httpCode >= 400 || !is_file($tmp) || filesize($tmp) <= 0) {
        @unlink($tmp);
        $details = $err !== '' ? $err : ('HTTP ' . $httpCode);
        throw new RuntimeException('Не удалось скачать фото: ' . $details);
    }

    $image = supplier_products_db_pixlab_detect_image($tmp);
    $image['cleanup'] = true;
    return $image;
}

function supplier_products_db_pixlab_source_file(string $url, array $cfg, int $maxBytes, int $timeoutSec): array
{
    $url = trim($url);
    if ($url === '') {
        throw new RuntimeException('Пустая ссылка на фото.');
    }

    $relative = supplier_products_local_image_relative_from_url($url);
    if ($relative !== '') {
        $path = supplier_products_local_image_abs_path($relative, $cfg);
        if ($path === '' || !is_file($path)) {
            throw new RuntimeException('Локальный файл фото не найден: ' . $relative);
        }
        $image = supplier_products_db_pixlab_detect_image($path);
        $image['cleanup'] = false;
        return $image;
    }

    $scheme = strtolower((string)(parse_url($url, PHP_URL_SCHEME) ?? ''));
    if ($scheme !== 'http' && $scheme !== 'https') {
        throw new RuntimeException('PixLab-операция поддерживает только локальные, HTTP и HTTPS фото.');
    }

    return supplier_products_db_pixlab_download_to_temp($url, $maxBytes, $timeoutSec);
}

function supplier_products_db_pixlab_response_error(array $json, int $httpCode): string
{
    foreach (['message', 'error', 'description'] as $key) {
        if (isset($json[$key]) && trim((string)$json[$key]) !== '') {
            return trim((string)$json[$key]);
        }
    }
    if (isset($json['errors']) && is_array($json['errors'])) {
        $parts = [];
        foreach ($json['errors'] as $err) {
            if (is_scalar($err)) {
                $parts[] = (string)$err;
            } elseif (is_array($err)) {
                $parts[] = trim((string)($err['message'] ?? $err['error'] ?? json_encode($err, JSON_UNESCAPED_UNICODE)));
            }
        }
        $parts = array_values(array_filter($parts));
        if ($parts) {
            return implode('; ', $parts);
        }
    }
    return 'HTTP ' . $httpCode;
}

function supplier_products_db_pixlab_is_rate_limit_error(Throwable $e): bool
{
    $message = mb_strtolower($e->getMessage(), 'UTF-8');
    return str_contains($message, 'requests per minute')
        || str_contains($message, 'rate limit')
        || str_contains($message, 'too many requests')
        || str_contains($message, 'limited to');
}

function supplier_products_db_pixlab_download_bytes(string $url, int $maxBytes, int $timeoutSec): string
{
    $tmp = supplier_products_db_pixlab_download_to_temp($url, $maxBytes, $timeoutSec);
    try {
        $bytes = (string)file_get_contents((string)$tmp['path']);
    } finally {
        if (!empty($tmp['cleanup'])) {
            @unlink((string)$tmp['path']);
        }
    }
    if ($bytes === '') {
        throw new RuntimeException('PixLab вернул пустое изображение.');
    }
    return $bytes;
}

function supplier_products_db_pixlab_call_txtremove(string $endpoint, string $apiKey, array $image, int $maxBytes, int $timeoutSec): array
{
    if (!function_exists('curl_init')) {
        throw new RuntimeException('PHP cURL не установлен: PixLab-операция недоступна.');
    }
    if (!class_exists('CURLFile')) {
        throw new RuntimeException('PHP CURLFile не установлен: PixLab-операция недоступна.');
    }

    $ch = curl_init($endpoint);
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_CONNECTTIMEOUT => min(20, max(5, $timeoutSec)),
        CURLOPT_TIMEOUT => max(30, $timeoutSec),
        CURLOPT_POSTFIELDS => [
            'key' => $apiKey,
            'file' => new CURLFile((string)$image['path'], (string)$image['mime'], 'photo.' . (string)$image['ext']),
        ],
        CURLOPT_HTTPHEADER => ['Accept: application/json'],
    ]);

    $body = curl_exec($ch);
    $err = (string)curl_error($ch);
    $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($body === false) {
        throw new RuntimeException('PixLab TXT-REMOVE не ответил: ' . ($err !== '' ? $err : 'unknown cURL error'));
    }

    $json = json_decode((string)$body, true);
    if (!is_array($json)) {
        $snippet = mb_substr(trim((string)$body), 0, 300, 'UTF-8');
        throw new RuntimeException('PixLab TXT-REMOVE вернул не JSON: ' . $snippet);
    }

    $status = isset($json['status']) && is_numeric($json['status']) ? (int)$json['status'] : $httpCode;
    $hasError = !empty($json['error']) || ($httpCode >= 400) || ($status >= 400);
    if ($hasError) {
        throw new RuntimeException('PixLab TXT-REMOVE error: ' . supplier_products_db_pixlab_response_error($json, $httpCode));
    }

    $mime = trim((string)($json['mimeType'] ?? $json['mime'] ?? $image['mime'] ?? ''));
    $ext = strtolower(trim((string)($json['extension'] ?? '')));
    if ($ext === '') {
        $ext = supplier_products_db_pixlab_ext_for_mime($mime);
    }
    if ($mime === '' && $ext !== '') {
        $mime = match ($ext) {
            'jpg', 'jpeg' => 'image/jpeg',
            'png' => 'image/png',
            'webp' => 'image/webp',
            default => '',
        };
    }
    if ($ext === '') {
        $ext = (string)($image['ext'] ?? 'jpg');
    }
    if ($mime === '') {
        $mime = (string)($image['mime'] ?? 'image/jpeg');
    }

    $raw = '';
    foreach (['imgData', 'imageData', 'data'] as $key) {
        if (isset($json[$key]) && trim((string)$json[$key]) !== '') {
            $raw = trim((string)$json[$key]);
            break;
        }
    }
    if ($raw !== '') {
        if (str_starts_with($raw, 'data:') && str_contains($raw, ',')) {
            $raw = substr($raw, strpos($raw, ',') + 1);
        }
        $bytes = base64_decode($raw, true);
        if ($bytes === false || $bytes === '') {
            throw new RuntimeException('PixLab вернул повреждённый base64 imgData.');
        }
        return [
            'bytes' => $bytes,
            'mime' => $mime,
            'ext' => $ext,
            'raw' => $json,
        ];
    }

    foreach (['link', 'url', 'image', 'result'] as $key) {
        $link = trim((string)($json[$key] ?? ''));
        if ($link !== '' && preg_match('~^https?://~i', $link)) {
            return [
                'bytes' => supplier_products_db_pixlab_download_bytes($link, $maxBytes, $timeoutSec),
                'mime' => $mime,
                'ext' => $ext,
                'raw' => $json,
            ];
        }
    }

    throw new RuntimeException('PixLab TXT-REMOVE не вернул imgData или ссылку на изображение.');
}

function supplier_products_db_pixlab_save_image(int $supplierId, int $productId, int $photoIndex, string $bytes, string $mime, string $ext, array $cfg): string
{
    $ext = strtolower(trim($ext));
    if ($ext === '') {
        $ext = supplier_products_db_pixlab_ext_for_mime($mime);
    }
    if ($ext === '') {
        $ext = 'jpg';
    }

    $baseDir = supplier_products_image_storage_dir($cfg);
    $relativeDir = 'supplier_' . $supplierId . '/' . date('Ym') . '/pixlab';
    $dir = supplier_products_ensure_writable_dir($baseDir . '/' . $relativeDir, 'Не удалось создать папку для очищенных PixLab-фото.');
    $fileName = 'product_' . $productId . '_photo_' . ($photoIndex + 1) . '_txtremove_' . date('Ymd_His') . '_' . bin2hex(random_bytes(4)) . '.' . $ext;
    $path = $dir . '/' . $fileName;
    if (file_put_contents($path, $bytes) === false) {
        throw new RuntimeException('Не удалось сохранить очищенное PixLab-фото.');
    }
    @chmod($path, 0664);

    return supplier_products_publish_stored_image($path, $relativeDir . '/' . $fileName, $cfg, true);
}

function supplier_products_db_pixlab_photo_is_processed(string $url): bool
{
    $relative = supplier_products_local_image_relative_from_url($url);
    if ($relative === '') {
        return false;
    }
    $relative = str_replace('\\', '/', $relative);
    return str_contains($relative, '/pixlab/') && str_contains($relative, '_txtremove_');
}

function supplier_products_db_pixlab_cost_fields(array $pixlab, int $apiRequests): array
{
    $apiRequests = max(0, $apiRequests);
    $pricePer1000 = max(0.0, (float)($pixlab['price_per_1000_requests'] ?? 0.07));
    $currency = strtoupper(trim((string)($pixlab['cost_currency'] ?? 'USD')));
    if ($currency === '') {
        $currency = 'USD';
    }
    $cost = round(($apiRequests * $pricePer1000) / 1000.0, 6);

    return [
        'api_requests' => $apiRequests,
        'cost' => $cost,
        'cost_currency' => $currency,
        'cost_label' => openai_format_cost($cost, $currency),
        'cost_usd' => $cost,
        'price_per_1000_requests' => round($pricePer1000, 6),
        'price_per_1000_label' => openai_format_cost(round($pricePer1000, 6), $currency),
    ];
}

function supplier_products_db_white_bg_watermark_picture_is_generated(string $url): bool
{
    $relative = supplier_products_local_image_relative_from_url($url);
    if ($relative === '') {
        return false;
    }
    $relative = str_replace('\\', '/', $relative);
    return str_contains($relative, '/gpt_cover/')
        || str_contains($relative, '/gpt_photo_variant/')
        || str_contains($relative, '/photo_collage/')
        || str_contains($relative, '/product_specs_photo/');
}

function supplier_products_db_white_bg_watermark_picture_is_processed(string $url): bool
{
    $relative = supplier_products_local_image_relative_from_url($url);
    if ($relative === '') {
        return false;
    }
    $relative = str_replace('\\', '/', $relative);
    return str_contains($relative, '/white_bg_watermark_clean/');
}

function supplier_products_db_white_bg_watermark_dilate_mask(string $seed, int $w, int $h, int $radius): string
{
    $w = max(1, $w);
    $h = max(1, $h);
    $radius = max(0, $radius);
    $size = $w * $h;
    if ($radius <= 0) {
        return $seed;
    }

    $hmask = str_repeat("\0", $size);
    for ($y = 0; $y < $h; $y++) {
        $row = $y * $w;
        $last = -$radius - 2;
        for ($x = 0; $x < $w; $x++) {
            $idx = $row + $x;
            if ($seed[$idx] !== "\0") {
                $last = $x;
            }
            if (($x - $last) <= $radius) {
                $hmask[$idx] = "\1";
            }
        }

        $last = $w + $radius + 2;
        for ($x = $w - 1; $x >= 0; $x--) {
            $idx = $row + $x;
            if ($seed[$idx] !== "\0") {
                $last = $x;
            }
            if (($last - $x) <= $radius) {
                $hmask[$idx] = "\1";
            }
        }
    }

    $out = str_repeat("\0", $size);
    for ($x = 0; $x < $w; $x++) {
        $last = -$radius - 2;
        for ($y = 0; $y < $h; $y++) {
            $idx = ($y * $w) + $x;
            if ($hmask[$idx] !== "\0") {
                $last = $y;
            }
            if (($y - $last) <= $radius) {
                $out[$idx] = "\1";
            }
        }

        $last = $h + $radius + 2;
        for ($y = $h - 1; $y >= 0; $y--) {
            $idx = ($y * $w) + $x;
            if ($hmask[$idx] !== "\0") {
                $last = $y;
            }
            if (($last - $y) <= $radius) {
                $out[$idx] = "\1";
            }
        }
    }

    return $out;
}

function supplier_products_db_white_bg_watermark_edge_background_mask(
    GdImage $canvas,
    string $protectMask,
    int $w,
    int $h,
    int $lumaMin,
    int $distWhiteMax,
    int $spreadMax,
    array $profile = []
): array {
    $w = max(1, $w);
    $h = max(1, $h);
    $size = $w * $h;
    if ($size <= 0 || strlen($protectMask) < $size) {
        return [
            'mask' => str_repeat("\0", max(1, $size)),
            'pixels' => 0,
            'seed_pixels' => 0,
            'ratio' => 0.0,
            'mode' => 'edge_connected_background',
        ];
    }

    $edgeLumaMin = max(182, min(238, (int)($profile['edge_background_luma_min'] ?? min($lumaMin, 206))));
    $edgeChannelMin = max(142, min(235, (int)($profile['edge_background_channel_min'] ?? 152)));
    $edgeDistWhiteMax = max($distWhiteMax, (int)($profile['edge_background_dist_white_max'] ?? min(142, $distWhiteMax + 34)));
    $edgeDistWhiteMax = min(175, max(20, $edgeDistWhiteMax));
    $edgeSpreadMax = min(100, max($spreadMax, (int)($profile['edge_background_spread_max'] ?? ($spreadMax + 18))));
    $localEdgeMax = max(24, min(130, (int)($profile['edge_background_local_edge_max'] ?? 78)));
    $neighborDistanceMax = max(70, min(210, (int)($profile['edge_background_neighbor_distance_max'] ?? 158)));

    $rMap = str_repeat("\0", $size);
    $gMap = str_repeat("\0", $size);
    $bMap = str_repeat("\0", $size);
    $lumaMap = str_repeat("\0", $size);
    $preAllowed = str_repeat("\0", $size);

    for ($y = 0; $y < $h; $y++) {
        $row = $y * $w;
        for ($x = 0; $x < $w; $x++) {
            $idx = $row + $x;
            $rgb = imagecolorat($canvas, $x, $y);
            $r = ($rgb >> 16) & 0xFF;
            $g = ($rgb >> 8) & 0xFF;
            $b = $rgb & 0xFF;
            $max = max($r, $g, $b);
            $min = min($r, $g, $b);
            $spread = $max - $min;
            $luma = (int)round((0.2126 * $r) + (0.7152 * $g) + (0.0722 * $b));
            $distWhite = max(255 - $r, 255 - $g, 255 - $b);

            $rMap[$idx] = chr($r);
            $gMap[$idx] = chr($g);
            $bMap[$idx] = chr($b);
            $lumaMap[$idx] = chr($luma);

            if ($protectMask[$idx] === "\0"
                && $luma >= $edgeLumaMin
                && $min >= $edgeChannelMin
                && $distWhite <= $edgeDistWhiteMax
                && $spread <= $edgeSpreadMax
            ) {
                $preAllowed[$idx] = "\1";
            }
        }
    }

    $allowed = str_repeat("\0", $size);
    for ($y = 0; $y < $h; $y++) {
        $row = $y * $w;
        for ($x = 0; $x < $w; $x++) {
            $idx = $row + $x;
            if ($preAllowed[$idx] === "\0") {
                continue;
            }
            $luma = ord($lumaMap[$idx]);
            $localEdge = 0;
            if ($x > 0) {
                $localEdge = max($localEdge, abs($luma - ord($lumaMap[$idx - 1])));
            }
            if ($x < $w - 1) {
                $localEdge = max($localEdge, abs($luma - ord($lumaMap[$idx + 1])));
            }
            if ($y > 0) {
                $localEdge = max($localEdge, abs($luma - ord($lumaMap[$idx - $w])));
            }
            if ($y < $h - 1) {
                $localEdge = max($localEdge, abs($luma - ord($lumaMap[$idx + $w])));
            }
            if ($localEdge <= $localEdgeMax || $luma >= 248) {
                $allowed[$idx] = "\1";
            }
        }
    }
    unset($preAllowed);

    $canFlow = static function (int $fromIdx, int $toIdx) use (
        $rMap,
        $gMap,
        $bMap,
        $lumaMap,
        $edgeSpreadMax,
        $neighborDistanceMax
    ): bool {
        $r = ord($rMap[$toIdx]);
        $g = ord($gMap[$toIdx]);
        $b = ord($bMap[$toIdx]);
        $fr = ord($rMap[$fromIdx]);
        $fg = ord($gMap[$fromIdx]);
        $fb = ord($bMap[$fromIdx]);
        $distance = abs($r - $fr) + abs($g - $fg) + abs($b - $fb);
        if ($distance <= $neighborDistanceMax) {
            return true;
        }

        $luma = ord($lumaMap[$toIdx]);
        $fromLuma = ord($lumaMap[$fromIdx]);
        $max = max($r, $g, $b);
        $min = min($r, $g, $b);
        return $luma >= 204
            && $fromLuma >= 204
            && abs($luma - $fromLuma) <= 58
            && ($max - $min) <= $edgeSpreadMax;
    };

    $mask = str_repeat("\0", $size);
    $queue = [];
    $seedPixels = 0;
    $pushSeed = static function (int $x, int $y) use (
        &$mask,
        &$queue,
        &$seedPixels,
        $w,
        $allowed
    ): void {
        $idx = ($y * $w) + $x;
        if ($mask[$idx] !== "\0") {
            return;
        }
        if ($allowed[$idx] === "\0") {
            return;
        }
        $mask[$idx] = "\1";
        $queue[] = $idx;
        $seedPixels++;
    };

    for ($x = 0; $x < $w; $x++) {
        $pushSeed($x, 0);
        $pushSeed($x, $h - 1);
    }
    for ($y = 1; $y < $h - 1; $y++) {
        $pushSeed(0, $y);
        $pushSeed($w - 1, $y);
    }

    $head = 0;
    $pixels = 0;
    while ($head < count($queue)) {
        $idx = (int)$queue[$head++];
        $pixels++;
        $x = $idx % $w;
        $y = intdiv($idx, $w);

        if ($x > 0) {
            $nidx = $idx - 1;
            if ($mask[$nidx] === "\0" && $allowed[$nidx] !== "\0" && $canFlow($idx, $nidx)) {
                $mask[$nidx] = "\1";
                $queue[] = $nidx;
            }
        }
        if ($x < $w - 1) {
            $nidx = $idx + 1;
            if ($mask[$nidx] === "\0" && $allowed[$nidx] !== "\0" && $canFlow($idx, $nidx)) {
                $mask[$nidx] = "\1";
                $queue[] = $nidx;
            }
        }
        if ($y > 0) {
            $nidx = $idx - $w;
            if ($mask[$nidx] === "\0" && $allowed[$nidx] !== "\0" && $canFlow($idx, $nidx)) {
                $mask[$nidx] = "\1";
                $queue[] = $nidx;
            }
        }
        if ($y < $h - 1) {
            $nidx = $idx + $w;
            if ($mask[$nidx] === "\0" && $allowed[$nidx] !== "\0" && $canFlow($idx, $nidx)) {
                $mask[$nidx] = "\1";
                $queue[] = $nidx;
            }
        }
    }

    return [
        'mask' => $mask,
        'pixels' => $pixels,
        'seed_pixels' => $seedPixels,
        'ratio' => round($pixels / max(1, $size), 6),
        'mode' => 'edge_connected_background',
        'thresholds' => [
            'luma_min' => $edgeLumaMin,
            'channel_min' => $edgeChannelMin,
            'dist_white_max' => $edgeDistWhiteMax,
            'spread_max' => $edgeSpreadMax,
            'local_edge_max' => $localEdgeMax,
            'neighbor_distance_max' => $neighborDistanceMax,
        ],
    ];
}

function supplier_products_db_white_bg_watermark_attenuate_surface(
    GdImage $canvas,
    string $protectMask,
    int $w,
    int $h,
    array $profile
): array {
    if (empty($profile['surface_cleanup'])) {
        return [
            'enabled' => false,
            'candidate_pixels' => 0,
            'changed_pixels' => 0,
            'changed_ratio' => 0.0,
            'skipped_reason' => '',
        ];
    }

    $size = max(1, $w * $h);
    if (strlen($protectMask) < $size || $w < 24 || $h < 24) {
        return [
            'enabled' => true,
            'candidate_pixels' => 0,
            'changed_pixels' => 0,
            'changed_ratio' => 0.0,
            'skipped_reason' => 'image_or_mask_too_small',
        ];
    }

    $source = imagecreatetruecolor($w, $h);
    $work = imagecreatetruecolor($w, $h);
    if (!$source instanceof GdImage || !$work instanceof GdImage) {
        return [
            'enabled' => true,
            'candidate_pixels' => 0,
            'changed_pixels' => 0,
            'changed_ratio' => 0.0,
            'skipped_reason' => 'canvas_alloc_failed',
        ];
    }
    imagecopy($source, $canvas, 0, 0, 0, 0, $w, $h);
    imagecopy($work, $canvas, 0, 0, 0, 0, $w, $h);

    $lumaMin = max(0, min(255, (int)($profile['surface_luma_min'] ?? 22)));
    $lumaMax = max($lumaMin + 1, min(235, (int)($profile['surface_luma_max'] ?? 168)));
    $spreadMax = max(4, min(80, (int)($profile['surface_spread_max'] ?? 34)));
    $contrastMin = max(2, min(40, (int)($profile['surface_contrast_min'] ?? 6)));
    $contrastMax = max($contrastMin + 1, min(100, (int)($profile['surface_contrast_max'] ?? 54)));
    $edgeMax = max(6, min(100, (int)($profile['surface_edge_max'] ?? 38)));
    $strength = max(0.10, min(0.90, (float)($profile['surface_strength'] ?? 0.58)));
    $maxChangedRatio = max(0.001, min(0.20, (float)($profile['surface_max_changed_ratio'] ?? 0.04)));
    $r1 = max(4, min(18, (int)($profile['surface_sample_radius'] ?? round(min($w, $h) * 0.007))));
    $r2 = min(28, max($r1 + 2, $r1 * 2));

    $lumaOf = static function (int $rgb): int {
        $r = ($rgb >> 16) & 0xFF;
        $g = ($rgb >> 8) & 0xFF;
        $b = $rgb & 0xFF;
        return (int)round((0.2126 * $r) + (0.7152 * $g) + (0.0722 * $b));
    };
    $sampleOffsets = [
        [-$r1, 0], [$r1, 0], [0, -$r1], [0, $r1],
        [-$r1, -$r1], [$r1, -$r1], [-$r1, $r1], [$r1, $r1],
        [-$r2, 0], [$r2, 0], [0, -$r2], [0, $r2],
        [-$r2, -$r1], [$r2, -$r1], [-$r2, $r1], [$r2, $r1],
        [-$r1, -$r2], [$r1, -$r2], [-$r1, $r2], [$r1, $r2],
    ];

    $candidatePixels = 0;
    $changedPixels = 0;
    $start = $r2 + 1;
    $endY = $h - $r2 - 1;
    $endX = $w - $r2 - 1;
    for ($y = $start; $y < $endY; $y++) {
        $row = $y * $w;
        for ($x = $start; $x < $endX; $x++) {
            $idx = $row + $x;
            if ($protectMask[$idx] === "\0") {
                continue;
            }

            $rgb = imagecolorat($source, $x, $y);
            $r = ($rgb >> 16) & 0xFF;
            $g = ($rgb >> 8) & 0xFF;
            $b = $rgb & 0xFF;
            $max = max($r, $g, $b);
            $min = min($r, $g, $b);
            $spread = $max - $min;
            $luma = (int)round((0.2126 * $r) + (0.7152 * $g) + (0.0722 * $b));

            if ($luma < $lumaMin || $luma > $lumaMax || $spread > $spreadMax) {
                continue;
            }
            if ($spread > max(14, (int)round($luma * 0.42))) {
                continue;
            }

            $edge = 0;
            $edge = max($edge, abs($luma - $lumaOf(imagecolorat($source, $x - 1, $y))));
            $edge = max($edge, abs($luma - $lumaOf(imagecolorat($source, $x + 1, $y))));
            $edge = max($edge, abs($luma - $lumaOf(imagecolorat($source, $x, $y - 1))));
            $edge = max($edge, abs($luma - $lumaOf(imagecolorat($source, $x, $y + 1))));
            if ($edge > $edgeMax) {
                continue;
            }

            $samples = [];
            foreach ($sampleOffsets as $off) {
                $sx = $x + (int)$off[0];
                $sy = $y + (int)$off[1];
                if ($sx < 0 || $sx >= $w || $sy < 0 || $sy >= $h) {
                    continue;
                }
                $sidx = ($sy * $w) + $sx;
                if ($protectMask[$sidx] === "\0") {
                    continue;
                }
                $srgb = imagecolorat($source, $sx, $sy);
                $sr = ($srgb >> 16) & 0xFF;
                $sg = ($srgb >> 8) & 0xFF;
                $sb = $srgb & 0xFF;
                $smax = max($sr, $sg, $sb);
                $smin = min($sr, $sg, $sb);
                $sspread = $smax - $smin;
                $sluma = (int)round((0.2126 * $sr) + (0.7152 * $sg) + (0.0722 * $sb));
                if ($sspread > ($spreadMax + 14) || $sluma > ($lumaMax + 32)) {
                    continue;
                }
                $samples[] = ['l' => $sluma, 'r' => $sr, 'g' => $sg, 'b' => $sb];
            }
            if (count($samples) < 8) {
                continue;
            }

            usort($samples, static fn(array $a, array $b): int => (int)$a['l'] <=> (int)$b['l']);
            $refIdx = max(0, min(count($samples) - 1, (int)floor((count($samples) - 1) * 0.34)));
            $refLuma = (int)$samples[$refIdx]['l'];
            $contrast = $luma - $refLuma;
            if ($contrast < $contrastMin || $contrast > $contrastMax) {
                continue;
            }

            $target = [];
            foreach ($samples as $sample) {
                if ((int)$sample['l'] <= $refLuma + 8) {
                    $target[] = $sample;
                }
            }
            if (count($target) < 3) {
                $target = array_slice($samples, 0, min(5, count($samples)));
            }

            $tr = 0;
            $tg = 0;
            $tb = 0;
            foreach ($target as $sample) {
                $tr += (int)$sample['r'];
                $tg += (int)$sample['g'];
                $tb += (int)$sample['b'];
            }
            $tc = max(1, count($target));
            $tr = (int)round($tr / $tc);
            $tg = (int)round($tg / $tc);
            $tb = (int)round($tb / $tc);

            $localStrength = $strength;
            if ($contrast < 12) {
                $localStrength *= 0.58;
            } elseif ($contrast > 32) {
                $localStrength *= 0.82;
            }

            $nr = max(0, min(255, (int)round($r + (($tr - $r) * $localStrength))));
            $ng = max(0, min(255, (int)round($g + (($tg - $g) * $localStrength))));
            $nb = max(0, min(255, (int)round($b + (($tb - $b) * $localStrength))));

            if (abs($nr - $r) + abs($ng - $g) + abs($nb - $b) <= 3) {
                continue;
            }

            $candidatePixels++;
            imagesetpixel($work, $x, $y, ($nr << 16) | ($ng << 8) | $nb);
            $changedPixels++;
        }
    }

    $changedRatio = $changedPixels / $size;
    $skippedReason = '';
    if ($changedPixels > 0 && $changedRatio <= $maxChangedRatio) {
        imagecopy($canvas, $work, 0, 0, 0, 0, $w, $h);
    } elseif ($changedPixels > 0) {
        $skippedReason = 'surface_changed_ratio_limit';
        $changedPixels = 0;
        $changedRatio = 0.0;
    }

    imagedestroy($source);
    imagedestroy($work);

    return [
        'enabled' => true,
        'candidate_pixels' => $candidatePixels,
        'changed_pixels' => $changedPixels,
        'changed_ratio' => round($changedRatio, 6),
        'skipped_reason' => $skippedReason,
        'sample_radius' => $r1,
        'max_changed_ratio' => $maxChangedRatio,
    ];
}

function supplier_products_db_white_bg_watermark_supplier_profile(int $supplierId, array $products, array $cfg = []): array
{
    $supplier = suppliers_get($supplierId, $cfg) ?: [];
    $name = mb_strtolower(trim((string)($supplier['name'] ?? '')), 'UTF-8');
    $code = mb_strtolower(trim((string)($supplier['supplier_code'] ?? '')), 'UTF-8');
    $haystack = $name . ' ' . $code;

    $profile = [
        'code' => 'generic_light_gray_background_watermark',
        'label' => 'светло-серый повторяющийся знак на белом фоне',
        'supplier_name' => (string)($supplier['name'] ?? ''),
        'supplier_code' => (string)($supplier['supplier_code'] ?? ''),
        'background_only' => true,
        'luma_min_floor' => 198,
        'dist_white_min' => 5,
        'dist_white_max' => 95,
        'spread_max' => 54,
        'product_seed_luma_max' => 184,
        'bbox_pad_ratio' => 0.020,
        'max_changed_ratio' => 0.18,
        'surface_cleanup' => false,
    ];

    if (preg_match('~master\s*mobile|mastermobile|мастер\s*мобайл~iu', $haystack)) {
        $profile['code'] = 'master_mobile_diagonal_watermark';
        $profile['label'] = 'MASTER MOBILE: диагональный светло-серый текст и логотип';
        $profile['luma_min_floor'] = 190;
        $profile['dist_white_min'] = 2;
        $profile['dist_white_max'] = 105;
        $profile['spread_max'] = 58;
        $profile['product_seed_luma_max'] = 178;
        $profile['bbox_pad_ratio'] = 0.024;
        $profile['max_changed_ratio'] = 0.22;
        $profile['surface_cleanup'] = false;
        $profile['surface_cleanup_reason'] = 'disabled_for_product_safety_edge_background_only';
        $profile['surface_luma_min'] = 18;
        $profile['surface_luma_max'] = 172;
        $profile['surface_spread_max'] = 34;
        $profile['surface_contrast_min'] = 5;
        $profile['surface_contrast_max'] = 58;
        $profile['surface_edge_max'] = 34;
        $profile['surface_strength'] = 0.56;
        $profile['surface_sample_radius'] = 8;
        $profile['surface_max_changed_ratio'] = 0.045;
    }

    return $profile;
}

function supplier_products_db_white_bg_watermark_clean_image(string $url, array $cfg, int $protectRadius, int $lumaMin, int $jpegQuality, array $profile = []): array
{
    if (!extension_loaded('gd')) {
        throw new RuntimeException('Для локальной очистки белого фона требуется PHP GD.');
    }

    $loaded = supplier_products_db_photo_collage_load_source($url, $cfg);
    $src = $loaded['image'] ?? null;
    if (!$src instanceof GdImage) {
        throw new RuntimeException('Не удалось открыть исходное изображение.');
    }

    try {
        if (!imageistruecolor($src)) {
            imagepalettetotruecolor($src);
        }
        $w = max(1, imagesx($src));
        $h = max(1, imagesy($src));
        $size = $w * $h;
        $protectRadius = $protectRadius > 0 ? $protectRadius : max(8, (int)round(min($w, $h) * 0.010));
        $protectRadius = min(36, max(4, $protectRadius));
        $profileLumaFloor = (int)($profile['luma_min_floor'] ?? 198);
        $lumaMin = min(245, max($profileLumaFloor, $lumaMin));
        $jpegQuality = min(100, max(1, $jpegQuality));
        $distWhiteMin = max(0, (int)($profile['dist_white_min'] ?? 5));
        $distWhiteMax = min(180, max($distWhiteMin + 1, (int)($profile['dist_white_max'] ?? 95)));
        $spreadMax = min(120, max(8, (int)($profile['spread_max'] ?? 54)));
        $productSeedLumaMax = min(220, max(120, (int)($profile['product_seed_luma_max'] ?? 184)));
        $maxChangedRatio = max(0.01, min(0.65, (float)($profile['max_changed_ratio'] ?? 0.18)));

        $canvas = imagecreatetruecolor($w, $h);
        if (!$canvas instanceof GdImage) {
            throw new RuntimeException('Не удалось создать холст для очистки фона.');
        }
        imagealphablending($canvas, true);
        imagesavealpha($canvas, false);
        $white = imagecolorallocate($canvas, 255, 255, 255);
        imagefilledrectangle($canvas, 0, 0, $w, $h, $white);
        imagecopy($canvas, $src, 0, 0, 0, 0, $w, $h);

        $seed = str_repeat("\0", $size);
        $seedPixels = 0;
        $minX = $w;
        $minY = $h;
        $maxX = -1;
        $maxY = -1;

        for ($y = 0; $y < $h; $y++) {
            $row = $y * $w;
            for ($x = 0; $x < $w; $x++) {
                $rgb = imagecolorat($canvas, $x, $y);
                $r = ($rgb >> 16) & 0xFF;
                $g = ($rgb >> 8) & 0xFF;
                $b = $rgb & 0xFF;
                $max = max($r, $g, $b);
                $min = min($r, $g, $b);
                $spread = $max - $min;
                $luma = (int)round((0.2126 * $r) + (0.7152 * $g) + (0.0722 * $b));
                $distWhite = max(255 - $r, 255 - $g, 255 - $b);

                $isProductSeed = $luma < $productSeedLumaMax
                    || $min < 155
                    || ($spread > 44 && $distWhite > 28 && $luma < 248)
                    || ($spread > 24 && $min < 200 && $distWhite > 40);
                if (!$isProductSeed) {
                    continue;
                }

                $idx = $row + $x;
                $seed[$idx] = "\1";
                $seedPixels++;
                if ($x < $minX) $minX = $x;
                if ($x > $maxX) $maxX = $x;
                if ($y < $minY) $minY = $y;
                if ($y > $maxY) $maxY = $y;
            }
        }

        $protect = supplier_products_db_white_bg_watermark_dilate_mask($seed, $w, $h, $protectRadius);
        unset($seed);

        $bboxPadRatio = max(0.0, min(0.08, (float)($profile['bbox_pad_ratio'] ?? 0.02)));
        $bboxPad = max(20, $protectRadius * 2, (int)round(min($w, $h) * $bboxPadRatio));
        $bboxUsable = false;
        if ($seedPixels > 0) {
            $minX = max(0, $minX - $bboxPad);
            $minY = max(0, $minY - $bboxPad);
            $maxX = min($w - 1, $maxX + $bboxPad);
            $maxY = min($h - 1, $maxY + $bboxPad);
            $bboxArea = max(0, ($maxX - $minX + 1) * ($maxY - $minY + 1));
            $bboxUsable = $seedPixels >= max(40, (int)round($size * 0.00008))
                && $bboxArea > 0
                && ($bboxArea / max(1, $size)) <= 0.96;
        }

        $edgeBackgroundMeta = supplier_products_db_white_bg_watermark_edge_background_mask(
            $canvas,
            $protect,
            $w,
            $h,
            $lumaMin,
            $distWhiteMax,
            $spreadMax,
            $profile
        );
        $edgeBackground = (string)($edgeBackgroundMeta['mask'] ?? str_repeat("\0", $size));
        unset($edgeBackgroundMeta['mask']);

        $changedPixels = 0;
        $candidatePixels = 0;
        $protectedPixels = 0;
        $bboxProtectedPixels = 0;
        $edgeBackgroundProtectedPixels = 0;
        for ($y = 0; $y < $h; $y++) {
            $row = $y * $w;
            for ($x = 0; $x < $w; $x++) {
                $idx = $row + $x;
                if ($protect[$idx] !== "\0") {
                    $protectedPixels++;
                    continue;
                }
                if ($edgeBackground[$idx] === "\0") {
                    $edgeBackgroundProtectedPixels++;
                    continue;
                }

                $rgb = imagecolorat($canvas, $x, $y);
                $r = ($rgb >> 16) & 0xFF;
                $g = ($rgb >> 8) & 0xFF;
                $b = $rgb & 0xFF;
                $max = max($r, $g, $b);
                $min = min($r, $g, $b);
                $spread = $max - $min;
                $luma = (int)round((0.2126 * $r) + (0.7152 * $g) + (0.0722 * $b));
                $distWhite = max(255 - $r, 255 - $g, 255 - $b);

                if ($bboxUsable && $x >= $minX && $x <= $maxX && $y >= $minY && $y <= $maxY) {
                    $bboxProtectedPixels++;
                    continue;
                }

                if ($luma < $lumaMin || $min < 166) {
                    continue;
                }
                if ($distWhite < $distWhiteMin || $distWhite > $distWhiteMax) {
                    continue;
                }
                if ($spread > $spreadMax) {
                    continue;
                }
                if ($luma < 220 && $spread > 22) {
                    continue;
                }

                $candidatePixels++;
                if ($luma >= 206 && $spread <= $spreadMax) {
                    $nr = 255;
                    $ng = 255;
                    $nb = 255;
                } else {
                    $strength = 0.94;
                    $nr = min(255, (int)round($r + ((255 - $r) * $strength)));
                    $ng = min(255, (int)round($g + ((255 - $g) * $strength)));
                    $nb = min(255, (int)round($b + ((255 - $b) * $strength)));
                }

                if (abs($nr - $r) + abs($ng - $g) + abs($nb - $b) <= 2) {
                    continue;
                }

                imagesetpixel($canvas, $x, $y, ($nr << 16) | ($ng << 8) | $nb);
                $changedPixels++;
            }
        }

        $changedRatio = $size > 0 ? ($changedPixels / $size) : 0.0;
        if ($changedPixels > 0 && $changedRatio > $maxChangedRatio) {
            throw new RuntimeException(
                'Защита товара остановила очистку: слишком большая зона изменений '
                . round($changedRatio * 100, 2) . '% при лимите '
                . round($maxChangedRatio * 100, 2) . '%.'
            );
        }

        $surfaceMeta = supplier_products_db_white_bg_watermark_attenuate_surface($canvas, $protect, $w, $h, $profile);
        $surfaceChangedPixels = (int)($surfaceMeta['changed_pixels'] ?? 0);
        $totalChangedPixels = $changedPixels + $surfaceChangedPixels;
        $totalChangedRatio = $size > 0 ? ($totalChangedPixels / $size) : 0.0;
        unset($protect);
        unset($edgeBackground);

        imageinterlace($canvas, true);
        ob_start();
        $ok = imagejpeg($canvas, null, $jpegQuality);
        $bytes = ob_get_clean();
        unset($canvas);
        if (!$ok || !is_string($bytes) || $bytes === '') {
            throw new RuntimeException('Не удалось сохранить очищенное изображение.');
        }

        return [
            'bytes' => $bytes,
            'meta' => [
                'format' => 'jpeg',
                'width' => $w,
                'height' => $h,
                'jpeg_quality' => $jpegQuality,
                'protect_radius' => $protectRadius,
                'luma_min' => $lumaMin,
                'watermark_profile' => (string)($profile['code'] ?? 'generic_light_gray_background_watermark'),
                'watermark_label' => (string)($profile['label'] ?? ''),
                'seed_pixels' => $seedPixels,
                'protected_pixels' => $protectedPixels,
                'bbox_protected_pixels' => $bboxProtectedPixels,
                'edge_background_protected_pixels' => $edgeBackgroundProtectedPixels,
                'edge_background_pixels' => (int)($edgeBackgroundMeta['pixels'] ?? 0),
                'edge_background_seed_pixels' => (int)($edgeBackgroundMeta['seed_pixels'] ?? 0),
                'edge_background_ratio' => (float)($edgeBackgroundMeta['ratio'] ?? 0.0),
                'edge_background_mode' => (string)($edgeBackgroundMeta['mode'] ?? 'edge_connected_background'),
                'edge_background_thresholds' => (array)($edgeBackgroundMeta['thresholds'] ?? []),
                'candidate_pixels' => $candidatePixels,
                'changed_pixels' => $changedPixels,
                'changed_ratio' => round($changedRatio, 6),
                'surface_candidate_pixels' => (int)($surfaceMeta['candidate_pixels'] ?? 0),
                'surface_changed_pixels' => $surfaceChangedPixels,
                'surface_changed_ratio' => (float)($surfaceMeta['changed_ratio'] ?? 0.0),
                'surface_cleanup' => $surfaceMeta,
                'total_changed_pixels' => $totalChangedPixels,
                'total_changed_ratio' => round($totalChangedRatio, 6),
                'max_changed_ratio' => $maxChangedRatio,
                'product_bbox' => $bboxUsable ? [
                    'x1' => $minX,
                    'y1' => $minY,
                    'x2' => $maxX,
                    'y2' => $maxY,
                ] : null,
                'mode' => 'supplier_profile_edge_connected_background_watermark_cleanup',
            ],
        ];
    } finally {
        unset($src);
    }
}

function supplier_products_db_white_bg_watermark_save_image(int $supplierId, int $productId, int $photoIndex, string $bytes, array $cfg): string
{
    $info = @getimagesizefromstring($bytes);
    if (!is_array($info)) {
        throw new RuntimeException('Не удалось распознать очищенное изображение.');
    }

    $baseDir = supplier_products_image_storage_dir($cfg);
    $relativeDir = 'supplier_' . $supplierId . '/' . date('Ym') . '/white_bg_watermark_clean';
    $dir = supplier_products_ensure_writable_dir($baseDir . '/' . $relativeDir, 'Не удалось создать папку для локально очищенных фото.');
    $fileName = 'product_' . $productId . '_photo_' . ($photoIndex + 1) . '_white_bg_clean_' . date('Ymd_His') . '_' . bin2hex(random_bytes(5)) . '.jpg';
    $path = $dir . '/' . $fileName;
    if (file_put_contents($path, $bytes) === false) {
        throw new RuntimeException('Не удалось сохранить локально очищенное фото.');
    }
    @chmod($path, 0664);

    return supplier_products_publish_stored_image($path, $relativeDir . '/' . $fileName, $cfg, true);
}

function supplier_products_db_op_remove_white_bg_watermarks(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $photosLimit = max(0, (int)trim((string)($params['photos_limit'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '1') !== '' && (string)($params['overwrite'] ?? '1') !== '0');
    $protectRadius = max(0, (int)trim((string)($params['protect_radius'] ?? '0')));
    $lumaMin = max(0, (int)trim((string)($params['luma_min'] ?? '198')));
    $jpegQuality = max(1, min(100, (int)trim((string)($params['jpeg_quality'] ?? '94'))));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/white_bg_watermark_clean');

    $products = supplier_products_db_load_products($supplierId, $params, $maxItems);
    $total = count($products);
    $supplierProfile = supplier_products_db_white_bg_watermark_supplier_profile($supplierId, $products, $cfg);
    $log("supplier_db remove_white_bg_watermarks: products={$total}, photos_limit={$photosLimit}, overwrite=" . ($overwrite ? '1' : '0') . ", protect_radius=" . ($protectRadius > 0 ? (string)$protectRadius : 'auto') . ", luma_min={$lumaMin}, jpeg_quality={$jpegQuality}, profile=" . (string)($supplierProfile['code'] ?? 'generic') . ", watermark=" . (string)($supplierProfile['label'] ?? '') . ", background=edge_connected, uses_gpt=0\n");
    ops_update_progress($opId, 0, max(1, $total), 'local_image', 'preparing photos');

    $changedProducts = [];
    $productsChanged = 0;
    $photosSeen = 0;
    $photosProcessed = 0;
    $photosUpdated = 0;
    $skippedNoPhotos = 0;
    $skippedGenerated = 0;
    $skippedAlreadyProcessed = 0;
    $skippedNoCandidates = 0;
    $errors = [];
    $results = [];
    $done = 0;

    foreach ($products as $product) {
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? $product['vendor_code'] ?? $productId));
        if ($productId <= 0) {
            continue;
        }

        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        if (!$pictures) {
            $skippedNoPhotos++;
            $done++;
            ops_update_progress($opId, $done, max(1, $total), 'local_image', "processed={$done}, updated={$photosUpdated}, errors=" . count($errors));
            continue;
        }

        $changed = false;
        $limit = $photosLimit > 0 ? min($photosLimit, count($pictures)) : count($pictures);
        $productResult = [
            'offer_id' => $offerId,
            'product_id' => $productId,
            'photos' => [],
        ];
        for ($i = 0; $i < $limit; $i++) {
            $url = trim((string)($pictures[$i] ?? ''));
            if ($url === '') {
                continue;
            }
            $photosSeen++;
            if (supplier_products_db_white_bg_watermark_picture_is_generated($url)) {
                $skippedGenerated++;
                continue;
            }
            if (!$overwrite && supplier_products_db_white_bg_watermark_picture_is_processed($url)) {
                $skippedAlreadyProcessed++;
                continue;
            }

            try {
                $created = supplier_products_db_white_bg_watermark_clean_image($url, $cfg, $protectRadius, $lumaMin, $jpegQuality, $supplierProfile);
                $meta = (array)($created['meta'] ?? []);
                $totalChangedPixels = (int)($meta['total_changed_pixels'] ?? ((int)($meta['changed_pixels'] ?? 0) + (int)($meta['surface_changed_pixels'] ?? 0)));
                if ($totalChangedPixels <= 0) {
                    $skippedNoCandidates++;
                    $productResult['photos'][] = [
                        'photo_index' => $i + 1,
                        'status' => 'skipped_no_watermark_candidates',
                        'source_url' => $url,
                        'meta' => $meta,
                    ];
                    continue;
                }
                $newUrl = supplier_products_db_white_bg_watermark_save_image($supplierId, $productId, $i, (string)($created['bytes'] ?? ''), $cfg);
                $pictures[$i] = $newUrl;
                $photosProcessed++;
                $photosUpdated++;
                $changed = true;
                $productResult['photos'][] = [
                    'photo_index' => $i + 1,
                    'status' => 'ok',
                    'source_url' => $url,
                    'new_url' => $newUrl,
                    'meta' => $meta,
                ];
            } catch (Throwable $e) {
                $errors[] = [
                    'offer_id' => $offerId,
                    'product_id' => $productId,
                    'photo_index' => $i + 1,
                    'message' => $e->getMessage(),
                ];
                $productResult['photos'][] = [
                    'photo_index' => $i + 1,
                    'status' => 'error',
                    'source_url' => $url,
                    'error' => $e->getMessage(),
                ];
                $log("[white-bg-clean] {$offerId} photo #" . ($i + 1) . ': ' . $e->getMessage() . "\n");
            }
        }

        if ($changed) {
            supplier_products_update_pictures($productId, $pictures, $cfg);
            $changedProducts[$productId] = true;
            $productsChanged++;
        }

        $results[$offerId !== '' ? $offerId : (string)$productId] = $productResult;
        file_put_contents(
            $outDir . '/white_bg_watermark_clean/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId !== '' ? $offerId : (string)$productId) . '.json',
            json_encode($productResult, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );

        $done++;
        ops_update_progress($opId, $done, max(1, $total), 'local_image', "processed={$done}, updated={$photosUpdated}, errors=" . count($errors));
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    ops_update_progress($opId, $total > 0 ? $done : 1, $total > 0 ? max(1, $total) : 1, 'done', 'white background watermark cleanup finished');

    $report = [
        'title' => 'remove_white_bg_watermarks',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $total,
            'products_touched' => count($changedProducts),
            'products_changed' => $productsChanged,
            'photos_seen' => $photosSeen,
            'photos_processed' => $photosProcessed,
            'photos_updated' => $photosUpdated,
            'skipped_no_photos' => $skippedNoPhotos,
            'skipped_generated' => $skippedGenerated,
            'skipped_already_processed' => $skippedAlreadyProcessed,
            'skipped_no_watermark_candidates' => $skippedNoCandidates,
            'errors' => count($errors),
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'cost' => 0.0,
            'cost_currency' => 'USD',
            'cost_label' => openai_format_cost(0.0, 'USD'),
            'cost_usd' => 0.0,
        ],
        'params_effective' => [
            'max_items' => (string)$maxItems,
            'photos_limit' => (string)$photosLimit,
            'overwrite' => $overwrite ? '1' : '0',
            'protect_radius' => $protectRadius > 0 ? (string)$protectRadius : 'auto',
            'luma_min' => (string)$lumaMin,
            'jpeg_quality' => (string)$jpegQuality,
            'watermark_profile' => (string)($supplierProfile['code'] ?? 'generic'),
            'watermark_label' => (string)($supplierProfile['label'] ?? ''),
            'uses_gpt' => '0',
        ],
        'errors_sample' => array_slice($errors, 0, 50),
        'results' => $results,
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'remove_white_bg_watermarks',
        'items' => [
            'Products touched: ' . count($changedProducts),
            'Photos processed: ' . $photosProcessed,
            'Photos updated: ' . $photosUpdated,
            'Skipped generated photos: ' . $skippedGenerated,
            'Skipped already processed: ' . $skippedAlreadyProcessed,
            'Skipped no watermark candidates: ' . $skippedNoCandidates,
            'Errors: ' . count($errors),
            'Cost: ' . openai_format_cost(0.0, 'USD'),
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_pixlab_remove_photo_watermarks(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $pixlab = is_array($cfg['pixlab'] ?? null) ? $cfg['pixlab'] : [];
    $apiKey = trim((string)($pixlab['api_key'] ?? ''));
    if ($apiKey === '') {
        throw new RuntimeException('PixLab API key не настроен. Добавь PIXLAB_API_KEY в env или app/config.local.php: pixlab/api_key.');
    }

    $endpoint = trim((string)($pixlab['txtremove_url'] ?? 'https://api.pixlab.io/txtremove'));
    if ($endpoint === '') {
        $endpoint = 'https://api.pixlab.io/txtremove';
    }
    $timeoutSec = max(20, (int)($pixlab['timeout_sec'] ?? 90));
    $maxBytes = max(1024 * 1024, (int)($pixlab['max_image_bytes'] ?? (10 * 1024 * 1024)));
    $requestsPerMinute = max(1, (int)($pixlab['txtremove_requests_per_minute'] ?? 7));
    $requestSpacingSec = 60.0 / $requestsPerMinute;
    $rateLimitRetryAfterSec = max(5, (int)($pixlab['rate_limit_retry_after_sec'] ?? 65));
    $maxRetries = max(0, (int)($pixlab['max_retries'] ?? 3));
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $photosLimit = max(0, (int)trim((string)($params['photos_limit'] ?? '0')));
    $forceProcessed = trim((string)($params['force_processed'] ?? '0')) === '1';

    $products = supplier_products_db_load_products($supplierId, $params, $maxItems);
    $total = count($products);
    $pricing = supplier_products_db_pixlab_cost_fields($pixlab, 1000);
    $log("supplier_db pixlab_remove_photo_watermarks: products={$total}, photos_limit={$photosLimit}, endpoint={$endpoint}, price_per_1000={$pricing['price_per_1000_label']}, txtremove_rpm={$requestsPerMinute}, retries={$maxRetries}\n");
    ops_update_progress($opId, 0, max(1, $total), 'pixlab', 'preparing photos');

    $pdo = db();
    $updProduct = $pdo->prepare("UPDATE feedtools_supplier_products SET pictures_json = ? WHERE id = ?");

    $changedProducts = [];
    $productsWithPhotos = 0;
    $productsChanged = 0;
    $photosSeen = 0;
    $pixlabRequests = 0;
    $photosProcessed = 0;
    $photosUpdated = 0;
    $skippedNoPhotos = 0;
    $skippedAlreadyProcessed = 0;
    $errors = [];
    $done = 0;
    $nextPixlabRequestAt = 0.0;
    $waitForPixlabSlot = static function (string $offerId, int $photoIndex) use (
        &$nextPixlabRequestAt,
        $requestSpacingSec,
        $opId,
        &$done,
        $total,
        &$photosUpdated,
        &$errors,
        $log
    ): void {
        $now = microtime(true);
        if ($nextPixlabRequestAt > $now) {
            $waitSec = max(1, (int)ceil($nextPixlabRequestAt - $now));
            ops_update_progress($opId, $done, max(1, $total), 'pixlab', "waiting {$waitSec}s for PixLab rate limit; updated={$photosUpdated}, errors=" . count($errors));
            $log("[pixlab] waiting {$waitSec}s before {$offerId} photo #{$photoIndex}\n");
            sleep($waitSec);
        }
        $nextPixlabRequestAt = microtime(true) + $requestSpacingSec;
    };

    foreach ($products as $product) {
        $productId = (int)($product['id'] ?? 0);
        $offerId = (string)($product['offer_id'] ?? $product['vendor_code'] ?? $productId);
        if ($productId <= 0) {
            continue;
        }

        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        if (!$pictures) {
            $skippedNoPhotos++;
            $done++;
            ops_update_progress($opId, $done, max(1, $total), 'pixlab', "processed={$done}, updated={$photosUpdated}, errors=" . count($errors));
            continue;
        }

        $productsWithPhotos++;
        $changed = false;
        $limit = $photosLimit > 0 ? min($photosLimit, count($pictures)) : count($pictures);
        for ($i = 0; $i < $limit; $i++) {
            $url = trim((string)($pictures[$i] ?? ''));
            if ($url === '') {
                continue;
            }
            $photosSeen++;
            if (!$forceProcessed && supplier_products_db_pixlab_photo_is_processed($url)) {
                $skippedAlreadyProcessed++;
                continue;
            }

            $source = null;
            try {
                $source = supplier_products_db_pixlab_source_file($url, $cfg, $maxBytes, $timeoutSec);
                $result = null;
                for ($attempt = 0; $attempt <= $maxRetries; $attempt++) {
                    $waitForPixlabSlot($offerId, $i + 1);
                    try {
                        $pixlabRequests++;
                        $result = supplier_products_db_pixlab_call_txtremove($endpoint, $apiKey, $source, $maxBytes, $timeoutSec);
                        break;
                    } catch (Throwable $e) {
                        if (!supplier_products_db_pixlab_is_rate_limit_error($e) || $attempt >= $maxRetries) {
                            throw $e;
                        }
                        $waitSec = $rateLimitRetryAfterSec;
                        $nextPixlabRequestAt = max($nextPixlabRequestAt, microtime(true) + $waitSec);
                        $log("[pixlab] {$offerId} photo #" . ($i + 1) . ": rate limit, retry " . ($attempt + 1) . '/' . $maxRetries . " after {$waitSec}s\n");
                    }
                }
                if (!is_array($result)) {
                    throw new RuntimeException('PixLab TXT-REMOVE не вернул результат.');
                }
                $newUrl = supplier_products_db_pixlab_save_image(
                    $supplierId,
                    $productId,
                    $i,
                    (string)$result['bytes'],
                    (string)$result['mime'],
                    (string)$result['ext'],
                    $cfg
                );
                $pictures[$i] = $newUrl;
                $photosProcessed++;
                $photosUpdated++;
                $changed = true;
            } catch (Throwable $e) {
                $errors[] = [
                    'offer_id' => $offerId,
                    'product_id' => $productId,
                    'photo_index' => $i + 1,
                    'message' => $e->getMessage(),
                ];
                $log("[pixlab] {$offerId} photo #" . ($i + 1) . ": " . $e->getMessage() . "\n");
            } finally {
                if (is_array($source) && !empty($source['cleanup'])) {
                    @unlink((string)$source['path']);
                }
            }
        }

        if ($changed) {
            $updProduct->execute([
                json_encode(supplier_products_normalize_picture_urls($pictures), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
                $productId,
            ]);
            supplier_products_sync_product_summary_from_db($productId, $cfg);
            $changedProducts[] = $productId;
            $productsChanged++;
        }

        $done++;
        ops_update_progress($opId, $done, max(1, $total), 'pixlab', "processed={$done}, updated={$photosUpdated}, errors=" . count($errors));
    }

    if ($changedProducts) {
        $dataset = supplier_products_update_dataset_row_from_db($supplierId, $cfg);
    } else {
        $dataset = supplier_products_db_finish_changed_products($supplierId, [], $cfg, $opId);
    }
    ops_update_progress($opId, $total, max(1, $total), 'done', 'PixLab TXT-REMOVE finished');
    $usage = supplier_products_db_pixlab_cost_fields($pixlab, $pixlabRequests);
    $log("PixLab usage: requests={$pixlabRequests}, cost={$usage['cost_label']} ({$usage['price_per_1000_label']} / 1000 requests)\n");

    $report = [
        'title' => 'pixlab_remove_photo_watermarks',
        'storage' => 'supplier_products_db',
        'items' => [
            'PixLab API requests: ' . $pixlabRequests,
            'PixLab cost: ' . $usage['cost_label'],
        ],
        'metrics' => [
            'api_requests' => $pixlabRequests,
            'pixlab_requests' => $pixlabRequests,
            'cost' => $usage['cost'],
            'cost_currency' => $usage['cost_currency'],
            'cost_label' => $usage['cost_label'],
            'cost_usd' => $usage['cost_usd'],
            'price_per_1000_requests' => $usage['price_per_1000_requests'],
            'price_per_1000_label' => $usage['price_per_1000_label'],
        ],
        'usage_total' => [
            'api_requests' => $pixlabRequests,
            'pixlab_requests' => $pixlabRequests,
            'cost' => $usage['cost'],
            'cost_currency' => $usage['cost_currency'],
            'cost_label' => $usage['cost_label'],
            'cost_usd' => $usage['cost_usd'],
            'price_per_1000_requests' => $usage['price_per_1000_requests'],
            'price_per_1000_label' => $usage['price_per_1000_label'],
        ],
        'total_cost' => $usage['cost'],
        'total_cost_currency' => $usage['cost_currency'],
        'total_cost_label' => $usage['cost_label'],
        'total_cost_usd' => $usage['cost_usd'],
        'summary' => [
            'products_scanned' => $total,
            'products_with_photos' => $productsWithPhotos,
            'products_changed' => $productsChanged,
            'photos_seen' => $photosSeen,
            'pixlab_requests' => $pixlabRequests,
            'photos_sent_to_pixlab' => $photosProcessed,
            'photos_updated' => $photosUpdated,
            'skipped_no_photos' => $skippedNoPhotos,
            'skipped_already_processed' => $skippedAlreadyProcessed,
            'errors' => count($errors),
            'photos_limit' => $photosLimit,
            'max_items' => $maxItems,
            'endpoint' => $endpoint,
            'cost' => $usage['cost'],
            'cost_currency' => $usage['cost_currency'],
            'cost_label' => $usage['cost_label'],
            'cost_usd' => $usage['cost_usd'],
            'price_per_1000_requests' => $usage['price_per_1000_requests'],
        ],
        'errors' => array_slice($errors, 0, 100),
        'dataset' => $dataset,
    ];

    return supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
}

function supplier_products_db_template_fixed_param_rules(string $source, bool $includeCountryDefault = false): array
{
    $source = $source === 'wb' ? 'wildberries' : trim($source);
    if ($source === 'ozon') {
        $rules = [
            ['names' => ['НДС, %'], 'value' => 'Не облагается', 'mode' => 'force'],
            ['names' => ['Рассрочка'], 'value' => 'Нет', 'mode' => 'force'],
            ['names' => ['Нужен код маркировки', 'Требуется код маркировки'], 'value' => 'Нет', 'mode' => 'force'],
            ['names' => ['Количество заводских упаковок'], 'value' => '1', 'mode' => 'force'],
            ['names' => ['Наличие серийного номера'], 'value' => 'Нет', 'mode' => 'force'],
            ['names' => ['Гарантия', 'Гарантийный срок', 'Срок гарантии'], 'value' => '2 года', 'mode' => 'force'],
            ['names' => ['Срок службы, лет'], 'value' => '10', 'mode' => 'force'],
            ['names' => ['Класс опасности товара'], 'value' => 'Не опасен', 'mode' => 'force', 'required_only' => true],
            ['names' => ['Срок годности в днях'], 'value' => '3650', 'mode' => 'force'],
            ['names' => ['Гарантия на товар, мес.'], 'value' => '24', 'mode' => 'force'],
            ['names' => ['Комплектация'], 'value' => 'Товар в фирменной упаковке', 'mode' => 'fill'],
            ['names' => ['Количество в упаковке, шт', 'Количество товара в УЕИ', 'количество_в_единице_товара'], 'value' => '1', 'mode' => 'fill'],
        ];
        if ($includeCountryDefault) {
            $rules[] = ['names' => ['Страна-изготовитель', 'Страна изготовитель', 'Страна производства', 'Страна-производитель'], 'value' => 'Россия', 'mode' => 'fill'];
        }
        return $rules;
    }
    if ($source === 'wildberries') {
        $rules = [
            ['names' => ['КИЗ'], 'value' => 'Не нужен', 'mode' => 'force'],
            ['names' => ['18+'], 'value' => 'Нет', 'mode' => 'force'],
            ['names' => ['Только для ИП и юрлиц'], 'value' => 'Нет', 'mode' => 'force'],
            ['names' => ['Минимальное количество штук в заказе'], 'value' => '1', 'mode' => 'force'],
            ['names' => ['Подтверждаю, что товар промаркирован'], 'value' => 'Нет', 'mode' => 'force'],
            ['names' => ['Ставка НДС'], 'value' => 'Без НДС', 'mode' => 'force'],
            ['names' => ['Гарантия', 'Гарантийный срок', 'Срок гарантии'], 'value' => '2 года', 'mode' => 'force'],
            ['names' => ['Количество штук в упаковке', 'количество_в_единице_товара'], 'value' => '1', 'mode' => 'fill'],
        ];
        if ($includeCountryDefault) {
            $rules[] = ['names' => ['Страна производства', 'Страна производитель', 'Страна-производитель', 'Страна-изготовитель'], 'value' => 'Россия', 'mode' => 'fill'];
        }
        return $rules;
    }
    return [];
}

function supplier_products_db_template_fixed_rows_for_context(string $source, array $context, array $existingValuesByNorm, bool $includeCountryDefault = false): array
{
    $source = $source === 'wb' ? 'wildberries' : trim($source);
    $kind = $source === 'wildberries' ? 'wb_param' : 'param';
    $rules = supplier_products_db_template_fixed_param_rules($source, $includeCountryDefault);
    if (!$rules) {
        return [];
    }

    $ruleByNorm = [];
    foreach ($rules as $rule) {
        $value = trim((string)($rule['value'] ?? ''));
        if ($value === '') {
            continue;
        }
        foreach ((array)($rule['names'] ?? []) as $name) {
            foreach (supplier_products_db_attr_candidate_keys((string)$name) as $candidateKey) {
                if ($candidateKey !== '') {
                    $ruleByNorm[$candidateKey] = $rule;
                }
            }
        }
    }
    if (!$ruleByNorm) {
        return [];
    }

    $rows = [];
    foreach ((array)($context['category_attributes'] ?? []) as $attr) {
        if (!is_array($attr)) {
            continue;
        }
        $attrName = trim((string)($attr['name'] ?? ''));
        $attrNorm = supplier_products_db_attr_norm($attrName);
        if ($attrName === '' || $attrNorm === '') {
            continue;
        }
        $rule = null;
        foreach (supplier_products_db_attr_candidate_keys($attrName) as $candidateKey) {
            if ($candidateKey !== '' && isset($ruleByNorm[$candidateKey])) {
                $rule = $ruleByNorm[$candidateKey];
                break;
            }
        }
        if (!is_array($rule)) {
            continue;
        }
        if (!empty($rule['required_only']) && empty($attr['required'])) {
            continue;
        }
        $mode = (string)($rule['mode'] ?? 'fill');
        $current = '';
        foreach (supplier_products_db_attr_candidate_keys($attrName) as $candidateKey) {
            $candidateValue = trim((string)($existingValuesByNorm[$kind][$candidateKey] ?? ''));
            if ($candidateValue !== '') {
                $current = $candidateValue;
                break;
            }
        }
        if ($mode !== 'force' && $current !== '') {
            continue;
        }
        $values = supplier_products_db_values_allowed_for_attr((string)($rule['value'] ?? ''), $attr);
        if (!$values) {
            continue;
        }
        $rows[$kind . "\n" . $attrNorm] = [
            'kind' => $kind,
            'name' => $attrName,
            'value' => (string)$values[0],
            'mode' => $mode,
        ];
    }
    return array_values($rows);
}

function supplier_products_db_gpt_offer_params_excluded_attr(string $name): bool
{
    return in_array(supplier_products_db_attr_norm($name), [
        'гарантия',
        'гарантийный срок',
        'срок гарантии',
        'страна производства',
        'страна производитель',
        'страна изготовитель',
        'страна происхождения',
        'тн вэд',
        'тнвэд',
        'тн вэд коды еаэс',
        'код тн вэд',
        'коды тн вэд',
        'tn ved',
        'tnved',
        'tnved code',
    ], true);
}

function supplier_products_db_op_normalize_param_values(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $rows = db()->query("SELECT attr_name, old_value, new_value FROM feedtools_param_value_map WHERE is_active=1")->fetchAll(PDO::FETCH_ASSOC) ?: [];
    $norm = static function (string $s): string {
        $s = trim($s);
        $s = preg_replace('/\s+/u', ' ', $s);
        return mb_strtolower((string)$s, 'UTF-8');
    };
    $normKey = static function (string $s): string {
        $s = mb_strtolower(trim($s), 'UTF-8');
        return preg_replace('/[^0-9a-zа-я]+/ui', '', $s) ?? '';
    };
    $compatibilityAttrKeys = [
        supplier_products_db_attr_norm('Совместимость') => true,
        supplier_products_db_attr_norm('compatibility') => true,
    ];
    $isCompatibilityAttr = static function (string $fieldNormKey, string $attrNorm) use ($compatibilityAttrKeys, $norm): bool {
        return ($fieldNormKey !== '' && isset($compatibilityAttrKeys[$fieldNormKey]))
            || $attrNorm === $norm('Совместимость')
            || $attrNorm === $norm('compatibility');
    };
    $limitCompatibilityValue = static function (string $value, int $limit = 100): string {
        $value = trim((string)preg_replace('/\s+/u', ' ', $value));
        if ($value === '' || mb_strlen($value, 'UTF-8') <= $limit) {
            return $value;
        }

        $cut = mb_substr($value, 0, $limit, 'UTF-8');
        $wordCut = preg_replace('/\s+\S*$/u', '', $cut);
        if (is_string($wordCut) && mb_strlen($wordCut, 'UTF-8') >= 70) {
            $cut = $wordCut;
        }

        $cut = rtrim($cut, " \t\n\r\0\x0B,;./\\|-");
        if ($cut === '') {
            $cut = mb_substr($value, 0, $limit, 'UTF-8');
        }
        return $cut;
    };
    $map = [];
    foreach ($rows as $row) {
        $attr = $norm((string)($row['attr_name'] ?? ''));
        $old = $norm((string)($row['old_value'] ?? ''));
        $new = trim((string)($row['new_value'] ?? ''));
        if ($attr !== '' && $old !== '' && $new !== '') {
            $map[$attr][$old] = $new;
        }
    }
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $products = supplier_products_db_load_products($supplierId, $params, $maxItems);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    $total = count($products);
    $log("supplier_db normalize_param_values: rules=" . count($rows) . ", products={$total}\n");
    ops_update_progress($opId, 0, max(1, $total), 'db', 'normalizing params');

    $pdo = db();
    $updField = $pdo->prepare("UPDATE feedtools_supplier_product_fields SET field_value = ? WHERE id = ?");

    $changedProducts = [];
    $replacedCount = 0;
    $replacedByElement = ['param' => 0, 'wb_param' => 0];
    $replacedByAttr = [];
    $fixedWeight = 0;
    $fixedDimensions = 0;
    $hashtagsChanged = 0;
    $fixedMarketplaceValues = 0;
    $fixedMarketplaceByKind = ['param' => 0, 'wb_param' => 0];
    $trimmedCompatibility = 0;
    $done = 0;

    $pickDefaultsByPrice = static function (float $price): array {
        if ($price <= 5000) return ['0.15', '100/100/100'];
        if ($price <= 15000) return ['0.25', '200/150/100'];
        if ($price <= 30000) return ['0.5', '250/200/150'];
        return ['1', '350/200/200'];
    };

    foreach ($products as $product) {
        $productId = (int)($product['id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $changed = false;
        $brand = trim((string)($product['brand'] ?? ''));
        $price = (float)($product['price_original'] ?? 0);
        $standard = [];
        $standardIds = [];
        $fieldValuesByNorm = ['param' => [], 'wb_param' => []];

        foreach ($fields as $field) {
            $kind = (string)($field['field_kind'] ?? '');
            $name = trim((string)($field['field_name'] ?? ''));
            $value = (string)($field['field_value'] ?? '');

            if ($kind === 'standard') {
                $standard[$name] = $value;
                $standardIds[$name] = (int)$field['id'];
                if ($name === 'brand' && trim($value) !== '') {
                    $brand = trim($value);
                }
                if ($name === 'purchase_price' && $price <= 0 && is_numeric(str_replace(',', '.', trim($value)))) {
                    $price = (float)str_replace(',', '.', trim($value));
                }
                continue;
            }

            if (($kind === 'param' || $kind === 'wb_param') && $name !== '') {
                $attrNorm = $norm($name);
                $fieldNormKey = supplier_products_db_attr_norm($name);
                if ($fieldNormKey !== '' && !isset($fieldValuesByNorm[$kind][$fieldNormKey])) {
                    $fieldValuesByNorm[$kind][$fieldNormKey] = $value;
                }
                $valueNorm = $norm($value);
                $newValue = $value;
                $didTrimCompatibility = false;
                if (isset($map[$attrNorm][$valueNorm])) {
                    $mapped = $map[$attrNorm][$valueNorm];
                    if ($mapped !== $newValue) {
                        $newValue = $mapped;
                    }
                }
                if ($isCompatibilityAttr($fieldNormKey, $attrNorm)) {
                    $limited = $limitCompatibilityValue($newValue);
                    if ($limited !== $newValue) {
                        $newValue = $limited;
                        $didTrimCompatibility = true;
                    }
                }
                if ($newValue !== $value) {
                    $updField->execute([$newValue, (int)$field['id']]);
                    $changed = true;
                    $replacedCount++;
                    $replacedByElement[$kind] = (int)($replacedByElement[$kind] ?? 0) + 1;
                    $replacedByAttr[$attrNorm] = (int)($replacedByAttr[$attrNorm] ?? 0) + 1;
                    if ($didTrimCompatibility) {
                        $trimmedCompatibility++;
                    }
                    if ($attrNorm === $norm('Бренд')) {
                        $brand = trim($newValue);
                    }
                    if ($fieldNormKey !== '') {
                        $fieldValuesByNorm[$kind][$fieldNormKey] = $newValue;
                    }
                }
                continue;
            }

            if ($kind === 'tag' && $name === 'hashtags') {
                $brandKey = $normKey($brand);
                if ($brandKey === '') {
                    continue;
                }
                $parts = preg_split('/\s*,\s*/u', trim($value), -1, PREG_SPLIT_NO_EMPTY);
                $out = [];
                foreach ($parts ?: [] as $part) {
                    $part = trim((string)$part);
                    if ($part === '') {
                        continue;
                    }
                    $tagKey = $normKey(ltrim($part, "# \t\n\r\0\x0B"));
                    if ($tagKey !== '' && mb_stripos($tagKey, $brandKey, 0, 'UTF-8') !== false) {
                        continue;
                    }
                    $out[] = $part;
                }
                $new = implode(', ', $out);
                if ($new !== $value) {
                    $updField->execute([$new, (int)$field['id']]);
                    $changed = true;
                    $hashtagsChanged++;
                }
            }
        }

        $marketplaceContexts = [];
        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
        $ozonCtx = supplier_products_db_load_attr_category('ozon', $ozonCategory, $cfg);
        if ($ozonCtx && !empty($ozonCtx['category_attributes'])) {
            $marketplaceContexts[] = $ozonCtx;
        }
        $wbCtx = supplier_products_db_load_attr_category('wildberries', $wbCategory, $cfg);
        if ($wbCtx && !empty($wbCtx['category_attributes'])) {
            $marketplaceContexts[] = $wbCtx;
        }
        foreach ($marketplaceContexts as $ctx) {
            $source = (string)($ctx['source'] ?? '');
            foreach (supplier_products_db_template_fixed_rows_for_context($source, $ctx, $fieldValuesByNorm, true) as $fixedRow) {
                $kind = (string)($fixedRow['kind'] ?? '');
                $name = (string)($fixedRow['name'] ?? '');
                $value = (string)($fixedRow['value'] ?? '');
                if ($kind === '' || $name === '' || $value === '') {
                    continue;
                }
                if (supplier_products_db_set_param_value($pdo, $supplierId, $productId, $kind, $name, $value)) {
                    $changed = true;
                    $fixedMarketplaceValues++;
                    $fixedMarketplaceByKind[$kind] = (int)($fixedMarketplaceByKind[$kind] ?? 0) + 1;
                    $fieldValuesByNorm[$kind][supplier_products_db_attr_norm($name)] = $value;
                }
            }
        }

        if (isset($standardIds['weight'])) {
            $raw = trim((string)($standard['weight'] ?? ''));
            $num = (float)str_replace(',', '.', $raw);
            if ($raw === '' || abs($num) < 1e-9) {
                [$defWeight] = $pickDefaultsByPrice($price);
                $updField->execute([$defWeight, $standardIds['weight']]);
                $changed = true;
                $fixedWeight++;
            } elseif ($num >= 10) {
                $newWeight = rtrim(rtrim(sprintf('%.6f', $num / 1000.0), '0'), '.');
                $updField->execute([$newWeight, $standardIds['weight']]);
                $changed = true;
                $fixedWeight++;
            }
        }

        $length = trim((string)($standard['length'] ?? ''));
        $width = trim((string)($standard['width'] ?? ''));
        $height = trim((string)($standard['height'] ?? ''));
        $dimensionIdsPresent = isset($standardIds['length'], $standardIds['width'], $standardIds['height']);
        if ($dimensionIdsPresent) {
            $vals = [$length, $width, $height];
            $nums = [];
            foreach ($vals as $value) {
                $normalized = str_replace(',', '.', preg_replace('/\s+/u', '', $value));
                $nums[] = is_numeric($normalized) ? (float)$normalized : null;
            }
            $needsFix = ($length === '' && $width === '' && $height === '')
                || ($nums[0] !== null && $nums[1] !== null && $nums[2] !== null && abs($nums[0]) < 1e-9 && abs($nums[1]) < 1e-9 && abs($nums[2]) < 1e-9)
                || in_array(0.0, array_filter($nums, static fn($v) => $v !== null), true);
            if ($needsFix) {
                [, $defDims] = $pickDefaultsByPrice($price);
                $newVals = explode('/', $defDims);
                if ($nums[0] !== null && $nums[1] !== null && $nums[2] !== null) {
                    $nonZero = array_values(array_filter($nums, static fn($v) => $v !== null && abs((float)$v) > 1e-9));
                    if (count($nonZero) === 2) {
                        $avg = ($nonZero[0] + $nonZero[1]) / 2.0;
                        $fixed = $nums;
                        for ($i = 0; $i < 3; $i++) {
                            if ($fixed[$i] === null || abs((float)$fixed[$i]) <= 1e-9) {
                                $fixed[$i] = $avg;
                            }
                        }
                        $newVals = array_map(static function ($v): string {
                            $v = (float)$v;
                            $round = round($v);
                            return abs($v - $round) < 1e-6 ? (string)(int)$round : rtrim(rtrim(sprintf('%.6f', $v), '0'), '.');
                        }, $fixed);
                    }
                }
                foreach (['length', 'width', 'height'] as $idx => $key) {
                    if ((string)($standard[$key] ?? '') !== (string)($newVals[$idx] ?? '')) {
                        $updField->execute([(string)($newVals[$idx] ?? ''), $standardIds[$key]]);
                        $changed = true;
                    }
                }
                if ($changed) {
                    $fixedDimensions++;
                }
            }
        }

        if ($changed) {
            $changedProducts[] = $productId;
        }

        $done++;
        if ($done % 100 === 0) {
            ops_update_progress($opId, $done, max(1, $total), 'db', "processed={$done}, replaced={$replacedCount}");
        }
    }

    arsort($replacedByAttr);
    $dataset = supplier_products_db_finish_changed_products($supplierId, $changedProducts, $cfg, $opId);
    $report = [
        'title' => 'normalize_param_values',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_scanned' => $total,
            'products_changed' => count(array_unique($changedProducts)),
            'rules_active' => count($rows),
            'replaced_total' => $replacedCount,
            'replaced_param_total' => (int)($replacedByElement['param'] ?? 0),
            'replaced_wb_param_total' => (int)($replacedByElement['wb_param'] ?? 0),
            'fixed_weight_total' => $fixedWeight,
            'fixed_dimensions_total' => $fixedDimensions,
            'hashtags_changed_total' => $hashtagsChanged,
            'fixed_marketplace_values_total' => $fixedMarketplaceValues,
            'fixed_ozon_values_total' => (int)($fixedMarketplaceByKind['param'] ?? 0),
            'fixed_wb_values_total' => (int)($fixedMarketplaceByKind['wb_param'] ?? 0),
            'trimmed_compatibility_total' => $trimmedCompatibility,
            'replaced_by_attr_top30' => array_slice($replacedByAttr, 0, 30, true),
        ],
        'dataset' => $dataset,
    ];

    return supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
}

function supplier_products_db_set_tag_field(PDO $pdo, int $supplierId, int $productId, array $oldNames, string $canonicalName, string $value): bool
{
    $placeholders = implode(',', array_fill(0, count($oldNames), '?'));
    $st = $pdo->prepare("
        SELECT *
        FROM feedtools_supplier_product_fields
        WHERE product_id = ?
          AND field_kind = 'tag'
          AND field_name IN ({$placeholders})
        ORDER BY sort_order ASC, id ASC
        LIMIT 1
    ");
    $st->execute(array_merge([$productId], $oldNames));
    $field = $st->fetch(PDO::FETCH_ASSOC);
    $value = trim($value);

    if ($value === '') {
        if (is_array($field)) {
            $del = $pdo->prepare("DELETE FROM feedtools_supplier_product_fields WHERE id = ?");
            $del->execute([(int)$field['id']]);
            return true;
        }
        return false;
    }

    if (is_array($field)) {
        if ((string)($field['field_name'] ?? '') === $canonicalName && (string)($field['field_value'] ?? '') === $value) {
            return false;
        }
        $upd = $pdo->prepare("UPDATE feedtools_supplier_product_fields SET field_name = ?, field_value = ? WHERE id = ?");
        $upd->execute([$canonicalName, $value, (int)$field['id']]);
        return true;
    }

    $sort = $pdo->prepare("SELECT COALESCE(MAX(sort_order), 0) + 10 FROM feedtools_supplier_product_fields WHERE product_id = ?");
    $sort->execute([$productId]);
    $sortOrder = (int)$sort->fetchColumn();
    $ins = $pdo->prepare("
        INSERT INTO feedtools_supplier_product_fields (
            supplier_id, product_id, field_kind, field_name, field_value, sort_order
        ) VALUES (?, ?, 'tag', ?, ?, ?)
    ");
    $ins->execute([$supplierId, $productId, $canonicalName, $value, $sortOrder]);
    return true;
}

function supplier_products_db_set_feature_fields(PDO $pdo, int $supplierId, int $productId, array $features): bool
{
    $final = supplier_products_db_merge_feature_values([], $features);
    if ($supplierId <= 0 || $productId <= 0 || !$final) {
        return false;
    }

    $st = $pdo->prepare("
        SELECT id, field_name, field_value, sort_order
        FROM feedtools_supplier_product_fields
        WHERE product_id = ?
          AND field_kind = 'feature'
        ORDER BY sort_order ASC, id ASC
    ");
    $st->execute([$productId]);
    $rows = $st->fetchAll(PDO::FETCH_ASSOC) ?: [];
    $current = [];
    foreach ($rows as $row) {
        $value = supplier_products_db_normalize_feature_candidate((string)($row['field_value'] ?? ''));
        if ($value !== '' && !supplier_products_db_feature_is_weak($value)) {
            $current[] = $value;
        }
    }
    if ($current === $final) {
        return false;
    }

    $startedTx = false;
    if (!$pdo->inTransaction()) {
        $pdo->beginTransaction();
        $startedTx = true;
    }

    try {
        $del = $pdo->prepare("
            DELETE FROM feedtools_supplier_product_fields
            WHERE product_id = ?
              AND field_kind = 'feature'
        ");
        $del->execute([$productId]);

        $sort = $pdo->prepare("SELECT COALESCE(MAX(sort_order), 0) + 10 FROM feedtools_supplier_product_fields WHERE product_id = ?");
        $sort->execute([$productId]);
        $sortOrder = (int)$sort->fetchColumn();

        $ins = $pdo->prepare("
            INSERT INTO feedtools_supplier_product_fields (
                supplier_id, product_id, field_kind, field_name, field_value, sort_order
            ) VALUES (?, ?, 'feature', ?, ?, ?)
        ");
        $index = 0;
        foreach ($final as $feature) {
            $index++;
            $ins->execute([
                $supplierId,
                $productId,
                supplier_products_feature_field_name($index),
                $feature,
                $sortOrder,
            ]);
            $sortOrder += 10;
        }

        if ($startedTx) {
            $pdo->commit();
        }
    } catch (Throwable $e) {
        if ($startedTx && $pdo->inTransaction()) {
            $pdo->rollBack();
        }
        throw $e;
    }

    return true;
}

function supplier_products_db_op_run_pipeline(array $cfg, array $ds, int $opId, array $params, callable $log, array $opMeta): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $opsJson = (string)($params['ops_json'] ?? '[]');
    $stepsRaw = json_decode($opsJson, true);
    if (!is_array($stepsRaw) || !$stepsRaw) {
        throw new RuntimeException('Конвейер пустой или повреждён.');
    }

    $registry = op_registry();
    $stepsToRun = [];
    foreach ($stepsRaw as $step) {
        $step = trim((string)$step);
        if ($step === '' || $step === 'run_pipeline') {
            continue;
        }
        if (!isset($registry[$step]) || !supplier_products_db_operation_is_supported($step, (array)$registry[$step])) {
            throw new RuntimeException("Операция {$step} не подключена к DB-товарам поставщика.");
        }
        $stepsToRun[] = $step;
    }
    $stepsToRun = array_values(array_unique($stepsToRun));
    if (!$stepsToRun) {
        throw new RuntimeException('В конвейере не осталось DB-операций для запуска.');
    }

    if (!function_exists('op_run_one')) {
        require_once __DIR__ . '/op_runner.php';
    }

    $offerIds = [];
    if (!empty($params['offer_ids']) && is_array($params['offer_ids'])) {
        $offerIds = array_values(array_unique(array_filter(array_map('strval', $params['offer_ids']), static fn($v) => trim($v) !== '')));
    }
    $globalModel = trim((string)($params['model'] ?? ''));
    $stepModels = [];
    $stepModelsRaw = json_decode((string)($params['op_models_json'] ?? '{}'), true);
    if (is_array($stepModelsRaw)) {
        foreach ($stepModelsRaw as $stepKey => $stepModel) {
            $stepKey = trim((string)$stepKey);
            $stepModel = trim((string)$stepModel);
            if ($stepKey !== '' && $stepModel !== '') {
                $stepModels[$stepKey] = mb_substr($stepModel, 0, 120);
            }
        }
    }
    $stepImageModels = [];
    $stepImageModelsRaw = json_decode((string)($params['op_image_models_json'] ?? '{}'), true);
    if (is_array($stepImageModelsRaw)) {
        foreach ($stepImageModelsRaw as $stepKey => $stepModel) {
            $stepKey = trim((string)$stepKey);
            $stepModel = trim((string)$stepModel);
            if ($stepKey !== '' && $stepModel !== '') {
                $stepImageModels[$stepKey] = mb_substr($stepModel, 0, 120);
            }
        }
    }
    $hasStepParamsPayload = array_key_exists('op_params_json', $params);
    $stepParams = [];
    $stepParamsRaw = json_decode((string)($params['op_params_json'] ?? '{}'), true);
    if (is_array($stepParamsRaw)) {
        foreach ($stepParamsRaw as $stepKey => $stepParamMap) {
            $stepKey = trim((string)$stepKey);
            if ($stepKey === '' || !is_array($stepParamMap)) {
                continue;
            }
            foreach ($stepParamMap as $paramKey => $paramValue) {
                $paramKey = trim((string)$paramKey);
                if ($paramKey === '' || is_array($paramValue) || is_object($paramValue)) {
                    continue;
                }
                $stepParams[$stepKey][$paramKey] = mb_substr((string)$paramValue, 0, 500);
            }
        }
    }
    $globalMaxItems = trim((string)($params['max_items'] ?? '0'));
    if ($globalMaxItems === '') {
        $globalMaxItems = '0';
    }
    $globalOzonConnectionId = trim((string)($params['ozon_connection_id'] ?? '0'));
    $globalWbConnectionId = trim((string)($params['wb_connection_id'] ?? '0'));
    $globalBrandList = trim((string)($params['brand_list'] ?? ''));

    $log("supplier_db run_pipeline: dataset={$datasetId}, supplier={$supplierId}, steps=" . count($stepsToRun) . ", selected_offers=" . count($offerIds) . "\n");
    ops_update_progress($opId, 0, count($stepsToRun), 'pipeline', 'starting DB pipeline');

    $extractUsage = static function (?array $summary): array {
        $fromArray = static function (array $u): array {
            $amount = (float)($u['cost'] ?? $u['cost_usd'] ?? $u['gpt_cost'] ?? $u['gpt_cost_usd'] ?? $u['image_generation_cost'] ?? 0.0);
            $costUsd = (float)($u['cost_usd'] ?? $u['gpt_cost_usd'] ?? $u['image_generation_cost_usd'] ?? $amount);
            return [
                'input_tokens' => (int)($u['input_tokens'] ?? $u['tokens_in'] ?? $u['gpt_tokens_input'] ?? $u['image_input_tokens'] ?? 0),
                'cached_input_tokens' => (int)($u['cached_input_tokens'] ?? $u['tokens_cached_in'] ?? $u['gpt_tokens_cached_input'] ?? $u['image_cached_input_tokens'] ?? 0),
                'output_tokens' => (int)($u['output_tokens'] ?? $u['tokens_out'] ?? $u['gpt_tokens_output'] ?? $u['image_output_tokens'] ?? 0),
                'cost' => $amount,
                'cost_usd' => $costUsd,
                'cost_currency' => (string)($u['cost_currency'] ?? $u['gpt_cost_currency'] ?? $u['image_generation_cost_currency'] ?? ''),
                'cost_label' => (string)($u['cost_label'] ?? $u['gpt_cost_label'] ?? $u['image_generation_cost_label'] ?? ''),
                'image_input_tokens' => (int)($u['image_input_tokens'] ?? 0),
                'image_cached_input_tokens' => (int)($u['image_cached_input_tokens'] ?? 0),
                'image_output_tokens' => (int)($u['image_output_tokens'] ?? 0),
                'image_generation_cost' => (float)($u['image_generation_cost'] ?? 0.0),
                'image_generation_cost_label' => (string)($u['image_generation_cost_label'] ?? ''),
            ];
        };
        if ($summary) {
            if (isset($summary['summary']['usage']) && is_array($summary['summary']['usage'])) {
                return $fromArray($summary['summary']['usage']);
            }
            if (isset($summary['metrics']['usage']) && is_array($summary['metrics']['usage'])) {
                return $fromArray($summary['metrics']['usage']);
            }
            if (isset($summary['usage']) && is_array($summary['usage'])) {
                return $fromArray($summary['usage']);
            }
            if (isset($summary['usage_total']) && is_array($summary['usage_total'])) {
                return $fromArray($summary['usage_total']);
            }
            if (isset($summary['metrics']) && is_array($summary['metrics'])) {
                return $fromArray($summary['metrics']);
            }
        }
        return $fromArray([]);
    };

    $steps = [];
    $totalIn = 0;
    $totalCachedIn = 0;
    $totalOut = 0;
    $totalCostUsd = 0.0;
    $totalCostsByCurrency = [];
    $createdBy = trim((string)($params['_actor'] ?? ''));

    foreach ($stepsToRun as $idx => $stepType) {
        $stepNo = $idx + 1;
        $meta = $registry[$stepType];
        $defs = (array)($meta['params'] ?? []);
        $childParams = [];
        foreach ($defs as $key => $def) {
            if (is_array($def) && array_key_exists('default', $def)) {
                $childParams[$key] = (string)$def['default'];
            }
        }
        if ($offerIds) {
            $childParams['offer_ids'] = $offerIds;
        }
        $stepModel = trim((string)($stepModels[$stepType] ?? ''));
        $modelForStep = $stepModel !== '' ? $stepModel : $globalModel;
        if ($modelForStep !== '' && array_key_exists('model', $defs)) {
            $childParams['model'] = $modelForStep;
        }
        $imageModelForStep = trim((string)($stepImageModels[$stepType] ?? ''));
        if ($imageModelForStep !== '' && array_key_exists('image_model', $defs)) {
            $childParams['image_model'] = $imageModelForStep;
        }
        if (array_key_exists('max_items', $defs)) {
            $childParams['max_items'] = $globalMaxItems;
        }
        if ($globalOzonConnectionId !== '' && $globalOzonConnectionId !== '0' && array_key_exists('ozon_connection_id', $defs)) {
            $childParams['ozon_connection_id'] = $globalOzonConnectionId;
        }
        if ($globalWbConnectionId !== '' && $globalWbConnectionId !== '0' && array_key_exists('wb_connection_id', $defs)) {
            $childParams['wb_connection_id'] = $globalWbConnectionId;
        }
        if ($globalBrandList !== '' && array_key_exists('brand_list', $defs)) {
            $childParams['brand_list'] = $globalBrandList;
        }
        if (array_key_exists('inplace', $defs)) {
            $childParams['inplace'] = '1';
        }
        if (array_key_exists('auto_dataset', $defs)) {
            $childParams['auto_dataset'] = '0';
        }
        if (!$hasStepParamsPayload && $stepType === 'gpt_generate_product_photo_variant' && array_key_exists('only_single_source_photo', $defs)) {
            $childParams['only_single_source_photo'] = '1';
        }
        foreach ((array)($stepParams[$stepType] ?? []) as $paramKey => $paramValue) {
            if (array_key_exists($paramKey, $defs)) {
                $childParams[$paramKey] = (string)$paramValue;
            }
        }
        $childParams['_pipeline_parent_op_id'] = $opId;
        $childParams['_pipeline_step_index'] = $stepNo;
        $childParams['_pipeline_steps_total'] = count($stepsToRun);
        $childParams['_pipeline_step_op_type'] = $stepType;
        $childParams['_supplier_products_db_pipeline'] = '1';

        $childOpId = ops_create($datasetId, $stepType, $childParams, $createdBy !== '' ? $createdBy : null);
        ops_set_status($childOpId, 'running', "Started by supplier DB pipeline op={$opId}\n", null);
        $modelLog = isset($childParams['model']) && trim((string)$childParams['model']) !== '' ? ', model=' . (string)$childParams['model'] : '';
        $imageModelLog = isset($childParams['image_model']) && trim((string)$childParams['image_model']) !== '' ? ', image_model=' . (string)$childParams['image_model'] : '';
        $photoVariantScopeLog = $stepType === 'gpt_generate_product_photo_variant' && isset($childParams['only_single_source_photo'])
            ? ', only_single_source_photo=' . (string)$childParams['only_single_source_photo']
            : '';
        $log("Step {$stepNo}/" . count($stepsToRun) . ": op={$stepType}, child_op_id={$childOpId}{$modelLog}{$imageModelLog}{$photoVariantScopeLog}\n");
        ops_update_progress($opId, $idx, count($stepsToRun), 'pipeline', "running {$stepType}");

        $childRow = ops_get($childOpId);
        if (!$childRow) {
            throw new RuntimeException("Не удалось прочитать дочернюю операцию {$childOpId}.");
        }

        $childOutDir = op_output_dir($cfg, $datasetId, $childOpId);
        ensure_dir($childOutDir);
        $childLogFileAbs = $childOutDir . '/op.log';
        if (!is_file($childLogFileAbs)) {
            file_put_contents($childLogFileAbs, '');
        }
        $childLog = static function (string $msg) use ($childOpId, $childLogFileAbs): void {
            file_put_contents($childLogFileAbs, $msg, FILE_APPEND);
            try {
                ops_append_log_tail($childOpId, $msg, 200000);
            } catch (Throwable $e) {
            }
        };

        try {
            op_run_one($cfg, $childRow, $childLog);
            ops_set_status($childOpId, 'done', "Done.\n", null);
        } catch (Throwable $e) {
            ops_set_status($childOpId, 'error', null, $e->getMessage());
            $log("Pipeline stop: child op error: {$stepType}: " . $e->getMessage() . "\n");
            throw $e;
        }

        $childDone = ops_get($childOpId);
        $childSummary = null;
        if ($childDone && !empty($childDone['summary_json'])) {
            $decoded = json_decode((string)$childDone['summary_json'], true);
            $childSummary = is_array($decoded) ? $decoded : null;
        }
        $usage = $extractUsage($childSummary);
        $totalIn += (int)$usage['input_tokens'];
        $totalCachedIn += (int)$usage['cached_input_tokens'];
        $totalOut += (int)$usage['output_tokens'];
        $totalCostUsd += (float)$usage['cost_usd'];
        $usageCurrency = strtoupper(trim((string)($usage['cost_currency'] ?? '')));
        if ($usageCurrency !== '') {
            $totalCostsByCurrency[$usageCurrency] = (float)($totalCostsByCurrency[$usageCurrency] ?? 0.0) + (float)($usage['cost'] ?? $usage['cost_usd'] ?? 0.0);
        }

        $steps[] = [
            'op_type' => $stepType,
            'op_id' => $childOpId,
            'status' => 'done',
            'model' => (string)($childParams['model'] ?? ($childParams['image_model'] ?? '')),
            'usage' => $usage,
        ];
        ops_update_progress($opId, $stepNo, count($stepsToRun), 'pipeline', "done {$stepType}");
    }

    supplier_products_update_dataset_row_from_db($supplierId, $cfg);

    $totalCostCurrency = count($totalCostsByCurrency) === 1 ? (string)array_key_first($totalCostsByCurrency) : '';
    $totalCost = count($totalCostsByCurrency) === 1 ? round((float)reset($totalCostsByCurrency), 6) : round($totalCostUsd, 6);
    $summary = [
        'title' => 'Supplier DB pipeline finished',
        'pipeline' => [
            'steps' => $steps,
            'selected_offers' => count($offerIds),
            'dataset_id' => $datasetId,
            'supplier_id' => $supplierId,
        ],
        'usage_total' => [
            'input_tokens' => $totalIn,
            'cached_input_tokens' => $totalCachedIn,
            'output_tokens' => $totalOut,
            'cost' => $totalCost,
            'cost_currency' => $totalCostCurrency,
            'cost_label' => $totalCostCurrency !== '' ? openai_format_cost($totalCost, $totalCostCurrency) : '',
            'costs' => $totalCostsByCurrency,
            'cost_usd' => round($totalCostUsd, 6),
        ],
        'total_cost' => $totalCost,
        'total_cost_currency' => $totalCostCurrency,
        'total_cost_label' => $totalCostCurrency !== '' ? openai_format_cost($totalCost, $totalCostCurrency) : '',
        'total_cost_usd' => round($totalCostUsd, 6),
    ];

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    $stepsAbs = $outDir . '/pipeline_steps.json';
    file_put_contents($stepsAbs, json_encode($summary, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT));

    return [
        'summary_json_inline' => $summary,
        'pipeline_steps_json' => rel_to_outputs($cfg, $stepsAbs),
    ];
}

function supplier_products_db_op_gpt_fill_color_vision(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $requestedModel = LLM::modelForOp($cfg, $params);
    $model = LLM::modelForVisionOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'color_detect_vision_ru.txt');
    $client = LLM::client($cfg, $model);
    $pricing = openai_pricing_for_model($cfg, $model);
    $log("supplier_db gpt_fill_color_vision: model={$model}, requested_model={$requestedModel}, max_items={$maxItems}\n");
    $log("pricing: " . openai_pricing_debug_string($pricing) . "\n");

    $norm = static function (string $s): string {
        $s = trim($s);
        if ($s === '') return '';
        return mb_strtolower($s, 'UTF-8');
    };

    $descToSnippet = static function (string $raw, int $maxLen = 600): string {
        $raw = html_entity_decode($raw, ENT_QUOTES | ENT_XML1, 'UTF-8');
        $raw = strip_tags($raw);
        $raw = preg_replace('/\s+/u', ' ', $raw);
        $raw = trim((string)$raw);
        if ($raw === '') return '';
        if (mb_strlen($raw, 'UTF-8') > $maxLen) {
            return mb_substr($raw, 0, $maxLen, 'UTF-8') . '...';
        }
        return $raw;
    };

    $extractJsonFromText = static function (string $text): array {
        $text = trim($text);
        $i = strpos($text, '{');
        $j = strrpos($text, '}');
        if ($i === false || $j === false || $j <= $i) {
            throw new RuntimeException('JSON braces not found in GPT output');
        }
        $obj = json_decode(substr($text, $i, $j - $i + 1), true);
        if (!is_array($obj)) {
            throw new RuntimeException('GPT output is not valid JSON');
        }
        return $obj;
    };

    $extractUsage = static function (?array $raw): array {
        if (!$raw) return ['input' => 0, 'output' => 0, 'cached_input' => 0];
        $u = $raw['usage'] ?? null;
        if (!is_array($u)) return ['input' => 0, 'output' => 0, 'cached_input' => 0];

        $cached = 0;
        $details = $u['input_tokens_details'] ?? null;
        if (is_array($details)) {
            $cached = (int)($details['cached_tokens'] ?? ($details['cached_input_tokens'] ?? 0));
        }
        return [
            'input' => (int)($u['input_tokens'] ?? 0),
            'output' => (int)($u['output_tokens'] ?? 0),
            'cached_input' => $cached,
        ];
    };

    $normalizeColor = static function (string $s): string {
        $s = trim((string)preg_replace('/\s+/u', ' ', $s));
        if ($s === '') return '';
        $first = mb_substr($s, 0, 1, 'UTF-8');
        $rest = mb_substr($s, 1, null, 'UTF-8');
        return mb_strtoupper($first, 'UTF-8') . $rest;
    };

    $splitColorValues = static function (array $values) use ($normalizeColor): array {
        $out = [];
        foreach ($values as $value) {
            foreach (preg_split('/\s*[,;\/\|]+\s*/u', trim((string)$value), -1, PREG_SPLIT_NO_EMPTY) ?: [] as $part) {
                $color = $normalizeColor((string)$part);
                if ($color !== '' && !in_array($color, $out, true)) {
                    $out[] = $color;
                }
            }
        }
        return array_slice($out, 0, 3);
    };

    $detectColorsFromText = static function (string $name, string $desc) use ($normalizeColor): array {
        $text = trim($name . ' ' . $desc);
        if ($text === '') return [];
        $t = str_replace('ё', 'е', mb_strtolower($text, 'UTF-8'));
        $patterns = [
            'Черный' => '/\bчерн(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Белый' => '/\bбел(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Серый' => '/\bсер(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Красный' => '/\bкрасн(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Синий' => '/\bсин(ий|яя|ее|ие|его|ему|им|их|юю)?\b/u',
            'Голубой' => '/\bголуб(ой|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Зеленый' => '/\bзелен(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Желтый' => '/\bжелт(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Оранжевый' => '/\bоранжев(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Фиолетовый' => '/\bфиолетов(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Розовый' => '/\bрозов(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Коричневый' => '/\bкоричнев(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Бежевый' => '/\bбежев(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Золотой' => '/\bзолот(ой|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
            'Серебристый' => '/\bсеребрист(ый|ая|ое|ые|ого|ому|ым|ых|ую)?\b/u',
        ];

        $found = [];
        foreach ($patterns as $color => $re) {
            if (preg_match($re, $t, $m, PREG_OFFSET_CAPTURE)) {
                $found[] = ['color' => $normalizeColor($color), 'pos' => (int)$m[0][1]];
            }
        }
        if (!$found) return [];
        usort($found, static fn($a, $b) => $a['pos'] <=> $b['pos']);

        $out = [];
        $seen = [];
        foreach ($found as $row) {
            $color = (string)$row['color'];
            if ($color === '' || isset($seen[$color])) continue;
            $seen[$color] = true;
            $out[] = $color;
            if (count($out) >= 3) break;
        }
        return $out;
    };

    $standardColorParts = [
        'черный' => true, 'белый' => true, 'серый' => true, 'красный' => true,
        'синий' => true, 'голубой' => true, 'зеленый' => true, 'желтый' => true,
        'оранжевый' => true, 'фиолетовый' => true, 'розовый' => true, 'коричневый' => true,
        'бежевый' => true, 'золотой' => true, 'серебристый' => true,
        'прозрачный' => true, 'разноцветный' => true, 'мультиколор' => true, 'многоцветный' => true,
    ];
    $colorValueNeedsRedetect = static function (array $colorVals) use ($norm, $standardColorParts): bool {
        if (!$colorVals) return true;
        foreach ($colorVals as $colorVal) {
            $value = str_replace('ё', 'е', $norm((string)$colorVal));
            $value = trim((string)preg_replace('/[\.;:]+$/u', '', $value));
            if ($value === '' || in_array($value, ['цвет не указан', 'не указан', 'не указано', 'нет'], true)) {
                return true;
            }
            $parts = preg_split('/\s*[,;\/\|]+\s*/u', $value, -1, PREG_SPLIT_NO_EMPTY) ?: [$value];
            foreach ($parts as $part) {
                $part = trim((string)$part);
                if ($part !== '' && !isset($standardColorParts[$part])) {
                    return true;
                }
            }
        }
        return false;
    };

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    $totalProducts = count($products);
    $log("scope: products={$totalProducts}\n");
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'finding products without valid color');

    $candidates = [];
    $productByOfferId = [];
    $oldColorFieldIdsByOfferId = [];
    $colorTargetsByOfferId = [];
    $colorMap = [];
    $seen = 0;

    foreach ($products as $product) {
        $seen++;
        $productId = (int)($product['id'] ?? 0);
        if ($productId <= 0) continue;
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($offerId === '') continue;

        $fields = $fieldsByProduct[$productId] ?? [];
        $colorTargets = supplier_products_db_attr_targets_for_product($product, $fields, 'Цвет', $cfg);
        if (!$colorTargets) {
            $colorTargets = [[
                'source' => 'ozon',
                'kind' => 'param',
                'name' => 'Цвет',
                'attr' => ['name' => 'Цвет', 'allowed_values' => []],
            ]];
        }
        $targetKeys = [];
        foreach ($colorTargets as $target) {
            $targetKeys[(string)$target['kind'] . "\n" . supplier_products_db_attr_norm((string)$target['name'])] = true;
        }
        $colorAliasKeys = array_fill_keys(supplier_products_db_attr_candidate_keys('Цвет'), true);
        $colorVals = [];
        $colorFieldIds = [];
        $nonEmptyTargetKeys = [];
        foreach ($fields as $field) {
            $kind = (string)($field['field_kind'] ?? '');
            if ($kind !== 'param' && $kind !== 'wb_param') continue;
            $fieldName = (string)($field['field_name'] ?? '');
            $fieldKey = $kind . "\n" . supplier_products_db_attr_norm($fieldName);
            $matchesColorAlias = false;
            foreach (supplier_products_db_attr_candidate_keys($fieldName) as $candidateKey) {
                if (isset($colorAliasKeys[$candidateKey])) {
                    $matchesColorAlias = true;
                    break;
                }
            }
            if (!isset($targetKeys[$fieldKey]) && !$matchesColorAlias) continue;
            $fieldId = (int)($field['id'] ?? 0);
            if ($fieldId > 0) {
                $colorFieldIds[] = $fieldId;
            }
            $value = trim((string)($field['field_value'] ?? ''));
            if ($value !== '') {
                $colorVals[] = $value;
                if (isset($targetKeys[$fieldKey])) {
                    $nonEmptyTargetKeys[$fieldKey] = true;
                }
            }
        }

        $missingTarget = false;
        foreach (array_keys($targetKeys) as $targetKey) {
            if (empty($nonEmptyTargetKeys[$targetKey])) {
                $missingTarget = true;
                break;
            }
        }

        $needsRedetect = $colorValueNeedsRedetect($colorVals);
        if (!$needsRedetect && !$missingTarget) {
            continue;
        }

        $productByOfferId[$offerId] = $product;
        $colorTargetsByOfferId[$offerId] = $colorTargets;
        $oldColorFieldIdsByOfferId[$offerId] = $needsRedetect ? array_values(array_filter($colorFieldIds)) : [];

        if (!$needsRedetect && $colorVals) {
            $colorMap[$offerId] = ['colors' => $splitColorValues($colorVals), 'status' => 'from_existing'];
            continue;
        }

        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        $sourcePicture = supplier_products_db_photo_variant_source_picture($pictures);
        if ($sourcePicture === '') {
            $sourcePicture = (string)($pictures[0] ?? '');
        }
        $candidate = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'vendorCode' => (string)($product['vendor_code'] ?? ''),
            'name' => (string)($product['name'] ?? ''),
            'desc' => $descToSnippet((string)($product['description_html'] ?? ''), 650),
            'picture' => $sourcePicture,
        ];
        $candidates[$offerId] = $candidate;

        if ($maxItems > 0 && count($candidates) >= $maxItems) {
            break;
        }
        if ($seen % 250 === 0) {
            ops_update_progress($opId, $seen, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log("scan: products_seen={$seen}, candidates_need_redetect=" . count($candidates) . "\n");

    $candidatesForGpt = [];
    $filledFromText = 0;
    foreach ($candidates as $offerId => $item) {
        $colorsText = $detectColorsFromText((string)($item['name'] ?? ''), (string)($item['desc'] ?? ''));
        if ($colorsText) {
            $colorMap[$offerId] = ['colors' => $colorsText, 'status' => 'from_text'];
            $filledFromText++;
        } else {
            $candidatesForGpt[$offerId] = $item;
        }
    }
    $log("prepass text: filled={$filledFromText}, need_gpt=" . count($candidatesForGpt) . "\n");

    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $gptTotal = max(1, count($candidatesForGpt));
    $gptDone = 0;
    $firstLlmError = '';

    foreach ($candidatesForGpt as $offerId => $item) {
        $gptDone++;
        ops_update_progress($opId, $gptDone, $gptTotal, 'gpt', "detecting color ({$gptDone}/{$gptTotal})");

        $pic = trim((string)($item['picture'] ?? ''));
        if ($pic === '') {
            $colorMap[$offerId] = ['colors' => [], 'status' => 'no_picture'];
            continue;
        }

        $imageForLlm = $pic;
        $imageMetaForReport = [];
        try {
            $imageMeta = supplier_products_db_cover_image_data_url($pic, $cfg);
            $imageForLlm = (string)($imageMeta['image_url'] ?? $pic);
            $imageMetaForReport = array_diff_key($imageMeta, ['image_url' => true]);
        } catch (Throwable $e) {
            $colorMap[$offerId] = ['colors' => [], 'status' => 'image_unavailable', 'error' => $e->getMessage()];
            $log("IMAGE SKIP offer={$offerId}: " . $e->getMessage() . "\n");
            continue;
        }

        $productJson = [
            'offer_id' => (string)$item['offer_id'],
            'vendorCode' => (string)$item['vendorCode'],
            'name' => (string)$item['name'],
            'desc' => (string)$item['desc'],
        ];
        $input = [[
            'role' => 'user',
            'content' => [
                ['type' => 'input_text', 'text' => "JSON:\n" . json_encode($productJson, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)],
                ['type' => 'input_image', 'image_url' => $imageForLlm],
            ],
        ]];

        try {
            $res = $client->generateText($model, $input, $prompt, [
                'prompt_cache_key' => 'fill_color:' . substr(hash('sha256', $prompt), 0, 48),
                'temperature' => 0.2,
                'max_output_tokens' => 220,
                'text' => ['format' => ['type' => 'json_object']],
            ]);
            $usage = $extractUsage($res['raw'] ?? null);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $cost = openai_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);
            $costUsdTotal += $cost;

            $outText = (string)($res['output_text'] ?? '');
            $obj = $extractJsonFromText($outText);
            $colors = [];
            foreach ((array)($obj['colors'] ?? []) as $color) {
                $color = $normalizeColor((string)$color);
                if ($color !== '') $colors[$color] = true;
            }
            $colors = array_slice(array_keys($colors), 0, 3);
            $colorMap[$offerId] = ['colors' => $colors, 'status' => $colors ? 'ok' : 'undetermined'];

            file_put_contents(
                $outDir . '/gpt/' . preg_replace('/[^a-zA-Z0-9_\\-\\.]/', '_', $offerId) . '.json',
	                json_encode([
	                    'offer_id' => $offerId,
	                    'picture' => $pic,
	                    'image_prepared' => $imageMetaForReport,
	                    'product' => $productJson,
	                    'gpt_output_text' => $outText,
	                    'parsed' => $obj,
                    'colors_final' => $colors,
                    'gpt_usage' => $usage,
                    'gpt_cost_usd' => $cost,
                ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
            );
        } catch (Throwable $e) {
            $colorMap[$offerId] = ['colors' => [], 'status' => 'error', 'error' => $e->getMessage()];
            if ($firstLlmError === '') {
                $firstLlmError = $e->getMessage();
            }
            $log("GPT ERROR offer={$offerId}: " . $e->getMessage() . "\n");
        }
    }

    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $log("GPT usage total: input={$tokensInTotal}, cached_input={$tokensCachedTotal}, output={$tokensOutTotal}\n");
    $log("GPT cost total: {$costLabel}\n");

    $pdo = db();
    $changedProducts = [];
    $removedOldColorParams = 0;
    $insertedColorParams = 0;
    $offersInsertedNonEmpty = 0;

    ops_update_progress($opId, 0, max(1, count($colorMap)), 'db', 'saving colors');
    $pdo->beginTransaction();
    try {
        $applyDone = 0;
        foreach ($colorMap as $offerId => $result) {
            $product = $productByOfferId[$offerId] ?? null;
            if (!is_array($product)) continue;
            $productId = (int)($product['id'] ?? 0);
            if ($productId <= 0) continue;

            $fieldIds = array_values(array_filter(array_map('intval', $oldColorFieldIdsByOfferId[$offerId] ?? [])));
            if ($fieldIds) {
                $del = $pdo->prepare("DELETE FROM feedtools_supplier_product_fields WHERE id IN (" . implode(',', array_fill(0, count($fieldIds), '?')) . ")");
                $del->execute($fieldIds);
                $removedOldColorParams += count($fieldIds);
                $changedProducts[$productId] = true;
            }

            $colors = (array)($result['colors'] ?? []);
            if ($colors) {
                $insertedForOffer = 0;
                $targets = (array)($colorTargetsByOfferId[$offerId] ?? []);
                if (!$targets) {
                    $targets = [[
                        'kind' => 'param',
                        'name' => 'Цвет',
                    ]];
                }
                foreach ($colors as $color) {
                    $color = $normalizeColor((string)$color);
                    if ($color === '') continue;
                    foreach ($targets as $target) {
                        if (!is_array($target)) {
                            continue;
                        }
                        foreach (supplier_products_db_values_allowed_for_attr($color, (array)($target['attr'] ?? ['allowed_values' => []])) as $valueForTarget) {
                            if ($valueForTarget === '') {
                                continue;
                            }
                            if (supplier_products_db_add_param_if_missing(
                                $pdo,
                                $supplierId,
                                $productId,
                                (string)($target['kind'] ?? 'param'),
                                (string)($target['name'] ?? 'Цвет'),
                                $valueForTarget
                            )) {
                                $insertedColorParams++;
                                $insertedForOffer++;
                            }
                        }
                    }
                }
                if ($insertedForOffer > 0) {
                    $offersInsertedNonEmpty++;
                    $changedProducts[$productId] = true;
                }
            }

            $applyDone++;
            if ($applyDone % 100 === 0) {
                ops_update_progress($opId, $applyDone, max(1, count($colorMap)), 'db', 'saving colors');
            }
        }
        $pdo->commit();
    } catch (Throwable $e) {
        $pdo->rollBack();
        throw $e;
    }

    $changedIds = array_keys($changedProducts);
    $dataset = supplier_products_db_finish_changed_products($supplierId, $changedIds, $cfg, $opId);

    $statusCounts = ['ok' => 0, 'undetermined' => 0, 'no_picture' => 0, 'image_unavailable' => 0, 'error' => 0, 'from_text' => 0, 'from_existing' => 0];
    foreach ($colorMap as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) $statusCounts[$status] = 0;
        $statusCounts[$status]++;
    }
    supplier_products_db_fail_if_llm_unavailable(
        'gpt_fill_color_vision',
        count($candidatesForGpt),
        (int)($statusCounts['error'] ?? 0),
        $tokensInTotal,
        $tokensOutTotal,
        $firstLlmError
    );

    $report = [
        'title' => 'gpt_fill_color_vision',
        'storage' => 'supplier_products_db',
        'summary' => [
            'offers_total' => (int)($dataset['offers_count'] ?? 0),
            'products_seen' => $seen,
            'candidates_need_redetect' => count($candidates),
            'gpt_status_counts' => $statusCounts,
            'removed_old_color_params' => $removedOldColorParams,
            'inserted_color_params' => $insertedColorParams,
            'offers_with_inserted_colors' => $offersInsertedNonEmpty,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'gpt_tokens_input' => $tokensInTotal,
            'gpt_tokens_cached_input' => $tokensCachedTotal,
            'gpt_tokens_output' => $tokensOutTotal,
            'gpt_cost_usd' => $costUsdTotal,
            'gpt_cost' => $costUsdTotal,
            'gpt_cost_currency' => openai_cost_currency_for_model($cfg, $model),
            'gpt_cost_label' => $costLabel,
            'products_changed' => count($changedIds),
        ],
        'params_effective' => [
            'model' => $model,
            'max_items' => (string)$maxItems,
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_fill_color_vision',
        'items' => [
            'Candidates (need redetect): ' . count($candidates),
            'Inserted color params: ' . $insertedColorParams,
            'Offers with inserted colors: ' . $offersInsertedNonEmpty,
            'Images unavailable/skipped: ' . (int)($statusCounts['image_unavailable'] ?? 0),
            'Removed existing color params: ' . $removedOldColorParams,
            'GPT tokens in: ' . $tokensInTotal,
            'GPT tokens cached in: ' . $tokensCachedTotal,
            'GPT tokens out: ' . $tokensOutTotal,
            'GPT cost: ' . $costLabel,
        ],
        'metrics' => [
            'candidates_need_redetect' => count($candidates),
            'inserted_color_params' => $insertedColorParams,
            'offers_with_inserted_colors' => $offersInsertedNonEmpty,
            'removed_old_color_params' => $removedOldColorParams,
            'gpt_status_counts' => $statusCounts,
            'inplace' => 1,
            'updated_dataset_id' => $datasetId,
            'gpt_tokens_input' => $tokensInTotal,
            'gpt_tokens_cached_input' => $tokensCachedTotal,
            'gpt_tokens_output' => $tokensOutTotal,
            'gpt_cost_usd' => $costUsdTotal,
            'gpt_cost' => $costUsdTotal,
            'gpt_cost_currency' => openai_cost_currency_for_model($cfg, $model),
            'gpt_cost_label' => $costLabel,
        ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
    ];
    return $outputs;
}

function supplier_products_db_product_prompt_context_from_fields(array $fieldRows): array
{
    $fields = [];
    $params = [];
    $brand = '';
    $vendor = '';
    $model = '';

    foreach ($fieldRows as $field) {
        $kind = (string)($field['field_kind'] ?? '');
        $name = trim((string)($field['field_name'] ?? ''));
        $value = trim((string)($field['field_value'] ?? ''));
        if ($name === '' || $value === '') {
            continue;
        }
        if (mb_strlen($value, 'UTF-8') > 220) {
            $value = mb_substr($value, 0, 220, 'UTF-8') . '...';
        }

        $normName = mb_strtolower($name, 'UTF-8');
        if ($kind === 'param' || $kind === 'wb_param') {
            $params[] = ['name' => $kind === 'wb_param' ? ('WB: ' . $name) : $name, 'value' => $value];
        } else {
            $fields[$name] = $value;
        }

        if ($brand === '' && in_array($normName, ['brand', 'бренд', 'vendor', 'производитель'], true)) {
            $brand = $value;
        }
        if ($vendor === '' && in_array($normName, ['vendor', 'производитель', 'brand', 'бренд'], true)) {
            $vendor = $value;
        }
        if ($model === '' && in_array($normName, ['model', 'модель'], true)) {
            $model = $value;
        }
    }

    return [
        'vendor' => $vendor,
        'brand' => $brand,
        'model' => $model,
        'fields' => $fields,
        'params' => $params,
    ];
}

function supplier_products_db_product_prompt_context(int $productId): array
{
    if ($productId <= 0) {
        return ['vendor' => '', 'brand' => '', 'model' => '', 'fields' => [], 'params' => []];
    }
    return supplier_products_db_product_prompt_context_from_fields(supplier_products_fields_for_product($productId));
}

function supplier_products_db_extract_json_object(string $text): array
{
    $text = trim($text);
    $decoded = json_decode($text, true);
    if (is_array($decoded)) {
        return $decoded;
    }

    $i = strpos($text, '{');
    $j = strrpos($text, '}');
    if ($i === false || $j === false || $j <= $i) {
        throw new RuntimeException('JSON braces not found in GPT output');
    }
    $decoded = json_decode(substr($text, $i, $j - $i + 1), true);
    if (!is_array($decoded)) {
        throw new RuntimeException('GPT output is not valid JSON');
    }
    return $decoded;
}

function supplier_products_db_extract_openai_usage(?array $raw): array
{
    if (!$raw) {
        return ['input' => 0, 'output' => 0, 'cached_input' => 0];
    }

    $intFrom = static function (array $row, array $keys): int {
        foreach ($keys as $key) {
            if (isset($row[$key]) && is_numeric($row[$key])) {
                return max(0, (int)$row[$key]);
            }
        }
        return 0;
    };

    $cachedFromDetails = static function ($details) use ($intFrom): int {
        if (!is_array($details)) {
            return 0;
        }
        return $intFrom($details, [
            'cached_tokens',
            'cached_input_tokens',
            'cache_read_input_tokens',
            'cachedContentTokenCount',
        ]);
    };

    $geminiUsage = $raw['usageMetadata'] ?? null;
    if (is_array($geminiUsage) && !is_array($raw['usage'] ?? null)) {
        $input = $intFrom($geminiUsage, ['promptTokenCount', 'input_tokens', 'prompt_tokens']);
        $candidate = $intFrom($geminiUsage, ['candidatesTokenCount']);
        $thoughts = $intFrom($geminiUsage, ['thoughtsTokenCount']);
        $total = $intFrom($geminiUsage, ['totalTokenCount', 'total_tokens']);
        $output = max($candidate + $thoughts, $total > $input ? $total - $input : 0);
        return [
            'input' => $input,
            'output' => $output,
            'cached_input' => min($input, $intFrom($geminiUsage, ['cachedContentTokenCount', 'cached_input_tokens', 'cached_tokens'])),
        ];
    }

    $u = $raw['usage'] ?? null;
    if (!is_array($u)) {
        return ['input' => 0, 'output' => 0, 'cached_input' => 0];
    }

    $input = $intFrom($u, ['input_tokens', 'prompt_tokens', 'promptTokenCount']);
    $output = $intFrom($u, ['output_tokens', 'completion_tokens', 'candidatesTokenCount']);
    $total = $intFrom($u, ['total_tokens', 'totalTokenCount']);
    if ($output <= 0 && $total > $input) {
        $output = $total - $input;
    }

    $cached = $intFrom($u, ['cached_input_tokens', 'cached_tokens', 'cache_read_input_tokens']);
    $cached = max(
        $cached,
        $cachedFromDetails($u['input_tokens_details'] ?? null),
        $cachedFromDetails($u['prompt_tokens_details'] ?? null)
    );

    return [
        'input' => $input,
        'output' => $output,
        'cached_input' => min($input, $cached),
    ];
}

function supplier_products_db_fail_if_llm_unavailable(
    string $opName,
    int $attempts,
    int $errors,
    int $tokensIn,
    int $tokensOut,
    string $sampleError = ''
): void
{
    if ($attempts > 0 && $errors >= $attempts && ($tokensIn + $tokensOut) === 0) {
        $message = "{$opName}: все LLM-запросы завершились ошибкой.";
        $sampleError = trim($sampleError);
        if ($sampleError !== '') {
            if (stripos($sampleError, 'User location is not supported') !== false) {
                $sampleError = 'Gemini API отклонил запрос: локация пользователя, проекта или сервера не поддерживается для API.';
            }
            $message .= ' Причина: ' . $sampleError;
        } else {
            $message .= ' Проверь ключ, модель, доступность провайдера или фильтр безопасности.';
        }
        throw new RuntimeException($message);
    }
}

function supplier_products_db_fill_offer_params_prompt(array $cfg, string $model, string $defaultPrompt): string
{
    if (LLM::providerForModel($cfg, $model) !== 'yandex') {
        return $defaultPrompt;
    }

    return <<<'PROMPT'
Ты PIM-аналитик маркетплейса. Заполни характеристики товара по входному JSON.

Правила:
- возвращай только JSON без markdown и пояснений;
- используй только имена атрибутов из marketplace_contexts[*].category_attributes;
- для Ozon и Wildberries возвращай отдельные объекты с marketplace="ozon" или "wildberries";
- если у атрибута есть allowed_values или selection_mode="choose_one", value должен строго совпадать с одним allowed_values;
- не выбирай приблизительное значение из allowed_values, если товар не является этим значением;
- не дублируй existing_params с непустым значением для того же marketplace;
- если в названии есть "уп 1000", "уп. 1000", "упаковка 1000", считай это 1000 штук и заполняй аналог атрибута "количество в единице товара";
- для аккумуляторов и батарей не путай количество товара с количеством ячеек/банок: "6S", "6S1P", "6 ячеек", "cell count 6" и напряжение не означают 6 штук в упаковке; количество в упаковке больше 1 заполняй только при явных словах "комплект", "набор", "упаковка 6 шт", "6 шт";
- для защитных стекол и пленок форматы "2 в 1", "3 в 1", "4-in-1" не означают количество штук; если нет явного "3 шт", "комплект из 3", "упаковка 3 шт", заполняй количество как 1 или пропускай;
- для Ozon характеристика "Подходит для" принимает только чистое название бренда совместимости: DJI, Apple, Samsung, Xiaomi. Не пиши туда модели, серии, категории, типы устройств и пояснения; если бренд совместимости неясен, пиши бренд самого товара;
- для Ozon характеристика "Совместимые модели" заполняется отдельно от "Подходит для": пиши туда только модели/коды моделей без бренда, категории и пояснений. Для запчастей телефонов сохраняй точные обозначения моделей, например "P30 Lite", "Redmi Note 12", "A217F". Если моделей несколько, верни values;
- не заполняй ТН ВЭД, ТНВЭД, "ТН ВЭД коды ЕАЭС" и любые аналогичные коды классификации;
- для Wildberries каждое значение характеристики должно быть не длиннее 100 символов;
- не выдумывай факты, если данных недостаточно или подходящего значения нет — пропусти атрибут;
- если product.brand и product.vendor пустые, можно вернуть vendor верхнего уровня.

Формат:
{"vendor":"","params":[{"marketplace":"ozon","name":"точное имя атрибута","value":"значение"}]}
PROMPT;
}

function supplier_products_db_title_prompt_cache_preamble(array $cfg, string $model): string
{
    if (LLM::providerForModel($cfg, $model) !== 'openai') {
        return '';
    }

    return <<<'PROMPT'
CACHEABLE_TITLE_REWRITE_CONTEXT_v2026_07_01_CANONICAL_BRAND_TITLE
Этот блок намеренно одинаковый для всех товаров одной операции. Он нужен не для ответа пользователю, а как стабильный длинный префикс запроса, чтобы серверный prompt cache мог переиспользовать общие правила. Следующие правила применяются к каждому товару.

Роль: аккуратный PIM-редактор маркетплейса. Цель не уникализировать название любой ценой, а получить точное товарное название до 200 символов и отдельное короткое название до 60 символов. Названия должны быть полезны для карточки товара: без рекламных слов, без мусора, без механической обрезки, без потери бренда, важных моделей и кодов совместимости.

Порядок мышления всегда одинаковый:
1. Прочитай card_brief, если он есть: это сжатая карта задачи покупателя, ключевых фактов, совместимости и вопросов, которые должна закрывать карточка. Затем определи товарный домен по категории поставщика, категориям Ozon/Wildberries, описанию, параметрам и исходному названию.
2. Определи базовый тип товара на русском языке. Если тип уже указан точно, не меняй его без причины. Если тип неясен, выбирай безопасное широкое описание, а не узкую догадку.
3. Выдели бренд, модель, серию, совместимые модели, размер, объем, цвет, материал, количество, фасовку и другие отличительные признаки.
4. Проверь, что каждый факт в новом названии прямо подтвержден входными данными.
5. Убери служебный шум: NEW, Hot, Original, 100%, SKU, vendorCode, offer_id, повторяющиеся слова, лишние скобки, двойные пробелы, хаотичный капслок.
6. Если бренд товара, бренд совместимого устройства или производитель подтвержден во входных данных и помогает понять товар, сохраняй его в названии. Не выдумывай бренды, которых нет во входе.
7. Не добавляй vendorCode, offer_id и артикул продавца как часть товарного названия. При этом совместимые модели и технические коды не являются артикулом продавца и должны сохраняться, если они отличают товар.
8. Если исходное название уже хорошее, точное, читаемое и не длиннее лимита, выбери action="keep". Если исходное название длиннее лимита, action="keep" запрещен: надо переписать компактно.

Безопасные принципы:
- card_brief помогает понять акценты карточки, но не является разрешением придумывать новые свойства. Если card_brief конфликтует с product/category/original_name, верь исходным данным товара и категории.
- Не меняй домен товара. Аккумулятор остается аккумулятором, шлейф остается шлейфом, нижняя плата остается нижней платой, квадрокоптер остается квадрокоптером, петля мебели остается петлей мебели.
- Не превращай товар в аксессуар, запчасть или комплект без явного подтверждения.
- Не добавляй совместимость, если она не указана в названии, описании, категории или характеристиках.
- Не переводь бренд и модель. Не исправляй буквенно-цифровые коды по своему усмотрению.
- Не выкидывай коды вроде A1466, TLp029A1, HRY-LX1, COL-L29, PCT-L29, EB-BG975ABU, DS-2, BN46, AL12A32. Для электроники это часто главный идентификатор совместимости.
- Если кодов очень много, оставь ключевые коды компактно через "/" или в скобках. Если все коды не помещаются в 200 символов, сохрани наиболее важные и не искажай тип товара.
- Если есть формат "уп 1000", "уп. 1000", "упаковка 1000", переписывай как "1000 шт".
- Если есть количество в комплекте, указывай его только если оно явно есть.
- Если есть цвет, размер, материал, объем, емкость или напряжение, включай только тогда, когда это важно для различения товара и подтверждено входом.
- Не используй оценочные слова: лучший, топ, хит, премиум, качественный, новый, оригинальный, скидка, распродажа.

Структура хорошего названия:
- Базовый тип товара на русском.
- Основная модель/совместимость/назначение.
- Важные отличительные характеристики.
- Количество или фасовка, если это часть товарного предложения.
Название должно звучать естественно. Нельзя заканчивать оборванным словом, многоточием или фрагментом списка. Нельзя просто взять первые 200 символов исходника. Если строка длинная, надо переписать ее как цельную компактную фразу.

Короткое название short_name:
- обязательное поле ответа;
- длина не больше 60 символов;
- это не механический обрез new_name, а цельное короткое название;
- это компактное идеальное название товара для интерфейса, фото-обложки и других мест, где нужен короткий текст;
- сохраняй тип товара и главный отличительный идентификатор: совместимую модель, серию, объем, размер или ключевой код;
- сохраняй бренд, если он подтвержден и помогает сделать короткое название понятнее;
- убирай второстепенные уточнения, фасовки и длинные списки совместимости, если они не помещаются;
- не заканчивай оборванным словом, многоточием, запятой или фрагментом скобок.

Особые случаи:
- Для запчастей смартфонов, планшетов, ноутбуков и другой электроники модель совместимости часто важнее бренда продавца. В названии нужно сохранять "для Huawei Honor 10 (COL-L29)", "для MacBook Air A1466", "TLp029A1/TLp029A2" и подобные обозначения.
- Для аккумуляторов важны совместимость, емкость, напряжение и химический тип, если они указаны.
- Для шлейфов, плат, разъемов, модулей и дисплеев важны тип запчасти и совместимая модель.
- Для мебели и фурнитуры важны тип изделия, назначение, сторона/тип петли, материал, цвет, размер, если они указаны.
- Для игрушек, дронов, электроники и инструментов важно не подменять сам товар аксессуаром или запчастью.
- Если категория говорит "Квадрокоптер", а название говорит "Квадрокоптер Cetus Pro", нельзя писать "только дрон" или "для Cetus Pro"; это сам товар.
- Если категория говорит "Аккумулятор для телефона", нельзя писать просто модель телефона без слова аккумулятор.
- Если категория говорит "Нижняя плата", нельзя превращать ее в кабель или разъем, даже если в названии перечислены разъемы.

Формат ответа всегда один:
{
  "action": "keep или update",
  "type_ru": "1-4 слова на русском",
  "new_name": "цельное точное название до 200 символов",
  "short_name": "цельное короткое название до 60 символов",
  "confidence": 0.0,
  "evidence": ["короткое доказательство из входа", "еще одно доказательство"]
}
Возвращай только JSON. Не добавляй markdown. Если данных мало, лучше сохранить безопасное близкое название, чем придумать новое.
END_CACHEABLE_TITLE_REWRITE_CONTEXT
PROMPT;
}

function supplier_products_db_title_request_input(array $cfg, string $model, string $inputJson): string
{
    $preamble = supplier_products_db_title_prompt_cache_preamble($cfg, $model);
    if ($preamble === '') {
        return "Return a valid json object only.\n\n" . $inputJson;
    }
    return "Return a valid json object only.\n\n" . $preamble . "\n\nPRODUCT_PAYLOAD_JSON:\n" . $inputJson;
}

function supplier_products_db_short_title_fallback(string $title, int $limit = 60): string
{
    $title = supplier_products_db_title_norm_spaces($title);
    if ($title === '' || $limit <= 0) {
        return '';
    }
    if (mb_strlen($title, 'UTF-8') <= $limit) {
        return $title;
    }

    $slice = trim((string)mb_substr($title, 0, $limit, 'UTF-8'));
    $spacePos = mb_strrpos($slice, ' ', 0, 'UTF-8');
    if ($spacePos !== false && $spacePos >= (int)floor($limit * 0.55)) {
        $slice = trim((string)mb_substr($slice, 0, $spacePos, 'UTF-8'));
    }
    $slice = preg_replace('~\s+([\)\]\},;:.!?])~u', '$1', (string)$slice);
    $slice = preg_replace('~([\(\[\{])\s+~u', '$1', (string)$slice);
    $slice = rtrim((string)$slice, " \t\n\r\0\x0B.,;:-/([");
    $slice = preg_replace('~[\(\[][^()\[\]]*$~u', '', (string)$slice);
    $slice = trim((string)$slice, " \t\n\r\0\x0B.,;:-/()");
    $slice = supplier_products_db_short_title_strip_trailing_noise($slice);

    return $slice !== '' ? $slice : trim((string)mb_substr($title, 0, $limit, 'UTF-8'));
}

function supplier_products_db_short_title_strip_trailing_noise(string $title): string
{
    $title = supplier_products_db_title_norm_spaces($title);
    $stopWords = '(и|или|с|со|для|по|в|во|на|к|ко|от|до|без|под|над|при|о|об|обо|у|из|за|через)';
    for ($i = 0; $i < 3; $i++) {
        $next = preg_replace('~\s+' . $stopWords . '$~iu', '', $title);
        $next = trim((string)$next, " \t\n\r\0\x0B.,;:-/()");
        if ($next === $title || $next === '') {
            break;
        }
        $title = $next;
    }
    return $title;
}

function supplier_products_db_normalize_short_title(string $shortTitle, string $fallbackTitle, int $limit = 60): string
{
    $shortTitle = supplier_products_db_title_norm_spaces($shortTitle);
    $shortTitle = preg_replace('~\s+([\)\]\},;:.!?])~u', '$1', (string)$shortTitle);
    $shortTitle = preg_replace('~([\(\[\{])\s+~u', '$1', (string)$shortTitle);
    $shortTitle = trim((string)$shortTitle, " \t\n\r\0\x0B.,;:-/");
    $shortTitle = supplier_products_db_short_title_strip_trailing_noise($shortTitle);
    if ($shortTitle === '') {
        return supplier_products_db_short_title_fallback($fallbackTitle, $limit);
    }
    if (mb_strlen($shortTitle, 'UTF-8') <= $limit) {
        return $shortTitle;
    }
    return supplier_products_db_short_title_fallback($shortTitle, $limit);
}

function supplier_products_db_op_gpt_title(array $cfg, array $ds, int $opId, array $params, callable $log, string $mode): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $isFix = ($mode === 'fix');
    $knownModes = [
        'fix' => [
            'op' => 'gpt_fix_title_ru',
            'prompt' => 'title_fix_ru.txt',
            'cache' => 'fix_title:',
        ],
        'optimize' => [
            'op' => 'gpt_optimize_title_marketplace',
            'prompt' => 'title_optimize_marketplace.txt',
            'cache' => 'opt_title:',
        ],
        'rewrite' => [
            'op' => 'gpt_rewrite_title_marketplace',
            'prompt' => 'title_rewrite_marketplace.txt',
            'cache' => 'rewrite_title:',
        ],
    ];
    if (!isset($knownModes[$mode])) {
        throw new RuntimeException('Неизвестный режим DB-операции названий: ' . $mode);
    }
    $opName = $knownModes[$mode]['op'];
    $promptFile = $knownModes[$mode]['prompt'];
    $cachePrefix = $knownModes[$mode]['cache'];
    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $maxOut = max(0, (int)trim((string)($params['max_output_tokens'] ?? '0')));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    $cancelFlagAbs = $outDir . '/cancel.flag';
    $checkCancel = static function () use ($cancelFlagAbs): bool {
        clearstatcache(true, $cancelFlagAbs);
        return is_file($cancelFlagAbs);
    };

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', $promptFile);
    $log("supplier_db {$opName}: model={$model}, max_items={$maxItems}\n");
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");
    $titleCachePreamble = supplier_products_db_title_prompt_cache_preamble($cfg, $model);
    if ($titleCachePreamble !== '') {
        $log(
            'prompt_cache_static_prefix: chars=' . strlen($titleCachePreamble) .
            ' sha256=' . substr(hash('sha256', $titleCachePreamble), 0, 16) .
            " layout=static_prefix_rules_category_then_product\n"
        );
    }

    $hasCyrillicRun5 = static fn(string $s): bool => (bool)preg_match('/\p{Cyrillic}{5}/u', $s);

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $offersTotal = count($products);
    $selectedRequested = count((array)($params['offer_ids'] ?? []));
    $candidates = [];
    $alreadyOk = 0;
    foreach ($products as $product) {
        $name = trim((string)($product['name'] ?? ''));
        if ($name === '') {
            continue;
        }
        $cleanCandidateName = supplier_products_db_prepare_canonical_title(
            $name,
            (string)($product['brand'] ?? ''),
            '',
            (string)($product['offer_id'] ?? ''),
            (string)($product['vendor_code'] ?? '')
        );
        if ($isFix && $hasCyrillicRun5($name) && $cleanCandidateName === supplier_products_db_normalize_unit_pack_in_title($name)) {
            $alreadyOk++;
            continue;
        }
        $candidates[] = $product;
    }

    $needFix = count($candidates);
    $totalToProcess = $maxItems > 0 ? min($needFix, $maxItems) : $needFix;
    ops_update_progress($opId, 0, max(1, $totalToProcess), 'scan', "products_total={$offersTotal}, candidates={$needFix}");
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($candidates));

    $resultsJsonlAbs = $outDir . '/gpt_results.jsonl';
    $rawJsonlAbs = $outDir . '/gpt_raw.jsonl';
    $csvAbs = $outDir . '/changes.csv';
    file_put_contents($resultsJsonlAbs, '');
    file_put_contents($rawJsonlAbs, '');
    $csvFp = fopen($csvAbs, 'wb');
    if ($csvFp) {
        fwrite($csvFp, "\xEF\xBB\xBF");
        fputcsv($csvFp, ['offer_id', 'vendorCode', 'original_name', 'new_name', 'short_name', 'type_ru', 'confidence', 'status', 'title_updated', 'short_name_updated', 'error'], ';');
    }

    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $done = 0;
    $titlesUpdated = 0;
    $productsTouched = 0;
    $failed = 0;
    $skippedLimit = 0;
    $lowConfidence = 0;
    $skippedKept = 0;
    $skippedGuard = 0;
    $guardLogSamples = 0;
    $longTitlesPrepended = 0;
    $shortNamesUpdated = 0;
    $cancelled = false;
    $firstLlmError = '';
    $samples = [];
    $changedProducts = [];
    $pdo = db();
    $updateName = $pdo->prepare("UPDATE feedtools_supplier_products SET name = ? WHERE id = ?");
    $updateDescription = $pdo->prepare("UPDATE feedtools_supplier_products SET description_html = ? WHERE id = ?");
    $client = $totalToProcess > 0 ? LLM::client($cfg, $model) : null;

    foreach ($candidates as $product) {
        if ($checkCancel()) {
            $cancelled = true;
            $log("supplier_db {$opName}: cancelled by user\n");
            break;
        }
        if ($maxItems > 0 && $done >= $maxItems) {
            $skippedLimit++;
            continue;
        }

        $productId = (int)($product['id'] ?? 0);
        $offerId = (string)($product['offer_id'] ?? '');
        $vendorCode = (string)($product['vendor_code'] ?? '');
        $originalName = trim((string)($product['name'] ?? ''));
        if ($productId <= 0 || $originalName === '') {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $brand = trim((string)($product['brand'] ?? ''));
        if ($brand !== '' && (string)($context['brand'] ?? '') === '') {
            $context['brand'] = $brand;
        }
        $titleBrand = trim((string)($context['brand'] ?? $brand));
        $titleVendor = trim((string)($context['vendor'] ?? ''));
        $cleanOriginalNameForPrompt = supplier_products_db_clean_title_for_prompt(
            $originalName,
            $titleBrand,
            $titleVendor,
            $offerId,
            $vendorCode
        );
        $preparedOriginalName = supplier_products_db_prepare_canonical_title(
            $originalName,
            $titleBrand,
            $titleVendor,
            $offerId,
            $vendorCode
        );
        $context['fields']['category_id'] = (string)($product['category_id'] ?? '');
        $context['fields']['category_path'] = (string)($product['category_path'] ?? '');
        $context['fields']['ozon_category'] = (string)($product['ozon_category'] ?? '');
        $context['fields']['wb_category'] = (string)($product['wb_category'] ?? '');

        $standard = [];
        foreach ($fields as $field) {
            if ((string)($field['field_kind'] ?? '') !== 'standard') {
                continue;
            }
            $name = trim((string)($field['field_name'] ?? ''));
            $value = trim((string)($field['field_value'] ?? ''));
            if ($name !== '' && $value !== '') {
                $standard[$name] = $value;
            }
        }

        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
        $marketplaceCategories = [];
        $ozonCtx = ft_load_ozon_category_context($ozonCategory);
        if ($ozonCtx) {
            $marketplaceCategories[] = [
                'source' => 'ozon',
                'code' => (string)($ozonCtx['code'] ?? $ozonCategory),
                'name' => (string)($ozonCtx['name'] ?? ''),
                'full_path' => (string)($ozonCtx['full_path'] ?? ''),
                'description' => supplier_products_db_description_snippet((string)($ozonCtx['description'] ?? ''), 500),
                'typical_goods' => supplier_products_db_description_snippet((string)($ozonCtx['typical_goods'] ?? ''), 500),
                'features' => supplier_products_db_description_snippet((string)($ozonCtx['features'] ?? ''), 500),
            ];
        }
        $wbCtx = ft_load_wb_category_context($wbCategory);
        if ($wbCtx) {
            $marketplaceCategories[] = [
                'source' => 'wildberries',
                'code' => (string)($wbCtx['code'] ?? $wbCategory),
                'name' => (string)($wbCtx['name'] ?? ''),
                'full_path' => (string)($wbCtx['full_path'] ?? ''),
                'description' => supplier_products_db_description_snippet((string)($wbCtx['description'] ?? ''), 500),
                'typical_goods' => supplier_products_db_description_snippet((string)($wbCtx['typical_goods'] ?? ''), 500),
                'features' => supplier_products_db_description_snippet((string)($wbCtx['features'] ?? ''), 500),
            ];
        }

        $categoryContext = [
            'supplier_category' => [
                'id' => (string)($product['category_id'] ?? ''),
                'path' => (string)($product['category_path'] ?? ''),
            ],
            'marketplace_categories' => $marketplaceCategories,
        ];
        $briefCategory = ft_load_combined_marketplace_category_context($ozonCategory, $wbCategory, true);
        if (!$briefCategory) {
            $briefCategory = supplier_products_db_empty_description_category_context();
        }
        $briefProduct = [
            'offer_id' => $offerId,
            'vendorCode' => $vendorCode,
            'name' => $cleanOriginalNameForPrompt !== '' ? $cleanOriginalNameForPrompt : $originalName,
            'brand' => (string)($context['brand'] ?? ''),
            'vendor' => (string)($context['vendor'] ?? ''),
            'model' => (string)($context['model'] ?? ''),
            'category_path' => (string)($product['category_path'] ?? ''),
            'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 1800),
            'params' => supplier_products_db_product_params_payload($fields),
        ];
        $cardBrief = ft_card_brief_build($briefProduct, $briefCategory, [
            'purpose' => 'title',
            'operation_mode' => $mode,
            'use_keywords' => true,
        ]);
        $inputObj = [
            '_schema' => 'supplier_product_title_rewrite_v3_short_name',
            '_mode' => $mode,
            'title_rules' => [
                'max_length' => supplier_products_db_wb_title_limit(),
                'remove_article' => true,
                'article_tokens_source' => 'product.article_tokens_to_remove',
                'must_keep_tokens_source' => 'product.must_keep_tokens',
                'note' => 'Final new_name must be the best canonical product title: keep confirmed useful brands, remove only service ids/articles/noise, not longer than max_length characters, and not mechanically truncated. Also return short_name up to 60 characters.',
                'must_keep_note' => 'Preserve exact compatibility model codes and series. For electronics spare parts these codes distinguish the product and are not seller articles.',
            ],
            'short_title_rules' => [
                'field' => 'short_name',
                'max_length' => 60,
                'must_be_complete_phrase' => true,
                'must_not_be_mechanical_truncation' => true,
                'purpose' => 'compact canonical product title for UI and cover-image text',
                'keep_confirmed_brand' => true,
            ],
            'category_context' => $categoryContext,
            'card_brief' => $cardBrief,
            'original_name' => $cleanOriginalNameForPrompt,
            'source_name' => $originalName,
            'product' => [
                'id' => $offerId,
                'vendorCode' => $vendorCode,
                'vendor' => (string)($context['vendor'] ?? ''),
                'brand' => (string)($context['brand'] ?? ''),
                'model' => (string)($context['model'] ?? ''),
                'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 1800),
                'standard' => $standard,
                'fields' => (array)($context['fields'] ?? []),
                'params' => (array)($context['params'] ?? []),
                'article_tokens_to_remove' => supplier_products_db_title_article_tokens($offerId, $vendorCode),
            ],
        ];
        $mustKeepTokens = array_values(supplier_products_db_title_guard_important_tokens($cleanOriginalNameForPrompt, $inputObj));
        if ($mustKeepTokens) {
            $inputObj['product']['must_keep_tokens'] = array_slice($mustKeepTokens, 0, 24);
        }
        $inputJson = json_encode($inputObj, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($inputJson === false) {
            $inputJson = '{"original_name":""}';
        }
        $requestInput = supplier_products_db_title_request_input($cfg, $model, $inputJson);

        ops_update_progress($opId, $done, max(1, $totalToProcess), 'openai', "offer={$offerId}");

        $status = 'ok';
        $errText = '';
        $newName = '';
        $shortName = '';
        $nameChanged = false;
        $shortNameChanged = false;
        $typeRu = '';
        $confidence = null;
        $raw = null;
        $usage = ['input' => 0, 'cached_input' => 0, 'output' => 0];

        try {
            if ($checkCancel()) {
                $cancelled = true;
                break;
            }

            $opts = [
                'prompt_cache_key' => $cachePrefix . substr(hash('sha256', $prompt), 0, 48),
                'text' => ['format' => ['type' => 'json_object']],
            ];
            if (!$isFix && $maxOut > 0) {
                $opts['max_output_tokens'] = $maxOut;
            }

            $res = $client->generateText($model, $requestInput, $prompt, $opts);
            $rawText = trim((string)($res['output_text'] ?? ''));
            $raw = is_array($res['raw'] ?? null) ? $res['raw'] : null;
            $usage = supplier_products_db_extract_openai_usage($raw);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += openai_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);

            $decoded = supplier_products_db_extract_json_object($rawText);
            $typeRu = trim((string)($decoded['type_ru'] ?? ''));
            $keepRequested = supplier_products_db_title_keep_requested($decoded);
            $normalizedOriginalName = $preparedOriginalName;
            $newName = $keepRequested
                ? $normalizedOriginalName
                : supplier_products_db_prepare_canonical_title(
                    trim((string)($decoded['new_name'] ?? '')),
                    $titleBrand,
                    $titleVendor,
                    $offerId,
                    $vendorCode
                );
            $shortName = supplier_products_db_normalize_short_title(
                trim((string)($decoded['short_name'] ?? '')),
                $newName !== '' ? $newName : ($normalizedOriginalName !== '' ? $normalizedOriginalName : $originalName),
                60
            );
            if (isset($decoded['confidence']) && is_numeric($decoded['confidence'])) {
                $confidence = max(0.0, min(1.0, (float)$decoded['confidence']));
            }

            if ($newName === '') {
                throw new RuntimeException('GPT output: new_name is empty');
            } elseif (mb_strlen($newName, 'UTF-8') > supplier_products_db_wb_title_limit()) {
                throw new RuntimeException('GPT output: new_name is longer than 200 characters');
            } elseif (!$keepRequested && $confidence !== null && $confidence < ($isFix ? 0.62 : 0.70)) {
                $status = 'skipped_low_confidence';
                $errText = 'GPT confidence is too low to update title';
                $lowConfidence++;
            } elseif (!$hasCyrillicRun5($newName)) {
                throw new RuntimeException('GPT output: new_name has no 5 кириллических подряд');
            } elseif (($missingTokens = supplier_products_db_title_missing_important_tokens($cleanOriginalNameForPrompt, $newName, $inputObj)) !== []) {
                $repairedName = supplier_products_db_title_repair_missing_important_tokens(
                    $newName,
                    $missingTokens,
                    $cleanOriginalNameForPrompt,
                    supplier_products_db_wb_title_limit()
                );
                $repairedMissing = $repairedName !== ''
                    ? supplier_products_db_title_missing_important_tokens($cleanOriginalNameForPrompt, $repairedName, $inputObj)
                    : $missingTokens;
                if ($repairedName !== '' && $repairedMissing === [] && $hasCyrillicRun5($repairedName)) {
                    $newName = $repairedName;
                } else {
                    $missingTokens = $repairedMissing ?: $missingTokens;
                    $status = 'skipped_guard';
                    $errText = 'Title guard: proposed title lost important tokens: ' . implode(', ', $missingTokens);
                    $skippedGuard++;
                    if ($guardLogSamples < 50) {
                        $log("supplier_db {$opName}: offer={$offerId} skipped_guard: {$errText}\n");
                        $guardLogSamples++;
                    }
                }
            }

            if ($status === 'ok') {
                $nameChanged = ($newName !== $originalName);

                if (mb_strlen($newName, 'UTF-8') > supplier_products_db_wb_title_limit()) {
                    throw new RuntimeException('GPT output: repaired new_name is longer than 200 characters');
                }

                if ($nameChanged) {
                    $updateName->execute([$newName, $productId]);
                    $changedProducts[$productId] = true;
                    $titlesUpdated++;
                }

                if ($shortName !== '' && supplier_products_set_standard_field_value($pdo, $supplierId, $productId, 'short_name', $shortName)) {
                    $shortNameChanged = true;
                    $shortNamesUpdated++;
                    $changedProducts[$productId] = true;
                }

                if ($nameChanged) {
                    $descriptionResult = supplier_products_db_prepend_long_source_title_to_description(
                        (string)($product['description_html'] ?? ''),
                        $originalName
                    );
                    if (!empty($descriptionResult['changed'])) {
                        $updateDescription->execute([(string)$descriptionResult['description_html'], $productId]);
                        $changedProducts[$productId] = true;
                        $longTitlesPrepended++;
                    }
                }

                if ($nameChanged || $shortNameChanged) {
                    $productsTouched++;
                    $status = $nameChanged
                        ? ($shortNameChanged ? 'title_and_short_name_updated' : 'title_updated')
                        : 'short_name_updated';
                    if (count($samples) < 25) {
                        $samples[] = [
                            'offer_id' => $offerId,
                            'vendorCode' => $vendorCode,
                            'before' => $originalName,
                            'after' => $newName,
                            'short_name' => $shortName,
                            'title_updated' => $nameChanged,
                            'short_name_updated' => $shortNameChanged,
                        ];
                    }
                } else {
                    $status = $keepRequested ? 'skipped_kept' : 'skipped_unchanged';
                    $skippedKept++;
                }
            } elseif ($status === 'skipped_guard' && $shortName !== '') {
                if (supplier_products_set_standard_field_value($pdo, $supplierId, $productId, 'short_name', $shortName)) {
                    $shortNameChanged = true;
                    $shortNamesUpdated++;
                    $productsTouched++;
                    $changedProducts[$productId] = true;
                    $status = 'skipped_guard_short_name_updated';
                    if (count($samples) < 25) {
                        $samples[] = [
                            'offer_id' => $offerId,
                            'vendorCode' => $vendorCode,
                            'before' => $originalName,
                            'after' => $originalName,
                            'proposed_title' => $newName,
                            'short_name' => $shortName,
                            'title_updated' => false,
                            'short_name_updated' => true,
                        ];
                    }
                }
            }
        } catch (Throwable $e) {
            $status = 'error';
            $errText = $e->getMessage();
            if ($firstLlmError === '') {
                $firstLlmError = $errText;
            }
            $failed++;
        }

        $row = [
            'offer_id' => $offerId,
            'vendorCode' => $vendorCode,
            'original_name' => $originalName,
            'type_ru' => $typeRu,
            'new_name' => $newName,
            'short_name' => $shortName,
            'confidence' => $confidence,
            'status' => $status,
            'title_updated' => $nameChanged,
            'short_name_updated' => $shortNameChanged,
            'error' => $errText,
            'usage' => $usage,
        ];
        file_put_contents($resultsJsonlAbs, json_encode($row, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
        if ($raw !== null) {
            file_put_contents($rawJsonlAbs, json_encode(['offer_id' => $offerId, 'usage' => $usage, 'raw' => $raw], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
        }
        if ($csvFp) {
            fputcsv($csvFp, [
                $offerId,
                $vendorCode,
                $originalName,
                $newName,
                $shortName,
                $typeRu,
                $confidence !== null ? (string)$confidence : '',
                $status,
                $nameChanged ? '1' : '0',
                $shortNameChanged ? '1' : '0',
                $errText,
            ], ';');
        }

        $done++;
    }

    if ($csvFp) {
        fclose($csvFp);
    }

    supplier_products_db_fail_if_llm_unavailable($opName, $done, $failed, $tokensInTotal, $tokensOutTotal, $firstLlmError);

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId);
    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $log("TOTAL usage: input={$tokensInTotal}, cached_input={$tokensCachedTotal}, output={$tokensOutTotal}\n");
    $log("TOTAL cost ({$model}): {$costLabel}\n");

    $report = [
        'summary' => [
            'products_total' => $offersTotal,
            'products_scope_total' => $offersTotal,
            'selected_requested' => $selectedRequested,
            'products_already_ok' => $alreadyOk,
            'candidates' => $needFix,
            'processed' => $done,
            'card_briefs_built' => $done,
            'fixed' => $titlesUpdated,
            'titles_updated' => $titlesUpdated,
            'products_touched' => $productsTouched,
            'short_names_updated' => $shortNamesUpdated,
            'failed' => $failed,
            'skipped_low_confidence' => $lowConfidence,
            'skipped_kept' => $skippedKept,
            'skipped_guard' => $skippedGuard,
            'long_titles_prepended_to_description' => $longTitlesPrepended,
            'skipped_due_to_max_items' => $skippedLimit,
            'cancelled' => $cancelled,
            'usage' => [
                'input_tokens' => $tokensInTotal,
                'cached_input_tokens' => $tokensCachedTotal,
                'output_tokens' => $tokensOutTotal,
            ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
        ],
        'samples' => $samples,
        'prompt_file' => 'app/llm/prompts/' . $promptFile,
        'params_effective' => [
            'model' => $model,
            'max_output_tokens' => $maxOut,
            'max_items' => $maxItems,
            'wildberries_title_limit' => supplier_products_db_wb_title_limit(),
            'title_cleanup' => 'article_cleanup_keep_brand',
            'wildberries_title_cleanup' => 'remove_brand_only_during_wb_export',
            'prompt_cache_static_prefix' => $titleCachePreamble !== '' ? '1' : '0',
            'prompt_cache_static_prefix_version' => '2026-07-01-canonical-brand-title',
            'prompt_cache_input_layout' => 'static_prefix_rules_category_then_product',
            'storage' => 'supplier_products_db',
        ],
        'dataset' => $dataset,
    ];

    $reportAbs = $outDir . '/report.json';
    file_put_contents($reportAbs, json_encode($report, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT));

    $summaryInline = [
        'title' => $opName,
        'items' => [
            "Products total: {$offersTotal}",
            "Candidates: {$needFix}",
            "Processed: {$done}",
            "Card briefs built: {$done}",
            "Titles updated: {$titlesUpdated}",
            "Short names updated: {$shortNamesUpdated}",
            "Products touched: {$productsTouched}",
            "Skipped low confidence: {$lowConfidence}",
            "Skipped kept/unchanged: {$skippedKept}",
            "Skipped guard: {$skippedGuard}",
            "Long source titles prepended to description: {$longTitlesPrepended}",
            "Failed: {$failed}",
            'WB title limit: ' . supplier_products_db_wb_title_limit(),
            "Tokens in: {$tokensInTotal}",
            "Tokens cached in: {$tokensCachedTotal}",
            "Tokens out: {$tokensOutTotal}",
            "Cost: " . $costLabel,
        ],
        'metrics' => [
            'products_total' => $offersTotal,
            'candidates' => $needFix,
            'processed' => $done,
            'card_briefs_built' => $done,
            'fixed' => $titlesUpdated,
            'titles_updated' => $titlesUpdated,
            'products_touched' => $productsTouched,
            'short_names_updated' => $shortNamesUpdated,
            'failed' => $failed,
            'skipped_low_confidence' => $lowConfidence,
            'skipped_kept' => $skippedKept,
            'skipped_guard' => $skippedGuard,
            'long_titles_prepended_to_description' => $longTitlesPrepended,
            'wildberries_title_limit' => supplier_products_db_wb_title_limit(),
            'inplace' => '1',
            'inplace_applied' => '1',
            'tokens_in' => $tokensInTotal,
            'tokens_cached_in' => $tokensCachedTotal,
            'tokens_out' => $tokensOutTotal,
        ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
    ];
    if ($cancelled) {
        $summaryInline['items'][] = 'CANCELLED: stopped early';
        $summaryInline['metrics']['cancelled'] = true;
    }

    ops_update_progress($opId, max(1, $totalToProcess), max(1, $totalToProcess), 'done', 'completed');

    return [
        'report_json' => rel_to_outputs($cfg, $reportAbs),
        'gpt_results_jsonl' => rel_to_outputs($cfg, $resultsJsonlAbs),
        'gpt_raw_jsonl' => rel_to_outputs($cfg, $rawJsonlAbs),
        'changes_csv' => rel_to_outputs($cfg, $csvAbs),
        'summary_json_inline' => $summaryInline,
    ];
}

function supplier_products_db_normalize_hashtag(string $s): string
{
    $s = trim($s);
    if ($s === '') {
        return '';
    }
    $s = preg_replace('~^#+~u', '', $s);
    $s = preg_replace('/\s+/u', '_', (string)$s);
    $s = preg_replace('~[^\p{L}\p{N}_]+~u', '', (string)$s);
    $s = mb_strtolower((string)$s, 'UTF-8');
    $s = trim((string)$s, '_');
    if ($s === '') {
        return '';
    }
    // The marketplace limit is 30 characters for the full hashtag, including "#".
    if (mb_strlen($s, 'UTF-8') > 29) {
        $s = trim((string)mb_substr($s, 0, 29, 'UTF-8'), '_');
    }
    return $s === '' ? '' : ('#' . $s);
}

function supplier_products_db_description_snippet(string $raw, int $maxLen = 3000): string
{
    $raw = html_entity_decode($raw, ENT_QUOTES | ENT_XML1, 'UTF-8');
    $raw = strip_tags($raw);
    $raw = preg_replace('/\s+/u', ' ', $raw);
    $raw = trim((string)$raw);
    if ($raw === '') {
        return '';
    }
    if ($maxLen > 0 && mb_strlen($raw, 'UTF-8') > $maxLen) {
        return mb_substr($raw, 0, $maxLen, 'UTF-8') . '...';
    }
    return $raw;
}

function supplier_products_db_plain_text(string $raw): string
{
    $raw = html_entity_decode($raw, ENT_QUOTES | ENT_XML1, 'UTF-8');
    $raw = strip_tags($raw);
    $raw = preg_replace('/\s+/u', ' ', $raw);
    return trim((string)$raw);
}

function supplier_products_db_normalize_description_html(string $html): string
{
    $html = str_replace(['<![CDATA[', ']]>'], '', $html);
    $html = trim((string)$html);
    $html = preg_replace('~<\s*br\s*/?\s*>~iu', '<br>', $html);
    $html = preg_replace('~<\s*/?\s*(p|div)\b[^>]*>~iu', '<br>', (string)$html);
    $html = preg_replace_callback('~<\s*/?\s*(ul|li)\b[^>]*>~iu', static function (array $m): string {
        $tag = mb_strtolower((string)($m[1] ?? ''), 'UTF-8');
        if ($tag === 'ul') {
            return strpos((string)$m[0], '</') === 0 ? '</ul>' : '<ul>';
        }
        return strpos((string)$m[0], '</') === 0 ? '</li>' : '<li>';
    }, (string)$html);
    $html = strip_tags((string)$html, '<br><ul><li>');
    $html = preg_replace('~(?:<br>\s*){3,}~u', '<br><br>', (string)$html);
    $html = preg_replace('~\s*<br>\s*~u', '<br>', (string)$html);
    $html = preg_replace('~<ul>\s*~u', '<ul>', (string)$html);
    $html = preg_replace('~\s*</ul>~u', '</ul>', (string)$html);
    $html = preg_replace('~<li>\s*~u', '<li>', (string)$html);
    $html = preg_replace('~\s*</li>~u', '</li>', (string)$html);

    $plain = supplier_products_db_plain_text((string)$html);
    if (mb_strlen($plain, 'UTF-8') <= 1800) {
        return trim((string)$html);
    }

    $cut = mb_substr($plain, 0, 1790, 'UTF-8');
    $space = mb_strrpos($cut, ' ', 0, 'UTF-8');
    if ($space !== false && $space > 1200) {
        $cut = mb_substr($cut, 0, $space, 'UTF-8');
    }
    return trim((string)$cut) . '...';
}

function supplier_products_db_normalize_description_html_preserve_length(string $html): string
{
    $html = str_replace(['<![CDATA[', ']]>'], '', $html);
    $html = trim((string)$html);
    $html = preg_replace('~<\s*br\s*/?\s*>~iu', '<br>', $html);
    $html = preg_replace('~<\s*/?\s*(p|div)\b[^>]*>~iu', '<br>', (string)$html);
    $html = preg_replace_callback('~<\s*/?\s*(ul|li)\b[^>]*>~iu', static function (array $m): string {
        $tag = mb_strtolower((string)($m[1] ?? ''), 'UTF-8');
        if ($tag === 'ul') {
            return strpos((string)$m[0], '</') === 0 ? '</ul>' : '<ul>';
        }
        return strpos((string)$m[0], '</') === 0 ? '</li>' : '<li>';
    }, (string)$html);
    $html = strip_tags((string)$html, '<br><ul><li>');
    $html = preg_replace('~(?:<br>\s*){3,}~u', '<br><br>', (string)$html);
    $html = preg_replace('~\s*<br>\s*~u', '<br>', (string)$html);
    $html = preg_replace('~<ul>\s*~u', '<ul>', (string)$html);
    $html = preg_replace('~\s*</ul>~u', '</ul>', (string)$html);
    $html = preg_replace('~<li>\s*~u', '<li>', (string)$html);
    $html = preg_replace('~\s*</li>~u', '</li>', (string)$html);
    return trim((string)$html);
}

function supplier_products_db_description_structure_meta(string $html): array
{
    $plain = supplier_products_db_plain_text($html);
    preg_match_all('~<\s*li\b~iu', $html, $liMatches);
    preg_match_all('~<\s*ul\b~iu', $html, $ulMatches);
    preg_match_all('~<\s*br\s*/?\s*>~iu', $html, $brMatches);
    return [
        'plain_len' => mb_strlen($plain, 'UTF-8'),
        'has_list' => !empty($liMatches[0]) || !empty($ulMatches[0]),
        'list_items_count' => isset($liMatches[0]) ? count($liMatches[0]) : 0,
        'breaks_count' => isset($brMatches[0]) ? count($brMatches[0]) : 0,
    ];
}

function supplier_products_db_description_html_snippet(string $html, int $maxLen = 9000): string
{
    $html = supplier_products_db_normalize_description_html_preserve_length($html);
    if ($maxLen > 0 && mb_strlen($html, 'UTF-8') > $maxLen) {
        return mb_substr($html, 0, $maxLen, 'UTF-8') . '...';
    }
    return $html;
}

function supplier_products_db_validate_rewritten_description(string $sourceHtml, string $rewrittenHtml): void
{
    $source = supplier_products_db_description_structure_meta($sourceHtml);
    $rewritten = supplier_products_db_description_structure_meta($rewrittenHtml);
    $sourceLen = (int)($source['plain_len'] ?? 0);
    $rewrittenLen = (int)($rewritten['plain_len'] ?? 0);
    $sourceListItems = (int)($source['list_items_count'] ?? 0);
    $rewrittenListItems = (int)($rewritten['list_items_count'] ?? 0);

    if (!empty($source['has_list']) && $rewrittenListItems <= 0) {
        throw new RuntimeException('GPT removed the list from rewritten description');
    }
    if ($sourceListItems >= 3) {
        $minListItems = max(2, (int)floor($sourceListItems * 0.5));
        if ($rewrittenListItems < $minListItems) {
            throw new RuntimeException('GPT shortened the list too aggressively');
        }
    }
    if ($sourceLen >= 800 && $rewrittenLen < max(300, (int)floor($sourceLen * 0.4))) {
        throw new RuntimeException('GPT shortened a long source description too aggressively');
    }
}

function supplier_products_db_empty_description_category_context(): array
{
    return [
        'code' => '',
        'name' => '',
        'full_path' => '',
        'description' => '',
        'typical_goods' => '',
        'features' => '',
        'keywords_lines' => '',
        'marketplace_contexts' => [],
    ];
}

function supplier_products_db_description_operation_mode(string $descPlain, int $minDescLen): array
{
    $descPlain = supplier_products_db_plain_text($descPlain);
    $plainLen = mb_strlen($descPlain, 'UTF-8');
    $latinShare = $descPlain === '' ? 0.0 : supplier_products_db_latin_share($descPlain);

    if ($descPlain === '') {
        return [
            'mode' => 'generate',
            'reason' => 'empty_description',
            'plain_len' => 0,
            'latin_share' => 0.0,
        ];
    }
    if ($latinShare > 0.20) {
        return [
            'mode' => 'generate',
            'reason' => 'latin_heavy_description',
            'plain_len' => $plainLen,
            'latin_share' => round($latinShare, 4),
        ];
    }
    if ($minDescLen > 0 && $plainLen < $minDescLen) {
        return [
            'mode' => 'generate',
            'reason' => 'short_description',
            'plain_len' => $plainLen,
            'latin_share' => round($latinShare, 4),
        ];
    }

    return [
        'mode' => 'rewrite',
        'reason' => 'existing_description',
        'plain_len' => $plainLen,
        'latin_share' => round($latinShare, 4),
    ];
}

function supplier_products_db_prepend_long_source_title_to_description(string $descriptionHtml, string $sourceTitle): array
{
    $sourceTitle = supplier_products_db_title_norm_spaces($sourceTitle);
    if ($sourceTitle === '' || mb_strlen($sourceTitle, 'UTF-8') <= 250) {
        return ['description_html' => $descriptionHtml, 'changed' => false];
    }

    $existingPlain = supplier_products_db_title_norm_spaces(supplier_products_db_plain_text($descriptionHtml));
    $sourceNorm = mb_strtolower($sourceTitle, 'UTF-8');
    $existingNorm = mb_strtolower($existingPlain, 'UTF-8');
    if ($existingNorm !== '' && str_contains($existingNorm, $sourceNorm)) {
        return ['description_html' => $descriptionHtml, 'changed' => false];
    }

    $lead = '<p><strong>Полное исходное название:</strong> '
        . htmlspecialchars($sourceTitle, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8')
        . '</p>';
    $descriptionHtml = trim((string)$descriptionHtml);
    return [
        'description_html' => $descriptionHtml === '' ? $lead : ($lead . "\n" . $descriptionHtml),
        'changed' => true,
    ];
}

function supplier_products_db_latin_share(string $s): float
{
    preg_match_all('/[A-Za-z]/u', $s, $mLat);
    preg_match_all('/[A-Za-zА-Яа-яЁё]/u', $s, $mAll);
    $latin = isset($mLat[0]) ? count($mLat[0]) : 0;
    $all = isset($mAll[0]) ? count($mAll[0]) : 0;
    return $all <= 0 ? 0.0 : ($latin / $all);
}

function supplier_products_db_product_tag_value(array $fields, array $names): string
{
    foreach ($fields as $field) {
        if ((string)($field['field_kind'] ?? '') !== 'tag') {
            continue;
        }
        $name = trim((string)($field['field_name'] ?? ''));
        if (!in_array($name, $names, true)) {
            continue;
        }
        $value = trim((string)($field['field_value'] ?? ''));
        if ($value !== '') {
            return $value;
        }
    }
    return '';
}

function supplier_products_db_product_params_payload(array $fields): array
{
    $out = [];
    foreach ($fields as $field) {
        $kind = (string)($field['field_kind'] ?? '');
        if ($kind !== 'param' && $kind !== 'wb_param') {
            continue;
        }
        $name = trim((string)($field['field_name'] ?? ''));
        $value = trim((string)($field['field_value'] ?? ''));
        if ($name === '' || $value === '') {
            continue;
        }
        $out[] = [
            'marketplace' => $kind === 'wb_param' ? 'wildberries' : 'ozon',
            'name' => $name,
            'value' => $value,
        ];
    }
    return $out;
}

function supplier_products_db_normalize_feature_candidate(string $value): string
{
    $value = html_entity_decode($value, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $value = preg_replace('~^\s*(?:[-*]|\x{2022}|\d+\)(?:\s+|$)|\d+\.(?!\d)(?:\s+|$))~u', '', (string)$value);
    $value = trim((string)$value);
    if (preg_match('~^[\"\'`«»“”„](.+)[\"\'`«»“”„]$~us', $value, $m)) {
        $value = trim((string)$m[1]);
    }
    $value = preg_replace('~^[\.,;:!\?\(\)\[\]\{\}<>]+|[\.,;:!\?\(\)\[\]\{\}<>]+$~u', '', $value);
    $value = trim((string)$value);
    $value = preg_replace('~\s+~u', ' ', $value);
    $value = supplier_products_normalize_feature_value((string)$value);
    if ($value === '') {
        return '';
    }
    if (mb_strlen($value, 'UTF-8') > 80) {
        $value = rtrim(mb_substr($value, 0, 80, 'UTF-8'), " \t\n\r\0\x0B.,;:-");
    }
    return $value;
}

function supplier_products_db_product_feature_values(array $fields): array
{
    $out = [];
    $seen = [];
    foreach ($fields as $field) {
        if ((string)($field['field_kind'] ?? '') !== 'feature') {
            continue;
        }
        $value = supplier_products_db_normalize_feature_candidate((string)($field['field_value'] ?? ''));
        if ($value === '' || supplier_products_db_feature_is_weak($value)) {
            continue;
        }
        $key = supplier_products_db_attr_norm($value);
        if ($key === '' || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $out[] = $value;
        if (count($out) >= SUPPLIER_PRODUCTS_FEATURE_MAX) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_cover_features_preflight(array $cfg, array $ds, array $params): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    $selectedRequested = count((array)($params['offer_ids'] ?? []));
    $scope = $selectedRequested > 0 ? 'selected' : 'all';

    $total = count($products);
    $withFeatures = 0;
    $missingFeatures = 0;
    $withCoverDesign = 0;
    $missingCoverDesign = 0;
    $readyProducts = 0;
    $missingExamples = [];
    foreach ($products as $product) {
        $productId = (int)($product['id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        $fields = $fieldsByProduct[$productId] ?? [];
        $features = supplier_products_db_product_feature_values($fields);
        $hasFeatures = !empty($features);
        $categoryPayload = supplier_products_db_cover_category_payload($product, $fields);
        $hasCoverDesign = trim((string)($categoryPayload['cover_design'] ?? '')) !== '';
        if ($hasFeatures) {
            $withFeatures++;
        } else {
            $missingFeatures++;
        }
        if ($hasCoverDesign) {
            $withCoverDesign++;
        } else {
            $missingCoverDesign++;
        }
        if ($hasFeatures && $hasCoverDesign) {
            $readyProducts++;
            continue;
        }
        if (count($missingExamples) < 12) {
            $reason = [];
            if (!$hasFeatures) {
                $reason[] = 'no_features';
            }
            if (!$hasCoverDesign) {
                $reason[] = 'no_cover_design';
            }
            $missingExamples[] = [
                'product_id' => $productId,
                'offer_id' => (string)($product['offer_id'] ?? ''),
                'name' => (string)($product['name'] ?? ''),
                'missing_reason' => implode(',', $reason),
            ];
        }
    }

    $isSingle = $total === 1 || $selectedRequested === 1;
    $blocked = $total <= 0 || $readyProducts <= 0 || ($isSingle && ($missingFeatures > 0 || $missingCoverDesign > 0));
    $warning = !$blocked && ($missingFeatures > 0 || $missingCoverDesign > 0);
    if ($total <= 0) {
        $message = 'Нет товаров для запуска операции генерации обложек.';
    } elseif ($isSingle && $missingFeatures > 0 && $missingCoverDesign > 0) {
        $message = 'У выбранного товара не заполнены фишки и нет описания дизайна обложки в категории. Сначала заполни фишки и поле «Дизайн обложки» в категории товара.';
    } elseif ($isSingle && $missingFeatures > 0) {
        $message = 'У выбранного товара не заполнены фишки. Сначала запусти операцию «Фишки» или заполни их вручную.';
    } elseif ($isSingle && $missingCoverDesign > 0) {
        $message = 'У выбранного товара нет описания дизайна обложки в категории. Открой категорию товара и заполни поле «Дизайн обложки» или запусти «Анализ категорий».';
    } elseif ($readyProducts <= 0) {
        $parts = [];
        if ($missingFeatures > 0) {
            $parts[] = 'без фишек: ' . $missingFeatures;
        }
        if ($missingCoverDesign > 0) {
            $parts[] = 'без дизайна обложки категории: ' . $missingCoverDesign;
        }
        $message = 'Ни один товар в выбранном наборе не готов к генерации обложек (' . implode(', ', $parts) . '). Операция не будет запущена.';
    } elseif ($warning) {
        $parts = [];
        if ($missingFeatures > 0) {
            $parts[] = 'без фишек: ' . $missingFeatures;
        }
        if ($missingCoverDesign > 0) {
            $parts[] = 'без дизайна обложки категории: ' . $missingCoverDesign;
        }
        $message = 'Часть товаров не готова к генерации обложек (' . implode(', ', $parts) . '). Для них операция не запустится. Будет обработано товаров: ' . $readyProducts . ' из ' . $total . '.';
    } else {
        $message = 'Фишки и дизайн обложки заполнены у всех товаров для генерации обложек.';
    }

    return [
        'op_type' => 'gpt_generate_cover_image',
        'scope' => $scope,
        'total_products' => $total,
        'selected_requested' => $selectedRequested,
        'products_with_features' => $withFeatures,
        'products_missing_features' => $missingFeatures,
        'products_with_cover_design' => $withCoverDesign,
        'products_missing_cover_design' => $missingCoverDesign,
        'will_run_products' => $readyProducts,
        'blocked' => $blocked,
        'warning' => $warning,
        'message' => $message,
        'missing_examples' => $missingExamples,
    ];
}

function supplier_products_db_feature_values_from_llm($rawFeatures): array
{
    if (is_string($rawFeatures)) {
        $items = preg_split('~[\n\r;|]+~u', $rawFeatures) ?: [$rawFeatures];
    } elseif (is_array($rawFeatures)) {
        $items = $rawFeatures;
    } else {
        $items = [];
    }

    $out = [];
    $seen = [];
    foreach ($items as $item) {
        if (is_array($item)) {
            $item = $item['text'] ?? $item['value'] ?? $item['title'] ?? '';
        }
        $value = supplier_products_db_normalize_feature_candidate((string)$item);
        if ($value === '') {
            continue;
        }
        $key = supplier_products_db_attr_norm($value);
        if ($key === '' || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $out[] = $value;
        if (count($out) >= SUPPLIER_PRODUCTS_FEATURE_MAX) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_merge_feature_values(array $existing, array $generated): array
{
    $out = [];
    $seen = [];
    foreach ([$existing, $generated] as $group) {
        foreach ($group as $item) {
            $value = supplier_products_db_normalize_feature_candidate((string)$item);
            if ($value === '' || supplier_products_db_feature_is_weak($value)) {
                continue;
            }
            $key = supplier_products_db_attr_norm($value);
            if ($key === '' || isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;
            $out[] = $value;
            if (count($out) >= SUPPLIER_PRODUCTS_FEATURE_MAX) {
                return $out;
            }
        }
    }
    return $out;
}

function supplier_products_db_required_quality_feature_values(array $fields): array
{
    $target = supplier_products_db_attr_norm('Уровень качества запчасти');
    $out = [];
    $seen = [];
    foreach ($fields as $field) {
        if (!is_array($field)) {
            continue;
        }
        $kind = (string)($field['field_kind'] ?? '');
        if ($kind === 'feature') {
            continue;
        }
        $name = trim((string)($field['field_name'] ?? ''));
        $value = supplier_products_db_normalize_feature_candidate((string)($field['field_value'] ?? ''));
        if ($name === '' || $value === '') {
            continue;
        }
        if (supplier_products_db_attr_norm($name) !== $target) {
            continue;
        }
        $key = supplier_products_db_attr_norm($value);
        if ($key === '' || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $out[] = $value;
        if (count($out) >= SUPPLIER_PRODUCTS_FEATURE_MAX) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_feature_category_text(array $product, array $category): string
{
    $parts = [
        (string)($product['category_path'] ?? ''),
        (string)($product['ozon_category'] ?? ''),
        (string)($product['wb_category'] ?? ''),
        (string)($category['ozon_category'] ?? ''),
        (string)($category['wildberries_category'] ?? ''),
    ];

    $supplier = is_array($category['supplier'] ?? null) ? $category['supplier'] : [];
    $parts[] = (string)($supplier['path'] ?? '');

    $marketplace = is_array($category['marketplace'] ?? null) ? $category['marketplace'] : [];
    foreach (['name', 'full_path', 'description', 'typical_goods', 'features'] as $key) {
        $parts[] = (string)($marketplace[$key] ?? '');
    }

    return implode("\n", array_values(array_filter(array_map(
        static fn($value): string => trim((string)$value),
        $parts
    ))));
}

function supplier_products_db_feature_direct_category_text(array $product, array $category): string
{
    $parts = [
        (string)($product['name'] ?? ''),
        (string)($product['category_path'] ?? ''),
        (string)($product['ozon_category'] ?? ''),
        (string)($product['wb_category'] ?? ''),
        (string)($category['ozon_category'] ?? ''),
        (string)($category['wildberries_category'] ?? ''),
    ];

    $supplier = is_array($category['supplier'] ?? null) ? $category['supplier'] : [];
    $parts[] = (string)($supplier['path'] ?? '');

    $marketplace = is_array($category['marketplace'] ?? null) ? $category['marketplace'] : [];
    foreach (['name', 'full_path'] as $key) {
        $parts[] = (string)($marketplace[$key] ?? '');
    }

    return implode("\n", array_values(array_filter(array_map(
        static fn($value): string => trim((string)$value),
        $parts
    ))));
}

function supplier_products_db_is_electronics_spare_category(array $product, array $category): bool
{
    // Only direct taxonomy/product labels are reliable here. Category analysis text can
    // mention adjacent goods such as batteries or spare parts and must not turn a
    // complete product (for example a quadcopter) into an accessory.
    $text = supplier_products_db_feature_direct_category_text($product, $category);
    $text = supplier_products_db_attr_norm($text);
    if ($text === '') {
        return false;
    }

    $electronics = (bool)preg_match(
        '~электрон|гаджет|смартфон|телефон|планшет|ноутбук|macbook|компьютер|монитор|телевиз|tv|смарт\s*час|iphone|ipad|apple|xiaomi|redmi|samsung|huawei|honor|oppo|vivo|realme|alcatel|nokia|sony|lg|asus|acer|lenovo|meizu|playstation|xbox|приставк~u',
        $text
    );
    $spare = (bool)preg_match(
        '~запчаст|запасн|ремонт|аккумулятор|батаре|диспле|экран|тачскрин|шлейф|модул|крышк|корпус|разъем|динамик|микрофон|камер|антенн|кнопк|стекл|матриц|плат[аы]|адаптер|зарядн~u',
        $text
    );

    return $electronics && $spare;
}

function supplier_products_db_feature_field_value_by_names(array $fields, array $names): string
{
    $targets = [];
    foreach ($names as $name) {
        $norm = supplier_products_db_attr_norm((string)$name);
        if ($norm !== '') {
            $targets[$norm] = true;
        }
    }
    if (!$targets) {
        return '';
    }

    foreach ($fields as $field) {
        if (!is_array($field)) {
            continue;
        }
        $name = supplier_products_db_attr_norm((string)($field['field_name'] ?? ''));
        if ($name === '' || !isset($targets[$name])) {
            continue;
        }
        $value = trim((string)($field['field_value'] ?? ''));
        if ($value !== '') {
            return $value;
        }
    }
    return '';
}

function supplier_products_db_feature_is_code_like_model(string $value): bool
{
    $value = trim($value);
    if ($value === '') {
        return true;
    }
    $norm = supplier_products_db_attr_norm($value);
    if ($norm === '') {
        return true;
    }
    if (preg_match('~^\d{3,}(?:__\d+)?$~u', $norm)) {
        return true;
    }
    if (preg_match('~^(?:нет|не указано|без модели|универсальный|разные|прочие)$~u', $norm)) {
        return true;
    }
    return false;
}

function supplier_products_db_feature_product_model_values(array $product, array $fields): array
{
    $values = [];
    foreach ([
        supplier_products_db_feature_field_value_by_names($fields, ['same_model', 'Модель товара']),
        supplier_products_db_feature_field_value_by_names($fields, ['Версия', 'Модель', 'Название модели']),
        (string)($product['model'] ?? ''),
    ] as $value) {
        $value = supplier_products_db_normalize_feature_candidate((string)$value);
        if ($value === '' || supplier_products_db_feature_is_code_like_model($value)) {
            continue;
        }
        $key = supplier_products_db_attr_norm($value);
        if ($key !== '') {
            $values[$key] = $value;
        }
    }
    return array_values($values);
}

function supplier_products_db_feature_product_role_context(array $product, array $fields, array $category): array
{
    $direct = supplier_products_db_feature_direct_category_text($product, $category);
    $directNorm = supplier_products_db_attr_norm($direct);
    $productNameNorm = supplier_products_db_attr_norm((string)($product['name'] ?? ''));
    $supplier = is_array($category['supplier'] ?? null) ? $category['supplier'] : [];
    $marketplace = is_array($category['marketplace'] ?? null) ? $category['marketplace'] : [];
    $categoryNorm = supplier_products_db_attr_norm(
        (string)($product['category_path'] ?? '') . ' ' .
        (string)($category['ozon_category'] ?? '') . ' ' .
        (string)($category['wildberries_category'] ?? '') . ' ' .
        (string)($supplier['path'] ?? '') . ' ' .
        (string)($marketplace['name'] ?? '') . ' ' .
        (string)($marketplace['full_path'] ?? '')
    );

    $isElectronicsSpare = supplier_products_db_is_electronics_spare_category($product, $category);
    $batteryPattern = '~аккумулятор|акб|батаре|battery|lipo|lihv|lifepo|li ion|liion|li polymer~u';
    $dronePattern = '~квадрокоптер|дрон|fpv|tiny whoop|радиоуправляем~u';

    $nameLooksBattery = (bool)preg_match($batteryPattern, $productNameNorm);
    $categoryLooksBattery = (bool)preg_match($batteryPattern, $categoryNorm);
    $looksDrone = (bool)preg_match($dronePattern, $directNorm);
    $isBatteryProduct = ($nameLooksBattery || $categoryLooksBattery) && !($looksDrone && !$nameLooksBattery && !$categoryLooksBattery);

    $kind = 'product';
    if ($isBatteryProduct) {
        $kind = 'battery';
    } elseif ($isElectronicsSpare) {
        $kind = 'electronics_spare';
    } elseif ($looksDrone) {
        $kind = 'drone';
    }

    return [
        'kind' => $kind,
        'is_battery_product' => $isBatteryProduct,
        'is_spare_or_accessory' => $isElectronicsSpare,
        'avoid_self_compatibility' => !$isElectronicsSpare,
        'product_models' => supplier_products_db_feature_product_model_values($product, $fields),
        'direct_category_text' => supplier_products_db_description_snippet($direct, 700),
    ];
}

function supplier_products_db_feature_clean_compatibility_model(string $value): string
{
    $value = supplier_products_db_plain_text($value);
    $value = html_entity_decode($value, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $value = str_replace(["\xC2\xA0", '•', '·', '—'], [' ', ' ', ' ', '-'], $value);
    $value = preg_replace('~\s+~u', ' ', (string)$value);
    $value = trim((string)$value);
    if ($value === '') {
        return '';
    }

    $value = preg_replace('~^(?:совместим(?:ость|ые|ая|о|ы)?(?:\s+с)?(?:\s+модел(?:ью|ями|и))?|подходит\s+для(?:\s+модел(?:и|ей))?|для\s+модел(?:и|ей)|модель\s+(?:устройства|телефона|планшета)|модели?)\s*[:=\-]?\s*~iu', '', $value) ?? $value;
    $value = trim($value);
    if ($value === '') {
        return '';
    }

    $value = preg_replace('~\s+(?:и\s+др\.?|и\s+другие|etc\.?)$~iu', '', $value) ?? $value;
    $value = preg_replace('~\b(?:емкость|ёмкость)\s*[:=\-]?\s*\d{2,6}\s*(?:мАч|mAh|mah)\b.*$~iu', '', $value) ?? $value;
    $value = preg_replace('~\b(?:цена|остаток|наличие|vendorCode|offer_id)\b.*$~iu', '', $value) ?? $value;
    $value = trim($value, " \t\n\r\0\x0B.,;:-/");
    if ($value === '') {
        return '';
    }

    $firstLine = preg_split('~[\r\n]+~u', $value, 2)[0] ?? $value;
    $value = trim((string)$firstLine);

    $withoutDates = trim((string)(preg_replace('~\s*\([^)]*(?:,|19\d{2}|20\d{2}|mid|год|orig)[^)]*\)\s*~iu', ' ', $value) ?? $value));
    $withoutDates = preg_replace('~\s+~u', ' ', $withoutDates) ?? $withoutDates;
    if ($withoutDates !== '' && mb_strlen($withoutDates, 'UTF-8') >= 4) {
        $value = $withoutDates;
    }

    if (mb_strlen($value, 'UTF-8') > 56) {
        $withoutParen = trim((string)(preg_replace('~\s*\([^)]{8,}\)\s*~u', ' ', $value) ?? $value));
        $withoutParen = preg_replace('~\s+~u', ' ', $withoutParen) ?? $withoutParen;
        if ($withoutParen !== '' && mb_strlen($withoutParen, 'UTF-8') >= 4) {
            $value = $withoutParen;
        }
    }
    if (mb_strlen($value, 'UTF-8') > 56) {
        $split = preg_split('~\s*(?:/|,|;|\|)\s*~u', $value, 3);
        $first = trim((string)($split[0] ?? ''));
        if ($first !== '' && mb_strlen($first, 'UTF-8') >= 4) {
            $value = $first;
        }
    }
    if (mb_strlen($value, 'UTF-8') > 56) {
        $value = rtrim(mb_substr($value, 0, 56, 'UTF-8'), " \t\n\r\0\x0B.,;:-/");
    }
    $value = trim((string)(preg_replace('~\s*\([^)]*$~u', '', $value) ?? $value));
    $value = trim((string)(preg_replace('~\b(?:early|mid|late)\s+20\d{2}\b(?:\s*,\s*(?:early|mid|late)\s+20\d{2}\b)*~iu', '', $value) ?? $value));
    $value = trim((string)(preg_replace('~\b20\d{2}\s*(?:г\.?|год[ау]?)\b~iu', '', $value) ?? $value));
    $value = trim((string)(preg_replace('~\s+(?:черн(?:ый|ая|ое)|бел(?:ый|ая|ое)|син(?:ий|яя|ее)|красн(?:ый|ая|ое)|зелен(?:ый|ая|ое)|сер(?:ый|ая|ое)|розов(?:ый|ая|ое)|золот(?:ой|ая|ое)|серебрист(?:ый|ая|ое)|фиолетов(?:ый|ая|ое)|желт(?:ый|ая|ое)|коричнев(?:ый|ая|ое)|black|white|blue|red|green|pink|gold|silver)$~iu', '', $value) ?? $value));
    $value = trim((string)(preg_replace('~\s{2,}~u', ' ', $value) ?? $value), " \t\n\r\0\x0B.,;:-/");

    $norm = supplier_products_db_attr_norm($value);
    if ($norm === '') {
        return '';
    }
    if (preg_match('~^(?:нет|не указано|универсальный|любой|разные|прочие|без модели)$~u', $norm)) {
        return '';
    }
    if (preg_match('~^(?:alcatel|apple|samsung|xiaomi|redmi|huawei|honor|oppo|vivo|realme|nokia|sony|lg|asus|acer|lenovo|meizu)$~u', $norm)) {
        return '';
    }

    $feature = preg_match('~^для\s+~iu', $value) ? $value : ('Для ' . $value);
    return supplier_products_db_normalize_feature_candidate($feature);
}

function supplier_products_db_feature_compatibility_from_fields(array $fields): string
{
    $preferred = [];
    $fallback = [];
    foreach ($fields as $field) {
        if (!is_array($field)) {
            continue;
        }
        if ((string)($field['field_kind'] ?? '') === 'feature') {
            continue;
        }
        $name = trim((string)($field['field_name'] ?? ''));
        $value = trim((string)($field['field_value'] ?? ''));
        if ($name === '' || $value === '') {
            continue;
        }
        $nameNorm = supplier_products_db_attr_norm($name);
        if ($nameNorm === '') {
            continue;
        }
        if (preg_match('~^(?:model|модель|название модели|название модели для объединения в одну карточку|объединить в похожие товары|партномер|partnumber|код продавца|vendorcode)$~u', $nameNorm)) {
            continue;
        }

        $isModelCompatibility = (bool)preg_match('~совместим|совместимость|подходит|для модели|модель устройства|модель телефона|модель планшета~u', $nameNorm)
            && !preg_match('~бренд|производител~u', $nameNorm);
        if ($isModelCompatibility && preg_match('~модел|совместим|подходит|для~u', $nameNorm)) {
            $preferred[] = $value;
            continue;
        }
        if (preg_match('~совместим|совместимость|подходит~u', $nameNorm) && !preg_match('~бренд|производител~u', $nameNorm)) {
            $fallback[] = $value;
        }
    }

    foreach ([$preferred, $fallback] as $group) {
        foreach ($group as $value) {
            $feature = supplier_products_db_feature_clean_compatibility_model((string)$value);
            if ($feature !== '') {
                return $feature;
            }
        }
    }
    return '';
}

function supplier_products_db_feature_compatibility_from_text(string $text): string
{
    $plain = supplier_products_db_plain_text($text);
    $plain = str_replace("\xC2\xA0", ' ', $plain);
    $plain = preg_replace('~\s+~u', ' ', (string)$plain);
    $plain = trim((string)$plain);
    if ($plain === '') {
        return '';
    }

    $patterns = [
        '~(?:совместим(?:ость|ые|ая|о|ы)?(?:\s+с)?(?:\s+модел(?:ью|ями|и))?|подходит\s+для(?:\s+модел(?:и|ей))?|для\s+модел(?:и|ей))\s*[:=\-]?\s*([^.;\n]{3,160})~iu',
        '~(?:аккумулятор|батаре[яи]|дисплей|экран|тачскрин|шлейф|модул[ьи]?|камера|крышка|корпус|разъем|динамик|микрофон|антенна|кнопка|стекло|матрица)\s+для\s+([^.;\n]{3,180})~iu',
    ];
    foreach ($patterns as $pattern) {
        if (!preg_match($pattern, $plain, $m)) {
            continue;
        }
        $feature = supplier_products_db_feature_clean_compatibility_model((string)$m[1]);
        if ($feature !== '') {
            return $feature;
        }
    }
    return '';
}

function supplier_products_db_required_electronics_spare_compatibility_feature_values(array $product, array $fields, array $category): array
{
    if (!supplier_products_db_is_electronics_spare_category($product, $category)) {
        return [];
    }

    $feature = supplier_products_db_feature_compatibility_from_fields($fields);
    if ($feature === '') {
        $feature = supplier_products_db_feature_compatibility_from_text((string)($product['name'] ?? ''));
    }
    if ($feature === '') {
        $feature = supplier_products_db_feature_compatibility_from_text((string)($product['description_html'] ?? ''));
    }
    return $feature !== '' ? [$feature] : [];
}

function supplier_products_db_features_contain_value(array $features, string $required): bool
{
    $requiredKey = supplier_products_db_attr_norm($required);
    if ($requiredKey === '') {
        return true;
    }
    foreach ($features as $feature) {
        if (supplier_products_db_attr_norm((string)$feature) === $requiredKey) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_features_missing_required(array $features, array $required): array
{
    $missing = [];
    foreach ($required as $value) {
        $value = supplier_products_db_normalize_feature_candidate((string)$value);
        if ($value === '') {
            continue;
        }
        if (!supplier_products_db_features_contain_value($features, $value)) {
            $missing[] = $value;
        }
    }
    return supplier_products_db_merge_feature_values([], $missing);
}

function supplier_products_db_force_required_feature_values(array $features, array $required): array
{
    $out = supplier_products_db_merge_feature_values([], $features);
    $required = supplier_products_db_merge_feature_values([], $required);
    if (!$required) {
        return $out;
    }

    foreach ($required as $value) {
        if (supplier_products_db_features_contain_value($out, $value)) {
            continue;
        }
        if (count($out) < SUPPLIER_PRODUCTS_FEATURE_MAX) {
            $out[] = $value;
            continue;
        }

        $replaceIndex = count($out) - 1;
        for ($i = count($out) - 1; $i >= 0; $i--) {
            $isRequiredSlot = false;
            foreach ($required as $req) {
                if (supplier_products_db_features_contain_value([$out[$i]], $req)) {
                    $isRequiredSlot = true;
                    break;
                }
            }
            if (!$isRequiredSlot) {
                $replaceIndex = $i;
                break;
            }
        }
        $out[$replaceIndex] = $value;
        $out = supplier_products_db_merge_feature_values([], $out);
    }

    return array_slice($out, 0, SUPPLIER_PRODUCTS_FEATURE_MAX);
}

function supplier_products_db_feature_text_sources(array $product, array $fields): array
{
    $texts = [
        (string)($product['name'] ?? ''),
        supplier_products_db_plain_text((string)($product['description_html'] ?? '')),
        (string)($product['category_path'] ?? ''),
    ];
    foreach ($fields as $field) {
        $kind = (string)($field['field_kind'] ?? '');
        if ($kind !== 'param' && $kind !== 'wb_param') {
            continue;
        }
        $name = trim((string)($field['field_name'] ?? ''));
        $value = trim((string)($field['field_value'] ?? ''));
        if ($name === '' || $value === '') {
            continue;
        }
        $texts[] = $name . ': ' . $value;
    }
    return array_values(array_filter(array_map(
        static fn($text): string => trim((string)$text),
        $texts
    )));
}

function supplier_products_db_feature_add_hint(array &$hints, string $type, string $value, int $rank): void
{
    $value = supplier_products_db_normalize_feature_candidate($value);
    if ($value === '') {
        return;
    }
    $key = $type . "\n" . supplier_products_db_attr_norm($value);
    if (isset($hints[$key])) {
        return;
    }
    $hints[$key] = [
        'type' => $type,
        'value' => $value,
        'rank' => $rank,
    ];
}

function supplier_products_db_feature_hints(array $product, array $fields, array $roleContext = []): array
{
    $hints = [];
    $text = implode("\n", supplier_products_db_feature_text_sources($product, $fields));
    $text = str_replace("\xC2\xA0", ' ', $text);

    if (preg_match_all('~(?<![\p{L}\p{N}])(\d{2,6})\s*(?:мАч|mAh|mah|мач)(?![\p{L}\p{N}])~iu', $text, $m, PREG_SET_ORDER)) {
        foreach ($m as $row) {
            supplier_products_db_feature_add_hint($hints, 'capacity', (string)$row[1] . ' мАч', 10);
        }
    }
    if (preg_match_all('~(?<![\p{L}\p{N}])(\d{1,3}(?:[\.,]\d{1,2})?)\s*(?:В|V)(?![\p{L}\p{N}])~iu', $text, $m, PREG_SET_ORDER)) {
        foreach ($m as $row) {
            $num = str_replace(',', '.', (string)$row[1]);
            supplier_products_db_feature_add_hint($hints, 'voltage', $num . ' В', 20);
        }
    }
    if (preg_match_all('~(?<![\p{L}\p{N}])([1-9]\d?)\s*S(?![\p{L}\p{N}])~iu', $text, $m, PREG_SET_ORDER)) {
        foreach ($m as $row) {
            supplier_products_db_feature_add_hint($hints, 'cells', strtoupper((string)$row[1]) . 'S', 50);
        }
    }
    if (preg_match_all('~(?<![\p{L}\p{N}])(\d{1,3})\s*[CcСс](?![\p{L}\p{N}])~u', $text, $m, PREG_SET_ORDER)) {
        foreach ($m as $row) {
            supplier_products_db_feature_add_hint($hints, 'c_rating', (string)$row[1] . 'C', 40);
        }
    }

    $batteryType = '';
    if (preg_match('~(?<![\p{L}\p{N}])(LiPo|LiHV|LiFe|Li[-\s]?Ion|литий[-\s]?полимерн\w*|литий[-\s]?ионн\w*)(?![\p{L}\p{N}])~iu', $text, $m)) {
        $raw = supplier_products_db_attr_norm((string)$m[1]);
        if (str_contains($raw, 'полимер') || str_contains($raw, 'lipo')) {
            $batteryType = 'LiPo';
        } elseif (str_contains($raw, 'lihv')) {
            $batteryType = 'LiHV';
        } elseif (str_contains($raw, 'life')) {
            $batteryType = 'LiFe';
        } elseif (str_contains($raw, 'ион') || str_contains($raw, 'li ion') || str_contains($raw, 'liion')) {
            $batteryType = 'Li-ion';
        }
        if ($batteryType !== '') {
            supplier_products_db_feature_add_hint($hints, 'battery_type', $batteryType, 70);
        }
    }

    $connectorPatterns = [
        'XT30' => '~(?<![\p{L}\p{N}])XT[-\s]?30(?![\p{L}\p{N}])~iu',
        'XT60' => '~(?<![\p{L}\p{N}])XT[-\s]?60(?![\p{L}\p{N}])~iu',
        'XT90' => '~(?<![\p{L}\p{N}])XT[-\s]?90(?![\p{L}\p{N}])~iu',
        'JST' => '~(?<![\p{L}\p{N}])JST(?![\p{L}\p{N}])~iu',
        'PH2.0' => '~(?<![\p{L}\p{N}])PH[-\s]?2\.?0(?![\p{L}\p{N}])~iu',
        'BT2.0' => '~(?<![\p{L}\p{N}])BT[-\s]?2\.?0(?![\p{L}\p{N}])~iu',
        'EC3' => '~(?<![\p{L}\p{N}])EC[-\s]?3(?![\p{L}\p{N}])~iu',
        'EC5' => '~(?<![\p{L}\p{N}])EC[-\s]?5(?![\p{L}\p{N}])~iu',
    ];
    foreach ($connectorPatterns as $label => $pattern) {
        if (preg_match($pattern, $text)) {
            supplier_products_db_feature_add_hint($hints, 'connector', $label, 30);
        }
    }

    $cells = [];
    foreach ($hints as $hint) {
        if (($hint['type'] ?? '') === 'cells') {
            $cells[] = (string)($hint['value'] ?? '');
        }
    }
    if ($batteryType !== '' && $cells) {
        supplier_products_db_feature_add_hint($hints, 'type_cells', $batteryType . ' ' . $cells[0], 45);
    }

    $items = array_values($hints);
    usort($items, static function (array $a, array $b): int {
        $rankCmp = ((int)($a['rank'] ?? 999)) <=> ((int)($b['rank'] ?? 999));
        if ($rankCmp !== 0) {
            return $rankCmp;
        }
        return strnatcasecmp((string)($a['value'] ?? ''), (string)($b['value'] ?? ''));
    });

    $isBattery = !empty($roleContext['is_battery_product']);
    if (!$roleContext) {
        $directText = (string)($product['name'] ?? '') . "\n" . (string)($product['category_path'] ?? '');
        $isBattery = (bool)preg_match('~аккумулятор|акб|батаре|battery|lipo|lihv|life|li[-\s]?ion~iu', $directText);
    }

    return [
        'is_battery' => $isBattery,
        'items' => $items,
    ];
}

function supplier_products_db_feature_value_role(string $value): string
{
    $value = trim($value);
    if ($value === '') {
        return '';
    }
    if (preg_match('~\d{2,6}\s*(?:мАч|mAh|mah|мач)~iu', $value)) {
        return 'capacity';
    }
    if (preg_match('~\d{1,3}(?:[\.,]\d{1,2})?\s*(?:В|V)~iu', $value)) {
        return 'voltage';
    }
    if (preg_match('~(?<![\p{L}\p{N}])(?:XT[-\s]?(?:30|60|90)|JST|PH[-\s]?2\.?0|BT[-\s]?2\.?0|EC[-\s]?[35])(?![\p{L}\p{N}])~iu', $value)) {
        return 'connector';
    }
    if (preg_match('~(?<![\p{L}\p{N}])\d{1,3}\s*[CcСс](?![\p{L}\p{N}])~u', $value)) {
        return 'c_rating';
    }
    if (preg_match('~(?:LiPo|LiHV|LiFe|Li[-\s]?Ion).*(?<![\p{L}\p{N}])[1-9]\d?\s*S(?![\p{L}\p{N}])|(?<![\p{L}\p{N}])[1-9]\d?\s*S(?![\p{L}\p{N}]).*(?:LiPo|LiHV|LiFe|Li[-\s]?Ion)~iu', $value)) {
        return 'type_cells';
    }
    if (preg_match('~(?<![\p{L}\p{N}])[1-9]\d?\s*S(?![\p{L}\p{N}])~iu', $value)) {
        return 'cells';
    }
    if (preg_match('~(?<![\p{L}\p{N}])(?:LiPo|LiHV|LiFe|Li[-\s]?Ion)(?![\p{L}\p{N}])~iu', $value)) {
        return 'battery_type';
    }
    return '';
}

function supplier_products_db_feature_is_weak(string $value): bool
{
    $key = supplier_products_db_attr_norm($value);
    if ((bool)preg_match('~^1\s*(?:шт|штука|штуки|штук|pcs|pc)$~iu', $key)) {
        return true;
    }
    return supplier_products_db_feature_is_bare_dimension($value);
}

function supplier_products_db_feature_is_bare_dimension(string $value): bool
{
    $value = trim(str_replace(["\xC2\xA0", '×'], [' ', 'x'], $value));
    if ($value === '') {
        return false;
    }
    $lower = mb_strtolower($value, 'UTF-8');
    $lower = str_replace('ё', 'е', $lower);
    $lower = preg_replace('~\s+~u', ' ', (string)$lower);
    $lower = trim((string)$lower);
    $withoutLabel = preg_replace('~^(?:размер|размеры|габарит|габариты|длина|ширина|высота|толщина|диаметр)\s*[:=\-]?\s*~u', '', $lower) ?? $lower;
    $withoutLabel = trim($withoutLabel);

    if (preg_match('~^\d+(?:[\.,]\d+)?\s*x\s*\d+(?:[\.,]\d+)?(?:\s*x\s*\d+(?:[\.,]\d+)?)?\s*(?:мм|см|м|mm|cm|m)?$~iu', $withoutLabel)) {
        return true;
    }
    if (preg_match('~^\d+(?:[\.,]\d+)?\s*(?:мм|см|м|mm|cm|m)$~iu', $withoutLabel)) {
        return true;
    }
    if (preg_match('~^(?:длина|ширина|высота|толщина|диаметр)\s+\d+(?:[\.,]\d+)?\s*(?:мм|см|м|mm|cm|m)$~iu', $lower)) {
        return true;
    }
    return false;
}

function supplier_products_db_feature_is_bare_dimension_attribute(string $name): bool
{
    $key = supplier_products_db_attr_norm($name);
    return in_array($key, [
        'length',
        'width',
        'height',
        'dimensions',
        'dimension',
        'длина',
        'ширина',
        'высота',
        'габариты',
        'габарит',
        'размеры',
        'размер',
    ], true);
}

function supplier_products_db_feature_payload_fields(array $fields): array
{
    $out = [];
    foreach ($fields as $name => $value) {
        $name = trim((string)$name);
        $value = trim((string)$value);
        if ($name === '' || $value === '' || supplier_products_db_feature_is_bare_dimension_attribute($name)) {
            continue;
        }
        $out[$name] = $value;
    }
    return $out;
}

function supplier_products_db_feature_payload_params(array $params): array
{
    $out = [];
    foreach ($params as $param) {
        if (!is_array($param)) {
            continue;
        }
        if (supplier_products_db_feature_is_bare_dimension_attribute((string)($param['name'] ?? ''))) {
            continue;
        }
        $out[] = $param;
    }
    return $out;
}

function supplier_products_db_feature_candidate_attr_excluded(string $name): bool
{
    $key = supplier_products_db_attr_norm($name);
    if ($key === '') {
        return true;
    }
    if (supplier_products_db_feature_is_bare_dimension_attribute($name)) {
        return true;
    }
    if (preg_match('~(?:гарант|срок службы|срок годности|возраст|тн вэд|тнвэд|код продавца|vendorcode|артикул|партномер|страна|опасност|количество товара в уеи|минимальное количество|остаток|наличие|цена|вес с упаковкой|вес товара с упаковкой)~u', $key)) {
        return true;
    }
    if (preg_match('~^(?:model|модель|название модели|название модели для объединения в одну карточку|объединить в похожие товары|описание|краткое описание)$~u', $key)) {
        return true;
    }
    return false;
}

function supplier_products_db_feature_candidate_from_param(string $name, string $value, array $roleContext): string
{
    $name = trim($name);
    $value = supplier_products_db_normalize_feature_candidate($value);
    if ($name === '' || $value === '' || supplier_products_db_feature_candidate_attr_excluded($name)) {
        return '';
    }

    $key = supplier_products_db_attr_norm($name);
    $valueNorm = supplier_products_db_attr_norm($value);
    if ($valueNorm === '' || preg_match('~^(?:нет|не указано|не требуется|false|0)$~u', $valueNorm)) {
        return '';
    }

    if (preg_match('~(?:приемник|приёмник|протокол приемника|протокол приёмника|беспроводные интерфейсы)~u', $key)) {
        return $value;
    }
    if (preg_match('~видеопередача|тип видеопередачи|fpv~u', $key)) {
        return preg_match('~аналог~u', $valueNorm) ? 'Аналоговая FPV' : $value;
    }
    if (preg_match('~тип fpv дрона|тип дрона~u', $key)) {
        return mb_convert_case($value, MB_CASE_TITLE, 'UTF-8');
    }
    if (preg_match('~размер рамы~u', $key)) {
        return preg_match('~мм|mm~iu', $value) ? ('Рама ' . $value) : ('Рама ' . $value . ' мм');
    }
    if (preg_match('~размер пропеллер~u', $key)) {
        return preg_match('~пропел~iu', $value) ? $value : ('Пропеллеры ' . $value);
    }
    if (preg_match('~разъем питания|разъём питания|коннектор|разъем|разъём~u', $key)) {
        return preg_match('~^(?:BT|XT|JST|PH|EC)~iu', $value) ? $value : ('Разъем ' . $value);
    }
    if (preg_match('~^питание$|типоразмер элемента питания~u', $key)) {
        return $value;
    }
    if (preg_match('~камера|gps|стабилизац|количество моторов|дальность полета|время работы~u', $key)) {
        if (mb_strlen($value, 'UTF-8') <= 42) {
            return preg_match('~^(?:да|есть)$~u', $valueNorm) ? $name : $value;
        }
    }
    if (preg_match('~цвет|материал|тип|вид|назначение|качество|уровень качества~u', $key) && mb_strlen($value, 'UTF-8') <= 42) {
        return $value;
    }

    return '';
}

function supplier_products_db_feature_candidates(array $fields, array $roleContext): array
{
    $out = [];
    $seen = [];
    foreach ($fields as $field) {
        if (!is_array($field)) {
            continue;
        }
        $kind = (string)($field['field_kind'] ?? '');
        if (!in_array($kind, ['param', 'wb_param'], true)) {
            continue;
        }
        $name = trim((string)($field['field_name'] ?? ''));
        $value = trim((string)($field['field_value'] ?? ''));
        $candidate = supplier_products_db_feature_candidate_from_param($name, $value, $roleContext);
        if ($candidate === '' || supplier_products_db_feature_is_weak($candidate)) {
            continue;
        }
        $key = supplier_products_db_attr_norm($candidate);
        if ($key === '' || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $out[] = [
            'source' => $kind === 'wb_param' ? 'wildberries' : 'ozon',
            'name' => $name,
            'value' => supplier_products_db_normalize_feature_candidate($value),
            'candidate' => $candidate,
        ];
        if (count($out) >= 30) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_feature_matches_product_model(string $feature, array $product, array $roleContext): bool
{
    if (empty($roleContext['avoid_self_compatibility'])) {
        return false;
    }
    if (!preg_match('~^для\s+(.+)$~iu', trim($feature), $m)) {
        return false;
    }
    $target = supplier_products_db_attr_norm((string)$m[1]);
    if ($target === '') {
        return false;
    }

    foreach ((array)($roleContext['product_models'] ?? []) as $model) {
        $modelNorm = supplier_products_db_attr_norm((string)$model);
        if ($modelNorm !== '' && ($target === $modelNorm || str_contains($target, $modelNorm) || str_contains($modelNorm, $target))) {
            return true;
        }
    }

    $nameNorm = supplier_products_db_attr_norm((string)($product['name'] ?? ''));
    return $nameNorm !== '' && str_contains($nameNorm, $target);
}

function supplier_products_db_feature_is_bad_for_product(string $feature, array $product, array $roleContext): bool
{
    $feature = supplier_products_db_normalize_feature_candidate($feature);
    if ($feature === '' || supplier_products_db_feature_is_weak($feature)) {
        return true;
    }
    $key = supplier_products_db_attr_norm($feature);
    if ($key === '') {
        return true;
    }
    if (preg_match('~^(?:товар|дрон|квадрокоптер|fpv|радиоуправляемая игрушка|только дрон|только квадрокоптер)$~u', $key)) {
        return true;
    }
    if (empty($roleContext['is_battery_product']) && preg_match('~^(?:емкость\s*)?\d{2,6}\s*(?:мач|mah|м ач|мmah)$~u', $key)) {
        return true;
    }
    if (supplier_products_db_feature_matches_product_model($feature, $product, $roleContext)) {
        return true;
    }
    return false;
}

function supplier_products_db_filter_features_for_product(
    array $features,
    array $product,
    array $roleContext,
    array $required = [],
    array $candidates = []
): array {
    $out = supplier_products_db_merge_feature_values([], $required);
    foreach ($features as $feature) {
        $feature = supplier_products_db_normalize_feature_candidate((string)$feature);
        if ($feature === '' || supplier_products_db_features_contain_value($out, $feature)) {
            continue;
        }
        if (supplier_products_db_feature_is_bad_for_product($feature, $product, $roleContext)
            && !supplier_products_db_features_contain_value($required, $feature)) {
            continue;
        }
        $out = supplier_products_db_merge_feature_values($out, [$feature]);
        if (count($out) >= SUPPLIER_PRODUCTS_FEATURE_MAX) {
            return $out;
        }
    }

    foreach ($candidates as $candidate) {
        $feature = is_array($candidate)
            ? (string)($candidate['candidate'] ?? $candidate['value'] ?? '')
            : (string)$candidate;
        $feature = supplier_products_db_normalize_feature_candidate($feature);
        if ($feature === '' || supplier_products_db_features_contain_value($out, $feature)) {
            continue;
        }
        if (supplier_products_db_feature_is_bad_for_product($feature, $product, $roleContext)) {
            continue;
        }
        $out = supplier_products_db_merge_feature_values($out, [$feature]);
        if (count($out) >= SUPPLIER_PRODUCTS_FEATURE_MAX) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_feature_refine_with_hints(array $features, array $hints): array
{
    $items = (array)($hints['items'] ?? []);
    if (empty($hints['is_battery']) || !$items) {
        return supplier_products_db_merge_feature_values([], array_values(array_filter(
            $features,
            static fn($value): bool => !supplier_products_db_feature_is_weak((string)$value)
        )));
    }

    $hintByType = [];
    foreach ($items as $hint) {
        $type = (string)($hint['type'] ?? '');
        $value = supplier_products_db_normalize_feature_candidate((string)($hint['value'] ?? ''));
        if ($type === '' || $value === '' || isset($hintByType[$type])) {
            continue;
        }
        $hintByType[$type] = $value;
    }

    $canonicalGenerated = [];
    foreach ($features as $feature) {
        $feature = supplier_products_db_normalize_feature_candidate((string)$feature);
        if ($feature === '' || supplier_products_db_feature_is_weak($feature)) {
            continue;
        }
        $role = supplier_products_db_feature_value_role($feature);
        if ($role !== '' && isset($hintByType[$role])) {
            $feature = $hintByType[$role];
        } elseif ($role === 'battery_type' && isset($hintByType['type_cells'])) {
            $feature = $hintByType['type_cells'];
        }
        $canonicalGenerated[] = $feature;
    }

    $priority = [];
    foreach (['capacity', 'voltage'] as $type) {
        if (isset($hintByType[$type])) {
            $priority[] = $hintByType[$type];
        }
    }

    $out = supplier_products_db_merge_feature_values([], $priority);
    foreach ($canonicalGenerated as $feature) {
        $out = supplier_products_db_merge_feature_values($out, [$feature]);
        if (count($out) >= SUPPLIER_PRODUCTS_FEATURE_MAX) {
            return $out;
        }
    }
    foreach (['connector', 'c_rating', 'type_cells', 'cells', 'battery_type'] as $type) {
        if (!isset($hintByType[$type])) {
            continue;
        }
        $out = supplier_products_db_merge_feature_values($out, [$hintByType[$type]]);
        if (count($out) >= SUPPLIER_PRODUCTS_FEATURE_MAX) {
            return $out;
        }
    }
    return $out;
}

function supplier_products_db_attr_norm(string $s): string
{
    $s = trim($s);
    $s = str_replace(["\xC2\xA0", "\xE2\x80\x8B"], ' ', $s);
    $s = mb_strtolower($s, 'UTF-8');
    $s = str_replace('ё', 'е', $s);
    $s = preg_replace('~[^\p{L}\p{N}]+~u', ' ', $s);
    $s = preg_replace('~\s+~u', ' ', (string)$s);
    return trim((string)$s);
}

function supplier_products_db_is_ozon_fits_for_attribute(string $source, string $name): bool
{
    $source = $source === 'wb' ? 'wildberries' : trim($source);
    if ($source !== 'ozon') {
        return false;
    }
    $key = supplier_products_db_attr_norm($name);
    return in_array($key, [
        'подходит для',
        'для чего подходит',
        'для бренда',
        'совместимый бренд',
        'бренд совместимости',
    ], true);
}

function supplier_products_db_is_ozon_compatible_models_attribute(string $source, string $name): bool
{
    $source = $source === 'wb' ? 'wildberries' : trim($source);
    if ($source !== 'ozon') {
        return false;
    }
    $key = supplier_products_db_attr_norm($name);
    return in_array($key, [
        'совместимые модели',
        'совместимые модели устройства',
        'совместимые модели товара',
        'модели совместимости',
        'модель совместимости',
        'совместимость с моделями',
        'подходит для моделей',
    ], true);
}

function supplier_products_db_is_ozon_release_type_attribute(string $source, string $name): bool
{
    $source = $source === 'wb' ? 'wildberries' : trim($source);
    if ($source !== 'ozon') {
        return false;
    }
    if (function_exists('supplier_products_is_ozon_release_type_characteristic_name')) {
        return supplier_products_is_ozon_release_type_characteristic_name($name);
    }
    return supplier_products_db_attr_norm($name) === 'вид выпуска товара';
}

function supplier_products_db_ozon_release_type_allowed_values(array $values = []): array
{
    if (function_exists('supplier_products_ozon_release_type_sanitized_allowed_values')) {
        return supplier_products_ozon_release_type_sanitized_allowed_values($values);
    }
    return ['Фабричное производство', 'Ручная, авторская работа', 'По индивидуальному дизайну'];
}

function supplier_products_db_is_single_value_color_attribute_name(string $name): bool
{
    $key = supplier_products_db_attr_norm($name);
    return in_array($key, [
        'название цвета',
        'название цвета товара',
    ], true);
}

function supplier_products_db_attribute_max_values(array $attr): int
{
    foreach (['max_count', 'maxCount', 'max_values', 'maxValues'] as $key) {
        if (array_key_exists($key, $attr)) {
            $value = (int)$attr[$key];
            if ($value > 0) {
                return $value;
            }
        }
    }
    return supplier_products_db_is_single_value_color_attribute_name((string)($attr['name'] ?? '')) ? 1 : 0;
}

function supplier_products_db_attribute_source(array $attr): string
{
    $source = trim((string)($attr['source'] ?? ($attr['marketplace'] ?? '')));
    if ($source === 'wb') {
        return 'wildberries';
    }
    if ($source !== '') {
        return $source;
    }
    $marketplaces = (array)($attr['marketplaces'] ?? []);
    if (count($marketplaces) === 1) {
        $source = trim((string)$marketplaces[0]);
        return $source === 'wb' ? 'wildberries' : $source;
    }
    return '';
}

function supplier_products_db_limit_wb_characteristic_value(string $value, int $limit = 100): string
{
    if (function_exists('supplier_products_limit_wb_characteristic_value')) {
        return supplier_products_limit_wb_characteristic_value($value, $limit);
    }
    $value = trim((string)preg_replace('/\s+/u', ' ', $value));
    if ($value === '' || $limit <= 0 || mb_strlen($value, 'UTF-8') <= $limit) {
        return $value;
    }
    $cut = mb_substr($value, 0, $limit, 'UTF-8');
    $wordCut = preg_replace('/\s+\S*$/u', '', $cut);
    if (is_string($wordCut) && mb_strlen($wordCut, 'UTF-8') >= 50) {
        $cut = $wordCut;
    }
    $cut = rtrim($cut, " \t\n\r\0\x0B,;:./\\|-");
    return $cut !== '' ? $cut : mb_substr($value, 0, $limit, 'UTF-8');
}

function supplier_products_db_normalize_param_value_for_kind(string $kind, string $value): string
{
    $value = trim((string)preg_replace('/\s+/u', ' ', $value));
    if ($kind === 'wb_param') {
        $value = supplier_products_db_limit_wb_characteristic_value($value);
    }
    return $value;
}

function supplier_products_db_limit_values_for_attr(array $values, array $attr): array
{
    $isWb = supplier_products_db_attribute_source($attr) === 'wildberries';
    $values = array_values(array_filter(array_map(
        static function ($value) use ($isWb): string {
            $value = is_array($value) ? (string)($value['value'] ?? ($value['name'] ?? '')) : (string)$value;
            $value = trim((string)preg_replace('/\s+/u', ' ', $value));
            return $isWb ? supplier_products_db_limit_wb_characteristic_value($value) : $value;
        },
        $values
    ), static fn(string $value): bool => $value !== ''));

    $maxValues = supplier_products_db_attribute_max_values($attr);
    if ($maxValues <= 0 || !$values) {
        return $values;
    }

    if ($maxValues === 1) {
        foreach ($values as $value) {
            foreach (preg_split('~\s*(?:/|;|\||,|\R|\s+\+\s+|\s+и\s+)\s*~iu', (string)$value, -1, PREG_SPLIT_NO_EMPTY) ?: [] as $part) {
                $part = trim((string)preg_replace('/\s+/u', ' ', (string)$part));
                if ($part !== '') {
                    return [$part];
                }
            }
        }
        return [];
    }

    return array_slice($values, 0, $maxValues);
}

function supplier_products_db_ozon_fits_for_brand_aliases(): array
{
    return [
        'apple' => 'Apple',
        'iphone' => 'Apple',
        'ipad' => 'Apple',
        'ipod' => 'Apple',
        'macbook' => 'Apple',
        'samsung' => 'Samsung',
