function supplier_products_db_product_brand_for_fits_for(array $product, string $vendorFallback = ''): string
{
    foreach ([
        $product['brand'] ?? '',
        $product['vendor'] ?? '',
        $vendorFallback,
    ] as $candidate) {
        $candidate = trim((string)$candidate);
        if ($candidate !== '' && !supplier_products_db_brand_is_empty_like($candidate)) {
            return $candidate;
        }
    }
    return '';
}

function supplier_products_db_ozon_brand_names_for_category(string $ozonCategory): array
{
    static $cache = [];

    $ozonCategory = trim($ozonCategory);
    if ($ozonCategory === '') {
        return [];
    }
    if (array_key_exists($ozonCategory, $cache)) {
        return $cache[$ozonCategory];
    }
    if (!preg_match('~^(\d+)_(\d+)$~', $ozonCategory, $m)) {
        return $cache[$ozonCategory] = [];
    }

    try {
        marketplace_brand_dictionary_tables_ensure();
        $st = db()->prepare("
            SELECT DISTINCT b.brand_name
            FROM feedtools_ozon_brands b
            JOIN feedtools_ozon_brand_categories c ON c.brand_id = b.brand_id
            WHERE c.description_category_id = ?
              AND c.type_id IN (0, ?)
            ORDER BY CHAR_LENGTH(b.brand_name) DESC, b.brand_name ASC
            LIMIT 5000
        ");
        $st->execute([(int)$m[1], (int)$m[2]]);
        $names = [];
        while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
            $name = trim((string)($row['brand_name'] ?? ''));
            if ($name !== '') {
                $names[] = $name;
            }
        }
        return $cache[$ozonCategory] = $names;
    } catch (Throwable $e) {
        return $cache[$ozonCategory] = [];
    }
}

function supplier_products_db_normalize_ozon_fits_for_brands(
    array $rawValues,
    array $product,
    string $ozonCategory = '',
    string $vendorFallback = ''
): array {
    $fallbackBrand = supplier_products_db_product_brand_for_fits_for($product, $vendorFallback);
    $brandMap = [];
    $addBrand = static function (string $alias, string $brand) use (&$brandMap): void {
        $alias = trim((string)preg_replace('~\s+~u', ' ', $alias));
        $brand = trim((string)preg_replace('~\s+~u', ' ', $brand));
        $aliasNorm = supplier_products_db_attr_norm($alias);
        $brandNorm = supplier_products_db_attr_norm($brand);
        if ($aliasNorm !== '' && $brand !== '') {
            $brandMap[$aliasNorm] = $brand;
        }
        if ($brandNorm !== '' && $brand !== '') {
            $brandMap[$brandNorm] = $brand;
        }
    };

    foreach (supplier_products_db_ozon_brand_names_for_category($ozonCategory) as $brand) {
        $addBrand((string)$brand, (string)$brand);
    }
    foreach (supplier_products_db_ozon_fits_for_brand_aliases() as $alias => $brand) {
        $addBrand((string)$alias, (string)$brand);
    }
    if ($fallbackBrand !== '') {
        $addBrand($fallbackBrand, $fallbackBrand);
    }

    $skipBrandNorms = array_fill_keys([
        'air', 'unit', 'pro', 'mini', 'max', 'plus', 'fpv', 'hd', 'uhd', 'go', 'mi',
        'для', 'товар', 'товара', 'дрон', 'дроны', 'квадрокоптер', 'квадрокоптеры',
        'аккумулятор', 'батарея', 'контроллер', 'пульт', 'модуль', 'камера',
    ], true);

    uksort($brandMap, static function ($a, $b): int {
        return mb_strlen((string)$b, 'UTF-8') <=> mb_strlen((string)$a, 'UTF-8');
    });

    $out = [];
    $seen = [];
    $scanValues = static function (array $values) use (&$out, &$seen, $brandMap, $skipBrandNorms): void {
        foreach ($values as $raw) {
            $raw = trim((string)preg_replace('~\s+~u', ' ', (string)$raw));
            if ($raw === '') {
                continue;
            }
            $raw = (string)preg_replace(
                '~^\s*(?:подходит\s+для|совместим(?:о|а|ый|ые)?\s+(?:с|для)?|для)\s*[:\-–—]?\s*~iu',
                '',
                $raw
            );
            $rawNorm = supplier_products_db_attr_norm($raw);
            if ($rawNorm === '') {
                continue;
            }
            $haystack = ' ' . $rawNorm . ' ';
            foreach ($brandMap as $brandNorm => $brandName) {
                $brandNorm = (string)$brandNorm;
                if ($brandNorm === '' || isset($skipBrandNorms[$brandNorm])) {
                    continue;
                }
                if (preg_match('~^\d+$~u', $brandNorm) === 1) {
                    continue;
                }
                $shortBrand = mb_strlen($brandNorm, 'UTF-8') < 3;
                if ($shortBrand && $rawNorm !== $brandNorm) {
                    continue;
                }
                if (!$shortBrand && !preg_match('~(^| )' . preg_quote($brandNorm, '~') . '($| )~u', $haystack)) {
                    continue;
                }
                $key = supplier_products_db_attr_norm((string)$brandName);
                if ($key !== '' && !isset($seen[$key])) {
                    $seen[$key] = true;
                    $out[] = (string)$brandName;
                }
                if (count($out) >= 6) {
                    return;
                }
            }
        }
    };

    $scanValues($rawValues);

    if (!$out) {
        $productHints = [];
        foreach (['name', 'source_line', 'model', 'description'] as $key) {
            $value = trim((string)($product[$key] ?? ''));
            if ($value !== '') {
                $productHints[] = mb_substr($value, 0, 1600, 'UTF-8');
            }
        }
        foreach ((array)($product['params'] ?? []) as $param) {
            if (!is_array($param)) {
                continue;
            }
            $name = trim((string)($param['name'] ?? ''));
            $value = trim((string)($param['value'] ?? ''));
            if ($name !== '' || $value !== '') {
                $productHints[] = trim($name . ': ' . $value);
            }
            if (count($productHints) >= 80) {
                break;
            }
        }
        $scanValues($productHints);
    }

    if (!$out && $fallbackBrand !== '') {
        $out[] = $fallbackBrand;
    }
    return $out;
}

function supplier_products_db_join_ozon_fits_for_values(array $values): string
{
    $out = [];
    $seen = [];
    foreach ($values as $value) {
        $value = trim((string)preg_replace('~\s+~u', ' ', (string)$value));
        $key = supplier_products_db_attr_norm($value);
        if ($value === '' || $key === '' || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $out[] = $value;
    }
    return implode('; ', $out);
}

function supplier_products_db_ozon_clean_compatible_model_value(string $value, array $knownBrands = []): string
{
    $value = supplier_products_db_plain_text($value);
    $value = html_entity_decode($value, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $value = str_replace(["\xC2\xA0", '•', '·', '—'], [' ', ' ', ' ', '-'], $value);
    $value = preg_replace('~\s+~u', ' ', (string)$value);
    $value = trim((string)$value, " \t\n\r\0\x0B.,;:-/");
    if ($value === '') {
        return '';
    }
    $value = preg_replace(
        '~^(?:для|подходит\s+для|совместим(?:о|а|ый|ые)?\s+(?:с|для)?|модели?|совместимые\s+модели)\s*[:=\-]?\s*~iu',
        '',
        $value
    ) ?? $value;
    $value = trim((string)$value, " \t\n\r\0\x0B.,;:-/");

    $brands = [];
    foreach ($knownBrands as $brand) {
        $brand = trim((string)$brand);
        if ($brand !== '') {
            $brands[] = $brand;
        }
    }
    foreach (['Apple', 'Samsung', 'Xiaomi', 'Huawei', 'Honor', 'OPPO', 'Realme', 'OnePlus', 'Vivo', 'Nokia', 'Sony', 'Google', 'Motorola', 'Tecno', 'Infinix', 'ASUS', 'Lenovo', 'ZTE'] as $brand) {
        $brands[] = $brand;
    }
    usort($brands, static fn(string $a, string $b): int => mb_strlen($b, 'UTF-8') <=> mb_strlen($a, 'UTF-8'));
    foreach (array_values(array_unique($brands)) as $brand) {
        $brand = trim($brand);
        if ($brand === '') {
            continue;
        }
        $value = preg_replace('~^\s*' . preg_quote($brand, '~') . '\s+~iu', '', $value) ?? $value;
    }

    $value = preg_replace('~\s+(?:и\s+др\.?|и\s+другие|etc\.?)$~iu', '', (string)$value) ?? $value;
    $value = preg_replace('~\b(?:емкость|ёмкость)\s*[:=\-]?\s*\d{2,6}\s*(?:мАч|mAh|mah)\b.*$~iu', '', (string)$value) ?? $value;
    $value = trim((string)(preg_replace('~\s+~u', ' ', (string)$value) ?? $value), " \t\n\r\0\x0B.,;:-/");
    if ($value === '' || mb_strlen($value, 'UTF-8') < 2) {
        return '';
    }
    if (preg_match('~^(?:нет|не указано|универсальный|любой|разные|прочие|без модели)$~iu', $value)) {
        return '';
    }
    return mb_substr($value, 0, 120, 'UTF-8');
}

function supplier_products_db_ozon_compatible_models_from_product(array $product, array $fields): array
{
    $knownBrands = [];
    foreach ([
        (string)($product['brand'] ?? ''),
        (string)($product['vendor'] ?? ''),
    ] as $brand) {
        if (trim($brand) !== '') {
            $knownBrands[] = trim($brand);
        }
    }

    $raw = [];
    $fromFields = supplier_products_db_feature_compatibility_from_fields($fields);
    if ($fromFields !== '') {
        $raw[] = $fromFields;
    }
    foreach ([(string)($product['name'] ?? ''), (string)($product['description_html'] ?? ($product['description'] ?? ''))] as $text) {
        $fromText = supplier_products_db_feature_compatibility_from_text($text);
        if ($fromText !== '') {
            $raw[] = $fromText;
        }
    }
    foreach ($fields as $field) {
        if (!is_array($field)) {
            continue;
        }
        $name = supplier_products_db_attr_norm((string)($field['field_name'] ?? ''));
        $value = trim((string)($field['field_value'] ?? ''));
        if ($value === '' || $name === '') {
            continue;
        }
        if (preg_match('~(?:совместим|подходит|для модели|модель телефона|модель устройства|модель планшета)~u', $name)
            && !preg_match('~(?:бренд|производител)~u', $name)
        ) {
            $raw[] = $value;
        }
    }

    $out = [];
    $seen = [];
    foreach ($raw as $value) {
        foreach (preg_split('~\s*(?:;|\||\R)\s*~u', (string)$value, -1, PREG_SPLIT_NO_EMPTY) ?: [] as $part) {
            $clean = supplier_products_db_ozon_clean_compatible_model_value((string)$part, $knownBrands);
            $key = supplier_products_db_attr_norm($clean);
            if ($clean === '' || $key === '' || isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;
            $out[] = $clean;
            if (count($out) >= 20) {
                return $out;
            }
        }
    }
    return $out;
}

function supplier_products_db_attr_alias_names(string $name): array
{
    $name = trim($name);
    $names = [];
    if ($name !== '') {
        $names[] = $name;
    }
    if (function_exists('supplier_push_attribute_alias_names')) {
        foreach (supplier_push_attribute_alias_names($name) as $candidate) {
            $candidate = trim((string)$candidate);
            if ($candidate !== '') {
                $names[] = $candidate;
            }
        }
    }

    $norm = supplier_products_db_attr_norm($name);
    $groups = [
        ['страна производства', 'страна-производитель', 'страна производитель', 'страна-изготовитель', 'страна изготовитель', 'страна происхождения', 'country of origin', 'country'],
        ['модель', 'модель товара', 'название модели', 'название модели для объединения в одну карточку'],
    ];
    foreach ($groups as $group) {
        $groupKeys = [];
        foreach ($group as $alias) {
            $key = supplier_products_db_attr_norm((string)$alias);
            if ($key !== '') {
                $groupKeys[$key] = true;
            }
        }
        if ($norm !== '' && isset($groupKeys[$norm])) {
            foreach ($group as $alias) {
                $alias = trim((string)$alias);
                if ($alias !== '') {
                    $names[] = $alias;
                }
            }
        }
    }

    $out = [];
    $seen = [];
    foreach ($names as $candidate) {
        $key = supplier_products_db_attr_norm((string)$candidate);
        if ($key === '' || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $out[] = (string)$candidate;
    }
    return $out;
}

function supplier_products_db_attr_candidate_keys(string $name): array
{
    $out = [];
    foreach (supplier_products_db_attr_alias_names($name) as $candidate) {
        $key = supplier_products_db_attr_norm((string)$candidate);
        if ($key !== '') {
            $out[$key] = true;
        }
    }
    return array_keys($out);
}

function supplier_products_db_product_category_value(array $product, array $fields, string $source): string
{
    $source = $source === 'wildberries' ? 'wildberries' : 'ozon';
    if ($source === 'ozon') {
        $value = trim((string)($product['ozon_category'] ?? ''));
        if ($value === '') {
            $value = supplier_products_db_product_tag_value($fields, ['ozon_category']);
        }
        if (preg_match('~^leaf:(\d+_\d+)$~', $value, $m)) {
            $value = (string)$m[1];
        }
        return $value;
    }

    $value = trim((string)($product['wb_category'] ?? ''));
    if ($value === '') {
        $value = supplier_products_db_product_tag_value($fields, ['wb_category', 'wb_subject_id']);
    }
    if (preg_match('~^wb:(?:subject|parent):(\d+)$~', $value, $m)) {
        $value = (string)$m[1];
    }
    return $value;
}

function supplier_products_db_attr_targets_for_contexts(array $contexts, string $name): array
{
    $wantedKeys = supplier_products_db_attr_candidate_keys($name);
    if (!$wantedKeys) {
        return [];
    }
    $wanted = array_fill_keys($wantedKeys, true);
    $targets = [];
    $seen = [];
    foreach ($contexts as $ctx) {
        if (!is_array($ctx)) {
            continue;
        }
        $source = (string)($ctx['source'] ?? '');
        if ($source !== 'ozon' && $source !== 'wildberries') {
            continue;
        }
        foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
            if (!is_array($attr)) {
                continue;
            }
            $attrName = trim((string)($attr['name'] ?? ''));
            if ($attrName === '') {
                continue;
            }
            $matches = false;
            foreach (supplier_products_db_attr_candidate_keys($attrName) as $key) {
                if (isset($wanted[$key])) {
                    $matches = true;
                    break;
                }
            }
            if (!$matches) {
                continue;
            }
            $kind = $source === 'wildberries' ? 'wb_param' : 'param';
            $targetKey = $kind . "\n" . supplier_products_db_attr_norm($attrName);
            if (isset($seen[$targetKey])) {
                continue;
            }
            $seen[$targetKey] = true;
            $targets[] = [
                'source' => $source,
                'kind' => $kind,
                'name' => $attrName,
                'attr' => $attr,
            ];
        }
    }
    return $targets;
}

function supplier_products_db_attr_targets_for_product(array $product, array $fields, string $name, array $cfg): array
{
    $contexts = [];
    $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
    $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
    $ozonCtx = supplier_products_db_load_attr_category('ozon', $ozonCategory, $cfg);
    if ($ozonCtx && !empty($ozonCtx['category_attributes'])) {
        $contexts[] = $ozonCtx;
    }
    $wbCtx = supplier_products_db_load_attr_category('wildberries', $wbCategory, $cfg);
    if ($wbCtx && !empty($wbCtx['category_attributes'])) {
        $contexts[] = $wbCtx;
    }
    return supplier_products_db_attr_targets_for_contexts($contexts, $name);
}

function supplier_products_db_is_tnved_attribute_name(string $name): bool
{
    $norm = supplier_products_db_attr_norm($name);
    return in_array($norm, [
        'тн вэд',
        'тнвэд',
        'тн вэд коды еаэс',
        'код тн вэд',
        'коды тн вэд',
        'tn ved',
        'tnved',
        'tnved code',
    ], true);
}

function supplier_products_db_without_tnved_fields(array $fields, ?int &$removedValues = null): array
{
    $removedValues = 0;
    $out = [];
    foreach ($fields as $field) {
        if (!is_array($field)) {
            continue;
        }
        $kind = (string)($field['field_kind'] ?? '');
        $name = (string)($field['field_name'] ?? '');
        $isTnved = ($kind === 'standard' && $name === supplier_products_tnved_standard_field_name())
            || (($kind === 'param' || $kind === 'wb_param') && supplier_products_db_is_tnved_attribute_name($name));
        if ($isTnved) {
            if (trim((string)($field['field_value'] ?? '')) !== '') {
                $removedValues++;
            }
            continue;
        }
        $out[] = $field;
    }
    return $out;
}

function supplier_products_db_clear_tnved_fields_for_product(PDO $pdo, int $supplierId, int $productId): int
{
    if ($supplierId <= 0 || $productId <= 0) {
        return 0;
    }

    $st = $pdo->prepare("
        SELECT id, field_kind, field_name
        FROM feedtools_supplier_product_fields
        WHERE supplier_id = ?
          AND product_id = ?
          AND field_kind IN ('standard', 'param', 'wb_param')
    ");
    $st->execute([$supplierId, $productId]);
    $deleteIds = [];
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
        $kind = (string)($row['field_kind'] ?? '');
        $name = (string)($row['field_name'] ?? '');
        $isTnved = ($kind === 'standard' && $name === supplier_products_tnved_standard_field_name())
            || (($kind === 'param' || $kind === 'wb_param') && supplier_products_db_is_tnved_attribute_name($name));
        if ($isTnved) {
            $fieldId = (int)($row['id'] ?? 0);
            if ($fieldId > 0) {
                $deleteIds[] = $fieldId;
            }
        }
    }
    if (!$deleteIds) {
        return 0;
    }

    foreach (array_chunk($deleteIds, 400) as $chunk) {
        $placeholders = implode(',', array_fill(0, count($chunk), '?'));
        $delete = $pdo->prepare("DELETE FROM feedtools_supplier_product_fields WHERE id IN ({$placeholders})");
        $delete->execute($chunk);
    }
    return count($deleteIds);
}

function supplier_products_db_tnved_code_from_text(string $value): string
{
    $value = trim($value);
    if ($value === '') {
        return '';
    }
    if (preg_match('~(?<!\d)(\d{10})(?!\d)~u', $value, $m)) {
        return (string)$m[1];
    }
    $digits = preg_replace('~\D+~u', '', $value);
    if (is_string($digits) && strlen($digits) === 10) {
        return $digits;
    }
    return '';
}

function supplier_products_db_tnved_value_requires_marking($value): bool
{
    if (is_array($value)) {
        $value = (string)($value['value'] ?? ($value['prompt_value'] ?? ''));
    }
    $norm = supplier_products_db_attr_norm((string)$value);
    if ($norm === '') {
        return false;
    }
    return str_contains($norm, 'маркировка рф')
        || str_contains($norm, 'обязательная маркировка')
        || str_contains($norm, 'требуется маркировка')
        || str_contains($norm, 'подлежит маркировке');
}

function supplier_products_db_tnved_without_marking_values(array $values, ?int &$removed = null): array
{
    $removed = 0;
    $out = [];
    foreach ($values as $value) {
        if (supplier_products_db_tnved_value_requires_marking($value)) {
            $removed++;
            continue;
        }
        $out[] = $value;
    }
    return $out;
}

function supplier_products_db_tnved_code_is_known_non_leaf(string $code): bool
{
    $code = supplier_products_db_tnved_code_from_text($code);
    if ($code === '') {
        return false;
    }
    static $known = [
        '8806000000' => true,
        '8806100000' => true,
        '8806200000' => true,
        '8806210000' => true,
        '8806220000' => true,
        '8806229000' => true,
        '8806230000' => true,
        '8806240000' => true,
        '8806290000' => true,
        '8806299000' => true,
        '8806900000' => true,
        '8806910000' => true,
        '8806920000' => true,
        '8806930000' => true,
        '8806940000' => true,
        '8806990000' => true,
    ];
    return isset($known[$code]);
}

function supplier_products_db_tnved_code_has_specific_allowed_children(string $code, array $allowedValues): bool
{
    $code = supplier_products_db_tnved_code_from_text($code);
    if ($code === '' || !$allowedValues) {
        return false;
    }
    $prefix = rtrim($code, '0');
    if (strlen($prefix) < 5 || strlen($prefix) >= 10) {
        return false;
    }
    foreach ($allowedValues as $value) {
        $childCode = supplier_products_db_tnved_code_from_text((string)$value);
        if ($childCode !== '' && $childCode !== $code && str_starts_with($childCode, $prefix)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_tnved_non_leaf_reason(string $code, array $allowedValues = []): string
{
    $code = supplier_products_db_tnved_code_from_text($code);
    if ($code === '') {
        return '';
    }
    if (supplier_products_db_tnved_code_is_known_non_leaf($code)) {
        return 'known_parent_tnved_code';
    }
    if (supplier_products_db_tnved_code_has_specific_allowed_children($code, $allowedValues)) {
        return 'dictionary_parent_has_more_specific_children';
    }
    return '';
}

function supplier_products_db_tnved_allowed_value(string $code, array $allowedValues): string
{
    $code = supplier_products_db_tnved_code_from_text($code);
    if ($code === '') {
        return '';
    }
    if (supplier_products_db_tnved_non_leaf_reason($code, $allowedValues) !== '') {
        return '';
    }
    foreach ($allowedValues as $value) {
        $value = trim((string)$value);
        if ($value !== '' && supplier_products_db_tnved_code_from_text($value) === $code) {
            return $value;
        }
    }
    return '';
}

function supplier_products_db_tnved_target_requires_dictionary(array $target): bool
{
    $attr = is_array($target['attr'] ?? null) ? (array)$target['attr'] : [];
    $source = (string)($target['source'] ?? '');
    $name = (string)($target['name'] ?? ($attr['name'] ?? ''));
    if (!supplier_products_db_is_tnved_attribute_name($name)) {
        return false;
    }
    if ($source === 'ozon') {
        return true;
    }
    return (int)($attr['dictionary_id'] ?? 0) > 0
        || in_array((string)($attr['selection_mode'] ?? ''), ['choose_one', 'dictionary'], true)
        || str_contains((string)($attr['value_source'] ?? ''), 'dictionary')
        || str_contains((string)($attr['value_source'] ?? ''), 'directory');
}

function supplier_products_db_tnved_prompt_tokens(string $text): array
{
    $norm = supplier_products_db_attr_norm($text);
    if ($norm === '') {
        return [];
    }
    $tokens = [];
    static $stopTokens = [
        'модуль' => true,
        'модули' => true,
        'товар' => true,
        'товары' => true,
        'товарная' => true,
        'товарной' => true,
        'позиция' => true,
        'позиции' => true,
        'часть' => true,
        'части' => true,
        'запчасть' => true,
        'запчасти' => true,
        'аксессуар' => true,
        'аксессуары' => true,
        'предназначен' => true,
        'предназначенная' => true,
        'предназначенные' => true,
        'совместимый' => true,
        'совместимая' => true,
        'совместимые' => true,
        'модель' => true,
        'модели' => true,
        'для' => true,
        'под' => true,
        'при' => true,
        'или' => true,
        'без' => true,
        'как' => true,
        'это' => true,
        'что' => true,
    ];
    foreach (preg_split('~\s+~u', $norm) ?: [] as $token) {
        $token = trim((string)$token);
        if ($token === '' || isset($stopTokens[$token]) || mb_strlen($token, 'UTF-8') < 3) {
            continue;
        }
        if (ctype_digit($token) && strlen($token) < 4) {
            continue;
        }
        $tokens[$token] = true;
        if (mb_strlen($token, 'UTF-8') >= 6) {
            $tokens[mb_substr($token, 0, 6, 'UTF-8')] = true;
        }
        if (mb_strlen($token, 'UTF-8') >= 8) {
            $tokens[mb_substr($token, 0, 8, 'UTF-8')] = true;
        }
    }
    return array_values(array_map('strval', array_keys($tokens)));
}

function supplier_products_db_tnved_search_expansion(string $text): string
{
    $norm = supplier_products_db_attr_norm($text);
    if ($norm === '') {
        return '';
    }

    $terms = [];
    $add = static function (array $values) use (&$terms): void {
        foreach ($values as $value) {
            $value = trim((string)$value);
            if ($value !== '') {
                $terms[$value] = true;
            }
        }
    };

    $rules = [
        ['~\b(?:gps|gnss|глонасс|навигац|позиционир)~u', ['радионавигационная', 'навигационная', 'спутниковая', 'приемник', 'аппаратура']],
        ['~\b(?:диспл|экран|lcd|oled|tft|тачскрин|touchscreen|матриц)~u', ['дисплей', 'экран', 'монитор', 'индикатор', 'жидкокристаллический', 'части']],
        ['~\b(?:аккумулятор|батаре|battery|li-ion|литий)~u', ['аккумулятор', 'батарея', 'литий', 'электрический']],
        ['~\b(?:шлейф|кабель|cable|провод|переходник)~u', ['кабель', 'провод', 'электрический', 'изолированный', 'соединительный']],
        ['~\b(?:разъ[её]м|коннектор|connector|гнезд|порт)~u', ['соединитель', 'разъем', 'контакт', 'электрический']],
        ['~\b(?:корпус|рамк|держател|лоток|крышк|панел|holder|tray)~u', ['пластмасса', 'части', 'принадлежности', 'крепление']],
        ['~\b(?:стекл|glass|линз)~u', ['стекло', 'защитное', 'части']],
        ['~\b(?:камер|camera|объектив|модуль\s+камер)~u', ['камера', 'фотокамера', 'объектив', 'оптический', 'части']],
        ['~\b(?:плата|pcb|контроллер|микросхем|чип|модуль)~u', ['плата', 'схема', 'электронный', 'модуль', 'аппаратура']],
        ['~\b(?:мотор|двигател|esc|регулятор)~u', ['двигатель', 'электродвигатель', 'регулятор', 'электрический']],
        ['~\b(?:винт|пропеллер|лопаст)~u', ['винт', 'пропеллер', 'части', 'летательный']],
        ['~\b(?:пульт|передатчик|при[её]мник|антенн|radio|fpv)~u', ['радио', 'передающая', 'приемная', 'аппаратура', 'антенна']],
        ['~\b(?:зарядн|адаптер|блок\s+питания|charger|power\s+supply)~u', ['зарядное', 'преобразователь', 'источник', 'питания', 'электрический']],
        ['~\b(?:пододеял|наволоч|простын|постельн|бель[её])~u', ['белье', 'постельное', 'текстиль', 'хлопчатобумажный']],
        ['~\b(?:сатин|жаккард|хлопок|полиэстер|ткан)~u', ['ткань', 'хлопчатобумажный', 'текстиль', 'синтетический']],
        ['~\b(?:чехол|сумк|кейс|case)~u', ['чехол', 'футляр', 'сумка', 'пластмасса', 'текстиль']],
        ['~\b(?:инструмент|отвертк|ключ|паяльник)~u', ['инструмент', 'ручной', 'электрический']],
    ];

    foreach ($rules as $rule) {
        if (preg_match((string)$rule[0], $norm)) {
            $add((array)$rule[1]);
        }
    }

    return implode(' ', array_keys($terms));
}

function supplier_products_db_tnved_classification_hints(string $searchText): array
{
    $norm = supplier_products_db_attr_norm($searchText);
    if ($norm === '') {
        return [];
    }

    $hints = [];
    $add = static function (string $role, array $likely, array $avoid, string $note) use (&$hints): void {
        $key = supplier_products_db_attr_norm($role . ' ' . $note);
        if ($key === '') {
            $key = (string)count($hints);
        }
        if (isset($hints[$key])) {
            return;
        }
        $hints[$key] = [
            'role_hint' => $role,
            'likely_headings_or_groups' => array_values(array_slice(array_filter(array_map('strval', $likely)), 0, 6)),
            'avoid_if_not_explicit' => array_values(array_slice(array_filter(array_map('strval', $avoid)), 0, 6)),
            'note' => acp_trunc($note, 220),
        ];
    };

    if (preg_match('~\b(?:зарядн|зарядка|charger|блок\s+питания|адаптер\s+питания|power\s+supply)~u', $norm)) {
        $add(
            'зарядное устройство / статический преобразователь',
            ['8504: статические преобразователи, зарядные устройства'],
            ['8507: аккумуляторы', 'код готового дрона/телефона'],
            'Классифицируй продаваемую зарядку, а не аккумулятор или устройство совместимости.'
        );
    }
    if (preg_match('~\b(?:аккумулятор|акб|батаре|battery|lipo|li\s*po|li-ion|литий)~u', $norm)) {
        $add(
            'аккумулятор',
            ['8507: электрические аккумуляторы'],
            ['8504: зарядные устройства'],
            'Если продается сама батарея/аккумулятор, не выбирай код зарядного устройства.'
        );
    }
    if (preg_match('~\b(?:чехол|кейс|сумк|футляр|case|bag|carry|переноск|хранен)~u', $norm)) {
        $add(
            'чехол / кейс / футляр',
            ['4202: футляры, чехлы, кейсы для хранения/переноски', '3926: простые пластиковые/силиконовые накладки без функции сумки'],
            ['8529: части камер/электроники', '8807: части летательных аппаратов'],
            'Для кейса/чехла важнее функция хранения, переноски или защиты, а не код камеры, дрона или модели совместимости.'
        );
    }
    if (preg_match('~\b(?:наклейк|стикер|sticker|пленк|skin)~u', $norm)) {
        $add(
            'наклейка / декоративная пленка',
            ['3919: самоклеящиеся пленки/наклейки', '3926: прочие изделия из пластмасс'],
            ['8807: части летательных аппаратов', '8529: части электроники'],
            'Классифицируй наклейку как материал/изделие, а не как часть дрона или камеры.'
        );
    }
    if (preg_match('~\b(?:защитн[а-яё]*\s+стекл[а-яё]*|закаленн[а-яё]*\s+стекл[а-яё]*|стекл[а-яё]*\s+(?:для|на)\s+(?:экран|диспл|камер)|tempered\s+glass|screen\s+protector)\b~u', $norm)) {
        $add(
            'защитное стекло / стеклянный протектор',
            ['70: стекло и изделия из стекла; выбирай конечный код по обработке и составу'],
            ['8534: печатные схемы', '8517/8529: электронные части телефона', 'код совместимого телефона'],
            'Классифицируй продаваемое защитное стекло как изделие из стекла, а не как дисплей, печатную плату или телефон.'
        );
    }
    if (preg_match('~\b(?:заглушк|фиксатор|держател|креплен|кронштейн|защит[аы]|удлинител|шасси|посадочн|накладк|holder|mount|bracket|plug|cover|guard)~u', $norm)) {
        $add(
            'неэлектронный аксессуар / крепеж / защита',
            ['3926: пластиковые аксессуары', '7616: алюминиевые изделия, если явно металл', '8302: крепежная фурнитура, если применимо'],
            ['код готового устройства', '8807: части летательных аппаратов без явной конструкционной функции', '8529: части камер/электроники без электронной функции'],
            'Если товар не содержит электроники и продается как защитная/крепежная деталь, не классифицируй по устройству совместимости.'
        );
    }
    if (preg_match('~\b(?:диспл|экран|lcd|oled|тачскрин|touchscreen|матриц)~u', $norm)) {
        $add(
            'дисплейный модуль / экран',
            ['8517/8524/8528/8529: выбирай по назначению и устройству', 'части телефонов, если это дисплей для смартфона'],
            ['код готового телефона', 'простое стекло, если это модуль с электроникой'],
            'Для дисплея телефона классифицируй продаваемый модуль/часть, а не совместимый телефон.'
        );
    }
    if (preg_match('~\b(?:кабель|шлейф|провод|cable|wire)~u', $norm)) {
        $add(
            'кабель / провод / шлейф',
            ['8544: изолированные провода, кабели и шлейфы', '8517: части/компоненты связи только если это не просто кабель'],
            ['код готового устройства'],
            'Если продается кабель или шлейф, не классифицируй по телефону/дрону, к которому он подходит.'
        );
    }
    if (preg_match('~\b(?:пододеял|наволоч|простын|постельн|бель[её])~u', $norm)) {
        $add(
            'постельное белье',
            ['6302: постельное белье'],
            ['ткани в рулонах', 'одежда'],
            'Для комплектов постельного белья важен готовый текстильный товар, а не материал как сырье.'
        );
    }

    return array_values($hints);
}

function supplier_products_db_tnved_unique_assoc(array $values): array
{
    $out = [];
    foreach ($values as $key => $value) {
        $key = trim((string)$key);
        $value = trim((string)$value);
        if ($key !== '' && $value !== '') {
            $out[$key] = $value;
        }
    }
    return $out;
}

function supplier_products_db_tnved_drone_takeoff_weight_grams(string $text): float
{
    $text = html_entity_decode((string)preg_replace('~<[^>]+>~u', ' ', $text), ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $text = (string)preg_replace('~\b(кг|kg|килограмм[а-яё]*|гр|г|g)(?=[А-ЯЁA-Z])~u', '$1 ', $text);
    $source = str_replace(',', '.', mb_strtolower($text, 'UTF-8'));
    $weights = [];
    $addWeight = static function ($value, string $unit) use (&$weights): void {
        $value = (float)$value;
        $unit = mb_strtolower(trim($unit), 'UTF-8');
        if ($value <= 0) {
            return;
        }
        if (str_starts_with($unit, 'к') || $unit === 'kg') {
            $value *= 1000;
        }
        if ($value > 0 && $value < 10000000) {
            $weights[] = $value;
        }
    };

    $patterns = [
        ['~(?:макс(?:имальн[а-яё]*)?\s+взл[её]тн[а-яё]*\s+(?:масса|вес)|взл[её]тн[а-яё]*\s+(?:масса|вес)|mtow|max(?:imum)?\s+take[\s-]?off\s+weight|take[\s-]?off\s+weight)[^\d]{0,90}(\d+(?:\.\d+)?)\s*(кг|kg|килограмм[а-яё]*|гр|г|g)\b~ui', 1, 2],
        ['~(?:макс(?:имальн[а-яё]*)?\s+взл[её]тн[а-яё]*\s+(?:масса|вес)|взл[её]тн[а-яё]*\s+(?:масса|вес)|mtow|max(?:imum)?\s+take[\s-]?off\s+weight|take[\s-]?off\s+weight)[^\n\r\d]{0,80}\b(кг|kg|килограмм[а-яё]*|гр|г|g)\b[^\d]{0,30}(\d+(?:\.\d+)?)\b~ui', 2, 1],
        ['~(?:масса|вес)\s+(?:с\s+аккумулятором|пол[её]тн[а-яё]*)[^\d]{0,90}(\d+(?:\.\d+)?)\s*(кг|kg|килограмм[а-яё]*|гр|г|g)\b~ui', 1, 2],
    ];
    foreach ($patterns as $row) {
        $pattern = (string)($row[0] ?? '');
        $valueIdx = (int)($row[1] ?? 1);
        $unitIdx = (int)($row[2] ?? 2);
        if ($pattern === '' || !preg_match_all($pattern, $source, $matches, PREG_SET_ORDER)) {
            continue;
        }
        foreach ($matches as $m) {
            $addWeight($m[$valueIdx] ?? 0, (string)($m[$unitIdx] ?? ''));
        }
    }
    if ($weights) {
        return (float)min($weights);
    }
    return 0.0;
}

function supplier_products_db_tnved_drone_preferred_code(string $text): string
{
    $weight = supplier_products_db_tnved_drone_takeoff_weight_grams($text);
    if ($weight > 0) {
        if ($weight <= 250) {
            return '8806210009';
        }
        if ($weight <= 7000) {
            return '8806220009';
        }
        if ($weight <= 25000) {
            return '8806230009';
        }
        if ($weight <= 150000) {
            return '8806240009';
        }
        return '8806290029';
    }

    $norm = supplier_products_db_attr_norm($text);
    if (preg_match('~\b(?:tinywhoop|tiny\s+whoop|whoop|65\s*мм|75\s*мм|mini\s*2|mini\s*3|mini\s*4|до\s*250\s*г|249\s*г)~u', $norm)) {
        return '8806210009';
    }
    if (preg_match('~\b(?:long\s*range|chimera\s*7|chimera7|7\s*(?:inch|дюйм)|6s|5s|3300\s*mah|4000\s*mah)~u', $norm)) {
        return '8806220009';
    }

    return '8806220009';
}

function supplier_products_db_tnved_product_profile(string $searchText, array $analysis = []): array
{
    $analysisParts = [];
    foreach (['product_role', 'product_type', 'reason'] as $key) {
        $analysisParts[] = (string)($analysis[$key] ?? '');
    }
    foreach (['target_objects', 'materials', 'likely_headings', 'include_terms', 'exclude_terms'] as $key) {
        foreach ((array)($analysis[$key] ?? []) as $value) {
            $analysisParts[] = (string)$value;
        }
    }
    $source = trim($searchText . "\n" . implode("\n", $analysisParts));
    $norm = supplier_products_db_attr_norm($source);

    $profile = [
        'role' => '',
        'preferred_codes' => [],
        'likely_prefixes' => [],
        'avoid_prefixes' => [],
        'notes' => [],
        'strict_likely_prefix' => false,
        'profile_confidence' => 0.0,
    ];
    $addPreferred = static function (string $code, string $reason) use (&$profile): void {
        $code = supplier_products_db_tnved_code_from_text($code);
        if ($code !== '') {
            $profile['preferred_codes'][$code] = $reason;
        }
    };
    $addLikely = static function (string $prefix, string $reason) use (&$profile): void {
        $prefix = preg_replace('~\D+~', '', $prefix) ?? '';
        if ($prefix !== '') {
            $profile['likely_prefixes'][$prefix] = $reason;
        }
    };
    $addAvoid = static function (string $prefix, string $reason) use (&$profile): void {
        $prefix = preg_replace('~\D+~', '', $prefix) ?? '';
        if ($prefix !== '') {
            $profile['avoid_prefixes'][$prefix] = $reason;
        }
    };
    $addNote = static function (string $note) use (&$profile): void {
        $note = trim($note);
        if ($note !== '') {
            $profile['notes'][$note] = true;
        }
    };

    if ($norm === '') {
        return $profile;
    }

    $lines = preg_split('~\R+~u', $source) ?: [];
    $titleNorm = supplier_products_db_attr_norm((string)($lines[0] ?? ''));
    $roleNorm = supplier_products_db_attr_norm((string)($analysis['product_role'] ?? ''));
    $typeNorm = supplier_products_db_attr_norm((string)($analysis['product_type'] ?? ''));
    $titleHasReadyDrone = $titleNorm !== '' && preg_match('~\b(?:квадрокоптер|дрон|бпла|беспилотн|fpv\s*[- ]?дрон|cinewhoop|tinywhoop|uav|drone)\b~u', $titleNorm) === 1;
    $titleHasPartMarker = $titleNorm !== '' && (
        preg_match('~\b(?:для\s+(?:квадрокоптер|дрон|fpv|mavic|dji)|запчаст|часть|рама|мотор|двигател|регулятор|esc|плата|модуль|креплен|держател|защит|чехол|кейс|аккумулятор|батаре|зарядн|кабель|провод|стек|контроллер)\b~u', $titleNorm) === 1
        || preg_match('~(?:^|\s)(?:gps|gnss|антенн|при[её]мник|пульт|камера)\b.*\bдля\b|\bдля\b.*\b(?:gps|gnss|антенн|при[её]мник|пульт|камера)\b~u', $titleNorm) === 1
    );
    $readyDroneByTitle = $titleHasReadyDrone && !$titleHasPartMarker;
    $readyDroneByAnalysis = preg_match('~готов(?:ое|ый|ая)\s+изделие|квадрокоптер|дрон|бпла|беспилот~u', $roleNorm . ' ' . $typeNorm) === 1
        && preg_match('~запчаст|часть|аксессуар|комплектующ|модуль|аккумулятор|зарядн|кабель|контроллер|плата|камера~u', $roleNorm . ' ' . $typeNorm) !== 1;
    $readyDroneByFacts = $readyDroneByTitle
        || $readyDroneByAnalysis
        || ($titleHasReadyDrone && preg_match('~\b(?:готовый|готовое|собранн|cinewhoop|tinywhoop|long\s*range|bnf|pnp|rtf)\b~u', $titleNorm) === 1);

    $titleHasBattery = $titleNorm !== '' && preg_match('~\b(?:аккумулятор|акб|батаре|battery|lipo|li\s*po|lihv|li-ion|литий|литий[-\s]?ион)\b~u', $titleNorm) === 1;
    $titleHasCharger = $titleNorm !== '' && preg_match('~\b(?:зарядн[а-яё]*|зарядка|charger|блок\s+питания|адаптер\s+питания|power\s+supply)\b~u', $titleNorm) === 1;
    $titleChargerIsProduct = $titleNorm !== '' && preg_match(
        '~^(?:зарядн[а-яё]*\s+устройств[а-яё]*|зарядка|charger|блок\s+питания|адаптер\s+питания|power\s+supply)\b~u',
        $titleNorm
    ) === 1;
    $titleHasCable = $titleNorm !== '' && preg_match('~\b(?:кабель|шлейф|провод|cable|wire)\b~u', $titleNorm) === 1;
    $titleCableIsProduct = $titleHasCable && preg_match(
        '~(?:^|\s)(?:usb(?:[-\s]?[ac])?\s+|type[-\s]?c\s+|lightning\s+)?(?:кабель|шлейф|провод|cable|wire)\b|\b(?:кабель|шлейф|провод|cable|wire)\s*[-:]?\s*(?:заряд|type[-\s]?c|usb|lightning)~u',
        $titleNorm
    ) === 1;
    $titleHasProtectiveGlass = $titleNorm !== '' && preg_match(
        '~\b(?:защитн[а-яё]*\s+стекл[а-яё]*|закаленн[а-яё]*\s+стекл[а-яё]*|стекл[а-яё]*\s+(?:для|на)\s+(?:экран|диспл|камер)|tempered\s+glass|screen\s+protector)\b~u',
        $titleNorm
    ) === 1;
    $titleHasProtectiveFilm = $titleNorm !== '' && preg_match(
        '~\b(?:(?:защитн[а-яё]*|гидрогелев[а-яё]*|самоклеящ[а-яё]*)\s+пл[её]нк[а-яё]*|пл[её]нк[а-яё]*\s+(?:для|на)\s+(?:экран|диспл)|screen\s+film)\b~u',
        $titleNorm
    ) === 1;
    $titleSuppressesContextPower = $readyDroneByFacts || (
        $titleNorm !== ''
        && !$titleHasBattery
        && !$titleHasCharger
        && preg_match('~\b(?:пол[её]тн(?:ый|ого)\s+(?:контроллер|стек)|flight\s*controller|полетный\s+стек|gps|gnss|антенн|при[её]мник|передатчик|камера|видеомодуль|плата|pcb|контроллер|регулятор|esc|мотор|двигател|пропеллер|винт|рама|креплен|держател|чехол|кейс|кабель|шлейф|провод)\b~u', $titleNorm) === 1
    );
    $hasBattery = $titleHasBattery || (!$titleSuppressesContextPower && preg_match('~\b(?:аккумулятор|акб|батаре|battery|lipo|li\s*po|lihv|li-ion|литий|литий[-\s]?ион)~u', $norm) === 1);
    $hasCharger = $titleHasCharger || (!$titleSuppressesContextPower && preg_match('~\b(?:зарядн[а-яё]*|зарядка|charger|блок\s+питания|адаптер\s+питания|power\s+supply)~u', $norm) === 1);
    $titleHasElectronicBoard = $titleNorm !== '' && preg_match('~\b(?:пол[её]тн(?:ый|ого)\s+(?:контроллер|стек)|flight\s*controller|полетный\s+стек|стек|контроллер|регулятор|esc|плата|pcb|aio|f405|f411|f722|bls|fc[-\s]?esc)~u', $titleNorm) === 1;
    $hasCable = $titleHasCable
        || (!$readyDroneByFacts && !$titleHasElectronicBoard && preg_match('~\b(?:кабель|шлейф|провод|cable|wire)~u', $norm) === 1);
    $hasPropeller = !$titleHasElectronicBoard && preg_match('~\b(?:пропеллер|пропеллеры|винт|лопаст)~u', $norm) === 1;
    $hasMotor = !$titleHasElectronicBoard && preg_match('~\b(?:мотор|двигател|motor|brushless)~u', $norm) === 1;
    $hasGpsModule = preg_match('~\b(?:gps|gnss|глонасс|навигац|позиционир)~u', $titleNorm !== '' ? $titleNorm : $norm) === 1
        || (!$titleHasElectronicBoard && preg_match('~\b(?:gps|gnss|глонасс|навигац|позиционир)~u', $norm) === 1);
    $hasRadioModule = preg_match('~\b(?:при[её]мник|передатчик|антенн|elrs|crossfire|radio|rx|tx|vtx)~u', $titleNorm !== '' ? $titleNorm : $norm) === 1
        || (!$titleHasElectronicBoard && preg_match('~\b(?:при[её]мник|передатчик|антенн|elrs|crossfire|radio|rx|tx|vtx)~u', $norm) === 1);
    $hasCameraModule = preg_match('~\b(?:камера|camera|объектив|линз|видеомодуль)~u', $titleNorm !== '' ? $titleNorm : $norm) === 1
        || (!$titleHasElectronicBoard && preg_match('~\b(?:камера|camera|объектив|линз|видеомодуль)~u', $norm) === 1);
    $hasElectronicBoard = preg_match('~\b(?:пол[её]тн(?:ый|ого)\s+(?:контроллер|стек)|flight\s*controller|полетный\s+стек|стек|контроллер|регулятор|esc|плата|pcb|aio|f405|f411|f722|bls|fc[-\s]?esc)~u', $norm) === 1;
    $hasMountOrFrame = preg_match('~\b(?:рама|корпус|креплен|держател|кронштейн|шасси|защит[аы]|бампер|площадк|mount|holder|frame|bracket)~u', $norm) === 1;
    $hasReadyDrone = preg_match('~\b(?:квадрокоптер|дрон|бпла|беспилотн|fpv\s*[- ]?дрон|cinewhoop|tinywhoop|uav|drone)~u', $norm) === 1;
    $hasPartMarker = preg_match('~\b(?:для\s+(?:квадрокоптер|дрон|fpv|mavic|dji)|запчаст|часть|рама|мотор|двигател|регулятор|esc|плата|gps|антенн|при[её]мник|пульт|камера|модуль|креплен|держател|защит|чехол|кейс)~u', $norm) === 1;

    if ($titleHasProtectiveGlass) {
        $profile['role'] = 'защитное стекло / стеклянный протектор';
        $profile['profile_confidence'] = 0.92;
        $profile['strict_likely_prefix'] = true;
        $addLikely('70', 'стекло и изделия из стекла; конечный код зависит от обработки и состава');
        $addAvoid('8534', 'защитное стекло не является печатной схемой');
        $addAvoid('8517', 'защитное стекло не является электронной частью телефона');
        $addAvoid('8529', 'защитное стекло не является дисплейным или электронным модулем');
        $addNote('Не путать стеклянный протектор с совместимым смартфоном, дисплеем или печатной платой.');
    } elseif ($titleHasProtectiveFilm) {
        $profile['role'] = 'защитная пленка для экрана';
        $profile['profile_confidence'] = 0.9;
        $profile['strict_likely_prefix'] = true;
        $addLikely('3919', 'самоклеящиеся пленки и плоские формы из пластмасс');
        $addLikely('3920', 'пленки и листы из пластмасс без подложки');
        $addLikely('3921', 'прочие пленки и листы из пластмасс');
        $addAvoid('70', 'пленка не является стеклянным изделием');
        $addAvoid('8534', 'защитная пленка не является печатной схемой');
        $addAvoid('8517', 'защитная пленка не является электронной частью телефона');
    } elseif ($titleCableIsProduct && !$hasGpsModule && !$hasRadioModule && !$hasCameraModule && !$hasElectronicBoard) {
        $profile['role'] = 'кабель / шлейф / провод';
        $profile['profile_confidence'] = 0.9;
        $profile['strict_likely_prefix'] = true;
        $addLikely('8544', 'изолированные провода, кабели и шлейфы');
        $addAvoid('8504', 'кабель для зарядки не является зарядным устройством или преобразователем');
        $addAvoid('8507', 'кабель для аккумулятора не является аккумулятором');
        $addAvoid('8806', 'кабель для дрона не является БПЛА');
        $addAvoid('9503', 'кабель не является игрушкой/моделью');
        $addNote('Слова «зарядка» и «для зарядки» описывают назначение кабеля, а не меняют продаваемый объект на зарядное устройство.');
    } elseif ($hasCharger && (!$hasBattery || $titleChargerIsProduct)) {
        $profile['role'] = 'зарядное устройство / блок питания';
        $profile['profile_confidence'] = 0.88;
        $profile['strict_likely_prefix'] = true;
        $addLikely('8504', 'статические преобразователи и зарядные устройства');
        $addAvoid('8507', 'упоминание совместимого аккумулятора не делает зарядное устройство аккумулятором');
        $addAvoid('8806', 'зарядка для дрона не является дроном');
    } elseif ($hasBattery) {
        $profile['role'] = 'аккумулятор';
        $profile['profile_confidence'] = 0.9;
        $profile['strict_likely_prefix'] = true;
        $addLikely('8507', 'электрические аккумуляторы');
        if (preg_match('~\b(?:lipo|li\s*po|lihv|li-ion|литий|литий[-\s]?ион)~u', $norm)) {
            $addPreferred('8507600000', 'литий-ионный/литий-полимерный аккумулятор');
        }
        $addAvoid('8504', 'это зарядные устройства/преобразователи, а не аккумуляторы');
        $addAvoid('8806', 'аккумулятор для дрона не является беспилотным летательным аппаратом');
        $addAvoid('9503', 'аккумулятор не классифицируется как игрушка/модель');
        $addNote('Не путать количество ячеек 4S/6S и емкость с количеством товара в упаковке.');
    } elseif ($hasCable && !$hasGpsModule && !$hasRadioModule && !$hasCameraModule && !$hasElectronicBoard) {
        $profile['role'] = 'кабель / шлейф / провод';
        $profile['profile_confidence'] = 0.84;
        $profile['strict_likely_prefix'] = true;
        $addLikely('8544', 'изолированные провода, кабели и шлейфы');
        $addAvoid('8806', 'кабель для дрона не является БПЛА');
        $addAvoid('9503', 'кабель не является игрушкой/моделью');
    } elseif ($hasReadyDrone && $readyDroneByFacts) {
        $profile['role'] = 'готовый беспилотный летательный аппарат / квадрокоптер';
        $profile['profile_confidence'] = 0.88;
        $profile['strict_likely_prefix'] = true;
        $addLikely('8806', 'беспилотные летательные аппараты');
        $addPreferred(supplier_products_db_tnved_drone_preferred_code($source), 'готовый дрон/квадрокоптер; код зависит от максимальной взлетной массы');
        $addAvoid('8802', 'устаревшая/неподходящая группа для БПЛА после выделения 8806');
        $addAvoid('9503', 'готовый FPV/съемочный БПЛА не должен уходить в игрушки, если товар описан как дрон/квадрокоптер');
        $addAvoid('8543', 'дрон не является прочей электрической аппаратурой только из-за видеопередачи/GPS');
        $addAvoid('8525', 'камера/передатчик внутри дрона не определяет код готового летательного аппарата');
    } elseif ($hasPropeller) {
        $profile['role'] = 'пропеллер / лопасти';
        $profile['profile_confidence'] = 0.78;
        $addLikely('8807', 'части летательных аппаратов');
        $addLikely('3926', 'простые пластиковые изделия, если справочник не относит к авиационным частям');
        $addAvoid('8806', 'пропеллер не является готовым БПЛА');
        $addAvoid('9503', 'пропеллер для дрона не является готовой игрушкой');
    } elseif ($hasMotor) {
        $profile['role'] = 'электродвигатель / мотор';
        $profile['profile_confidence'] = 0.8;
        $profile['strict_likely_prefix'] = true;
        $addLikely('8501', 'электродвигатели');
        $addAvoid('8806', 'мотор для дрона не является готовым БПЛА');
        $addAvoid('9503', 'мотор не является готовой игрушкой/моделью');
    } elseif ($hasGpsModule) {
        $profile['role'] = 'GPS/GNSS модуль / радионавигационная аппаратура';
        $profile['profile_confidence'] = 0.78;
        $profile['strict_likely_prefix'] = true;
        $addLikely('8526', 'радионавигационная аппаратура и модули позиционирования');
        $addPreferred('8526912000', 'радионавигационный приемник GPS/GNSS');
        $addAvoid('8806', 'GPS модуль для дрона не является готовым БПЛА');
        $addAvoid('9503', 'GPS модуль не является игрушкой/моделью');
    } elseif ($hasRadioModule) {
        $profile['role'] = 'радиопередающий / радиоприемный модуль';
        $profile['profile_confidence'] = 0.76;
        $addLikely('8525', 'передающая аппаратура');
        $addLikely('8526', 'радионавигационная/радиоприемная аппаратура, если это приемник');
        $addAvoid('8806', 'радиомодуль для дрона не является готовым БПЛА');
        $addAvoid('9503', 'радиомодуль не является игрушкой/моделью');
    } elseif ($hasCameraModule && !$titleHasElectronicBoard) {
        $profile['role'] = 'камера / видеомодуль';
        $profile['profile_confidence'] = 0.76;
        $addLikely('8525', 'камеры и передающая аппаратура');
        $addLikely('8529', 'части камер/видеоаппаратуры, если это именно модуль/часть');
        $addAvoid('8806', 'камера для дрона не является готовым БПЛА');
        $addAvoid('9503', 'камера не является игрушкой/моделью');
    } elseif ($hasElectronicBoard) {
        $profile['role'] = 'электронная плата / контроллер / полетный стек';
        $profile['profile_confidence'] = 0.78;
        $profile['strict_likely_prefix'] = true;
        $addLikely('8537', 'пульты, панели, контроллеры и распределительные устройства');
        $addLikely('8543', 'электрические машины и аппаратура с индивидуальными функциями');
        $addLikely('8534', 'печатные схемы, если продается только печатная плата');
        $addAvoid('8806', 'полетный контроллер или стек для дрона не является готовым БПЛА');
        $addAvoid('9503', 'электронная плата/контроллер не является игрушкой/моделью');
    } elseif ($hasMountOrFrame) {
        $profile['role'] = 'рама / крепление / корпус / защитная деталь';
        $profile['profile_confidence'] = 0.74;
        $addLikely('3926', 'простые пластиковые аксессуары и детали');
        $addLikely('7616', 'алюминиевые изделия, если материал алюминий');
        $addLikely('8807', 'части летательных аппаратов, если справочник явно относит деталь к конструкционным частям БПЛА');
        $addAvoid('8806', 'деталь/крепление не является готовым БПЛА');
        $addAvoid('9503', 'деталь для дрона не является готовой игрушкой/моделью');
    } elseif (preg_match('~\b(?:пододеял|наволоч|простын|постельн|бель[её])~u', $norm)) {
        $profile['role'] = 'готовое постельное белье';
        $profile['profile_confidence'] = 0.84;
        $profile['strict_likely_prefix'] = true;
        $addLikely('6302', 'постельное белье');
        $addAvoid('5208', 'ткань в рулонах, а не готовое белье');
        $addAvoid('6200', 'одежда');
    } elseif (preg_match('~\b(?:чехол|кейс|футляр|сумк|case|bag|переноск|хранен)~u', $norm)) {
        $profile['role'] = 'чехол / кейс / футляр';
        $profile['profile_confidence'] = 0.78;
        $addLikely('4202', 'чехлы, футляры и кейсы для хранения/переноски');
        $addLikely('3926', 'простые пластиковые/силиконовые накладки');
        $addAvoid('8806', 'чехол для дрона не является БПЛА');
        $addAvoid('8529', 'чехол не является электронной частью камеры/телефона');
    }

    $profile['preferred_codes'] = supplier_products_db_tnved_unique_assoc((array)$profile['preferred_codes']);
    $profile['likely_prefixes'] = supplier_products_db_tnved_unique_assoc((array)$profile['likely_prefixes']);
    $profile['avoid_prefixes'] = supplier_products_db_tnved_unique_assoc((array)$profile['avoid_prefixes']);
    $profile['notes'] = array_values(array_keys((array)$profile['notes']));
    return $profile;
}

function supplier_products_db_tnved_profile_prompt(array $profile): array
{
    return [
        'role' => (string)($profile['role'] ?? ''),
        'preferred_codes' => (object)supplier_products_db_tnved_unique_assoc((array)($profile['preferred_codes'] ?? [])),
        'likely_prefixes' => (object)supplier_products_db_tnved_unique_assoc((array)($profile['likely_prefixes'] ?? [])),
        'avoid_prefixes' => (object)supplier_products_db_tnved_unique_assoc((array)($profile['avoid_prefixes'] ?? [])),
        'strict_likely_prefix' => !empty($profile['strict_likely_prefix']),
        'profile_confidence' => round((float)($profile['profile_confidence'] ?? 0), 3),
        'notes' => array_values(array_slice(array_map('strval', (array)($profile['notes'] ?? [])), 0, 5)),
    ];
}

function supplier_products_db_tnved_code_matches_prefixes(string $code, array $prefixes): bool
{
    $code = supplier_products_db_tnved_code_from_text($code);
    if ($code === '') {
        return false;
    }
    foreach ($prefixes as $prefix => $_reason) {
        $prefix = preg_replace('~\D+~', '', (string)$prefix) ?? '';
        if ($prefix !== '' && str_starts_with($code, $prefix)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_tnved_candidate_profile_score(string $code, string $value, array $profile): array
{
    $code = supplier_products_db_tnved_code_from_text($code);
    $valueNorm = supplier_products_db_attr_norm($value);
    $score = 0;
    $reasons = [];
    foreach ((array)($profile['preferred_codes'] ?? []) as $preferredCode => $reason) {
        $preferredCode = supplier_products_db_tnved_code_from_text((string)$preferredCode);
        if ($preferredCode === '' || $code === '') {
            continue;
        }
        if ($code === $preferredCode) {
            $score += 30000;
            $reasons[] = 'exact_preferred:' . $preferredCode;
        } elseif (substr($code, 0, 6) === substr($preferredCode, 0, 6)) {
            $score += 6500;
            $reasons[] = 'same_6_as_preferred:' . substr($preferredCode, 0, 6);
        } elseif (substr($code, 0, 4) === substr($preferredCode, 0, 4)) {
            $score += 2600;
            $reasons[] = 'same_4_as_preferred:' . substr($preferredCode, 0, 4);
        }
    }
    foreach ((array)($profile['likely_prefixes'] ?? []) as $prefix => $reason) {
        $prefix = preg_replace('~\D+~', '', (string)$prefix) ?? '';
        if ($prefix !== '' && $code !== '' && str_starts_with($code, $prefix)) {
            $score += 900 + min(2200, strlen($prefix) * 450);
            $reasons[] = 'likely_prefix:' . $prefix;
        }
    }
    foreach ((array)($profile['avoid_prefixes'] ?? []) as $prefix => $reason) {
        $prefix = preg_replace('~\D+~', '', (string)$prefix) ?? '';
        if ($prefix !== '' && $code !== '' && str_starts_with($code, $prefix)) {
            $score -= 28000;
            $reasons[] = 'avoid_prefix:' . $prefix;
        }
    }

    $role = supplier_products_db_attr_norm((string)($profile['role'] ?? ''));
    if ($role !== '' && $valueNorm !== '') {
        if (str_contains($role, 'беспилот') || str_contains($role, 'квадрокоптер')) {
            if (preg_match('~беспилот|летательн|квадрокоптер|дрон~u', $valueNorm)) {
                $score += 2600;
                $reasons[] = 'drone_terms';
            }
            if (preg_match('~игруш|модел~u', $valueNorm) && !preg_match('~беспилот|квадрокоптер|дрон~u', $valueNorm)) {
                $score -= 5000;
                $reasons[] = 'toy_model_without_drone_terms';
            }
        } elseif (str_contains($role, 'аккумулятор')) {
            if (preg_match('~аккумулятор|литий|li-ion|lithium|электрическ~u', $valueNorm)) {
                $score += 2200;
                $reasons[] = 'battery_terms';
            }
            if (preg_match('~зарядн|преобразователь|блок питания~u', $valueNorm)) {
                $score -= 7000;
                $reasons[] = 'charger_terms_for_battery';
            }
        } elseif (str_contains($role, 'заряд')) {
            if (preg_match('~зарядн|преобразователь|блок питания|статическ~u', $valueNorm)) {
                $score += 2200;
                $reasons[] = 'charger_terms';
            }
        } elseif (str_contains($role, 'кабель') || str_contains($role, 'шлейф')) {
            if (preg_match('~кабел|провод|изолирован|шлейф~u', $valueNorm)) {
                $score += 2200;
                $reasons[] = 'cable_terms';
            }
        } elseif (str_contains($role, 'постель')) {
            if (preg_match('~постель|бель[ея]|текстил~u', $valueNorm)) {
                $score += 2200;
                $reasons[] = 'bedding_terms';
            }
        }
    }

    return ['score' => $score, 'reasons' => array_values(array_slice(array_unique($reasons), 0, 4))];
}

function supplier_products_db_tnved_apply_profile_guard(array $decision, string $searchText, array $analysis = []): array
{
    $profile = supplier_products_db_tnved_product_profile($searchText, $analysis);
    $code = supplier_products_db_tnved_code_from_text((string)($decision['tnved_code'] ?? ''));
    $preferredCodes = (array)($profile['preferred_codes'] ?? []);
    $likelyPrefixes = (array)($profile['likely_prefixes'] ?? []);
    $avoidPrefixes = (array)($profile['avoid_prefixes'] ?? []);
    $changed = false;
    $guardReason = '';

    if ($preferredCodes) {
        $preferredCode = supplier_products_db_tnved_code_from_text((string)array_key_first($preferredCodes));
        $preferredReason = (string)reset($preferredCodes);
        $codeIsAvoided = $code !== '' && supplier_products_db_tnved_code_matches_prefixes($code, $avoidPrefixes);
        $codeIsNonLeaf = $code !== '' && supplier_products_db_tnved_non_leaf_reason($code) !== '';
        $codeLooksUnstableDroneLeaf = $code !== ''
            && $preferredCode !== ''
            && str_starts_with($preferredCode, '8806')
            && str_starts_with($code, '8806')
            && $code !== $preferredCode
            && (str_ends_with($code, '0000') || str_ends_with($code, '9000') || (float)($decision['confidence'] ?? 0) < 0.82);
        $codeMissesStrictPrefix = $code !== ''
            && !empty($profile['strict_likely_prefix'])
            && $likelyPrefixes
            && !supplier_products_db_tnved_code_matches_prefixes($code, $likelyPrefixes);
        if ($preferredCode !== '' && ($code === '' || $codeIsAvoided || $codeIsNonLeaf || $codeLooksUnstableDroneLeaf || $codeMissesStrictPrefix)) {
            $decision['tnved_code'] = $preferredCode;
            $decision['marketplace_value'] = $preferredCode;
            $decision['confidence'] = max((float)($decision['confidence'] ?? 0), min(0.9, max(0.78, (float)($profile['profile_confidence'] ?? 0.78))));
            $decision['review_required'] = !empty($decision['review_required']) || (float)($profile['profile_confidence'] ?? 0) < 0.86;
            $guardReason = 'Системная проверка товарной роли заменила код ' . ($code !== '' ? $code : 'пусто') . ' на ' . $preferredCode . ': ' . $preferredReason;
            $decision['reason'] = acp_trunc(trim((string)($decision['reason'] ?? '') . ' ' . $guardReason), 320);
            $riskFlags = (array)($decision['risk_flags'] ?? []);
            $riskFlags[] = 'system_profile_guard_applied';
            $decision['risk_flags'] = supplier_products_db_tnved_string_list($riskFlags, 8, 100);
            unset($decision['verification_rejected']);
            $decision['verification_corrected'] = 1;
            $changed = true;
        }
    } elseif ($code !== '' && supplier_products_db_tnved_non_leaf_reason($code) !== '') {
        $decision['confidence'] = min((float)($decision['confidence'] ?? 0), 0.49);
        $decision['review_required'] = true;
        $guardReason = 'Системная проверка ТН ВЭД: код ' . $code . ' выглядит как родительский/обобщенный и не должен записываться как конечное значение.';
        $decision['reason'] = acp_trunc(trim((string)($decision['reason'] ?? '') . ' ' . $guardReason), 320);
        $changed = true;
    } elseif ($code !== '' && !empty($profile['strict_likely_prefix']) && $likelyPrefixes && !supplier_products_db_tnved_code_matches_prefixes($code, $likelyPrefixes)) {
        $decision['confidence'] = min((float)($decision['confidence'] ?? 0), 0.69);
        $decision['review_required'] = true;
        $guardReason = 'Системная проверка товарной роли: код не попадает в ожидаемые группы ' . implode(', ', array_keys($likelyPrefixes));
        $decision['reason'] = acp_trunc(trim((string)($decision['reason'] ?? '') . ' ' . $guardReason), 320);
        $changed = true;
    }

    return [
        'decision' => $decision,
        'changed' => $changed,
        'reason' => $guardReason,
        'profile' => supplier_products_db_tnved_profile_prompt($profile),
    ];
}

function supplier_products_db_tnved_existing_code_matches_product_profile(string $code, string $searchText, array $analysis = []): bool
{
    $code = supplier_products_db_tnved_code_from_text($code);
    if ($code === '' || supplier_products_db_tnved_non_leaf_reason($code) !== '') {
        return false;
    }

    $profile = supplier_products_db_tnved_product_profile($searchText, $analysis);
    $likelyPrefixes = (array)($profile['likely_prefixes'] ?? []);
    $avoidPrefixes = (array)($profile['avoid_prefixes'] ?? []);
    if ($avoidPrefixes && supplier_products_db_tnved_code_matches_prefixes($code, $avoidPrefixes)) {
        return false;
    }
    if (!empty($profile['strict_likely_prefix']) && $likelyPrefixes && !supplier_products_db_tnved_code_matches_prefixes($code, $likelyPrefixes)) {
        return false;
    }

    return true;
}

function supplier_products_db_tnved_search_text_with_analysis(array $payload, array $analysis, array $hints = []): string
{
    $product = is_array($payload['product'] ?? null) ? (array)$payload['product'] : [];
    $parts = [
        (string)($product['name'] ?? ''),
        (string)($product['short_name'] ?? ''),
        (string)($product['description'] ?? ''),
        (string)(($product['supplier_category']['path'] ?? '') ?: ''),
    ];
    foreach ((array)($product['params'] ?? []) as $row) {
        if (is_array($row)) {
            $parts[] = (string)($row['name'] ?? '') . ' ' . (string)($row['value'] ?? '');
        }
    }
    foreach ((array)($payload['marketplace_categories'] ?? []) as $row) {
        if (is_array($row)) {
            $parts[] = (string)($row['full_path'] ?? '') . ' ' . (string)($row['description'] ?? '') . ' ' . (string)($row['typical_goods'] ?? '');
        }
    }
    foreach (['product_role', 'product_type', 'reason'] as $key) {
        $parts[] = (string)($analysis[$key] ?? '');
    }
    foreach (['target_objects', 'materials', 'likely_headings', 'include_terms', 'exclude_terms'] as $key) {
        foreach ((array)($analysis[$key] ?? []) as $value) {
            $parts[] = (string)$value;
        }
    }
    foreach ($hints as $hint) {
        if (!is_array($hint)) {
            continue;
        }
        $parts[] = (string)($hint['role_hint'] ?? '') . ' ' . (string)($hint['note'] ?? '');
        $parts[] = implode(' ', array_map('strval', (array)($hint['likely_headings_or_groups'] ?? [])));
        $parts[] = implode(' ', array_map('strval', (array)($hint['avoid_if_not_explicit'] ?? [])));
    }
    return implode("\n", array_filter($parts, static fn($value): bool => trim((string)$value) !== ''));
}

function supplier_products_db_tnved_prompt_value(string $value, int $maxLen = 170): string
{
    $value = trim((string)preg_replace('/\s+/u', ' ', strip_tags($value)));
    if ($value === '') {
        return '';
    }
    if (mb_strlen($value, 'UTF-8') <= $maxLen) {
        return $value;
    }
    return acp_trunc($value, $maxLen);
}

function supplier_products_db_tnved_incompatible_value_reason(string $value, string $searchText): string
{
    $valueNorm = supplier_products_db_attr_norm($value);
    if ($valueNorm === '') {
        return '';
    }
    $searchNorm = supplier_products_db_attr_norm($searchText);

    $hasSearch = static function (string $pattern) use ($searchNorm): bool {
        return $searchNorm !== '' && preg_match($pattern, $searchNorm) === 1;
    };
    $hasValue = static function (string $pattern) use ($valueNorm): bool {
        return preg_match($pattern, $valueNorm) === 1;
    };

    if ($hasValue('~природн(?:ый|ого)?\s+газ|рабоч(?:ее|его)\s+давлен|газов(?:ый|ого)\s+топлив|емкост[ьи]\s+для\s+.*газ~u')
        && !$hasSearch('~природн(?:ый|ого)?\s+газ|баллон|газов|давлен|резервуар|топлив~u')) {
        return 'dictionary_value_for_gas_pressure_equipment';
    }

    if ($hasValue('~гражданск(?:их|ие|ого)?\s+воздушн(?:ых|ые|ого)?\s+суд|авиационн(?:ых|ые|ого)?\s+двигател|производств[ао]\s+авиац~u')
        && !$hasSearch('~самолет|самол[её]т|вертолет|вертол[её]т|авиацион|авиац(?:ия|ионн)|авиадвигател|воздушн(?:ое|ого)\s+суд~u')) {
        return 'dictionary_value_for_certified_aircraft_production';
    }

    if ($hasValue('~перевозк[аи]\s+пассажир|пассажирск|количеств[ао]\s+пассажирск(?:их|ие)?\s+мест~u')
        && !$hasSearch('~пассажир|перевозк[аи]\s+людей|перевозк[аи]\s+пассажир~u')) {
        return 'dictionary_value_for_passenger_aircraft';
    }

    if ($hasValue('~медицинск|хирургическ|стоматологическ~u')
        && !$hasSearch('~медицинск|хирургическ|стоматологическ|медиц~u')) {
        return 'dictionary_value_for_medical_goods';
    }

    if ($hasValue('~железнодорожн|локомотив|вагон~u')
        && !$hasSearch('~железнодорожн|локомотив|вагон|рельс~u')) {
        return 'dictionary_value_for_railway_goods';
    }

    return '';
}

function supplier_products_db_tnved_clean_allowed_prompt_rows(array $rows, int $limit, string $searchText): array
{
    $limit = max(1, $limit);
    $compatible = [];
    foreach ($rows as $row) {
        if (!is_array($row)) {
            continue;
        }
        if (trim((string)($row['incompatible_reason'] ?? '')) !== '') {
            continue;
        }
        $compatible[] = $row;
    }
    $source = $compatible ?: $rows;
    $picked = [];
    foreach (array_slice($source, 0, $limit) as $row) {
        $picked[] = [
            'code' => (string)($row['code'] ?? ''),
            'value' => (string)($row['prompt_value'] ?? $row['value'] ?? ''),
            'score' => (int)($row['score'] ?? 0),
            'match_reasons' => array_values(array_slice(array_map('strval', (array)($row['match_reasons'] ?? [])), 0, 4)),
        ];
    }
    return $picked;
}

function supplier_products_db_tnved_allowed_values_selection(array $allowedValues, string $searchText, int $limit, array $memoryRows = []): array
{
    $limit = max(20, min(1000, $limit));
    $markingValuesFiltered = 0;
    $allowedValues = supplier_products_db_tnved_without_marking_values($allowedValues, $markingValuesFiltered);
    $clean = [];
    $seen = [];
    foreach ($allowedValues as $value) {
        $value = trim((string)$value);
        $key = supplier_products_db_attr_norm($value);
        if ($value === '' || $key === '' || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $code = supplier_products_db_tnved_code_from_text($value);
        $clean[] = [
            'idx' => count($clean),
            'code' => $code,
            'value' => $value,
            'prompt_value' => supplier_products_db_tnved_prompt_value($value),
            'incompatible_reason' => supplier_products_db_tnved_incompatible_value_reason($value, $searchText),
            'non_leaf_reason' => supplier_products_db_tnved_code_is_known_non_leaf($code) ? 'known_parent_tnved_code' : '',
        ];
    }
    $allowedRawValues = array_map(static fn(array $row): string => (string)($row['value'] ?? ''), $clean);
    foreach ($clean as &$row) {
        if ((string)($row['non_leaf_reason'] ?? '') === '') {
            $row['non_leaf_reason'] = supplier_products_db_tnved_code_has_specific_allowed_children((string)($row['code'] ?? ''), $allowedRawValues)
                ? 'dictionary_parent_has_more_specific_children'
                : '';
        }
    }
    unset($row);
    $expandedSearchText = $searchText . "\n" . supplier_products_db_tnved_search_expansion($searchText);
    $searchTokens = supplier_products_db_tnved_prompt_tokens($expandedSearchText);
    $profile = supplier_products_db_tnved_product_profile($expandedSearchText);
    $memoryCodes = [];
    foreach ($memoryRows as $row) {
        if (!is_array($row)) {
            continue;
        }
        $memoryCode = supplier_products_db_tnved_code_from_text((string)($row['code'] ?? ''));
        if ($memoryCode !== '') {
            $memoryCodes[$memoryCode] = max(1, (int)($row['count'] ?? 1));
        }
    }

    $scored = [];
    foreach ($clean as $row) {
        $value = (string)$row['value'];
        $code = (string)$row['code'];
        $norm = supplier_products_db_attr_norm($value);
        $score = 0;
        $reasons = [];
        if ($code !== '') {
            if (isset($memoryCodes[$code])) {
                $score += 10000 + min(500, $memoryCodes[$code] * 20);
                $reasons[] = 'category_memory_exact';
            }
            foreach ($memoryCodes as $memoryCode => $count) {
                $memoryCode = (string)$memoryCode;
                if ($memoryCode === $code || $memoryCode === '') {
                    continue;
                }
                if (substr($memoryCode, 0, 6) === substr($code, 0, 6)) {
                    $score += 180 + min(80, $count * 8);
                    $reasons[] = 'category_memory_same_6';
                } elseif (substr($memoryCode, 0, 4) === substr($code, 0, 4)) {
                    $score += 70 + min(40, $count * 4);
                    $reasons[] = 'category_memory_same_4';
                }
            }
        }
        foreach ($searchTokens as $token) {
            if ($token !== '' && str_contains($norm, $token)) {
                $score += mb_strlen($token, 'UTF-8') >= 6 ? 3 : 1;
            }
        }
        $profileScore = supplier_products_db_tnved_candidate_profile_score($code, $value, $profile);
        $score += (int)($profileScore['score'] ?? 0);
        foreach ((array)($profileScore['reasons'] ?? []) as $reason) {
            $reasons[] = (string)$reason;
        }
        if (preg_match('~\b(?:прочие|прочих|прочая|прочее|прочий|прочего)\b~u', $norm)) {
            $score += 420;
            $reasons[] = 'general_other_code';
        }
        if ((string)($row['incompatible_reason'] ?? '') !== '') {
            $score -= 100000;
            $reasons[] = 'incompatible_dictionary_value';
        }
        if ((string)($row['non_leaf_reason'] ?? '') !== '') {
            $score -= 120000;
            $reasons[] = 'non_leaf_tnved_code';
        }
        $scored[] = $row + [
            'score' => $score,
            'match_reasons' => array_values(array_slice(array_unique(array_filter($reasons)), 0, 4)),
        ];
    }
    usort($scored, static function (array $a, array $b): int {
        $cmp = ((int)$b['score'] <=> (int)$a['score']);
        return $cmp !== 0 ? $cmp : ((int)$a['idx'] <=> (int)$b['idx']);
    });

    $picked = [];
    $matched = 0;
    $incompatibleFiltered = 0;
    $topScore = (int)($scored[0]['score'] ?? 0);
    $compatibleScored = array_values(array_filter(
        $scored,
        static fn(array $row): bool => trim((string)($row['incompatible_reason'] ?? '')) === ''
            && trim((string)($row['non_leaf_reason'] ?? '')) === ''
    ));
    $sourceRows = $compatibleScored ?: $scored;
    foreach (array_slice($sourceRows, 0, $limit) as $row) {
        if ((int)($row['score'] ?? 0) > 0) {
            $matched++;
        }
        $picked[] = [
            'code' => (string)($row['code'] ?? ''),
            'value' => (string)($row['prompt_value'] ?? $row['value'] ?? ''),
            'score' => (int)($row['score'] ?? 0),
            'match_reasons' => array_values(array_slice(array_map('strval', (array)($row['match_reasons'] ?? [])), 0, 4)),
        ];
    }
    $incompatibleFiltered = max(0, count($clean) - count($compatibleScored));
    return [
        'values' => $picked,
        'top_score' => $topScore,
        'matched_values' => $matched,
        'incompatible_values_filtered' => $incompatibleFiltered,
        'marking_values_filtered' => $markingValuesFiltered,
        'profile' => supplier_products_db_tnved_profile_prompt($profile),
    ];
}

function supplier_products_db_tnved_allowed_values_for_prompt(array $allowedValues, string $searchText, int $limit, array $memoryRows = []): array
{
    $selection = supplier_products_db_tnved_allowed_values_selection($allowedValues, $searchText, $limit, $memoryRows);
    return (array)($selection['values'] ?? []);
}

function supplier_products_db_tnved_targets_for_contexts(array $contexts): array
{
    $targets = [];
    $seen = [];
    foreach ($contexts as $ctx) {
        if (!is_array($ctx)) {
            continue;
        }
        $source = (string)($ctx['source'] ?? '');
        if ($source !== 'ozon' && $source !== 'wildberries') {
            continue;
        }
        foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
            if (!is_array($attr)) {
                continue;
            }
            $name = trim((string)($attr['name'] ?? ''));
            if ($name === '' || !supplier_products_db_is_tnved_attribute_name($name)) {
                continue;
            }
            $kind = $source === 'wildberries' ? 'wb_param' : 'param';
            $key = $kind . "\n" . supplier_products_db_attr_norm($name);
            if (isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;
            $rawAllowedValues = array_values(array_filter(array_map('strval', (array)($attr['allowed_values'] ?? []))));
            $markingValuesFiltered = 0;
            $allowedValues = supplier_products_db_tnved_without_marking_values($rawAllowedValues, $markingValuesFiltered);
            $targets[] = [
                'source' => $source,
                'kind' => $kind,
                'name' => $name,
                'attr' => $attr,
                'allowed_values' => $allowedValues,
                'allowed_values_original_count' => count($rawAllowedValues),
                'marking_values_filtered' => $markingValuesFiltered,
                'requires_no_marking_code' => true,
                'requires_dictionary' => supplier_products_db_tnved_target_requires_dictionary([
                    'source' => $source,
                    'kind' => $kind,
                    'name' => $name,
                    'attr' => $attr,
                ]),
                'category_code' => (string)($ctx['code'] ?? ''),
                'category_name' => (string)($ctx['name'] ?? ''),
                'category_path' => (string)($ctx['full_path'] ?? ''),
            ];
        }
    }
    return $targets;
}

function supplier_products_db_tnved_fallback_targets(array $contexts, array $existingTargets = []): array
{
    $bySource = ['ozon' => null, 'wildberries' => null];
    foreach ($contexts as $ctx) {
        if (!is_array($ctx)) {
            continue;
        }
        $source = (string)($ctx['source'] ?? '');
        if ($source === 'ozon' || $source === 'wildberries') {
            $bySource[$source] = $ctx;
        }
    }

    $hasSourceTarget = ['ozon' => false, 'wildberries' => false];
    foreach ($existingTargets as $target) {
        if (!is_array($target)) {
            continue;
        }
        $source = (string)($target['source'] ?? '');
        if (isset($hasSourceTarget[$source])) {
            $hasSourceTarget[$source] = true;
        }
    }

    $out = [];
    foreach (['ozon' => 'ТН ВЭД коды ЕАЭС', 'wildberries' => 'ТН ВЭД'] as $source => $name) {
        if ($hasSourceTarget[$source]) {
            continue;
        }
        $ctx = is_array($bySource[$source]) ? $bySource[$source] : [];
        $out[] = [
            'source' => $source,
            'kind' => $source === 'wildberries' ? 'wb_param' : 'param',
            'name' => $name,
            'attr' => [
                'name' => $name,
                'allowed_values' => [],
            ],
            'allowed_values' => [],
            'requires_dictionary' => $source === 'ozon',
            'fallback_target' => true,
            'category_code' => (string)($ctx['code'] ?? ''),
            'category_name' => (string)($ctx['name'] ?? ''),
            'category_path' => (string)($ctx['full_path'] ?? ''),
        ];
    }
    return $out;
}

function supplier_products_db_tnved_target_prompt(array $target, string $searchText = '', int $allowedLimit = 160, array $memoryRows = []): array
{
    $markingValuesFilteredNow = 0;
    $allowedValues = supplier_products_db_tnved_without_marking_values(
        array_values((array)($target['allowed_values'] ?? [])),
        $markingValuesFilteredNow
    );
    $markingValuesFiltered = (int)($target['marking_values_filtered'] ?? 0) + $markingValuesFilteredNow;
    $allowedSelection = supplier_products_db_tnved_allowed_values_selection($allowedValues, $searchText, $allowedLimit, $memoryRows);
    $allowedForPrompt = (array)($allowedSelection['values'] ?? []);
    $source = (string)($target['source'] ?? '');
    $requiresDictionary = !empty($target['requires_dictionary']) || supplier_products_db_tnved_target_requires_dictionary($target);
    $strictCategoryDictionary = $source === 'ozon' && $requiresDictionary;
    if ($allowedValues) {
        $candidatePolicy = $strictCategoryDictionary
            ? 'choose_only_from_allowed_values; category_dictionary_is_authoritative; prefer_stable_leaf_code; reject_parent_codes'
            : (count($allowedValues) > count($allowedForPrompt)
                ? 'prefer_allowed_values_shortlist; prefer_stable_leaf_code; outside_code_allowed_only_if_all_candidates_semantically_wrong_and_full_dictionary_can_validate'
                : 'choose_only_from_allowed_values');
    } elseif ($markingValuesFiltered > 0
        && $markingValuesFiltered >= (int)($target['allowed_values_original_count'] ?? $markingValuesFiltered)) {
        $candidatePolicy = 'no_non_marking_candidates; do_not_choose_or_write_code';
    } else {
        $candidatePolicy = $strictCategoryDictionary
            ? 'missing_category_dictionary; choose_best_exact_leaf_code; validate_by_category_dictionary_after_decision; do_not_write_if_not_found'
            : 'free_classification_no_dictionary_values';
    }
    return [
        'marketplace' => $source,
        'attribute_name' => (string)($target['name'] ?? ''),
        'attribute_id' => (int)(($target['attr']['id'] ?? null) ?: ($target['attr']['attribute_id'] ?? 0)),
        'dictionary_id' => (int)(($target['attr']['dictionary_id'] ?? null) ?: 0),
        'requires_dictionary' => $requiresDictionary,
        'category_dictionary_is_authoritative' => $strictCategoryDictionary,
        'prefer_stable_leaf_code' => true,
        'reject_parent_codes' => true,
        'requires_no_marking_code' => true,
        'has_dictionary' => !empty($allowedValues)
            || (int)(($target['attr']['dictionary_id'] ?? null) ?: 0) > 0
            || (string)($target['attr']['selection_mode'] ?? '') === 'choose_one',
        'dictionary_values_missing' => empty($allowedValues) && (
            !empty($target['requires_dictionary'])
            || (int)(($target['attr']['dictionary_id'] ?? null) ?: 0) > 0
            || (string)($target['attr']['selection_mode'] ?? '') === 'choose_one'
        ),
        'allowed_values_count' => count($allowedValues),
        'allowed_values_original_count' => max(
            count($allowedValues) + $markingValuesFiltered,
            (int)($target['allowed_values_original_count'] ?? 0)
        ),
        'allowed_values_in_prompt' => count($allowedForPrompt),
        'allowed_values_top_score' => (int)($allowedSelection['top_score'] ?? 0),
        'allowed_values_matched_in_prompt' => (int)($allowedSelection['matched_values'] ?? 0),
        'allowed_values_incompatible_filtered' => (int)($allowedSelection['incompatible_values_filtered'] ?? 0),
        'marking_values_filtered' => $markingValuesFiltered + (int)($allowedSelection['marking_values_filtered'] ?? 0),
        'allowed_values_truncated' => count($allowedValues) > count($allowedForPrompt),
        'allowed_values_are_shortlist' => count($allowedValues) > count($allowedForPrompt),
        'candidate_policy' => $candidatePolicy,
        'candidate_profile' => is_array($allowedSelection['profile'] ?? null) ? $allowedSelection['profile'] : [],
        'allowed_values' => $allowedForPrompt,
        'category_code' => (string)($target['category_code'] ?? ''),
        'category_name' => (string)($target['category_name'] ?? ''),
        'category_path' => (string)($target['category_path'] ?? ''),
    ];
}

function supplier_products_db_tnved_marketplace_value(string $code, string $suggestedValue, array $target, string $searchText = ''): array
{
    if (supplier_products_db_tnved_value_requires_marking($suggestedValue)) {
        return ['value' => '', 'validated' => false, 'error' => 'marking_required_tnved_code'];
    }
    $code = supplier_products_db_tnved_code_from_text($code !== '' ? $code : $suggestedValue);
    if ($code === '') {
        return ['value' => '', 'validated' => false, 'error' => 'no_10_digit_tnved_code'];
    }

    $markingValuesFiltered = 0;
    $allowedValues = supplier_products_db_tnved_without_marking_values(
        array_values((array)($target['allowed_values'] ?? [])),
        $markingValuesFiltered
    );
    $requiresDictionary = !empty($target['requires_dictionary']) || supplier_products_db_tnved_target_requires_dictionary($target);
    $nonLeafReason = supplier_products_db_tnved_non_leaf_reason($code, $allowedValues);
    if ($nonLeafReason !== '') {
        return [
            'value' => '',
            'validated' => false,
            'dictionary_missing_fallback' => false,
            'error' => 'non_leaf_tnved_code',
            'non_leaf_reason' => $nonLeafReason,
        ];
    }
    if ($allowedValues) {
        $allowed = supplier_products_db_tnved_allowed_value($code, $allowedValues);
        if ($allowed === '') {
            return ['value' => '', 'validated' => false, 'error' => 'code_not_found_in_marketplace_dictionary'];
        }
        $incompatibleReason = supplier_products_db_tnved_incompatible_value_reason($allowed, $searchText);
        if ($incompatibleReason !== '') {
            return [
                'value' => '',
                'validated' => false,
                'error' => 'dictionary_value_incompatible_with_product',
                'incompatible_reason' => $incompatibleReason,
                'incompatible_value' => $allowed,
            ];
        }
        return ['value' => $allowed, 'validated' => true, 'error' => ''];
    }
    if ($requiresDictionary) {
        return ['value' => '', 'validated' => false, 'dictionary_missing_fallback' => false, 'error' => 'category_dictionary_missing'];
    }

    $suggestedValue = trim((string)preg_replace('/\s+/u', ' ', $suggestedValue));
    if ($suggestedValue !== '' && supplier_products_db_tnved_code_from_text($suggestedValue) === $code) {
        return ['value' => $suggestedValue, 'validated' => false, 'error' => ''];
    }

    return ['value' => $code, 'validated' => false, 'error' => ''];
}

function supplier_products_db_tnved_target_key(array $target): string
{
    return (string)($target['kind'] ?? '') . "\n" . supplier_products_db_attr_norm((string)($target['name'] ?? ''));
}

function supplier_products_db_tnved_existing_target_value_is_valid(array $target, string $existingValue): bool
{
    $existingValue = trim($existingValue);
    if ($existingValue === '') {
        return false;
    }
    $existingCode = supplier_products_db_tnved_code_from_text($existingValue);
    if ($existingCode === '' || supplier_products_db_tnved_non_leaf_reason($existingCode) !== '') {
        return false;
    }
    $requiresDictionary = !empty($target['requires_dictionary']) || supplier_products_db_tnved_target_requires_dictionary($target);
    if (!$requiresDictionary) {
        return true;
    }

    $resolved = supplier_products_db_tnved_marketplace_value($existingCode, $existingValue, $target, '');
    $resolvedValue = trim((string)($resolved['value'] ?? ''));
    if ($resolvedValue === '' || empty($resolved['validated'])) {
        return false;
    }

    return supplier_products_db_attr_norm($resolvedValue) === supplier_products_db_attr_norm($existingValue);
}

function supplier_products_db_tnved_supplier_category_key(array $product): string
{
    $id = trim((string)($product['category_id'] ?? ''));
    $path = supplier_products_db_attr_norm((string)($product['category_path'] ?? ''));
    if ($id !== '' && $id !== '0') {
        return 'id:' . $id . '|path:' . $path;
    }
    return $path !== '' ? 'path:' . $path : '';
}

function supplier_products_db_tnved_existing_memory(array $products, array $fieldsByProduct, int $examplesLimit = 4): array
{
    $raw = [];
    foreach ($products as $product) {
        if (!is_array($product)) {
            continue;
        }
        $productId = (int)($product['id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        $categoryKey = supplier_products_db_tnved_supplier_category_key($product);
        if ($categoryKey === '') {
            continue;
        }
        foreach ((array)($fieldsByProduct[$productId] ?? []) as $field) {
            if (!is_array($field)) {
                continue;
            }
            $kind = (string)($field['field_kind'] ?? '');
            $name = (string)($field['field_name'] ?? '');
            $isStandardTnved = $kind === 'standard' && trim($name) === supplier_products_tnved_standard_field_name();
            $isMarketplaceTnved = ($kind === 'param' || $kind === 'wb_param')
                && supplier_products_db_is_tnved_attribute_name($name);
            if (!$isStandardTnved && !$isMarketplaceTnved) {
                continue;
            }
            $code = supplier_products_db_tnved_code_from_text((string)($field['field_value'] ?? ''));
            if ($code === '' || supplier_products_db_tnved_non_leaf_reason($code) !== '') {
                continue;
            }
            $source = $isStandardTnved ? 'common' : ($kind === 'wb_param' ? 'wildberries' : 'ozon');
            if (!isset($raw[$categoryKey][$code])) {
                $raw[$categoryKey][$code] = [
                    'code' => $code,
                    'count' => 0,
                    'sources' => [],
                    'examples' => [],
                ];
            }
            $raw[$categoryKey][$code]['count']++;
            $raw[$categoryKey][$code]['sources'][$source] = true;
            if (count($raw[$categoryKey][$code]['examples']) < $examplesLimit) {
                $raw[$categoryKey][$code]['examples'][] = [
                    'offer_id' => (string)($product['offer_id'] ?? ''),
                    'name' => acp_trunc((string)($product['name'] ?? ''), 160),
                    'value' => acp_trunc((string)($field['field_value'] ?? ''), 160),
                ];
            }
        }
    }

    $out = [];
    foreach ($raw as $categoryKey => $codes) {
        $total = 0;
        foreach ($codes as $row) {
            $total += (int)($row['count'] ?? 0);
        }
        $rows = [];
        foreach ($codes as $row) {
            $count = (int)($row['count'] ?? 0);
            if ($count <= 0) {
                continue;
            }
            $rows[] = [
                'code' => (string)($row['code'] ?? ''),
                'count' => $count,
                'share' => $total > 0 ? round($count / $total, 3) : 0.0,
                'sources' => array_values(array_map('strval', array_keys((array)($row['sources'] ?? [])))),
                'examples' => array_values((array)($row['examples'] ?? [])),
            ];
        }
        usort($rows, static function (array $a, array $b): int {
            $cmp = ((int)($b['count'] ?? 0) <=> (int)($a['count'] ?? 0));
            return $cmp !== 0 ? $cmp : strcmp((string)($a['code'] ?? ''), (string)($b['code'] ?? ''));
        });
        if ($rows) {
            $out[(string)$categoryKey] = $rows;
        }
    }
    return $out;
}

function supplier_products_db_tnved_compact_memory(array $memoryRows, int $limit = 5): array
{
    $out = [];
    foreach (array_slice($memoryRows, 0, max(1, $limit)) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $out[] = [
            'code' => (string)($row['code'] ?? ''),
            'count' => (int)($row['count'] ?? 0),
            'share' => (float)($row['share'] ?? 0),
            'sources' => array_values(array_slice(array_map('strval', (array)($row['sources'] ?? [])), 0, 3)),
            'examples' => array_values(array_slice((array)($row['examples'] ?? []), 0, 3)),
        ];
    }
    return $out;
}

function supplier_products_db_tnved_signature_title(string $title): string
{
    $norm = supplier_products_db_attr_norm($title);
    if ($norm === '') {
        return '';
    }
    $norm = preg_replace('~\bsim\b~u', 'сим', $norm) ?? $norm;
    $beforeCompatibility = preg_split('~\b(?:для|под|совместим(?:ый|ая|ое|ые)?\s+с|compatible\s+with|for)\b~u', $norm, 2);
    if (is_array($beforeCompatibility) && trim((string)($beforeCompatibility[0] ?? '')) !== '') {
        $candidate = trim((string)$beforeCompatibility[0]);
        if (mb_strlen($candidate, 'UTF-8') >= 4) {
            $norm = $candidate;
        }
    }
    $tokens = [];
    static $noise = [
        'оригинал' => true,
        'оригинальный' => true,
        'original' => true,
        'новый' => true,
        'new' => true,
        'черный' => true,
        'черная' => true,
        'черное' => true,
        'белый' => true,
        'белая' => true,
        'белое' => true,
        'красный' => true,
        'синий' => true,
        'зеленый' => true,
        'желтый' => true,
        'серый' => true,
        'комплект' => true,
        'набор' => true,
        'шт' => true,
    ];
    foreach (preg_split('~\s+~u', $norm) ?: [] as $token) {
        $token = trim((string)$token);
        if ($token === '' || isset($noise[$token])) {
            continue;
        }
        if (preg_match('~^\d+$~u', $token)) {
            continue;
        }
        if (preg_match('~^(?:[a-zа-яё]+)?\d+[a-zа-яё0-9-]*$~u', $token)) {
            continue;
        }
        if (mb_strlen($token, 'UTF-8') < 2) {
            continue;
        }
        $tokens[] = $token;
        if (count($tokens) >= 8) {
            break;
        }
    }
    if (!$tokens) {
        return mb_substr($norm, 0, 80, 'UTF-8');
    }
    return implode(' ', $tokens);
}

function supplier_products_db_tnved_signature_key(array $payload): string
{
    $product = is_array($payload['product'] ?? null) ? (array)$payload['product'] : [];
    $title = supplier_products_db_tnved_signature_title((string)($product['short_name'] ?? ''));
    if ($title === '') {
        $title = supplier_products_db_tnved_signature_title((string)($product['name'] ?? ''));
    }
    $supplierCategory = is_array($product['supplier_category'] ?? null) ? (array)$product['supplier_category'] : [];
    $marketCategories = [];
    foreach ((array)($payload['marketplace_categories'] ?? []) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $marketCategories[] = [
            'source' => (string)($row['source'] ?? ''),
            'path' => supplier_products_db_attr_norm((string)($row['full_path'] ?? ($row['name'] ?? ''))),
        ];
    }
    $targets = [];
    foreach ((array)($payload['target_attributes'] ?? []) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $targets[] = [
            'marketplace' => (string)($row['marketplace'] ?? ''),
            'attribute' => supplier_products_db_attr_norm((string)($row['attribute_name'] ?? '')),
            'dictionary' => !empty($row['has_dictionary']) ? 1 : 0,
        ];
    }
    $source = [
        'supplier_category_id' => (string)($supplierCategory['id'] ?? ''),
        'supplier_category_path' => supplier_products_db_attr_norm((string)($supplierCategory['path'] ?? '')),
        'title' => $title,
        'marketplace_categories' => $marketCategories,
        'targets' => $targets,
    ];
    return substr(hash('sha256', json_encode($source, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 40);
}

function supplier_products_db_tnved_group_key(array $payload): string
{
    $product = is_array($payload['product'] ?? null) ? (array)$payload['product'] : [];
    $supplierCategory = is_array($product['supplier_category'] ?? null) ? (array)$product['supplier_category'] : [];
    $profile = is_array($payload['tnved_profile'] ?? null) ? (array)$payload['tnved_profile'] : [];

    $marketCategories = [];
    foreach ((array)($payload['marketplace_categories'] ?? []) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $source = trim((string)($row['source'] ?? ''));
        $code = trim((string)($row['code'] ?? ''));
        $path = supplier_products_db_attr_norm((string)($row['full_path'] ?? ($row['name'] ?? '')));
        if ($source === '' && $code === '' && $path === '') {
            continue;
        }
        $marketCategories[] = [
            'source' => $source,
            'code' => $code,
            'path' => $path,
        ];
    }
    usort($marketCategories, static fn(array $a, array $b): int => strcmp(
        ($a['source'] ?? '') . ':' . ($a['code'] ?? '') . ':' . ($a['path'] ?? ''),
        ($b['source'] ?? '') . ':' . ($b['code'] ?? '') . ':' . ($b['path'] ?? '')
    ));

    $likely = [];
    foreach ((array)($profile['likely_prefixes'] ?? []) as $prefix => $_reason) {
        $prefix = preg_replace('~\D+~', '', (string)$prefix) ?? '';
        if ($prefix !== '') {
            $likely[$prefix] = true;
        }
    }
    $likely = array_values(array_keys($likely));
    sort($likely, SORT_STRING);

    $preferred = [];
    foreach ((array)($profile['preferred_codes'] ?? []) as $code => $_reason) {
        $code = supplier_products_db_tnved_code_from_text((string)$code);
        if ($code !== '') {
            $preferred[$code] = true;
        }
    }
    $preferred = array_values(array_keys($preferred));
    sort($preferred, SORT_STRING);

    $source = [
        'supplier_category_id' => trim((string)($supplierCategory['id'] ?? '')),
        'supplier_category_path' => supplier_products_db_attr_norm((string)($supplierCategory['path'] ?? '')),
        'marketplace_categories' => $marketCategories,
        'role' => supplier_products_db_attr_norm((string)($profile['role'] ?? '')),
        'strict_likely_prefix' => !empty($profile['strict_likely_prefix']) ? 1 : 0,
        'likely_prefixes' => array_slice($likely, 0, 5),
        'preferred_codes' => array_slice($preferred, 0, 4),
    ];
    return substr(hash('sha256', json_encode($source, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 40);
}

function supplier_products_db_tnved_group_label(array $payload): string
{
    $product = is_array($payload['product'] ?? null) ? (array)$payload['product'] : [];
    $supplierCategory = is_array($product['supplier_category'] ?? null) ? (array)$product['supplier_category'] : [];
    $profile = is_array($payload['tnved_profile'] ?? null) ? (array)$payload['tnved_profile'] : [];
    $parts = [];
    $supplierPath = trim((string)($supplierCategory['path'] ?? ''));
    if ($supplierPath !== '') {
        $parts[] = acp_trunc($supplierPath, 120);
    }
    $role = trim((string)($profile['role'] ?? ''));
    if ($role !== '') {
        $parts[] = acp_trunc($role, 80);
    }
    $preferred = [];
    foreach ((array)($profile['preferred_codes'] ?? []) as $code => $_reason) {
        $code = supplier_products_db_tnved_code_from_text((string)$code);
        if ($code !== '') {
            $preferred[] = $code;
        }
    }
    if ($preferred) {
        $parts[] = 'pref ' . implode(',', array_slice(array_values(array_unique($preferred)), 0, 3));
    }
    foreach ((array)($payload['marketplace_categories'] ?? []) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $source = trim((string)($row['source'] ?? ''));
        $path = trim((string)($row['full_path'] ?? ($row['name'] ?? '')));
        if ($source !== '' && $path !== '') {
            $parts[] = $source . ': ' . acp_trunc($path, 120);
        }
    }
    return acp_trunc(implode(' | ', array_values(array_filter($parts))), 420);
}

function supplier_products_db_tnved_category_scope_key(array $payload): string
{
    $product = is_array($payload['product'] ?? null) ? (array)$payload['product'] : [];
    $supplierCategory = is_array($product['supplier_category'] ?? null) ? (array)$product['supplier_category'] : [];
    $marketCategories = [];
    foreach ((array)($payload['marketplace_categories'] ?? []) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $source = trim((string)($row['source'] ?? ''));
        $code = trim((string)($row['code'] ?? ''));
        $path = supplier_products_db_attr_norm((string)($row['full_path'] ?? ($row['name'] ?? '')));
        if ($source === '' && $code === '' && $path === '') {
            continue;
        }
        $marketCategories[] = $source . ':' . $code . ':' . $path;
    }
    sort($marketCategories, SORT_STRING);
    $source = [
        'supplier_category_id' => trim((string)($supplierCategory['id'] ?? '')),
        'supplier_category_path' => supplier_products_db_attr_norm((string)($supplierCategory['path'] ?? '')),
        'marketplace_categories' => $marketCategories,
    ];
    return substr(hash('sha256', json_encode($source, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 40);
}

function supplier_products_db_tnved_category_scope_label(array $payload): string
{
    $product = is_array($payload['product'] ?? null) ? (array)$payload['product'] : [];
    $supplierCategory = is_array($product['supplier_category'] ?? null) ? (array)$product['supplier_category'] : [];
    $parts = [];
    $supplierPath = trim((string)($supplierCategory['path'] ?? ''));
    if ($supplierPath !== '') {
        $parts[] = 'Поставщик: ' . acp_trunc($supplierPath, 150);
    }
    foreach ((array)($payload['marketplace_categories'] ?? []) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $source = trim((string)($row['source'] ?? ''));
        $path = trim((string)($row['full_path'] ?? ($row['name'] ?? '')));
        if ($source !== '' && $path !== '') {
            $parts[] = $source . ': ' . acp_trunc($path, 150);
        }
    }
    return acp_trunc(implode(' | ', $parts), 520);
}

/**
 * Builds one compact TN VED candidate list for a supplier category + marketplace
 * category. The list keeps the strongest candidates of every detected product
 * role, so products in one category do not repeatedly send the full Ozon
 * dictionary to the LLM.
 */
function supplier_products_db_tnved_prepare_category_shortlists(array &$jobs, int $limit = 16): array
{
    $limit = max(8, min(30, $limit));
    $scopes = [];
    foreach ($jobs as $offerId => &$job) {
        $payload = is_array($job['payload'] ?? null) ? (array)$job['payload'] : [];
        $scopeKey = supplier_products_db_tnved_category_scope_key($payload);
        if ($scopeKey === '') {
            continue;
        }
        $job['tnved_category_scope_key'] = $scopeKey;
        $job['tnved_category_scope_label'] = supplier_products_db_tnved_category_scope_label($payload);
        if (!isset($scopes[$scopeKey])) {
            $scopes[$scopeKey] = [
                'scope_key' => $scopeKey,
                'label' => (string)$job['tnved_category_scope_label'],
                'offers' => [],
                'has_ozon' => false,
            ];
        }
        $scopes[$scopeKey]['offers'][] = (string)$offerId;
        foreach ((array)($payload['target_attributes'] ?? []) as $target) {
            if (is_array($target)
                && (string)($target['marketplace'] ?? '') === 'ozon'
                && !empty($target['allowed_values'])) {
                $scopes[$scopeKey]['has_ozon'] = true;
                break;
            }
        }
    }
    unset($job);

    $plans = [];
    foreach ($scopes as $scopeKey => $scope) {
        $preferredSource = !empty($scope['has_ozon']) ? 'ozon' : '';
        $globalStats = [];
        $groupStats = [];
        $targetValues = [];
        $originalValuesCount = 0;

        foreach ((array)$scope['offers'] as $offerId) {
            if (!isset($jobs[$offerId])) {
                continue;
            }
            $job = (array)$jobs[$offerId];
            $payload = (array)($job['payload'] ?? []);
            $groupKey = (string)($job['tnved_group_key'] ?? '');
            if ($groupKey === '') {
                $groupKey = 'ungrouped';
            }
            foreach ((array)($payload['target_attributes'] ?? []) as $target) {
                if (!is_array($target)) {
                    continue;
                }
                $source = (string)($target['marketplace'] ?? '');
                if ($preferredSource !== '' && $source !== $preferredSource) {
                    continue;
                }
                $targetKey = $source . "\n" . supplier_products_db_attr_norm((string)($target['attribute_name'] ?? ''));
                $originalValuesCount = max($originalValuesCount, (int)($target['allowed_values_count'] ?? 0));
                $seenInTarget = [];
                foreach ((array)($target['allowed_values'] ?? []) as $rank => $row) {
                    if (!is_array($row)) {
                        continue;
                    }
                    $code = supplier_products_db_tnved_code_from_text((string)($row['code'] ?? ($row['value'] ?? '')));
                    if ($code === '' || isset($seenInTarget[$code]) || supplier_products_db_tnved_non_leaf_reason($code) !== '') {
                        continue;
                    }
                    $seenInTarget[$code] = true;
                    $value = trim((string)($row['value'] ?? $code));
                    $score = max(-100000, min(100000, (int)($row['score'] ?? 0)));
                    $rankPoints = max(1, 40 - min(39, (int)$rank));
                    if (!isset($globalStats[$code])) {
                        $globalStats[$code] = [
                            'code' => $code,
                            'value' => $value !== '' ? $value : $code,
                            'product_hits' => 0,
                            'top3_hits' => 0,
                            'rank_points' => 0,
                            'score_sum' => 0,
                            'best_score' => $score,
                            'general_leaf_hits' => 0,
                            'reasons' => [],
                        ];
                    }
                    $globalStats[$code]['product_hits']++;
                    $globalStats[$code]['top3_hits'] += (int)$rank < 3 ? 1 : 0;
                    $globalStats[$code]['rank_points'] += $rankPoints;
                    $globalStats[$code]['score_sum'] += $score;
                    $globalStats[$code]['best_score'] = max((int)$globalStats[$code]['best_score'], $score);
                    if (preg_match('~\b(?:прочие|прочих|прочая|прочее|прочий|прочего)\b~u', supplier_products_db_attr_norm($value))) {
                        $globalStats[$code]['general_leaf_hits']++;
                    }
                    foreach ((array)($row['match_reasons'] ?? []) as $reason) {
                        $reason = trim((string)$reason);
                        if ($reason !== '') {
                            $globalStats[$code]['reasons'][$reason] = true;
                        }
                    }
                    if (!isset($groupStats[$groupKey][$code])) {
                        $groupStats[$groupKey][$code] = [
                            'code' => $code,
                            'top3_hits' => 0,
                            'rank_points' => 0,
                            'score_sum' => 0,
                        ];
                    }
                    $groupStats[$groupKey][$code]['top3_hits'] += (int)$rank < 3 ? 1 : 0;
                    $groupStats[$groupKey][$code]['rank_points'] += $rankPoints;
                    $groupStats[$groupKey][$code]['score_sum'] += $score;
                    if ($value !== '') {
                        $targetValues[$targetKey][$code] = $value;
                    }
                }
            }
        }

        $sortRows = static function (array &$rows): void {
            usort($rows, static function (array $a, array $b): int {
                foreach (['top3_hits', 'rank_points', 'score_sum', 'general_leaf_hits', 'product_hits', 'best_score'] as $key) {
                    $cmp = ((int)($b[$key] ?? 0) <=> (int)($a[$key] ?? 0));
                    if ($cmp !== 0) {
                        return $cmp;
                    }
                }
                return strcmp((string)($a['code'] ?? ''), (string)($b['code'] ?? ''));
            });
        };
        $globalRows = array_values($globalStats);
        $sortRows($globalRows);

        $effectiveLimit = min(30, max($limit, min(24, count($groupStats) * 3)));
        $selectedCodes = [];
        foreach ($groupStats as $rowsByCode) {
            $rows = array_values($rowsByCode);
            $sortRows($rows);
            foreach (array_slice($rows, 0, 3) as $row) {
                $code = (string)($row['code'] ?? '');
                if ($code !== '') {
                    $selectedCodes[$code] = true;
                }
            }
        }
        foreach ($globalRows as $row) {
            if (count($selectedCodes) >= $effectiveLimit) {
                break;
            }
            $code = (string)($row['code'] ?? '');
            if ($code !== '') {
                $selectedCodes[$code] = true;
            }
        }
        if (count($selectedCodes) > $effectiveLimit) {
            $priority = [];
            foreach ($globalRows as $idx => $row) {
                $priority[(string)($row['code'] ?? '')] = $idx;
            }
            $codes = array_keys($selectedCodes);
            usort($codes, static fn(string $a, string $b): int => ((int)($priority[$a] ?? PHP_INT_MAX) <=> (int)($priority[$b] ?? PHP_INT_MAX)));
            $selectedCodes = array_fill_keys(array_slice($codes, 0, $effectiveLimit), true);
        }

        $shortlist = [];
        foreach ($globalRows as $row) {
            $code = (string)($row['code'] ?? '');
            if ($code === '' || !isset($selectedCodes[$code])) {
                continue;
            }
            $shortlist[] = [
                'code' => $code,
                'value' => (string)($row['value'] ?? $code),
                'product_hits' => (int)($row['product_hits'] ?? 0),
                'top3_hits' => (int)($row['top3_hits'] ?? 0),
                'rank_points' => (int)($row['rank_points'] ?? 0),
                'score' => (int)($row['best_score'] ?? 0),
                'general_leaf' => (int)($row['general_leaf_hits'] ?? 0) > 0,
                'match_reasons' => array_values(array_slice(array_keys((array)($row['reasons'] ?? [])), 0, 5)),
            ];
        }

        foreach ((array)$scope['offers'] as $offerId) {
            if (!isset($jobs[$offerId])) {
                continue;
            }
            $payload = (array)($jobs[$offerId]['payload'] ?? []);
            $targets = [];
            foreach ((array)($payload['target_attributes'] ?? []) as $target) {
                if (!is_array($target)) {
                    continue;
                }
                $source = (string)($target['marketplace'] ?? '');
                $targetKey = $source . "\n" . supplier_products_db_attr_norm((string)($target['attribute_name'] ?? ''));
                $rows = [];
                foreach ($shortlist as $candidate) {
                    $code = (string)($candidate['code'] ?? '');
                    $value = (string)($targetValues[$targetKey][$code] ?? '');
                    if ($code === '' || $value === '') {
                        continue;
                    }
                    $rows[] = [
                        'code' => $code,
                        'value' => $value,
                        'score' => (int)($candidate['score'] ?? 0),
                        'match_reasons' => array_values((array)($candidate['match_reasons'] ?? [])),
                        'category_product_hits' => (int)($candidate['product_hits'] ?? 0),
                        'category_top3_hits' => (int)($candidate['top3_hits'] ?? 0),
                    ];
                }
                if ($rows) {
                    $target['allowed_values'] = $rows;
                    $target['allowed_values_in_prompt'] = count($rows);
                    $target['allowed_values_are_shortlist'] = true;
                    $target['allowed_values_truncated'] = (int)($target['allowed_values_count'] ?? 0) > count($rows);
                    $target['category_shortlist_scope'] = $scopeKey;
                    $target['candidate_policy'] = (string)($target['marketplace'] ?? '') === 'ozon'
                        ? 'choose_only_from_category_shortlist; category_dictionary_is_authoritative; choose_broadest_suitable_leaf_code'
                        : 'prefer_category_shortlist; choose_broadest_suitable_leaf_code';
                }
                $targets[] = $target;
            }
            $payload['target_attributes'] = $targets;
            $payload['category_tnved_shortlist'] = [
                'scope_key' => $scopeKey,
                'category_label' => (string)($scope['label'] ?? ''),
                'products_in_scope' => count((array)$scope['offers']),
                'allowed_values_original' => $originalValuesCount,
                'candidate_codes' => $shortlist,
            ];
            $jobs[$offerId]['payload'] = $payload;
        }

        $plans[$scopeKey] = [
            'scope_key' => $scopeKey,
            'label' => (string)($scope['label'] ?? ''),
            'products' => count((array)$scope['offers']),
            'tnved_groups' => count($groupStats),
            'preferred_dictionary_source' => $preferredSource !== '' ? $preferredSource : 'available_marketplace',
            'allowed_values_original' => $originalValuesCount,
            'shortlist_count' => count($shortlist),
            'shortlist' => $shortlist,
        ];
    }

    return $plans;
}

function supplier_products_db_tnved_group_decision_applicable_to_job(
    array $candidate,
    array $job,
    array $payload,
    float $minConfidence
): array {
    $code = supplier_products_db_tnved_code_from_text((string)($candidate['tnved_code'] ?? ''));
    if ($code === '') {
        return ['ok' => false, 'reason' => 'empty_code'];
    }
    if (supplier_products_db_tnved_non_leaf_reason($code) !== '') {
        return ['ok' => false, 'reason' => 'non_leaf_code'];
    }
    $confidence = max(0.0, min(1.0, (float)($candidate['confidence'] ?? 0.86)));
    if ($confidence < max(0.76, $minConfidence - 0.04)) {
        return ['ok' => false, 'reason' => 'low_confidence'];
    }

    $suggestedValue = trim((string)($candidate['marketplace_value'] ?? $code));
    if ($suggestedValue === '') {
        $suggestedValue = $code;
    }
    $searchText = supplier_products_db_tnved_search_text_with_analysis(
        $payload,
        [],
        (array)($payload['classification_hints'] ?? [])
    );
    $decision = [
        'tnved_code' => $code,
        'marketplace_value' => $suggestedValue,
        'confidence' => $confidence,
        'review_required' => false,
        'risk_flags' => (array)($candidate['risk_flags'] ?? []),
        'alternatives' => (array)($candidate['alternatives'] ?? []),
        'reason' => (string)($candidate['reason'] ?? 'Переиспользовано устойчивое групповое решение.'),
    ];
    $guard = supplier_products_db_tnved_apply_profile_guard($decision, $searchText, []);
    $decision = (array)($guard['decision'] ?? $decision);
    $guardCode = supplier_products_db_tnved_code_from_text((string)($decision['tnved_code'] ?? ''));
    if ($guardCode === '' || $guardCode !== $code || !empty($decision['review_required'])) {
        return ['ok' => false, 'reason' => 'profile_guard_rejected'];
    }

    $hasWritableTarget = false;
    foreach ((array)($job['targets'] ?? []) as $target) {
        if (!is_array($target)) {
            continue;
        }
        $resolved = supplier_products_db_tnved_marketplace_value(
            $code,
            (string)($decision['marketplace_value'] ?? $suggestedValue),
            $target,
            (string)($job['tnved_search_text'] ?? '')
        );
        $value = trim((string)($resolved['value'] ?? ''));
        $requiresDictionary = !empty($target['requires_dictionary']) || supplier_products_db_tnved_target_requires_dictionary($target);
        if ($requiresDictionary && $value === '') {
            return ['ok' => false, 'reason' => 'not_in_required_dictionary'];
        }
        if ($value !== '') {
            $hasWritableTarget = true;
        }
    }
    if (!$hasWritableTarget) {
        return ['ok' => false, 'reason' => 'no_writable_target'];
    }

    $decision['tnved_code'] = $code;
    $decision['marketplace_value'] = (string)($decision['marketplace_value'] ?? $suggestedValue);
    $decision['confidence'] = $confidence;
    $decision['review_required'] = false;
    return ['ok' => true, 'decision' => $decision, 'reason' => 'ok'];
}

function supplier_products_db_tnved_memory_auto_decision(array $memoryRows, int $minCount, float $minShare): array
{
    $first = $memoryRows[0] ?? null;
    if (!is_array($first)) {
        return [];
    }
    $code = supplier_products_db_tnved_code_from_text((string)($first['code'] ?? ''));
    $count = (int)($first['count'] ?? 0);
    $share = (float)($first['share'] ?? 0);
    if ($code === '' || supplier_products_db_tnved_non_leaf_reason($code) !== '' || $count < $minCount || $share < $minShare) {
        return [];
    }
    return [
        'tnved_code' => $code,
        'marketplace_value' => $code,
        'confidence' => min(0.96, max(0.84, $share)),
        'review_required' => false,
        'reason' => 'Автовыбор по устойчивой памяти категории поставщика: код уже встречался ' . $count . ' раз, доля ' . round($share * 100) . '%.',
        'source' => 'supplier_category_memory',
        'memory_count' => $count,
        'memory_share' => $share,
    ];
}

function supplier_products_db_tnved_signature_memory_decision(array $memoryRows, string $signatureTitle, int $minCodeCount): array
{
    $signatureTitle = supplier_products_db_tnved_signature_title($signatureTitle);
    if ($signatureTitle === '') {
        return [];
    }

    $best = null;
    foreach ($memoryRows as $row) {
        if (!is_array($row)) {
            continue;
        }
        $code = supplier_products_db_tnved_code_from_text((string)($row['code'] ?? ''));
        $count = (int)($row['count'] ?? 0);
        if ($code === '' || supplier_products_db_tnved_non_leaf_reason($code) !== '' || $count < $minCodeCount) {
            continue;
        }
        $matches = 0;
        foreach ((array)($row['examples'] ?? []) as $example) {
            if (!is_array($example)) {
                continue;
            }
            $exampleTitle = supplier_products_db_tnved_signature_title((string)($example['name'] ?? ''));
            if ($exampleTitle !== '' && $exampleTitle === $signatureTitle) {
                $matches++;
            }
        }
        if ($matches <= 0) {
            continue;
        }
        $score = ($matches * 1000) + $count;
        if ($best === null || $score > (int)($best['score'] ?? 0)) {
            $best = [
                'code' => $code,
                'count' => $count,
                'matches' => $matches,
                'share' => (float)($row['share'] ?? 0),
                'score' => $score,
            ];
        }
    }

    if ($best === null) {
        return [];
    }

    $confidence = min(0.94, max(0.86, 0.82 + min(0.08, ((int)$best['matches']) * 0.03) + min(0.04, ((int)$best['count']) / 50)));
    return [
        'tnved_code' => (string)$best['code'],
        'marketplace_value' => (string)$best['code'],
        'confidence' => $confidence,
        'review_required' => false,
        'reason' => 'Автовыбор по похожим товарам в категории поставщика: сигнатура "' . $signatureTitle . '", совпадений ' . (int)$best['matches'] . ', код встречался ' . (int)$best['count'] . ' раз.',
        'source' => 'supplier_category_signature_memory',
        'memory_count' => (int)$best['count'],
        'memory_matches' => (int)$best['matches'],
        'memory_share' => (float)$best['share'],
    ];
}

function supplier_products_db_tnved_string_list($value, int $limit = 8, int $maxLen = 80): array
{
    $out = [];
    foreach ((array)$value as $item) {
        if (is_array($item) || is_object($item)) {
            continue;
        }
        $item = acp_trunc(trim((string)$item), $maxLen);
        if ($item === '' || in_array($item, $out, true)) {
            continue;
        }
        $out[] = $item;
        if (count($out) >= $limit) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_tnved_bool($value): bool
{
    if (is_bool($value)) {
        return $value;
    }
    return in_array(strtolower(trim((string)$value)), ['1', 'true', 'yes', 'ok', 'approved', 'correct', 'да', 'верно'], true);
}

function supplier_products_db_tnved_normalize_analysis(array $decoded): array
{
    $partRaw = $decoded['is_part_or_accessory'] ?? false;
    $isPartOrAccessory = supplier_products_db_tnved_bool($partRaw)
        || in_array(strtolower(trim((string)$partRaw)), ['part', 'accessory'], true);
    return [
        'product_role' => acp_trunc(trim((string)($decoded['product_role'] ?? '')), 80),
        'product_type' => acp_trunc(trim((string)($decoded['product_type'] ?? '')), 120),
        'target_objects' => supplier_products_db_tnved_string_list($decoded['target_objects'] ?? ($decoded['target_object'] ?? []), 8, 90),
        'materials' => supplier_products_db_tnved_string_list($decoded['materials'] ?? [], 8, 80),
        'is_part_or_accessory' => $isPartOrAccessory,
        'likely_headings' => supplier_products_db_tnved_string_list($decoded['likely_headings'] ?? [], 8, 80),
        'include_terms' => supplier_products_db_tnved_string_list($decoded['include_terms'] ?? ($decoded['include_tnved_terms'] ?? []), 10, 80),
        'exclude_terms' => supplier_products_db_tnved_string_list($decoded['exclude_terms'] ?? ($decoded['exclude_tnved_terms'] ?? []), 10, 80),
        'confidence' => max(0.0, min(1.0, (float)($decoded['confidence'] ?? 0))),
        'reason' => acp_trunc(trim((string)($decoded['reason'] ?? '')), 300),
    ];
}

function supplier_products_db_tnved_decision_from_decoded(array $decoded): array
{
    $alternatives = [];
    foreach ((array)($decoded['alternatives'] ?? []) as $row) {
        if (!is_array($row)) {
            $row = ['code' => (string)$row, 'reason' => ''];
        }
        $code = supplier_products_db_tnved_code_from_text((string)($row['code'] ?? ''));
        if ($code === '') {
            continue;
        }
        $alternatives[] = [
            'code' => $code,
            'reason' => acp_trunc(trim((string)($row['reason'] ?? '')), 180),
        ];
        if (count($alternatives) >= 5) {
            break;
        }
    }
    $code = supplier_products_db_tnved_code_from_text((string)($decoded['tnved_code'] ?? ($decoded['code'] ?? '')));
    return [
        'tnved_code' => $code,
        'marketplace_value' => trim((string)($decoded['marketplace_value'] ?? ($decoded['value'] ?? $code))),
        'confidence' => max(0.0, min(1.0, (float)($decoded['confidence'] ?? 0))),
        'reason' => acp_trunc(trim((string)($decoded['reason'] ?? '')), 320),
        'review_required' => supplier_products_db_tnved_bool($decoded['review_required'] ?? false),
        'risk_flags' => supplier_products_db_tnved_string_list($decoded['risk_flags'] ?? [], 8, 100),
        'alternatives' => $alternatives,
    ];
}

function supplier_products_db_tnved_verification_decision(array $decoded): array
{
    $raw = is_array($decoded['verification'] ?? null) ? (array)$decoded['verification'] : $decoded;
    $approvedRaw = $raw['approved'] ?? ($raw['is_correct'] ?? null);
    $approved = supplier_products_db_tnved_bool($approvedRaw);
    return [
        'approved' => $approved,
        'confidence' => max(0.0, min(1.0, (float)($raw['confidence'] ?? $raw['verified_confidence'] ?? 0))),
        'better_code' => supplier_products_db_tnved_code_from_text((string)($raw['better_code'] ?? $raw['correct_code'] ?? '')),
        'reason' => acp_trunc(trim((string)($raw['reason'] ?? '')), 280),
    ];
}

function supplier_products_db_tnved_apply_verification_to_decision(
    array $decision,
    array $verification,
    float $minVerifiedConfidence
): array {
    $code = supplier_products_db_tnved_code_from_text((string)($decision['tnved_code'] ?? ''));
    if ($code === '') {
        return $decision;
    }

    $verifiedConfidence = (float)($verification['confidence'] ?? 0);
    $approved = !empty($verification['approved']) && $verifiedConfidence >= $minVerifiedConfidence;
    $decision['verification'] = [
        'approved' => !empty($verification['approved']) ? 1 : 0,
        'confidence' => round($verifiedConfidence, 3),
        'better_code' => (string)($verification['better_code'] ?? ''),
        'reason' => (string)($verification['reason'] ?? ''),
    ];

    if (!$approved) {
        $betterCode = supplier_products_db_tnved_code_from_text((string)($verification['better_code'] ?? ''));
        if ($betterCode !== '' && $betterCode !== $code && $verifiedConfidence >= max(0.7, $minVerifiedConfidence - 0.08)) {
            $decision['tnved_code'] = $betterCode;
            $decision['marketplace_value'] = $betterCode;
            $decision['confidence'] = min(0.88, max((float)($decision['confidence'] ?? 0), $verifiedConfidence));
            $decision['review_required'] = true;
            $decision['verification_corrected'] = 1;
            $decision['reason'] = acp_trunc(trim((string)($decision['reason'] ?? '') . ' Проверка предложила более подходящий код ' . $betterCode . ': ' . (string)($verification['reason'] ?? '')), 320);
            return $decision;
        }
        $decision['confidence'] = min((float)($decision['confidence'] ?? 0), max(0.0, $minVerifiedConfidence - 0.03));
        $decision['verification_rejected'] = 1;
        $decision['reason'] = acp_trunc(trim((string)($decision['reason'] ?? '') . ' Проверка: ' . (string)($verification['reason'] ?? '')), 320);
        return $decision;
    }

    $decision['confidence'] = min((float)($decision['confidence'] ?? 0), max($minVerifiedConfidence, $verifiedConfidence));
    $decision['verification_approved'] = 1;
    return $decision;
}

function supplier_products_db_attr_exclude_map(string $source, array $cfg): array
{
    $out = [];
    $names = [];
    try {
        $names = taxonomy_get_global_exclude_attribute_names($source, $cfg);
    } catch (Throwable $e) {
        $names = taxonomy_global_exclusions_config_fallback($source, $cfg);
    }
    foreach ($names as $name) {
        $key = supplier_products_db_attr_norm((string)$name);
        if ($key !== '') {
            $out[$key] = true;
        }
    }
    return $out;
}

function supplier_products_db_is_country_attribute(string $name): bool
{
    $n = supplier_products_db_attr_norm($name);
    return in_array($n, [
        'страна производитель',
        'страна производства',
        'страна изготовитель',
        'страна происхождения',
        'country of origin',
        'country',
    ], true);
}

function supplier_products_db_build_category_attrs(string $source, array $meta, array $excludeMap): array
{
    $attrsMeta = [];
    $fallbackNames = [];
    if ($source === 'ozon') {
        $attrsMeta = is_array($meta['ozon_required_attributes_meta'] ?? null) ? $meta['ozon_required_attributes_meta'] : [];
        $fallbackNames = is_array($meta['ozon_required_attributes'] ?? null) ? $meta['ozon_required_attributes'] : [];
    } else {
        $attrsMeta = is_array($meta['wb_characteristics_meta'] ?? null) ? $meta['wb_characteristics_meta'] : [];
        $fallbackNames = is_array($meta['wb_required_attributes'] ?? null) ? $meta['wb_required_attributes'] : [];
    }
    $requiredFallbackKeys = [];
    foreach ($fallbackNames as $fallbackName) {
        foreach (supplier_products_db_attr_candidate_keys((string)$fallbackName) as $fallbackKey) {
            if ($fallbackKey !== '') {
                $requiredFallbackKeys[$fallbackKey] = true;
            }
        }
    }

    $attrs = [];
    $seen = [];
    foreach ($attrsMeta as $row) {
        if (!is_array($row)) {
            continue;
        }
        $name = trim((string)($row['name'] ?? ''));
        if ($name === '' || supplier_products_is_hashtags_field_name($name)) {
            continue;
        }
        $key = supplier_products_db_attr_norm($name);
        if ($key === '' || isset($excludeMap[$key]) || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $isRequired = !empty($row['required']) || !empty($row['is_required']) || isset($requiredFallbackKeys[$key]);

        $isCountry = supplier_products_db_is_country_attribute($name);
        $isOzonReleaseType = supplier_products_db_is_ozon_release_type_attribute($source, $name);
        $allowed = [];
        if ($isOzonReleaseType) {
            $allowed = supplier_products_db_ozon_release_type_allowed_values(
                is_array($row['allowed_values'] ?? null) ? (array)$row['allowed_values'] : []
            );
        } elseif (!$isCountry && is_array($row['allowed_values'] ?? null)) {
            foreach ($row['allowed_values'] as $value) {
                $value = trim((string)$value);
                $valueKey = supplier_products_db_attr_norm($value);
                if ($value !== '' && $valueKey !== '') {
                    $allowed[$valueKey] = $value;
                }
            }
        }
        $allowedLimit = supplier_products_db_is_tnved_attribute_name($name) ? 1000 : 250;
        $allowed = array_slice(array_values($allowed), 0, $allowedLimit);

        $description = trim((string)($row['description'] ?? ''));
        if ($allowed) {
            $description = 'Выбери строго одно значение из allowed_values. Не используй синонимы.';
        } elseif ($isCountry) {
            $description = trim($description . ' Используй обычное общеизвестное название страны.');
        }
        if ($isOzonReleaseType) {
            $description = 'Выбери строго одно значение из allowed_values. Для обычных серийных товаров используй "Фабричное производство". "Ручная, авторская работа" выбирай только для handmade/ручной авторской работы. "По индивидуальному дизайну" выбирай только если товар явно изготовлен под индивидуальный дизайн или на заказ.';
        }
        if ($source === 'ozon' && supplier_products_db_is_single_value_color_attribute_name($name)) {
            $description = trim($description . ' Для Ozon укажи только одно основное значение цвета, без перечисления нескольких цветов.');
        }
        if ($source === 'wildberries') {
            $parts = [];
            if (!empty($row['required'])) $parts[] = 'Обязательный атрибут.';
            if (trim((string)($row['unit'] ?? '')) !== '') $parts[] = 'Единица: ' . trim((string)$row['unit']) . '.';
            if (!empty($row['popular'])) $parts[] = 'Популярная характеристика.';
            if ($description !== '') $parts[] = $description;
            $description = trim(implode(' ', $parts));
        }

        $attrs[] = [
            'source' => $source,
            'name' => $name,
            'description' => $description,
            'id' => isset($row['id']) ? (int)$row['id'] : (int)($row['charcID'] ?? 0),
            'attribute_complex_id' => (int)($row['attribute_complex_id'] ?? ($row['complex_id'] ?? 0)),
            'required' => $isRequired,
            'dictionary_id' => (int)($row['dictionary_id'] ?? 0),
            'max_count' => (int)($row['max_count'] ?? ($row['maxCount'] ?? 0)),
            'unit' => trim((string)($row['unit'] ?? '')),
            'allowed_values' => $allowed,
            'selection_mode' => $allowed ? 'choose_one' : ($isCountry ? 'known_country' : 'free'),
            'value_source' => $allowed ? ($source === 'wildberries' ? 'wb_directory' : 'ozon_dictionary') : ($isCountry ? 'known_country' : 'free_text'),
        ];
    }

    if (!$attrs) {
        foreach ($fallbackNames as $name) {
            $name = trim((string)$name);
            if ($name === '' || supplier_products_is_hashtags_field_name($name)) {
                continue;
            }
            $key = supplier_products_db_attr_norm($name);
            if ($key === '' || isset($excludeMap[$key]) || isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;
            $attrs[] = [
                'source' => $source,
                'name' => $name,
                'description' => '',
                'id' => 0,
                'required' => true,
                'allowed_values' => [],
                'selection_mode' => supplier_products_db_is_country_attribute($name) ? 'known_country' : 'free',
                'value_source' => supplier_products_db_is_country_attribute($name) ? 'known_country' : 'free_text',
            ];
        }
    }

    return $attrs;
}

function supplier_products_db_load_attr_category(string $source, string $code, array $cfg, bool $forceReload = false): ?array
{
    static $cache = [];
    $source = trim($source);
    $code = trim($code);
    if ($source === '' || $code === '') {
        return null;
    }
    $cacheKey = $source . ':' . $code;
    if (!$forceReload && array_key_exists($cacheKey, $cache)) {
        return $cache[$cacheKey];
    }

    if ($source === 'ozon') {
        if (!preg_match('~^(\d+)_(\d+)$~', $code, $m)) {
            $cache[$cacheKey] = null;
            return null;
        }
        $st = db()->prepare("
            SELECT *
            FROM feedtools_taxonomy_categories
            WHERE source = 'ozon'
              AND is_leaf = 1
              AND ozon_parent_id = ?
              AND ozon_leaf_id = ?
            LIMIT 1
        ");
        $st->execute([(int)$m[1], (int)$m[2]]);
    } elseif ($source === 'wildberries') {
        if (!ctype_digit($code)) {
            $cache[$cacheKey] = null;
            return null;
        }
        $st = db()->prepare("
            SELECT *
            FROM feedtools_taxonomy_categories
            WHERE source = 'wildberries'
              AND is_leaf = 1
              AND external_id = ?
            LIMIT 1
        ");
        $st->execute(['wb:subject:' . $code]);
    } else {
        $cache[$cacheKey] = null;
        return null;
    }

    $row = $st->fetch(PDO::FETCH_ASSOC);
    if (!is_array($row)) {
        $cache[$cacheKey] = null;
        return null;
    }

    $meta = [];
    if (trim((string)($row['meta_json'] ?? '')) !== '') {
        $decoded = json_decode((string)$row['meta_json'], true);
        if (is_array($decoded)) {
            $meta = $decoded;
        }
    }
    $attrs = supplier_products_db_build_category_attrs($source, $meta, supplier_products_db_attr_exclude_map($source, $cfg));

    $cache[$cacheKey] = [
        'source' => $source,
        'source_label' => $source === 'wildberries' ? 'Wildberries' : 'Ozon',
        'code' => $code,
        'name' => (string)($row['name'] ?? ''),
        'full_path' => (string)($row['full_path'] ?? ''),
        'description' => (string)($meta['description'] ?? ''),
        'typical_goods' => (string)($meta['typical_goods'] ?? ''),
        'features' => (string)($meta['features'] ?? ''),
        'category_attributes' => $attrs,
    ];
    return $cache[$cacheKey];
}

function supplier_products_db_merge_category_attrs(array $contexts): array
{
    $merged = [];
    foreach ($contexts as $ctx) {
        if (!is_array($ctx)) {
            continue;
        }
        $source = (string)($ctx['source'] ?? '');
        foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
            if (!is_array($attr)) {
                continue;
            }
            $name = trim((string)($attr['name'] ?? ''));
            $key = supplier_products_db_attr_norm($name);
            if ($key === '') {
                continue;
            }
            if (!isset($merged[$key])) {
                $merged[$key] = [
                    'name' => $name,
                    'marketplaces' => [],
                    'description_parts' => [],
                    'allowed_values_by_marketplace' => [],
                ];
            }
            if ($source !== '' && !in_array($source, $merged[$key]['marketplaces'], true)) {
                $merged[$key]['marketplaces'][] = $source;
            }
            $desc = trim((string)($attr['description'] ?? ''));
            if ($desc !== '') {
                $label = $source === 'wildberries' ? 'Wildberries' : 'Ozon';
                $merged[$key]['description_parts'][] = '[' . $label . '] ' . $desc;
            }
            $allowed = array_values(array_filter(array_map('strval', (array)($attr['allowed_values'] ?? []))));
            if ($allowed && $source !== '') {
                $merged[$key]['allowed_values_by_marketplace'][$source] = $allowed;
            }
        }
    }

    return array_values(array_map(static function (array $row): array {
        $row['marketplaces'] = array_values(array_unique($row['marketplaces']));
        $row['description'] = implode(' ', array_values(array_unique($row['description_parts'])));
        unset($row['description_parts']);
        return $row;
    }, $merged));
}

function supplier_products_db_llm_attr_context(array $context): array
{
    $out = [
        'source' => (string)($context['source'] ?? ''),
        'source_label' => (string)($context['source_label'] ?? ''),
        'code' => (string)($context['code'] ?? ''),
        'name' => (string)($context['name'] ?? ''),
        'full_path' => (string)($context['full_path'] ?? ''),
        'category_attributes' => [],
    ];

    foreach ((array)($context['category_attributes'] ?? []) as $attr) {
        if (is_array($attr)) {
            if (supplier_products_db_gpt_offer_params_excluded_attr((string)($attr['name'] ?? ''))) {
                continue;
            }
            if (supplier_products_db_is_ozon_fits_for_attribute((string)($context['source'] ?? ''), (string)($attr['name'] ?? ''))) {
                $desc = trim((string)($attr['description'] ?? ''));
                $attr['description'] = trim($desc . ' Для Ozon это первая часть комплексной характеристики совместимости: поле принимает только бренд совместимости. Пиши чистые названия брендов без моделей, серий, категорий, типов устройств и пояснений. Если бренд совместимости неясен, используй бренд самого товара.');
            }
            if (supplier_products_db_is_ozon_compatible_models_attribute((string)($context['source'] ?? ''), (string)($attr['name'] ?? ''))) {
                $desc = trim((string)($attr['description'] ?? ''));
                $attr['description'] = trim($desc . ' Для Ozon это вторая часть комплексной характеристики совместимости: пиши только модели и коды моделей без бренда, категории и пояснений. Для запчастей телефонов сохраняй точные обозначения моделей; если моделей несколько, возвращай values.');
            }
            $out['category_attributes'][] = $attr;
        }
    }

    return $out;
}

function supplier_products_db_value_allowed_for_attr(string $value, array $attr): ?string
{
    $values = supplier_products_db_values_allowed_for_attr($value, $attr);
    return $values[0] ?? null;
}

function supplier_products_db_values_allowed_for_attr(string $value, array $attr): array
{
    $value = trim((string)preg_replace('/\s+/u', ' ', $value));
    if ($value === '') {
        return [];
    }
    if (mb_strlen($value, 'UTF-8') > 600) {
        $value = mb_substr($value, 0, 600, 'UTF-8');
    }

    $allowed = array_values(array_filter(array_map('strval', (array)($attr['allowed_values'] ?? []))));
    if (function_exists('supplier_products_normalize_characteristic_values')) {
        return supplier_products_db_limit_values_for_attr(
            supplier_products_normalize_characteristic_values([$value], $allowed, (bool)$allowed),
            $attr
        );
    }
    if (!$allowed) {
        return supplier_products_db_limit_values_for_attr([$value], $attr);
    }

    $parts = preg_split('/\s*[;\|\n\r]+\s*/u', $value, -1, PREG_SPLIT_NO_EMPTY) ?: [$value];
    $out = [];
    $seen = [];
    foreach ($parts as $part) {
        $part = trim((string)$part);
        if ($part === '') {
            continue;
        }
        $key = supplier_products_db_attr_norm($part);
        foreach ($allowed as $candidate) {
            $candidateKey = supplier_products_db_attr_norm((string)$candidate);
            if ($candidateKey !== '' && $candidateKey === $key && !isset($seen[$candidateKey])) {
                $seen[$candidateKey] = true;
                $out[] = (string)$candidate;
                break;
            }
        }
    }
    return supplier_products_db_limit_values_for_attr($out, $attr);
}

function supplier_products_db_add_param_if_missing(
    PDO $pdo,
    int $supplierId,
    int $productId,
    string $kind,
    string $name,
    string $value
): bool {
    $kind = supplier_products_validate_field_kind($kind);
    if ($kind !== 'param' && $kind !== 'wb_param') {
        return false;
    }
    $name = supplier_products_validate_field_name($kind, $name);
    $value = supplier_products_db_normalize_param_value_for_kind($kind, $value);
    if ($supplierId <= 0 || $productId <= 0 || $name === '' || $value === '') {
        return false;
    }

    $st = $pdo->prepare("
        SELECT id, field_value
        FROM feedtools_supplier_product_fields
        WHERE product_id = ?
          AND field_kind = ?
          AND field_name = ?
        ORDER BY sort_order ASC, id ASC
    ");
    $st->execute([$productId, $kind, $name]);
    $rows = $st->fetchAll(PDO::FETCH_ASSOC) ?: [];
    $emptyRowId = 0;
    $valueKeys = [];
    foreach (function_exists('supplier_products_normalize_characteristic_values') ? supplier_products_normalize_characteristic_values([$value]) : [$value] as $part) {
        $key = supplier_products_db_attr_norm((string)$part);
        if ($key !== '') {
            $valueKeys[$key] = true;
        }
    }
    foreach ($rows as $row) {
        $existingValue = trim((string)($row['field_value'] ?? ''));
        if ($existingValue === '' && $emptyRowId <= 0) {
            $emptyRowId = (int)($row['id'] ?? 0);
            continue;
        }
        $existingParts = function_exists('supplier_products_normalize_characteristic_values')
            ? supplier_products_normalize_characteristic_values([$existingValue])
            : [$existingValue];
        foreach ($existingParts as $existingPart) {
            $existingKey = supplier_products_db_attr_norm((string)$existingPart);
            if ($existingKey !== '' && isset($valueKeys[$existingKey])) {
                return false;
            }
        }
    }

    if ($emptyRowId > 0) {
        $upd = $pdo->prepare("UPDATE feedtools_supplier_product_fields SET field_value = ? WHERE id = ?");
        $upd->execute([$value, $emptyRowId]);
        return true;
    }

    $sort = $pdo->prepare("SELECT COALESCE(MAX(sort_order), 0) + 10 FROM feedtools_supplier_product_fields WHERE product_id = ?");
    $sort->execute([$productId]);
    $sortOrder = (int)$sort->fetchColumn();
    $ins = $pdo->prepare("
        INSERT INTO feedtools_supplier_product_fields (
            supplier_id, product_id, field_kind, field_name, field_value, sort_order
        ) VALUES (?, ?, ?, ?, ?, ?)
    ");
    $ins->execute([$supplierId, $productId, $kind, $name, $value, $sortOrder]);
    return true;
}

function supplier_products_db_set_param_value(
    PDO $pdo,
    int $supplierId,
    int $productId,
    string $kind,
    string $name,
    string $value
): bool {
    $kind = supplier_products_validate_field_kind($kind);
    if ($kind !== 'param' && $kind !== 'wb_param') {
        return false;
    }
    $name = supplier_products_validate_field_name($kind, $name);
    $value = supplier_products_db_normalize_param_value_for_kind($kind, $value);
    if ($supplierId <= 0 || $productId <= 0 || $name === '' || $value === '') {
        return false;
    }

    $st = $pdo->prepare("
        SELECT id, field_value
        FROM feedtools_supplier_product_fields
        WHERE product_id = ?
          AND field_kind = ?
          AND field_name = ?
        ORDER BY sort_order ASC, id ASC
    ");
    $st->execute([$productId, $kind, $name]);
    $rows = $st->fetchAll(PDO::FETCH_ASSOC) ?: [];
    if ($rows) {
        $changed = false;
        $upd = $pdo->prepare("UPDATE feedtools_supplier_product_fields SET field_value = ? WHERE id = ?");
        foreach ($rows as $row) {
            $fieldId = (int)($row['id'] ?? 0);
            if ($fieldId <= 0) {
                continue;
            }
            if (trim((string)($row['field_value'] ?? '')) === $value) {
                continue;
            }
            $upd->execute([$value, $fieldId]);
            $changed = true;
        }
        return $changed;
    }

    $sort = $pdo->prepare("SELECT COALESCE(MAX(sort_order), 0) + 10 FROM feedtools_supplier_product_fields WHERE product_id = ?");
    $sort->execute([$productId]);
    $sortOrder = (int)$sort->fetchColumn();
    $ins = $pdo->prepare("
        INSERT INTO feedtools_supplier_product_fields (
            supplier_id, product_id, field_kind, field_name, field_value, sort_order
        ) VALUES (?, ?, ?, ?, ?, ?)
    ");
    $ins->execute([$supplierId, $productId, $kind, $name, $value, $sortOrder]);
    return true;
}

function supplier_products_db_delete_param_values(
    PDO $pdo,
    int $supplierId,
    int $productId,
    string $kind,
    string $name
): bool {
    $kind = supplier_products_validate_field_kind($kind);
    if ($kind !== 'param' && $kind !== 'wb_param') {
        return false;
    }
    $name = supplier_products_validate_field_name($kind, $name);
    if ($supplierId <= 0 || $productId <= 0 || $name === '') {
        return false;
    }

    $del = $pdo->prepare("
        DELETE FROM feedtools_supplier_product_fields
        WHERE supplier_id = ?
          AND product_id = ?
          AND field_kind = ?
          AND field_name = ?
    ");
    $del->execute([$supplierId, $productId, $kind, $name]);
    return $del->rowCount() > 0;
}

function supplier_products_db_op_analyze_category_products(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }
    $supplier = suppliers_get($supplierId);
    $supplierCode = is_array($supplier) ? suppliers_normalize_code((string)($supplier['supplier_code'] ?? '')) : '';

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);

    $model = LLM::modelForOp($cfg, $params);
    $maxCats = max(0, (int)trim((string)($params['max_categories'] ?? '0')));
    $maxPerCat = max(5, (int)trim((string)($params['max_products_per_category'] ?? '60')));
    $descMax = max(0, (int)trim((string)($params['max_desc_len'] ?? '280')));
    $onlyMissing = ((string)($params['only_missing'] ?? '1') !== '' && (string)($params['only_missing'] ?? '1') !== '0');
    $refreshFilledIfChanged = ((string)($params['refresh_filled_if_changed'] ?? '1') !== '' && (string)($params['refresh_filled_if_changed'] ?? '1') !== '0');
    $searchQueriesEnabled = acp_param_bool($params, 'search_queries_enabled', true);
    $searchQuerySkuLimit = acp_param_int($params, 'search_queries_sku_limit', 300, 1, 1000);
    $searchQueryOfferLimit = min(3000, max($maxPerCat, $searchQuerySkuLimit * 3));
    $searchQueryKeywordLinesLimit = acp_param_int($params, 'search_queries_keyword_lines_limit', 40, 1, 120);

    $log(
        "supplier_db analyze_category_products: model={$model}, max_categories={$maxCats}, max_products_per_category={$maxPerCat}, " .
        'only_missing=' . ($onlyMissing ? '1' : '0') . ', refresh_filled_if_changed=' . ($refreshFilledIfChanged ? '1' : '0') .
        ', search_queries=' . ($searchQueriesEnabled ? '1' : '0') . "\n"
    );
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    $offersSeen = 0;
    $groups = [];
    ops_update_progress($opId, 0, 100, 'scan', 'Grouping DB products by marketplace categories');

    foreach ($products as $product) {
        $offersSeen++;
        $productId = (int)($product['id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $ozonCat = trim((string)($product['ozon_category'] ?? ''));
        if ($ozonCat === '') {
            $ozonCat = supplier_products_db_product_tag_value($fields, ['ozon_category']);
        }
        $wbCategory = trim((string)($product['wb_category'] ?? ''));
        if ($wbCategory === '') {
            $wbCategory = supplier_products_db_product_tag_value($fields, ['wb_category', 'wb_subject_id']);
        }
        if ($ozonCat === '' && $wbCategory === '') {
            continue;
        }

        $paramsArr = [];
        foreach ($fields as $field) {
            $kind = (string)($field['field_kind'] ?? '');
            if ($kind !== 'param' && $kind !== 'wb_param') {
                continue;
            }
            $name = trim((string)($field['field_name'] ?? ''));
            $value = acp_trunc((string)($field['field_value'] ?? ''), 180);
            if ($name === '' || $value === '') {
                continue;
            }
            $paramsArr[] = [
                'name' => $kind === 'wb_param' ? ('WB: ' . $name) : $name,
                'value' => $value,
            ];
        }

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $descTxt = supplier_products_db_plain_text((string)($product['description_html'] ?? ''));
        $descLen = $descTxt !== '' ? mb_strlen($descTxt, 'UTF-8') : 0;
        $score = (count($paramsArr) * 5) + ($descLen > 40 ? 30 : 0) + (int)min(50, ($descLen / 40));

        $productPayload = [
            '_score' => $score,
            'offer_id' => (string)($product['offer_id'] ?? ''),
            'name' => acp_trunc((string)($product['name'] ?? ''), 180),
            'vendorCode' => acp_trunc((string)($product['vendor_code'] ?? ''), 80),
            'brand' => acp_trunc((string)($context['brand'] ?? ($product['brand'] ?? '')), 80),
            'vendor' => acp_trunc((string)($context['vendor'] ?? ''), 80),
            'model' => acp_trunc((string)($context['model'] ?? ''), 80),
            'params' => array_slice($paramsArr, 0, 25),
            'description_snippet' => $descMax > 0 ? acp_trunc($descTxt, $descMax) : '',
        ];

        $targets = [];
        if ($ozonCat !== '') {
            $targets[] = ['source' => 'ozon', 'code' => $ozonCat];
        }
        if ($wbCategory !== '') {
            $targets[] = ['source' => 'wildberries', 'code' => $wbCategory];
        }

        foreach ($targets as $target) {
            $groupKey = $target['source'] . ':' . $target['code'];
            if (!isset($groups[$groupKey])) {
                $groups[$groupKey] = [
                    'source' => $target['source'],
                    'code' => $target['code'],
                    'total' => 0,
                    'products' => [],
                    'offer_ids' => [],
                    '_offer_id_set' => [],
                ];
            }
            $groups[$groupKey]['total']++;
            $searchOfferId = trim((string)($productPayload['offer_id'] ?? ''));
            if ($searchOfferId !== '' && count($groups[$groupKey]['offer_ids']) < $searchQueryOfferLimit && empty($groups[$groupKey]['_offer_id_set'][$searchOfferId])) {
                $groups[$groupKey]['offer_ids'][] = $searchOfferId;
                $groups[$groupKey]['_offer_id_set'][$searchOfferId] = true;
            }

            $bucket = &$groups[$groupKey]['products'];
            if (count($bucket) < $maxPerCat) {
                $bucket[] = $productPayload;
            } else {
                $minIdx = 0;
                $minScore = (int)($bucket[0]['_score'] ?? -999999);
                for ($i = 1; $i < $maxPerCat; $i++) {
                    $candidateScore = (int)($bucket[$i]['_score'] ?? -999999);
                    if ($candidateScore < $minScore) {
                        $minScore = $candidateScore;
                        $minIdx = $i;
                    }
                }
                if ($score > $minScore) {
                    $bucket[$minIdx] = $productPayload;
                }
            }
            unset($bucket);
        }

        if (($offersSeen % 500) === 0) {
            ops_update_progress($opId, 5, 100, 'scan', "Scanned DB products: {$offersSeen}");
        }
    }

    foreach ($groups as &$group) {
        usort($group['products'], static fn($a, $b): int => (int)($b['_score'] ?? 0) <=> (int)($a['_score'] ?? 0));
        $group['products'] = array_slice($group['products'], 0, $maxPerCat);
        foreach ($group['products'] as &$productPayload) {
            unset($productPayload['_score']);
        }
        unset($productPayload);
        unset($group['_offer_id_set']);
    }
    unset($group);

    uasort($groups, static fn($a, $b): int => (int)($b['total'] ?? 0) <=> (int)($a['total'] ?? 0));
    $groupKeys = array_keys($groups);
    if ($maxCats > 0) {
        $groupKeys = array_slice($groupKeys, 0, $maxCats);
    }
    $totalCats = count($groupKeys);

    $gptJsonlAbs = $outDir . '/gpt_results.jsonl';
    $rawJsonlAbs = $outDir . '/gpt_raw.jsonl';
    $templateJsonlAbs = $outDir . '/category_background_templates.jsonl';
    $searchQueriesJsonlAbs = $outDir . '/category_search_queries.jsonl';
    file_put_contents($gptJsonlAbs, '');
    file_put_contents($rawJsonlAbs, '');
    file_put_contents($templateJsonlAbs, '');
    file_put_contents($searchQueriesJsonlAbs, '');

    $report = [
        'summary' => [
            'storage' => 'supplier_products_db',
            'offers_seen' => $offersSeen,
            'categories_found_in_feed' => count($groups),
            'categories_planned' => $totalCats,
            'model' => $model,
            'max_products_per_category' => $maxPerCat,
            'overwrite' => 1,
            'key_search_queries' => [
                'enabled' => $searchQueriesEnabled ? 1 : 0,
                'sku_limit' => $searchQuerySkuLimit,
                'offer_id_limit' => $searchQueryOfferLimit,
            ],
        ],
        'categories' => [],
    ];

    if (!$groups) {
        $log("supplier_db analyze_category_products: no products with ozon_category or wb_category found\n");
        ops_update_progress($opId, 100, 100, 'done', 'No categories found');
        $report['summary']['usage'] = ['input_tokens' => 0, 'cached_input_tokens' => 0, 'output_tokens' => 0, 'cost_usd' => 0.0];
        $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
        $outputs['gpt_results_jsonl'] = rel_to_outputs($cfg, $gptJsonlAbs);
        $outputs['gpt_raw_jsonl'] = rel_to_outputs($cfg, $rawJsonlAbs);
        $outputs['category_background_templates_jsonl'] = rel_to_outputs($cfg, $templateJsonlAbs);
        $outputs['category_search_queries_jsonl'] = rel_to_outputs($cfg, $searchQueriesJsonlAbs);
        $outputs['summary_json_inline'] = [
            'title' => 'analyze_category_products',
            'items' => [
                'Products scanned: ' . $offersSeen,
                'Categories found: 0',
            ],
            'metrics' => $report['summary'],
        ];
        return $outputs;
    }

    $oz = null;
    try {
        $oz = acp_ozon_cfg($cfg);
    } catch (Throwable $e) {
        $log("WARN ozon cfg: " . $e->getMessage() . "\n");
    }

    $wb = null;
    try {
        $wb = new WildberriesClient(acp_wb_cfg($cfg));
    } catch (Throwable $e) {
        $log("WARN wb cfg: " . $e->getMessage() . "\n");
    }

    $globalOzonExcludeNames = taxonomy_get_global_exclude_attribute_names('ozon', $cfg);
    $globalWbExcludeNames = taxonomy_get_global_exclude_attribute_names('wildberries', $cfg);

    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $backgroundImageClient = null;
    $backgroundImageTotals = [
        'jobs' => 0,
        'generated' => 0,
        'cached' => 0,
        'skipped' => 0,
        'errors' => 0,
        'input_tokens' => 0,
        'cached_input_tokens' => 0,
        'output_tokens' => 0,
        'image_input_tokens' => 0,
        'image_output_tokens' => 0,
        'estimated_jobs' => 0,
        'cost' => 0.0,
    ];

    $prompt = null;
    $client = null;
    $done = 0;
    foreach ($groupKeys as $groupKey) {
        $done++;
        $group = $groups[$groupKey];
        $source = (string)($group['source'] ?? '');
        $code = (string)($group['code'] ?? '');
        ops_update_progress($opId, 5 + (int)(90 * ($done / max(1, $totalCats))), 100, 'gpt', "Category {$done}/{$totalCats}: {$source}:{$code}");

        $catRow = null;
        $descId = 0;
        $typeId = 0;

        if ($source === 'ozon') {
            $pair = acp_parse_category_code($code);
            if (!$pair) {
                $report['categories'][] = ['source' => $source, 'code' => $code, 'status' => 'skip', 'reason' => 'bad_code_format'];
                continue;
            }
            [$descId, $typeId] = $pair;
            $catRow = acp_load_taxonomy_category($descId, $typeId);
            if (!$catRow) {
                $report['categories'][] = ['source' => $source, 'code' => $code, 'status' => 'skip', 'reason' => 'taxonomy_leaf_not_found'];
                continue;
            }
        } elseif ($source === 'wildberries') {
            if (!ctype_digit($code)) {
                $report['categories'][] = ['source' => $source, 'code' => $code, 'status' => 'skip', 'reason' => 'bad_subject_id'];
                continue;
            }
            $catRow = acp_load_wb_taxonomy_category((int)$code);
            if (!$catRow) {
                $report['categories'][] = ['source' => $source, 'code' => $code, 'status' => 'skip', 'reason' => 'taxonomy_leaf_not_found'];
                continue;
            }
        } else {
            $report['categories'][] = ['source' => $source, 'code' => $code, 'status' => 'skip', 'reason' => 'unsupported_source'];
            continue;
        }

        $meta = [];
        if (!empty($catRow['meta_json'])) {
            $tmp = json_decode((string)$catRow['meta_json'], true);
            if (is_array($tmp)) {
                $meta = $tmp;
            }
        }
        $meta += ['description' => '', 'typical_goods' => '', 'features' => '', 'cover_design' => '', 'video_cover_design' => ''];

        if ($source === 'ozon' && is_array($oz)) {
            try {
                $descIdTry = (int)($meta['ozon_description_category_id'] ?? 0);
                $typeIdTry = (int)($meta['ozon_type_id'] ?? 0);

                $lines = [];
                $attrsMeta = [];
                $usedDescId = 0;
                $usedTypeId = 0;

                if ($descIdTry > 0 && $typeIdTry > 0) {
                    $tmp = acp_ozon_required_attr_data($oz, $descIdTry, $typeIdTry, $globalOzonExcludeNames);
                    $lines = $tmp['lines'];
                    $attrsMeta = $tmp['meta'];
                    $usedDescId = $descIdTry;
                    $usedTypeId = $typeIdTry;
                } else {
                    $attempts = [
                        ['desc' => $descId, 'type' => $typeId],
                        ['desc' => $typeId, 'type' => $descId],
                    ];
                    $errors = [];
                    foreach ($attempts as $attempt) {
                        try {
                            $tmp = acp_ozon_required_attr_data($oz, (int)$attempt['desc'], (int)$attempt['type'], $globalOzonExcludeNames);
                            if (count($tmp['lines']) > count($lines)) {
                                $lines = $tmp['lines'];
                                $attrsMeta = $tmp['meta'];
                                $usedDescId = (int)$attempt['desc'];
                                $usedTypeId = (int)$attempt['type'];
                            }
                        } catch (Throwable $e) {
                            $errors[] = $e->getMessage();
                        }
                    }
                    if (($usedDescId <= 0 || $usedTypeId <= 0) && $errors) {
                        $log("WARN attrs {$code}: " . implode(' | ', array_slice($errors, 0, 2)) . "\n");
                    }
                }

                if ($usedDescId > 0 && $usedTypeId > 0) {
                    $meta['ozon_description_category_id'] = $usedDescId;
                    $meta['ozon_type_id'] = $usedTypeId;
                }
                $meta['ozon_required_attributes'] = $lines;
                $meta['ozon_required_attributes_meta'] = $attrsMeta;
                $tnvedAllowedValues = acp_ozon_tnved_allowed_values_from_meta($attrsMeta);
                $meta['ozon_tnved_allowed_values'] = $tnvedAllowedValues;
                $meta['ozon_tnved_allowed_values_count'] = count($tnvedAllowedValues);
                $meta['ozon_tnved_allowed_values_updated_at'] = date('c');
                acp_save_category_meta((int)$catRow['id'], $meta);
            } catch (Throwable $e) {
                $log("WARN ozon attrs {$code}: " . $e->getMessage() . "\n");
            }
        }

        if ($source === 'wildberries' && $wb instanceof WildberriesClient) {
            try {
                $tmp = acp_wb_characteristics_data($wb, (int)$code, $globalWbExcludeNames);
                $meta['wb_required_attributes'] = $tmp['lines'];
                $meta['wb_characteristics_meta'] = $tmp['meta'];
                acp_save_category_meta((int)$catRow['id'], $meta);
            } catch (Throwable $e) {
                $log("WARN wb attrs {$code}: " . $e->getMessage() . "\n");
            }
        }

        $keySearchQueries = acp_collect_category_key_search_queries(
            $cfg,
            $ds,
            $params,
            $group,
            $catRow,
            $source,
            $code,
            $opId,
            $supplierId,
            $supplierCode
        );
        $meta = acp_apply_key_search_queries_to_meta($meta, $keySearchQueries, $searchQueryKeywordLinesLimit);
        acp_save_category_meta((int)$catRow['id'], $meta);
        file_put_contents($searchQueriesJsonlAbs, json_encode([
            'source' => $source,
            'code' => $code,
            'category_id' => (int)$catRow['id'],
            'supplier_id' => $supplierId,
            'result' => $keySearchQueries,
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
        if ((string)($keySearchQueries['status'] ?? '') === 'error') {
            $log("WARN key search queries {$code}: " . (string)($keySearchQueries['error'] ?? 'unknown error') . "\n");
        }

        $sampleIds = [];
        foreach ((array)($group['products'] ?? []) as $sampleProduct) {
            $sampleIds[] = (string)($sampleProduct['offer_id'] ?? '');
        }
        $sigPayload = [
            'source' => $source,
            'products_total' => (int)($group['total'] ?? 0),
            'sample_offer_ids' => $sampleIds,
            'max_products_per_category' => $maxPerCat,
            'storage' => 'supplier_products_db',
        ];
        $currentSig = sha1(json_encode($sigPayload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        $prevSig = (string)($meta['category_analysis']['signature'] ?? '');
        $missing = trim((string)$meta['description']) === ''
            || trim((string)$meta['typical_goods']) === ''
            || trim((string)$meta['features']) === ''
            || trim((string)$meta['cover_design']) === ''
            || trim((string)$meta['video_cover_design']) === '';
        $changed = ($prevSig === '' || $prevSig !== $currentSig);
        $shouldAnalyze = !$onlyMissing || $missing || ($refreshFilledIfChanged && $changed);
        if (!$shouldAnalyze) {
            $templateResult = ['status' => 'skipped', 'reason' => 'not_started', 'meta' => $meta];
            try {
                $templateResult = acp_generate_category_background_template(
                    $cfg,
                    $catRow,
                    $meta,
                    $source,
                    $code,
                    $opId,
                    $outDir,
                    $log,
                    $backgroundImageClient,
                    $backgroundImageTotals
                );
                $meta = is_array($templateResult['meta'] ?? null) ? $templateResult['meta'] : $meta;
                $templateStatus = (string)($templateResult['status'] ?? '');
                if ($templateStatus === 'generated') {
                    $backgroundImageTotals['generated']++;
                    acp_save_category_meta((int)$catRow['id'], $meta);
                    $log("category background template generated: {$source}:{$code}\n");
                } elseif ($templateStatus === 'cached') {
                    $backgroundImageTotals['cached']++;
                } elseif ($templateStatus === 'skipped') {
                    $backgroundImageTotals['skipped']++;
                }
            } catch (Throwable $e) {
                $backgroundImageTotals['errors']++;
                $templateResult = ['status' => 'error', 'error' => $e->getMessage(), 'meta' => $meta];
                $log("WARN category background template {$code}: " . $e->getMessage() . "\n");
            }
            file_put_contents($templateJsonlAbs, json_encode([
                'source' => $source,
                'code' => $code,
                'category_id' => (int)$catRow['id'],
                'result' => acp_background_template_report($templateResult),
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);

            $report['categories'][] = [
                'source' => $source,
                'code' => $code,
                'status' => 'skipped_cached',
                'category_id' => (int)$catRow['id'],
                'products_total' => (int)($group['total'] ?? 0),
                'products_sample_count' => count($group['products'] ?? []),
                'was_missing' => 0,
                'was_changed' => 0,
            ] + acp_key_search_queries_report($keySearchQueries) + acp_background_template_report($templateResult);
            continue;
        }
        if ($client === null || $prompt === null) {
            $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'category_analyze.txt');
            $client = LLM::client($cfg, $model);
        }

        $input = [
            'category' => [
                'source' => $source,
                'code' => $code,
                'name' => (string)($catRow['name'] ?? ''),
                'full_path' => (string)($catRow['full_path'] ?? ''),
            ],
            'category_current' => [
                'description' => (string)($meta['description'] ?? ''),
                'typical_goods' => (string)($meta['typical_goods'] ?? ''),
                'features' => (string)($meta['features'] ?? ''),
                'cover_design' => (string)($meta['cover_design'] ?? ''),
                'video_cover_design' => (string)($meta['video_cover_design'] ?? ''),
            ],
            'products_total' => (int)($group['total'] ?? 0),
            'products_sample' => $group['products'] ?? [],
            'sampling_note' => "products_sample is a subset (up to {$maxPerCat} most informative DB products selected by params count and description length).",
        ];

        $inputJson = json_encode($input, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($inputJson === false) {
            $inputJson = '{"category":{}}';
        }

        try {
            $res = $client->generateText($model, "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $inputJson, $prompt, [
                'prompt_cache_key' => 'an_cat:' . substr(hash('sha256', json_encode([
                    'category' => $input['category'] ?? [],
                    'category_current' => $input['category_current'] ?? [],
                ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                'text' => ['format' => ['type' => 'json_object']],
            ]);

            $rawText = trim((string)($res['output_text'] ?? ''));
            $raw = $res['raw'] ?? null;
            $usage = acp_extract_usage($raw);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += acp_calc_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);

            $decoded = json_decode($rawText, true);
            if (!is_array($decoded)) {
                $i = strpos($rawText, '{');
                $j = strrpos($rawText, '}');
                if ($i !== false && $j !== false && $j > $i) {
                    $decoded = json_decode(substr($rawText, $i, $j - $i + 1), true);
                }
            }
            if (!is_array($decoded)) {
                throw new RuntimeException('GPT output is not valid JSON. Preview: ' . mb_substr($rawText, 0, 200, 'UTF-8'));
            }

            $desc = trim((string)($decoded['description'] ?? ''));
            $typical = trim((string)($decoded['typical_goods'] ?? ''));
            $features = trim((string)($decoded['features'] ?? ''));
            $coverDesign = trim((string)($decoded['cover_design'] ?? ''));
            $videoCoverDesign = trim((string)($decoded['video_cover_design'] ?? ''));
            if ($desc === '' || $typical === '' || $features === '' || $coverDesign === '' || $videoCoverDesign === '') {
                throw new RuntimeException('GPT JSON missing required keys (description/typical_goods/features/cover_design/video_cover_design)');
            }

            $meta['description'] = $desc;
            $meta['typical_goods'] = $typical;
            $meta['features'] = $features;
            $meta['cover_design'] = $coverDesign;
            $meta['video_cover_design'] = $videoCoverDesign;
            $meta['category_analysis'] = $meta['category_analysis'] ?? [];
            $meta['category_analysis']['source'] = $source;
            $meta['category_analysis']['storage'] = 'supplier_products_db';
            $meta['category_analysis']['updated_by_op_id'] = $opId;
            $meta['category_analysis']['updated_at'] = date('c');
            $meta['category_analysis']['products_total'] = (int)($group['total'] ?? 0);
            $meta['category_analysis']['products_sample_count'] = count($group['products'] ?? []);
            $meta['category_analysis']['model'] = $model;
            $meta['category_analysis']['dataset_id'] = $datasetId;
            $meta['category_analysis']['supplier_id'] = $supplierId;
            $meta['category_analysis']['signature'] = $currentSig;
            $templateResult = ['status' => 'skipped', 'reason' => 'not_started', 'meta' => $meta];
            try {
                $templateResult = acp_generate_category_background_template(
                    $cfg,
                    $catRow,
                    $meta,
                    $source,
                    $code,
                    $opId,
                    $outDir,
                    $log,
                    $backgroundImageClient,
                    $backgroundImageTotals
                );
                $meta = is_array($templateResult['meta'] ?? null) ? $templateResult['meta'] : $meta;
                $templateStatus = (string)($templateResult['status'] ?? '');
                if ($templateStatus === 'generated') {
                    $backgroundImageTotals['generated']++;
                    $log("category background template generated: {$source}:{$code}\n");
                } elseif ($templateStatus === 'cached') {
                    $backgroundImageTotals['cached']++;
                } elseif ($templateStatus === 'skipped') {
                    $backgroundImageTotals['skipped']++;
                }
            } catch (Throwable $e) {
                $backgroundImageTotals['errors']++;
                $templateResult = ['status' => 'error', 'error' => $e->getMessage(), 'meta' => $meta];
                $log("WARN category background template {$code}: " . $e->getMessage() . "\n");
            }
            acp_save_category_meta((int)$catRow['id'], $meta);
            file_put_contents($templateJsonlAbs, json_encode([
                'source' => $source,
                'code' => $code,
                'category_id' => (int)$catRow['id'],
                'result' => acp_background_template_report($templateResult),
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);

            file_put_contents($gptJsonlAbs, json_encode([
                'source' => $source,
                'code' => $code,
                'category_id' => (int)$catRow['id'],
                'ok' => 1,
                'output' => ['description' => $desc, 'typical_goods' => $typical, 'features' => $features, 'cover_design' => $coverDesign, 'video_cover_design' => $videoCoverDesign],
                'usage' => $usage,
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
            file_put_contents($rawJsonlAbs, json_encode([
                'source' => $source,
                'code' => $code,
                'category_id' => (int)$catRow['id'],
                'raw' => $raw,
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);

            $report['categories'][] = [
                'source' => $source,
                'code' => $code,
                'status' => 'ok',
                'category_id' => (int)$catRow['id'],
                'products_total' => (int)($group['total'] ?? 0),
                'products_sample_count' => count($group['products'] ?? []),
                'was_missing' => $missing ? 1 : 0,
                'was_changed' => $changed ? 1 : 0,
            ] + acp_key_search_queries_report($keySearchQueries) + acp_background_template_report($templateResult);
        } catch (Throwable $e) {
            $report['categories'][] = [
                'source' => $source,
                'code' => $code,
                'status' => 'error',
                'category_id' => (int)($catRow['id'] ?? 0),
                'error' => $e->getMessage(),
            ] + acp_key_search_queries_report($keySearchQueries ?? []);
            $log("ERROR category {$code}: " . $e->getMessage() . "\n");
        }
    }

    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $backgroundCostTotal = round((float)($backgroundImageTotals['cost'] ?? 0.0), 6);
    $backgroundCostLabel = acp_template_cost_label($cfg, $backgroundCostTotal);
    $log("TOTAL usage: input={$tokensInTotal}, cached_input={$tokensCachedTotal}, output={$tokensOutTotal}\n");
    $log("TOTAL cost ({$model}): {$costLabel}\n");
    $log(
        "BACKGROUND templates: generated={$backgroundImageTotals['generated']}, cached={$backgroundImageTotals['cached']}, " .
        "skipped={$backgroundImageTotals['skipped']}, errors={$backgroundImageTotals['errors']}, cost={$backgroundCostLabel}\n"
    );

    $report['summary']['usage'] = [
        'input_tokens' => $tokensInTotal,
        'cached_input_tokens' => $tokensCachedTotal,
        'output_tokens' => $tokensOutTotal,
    ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal);
    $report['summary']['background_templates'] = [
        'model' => 'gpt-image-2',
        'quality' => 'medium',
        'size' => '1024x1536',
        'generated' => (int)$backgroundImageTotals['generated'],
        'cached' => (int)$backgroundImageTotals['cached'],
        'skipped' => (int)$backgroundImageTotals['skipped'],
        'errors' => (int)$backgroundImageTotals['errors'],
        'jobs' => (int)$backgroundImageTotals['jobs'],
        'estimated_jobs' => (int)$backgroundImageTotals['estimated_jobs'],
        'input_tokens' => (int)$backgroundImageTotals['input_tokens'],
        'cached_input_tokens' => (int)$backgroundImageTotals['cached_input_tokens'],
        'output_tokens' => (int)$backgroundImageTotals['output_tokens'],
        'image_input_tokens' => (int)$backgroundImageTotals['image_input_tokens'],
        'image_output_tokens' => (int)$backgroundImageTotals['image_output_tokens'],
        'cost_usd' => $backgroundCostTotal,
        'cost_label' => $backgroundCostLabel,
    ];
    ops_update_progress($opId, 100, 100, 'done', 'Done');

    $reportAbs = $outDir . '/report.json';
    file_put_contents($reportAbs, json_encode($report, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT));

    return [
        'report_json' => rel_to_outputs($cfg, $reportAbs),
        'gpt_results_jsonl' => rel_to_outputs($cfg, $gptJsonlAbs),
        'gpt_raw_jsonl' => rel_to_outputs($cfg, $rawJsonlAbs),
        'category_background_templates_jsonl' => rel_to_outputs($cfg, $templateJsonlAbs),
        'category_search_queries_jsonl' => rel_to_outputs($cfg, $searchQueriesJsonlAbs),
        'summary_json_inline' => [
            'title' => 'analyze_category_products',
            'items' => [
                'Products scanned: ' . $offersSeen,
                'Categories found: ' . count($groups),
                'Categories processed: ' . $totalCats,
                'Tokens in: ' . $tokensInTotal,
                'Tokens cached in: ' . $tokensCachedTotal,
                'Tokens out: ' . $tokensOutTotal,
                'Cost: ' . $costLabel,
                'Background templates generated: ' . (int)$backgroundImageTotals['generated'],
                'Background templates cost: ' . $backgroundCostLabel,
            ],
            'metrics' => $report['summary'],
        ],
    ];
}

function supplier_products_db_mcat_norm($value): string
{
    $value = (string)$value;
    $value = html_entity_decode($value, ENT_QUOTES | ENT_XML1, 'UTF-8');
    $value = str_replace(["\xC2\xA0", "\xE2\x80\x8B"], ' ', $value);
    $value = mb_strtolower($value, 'UTF-8');
    $value = str_replace('ё', 'е', $value);
    $value = preg_replace('~[^\p{L}\p{N}]+~u', ' ', $value);
    $value = preg_replace('~\s+~u', ' ', (string)$value);
    return trim((string)$value);
}

function supplier_products_db_mcat_token_stem(string $token): string
{
    static $suffixes = [
        'иями', 'ями', 'ами', 'ями', 'ого', 'его', 'ому', 'ему', 'ыми', 'ими',
        'ией', 'иям', 'ием', 'иях', 'ьям', 'ьев', 'ого', 'его', 'ами',
        'ова', 'ева', 'ыми', 'ими', 'ных', 'ний', 'ный', 'ная', 'ное', 'ные',
        'ого', 'ему', 'ую', 'юю', 'ая', 'яя', 'ое', 'ее', 'ые', 'ие',
        'ов', 'ев', 'ей', 'ам', 'ям', 'ом', 'ем', 'ах', 'ях', 'ию', 'ия',
        'ий', 'ый', 'ой', 'ое', 'ее', 'ые', 'ие', 'а', 'я', 'ы', 'и', 'е', 'о', 'у', 'ю',
    ];
    $token = trim($token);
    if ($token === '' || preg_match('~^\d+$~u', $token)) {
        return $token;
    }
    $len = mb_strlen($token, 'UTF-8');
    if ($len < 5) {
        return $token;
    }
    foreach ($suffixes as $suffix) {
        $suffixLen = mb_strlen($suffix, 'UTF-8');
        if ($suffixLen <= 0 || $suffixLen >= $len - 3) {
            continue;
        }
        if (str_ends_with($token, $suffix)) {
            $stem = mb_substr($token, 0, $len - $suffixLen, 'UTF-8');
            if (mb_strlen($stem, 'UTF-8') >= 4) {
                return $stem;
            }
        }
    }
    return $token;
}

function supplier_products_db_mcat_tokens($value): array
{
    static $stop = null;
    if ($stop === null) {
        $stop = array_fill_keys([
            'для', 'или', 'что', 'это', 'как', 'при', 'под', 'над', 'без', 'через', 'после', 'перед',
            'товар', 'товара', 'товары', 'изделие', 'изделия', 'набор', 'комплект', 'штук', 'шт',
            'серия', 'серии', 'новый', 'новая', 'новое', 'универсальный', 'универсальная',
            'with', 'for', 'and', 'the', 'from', 'set', 'pcs', 'piece', 'pieces', 'new',
        ], true);
    }

    $norm = supplier_products_db_mcat_norm($value);
    if ($norm === '') {
        return [];
    }

    $out = [];
    foreach (preg_split('~\s+~u', $norm) ?: [] as $token) {
        $token = trim((string)$token);
        if ($token === '' || mb_strlen($token, 'UTF-8') < 2 || isset($stop[$token])) {
            continue;
        }
        $out[$token] = true;
        $stem = supplier_products_db_mcat_token_stem($token);
        if ($stem !== $token && !isset($stop[$stem])) {
            $out[$stem] = true;
        }
    }

    $aliases = [
        'телефон' => ['смартфон', 'iphone', 'android', 'mobile'],
        'телефонов' => ['смартфон', 'iphone', 'android', 'mobile'],
        'смартфон' => ['телефон', 'iphone', 'android'],
        'смартфонов' => ['телефон', 'iphone', 'android'],
        'айфон' => ['iphone', 'смартфон', 'телефон'],
        'iphone' => ['айфон', 'смартфон', 'телефон'],
        'дрон' => ['квадрокоптер', 'коптер', 'fpv'],
        'дроны' => ['квадрокоптер', 'коптер', 'fpv'],
        'квадрокоптер' => ['дрон', 'коптер', 'fpv'],
        'квадрокоптеров' => ['дрон', 'коптер', 'fpv'],
        'аккумулятор' => ['батарея', 'battery', 'lipo', 'liion', 'li'],
        'аккумуляторы' => ['батарея', 'battery', 'lipo', 'liion', 'li'],
        'батарея' => ['аккумулятор', 'battery'],
        'запчасти' => ['запчасть', 'ремонт', 'parts'],
        'запчасть' => ['запчасти', 'ремонт', 'parts'],
        'ремонт' => ['запчасти', 'инструмент'],
        'деталь' => ['запчасть', 'parts'],
        'детали' => ['запчасть', 'parts'],
        'комплектующие' => ['запчасти', 'детали', 'parts'],
        'экран' => ['дисплей', 'тачскрин', 'display'],
        'экраны' => ['дисплей', 'тачскрин', 'display'],
        'дисплей' => ['экран', 'тачскрин', 'display'],
        'дисплеи' => ['экран', 'тачскрин', 'display'],
        'тачскрин' => ['дисплей', 'экран', 'touchscreen'],
        'рамка' => ['корпус', 'дисплей', 'экран'],
        'стекло' => ['защитное', 'пленка', 'экран'],
        'пленка' => ['защитное', 'стекло', 'экран'],
        'чехол' => ['защита', 'аксессуар'],
        'зарядка' => ['зарядное', 'адаптер', 'питание'],
        'зарядное' => ['зарядка', 'адаптер', 'питание'],
        'адаптер' => ['переходник', 'питание'],
        'кабель' => ['провод', 'шнур', 'cord', 'cable'],
        'провод' => ['кабель', 'шнур', 'wire'],
        'разъем' => ['коннектор', 'connector'],
        'пульт' => ['управление', 'радиоуправление'],
        'сервопривод' => ['серво', 'servo'],
        'серво' => ['сервопривод', 'servo'],
        'регулятор' => ['esc', 'оборотов'],
        'машинка' => ['модель', 'радиоуправляемая', 'rc'],
        'модели' => ['модель', 'радиоуправляемые', 'rc'],
        'радиоуправляемые' => ['rc', 'модели'],
        'радиоуправляемая' => ['rc', 'модель'],
    ];
    foreach (array_keys($out) as $token) {
        $token = (string)$token;
        foreach ($aliases[$token] ?? [] as $alias) {
            $out[$alias] = true;
            $stem = supplier_products_db_mcat_token_stem($alias);
            if ($stem !== $alias && !isset($stop[$stem])) {
                $out[$stem] = true;
            }
        }
    }

    return array_values(array_map('strval', array_keys($out)));
}

function supplier_products_db_mcat_token_weights(string $value, float $weight): array
{
    $out = [];
    foreach (supplier_products_db_mcat_tokens($value) as $token) {
        $out[$token] = ($out[$token] ?? 0.0) + $weight;
    }
    return $out;
}

function supplier_products_db_mcat_leaf_catalog(string $source): array
{
    static $cache = [];
    $source = $source === 'wb' ? 'wildberries' : $source;
    if (isset($cache[$source])) {
        return $cache[$source];
    }

    $sql = "
        SELECT id, source, name, full_path, external_id, parent_external_id, level, is_leaf,
               ozon_parent_id, ozon_leaf_id, meta_json
        FROM feedtools_taxonomy_categories
        WHERE source = ?
          AND is_leaf = 1
    ";
    if ($source === 'ozon') {
        $sql .= " AND ozon_parent_id > 0 AND ozon_leaf_id > 0";
    } else {
        $sql .= " AND external_id LIKE 'wb:subject:%'";
    }
    $sql .= " ORDER BY full_path ASC";

    $stmt = db()->prepare($sql);
    $stmt->execute([$source]);

    $rows = [];
    while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
        $value = ft_taxonomy_picker_leaf_value($source, $row);
        if ($value === '' || ($source === 'ozon' && $value === '_')) {
            continue;
        }

        $meta = [];
        if (!empty($row['meta_json'])) {
            $tmp = json_decode((string)$row['meta_json'], true);
            if (is_array($tmp)) {
                $meta = $tmp;
            }
        }
        $desc = trim((string)($meta['description'] ?? ''));
        $typical = trim((string)($meta['typical_goods'] ?? ''));
        $features = trim((string)($meta['features'] ?? ''));
        $keywords = '';
        if (function_exists('ft_taxonomy_meta_keywords')) {
            $kw = ft_taxonomy_meta_keywords($meta);
            $keywords = is_array($kw) ? implode(' ', array_map('strval', $kw)) : (string)$kw;
        } elseif (!empty($meta['keywords']) && is_array($meta['keywords'])) {
            $keywords = implode(' ', array_map('strval', $meta['keywords']));
        }
        $categoryAttributes = [];
        if (function_exists('supplier_products_characteristic_rows_from_taxonomy_meta')) {
            try {
                $attrRows = supplier_products_characteristic_rows_from_taxonomy_meta($meta, $source, is_array($GLOBALS['cfg'] ?? null) ? $GLOBALS['cfg'] : []);
                foreach ($attrRows as $attrRow) {
                    if (!is_array($attrRow)) {
                        continue;
                    }
                    $attrName = trim((string)($attrRow['name'] ?? ''));
                    if ($attrName === '') {
                        continue;
                    }
                    $categoryAttributes[] = $attrName . (!empty($attrRow['required']) ? ' *' : '');
                    if (count($categoryAttributes) >= 10) {
                        break;
                    }
                }
            } catch (Throwable) {
                $categoryAttributes = [];
            }
        }
        $categoryAttributesText = implode(', ', $categoryAttributes);

        $weights = [];
        foreach ([
            [(string)($row['name'] ?? ''), 5.0],
            [(string)($row['full_path'] ?? ''), 3.0],
            [$desc . ' ' . $typical . ' ' . $features . ' ' . $keywords, 1.2],
            [$categoryAttributesText, 0.9],
        ] as [$text, $weight]) {
            foreach (supplier_products_db_mcat_token_weights((string)$text, (float)$weight) as $token => $score) {
                $weights[$token] = ($weights[$token] ?? 0.0) + $score;
            }
        }

        $rows[$value] = [
            'value' => $value,
            'name' => (string)($row['name'] ?? ''),
            'full_path' => (string)($row['full_path'] ?? ''),
            'description' => acp_trunc($desc, 240),
            'typical_goods' => acp_trunc($typical, 240),
            'features' => acp_trunc($features, 240),
            'keywords' => acp_trunc($keywords, 240),
            'category_attributes' => acp_trunc($categoryAttributesText, 240),
            '_norm_path' => supplier_products_db_mcat_norm((string)($row['full_path'] ?? '')),
            '_weights' => $weights,
        ];
    }

    $cache[$source] = $rows;
    return $rows;
}

function supplier_products_db_mcat_group_key(array $product): string
{
    $categoryId = trim((string)($product['category_id'] ?? ''));
    $categoryPath = trim((string)($product['category_path'] ?? ''));
    if ($categoryId !== '' || $categoryPath !== '') {
        return ($categoryId !== '' ? $categoryId : 'path') . "\n" . $categoryPath;
    }
    return 'product' . "\n" . (string)($product['id'] ?? '');
}

function supplier_products_db_mcat_product_payload(array $product, array $fields): array
{
    $context = supplier_products_db_product_prompt_context_from_fields($fields);
    $params = [];
    foreach (supplier_products_db_product_params_payload($fields) as $param) {
        $name = trim((string)($param['name'] ?? ''));
        $value = trim((string)($param['value'] ?? ''));
        if ($name === '' || $value === '') {
            continue;
        }
        $params[] = [
            'name' => acp_trunc($name, 80),
            'value' => acp_trunc($value, 120),
        ];
        if (count($params) >= 14) {
            break;
        }
    }

    $desc = supplier_products_db_plain_text((string)($product['description_html'] ?? ''));
    return [
        'product_id' => (int)($product['id'] ?? 0),
        'offer_id' => (string)($product['offer_id'] ?? ''),
        'name' => acp_trunc((string)($product['name'] ?? ''), 220),
        'vendor_code' => acp_trunc((string)($product['vendor_code'] ?? ''), 80),
        'brand' => acp_trunc((string)($context['brand'] ?? ($product['brand'] ?? '')), 80),
        'vendor' => acp_trunc((string)($context['vendor'] ?? ''), 80),
        'model' => acp_trunc((string)($context['model'] ?? ''), 80),
        'description_snippet' => acp_trunc($desc, 360),
        'params' => $params,
        'current_ozon_category' => supplier_products_db_product_category_value($product, $fields, 'ozon'),
        'current_wb_category' => supplier_products_db_product_category_value($product, $fields, 'wildberries'),
    ];
}

function supplier_products_db_mcat_build_groups(array $products, array $fieldsByProduct, bool $overwrite, int $maxSample): array
{
    $groups = [];
    foreach ($products as $product) {
        $productId = (int)($product['id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        $fields = $fieldsByProduct[$productId] ?? [];
        $payload = supplier_products_db_mcat_product_payload($product, $fields);
        $key = supplier_products_db_mcat_group_key($product);
        if (!isset($groups[$key])) {
            $groups[$key] = [
                'supplier_category_id' => trim((string)($product['category_id'] ?? '')),
                'supplier_category_path' => trim((string)($product['category_path'] ?? '')),
                'products_total' => 0,
                'product_ids' => [],
                'sample' => [],
                'missing_ozon' => 0,
                'missing_wb' => 0,
                'invalid_existing_ozon' => 0,
                'invalid_existing_wb' => 0,
                'existing_ozon' => [],
                'existing_wb' => [],
                '_text' => '',
                '_identity_text' => '',
            ];
        }

        $groups[$key]['products_total']++;
        $groups[$key]['product_ids'][] = $productId;
        $ozon = (string)($payload['current_ozon_category'] ?? '');
        $wb = (string)($payload['current_wb_category'] ?? '');
        $ozonInvalid = false;
        if (!$overwrite && $ozon !== '') {
            $guardedCurrent = supplier_products_db_mcat_guard_decision_against_product(
                ['category' => $ozon, 'confidence' => 1.0, 'reason' => 'current category check'],
                'ozon',
                $product,
                $fields
            );
            $ozonInvalid = !empty($guardedCurrent['guard_rejected_category']);
        }
        $wbInvalid = false;
        if (!$overwrite && $wb !== '') {
            $guardedCurrent = supplier_products_db_mcat_guard_decision_against_product(
                ['category' => $wb, 'confidence' => 1.0, 'reason' => 'current category check'],
                'wildberries',
                $product,
                $fields
            );
            $wbInvalid = !empty($guardedCurrent['guard_rejected_category']);
        }
        if ($overwrite || $ozon === '' || $ozonInvalid) {
            $groups[$key]['missing_ozon']++;
            if ($ozonInvalid) {
                $groups[$key]['invalid_existing_ozon']++;
            }
        } else {
            $groups[$key]['existing_ozon'][$ozon] = (int)($groups[$key]['existing_ozon'][$ozon] ?? 0) + 1;
        }
        if ($overwrite || $wb === '' || $wbInvalid) {
            $groups[$key]['missing_wb']++;
            if ($wbInvalid) {
                $groups[$key]['invalid_existing_wb']++;
            }
        } else {
            $groups[$key]['existing_wb'][$wb] = (int)($groups[$key]['existing_wb'][$wb] ?? 0) + 1;
        }

        $paramsText = '';
        foreach ((array)($payload['params'] ?? []) as $param) {
            $paramsText .= ' ' . (string)($param['name'] ?? '') . ' ' . (string)($param['value'] ?? '');
        }
        $productText = implode(' ', [
            (string)($payload['name'] ?? ''),
            (string)($payload['brand'] ?? ''),
            (string)($payload['vendor'] ?? ''),
            (string)($payload['model'] ?? ''),
            $paramsText,
            (string)($payload['description_snippet'] ?? ''),
        ]);
        $identityText = implode(' ', [
            (string)($payload['name'] ?? ''),
            (string)($payload['brand'] ?? ''),
            (string)($payload['vendor'] ?? ''),
            (string)($payload['model'] ?? ''),
            (string)($payload['description_snippet'] ?? ''),
        ]);
        if (mb_strlen((string)$groups[$key]['_text'], 'UTF-8') < 30000) {
            $groups[$key]['_text'] .= ' ' . acp_trunc($productText, 900);
        }
        if (mb_strlen((string)$groups[$key]['_identity_text'], 'UTF-8') < 30000) {
            $groups[$key]['_identity_text'] .= ' ' . acp_trunc($identityText, 900);
        }

        $score = count((array)($payload['params'] ?? [])) * 8
            + (mb_strlen((string)($payload['description_snippet'] ?? ''), 'UTF-8') > 60 ? 25 : 0)
            + mb_strlen((string)($payload['name'] ?? ''), 'UTF-8') / 8;
        $payload['_score'] = $score;
        $sample = &$groups[$key]['sample'];
        if (count($sample) < $maxSample) {
            $sample[] = $payload;
        } else {
            $minIdx = 0;
            $minScore = (float)($sample[0]['_score'] ?? 0);
            foreach ($sample as $idx => $row) {
                $rowScore = (float)($row['_score'] ?? 0);
                if ($rowScore < $minScore) {
                    $minScore = $rowScore;
                    $minIdx = (int)$idx;
                }
            }
            if ($score > $minScore) {
                $sample[$minIdx] = $payload;
            }
        }
        unset($sample);
    }

    foreach ($groups as &$group) {
        usort($group['sample'], static fn(array $a, array $b): int => (float)($b['_score'] ?? 0) <=> (float)($a['_score'] ?? 0));
        foreach ($group['sample'] as &$sampleProduct) {
            unset($sampleProduct['_score'], $sampleProduct['product_id']);
        }
        unset($sampleProduct);
        arsort($group['existing_ozon']);
        arsort($group['existing_wb']);
        $group['profile'] = supplier_products_db_mcat_group_semantic_profile($group);
    }
    unset($group);

    uasort($groups, static fn(array $a, array $b): int => (int)($b['products_total'] ?? 0) <=> (int)($a['products_total'] ?? 0));
    return $groups;
}

function supplier_products_db_mcat_profile_token_weights(array $group): array
{
    $supplierPath = (string)($group['supplier_category_path'] ?? '');
    $productText = trim((string)($group['_identity_text'] ?? ''));
    if ($productText === '') {
        $productText = (string)($group['_text'] ?? '');
    }
    $counts = [];
    foreach (supplier_products_db_mcat_tokens($productText) as $token) {
        $counts[$token] = ($counts[$token] ?? 0.0) + 1.0;
    }
    foreach (supplier_products_db_mcat_tokens($supplierPath) as $token) {
        $counts[$token] = ($counts[$token] ?? 0.0) + 2.0;
    }

    $pathParts = supplier_products_db_mcat_path_parts($supplierPath);
    $lastPart = $pathParts ? (string)end($pathParts) : '';
    foreach (supplier_products_db_mcat_tokens($lastPart) as $token) {
        $counts[$token] = ($counts[$token] ?? 0.0) + 3.0;
    }
    arsort($counts);
    return array_slice($counts, 0, 120, true);
}

function supplier_products_db_mcat_path_parts(string $path): array
{
    $path = str_replace([' / ', '/', '→', '›'], '>', $path);
    $parts = preg_split('~\s*(?:->|>)\s*~u', $path) ?: [];
    $out = [];
    foreach ($parts as $part) {
        $part = trim((string)$part);
        if ($part !== '') {
            $out[] = $part;
        }
    }
    return $out;
}

function supplier_products_db_mcat_profile_has_any(array $weights, array $terms): bool
{
    foreach ($terms as $term) {
        foreach (supplier_products_db_mcat_tokens((string)$term) as $token) {
            if (isset($weights[$token])) {
                return true;
            }
        }
    }
    return false;
}

function supplier_products_db_mcat_norm_has_any(string $norm, array $terms): bool
{
    if ($norm === '') {
        return false;
    }
    foreach ($terms as $term) {
        $termNorm = supplier_products_db_mcat_norm((string)$term);
        if ($termNorm !== '' && str_contains($norm, $termNorm)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_mcat_path_part_supported_by_product_text(string $productText, string $pathPart): bool
{
    $textTokens = array_fill_keys(supplier_products_db_mcat_tokens($productText), true);
    if (!$textTokens) {
        return false;
    }
    $generic = array_fill_keys([
        'товар', 'товары', 'запчасти', 'запчасть', 'деталь', 'детали', 'комплектующие',
        'аксессуар', 'аксессуары', 'часть', 'части', 'прочее', 'разное', 'для',
    ], true);
    foreach (supplier_products_db_mcat_tokens($pathPart) as $token) {
        if (isset($generic[$token])) {
            continue;
        }
        if (isset($textTokens[$token])) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_mcat_domain_flags_from_text(string $text): array
{
    $norm = supplier_products_db_mcat_norm($text);
    $flags = [];
    $checks = [
        'fpv_drone' => [
            'fpv', 'квадрокоптер', 'квадрокоптеров', 'дрон', 'дрона', 'коптер', 'elrs', 'lipo', 'lihv',
            'полетный контроллер', 'полетн контроллер', 'flight controller', 'aio', 'bec', 'esc', 'vtx',
            'видеопередатчик', 'видеоприемник', 'приемник', 'радиоприемник', 'антенна', '5 8 ггц',
            'radiomaster', 'matek', 'rushfpv', 'rush', 'geprc', 'iflight', 'tbs', 'caddx', 'foxeer',
            'speedybee', 'betafpv', 'hglrc', 'skystars', 'diatone', 'holybro', 'toolkitrc',
        ],
        'rc_controller' => [
            'пульт управления', 'аппаратура управления', 'радиоаппаратура', 'radiomaster', 'tx15',
            't8l', 'boxer', 'zorro', 'elrs', 'remote controller', 'radio controller',
        ],
        'fpv_goggles' => ['fpv очки', 'очки fpv', 'goggles', 'шлем fpv', 'очки'],
        'winch' => ['лебедка', 'лебедки', 'лебедок'],
        'phone' => ['смартфон', 'телефон', 'iphone', 'айфон', 'samsung', 'xiaomi', 'redmi', 'huawei'],
        'charging' => ['зарядное устройство', 'зарядка', 'charger', 'toolkitrc', 'isdt', 'hota', 'm6dac', 'up9'],
        'flight_controller' => ['полетный контроллер', 'полетн контроллер', 'flight controller', 'aio', 'f405', 'h743'],
        'video_tx' => ['видеопередатчик', 'vtx', '5 8 ггц'],
        'motor' => ['мотор', 'двигатель', 'kv', 'brushless'],
    ];
    foreach ($checks as $flag => $terms) {
        if (supplier_products_db_mcat_norm_has_any($norm, $terms)) {
            $flags[$flag] = true;
        }
    }
    return $flags;
}

function supplier_products_db_mcat_category_row(string $source, string $category): array
{
    $source = $source === 'wb' ? 'wildberries' : $source;
    $category = supplier_products_db_mcat_normalize_category_value($source, $category);
    $catalog = supplier_products_db_mcat_leaf_catalog($source);
    return is_array($catalog[$category] ?? null) ? (array)$catalog[$category] : [];
}

function supplier_products_db_mcat_guard_reject_decision(array $decision, string $category, string $reason): array
{
    $decision['guard_rejected_category'] = $category;
    $decision['category'] = '';
    $decision['confidence'] = 0.0;
    $decision['reason'] = acp_trunc($reason, 280);
    return $decision;
}

function supplier_products_db_mcat_guard_decision_against_group(array $decision, string $source, array $group): array
{
    $source = $source === 'wb' ? 'wildberries' : $source;
    $category = supplier_products_db_mcat_normalize_category_value($source, (string)($decision['category'] ?? ''));
    if ($category === '' || !supplier_products_db_mcat_category_is_valid($source, $category)) {
        return $decision;
    }

    $categoryRow = supplier_products_db_mcat_category_row($source, $category);
    $categoryText = trim((string)($categoryRow['full_path'] ?? '') . ' ' . (string)($categoryRow['name'] ?? ''));
    $categoryNorm = supplier_products_db_mcat_norm($categoryText);
    $productText = trim((string)($group['_identity_text'] ?? ''));
    if ($productText === '') {
        $productText = (string)($group['_text'] ?? '');
    }
    if ($productText === '') {
        foreach ((array)($group['sample'] ?? []) as $sample) {
            if (!is_array($sample)) {
                continue;
            }
            $productText .= ' ' . (string)($sample['name'] ?? '') . ' ' . (string)($sample['brand'] ?? '') . ' ' . (string)($sample['model'] ?? '');
        }
    }
    $productNorm = supplier_products_db_mcat_norm($productText);
    $flags = supplier_products_db_mcat_domain_flags_from_text($productText);

    if (!empty($flags['fpv_drone']) && empty($flags['winch']) && supplier_products_db_mcat_norm_has_any($categoryNorm, ['лебедка', 'лебедки', 'лебедок'])) {
        return supplier_products_db_mcat_guard_reject_decision(
            $decision,
            $category,
            'Семантическая проверка отклонила категорию: товар относится к FPV/дронам, а выбранная категория про лебедки.'
        );
    }

    $categoryLooksLikeGlasses = supplier_products_db_mcat_norm_has_any($categoryNorm, ['3d очки', 'очки', 'vr', 'виртуальная реальность']);
    if ($categoryLooksLikeGlasses && empty($flags['fpv_goggles'])) {
        if (!empty($flags['rc_controller']) || supplier_products_db_mcat_norm_has_any($productNorm, ['пульт', 'аппаратура', 'elrs', 'радиоаппаратура'])) {
            return supplier_products_db_mcat_guard_reject_decision(
                $decision,
                $category,
                'Семантическая проверка отклонила категорию: это пульт/аппаратура управления, а не 3D/VR-очки.'
            );
        }
    }

    if (!empty($flags['fpv_drone'])
        && supplier_products_db_mcat_norm_has_any($categoryNorm, ['смартфон', 'телефон', 'iphone', 'айфон'])
        && empty($flags['phone'])
    ) {
        return supplier_products_db_mcat_guard_reject_decision(
            $decision,
            $category,
            'Семантическая проверка отклонила категорию: товар относится к FPV/дронам, а выбранная категория про телефоны.'
        );
    }

    if (!empty($flags['charging'])
        && supplier_products_db_mcat_norm_has_any($categoryNorm, ['очки', 'лебедка', 'пульт управления'])
        && !supplier_products_db_mcat_norm_has_any($categoryNorm, ['зарядное', 'зарядка', 'аккумулятор', 'питание'])
    ) {
        return supplier_products_db_mcat_guard_reject_decision(
            $decision,
            $category,
            'Семантическая проверка отклонила категорию: это зарядное устройство, а выбранная категория относится к другому типу товара.'
        );
    }

    return $decision;
}

function supplier_products_db_mcat_guard_decision_against_product(array $decision, string $source, array $product, array $fields): array
{
    $payload = supplier_products_db_mcat_product_payload($product, $fields);
    $paramsText = '';
    foreach ((array)($payload['params'] ?? []) as $param) {
        $paramsText .= ' ' . (string)($param['name'] ?? '') . ' ' . (string)($param['value'] ?? '');
    }
    $text = implode(' ', [
        (string)($payload['name'] ?? ''),
        (string)($payload['brand'] ?? ''),
        (string)($payload['vendor'] ?? ''),
        (string)($payload['model'] ?? ''),
        $paramsText,
        (string)($payload['description_snippet'] ?? ''),
    ]);
    $identityText = implode(' ', [
        (string)($payload['name'] ?? ''),
        (string)($payload['brand'] ?? ''),
        (string)($payload['vendor'] ?? ''),
        (string)($payload['model'] ?? ''),
        (string)($payload['description_snippet'] ?? ''),
    ]);
    $group = [
        'supplier_category_id' => trim((string)($product['category_id'] ?? '')),
        'supplier_category_path' => trim((string)($product['category_path'] ?? '')),
        'products_total' => 1,
        'sample' => [$payload],
        '_text' => $text,
        '_identity_text' => $identityText,
    ];
    $group['profile'] = supplier_products_db_mcat_group_semantic_profile($group);
    return supplier_products_db_mcat_guard_decision_against_group($decision, $source, $group);
}

function supplier_products_db_mcat_group_semantic_profile(array $group): array
{
    $supplierPath = (string)($group['supplier_category_path'] ?? '');
    $pathParts = supplier_products_db_mcat_path_parts($supplierPath);
    $weights = supplier_products_db_mcat_profile_token_weights($group);
    $dominantTerms = [];
    foreach (array_slice($weights, 0, 30, true) as $token => $score) {
        $dominantTerms[] = [
            'term' => (string)$token,
            'weight' => round((float)$score, 2),
        ];
    }

    $flags = [];
    $checks = [
        'spare_part' => ['запчасть', 'запчасти', 'деталь', 'детали', 'комплектующие', 'ремонт', 'шлейф', 'модуль'],
        'accessory' => ['аксессуар', 'чехол', 'держатель', 'кабель', 'переходник', 'адаптер', 'насадка'],
        'protective' => ['защитный', 'защитное', 'защита', 'стекло', 'пленка', 'чехол', 'накладка'],
        'power' => ['аккумулятор', 'батарея', 'зарядка', 'зарядное', 'адаптер', 'блок', 'питание', 'lipo', 'liion'],
        'rc_model' => ['радиоуправляемый', 'радиоуправляемые', 'модель', 'модели', 'rc', 'fpv', 'квадрокоптер', 'дрон', 'сервопривод', 'регулятор'],
        'phone' => ['iphone', 'айфон', 'смартфон', 'телефон'],
        'cable_connector' => ['кабель', 'провод', 'шнур', 'разъем', 'коннектор'],
        'display_module' => ['дисплей', 'экран', 'тачскрин', 'рамка', 'матрица'],
    ];
    foreach ($checks as $flag => $terms) {
        if (supplier_products_db_mcat_profile_has_any($weights, $terms)) {
            $flags[$flag] = true;
        }
    }

    return [
        'supplier_path_parts' => $pathParts,
        'supplier_leaf' => $pathParts ? (string)end($pathParts) : '',
        'dominant_terms' => $dominantTerms,
        'role_flags' => $flags,
    ];
}

function supplier_products_db_mcat_string_list($value, int $limit = 12, int $maxLen = 80): array
{
    $out = [];
    foreach ((array)$value as $item) {
        $s = trim((string)$item);
        if ($s === '') {
            continue;
        }
        $out[$s] = acp_trunc($s, $maxLen);
        if (count($out) >= $limit) {
            break;
        }
    }
    return array_values($out);
}

function supplier_products_db_mcat_normalize_role_analysis(array $decoded): array
{
    $src = is_array($decoded['role_analysis'] ?? null) ? (array)$decoded['role_analysis'] : $decoded;
    return [
        'product_role' => acp_trunc(trim((string)($src['product_role'] ?? '')), 80),
        'target_objects' => supplier_products_db_mcat_string_list($src['target_objects'] ?? [], 8, 80),
        'include_category_terms' => supplier_products_db_mcat_string_list($src['include_category_terms'] ?? [], 12, 80),
        'exclude_category_terms' => supplier_products_db_mcat_string_list($src['exclude_category_terms'] ?? [], 12, 80),
        'is_mixed' => !empty($src['is_mixed']),
        'confidence' => max(0.0, min(1.0, (float)($src['confidence'] ?? 0))),
        'reason' => acp_trunc(trim((string)($src['reason'] ?? '')), 240),
    ];
}

function supplier_products_db_mcat_role_analysis_terms(array $analysis, array $keys): array
{
    $terms = [];
    foreach ($keys as $key) {
        $value = $analysis[$key] ?? null;
        if (is_array($value)) {
            foreach ($value as $item) {
                $item = trim((string)$item);
                if ($item !== '') {
                    $terms[$item] = true;
                }
            }
        } else {
            $value = trim((string)$value);
            if ($value !== '') {
                $terms[$value] = true;
            }
        }
    }
    $out = [];
    foreach (array_keys($terms) as $term) {
        $term = trim((string)$term);
        if ($term !== '') {
            $out[] = $term;
        }
    }
    return $out;
}

function supplier_products_db_mcat_candidate_role_analysis_boost(array $row, array $roleAnalysis): array
{
    if (!$roleAnalysis) {
        return [0.0, []];
    }

    $weights = (array)($row['_weights'] ?? []);
    $normPath = (string)($row['_norm_path'] ?? '');
    $boost = 0.0;
    $signals = [];

    foreach (supplier_products_db_mcat_role_analysis_terms($roleAnalysis, ['product_role', 'target_objects', 'include_category_terms']) as $term) {
        $term = (string)$term;
        $termBoost = 0.0;
        foreach (supplier_products_db_mcat_tokens($term) as $token) {
            if (isset($weights[$token])) {
                $termBoost += (float)$weights[$token];
            }
        }
        $termNorm = supplier_products_db_mcat_norm($term);
        if ($termNorm !== '' && mb_strlen($termNorm, 'UTF-8') >= 4 && str_contains($normPath, $termNorm)) {
            $termBoost += 6.0;
        }
        if ($termBoost > 0.0) {
            $boost += min(34.0, 9.0 + ($termBoost * 2.4));
            $signals['role_analysis_include'][] = acp_trunc((string)$term, 60);
        }
        if ($boost >= 170.0) {
            break;
        }
    }

    $penalty = 0.0;
    foreach (supplier_products_db_mcat_role_analysis_terms($roleAnalysis, ['exclude_category_terms']) as $term) {
        $term = (string)$term;
        $termNorm = supplier_products_db_mcat_norm($term);
        if ($termNorm !== '' && mb_strlen($termNorm, 'UTF-8') >= 5 && str_contains($normPath, $termNorm)) {
            $penalty += 55.0;
            $signals['role_analysis_exclude'][] = acp_trunc((string)$term, 60);
        }
        if ($penalty >= 140.0) {
            break;
        }
    }

    return [round($boost - $penalty, 2), $signals];
}

function supplier_products_db_mcat_category_has_any(array $categoryWeights, string $normPath, array $terms): bool
{
    foreach ($terms as $term) {
        foreach (supplier_products_db_mcat_tokens((string)$term) as $token) {
            if (isset($categoryWeights[$token])) {
                return true;
            }
        }
        $termNorm = supplier_products_db_mcat_norm((string)$term);
        if ($termNorm !== '' && str_contains($normPath, $termNorm)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_mcat_candidate_role_boost(array $row, array $profile): array
{
    $flags = (array)($profile['role_flags'] ?? []);
    if (!$flags) {
        return [0.0, []];
    }
    $weights = (array)($row['_weights'] ?? []);
    $normPath = (string)($row['_norm_path'] ?? '');
    $boost = 0.0;
    $signals = [];
    $checks = [
        'spare_part' => [42.0, ['запчасть', 'запчасти', 'деталь', 'комплектующие', 'ремонт', 'модуль']],
        'accessory' => [26.0, ['аксессуар', 'чехол', 'держатель', 'кабель', 'переходник', 'адаптер']],
        'protective' => [36.0, ['защитный', 'защитное', 'стекло', 'пленка', 'чехол', 'накладка']],
        'power' => [34.0, ['аккумулятор', 'батарея', 'зарядка', 'зарядное', 'адаптер', 'питание', 'lipo']],
        'rc_model' => [48.0, ['радиоуправляемый', 'радиоуправляемые', 'модель', 'модели', 'игрушка', 'квадрокоптер', 'дрон', 'fpv', 'rc']],
        'phone' => [32.0, ['смартфон', 'телефон', 'iphone', 'айфон', 'мобильный']],
        'cable_connector' => [34.0, ['кабель', 'провод', 'шнур', 'разъем', 'коннектор']],
        'display_module' => [38.0, ['дисплей', 'экран', 'тачскрин', 'матрица', 'модуль']],
    ];
    foreach ($checks as $flag => [$flagBoost, $terms]) {
        if (!empty($flags[$flag]) && supplier_products_db_mcat_category_has_any($weights, $normPath, $terms)) {
            $boost += (float)$flagBoost;
            $signals['profile_role'][] = $flag;
        }
    }
    return [$boost, $signals];
}

function supplier_products_db_mcat_candidate_domain_boost(array $row, array $group): array
{
    $productText = trim((string)($group['_identity_text'] ?? ''));
    if ($productText === '') {
        $productText = (string)($group['_text'] ?? '');
    }
    $flags = supplier_products_db_mcat_domain_flags_from_text($productText);
    if (!$flags) {
        return [0.0, []];
    }

    $categoryText = trim((string)($row['full_path'] ?? '') . ' ' . (string)($row['name'] ?? ''));
    $categoryNorm = supplier_products_db_mcat_norm($categoryText);
    $boost = 0.0;
    $signals = [];
    $categoryDrone = supplier_products_db_mcat_norm_has_any($categoryNorm, ['квадрокоптер', 'дрон', 'fpv', 'радиоуправляем', 'радиоуправляемые', 'авиамодель', 'модель']);
    $categoryPower = supplier_products_db_mcat_norm_has_any($categoryNorm, ['зарядное', 'зарядка', 'аккумулятор', 'питание', 'батарея']);
    $categoryGlasses = supplier_products_db_mcat_norm_has_any($categoryNorm, ['3d очки', 'очки', 'vr', 'виртуальная реальность']);
    $categoryWinch = supplier_products_db_mcat_norm_has_any($categoryNorm, ['лебедка', 'лебедки', 'лебедок']);
    $categoryPhone = supplier_products_db_mcat_norm_has_any($categoryNorm, ['смартфон', 'телефон', 'iphone', 'айфон']);
    $categoryGenericRemote = supplier_products_db_mcat_norm_has_any($categoryNorm, ['пульт', 'пульты'])
        && !$categoryDrone;

    if (!empty($flags['rc_controller'])) {
        if ($categoryDrone) {
            $boost += 180.0;
            $signals['domain_boost'][] = 'rc_controller_drone';
        }
        if ($categoryGenericRemote) {
            $boost -= 80.0;
            $signals['domain_penalty'][] = 'generic_remote_not_drone';
        }
    }
    if (!empty($flags['fpv_drone'])) {
        if ($categoryDrone) {
            $boost += 120.0;
            $signals['domain_boost'][] = 'fpv_drone';
        }
        if ($categoryWinch || ($categoryGlasses && empty($flags['fpv_goggles'])) || ($categoryPhone && empty($flags['phone']))) {
            $boost -= 220.0;
            $signals['domain_penalty'][] = 'fpv_conflict';
        }
    }
    if (!empty($flags['charging']) && $categoryPower) {
        $boost += 90.0;
        $signals['domain_boost'][] = 'charging_power';
    }
    if ((!empty($flags['flight_controller']) || !empty($flags['video_tx']) || !empty($flags['motor'])) && $categoryDrone) {
        $boost += 70.0;
        $signals['domain_boost'][] = 'fpv_part_role';
    }

    return [round($boost, 2), $signals];
}

function supplier_products_db_mcat_candidates(string $source, array $group, int $limit, array $memory = []): array
{
    $catalog = supplier_products_db_mcat_leaf_catalog($source);
    if (!$catalog) {
        return [];
    }

    $profile = supplier_products_db_mcat_profile_token_weights($group);
    $semanticProfile = is_array($group['profile'] ?? null)
        ? (array)$group['profile']
        : supplier_products_db_mcat_group_semantic_profile($group);
    $roleAnalysis = is_array($semanticProfile['llm_role_analysis'] ?? null) ? (array)$semanticProfile['llm_role_analysis'] : [];
    foreach (supplier_products_db_mcat_role_analysis_terms($roleAnalysis, ['product_role', 'target_objects', 'include_category_terms']) as $term) {
        foreach (supplier_products_db_mcat_tokens((string)$term) as $token) {
            $profile[$token] = ($profile[$token] ?? 0.0) + 7.5;
        }
    }
    $pathParts = supplier_products_db_mcat_path_parts((string)($group['supplier_category_path'] ?? ''));
    $productText = trim((string)($group['_identity_text'] ?? ''));
    if ($productText === '') {
        $productText = (string)($group['_text'] ?? '');
    }
    $pathTokens = [];
    foreach ($pathParts as $idx => $part) {
        $partWeight = 1.0 + ($idx === count($pathParts) - 1 ? 1.5 : 0.0);
        foreach (supplier_products_db_mcat_tokens($part) as $token) {
            $pathTokens[$token] = ($pathTokens[$token] ?? 0.0) + $partWeight;
        }
    }
    $scores = [];
    $signals = [];
    foreach ($catalog as $value => $row) {
        $score = 0.0;
        $signal = [];
        $weights = (array)($row['_weights'] ?? []);
        foreach ($profile as $token => $weight) {
            if (isset($weights[$token])) {
                $score += (float)$weight * (float)$weights[$token];
            }
        }
        $pathTokenScore = 0.0;
        foreach ($pathTokens as $token => $weight) {
            if (isset($weights[$token])) {
                $pathTokenScore += (float)$weight * (float)$weights[$token];
            }
        }
        if ($pathTokenScore > 0.0) {
            $score += $pathTokenScore;
            $signal['supplier_path_tokens'] = round($pathTokenScore, 2);
        }
        foreach ($pathParts as $part) {
            $partNorm = supplier_products_db_mcat_norm($part);
            if ($partNorm !== ''
                && mb_strlen($partNorm, 'UTF-8') >= 5
                && str_contains((string)($row['_norm_path'] ?? ''), $partNorm)
                && supplier_products_db_mcat_path_part_supported_by_product_text($productText, $part)
            ) {
                $boost = 26.0;
                $score += $boost;
                $signal['supplier_path_exact'][] = $part;
            }
        }
        [$roleBoost, $roleSignals] = supplier_products_db_mcat_candidate_role_boost($row, $semanticProfile);
        if ($roleBoost > 0.0) {
            $score += $roleBoost;
            foreach ($roleSignals as $sigKey => $sigValue) {
                $signal[$sigKey] = $sigValue;
            }
        }
        [$analysisBoost, $analysisSignals] = supplier_products_db_mcat_candidate_role_analysis_boost($row, $roleAnalysis);
        if ($analysisBoost !== 0.0) {
            $score += $analysisBoost;
            foreach ($analysisSignals as $sigKey => $sigValue) {
                $signal[$sigKey] = $sigValue;
            }
        }
        [$domainBoost, $domainSignals] = supplier_products_db_mcat_candidate_domain_boost($row, $group);
        if ($domainBoost !== 0.0) {
            $score += $domainBoost;
            foreach ($domainSignals as $sigKey => $sigValue) {
                $signal[$sigKey] = $sigValue;
            }
        }
        $scores[$value] = $score;
        if ($signal) {
            $signals[$value] = $signal;
        }
    }

    $existingKey = $source === 'ozon' ? 'existing_ozon' : 'existing_wb';
    foreach ((array)($group[$existingKey] ?? []) as $value => $count) {
        $value = (string)$value;
        if (isset($catalog[$value])) {
            $scores[$value] = ($scores[$value] ?? 0.0) + (80.0 + ((int)$count * 10.0));
            $signals[$value]['already_used_in_supplier_category'] = (int)$count;
        }
    }

    foreach ($memory as $row) {
        if (!is_array($row)) {
            continue;
        }
        $value = supplier_products_db_mcat_normalize_category_value($source, (string)($row['category'] ?? ''));
        if ($value === '' || !isset($catalog[$value])) {
            continue;
        }
        $count = max(1, (int)($row['count'] ?? 1));
        $ratio = max(0.0, min(1.0, (float)($row['ratio'] ?? 0)));
        $boost = min(420.0, 150.0 + ($count * 18.0) + ($ratio * 90.0));
        $scores[$value] = ($scores[$value] ?? 0.0) + $boost;
        $signals[$value]['supplier_category_memory'] = [
            'count' => $count,
            'ratio' => round($ratio, 3),
            'boost' => round($boost, 2),
        ];
    }

    arsort($scores);
    $out = [];
    $rank = 0;
    foreach ($scores as $value => $score) {
        if ($score <= 0.0 && count($out) >= 8) {
            break;
        }
        $row = $catalog[(string)$value] ?? null;
        if (!$row) {
            continue;
        }
        $rank++;
        $out[] = [
            'category' => (string)$value,
            'name' => (string)($row['name'] ?? ''),
            'full_path' => (string)($row['full_path'] ?? ''),
            'description' => (string)($row['description'] ?? ''),
            'typical_goods' => (string)($row['typical_goods'] ?? ''),
            'features' => (string)($row['features'] ?? ''),
            'keywords' => (string)($row['keywords'] ?? ''),
            'category_attributes' => (string)($row['category_attributes'] ?? ''),
            'local_score' => round((float)$score, 2),
            'local_rank' => $rank,
            'match_signals' => $signals[$value] ?? (object)[],
        ];
        if (count($out) >= $limit) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_mcat_normalize_category_value(string $source, string $category): string
{
    $category = trim($category);
    if ($source === 'wildberries' && preg_match('~^wb:subject:(\d+)$~', $category, $m)) {
        return (string)$m[1];
    }
    if ($source === 'wildberries' && preg_match('~^wb:parent:(\d+)$~', $category, $m)) {
        return (string)$m[1];
    }
    if ($source === 'ozon' && preg_match('~^leaf:(\d+_\d+)$~', $category, $m)) {
        return (string)$m[1];
    }
    return $category;
}

function supplier_products_db_mcat_category_is_valid(string $source, string $category): bool
{
    $category = supplier_products_db_mcat_normalize_category_value($source, $category);
    if ($category === '') {
        return false;
    }
    return isset(supplier_products_db_mcat_leaf_catalog($source)[$category]);
}

function supplier_products_db_mcat_supplier_category_filter_sql(array $group, string $alias = 'p'): array
{
    $categoryId = trim((string)($group['supplier_category_id'] ?? ''));
    $categoryPath = trim((string)($group['supplier_category_path'] ?? ''));
    $parts = [];
    $params = [];
    if ($categoryId !== '') {
        $parts[] = "{$alias}.category_id = ?";
        $params[] = $categoryId;
    }
    if ($categoryPath !== '') {
        $parts[] = "{$alias}.category_path = ?";
        $params[] = $categoryPath;
    }
    if (!$parts) {
        return ['', []];
    }
    return ['(' . implode(' OR ', $parts) . ')', $params];
}

function supplier_products_db_mcat_supplier_category_memory(int $supplierId, array $group, string $source): array
{
    static $cache = [];
    $source = $source === 'wildberries' ? 'wildberries' : 'ozon';
    $categoryId = trim((string)($group['supplier_category_id'] ?? ''));
    $categoryPath = trim((string)($group['supplier_category_path'] ?? ''));
    $cacheKey = $supplierId . '|' . $source . '|' . $categoryId . '|' . hash('sha1', $categoryPath);
    if (array_key_exists($cacheKey, $cache)) {
        return $cache[$cacheKey];
    }

    [$where, $whereParams] = supplier_products_db_mcat_supplier_category_filter_sql($group, 'p');
    if ($supplierId <= 0 || $where === '') {
        $cache[$cacheKey] = [];
        return [];
    }

    $column = $source === 'ozon' ? 'ozon_category' : 'wb_category';
    $fieldNames = $source === 'ozon' ? ['ozon_category'] : ['wb_category', 'wb_subject_id'];
    $counts = [];
    $addRows = static function (array $rows) use (&$counts, $source): void {
        foreach ($rows as $row) {
            $category = supplier_products_db_mcat_normalize_category_value($source, (string)($row['category'] ?? ''));
            $qty = (int)($row['qty'] ?? 0);
            if ($category === '' || $qty <= 0 || !supplier_products_db_mcat_category_is_valid($source, $category)) {
                continue;
            }
            $counts[$category] = (int)($counts[$category] ?? 0) + $qty;
        }
    };

    try {
        $pdo = db();
        $placeholders = implode(',', array_fill(0, count($fieldNames), '?'));
        $sql = "
            SELECT category, COUNT(DISTINCT product_id) AS qty
            FROM (
                SELECT p.id AS product_id, CAST(p.{$column} AS CHAR(191)) AS category
                FROM feedtools_supplier_products p
                WHERE p.supplier_id = ?
                  AND {$where}
                  AND COALESCE(p.{$column}, '') <> ''
                UNION
                SELECT f.product_id AS product_id, CAST(f.field_value AS CHAR(191)) AS category
                FROM feedtools_supplier_product_fields f
                INNER JOIN feedtools_supplier_products p ON p.id = f.product_id
                WHERE p.supplier_id = ?
                  AND {$where}
                  AND f.field_kind = 'tag'
                  AND f.field_name IN ({$placeholders})
                  AND f.field_value IS NOT NULL
                  AND TRIM(CAST(f.field_value AS CHAR)) <> ''
            ) memory_categories
            WHERE category IS NOT NULL
              AND TRIM(category) <> ''
            GROUP BY category
            ORDER BY qty DESC
            LIMIT 200
        ";
        $st = $pdo->prepare($sql);
        $st->execute(array_merge([$supplierId], $whereParams, [$supplierId], $whereParams, $fieldNames));
        $addRows($st->fetchAll(PDO::FETCH_ASSOC) ?: []);
    } catch (Throwable) {
        $cache[$cacheKey] = [];
        return [];
    }

    if (!$counts) {
        $cache[$cacheKey] = [];
        return [];
    }

    arsort($counts);
    $catalog = supplier_products_db_mcat_leaf_catalog($source);
    $total = max(1, array_sum(array_map('intval', $counts)));
    $out = [];
    foreach (array_slice($counts, 0, 12, true) as $category => $count) {
        $row = $catalog[(string)$category] ?? [];
        $out[] = [
            'category' => (string)$category,
            'count' => (int)$count,
            'ratio' => round((int)$count / $total, 3),
            'name' => (string)($row['name'] ?? ''),
            'full_path' => (string)($row['full_path'] ?? ''),
        ];
    }
    $cache[$cacheKey] = $out;
    return $out;
}

function supplier_products_db_mcat_memory_decision(array $memory, array $group, string $source): array
{
    $source = $source === 'wildberries' ? 'wildberries' : 'ozon';
    $top = $memory[0] ?? null;
    if (!is_array($top)) {
        return [
            'category' => '',
            'confidence' => 0.0,
            'reason' => '',
            'alternatives' => [],
            'source' => 'supplier_category_memory',
            'count' => 0,
            'total_existing' => 0,
        ];
    }

    $category = supplier_products_db_mcat_normalize_category_value($source, (string)($top['category'] ?? ''));
    $count = max(0, (int)($top['count'] ?? 0));
    $total = max(1, array_sum(array_map(static fn($row): int => is_array($row) ? (int)($row['count'] ?? 0) : 0, $memory)));
    $ratio = max(0.0, min(1.0, (float)($top['ratio'] ?? ($count / $total))));
    $productsTotal = max(1, (int)($group['products_total'] ?? 0));
    $confidence = 0.0;
    if (supplier_products_db_mcat_category_is_valid($source, $category)) {
        if ($count >= 8 && $ratio >= 0.68) {
            $confidence = min(0.99, 0.965 + min(0.02, ($ratio - 0.68) / 8));
        } elseif ($count >= 4 && $ratio >= 0.72) {
            $confidence = 0.955;
        } elseif ($count >= 2 && $ratio >= 0.8) {
            $confidence = 0.94;
        } elseif ($count === 1 && $ratio >= 0.999 && $productsTotal <= 3) {
            $confidence = 0.86;
        }
    }

    $alternatives = [];
    foreach (array_slice($memory, 1, 3) as $row) {
        if (is_array($row) && !empty($row['category'])) {
            $alternatives[] = (string)$row['category'];
        }
    }
    return [
        'category' => $category,
        'confidence' => round($confidence, 3),
        'reason' => $confidence > 0.0
            ? 'Эта категория уже устойчиво назначалась товарам той же категории поставщика.'
            : 'Недостаточно устойчивой памяти по категории поставщика.',
        'alternatives' => $alternatives,
        'source' => 'supplier_category_memory',
        'count' => $count,
        'total_existing' => $total,
        'ratio' => round($ratio, 3),
    ];
}

function supplier_products_db_mcat_existing_majority_decision(array $group, string $source): array
{
    $source = $source === 'wildberries' ? 'wildberries' : 'ozon';
    $existingKey = $source === 'ozon' ? 'existing_ozon' : 'existing_wb';
    $existing = (array)($group[$existingKey] ?? []);
    if (!$existing) {
        return [
            'category' => '',
            'confidence' => 0.0,
            'reason' => '',
            'alternatives' => [],
            'source' => 'existing_majority',
            'count' => 0,
            'total_existing' => 0,
        ];
    }

    arsort($existing);
    $topCategory = supplier_products_db_mcat_normalize_category_value($source, (string)array_key_first($existing));
    $topCount = (int)reset($existing);
    $totalExisting = max(1, array_sum(array_map('intval', $existing)));
    $ratio = $topCount / $totalExisting;
    $productsTotal = max(1, (int)($group['products_total'] ?? 0));
    $missingKey = $source === 'ozon' ? 'missing_ozon' : 'missing_wb';
    $missing = max(0, (int)($group[$missingKey] ?? 0));

    $confidence = 0.0;
    if (supplier_products_db_mcat_category_is_valid($source, $topCategory)) {
        if ($topCount >= 3 && $ratio >= 0.6) {
            $confidence = min(0.98, 0.9 + min(0.08, ($ratio - 0.6) / 5) + min(0.04, $topCount / 100));
        } elseif ($topCount >= 2 && $ratio >= 0.75) {
            $confidence = 0.93;
        } elseif ($topCount === 1 && $productsTotal <= 3 && $missing > 0) {
            $confidence = 0.86;
        }
    }

    $alternatives = array_keys(array_slice($existing, 1, 3, true));
    return [
        'category' => $topCategory,
        'confidence' => round($confidence, 3),
        'reason' => $confidence > 0.0
            ? 'Категория уже назначалась товарам той же категории поставщика.'
            : 'Нет устойчивого большинства среди уже назначенных категорий.',
        'alternatives' => array_values(array_map('strval', $alternatives)),
        'source' => 'existing_majority',
        'count' => $topCount,
        'total_existing' => $totalExisting,
        'ratio' => round($ratio, 3),
    ];
}

function supplier_products_db_mcat_apply_category_decision(
    PDO $pdo,
    int $supplierId,
    int $productId,
    array $productStub,
    array $fields,
    string $source,
    string $category,
    bool $overwrite
): bool {
    $source = $source === 'wildberries' ? 'wildberries' : 'ozon';
    $category = supplier_products_db_mcat_normalize_category_value($source, $category);
    if (!supplier_products_db_mcat_category_is_valid($source, $category)) {
        return false;
    }
    $current = supplier_products_db_product_category_value($productStub, $fields, $source);
    if (!$overwrite && $current !== '') {
        $guardedCurrent = supplier_products_db_mcat_guard_decision_against_product(
            ['category' => $current, 'confidence' => 1.0, 'reason' => 'current category check'],
            $source,
            $productStub,
            $fields
        );
        if (empty($guardedCurrent['guard_rejected_category'])) {
            return false;
        }
    }
    if ($source === 'ozon') {
        return supplier_products_db_set_tag_field($pdo, $supplierId, $productId, ['ozon_category'], 'ozon_category', $category);
    }
    return supplier_products_db_set_tag_field($pdo, $supplierId, $productId, ['wb_category', 'wb_subject_id'], 'wb_category', $category);
}

function supplier_products_db_mcat_decision_applicable(array $decision, string $source, float $threshold, string $strategy): bool
{
    $category = (string)($decision['category'] ?? '');
    if (!supplier_products_db_mcat_category_is_valid($source, $category)) {
        return false;
    }
    if ((float)($decision['confidence'] ?? 0) < $threshold) {
        return false;
    }
    $decisionSource = (string)($decision['source'] ?? 'llm');
    return $decisionSource !== 'llm' || $strategy === 'group';
}

function supplier_products_db_mcat_candidate_set(array $candidates, string $source): array
{
    $out = [];
    foreach ($candidates as $candidate) {
        if (!is_array($candidate)) {
            continue;
        }
        $category = supplier_products_db_mcat_normalize_category_value($source, (string)($candidate['category'] ?? ''));
        if ($category !== '') {
            $out[$category] = true;
        }
    }
    return $out;
}

function supplier_products_db_mcat_guard_llm_decision(array $decision, string $source, array $allowedSet): array
{
    $category = supplier_products_db_mcat_normalize_category_value($source, (string)($decision['category'] ?? ''));
    if ($category === '') {
        $decision['category'] = '';
        return $decision;
    }
    if (!isset($allowedSet[$category])) {
        $decision['rejected_category'] = $category;
        $decision['category'] = '';
        $decision['confidence'] = 0.0;
        $decision['reason'] = 'LLM выбрала категорию вне переданного shortlist кандидатов.';
    }
    return $decision;
}

function supplier_products_db_mcat_compact_profile(array $profile, int $maxTerms = 16): array
{
    $terms = [];
    foreach (array_slice((array)($profile['dominant_terms'] ?? []), 0, $maxTerms) as $row) {
        if (is_array($row) && trim((string)($row['term'] ?? '')) !== '') {
            $terms[] = [
                'term' => (string)$row['term'],
                'weight' => round((float)($row['weight'] ?? 0), 1),
            ];
        } elseif (is_string($row) && trim($row) !== '') {
            $terms[] = ['term' => trim($row)];
        }
    }
    $out = [
        'supplier_leaf' => (string)($profile['supplier_leaf'] ?? ''),
        'role_flags' => (array)($profile['role_flags'] ?? []),
        'dominant_terms' => $terms,
    ];
    if (is_array($profile['llm_role_analysis'] ?? null) && $profile['llm_role_analysis']) {
        $out['llm_role_analysis'] = (array)$profile['llm_role_analysis'];
    }
    return $out;
}

function supplier_products_db_mcat_compact_memory(array $memory, int $limit = 5): array
{
    $out = [];
    foreach (array_slice($memory, 0, $limit) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $out[] = [
            'category' => (string)($row['category'] ?? ''),
            'count' => (int)($row['count'] ?? 0),
            'ratio' => round((float)($row['ratio'] ?? 0), 3),
            'name' => acp_trunc((string)($row['name'] ?? ''), 90),
            'full_path' => acp_trunc((string)($row['full_path'] ?? ''), 180),
        ];
    }
    return $out;
}

function supplier_products_db_mcat_compact_match_signals($signals)
{
    if (is_object($signals)) {
        $signals = (array)$signals;
    }
    if (!is_array($signals) || !$signals) {
        return (object)[];
    }
    $out = [];
    foreach (['supplier_category_memory', 'already_used_in_supplier_category', 'profile_role', 'role_analysis_include', 'role_analysis_exclude', 'domain_boost', 'domain_penalty', 'supplier_path_exact', 'supplier_path_tokens'] as $key) {
        if (array_key_exists($key, $signals)) {
            $out[$key] = $signals[$key];
        }
    }
    return $out ?: (object)[];
}

function supplier_products_db_mcat_llm_candidates(array $candidates, int $limit, int $detailsTop): array
{
    $out = [];
    $limit = max(1, $limit);
    $detailsTop = max(0, $detailsTop);
    foreach (array_slice($candidates, 0, $limit) as $idx => $candidate) {
        if (!is_array($candidate)) {
            continue;
        }
        $row = [
            'category' => (string)($candidate['category'] ?? ''),
            'name' => acp_trunc((string)($candidate['name'] ?? ''), 90),
            'full_path' => acp_trunc((string)($candidate['full_path'] ?? ''), 220),
            'local_rank' => (int)($candidate['local_rank'] ?? ($idx + 1)),
            'local_score' => round((float)($candidate['local_score'] ?? 0), 2),
            'match_signals' => supplier_products_db_mcat_compact_match_signals($candidate['match_signals'] ?? []),
        ];
        if ($idx < $detailsTop) {
            foreach (['description' => 180, 'typical_goods' => 180, 'features' => 150, 'keywords' => 160, 'category_attributes' => 180] as $key => $maxLen) {
                $value = trim((string)($candidate[$key] ?? ''));
                if ($value !== '') {
                    $row[$key] = acp_trunc($value, $maxLen);
                }
            }
        }
        $out[] = $row;
    }
    return $out;
}

function supplier_products_db_mcat_llm_candidate_categories(array $candidates): array
{
    return array_values(array_filter(array_map(static fn(array $row): string => (string)($row['category'] ?? ''), $candidates)));
}

function supplier_products_db_mcat_apply_group_category_decisions(
    PDO $pdo,
    int $supplierId,
    array $group,
    array $productById,
    array $fieldsByProduct,
    array $resolvedOzon,
    array $resolvedWb,
    bool $wantOzon,
    bool $wantWb,
    bool $overwrite,
    float $autoConfidence,
    string $strategy,
    array &$changedProductIds,
    array &$assignedCategoryByProduct,
    array &$groupReport,
    array &$summary
): void {
    foreach ((array)($group['product_ids'] ?? []) as $productId) {
        $productId = (int)$productId;
        if ($productId <= 0) {
            continue;
        }
        $fields = $fieldsByProduct[$productId] ?? [];
        $productStub = $productById[$productId] ?? ['ozon_category' => '', 'wb_category' => ''];

        if ($wantOzon && supplier_products_db_mcat_decision_applicable($resolvedOzon, 'ozon', $autoConfidence, $strategy)) {
            if (supplier_products_db_mcat_apply_category_decision($pdo, $supplierId, $productId, $productStub, $fields, 'ozon', (string)$resolvedOzon['category'], $overwrite)) {
                $changedProductIds[$productId] = true;
                $assignedCategoryByProduct[$productId]['ozon'] = true;
                $groupReport['applied_ozon']++;
                $summary['applied_ozon']++;
                if (($resolvedOzon['source'] ?? '') === 'existing_majority') {
                    $groupReport['applied_from_existing_majority_ozon']++;
                    $summary['applied_from_existing_majority_ozon']++;
                } elseif (($resolvedOzon['source'] ?? '') === 'supplier_category_memory') {
                    $groupReport['applied_from_supplier_category_memory_ozon']++;
                    $summary['applied_from_supplier_category_memory_ozon']++;
                }
            }
        }

        if ($wantWb && supplier_products_db_mcat_decision_applicable($resolvedWb, 'wildberries', $autoConfidence, $strategy)) {
            if (supplier_products_db_mcat_apply_category_decision($pdo, $supplierId, $productId, $productStub, $fields, 'wildberries', (string)$resolvedWb['category'], $overwrite)) {
                $changedProductIds[$productId] = true;
                $assignedCategoryByProduct[$productId]['wildberries'] = true;
                $groupReport['applied_wb']++;
                $summary['applied_wb']++;
                if (($resolvedWb['source'] ?? '') === 'existing_majority') {
                    $groupReport['applied_from_existing_majority_wb']++;
                    $summary['applied_from_existing_majority_wb']++;
                } elseif (($resolvedWb['source'] ?? '') === 'supplier_category_memory') {
                    $groupReport['applied_from_supplier_category_memory_wb']++;
                    $summary['applied_from_supplier_category_memory_wb']++;
                }
            }
        }
    }
}

function supplier_products_db_mcat_group_prompt_sample(array $group, int $limit = 12): array
{
    $sample = array_slice((array)($group['sample'] ?? []), 0, max(1, $limit));
    foreach ($sample as &$product) {
        unset($product['product_id'], $product['offer_id'], $product['vendor_code'], $product['current_ozon_category'], $product['current_wb_category']);
        $product['description_snippet'] = acp_trunc((string)($product['description_snippet'] ?? ''), 180);
        $product['params'] = array_slice((array)($product['params'] ?? []), 0, 6);
        foreach ($product as $key => $value) {
            if ($value === '' || $value === [] || $value === null) {
                unset($product[$key]);
            }
        }
    }
    unset($product);
    return $sample;
}

function supplier_products_db_mcat_product_payloads(array $productIds, array $productById, array $fieldsByProduct): array
{
    $out = [];
    foreach ($productIds as $productId) {
        $productId = (int)$productId;
        if ($productId <= 0 || !isset($productById[$productId])) {
            continue;
        }
        $payload = supplier_products_db_mcat_product_payload($productById[$productId], $fieldsByProduct[$productId] ?? []);
        unset($payload['offer_id'], $payload['vendor_code'], $payload['current_ozon_category'], $payload['current_wb_category']);
        $payload['description_snippet'] = acp_trunc((string)($payload['description_snippet'] ?? ''), 180);
        $payload['params'] = array_slice((array)($payload['params'] ?? []), 0, 6);
        foreach ($payload as $key => $value) {
            if ($value === '' || $value === [] || $value === null) {
                unset($payload[$key]);
            }
        }
        $out[] = $payload;
    }
    return $out;
}

function supplier_products_db_mcat_fallback_ids(
    array $group,
    array $productById,
    array $fieldsByProduct,
    array $assignedCategoryByProduct,
    bool $wantOzon,
    bool $wantWb,
    bool $overwrite,
    bool $needsOzonFallback,
    bool $needsWbFallback
): array {
    $ids = [];
    $needOzon = false;
    $needWb = false;
    $needOzonCount = 0;
    $needWbCount = 0;
    foreach ((array)($group['product_ids'] ?? []) as $productId) {
        $productId = (int)$productId;
        if ($productId <= 0 || !isset($productById[$productId])) {
            continue;
        }
        $fields = $fieldsByProduct[$productId] ?? [];
        $product = $productById[$productId];
        $productNeedsOzon = $wantOzon
            && $needsOzonFallback
            && empty($assignedCategoryByProduct[$productId]['ozon'])
            && ($overwrite || supplier_products_db_product_category_value($product, $fields, 'ozon') === '');
        $productNeedsWb = $wantWb
            && $needsWbFallback
            && empty($assignedCategoryByProduct[$productId]['wildberries'])
            && ($overwrite || supplier_products_db_product_category_value($product, $fields, 'wildberries') === '');
        if ($productNeedsOzon || $productNeedsWb) {
            $ids[] = $productId;
            $needOzon = $needOzon || $productNeedsOzon;
            $needWb = $needWb || $productNeedsWb;
            $needOzonCount += $productNeedsOzon ? 1 : 0;
            $needWbCount += $productNeedsWb ? 1 : 0;
        }
    }
    return [
        'ids' => $ids,
        'need_ozon' => $needOzon,
        'need_wb' => $needWb,
        'need_ozon_count' => $needOzonCount,
        'need_wb_count' => $needWbCount,
    ];
}

function supplier_products_db_mcat_product_decisions(array $decoded, string $source): array
{
    $source = $source === 'wildberries' ? 'wildberries' : 'ozon';
    $sourceKey = $source === 'ozon' ? 'ozon' : 'wildberries';
    $categoryKey = $source === 'ozon' ? 'ozon_category' : 'wb_category';
    $out = [];
    foreach ((array)($decoded['product_decisions'] ?? []) as $row) {
        if (!is_array($row)) {
            continue;
        }
        $productId = (int)($row['product_id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        $raw = $row[$sourceKey] ?? null;
        if (!is_array($raw)) {
            $raw = [
                'category' => $row[$categoryKey] ?? '',
                'confidence' => $row[$sourceKey . '_confidence'] ?? ($row['confidence'] ?? 0),
                'reason' => $row[$sourceKey . '_reason'] ?? ($row['reason'] ?? ''),
            ];
        }
        $category = supplier_products_db_mcat_normalize_category_value($source, (string)($raw['category'] ?? ''));
        $out[$productId] = [
            'category' => $category,
            'confidence' => max(0.0, min(1.0, (float)($raw['confidence'] ?? 0))),
            'reason' => acp_trunc((string)($raw['reason'] ?? ''), 220),
        ];
    }
    return $out;
}

function supplier_products_db_mcat_decision(array $decoded, string $source): array
{
    $key = $source === 'ozon' ? 'ozon' : 'wildberries';
    $raw = $decoded[$key] ?? [];
    if (!is_array($raw)) {
        $raw = [];
    }
    $category = supplier_products_db_mcat_normalize_category_value($source, (string)($raw['category'] ?? ''));
    return [
        'category' => $category,
        'confidence' => max(0.0, min(1.0, (float)($raw['confidence'] ?? 0))),
        'reason' => acp_trunc((string)($raw['reason'] ?? ''), 280),
        'alternatives' => array_values(array_slice(array_filter(array_map('strval', (array)($raw['alternatives'] ?? []))), 0, 5)),
    ];
}

function supplier_products_db_mcat_verification_decision(array $decoded, string $source): array
{
    $key = $source === 'ozon' ? 'ozon' : 'wildberries';
    $raw = $decoded[$key] ?? ($decoded[$key . '_verification'] ?? []);
    if (!is_array($raw)) {
        $raw = [];
    }
    $approvedRaw = $raw['approved'] ?? ($raw['is_correct'] ?? null);
    $approved = is_bool($approvedRaw)
        ? $approvedRaw
        : in_array(strtolower(trim((string)$approvedRaw)), ['1', 'true', 'yes', 'ok', 'approved', 'correct'], true);
    return [
        'approved' => $approved,
        'confidence' => max(0.0, min(1.0, (float)($raw['confidence'] ?? $raw['verified_confidence'] ?? 0))),
        'better_category' => supplier_products_db_mcat_normalize_category_value($source, (string)($raw['better_category'] ?? '')),
        'reason' => acp_trunc(trim((string)($raw['reason'] ?? '')), 260),
    ];
}

function supplier_products_db_mcat_apply_verification_to_decision(
    array $decision,
    array $verification,
    string $source,
    float $minVerifiedConfidence
): array {
    $category = supplier_products_db_mcat_normalize_category_value($source, (string)($decision['category'] ?? ''));
    if ($category === '' || !supplier_products_db_mcat_category_is_valid($source, $category)) {
        return $decision;
    }

    $verifiedConfidence = (float)($verification['confidence'] ?? 0);
    $approved = !empty($verification['approved']) && $verifiedConfidence >= $minVerifiedConfidence;
    $decision['verification'] = [
        'approved' => !empty($verification['approved']) ? 1 : 0,
        'confidence' => round($verifiedConfidence, 3),
        'better_category' => (string)($verification['better_category'] ?? ''),
        'reason' => (string)($verification['reason'] ?? ''),
    ];

    if (!$approved) {
        $decision['confidence'] = min((float)($decision['confidence'] ?? 0), max(0.0, $minVerifiedConfidence - 0.03));
        $decision['verification_rejected'] = 1;
        if (($decision['reason'] ?? '') !== '') {
            $decision['reason'] = acp_trunc((string)$decision['reason'] . ' Проверка: ' . (string)($verification['reason'] ?? ''), 280);
        } else {
            $decision['reason'] = acp_trunc('Проверка: ' . (string)($verification['reason'] ?? ''), 280);
        }
        return $decision;
    }

    $decision['confidence'] = min((float)($decision['confidence'] ?? 0), max($minVerifiedConfidence, $verifiedConfidence));
    $decision['verification_approved'] = 1;
    return $decision;
}

function supplier_products_db_mcat_verifier_candidates(array $candidates, array $decision, int $limit = 12): array
{
    $chosen = trim((string)($decision['category'] ?? ''));
    $out = [];
    foreach ($candidates as $candidate) {
        if (!is_array($candidate)) {
            continue;
        }
        $category = trim((string)($candidate['category'] ?? ''));
        if ($category === '') {
            continue;
        }
        if ($category === $chosen || count($out) < $limit) {
            $row = [
                'category' => $category,
                'name' => acp_trunc((string)($candidate['name'] ?? ''), 90),
                'full_path' => acp_trunc((string)($candidate['full_path'] ?? ''), 240),
                'local_rank' => (int)($candidate['local_rank'] ?? 0),
                'local_score' => round((float)($candidate['local_score'] ?? 0), 2),
                'match_signals' => supplier_products_db_mcat_compact_match_signals($candidate['match_signals'] ?? []),
            ];
            foreach (['description' => 180, 'typical_goods' => 180, 'features' => 150, 'keywords' => 160, 'category_attributes' => 180] as $key => $maxLen) {
                $value = trim((string)($candidate[$key] ?? ''));
                if ($value !== '') {
                    $row[$key] = acp_trunc($value, $maxLen);
                }
            }
            $out[$category] = $row;
        }
        if (count($out) >= $limit && ($chosen === '' || isset($out[$chosen]))) {
            break;
        }
    }
    return array_values($out);
}

function supplier_products_db_op_gpt_assign_marketplace_categories(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $maxGroups = max(0, (int)trim((string)($params['max_groups'] ?? '0')));
    $maxSample = max(5, min(100, (int)trim((string)($params['max_products_per_group'] ?? '48'))));
    $maxCandidates = max(8, min(140, (int)trim((string)($params['max_candidates_per_marketplace'] ?? '70'))));
    $llmProductsPerGroup = max(4, min(36, (int)trim((string)($params['llm_products_per_group'] ?? '16'))));
    $llmCandidatesLimit = max(6, min($maxCandidates, (int)trim((string)($params['llm_candidates_per_marketplace'] ?? '42'))));
    $llmCandidateDetailsTop = max(0, min($llmCandidatesLimit, (int)trim((string)($params['llm_candidate_details_top'] ?? '22'))));
    $apply = ((string)($params['apply'] ?? '1') !== '0');
    $overwrite = ((string)($params['overwrite'] ?? '0') === '1');
    $autoConfidence = max(0.5, min(0.99, (float)str_replace(',', '.', (string)($params['auto_confidence'] ?? '0.88'))));
    $productFallback = ((string)($params['product_fallback'] ?? '1') !== '0');
    $fallbackConfidenceDefault = max(0.78, $autoConfidence - 0.08);
    $fallbackConfidence = max(0.5, min(0.99, (float)str_replace(',', '.', (string)($params['fallback_confidence'] ?? (string)$fallbackConfidenceDefault))));
    $maxProductFallbackPerGroup = max(0, min(400, (int)trim((string)($params['max_product_fallback_per_group'] ?? '120'))));
    $fallbackChunkSize = max(5, min(24, (int)trim((string)($params['fallback_chunk_size'] ?? '12'))));
    $rolePrepass = ((string)($params['role_prepass'] ?? '1') !== '0');
    $verifyDecisions = ((string)($params['verify_decisions'] ?? '1') !== '0');
    $verificationConfidence = max(0.5, min(0.99, (float)str_replace(',', '.', (string)($params['verification_confidence'] ?? '0.82'))));
    $marketplacesParam = strtolower(trim((string)($params['marketplaces'] ?? 'both')));
    $wantOzon = $marketplacesParam === '' || $marketplacesParam === 'both' || str_contains($marketplacesParam, 'ozon');
    $wantWb = $marketplacesParam === '' || $marketplacesParam === 'both' || str_contains($marketplacesParam, 'wb') || str_contains($marketplacesParam, 'wildberries');

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'assign_marketplace_categories_ru.txt');

    $log("supplier_db gpt_assign_marketplace_categories: model={$model}, apply=" . ($apply ? '1' : '0') . ", overwrite=" . ($overwrite ? '1' : '0') . ", auto_confidence={$autoConfidence}, fallback=" . ($productFallback ? '1' : '0') . ", fallback_confidence={$fallbackConfidence}, role_prepass=" . ($rolePrepass ? '1' : '0') . ", verifier=" . ($verifyDecisions ? '1' : '0') . ", verifier_confidence={$verificationConfidence}, llm_candidates={$llmCandidatesLimit}, llm_sample={$llmProductsPerGroup}\n");
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, $maxItems);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    $groups = supplier_products_db_mcat_build_groups($products, $fieldsByProduct, $overwrite, $maxSample);
    if ($maxGroups > 0) {
        $groups = array_slice($groups, 0, $maxGroups, true);
    }

    $totalGroups = count($groups);
    ops_update_progress($opId, 0, max(1, $totalGroups), 'scan', "groups={$totalGroups}");

    $report = [
        'summary' => [
            'storage' => 'supplier_products_db',
            'supplier_id' => $supplierId,
            'dataset_id' => $datasetId,
            'model' => $model,
            'products_seen' => count($products),
            'groups_total' => $totalGroups,
            'apply' => $apply ? 1 : 0,
            'overwrite' => $overwrite ? 1 : 0,
            'auto_confidence' => $autoConfidence,
            'llm_products_per_group' => $llmProductsPerGroup,
            'llm_candidates_per_marketplace' => $llmCandidatesLimit,
            'llm_candidate_details_top' => $llmCandidateDetailsTop,
            'role_prepass' => $rolePrepass ? 1 : 0,
            'verify_decisions' => $verifyDecisions ? 1 : 0,
            'verification_confidence' => $verificationConfidence,
            'applied_products' => 0,
            'applied_ozon' => 0,
            'applied_wb' => 0,
            'applied_from_existing_majority_ozon' => 0,
            'applied_from_existing_majority_wb' => 0,
            'applied_from_supplier_category_memory_ozon' => 0,
            'applied_from_supplier_category_memory_wb' => 0,
            'applied_from_product_fallback_ozon' => 0,
            'applied_from_product_fallback_wb' => 0,
            'memory_direct_groups' => 0,
            'memory_candidate_groups' => 0,
            'memory_partial_groups' => 0,
            'role_analysis_requests' => 0,
            'role_analysis_errors' => 0,
            'verification_requests' => 0,
            'verification_errors' => 0,
            'verification_approved_ozon' => 0,
            'verification_approved_wb' => 0,
            'verification_rejected_ozon' => 0,
            'verification_rejected_wb' => 0,
            'gpt_requests_estimated' => 0,
            'gpt_requests_sent' => 0,
            'gpt_requests_usage_estimated' => 0,
            'gpt_requests_skipped_by_memory' => 0,
            'rejected_llm_out_of_candidates_ozon' => 0,
            'rejected_llm_out_of_candidates_wb' => 0,
            'fallback_candidate_products' => 0,
            'fallback_skipped_no_remaining_products' => 0,
            'review_groups' => 0,
            'error_groups' => 0,
        ],
        'groups' => [],
    ];

    if (!$groups) {
        ops_update_progress($opId, 100, 100, 'done', 'No products');
        return supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    }

    $client = LLM::client($cfg, $model);
    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $estimatedRequests = 0;
    $estimatedInputTokensTotal = 0;
    $estimatedExpectedOutputTokensTotal = 0;
    $estimatedMaxOutputTokensTotal = 0;
    $estimatedExpectedCostTotal = 0.0;
    $estimatedMaxCostTotal = 0.0;
    $usageEstimatedRequests = 0;
    $memorySkippedRequests = 0;
    $llmAttempts = 0;
    $llmErrors = 0;
    $firstLlmError = '';
    $changedProductIds = [];
    $assignedCategoryByProduct = [];
    $pdo = db();
    $done = 0;
    $productById = [];
    foreach ($products as $productRow) {
        $pid = (int)($productRow['id'] ?? 0);
        if ($pid > 0) {
            $productById[$pid] = $productRow;
        }
    }

    foreach ($groups as $groupKey => $group) {
        $done++;
        ops_update_progress($opId, $done - 1, max(1, $totalGroups), 'gpt', "category group {$done}/{$totalGroups}");

        $ozonMemory = $wantOzon ? supplier_products_db_mcat_supplier_category_memory($supplierId, $group, 'ozon') : [];
        $wbMemory = $wantWb ? supplier_products_db_mcat_supplier_category_memory($supplierId, $group, 'wildberries') : [];
        $ozonMemoryDecision = $wantOzon ? supplier_products_db_mcat_memory_decision($ozonMemory, $group, 'ozon') : [];
        $wbMemoryDecision = $wantWb ? supplier_products_db_mcat_memory_decision($wbMemory, $group, 'wildberries') : [];
        if ($wantOzon) {
            $ozonMemoryDecision = supplier_products_db_mcat_guard_decision_against_group($ozonMemoryDecision, 'ozon', $group);
        }
        if ($wantWb) {
            $wbMemoryDecision = supplier_products_db_mcat_guard_decision_against_group($wbMemoryDecision, 'wildberries', $group);
        }
        $needsOzonCategory = $wantOzon && ((int)($group['missing_ozon'] ?? 0) > 0 || $overwrite);
        $needsWbCategory = $wantWb && ((int)($group['missing_wb'] ?? 0) > 0 || $overwrite);
        $ozonMemoryApplicable = $needsOzonCategory
            && supplier_products_db_mcat_decision_applicable($ozonMemoryDecision, 'ozon', $autoConfidence, 'group');
        $wbMemoryApplicable = $needsWbCategory
            && supplier_products_db_mcat_decision_applicable($wbMemoryDecision, 'wildberries', $autoConfidence, 'group');
        $roleAnalysis = [];
        $roleAnalysisEstimate = null;
        $roleAnalysisUsage = null;
        $roleAnalysisError = '';
        $roleAnalysisNeeded = $rolePrepass
            && (
                ($needsOzonCategory && !$ozonMemoryApplicable)
                || ($needsWbCategory && !$wbMemoryApplicable)
            );
        if ($roleAnalysisNeeded) {
            try {
                $roleRequest = [
                    'mode' => 'role_analysis',
                    'supplier_group' => [
                        'supplier_category_id' => (string)($group['supplier_category_id'] ?? ''),
                        'supplier_category_path' => (string)($group['supplier_category_path'] ?? ''),
                        'profile' => supplier_products_db_mcat_compact_profile((array)($group['profile'] ?? [])),
                        'products_total' => (int)($group['products_total'] ?? 0),
                        'products_sample' => supplier_products_db_mcat_group_prompt_sample($group, min($llmProductsPerGroup, 18)),
                        'existing_ozon_categories' => array_slice((array)($group['existing_ozon'] ?? []), 0, 8, true),
                        'existing_wb_categories' => array_slice((array)($group['existing_wb'] ?? []), 0, 8, true),
                    ],
                    'marketplaces' => [
                        'ozon' => [
                            'need_fill_count' => (int)($group['missing_ozon'] ?? 0),
                            'supplier_category_memory' => supplier_products_db_mcat_compact_memory($ozonMemory),
                        ],
                        'wildberries' => [
                            'need_fill_count' => (int)($group['missing_wb'] ?? 0),
                            'supplier_category_memory' => supplier_products_db_mcat_compact_memory($wbMemory),
                        ],
                    ],
                    'instruction' => 'Сначала определи товарную роль группы и термины, которые помогут выбрать категорию. Не выбирай коды категорий на этом шаге.',
                ];
                $roleJson = json_encode($roleRequest, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                if ($roleJson === false) {
                    $roleJson = '{"mode":"role_analysis"}';
                }
                $roleUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $roleJson;
                $roleMaxOutputTokens = 900;
                $roleEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $roleUserMessage, $roleMaxOutputTokens, 0.5);
                $roleAnalysisEstimate = $roleEstimate;
                $estimatedRequests++;
                $estimatedInputTokensTotal += (int)$roleEstimate['input_tokens'];
                $estimatedExpectedOutputTokensTotal += (int)$roleEstimate['expected_output_tokens'];
                $estimatedMaxOutputTokensTotal += (int)$roleEstimate['max_output_tokens'];
                $estimatedExpectedCostTotal += (float)$roleEstimate['expected_cost'];
                $estimatedMaxCostTotal += (float)$roleEstimate['max_cost'];
                $report['summary']['role_analysis_requests']++;

                $llmAttempts++;
                $roleRes = $client->generateText($model, $roleUserMessage, $prompt, [
                    'prompt_cache_key' => 'assign_mcat_role:' . substr(hash('sha256', json_encode([
                        'supplier_category_path' => $group['supplier_category_path'] ?? '',
                        'profile' => supplier_products_db_mcat_compact_profile((array)($group['profile'] ?? [])),
                        'ozon_memory' => array_column($ozonMemory, 'category'),
                        'wb_memory' => array_column($wbMemory, 'category'),
                    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                    'text' => ['format' => ['type' => 'json_object']],
                    'max_output_tokens' => $roleMaxOutputTokens,
                ]);
                $roleRaw = $roleRes['raw'] ?? null;
                $roleUsage = supplier_products_db_merge_llm_usage_with_estimate(
                    $cfg,
                    $model,
                    is_array($roleRaw) ? $roleRaw : null,
                    $prompt,
                    $roleUserMessage,
                    (string)($roleRes['output_text'] ?? ''),
                    $roleMaxOutputTokens
                );
                $roleAnalysisUsage = $roleUsage;
                $tokensInTotal += (int)$roleUsage['input'];
                $tokensOutTotal += (int)$roleUsage['output'];
                $tokensCachedTotal += (int)$roleUsage['cached_input'];
                $costUsdTotal += (float)$roleUsage['cost'];
                if (!empty($roleUsage['estimated'])) {
                    $usageEstimatedRequests++;
                }
                $roleDecoded = supplier_products_db_extract_json_object((string)($roleRes['output_text'] ?? ''));
                $roleAnalysis = supplier_products_db_mcat_normalize_role_analysis($roleDecoded);
                if ($roleAnalysis['product_role'] !== '' || $roleAnalysis['include_category_terms'] || $roleAnalysis['target_objects']) {
                    $group['profile']['llm_role_analysis'] = $roleAnalysis;
                }
            } catch (Throwable $e) {
                $roleAnalysisError = $e->getMessage();
                $report['summary']['role_analysis_errors']++;
                $log("assign category role analysis skipped group {$done}: " . $e->getMessage() . "\n");
            }
        }
        $ozonCandidates = $wantOzon && ((int)($group['missing_ozon'] ?? 0) > 0 || $overwrite)
            ? supplier_products_db_mcat_candidates('ozon', $group, $maxCandidates, $ozonMemory)
            : [];
        $wbCandidates = $wantWb && ((int)($group['missing_wb'] ?? 0) > 0 || $overwrite)
            ? supplier_products_db_mcat_candidates('wildberries', $group, $maxCandidates, $wbMemory)
            : [];
        $ozonMajority = $wantOzon ? supplier_products_db_mcat_existing_majority_decision($group, 'ozon') : [];
        $wbMajority = $wantWb ? supplier_products_db_mcat_existing_majority_decision($group, 'wildberries') : [];
        if ($wantOzon) {
            $ozonMajority = supplier_products_db_mcat_guard_decision_against_group($ozonMajority, 'ozon', $group);
        }
        if ($wantWb) {
            $wbMajority = supplier_products_db_mcat_guard_decision_against_group($wbMajority, 'wildberries', $group);
        }
        if ($ozonMemory || $wbMemory) {
            $report['summary']['memory_candidate_groups']++;
        }

        $groupReport = [
            'supplier_category_id' => (string)($group['supplier_category_id'] ?? ''),
            'supplier_category_path' => (string)($group['supplier_category_path'] ?? ''),
            'profile' => $group['profile'] ?? [],
            'products_total' => (int)($group['products_total'] ?? 0),
            'missing_ozon' => (int)($group['missing_ozon'] ?? 0),
            'missing_wb' => (int)($group['missing_wb'] ?? 0),
            'invalid_existing_ozon' => (int)($group['invalid_existing_ozon'] ?? 0),
            'invalid_existing_wb' => (int)($group['invalid_existing_wb'] ?? 0),
            'existing_ozon' => array_slice((array)($group['existing_ozon'] ?? []), 0, 5, true),
            'existing_wb' => array_slice((array)($group['existing_wb'] ?? []), 0, 5, true),
            'supplier_category_memory_ozon' => $ozonMemory,
            'supplier_category_memory_wb' => $wbMemory,
            'supplier_category_memory_decision_ozon' => $ozonMemoryDecision,
            'supplier_category_memory_decision_wb' => $wbMemoryDecision,
            'candidates_ozon' => count($ozonCandidates),
            'candidates_wb' => count($wbCandidates),
            'top_candidate_ozon' => $ozonCandidates[0]['category'] ?? '',
            'top_candidate_wb' => $wbCandidates[0]['category'] ?? '',
            'existing_majority_ozon' => $ozonMajority,
            'existing_majority_wb' => $wbMajority,
            'status' => 'planned',
            'applied_ozon' => 0,
            'applied_wb' => 0,
            'applied_from_existing_majority_ozon' => 0,
            'applied_from_existing_majority_wb' => 0,
            'applied_from_supplier_category_memory_ozon' => 0,
            'applied_from_supplier_category_memory_wb' => 0,
            'applied_from_product_fallback_ozon' => 0,
            'applied_from_product_fallback_wb' => 0,
        ];
        if ($roleAnalysis) {
            $groupReport['role_analysis'] = $roleAnalysis;
        }
        if (is_array($roleAnalysisEstimate)) {
            $groupReport['role_analysis_estimate'] = $roleAnalysisEstimate;
        }
        if (is_array($roleAnalysisUsage)) {
            $groupReport['role_analysis_actual_usage'] = $roleAnalysisUsage;
        }
        if ($roleAnalysisError !== '') {
            $groupReport['role_analysis_error'] = $roleAnalysisError;
        }

        if (!$ozonCandidates && !$wbCandidates && !$ozonMemoryApplicable && !$wbMemoryApplicable) {
            $groupReport['status'] = 'skipped_no_candidates_or_nothing_to_fill';
            $report['groups'][] = $groupReport;
            continue;
        }

        $canUseMemoryDirectly = ($ozonMemoryApplicable || $wbMemoryApplicable)
            && (!$needsOzonCategory || $ozonMemoryApplicable)
            && (!$needsWbCategory || $wbMemoryApplicable);
        if ($canUseMemoryDirectly) {
            $groupReport['status'] = $apply ? 'ok_supplier_category_memory_direct' : 'planned_supplier_category_memory_direct';
            $groupReport['strategy'] = 'group';
            $groupReport['resolved_ozon'] = $ozonMemoryDecision;
            $groupReport['resolved_wb'] = $wbMemoryDecision;
            $report['summary']['memory_direct_groups']++;
            $memorySkippedRequests++;
            $groupReport['gpt_request_skipped_by_memory'] = 1;
            if ($apply) {
                supplier_products_db_mcat_apply_group_category_decisions(
                    $pdo,
                    $supplierId,
                    $group,
                    $productById,
                    $fieldsByProduct,
                    $ozonMemoryDecision,
                    $wbMemoryDecision,
                    $wantOzon,
                    $wantWb,
                    $overwrite,
                    $autoConfidence,
                    'group',
                    $changedProductIds,
                    $assignedCategoryByProduct,
                    $groupReport,
                    $report['summary']
                );
            }
            $report['groups'][] = $groupReport;
            continue;
        }

        $ozonHandledByMemory = false;
        $wbHandledByMemory = false;
        if ($ozonMemoryApplicable || $wbMemoryApplicable) {
            $groupReport['status'] = $apply ? 'ok_supplier_category_memory_partial' : 'planned_supplier_category_memory_partial';
            $report['summary']['memory_partial_groups']++;
            if ($ozonMemoryApplicable) {
                $ozonHandledByMemory = true;
                $groupReport['resolved_ozon'] = $ozonMemoryDecision;
            }
            if ($wbMemoryApplicable) {
                $wbHandledByMemory = true;
                $groupReport['resolved_wb'] = $wbMemoryDecision;
            }
            if ($apply) {
                supplier_products_db_mcat_apply_group_category_decisions(
                    $pdo,
                    $supplierId,
                    $group,
                    $productById,
                    $fieldsByProduct,
                    $ozonMemoryDecision,
                    $wbMemoryDecision,
                    $ozonHandledByMemory,
                    $wbHandledByMemory,
                    $overwrite,
                    $autoConfidence,
                    'group',
                    $changedProductIds,
                    $assignedCategoryByProduct,
                    $groupReport,
                    $report['summary']
                );
            }
        }

        $ozonCandidatesForLlm = $ozonHandledByMemory ? [] : $ozonCandidates;
        $wbCandidatesForLlm = $wbHandledByMemory ? [] : $wbCandidates;
        $ozonLlmCandidates = supplier_products_db_mcat_llm_candidates($ozonCandidatesForLlm, $llmCandidatesLimit, $llmCandidateDetailsTop);
        $wbLlmCandidates = supplier_products_db_mcat_llm_candidates($wbCandidatesForLlm, $llmCandidatesLimit, $llmCandidateDetailsTop);
        $ozonAllowedLlmCategories = supplier_products_db_mcat_candidate_set($ozonLlmCandidates, 'ozon');
        $wbAllowedLlmCategories = supplier_products_db_mcat_candidate_set($wbLlmCandidates, 'wildberries');

        if (!$ozonLlmCandidates && !$wbLlmCandidates) {
            if (!$ozonHandledByMemory && !$wbHandledByMemory) {
                $groupReport['status'] = 'skipped_no_llm_candidates';
            }
            $report['groups'][] = $groupReport;
            continue;
        }

        $request = [
            'mode' => 'supplier_group',
            'supplier_group' => [
                'supplier_category_id' => (string)($group['supplier_category_id'] ?? ''),
                'supplier_category_path' => (string)($group['supplier_category_path'] ?? ''),
                'profile' => supplier_products_db_mcat_compact_profile((array)($group['profile'] ?? [])),
                'role_analysis' => $roleAnalysis,
                'products_total' => (int)($group['products_total'] ?? 0),
                'products_sample' => supplier_products_db_mcat_group_prompt_sample($group, $llmProductsPerGroup),
                'existing_ozon_categories' => array_slice((array)($group['existing_ozon'] ?? []), 0, 8, true),
                'existing_wb_categories' => array_slice((array)($group['existing_wb'] ?? []), 0, 8, true),
                'instruction' => 'Путь категории поставщика — только подсказка. Если название, характеристики или фото-описания товаров противоречат пути поставщика, игнорируй путь поставщика и выбирай категорию по реальной товарной роли.',
            ],
            'marketplaces' => [
                'ozon' => [
                    'need_fill_count' => $ozonHandledByMemory ? 0 : (int)($group['missing_ozon'] ?? 0),
                    'supplier_category_memory' => supplier_products_db_mcat_compact_memory($ozonMemory),
                    'candidates' => $ozonLlmCandidates,
                ],
                'wildberries' => [
                    'need_fill_count' => $wbHandledByMemory ? 0 : (int)($group['missing_wb'] ?? 0),
                    'supplier_category_memory' => supplier_products_db_mcat_compact_memory($wbMemory),
                    'candidates' => $wbLlmCandidates,
                ],
            ],
        ];
        $inputJson = json_encode($request, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($inputJson === false) {
            $inputJson = '{"supplier_group":{},"marketplaces":{}}';
        }
        $groupUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $inputJson;
        $groupMaxOutputTokens = 1800;
        $groupEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $groupUserMessage, $groupMaxOutputTokens, 0.46);
        $estimatedRequests++;
        $estimatedInputTokensTotal += (int)$groupEstimate['input_tokens'];
        $estimatedExpectedOutputTokensTotal += (int)$groupEstimate['expected_output_tokens'];
        $estimatedMaxOutputTokensTotal += (int)$groupEstimate['max_output_tokens'];
        $estimatedExpectedCostTotal += (float)$groupEstimate['expected_cost'];
        $estimatedMaxCostTotal += (float)$groupEstimate['max_cost'];
        $groupReport['gpt_estimate'] = $groupEstimate;

        try {
            $llmAttempts++;
            $res = $client->generateText($model, $groupUserMessage, $prompt, [
                'prompt_cache_key' => 'assign_mcat:' . substr(hash('sha256', json_encode([
                    'supplier_category_path' => $group['supplier_category_path'] ?? '',
                    'profile' => supplier_products_db_mcat_compact_profile((array)($group['profile'] ?? [])),
                    'ozon_memory' => array_column($ozonMemory, 'category'),
                    'wb_memory' => array_column($wbMemory, 'category'),
                    'ozon_candidates' => supplier_products_db_mcat_llm_candidate_categories($ozonLlmCandidates),
                    'wb_candidates' => supplier_products_db_mcat_llm_candidate_categories($wbLlmCandidates),
                ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                'text' => ['format' => ['type' => 'json_object']],
                'max_output_tokens' => $groupMaxOutputTokens,
            ]);

            $raw = $res['raw'] ?? null;
            $usage = supplier_products_db_merge_llm_usage_with_estimate(
                $cfg,
                $model,
                is_array($raw) ? $raw : null,
                $prompt,
                $groupUserMessage,
                (string)($res['output_text'] ?? ''),
                $groupMaxOutputTokens
            );
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += (float)$usage['cost'];
            if (!empty($usage['estimated'])) {
                $usageEstimatedRequests++;
            }
            $groupReport['gpt_actual_usage'] = $usage;

            $decoded = supplier_products_db_extract_json_object((string)($res['output_text'] ?? ''));
            $strategy = trim((string)($decoded['strategy'] ?? 'uncertain'));
            if (!in_array($strategy, ['group', 'mixed', 'uncertain'], true)) {
                $strategy = 'uncertain';
            }

            $ozonDecision = supplier_products_db_mcat_decision($decoded, 'ozon');
            $wbDecision = supplier_products_db_mcat_decision($decoded, 'wildberries');
            $ozonRejectedCategory = (string)($ozonDecision['category'] ?? '');
            $wbRejectedCategory = (string)($wbDecision['category'] ?? '');
            $ozonDecision = supplier_products_db_mcat_guard_llm_decision($ozonDecision, 'ozon', $ozonAllowedLlmCategories);
            $wbDecision = supplier_products_db_mcat_guard_llm_decision($wbDecision, 'wildberries', $wbAllowedLlmCategories);
            $ozonDecision = supplier_products_db_mcat_guard_decision_against_group($ozonDecision, 'ozon', $group);
            $wbDecision = supplier_products_db_mcat_guard_decision_against_group($wbDecision, 'wildberries', $group);
            if (!empty($ozonDecision['rejected_category'])) {
                $groupReport['rejected_llm_out_of_candidates_ozon'] = $ozonRejectedCategory;
                $report['summary']['rejected_llm_out_of_candidates_ozon']++;
            }
            if (!empty($wbDecision['rejected_category'])) {
                $groupReport['rejected_llm_out_of_candidates_wb'] = $wbRejectedCategory;
                $report['summary']['rejected_llm_out_of_candidates_wb']++;
            }
            $groupReport['status'] = $strategy === 'group' ? 'ok' : 'needs_review';
            $groupReport['strategy'] = $strategy;
            $groupReport['ozon'] = $ozonDecision;
            $groupReport['wildberries'] = $wbDecision;
            $groupReport['review_note'] = acp_trunc((string)($decoded['review_note'] ?? ''), 300);

            $resolvedOzon = $ozonHandledByMemory ? $ozonMemoryDecision : ($ozonDecision + ['source' => 'llm']);
            $resolvedWb = $wbHandledByMemory ? $wbMemoryDecision : ($wbDecision + ['source' => 'llm']);
            if (!supplier_products_db_mcat_category_is_valid('ozon', (string)($resolvedOzon['category'] ?? '')) || (float)($resolvedOzon['confidence'] ?? 0) < $autoConfidence) {
                if ((float)($ozonMemoryDecision['confidence'] ?? 0) >= $autoConfidence) {
                    $resolvedOzon = $ozonMemoryDecision;
                } elseif ((float)($ozonMajority['confidence'] ?? 0) >= $autoConfidence) {
                    $resolvedOzon = $ozonMajority;
                }
            }
            if (!supplier_products_db_mcat_category_is_valid('wildberries', (string)($resolvedWb['category'] ?? '')) || (float)($resolvedWb['confidence'] ?? 0) < $autoConfidence) {
                if ((float)($wbMemoryDecision['confidence'] ?? 0) >= $autoConfidence) {
                    $resolvedWb = $wbMemoryDecision;
                } elseif ((float)($wbMajority['confidence'] ?? 0) >= $autoConfidence) {
                    $resolvedWb = $wbMajority;
                }
            }
            $needsVerificationOzon = $verifyDecisions
                && $strategy === 'group'
                && !$ozonHandledByMemory
                && (($resolvedOzon['source'] ?? '') === 'llm')
                && supplier_products_db_mcat_category_is_valid('ozon', (string)($resolvedOzon['category'] ?? ''))
                && (float)($resolvedOzon['confidence'] ?? 0) >= $autoConfidence;
            $needsVerificationWb = $verifyDecisions
                && $strategy === 'group'
                && !$wbHandledByMemory
                && (($resolvedWb['source'] ?? '') === 'llm')
                && supplier_products_db_mcat_category_is_valid('wildberries', (string)($resolvedWb['category'] ?? ''))
                && (float)($resolvedWb['confidence'] ?? 0) >= $autoConfidence;
            if ($needsVerificationOzon || $needsVerificationWb) {
                try {
                    $verifyRequest = [
                        'mode' => 'verify_category_decision',
                        'supplier_group' => [
                            'supplier_category_id' => (string)($group['supplier_category_id'] ?? ''),
                            'supplier_category_path' => (string)($group['supplier_category_path'] ?? ''),
                            'profile' => supplier_products_db_mcat_compact_profile((array)($group['profile'] ?? [])),
                            'role_analysis' => $roleAnalysis,
                            'products_total' => (int)($group['products_total'] ?? 0),
                            'products_sample' => supplier_products_db_mcat_group_prompt_sample($group, min($llmProductsPerGroup, 14)),
                        ],
                        'decisions' => [
                            'ozon' => $needsVerificationOzon ? $resolvedOzon : (object)[],
                            'wildberries' => $needsVerificationWb ? $resolvedWb : (object)[],
                        ],
                        'alternatives' => [
                            'ozon' => $needsVerificationOzon ? supplier_products_db_mcat_verifier_candidates($ozonCandidatesForLlm, $resolvedOzon, 14) : [],
                            'wildberries' => $needsVerificationWb ? supplier_products_db_mcat_verifier_candidates($wbCandidatesForLlm, $resolvedWb, 14) : [],
                        ],
                        'instruction' => 'Проверь выбранные категории независимо. Одобряй только если товарная роль, объект применения, путь поставщика и leaf-категория согласуются. Если есть более точная альтернатива из списка, верни approved=false и better_category.',
                    ];
                    $verifyJson = json_encode($verifyRequest, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                    if ($verifyJson === false) {
                        $verifyJson = '{"mode":"verify_category_decision"}';
                    }
                    $verifyUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $verifyJson;
                    $verifyMaxOutputTokens = 1000;
                    $verifyEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $verifyUserMessage, $verifyMaxOutputTokens, 0.5);
                    $estimatedRequests++;
                    $estimatedInputTokensTotal += (int)$verifyEstimate['input_tokens'];
                    $estimatedExpectedOutputTokensTotal += (int)$verifyEstimate['expected_output_tokens'];
                    $estimatedMaxOutputTokensTotal += (int)$verifyEstimate['max_output_tokens'];
                    $estimatedExpectedCostTotal += (float)$verifyEstimate['expected_cost'];
                    $estimatedMaxCostTotal += (float)$verifyEstimate['max_cost'];
                    $report['summary']['verification_requests']++;
                    $groupReport['verification_estimate'] = $verifyEstimate;

                    $llmAttempts++;
                    $verifyRes = $client->generateText($model, $verifyUserMessage, $prompt, [
                        'prompt_cache_key' => 'assign_mcat_verify:' . substr(hash('sha256', json_encode([
                            'supplier_category_path' => $group['supplier_category_path'] ?? '',
                            'profile' => supplier_products_db_mcat_compact_profile((array)($group['profile'] ?? [])),
                            'role_analysis' => $roleAnalysis,
                            'ozon' => $needsVerificationOzon ? ($resolvedOzon['category'] ?? '') : '',
                            'wb' => $needsVerificationWb ? ($resolvedWb['category'] ?? '') : '',
                        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                        'text' => ['format' => ['type' => 'json_object']],
                        'max_output_tokens' => $verifyMaxOutputTokens,
                    ]);
                    $verifyRaw = $verifyRes['raw'] ?? null;
                    $verifyUsage = supplier_products_db_merge_llm_usage_with_estimate(
                        $cfg,
                        $model,
                        is_array($verifyRaw) ? $verifyRaw : null,
                        $prompt,
                        $verifyUserMessage,
                        (string)($verifyRes['output_text'] ?? ''),
                        $verifyMaxOutputTokens
                    );
                    $tokensInTotal += (int)$verifyUsage['input'];
                    $tokensOutTotal += (int)$verifyUsage['output'];
                    $tokensCachedTotal += (int)$verifyUsage['cached_input'];
                    $costUsdTotal += (float)$verifyUsage['cost'];
                    if (!empty($verifyUsage['estimated'])) {
                        $usageEstimatedRequests++;
                    }
                    $groupReport['verification_actual_usage'] = $verifyUsage;
                    $verifyDecoded = supplier_products_db_extract_json_object((string)($verifyRes['output_text'] ?? ''));
                    if ($needsVerificationOzon) {
                        $ozonVerification = supplier_products_db_mcat_verification_decision($verifyDecoded, 'ozon');
                        $resolvedOzon = supplier_products_db_mcat_apply_verification_to_decision($resolvedOzon, $ozonVerification, 'ozon', $verificationConfidence);
                        $groupReport['verification_ozon'] = $ozonVerification;
                        if (!empty($resolvedOzon['verification_rejected'])) {
                            $report['summary']['verification_rejected_ozon']++;
                        } elseif (!empty($resolvedOzon['verification_approved'])) {
                            $report['summary']['verification_approved_ozon']++;
                        }
                    }
                    if ($needsVerificationWb) {
                        $wbVerification = supplier_products_db_mcat_verification_decision($verifyDecoded, 'wildberries');
                        $resolvedWb = supplier_products_db_mcat_apply_verification_to_decision($resolvedWb, $wbVerification, 'wildberries', $verificationConfidence);
                        $groupReport['verification_wb'] = $wbVerification;
                        if (!empty($resolvedWb['verification_rejected'])) {
                            $report['summary']['verification_rejected_wb']++;
                        } elseif (!empty($resolvedWb['verification_approved'])) {
                            $report['summary']['verification_approved_wb']++;
                        }
                    }
                } catch (Throwable $e) {
                    $report['summary']['verification_errors']++;
                    $groupReport['verification_error'] = $e->getMessage();
                    $log("assign category verification skipped group {$done}: " . $e->getMessage() . "\n");
                }
            }
            $groupReport['resolved_ozon'] = $resolvedOzon;
            $groupReport['resolved_wb'] = $resolvedWb;

            $hasHighConfidenceSide =
                ($wantOzon && supplier_products_db_mcat_decision_applicable($resolvedOzon, 'ozon', $autoConfidence, $strategy))
                || ($wantWb && supplier_products_db_mcat_decision_applicable($resolvedWb, 'wildberries', $autoConfidence, $strategy));
            $hasUnresolvedNeededSide =
                ($wantOzon
                    && $needsOzonCategory
                    && !supplier_products_db_mcat_decision_applicable($resolvedOzon, 'ozon', $autoConfidence, $strategy))
                || ($wantWb
                    && $needsWbCategory
                    && !supplier_products_db_mcat_decision_applicable($resolvedWb, 'wildberries', $autoConfidence, $strategy));
            $needsReview = $strategy !== 'group';
            if ($apply) {
                supplier_products_db_mcat_apply_group_category_decisions(
                    $pdo,
                    $supplierId,
                    $group,
                    $productById,
                    $fieldsByProduct,
                    $resolvedOzon,
                    $resolvedWb,
                    $wantOzon && !$ozonHandledByMemory,
                    $wantWb && !$wbHandledByMemory,
                    $overwrite,
                    $autoConfidence,
                    $strategy,
                    $changedProductIds,
                    $assignedCategoryByProduct,
                    $groupReport,
                    $report['summary']
                );
            }

            $shouldFallback = $productFallback
                && $maxProductFallbackPerGroup > 0
                && (($strategy !== 'group') || $hasUnresolvedNeededSide)
                && ($ozonCandidatesForLlm || $wbCandidatesForLlm);
            if ($shouldFallback && $apply) {
                $needsOzonFallback = $wantOzon
                    && (bool)$ozonLlmCandidates
                    && !supplier_products_db_mcat_decision_applicable($resolvedOzon, 'ozon', $autoConfidence, $strategy);
                $needsWbFallback = $wantWb
                    && (bool)$wbLlmCandidates
                    && !supplier_products_db_mcat_decision_applicable($resolvedWb, 'wildberries', $autoConfidence, $strategy);
                $fallbackMeta = supplier_products_db_mcat_fallback_ids(
                    $group,
                    $productById,
                    $fieldsByProduct,
                    $assignedCategoryByProduct,
                    $wantOzon,
                    $wantWb,
                    $overwrite,
                    $needsOzonFallback,
                    $needsWbFallback
                );
                $fallbackIds = array_slice(array_map('intval', (array)($fallbackMeta['ids'] ?? [])), 0, $maxProductFallbackPerGroup);
                $groupReport['product_fallback_candidate_products'] = count($fallbackIds);
                $report['summary']['fallback_candidate_products'] += count($fallbackIds);
                if (!$fallbackIds) {
                    $report['summary']['fallback_skipped_no_remaining_products']++;
                }
                foreach (array_chunk($fallbackIds, $fallbackChunkSize) as $chunkIdx => $chunkIds) {
                    $productPayloads = supplier_products_db_mcat_product_payloads($chunkIds, $productById, $fieldsByProduct);
                    if (!$productPayloads) {
                        continue;
                    }
                    $fallbackNeedOzon = !empty($fallbackMeta['need_ozon']);
                    $fallbackNeedWb = !empty($fallbackMeta['need_wb']);
                    $fallbackRequest = [
                        'mode' => 'product_fallback',
                        'supplier_group' => [
                            'supplier_category_id' => (string)($group['supplier_category_id'] ?? ''),
                            'supplier_category_path' => (string)($group['supplier_category_path'] ?? ''),
                            'profile' => supplier_products_db_mcat_compact_profile((array)($group['profile'] ?? [])),
                            'role_analysis' => $roleAnalysis,
                            'products_total' => (int)($group['products_total'] ?? 0),
                            'existing_ozon_categories' => array_slice((array)($group['existing_ozon'] ?? []), 0, 8, true),
                            'existing_wb_categories' => array_slice((array)($group['existing_wb'] ?? []), 0, 8, true),
                            'instruction' => 'Определи категорию отдельно для каждого товара. Категория поставщика и соседние товары являются контекстом, но не истиной: если конкретный товар им противоречит, выбирай по названию, характеристикам и описанию самого товара.',
                        ],
                        'products' => $productPayloads,
                        'marketplaces' => [
                            'ozon' => [
                                'need_fill_count' => $fallbackNeedOzon ? (int)($fallbackMeta['need_ozon_count'] ?? 0) : 0,
                                'supplier_category_memory' => supplier_products_db_mcat_compact_memory($ozonMemory),
                                'candidates' => $fallbackNeedOzon ? $ozonLlmCandidates : [],
                            ],
                            'wildberries' => [
                                'need_fill_count' => $fallbackNeedWb ? (int)($fallbackMeta['need_wb_count'] ?? 0) : 0,
                                'supplier_category_memory' => supplier_products_db_mcat_compact_memory($wbMemory),
                                'candidates' => $fallbackNeedWb ? $wbLlmCandidates : [],
                            ],
                        ],
                    ];
                    $fallbackJson = json_encode($fallbackRequest, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                    if ($fallbackJson === false) {
                        continue;
                    }
                    $fallbackUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $fallbackJson;
                    $fallbackMaxOutputTokens = max(1400, min(4200, 700 + (count($productPayloads) * 230)));
                    $fallbackEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $fallbackUserMessage, $fallbackMaxOutputTokens, 0.55);
                    $estimatedRequests++;
                    $estimatedInputTokensTotal += (int)$fallbackEstimate['input_tokens'];
                    $estimatedExpectedOutputTokensTotal += (int)$fallbackEstimate['expected_output_tokens'];
                    $estimatedMaxOutputTokensTotal += (int)$fallbackEstimate['max_output_tokens'];
                    $estimatedExpectedCostTotal += (float)$fallbackEstimate['expected_cost'];
                    $estimatedMaxCostTotal += (float)$fallbackEstimate['max_cost'];
                    $groupReport['product_fallback_estimates'][] = [
                        'chunk' => (int)$chunkIdx + 1,
                        'products' => count($productPayloads),
                        'estimate' => $fallbackEstimate,
                    ];

                    $llmAttempts++;
                    $fallbackRes = $client->generateText($model, $fallbackUserMessage, $prompt, [
                        'prompt_cache_key' => 'assign_mcat_pf:' . substr(hash('sha256', json_encode([
                            'supplier_category_path' => $group['supplier_category_path'] ?? '',
                            'profile' => supplier_products_db_mcat_compact_profile((array)($group['profile'] ?? [])),
                            'chunk' => $chunkIds,
                            'ozon_memory' => array_column($ozonMemory, 'category'),
                            'wb_memory' => array_column($wbMemory, 'category'),
                            'ozon_candidates' => $fallbackNeedOzon ? supplier_products_db_mcat_llm_candidate_categories($ozonLlmCandidates) : [],
                            'wb_candidates' => $fallbackNeedWb ? supplier_products_db_mcat_llm_candidate_categories($wbLlmCandidates) : [],
                        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                        'text' => ['format' => ['type' => 'json_object']],
                        'max_output_tokens' => $fallbackMaxOutputTokens,
                    ]);
                    $fallbackRaw = $fallbackRes['raw'] ?? null;
                    $fallbackUsage = supplier_products_db_merge_llm_usage_with_estimate(
                        $cfg,
                        $model,
                        is_array($fallbackRaw) ? $fallbackRaw : null,
                        $prompt,
                        $fallbackUserMessage,
                        (string)($fallbackRes['output_text'] ?? ''),
                        $fallbackMaxOutputTokens
                    );
                    $tokensInTotal += (int)$fallbackUsage['input'];
                    $tokensOutTotal += (int)$fallbackUsage['output'];
                    $tokensCachedTotal += (int)$fallbackUsage['cached_input'];
                    $costUsdTotal += (float)$fallbackUsage['cost'];
                    if (!empty($fallbackUsage['estimated'])) {
                        $usageEstimatedRequests++;
                    }
                    $groupReport['product_fallback_actual_usage'][] = [
                        'chunk' => (int)$chunkIdx + 1,
                        'usage' => $fallbackUsage,
                    ];
                    $fallbackDecoded = supplier_products_db_extract_json_object((string)($fallbackRes['output_text'] ?? ''));
                    $groupReport['product_fallback_chunks'] = (int)($groupReport['product_fallback_chunks'] ?? 0) + 1;

                    $ozonProductDecisions = $fallbackNeedOzon ? supplier_products_db_mcat_product_decisions($fallbackDecoded, 'ozon') : [];
                    $wbProductDecisions = $fallbackNeedWb ? supplier_products_db_mcat_product_decisions($fallbackDecoded, 'wildberries') : [];
                    foreach ($chunkIds as $productId) {
                        $productId = (int)$productId;
                        if ($productId <= 0) {
                            continue;
                        }
                        $fields = $fieldsByProduct[$productId] ?? [];
                        $productStub = $productById[$productId] ?? ['ozon_category' => '', 'wb_category' => ''];
                        $decision = $ozonProductDecisions[$productId] ?? null;
                        if (is_array($decision)) {
                            $before = (string)($decision['category'] ?? '');
                            $decision = supplier_products_db_mcat_guard_llm_decision($decision, 'ozon', $ozonAllowedLlmCategories);
                            $decision = supplier_products_db_mcat_guard_decision_against_product($decision, 'ozon', $productStub, $fields);
                            if (!empty($decision['rejected_category'])) {
                                $groupReport['rejected_product_fallback_out_of_candidates_ozon'] = (int)($groupReport['rejected_product_fallback_out_of_candidates_ozon'] ?? 0) + 1;
                                $report['summary']['rejected_llm_out_of_candidates_ozon']++;
                                $log("assign category fallback rejected ozon category outside candidates: product={$productId}, category={$before}\n");
                            }
                        }
                        if (empty($assignedCategoryByProduct[$productId]['ozon'])
                            && is_array($decision)
                            && supplier_products_db_mcat_category_is_valid('ozon', (string)($decision['category'] ?? ''))
                            && (float)($decision['confidence'] ?? 0) >= $fallbackConfidence
                        ) {
                            if (supplier_products_db_mcat_apply_category_decision($pdo, $supplierId, $productId, $productStub, $fields, 'ozon', (string)$decision['category'], $overwrite)) {
                                $changedProductIds[$productId] = true;
                                $assignedCategoryByProduct[$productId]['ozon'] = true;
                                $groupReport['applied_ozon']++;
                                $groupReport['applied_from_product_fallback_ozon']++;
                                $report['summary']['applied_ozon']++;
                                $report['summary']['applied_from_product_fallback_ozon']++;
                            }
                        }
                        $decision = $wbProductDecisions[$productId] ?? null;
                        if (is_array($decision)) {
                            $before = (string)($decision['category'] ?? '');
                            $decision = supplier_products_db_mcat_guard_llm_decision($decision, 'wildberries', $wbAllowedLlmCategories);
                            $decision = supplier_products_db_mcat_guard_decision_against_product($decision, 'wildberries', $productStub, $fields);
                            if (!empty($decision['rejected_category'])) {
                                $groupReport['rejected_product_fallback_out_of_candidates_wb'] = (int)($groupReport['rejected_product_fallback_out_of_candidates_wb'] ?? 0) + 1;
                                $report['summary']['rejected_llm_out_of_candidates_wb']++;
                                $log("assign category fallback rejected wb category outside candidates: product={$productId}, category={$before}\n");
                            }
                        }
                        if (empty($assignedCategoryByProduct[$productId]['wildberries'])
                            && is_array($decision)
                            && supplier_products_db_mcat_category_is_valid('wildberries', (string)($decision['category'] ?? ''))
                            && (float)($decision['confidence'] ?? 0) >= $fallbackConfidence
                        ) {
                            if (supplier_products_db_mcat_apply_category_decision($pdo, $supplierId, $productId, $productStub, $fields, 'wildberries', (string)$decision['category'], $overwrite)) {
                                $changedProductIds[$productId] = true;
                                $assignedCategoryByProduct[$productId]['wildberries'] = true;
                                $groupReport['applied_wb']++;
                                $groupReport['applied_from_product_fallback_wb']++;
                                $report['summary']['applied_wb']++;
                                $report['summary']['applied_from_product_fallback_wb']++;
                            }
                        }
                    }
                    $log("assign category fallback group {$done}, chunk " . ((int)$chunkIdx + 1) . ': products=' . count($productPayloads) . ", ozon_decisions=" . count($ozonProductDecisions) . ", wb_decisions=" . count($wbProductDecisions) . "\n");
                }
            }

            $fallbackAppliedInGroup = (($groupReport['applied_from_product_fallback_ozon'] ?? 0) > 0 || ($groupReport['applied_from_product_fallback_wb'] ?? 0) > 0);
            if ($hasUnresolvedNeededSide && !$fallbackAppliedInGroup) {
                $groupReport['status'] = $groupReport['status'] === 'ok' ? 'needs_review_partial_low_confidence' : $groupReport['status'];
                $needsReview = true;
            } elseif (!$hasHighConfidenceSide && $groupReport['applied_ozon'] <= 0 && $groupReport['applied_wb'] <= 0) {
                $groupReport['status'] = $groupReport['status'] === 'ok' ? 'needs_review_low_confidence' : $groupReport['status'];
                $needsReview = true;
            } elseif ($fallbackAppliedInGroup) {
                $groupReport['status'] = 'ok_product_fallback';
                $needsReview = false;
            } elseif (($groupReport['applied_from_supplier_category_memory_ozon'] ?? 0) > 0 || ($groupReport['applied_from_supplier_category_memory_wb'] ?? 0) > 0) {
                $groupReport['status'] = 'ok_supplier_category_memory';
                $needsReview = false;
            } elseif (($groupReport['applied_from_existing_majority_ozon'] ?? 0) > 0 || ($groupReport['applied_from_existing_majority_wb'] ?? 0) > 0) {
                $groupReport['status'] = 'ok_existing_majority';
                $needsReview = false;
            }
            if ($needsReview) {
                $report['summary']['review_groups']++;
            }
        } catch (Throwable $e) {
            $llmErrors++;
            if ($firstLlmError === '') {
                $firstLlmError = $e->getMessage();
            }
            $report['summary']['error_groups']++;
            $groupReport['status'] = 'error';
            $groupReport['error'] = $e->getMessage();
            $log("ERROR assign category group {$done}: " . $e->getMessage() . "\n");
        }

        $report['groups'][] = $groupReport;
    }

    supplier_products_db_fail_if_llm_unavailable(
        'gpt_assign_marketplace_categories',
        $llmAttempts,
        $llmErrors,
        $tokensInTotal,
        $tokensOutTotal,
        $firstLlmError
    );

    $changedIds = array_keys($changedProductIds);
    $report['summary']['applied_products'] = count($changedIds);
    $costUsdTotal = round($costUsdTotal, 6);
    $estimatedExpectedCostTotal = round($estimatedExpectedCostTotal, 6);
    $estimatedMaxCostTotal = round($estimatedMaxCostTotal, 6);
    $report['summary']['gpt_requests_estimated'] = $estimatedRequests;
    $report['summary']['gpt_requests_sent'] = $llmAttempts;
    $report['summary']['gpt_requests_usage_estimated'] = $usageEstimatedRequests;
    $report['summary']['gpt_requests_skipped_by_memory'] = $memorySkippedRequests;
    $report['summary']['usage'] = [
        'input_tokens' => $tokensInTotal,
        'cached_input_tokens' => $tokensCachedTotal,
        'output_tokens' => $tokensOutTotal,
    ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal);
    $report['summary']['estimated_usage'] = [
        'requests' => $estimatedRequests,
        'input_tokens' => $estimatedInputTokensTotal,
        'cached_input_tokens' => 0,
        'expected_output_tokens' => $estimatedExpectedOutputTokensTotal,
        'max_output_tokens' => $estimatedMaxOutputTokensTotal,
        'expected_cost' => $estimatedExpectedCostTotal,
        'expected_cost_currency' => openai_cost_currency_for_model($cfg, $model),
        'expected_cost_label' => supplier_products_db_cost_label($cfg, $model, $estimatedExpectedCostTotal),
        'max_cost' => $estimatedMaxCostTotal,
        'max_cost_currency' => openai_cost_currency_for_model($cfg, $model),
        'max_cost_label' => supplier_products_db_cost_label($cfg, $model, $estimatedMaxCostTotal),
    ];
    $report['summary']['tokens_in'] = $tokensInTotal;
    $report['summary']['tokens_cached_in'] = $tokensCachedTotal;
    $report['summary']['tokens_out'] = $tokensOutTotal;
    $report['summary']['cost_usd'] = $costUsdTotal;
    $report['summary']['cost_label'] = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);

    if ($changedIds) {
        supplier_products_db_finish_changed_products($supplierId, $changedIds, $cfg, $opId);
    } else {
        ops_update_progress($opId, 100, 100, 'done', 'No confident category changes');
    }

    $log("assign categories done: groups={$totalGroups}, changed_products=" . count($changedIds) . ", ozon={$report['summary']['applied_ozon']}, wb={$report['summary']['applied_wb']}\n");
    $log("TOTAL usage: input={$tokensInTotal}, cached_input={$tokensCachedTotal}, output={$tokensOutTotal}\n");
    $log("ESTIMATED launch usage: requests={$estimatedRequests}, input={$estimatedInputTokensTotal}, expected_output={$estimatedExpectedOutputTokensTotal}, max_output={$estimatedMaxOutputTokensTotal}\n");
    $log("ESTIMATED launch cost ({$model}): expected=" . supplier_products_db_cost_label($cfg, $model, $estimatedExpectedCostTotal) . ', max=' . supplier_products_db_cost_label($cfg, $model, $estimatedMaxCostTotal) . "\n");
    $log("TOTAL cost ({$model}): " . supplier_products_db_cost_label($cfg, $model, $costUsdTotal) . "\n");

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_assign_marketplace_categories',
        'items' => [
            'Products seen: ' . count($products),
            'Groups total: ' . $totalGroups,
            'GPT requests sent: ' . $llmAttempts,
            'GPT requests estimated: ' . $estimatedRequests,
            'GPT requests skipped by memory: ' . $memorySkippedRequests,
            'Role analysis requests: ' . (int)$report['summary']['role_analysis_requests'],
            'Verification requests: ' . (int)$report['summary']['verification_requests'],
            'Verification rejected Ozon: ' . (int)$report['summary']['verification_rejected_ozon'],
            'Verification rejected WB: ' . (int)$report['summary']['verification_rejected_wb'],
            'Applied products: ' . count($changedIds),
            'Applied Ozon: ' . (int)$report['summary']['applied_ozon'],
            'Applied WB: ' . (int)$report['summary']['applied_wb'],
            'Tokens in: ' . $tokensInTotal,
            'Tokens cached in: ' . $tokensCachedTotal,
            'Tokens out: ' . $tokensOutTotal,
            'Actual cost: ' . supplier_products_db_cost_label($cfg, $model, $costUsdTotal),
            'Estimated launch expected cost: ' . supplier_products_db_cost_label($cfg, $model, $estimatedExpectedCostTotal),
            'Estimated launch max cost: ' . supplier_products_db_cost_label($cfg, $model, $estimatedMaxCostTotal),
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_gpt_fill_offer_params(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = supplier_products_db_fill_offer_params_prompt(
        $cfg,
        $model,
        PromptTemplates::load(__DIR__ . '/llm/prompts', 'fill_offer_params_ru.txt')
    );
    $log("supplier_db gpt_fill_offer_params: model={$model}, max_items={$maxItems}\n");
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));

    $jobs = [];
    $seenProducts = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');

        $marketplaceContexts = [];
        $ozonCtx = supplier_products_db_load_attr_category('ozon', $ozonCategory, $cfg);
        if ($ozonCtx && !empty($ozonCtx['category_attributes'])) {
            $marketplaceContexts[] = $ozonCtx;
        }
        $wbCtx = supplier_products_db_load_attr_category('wildberries', $wbCategory, $cfg);
        if ($wbCtx && !empty($wbCtx['category_attributes'])) {
            $marketplaceContexts[] = $wbCtx;
        }
        if (!$marketplaceContexts) {
            continue;
        }
        $llmMarketplaceContexts = [];
        foreach ($marketplaceContexts as $ctx) {
            if (is_array($ctx)) {
                $llmMarketplaceContexts[] = supplier_products_db_llm_attr_context($ctx);
            }
        }
        $llmMarketplaceContexts = array_values(array_filter(
            $llmMarketplaceContexts,
            static fn(array $ctx): bool => !empty($ctx['category_attributes'])
        ));
        if (!$llmMarketplaceContexts) {
            continue;
        }

        $standardValues = [
            'length' => trim((string)($product['length'] ?? '')),
            'width' => trim((string)($product['width'] ?? '')),
            'height' => trim((string)($product['height'] ?? '')),
            'weight' => trim((string)($product['weight'] ?? '')),
        ];
        foreach ($fields as $field) {
            if ((string)($field['field_kind'] ?? '') !== 'standard') {
                continue;
            }
            $name = trim((string)($field['field_name'] ?? ''));
            if (!array_key_exists($name, $standardValues)) {
                continue;
            }
            $value = trim((string)($field['field_value'] ?? ''));
            if ($value !== '') {
                $standardValues[$name] = $value;
            }
        }

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $productPrompt = [
            'offer_id' => $offerId,
            'vendorCode' => (string)($product['vendor_code'] ?? ''),
            'name' => (string)($product['name'] ?? ''),
            'source_line' => (string)(($product['name'] ?? '') ?: (($product['vendor_code'] ?? '') ?: ($context['model'] ?? ''))),
            'brand' => (string)($context['brand'] ?? ($product['brand'] ?? '')),
            'vendor' => (string)($context['vendor'] ?? ''),
            'model' => (string)($context['model'] ?? ''),
            'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 2200),
            'params' => supplier_products_db_product_params_payload($fields),
            'pictures' => array_slice(supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null)), 0, 3),
        ];

        $existingParams = [];
        $existingNonempty = ['ozon' => [], 'wildberries' => []];
        $existingValuesByNorm = ['param' => [], 'wb_param' => []];
        $forcedOzonFitsForRows = [];
        foreach ($fields as $field) {
            $kind = (string)($field['field_kind'] ?? '');
            if ($kind !== 'param' && $kind !== 'wb_param') {
                continue;
            }
            $name = trim((string)($field['field_name'] ?? ''));
            $value = trim((string)($field['field_value'] ?? ''));
            if ($name === '') {
                continue;
            }
            $nameNorm = supplier_products_db_attr_norm($name);
            if ($nameNorm !== '' && !isset($existingValuesByNorm[$kind][$nameNorm])) {
                $existingValuesByNorm[$kind][$nameNorm] = $value;
            }
            if ($value === '') {
                continue;
            }
            $source = $kind === 'wb_param' ? 'wildberries' : 'ozon';
            if (supplier_products_db_is_ozon_fits_for_attribute($source, $name)) {
                $normalizedFitsFor = supplier_products_db_normalize_ozon_fits_for_brands([$value], $productPrompt, $ozonCategory);
                $normalizedFitsForValue = supplier_products_db_join_ozon_fits_for_values($normalizedFitsFor);
                if ($normalizedFitsForValue !== '' && supplier_products_db_attr_norm($normalizedFitsForValue) !== supplier_products_db_attr_norm($value)) {
                    $forcedOzonFitsForRows[$kind . "\n" . $nameNorm] = [
                        'marketplace' => 'ozon',
                        'kind' => 'param',
                        'name' => $name,
                        'value' => $normalizedFitsForValue,
                        'forced_ozon_fits_for' => true,
                    ];
                }
            }
            $existingParams[] = [
                'marketplace' => $source,
                'name' => $name,
                'value' => $value,
            ];
            if ($nameNorm !== '') {
                $existingNonempty[$source][$nameNorm] = true;
            }
        }
        foreach ($marketplaceContexts as &$ctx) {
            $src = (string)($ctx['source'] ?? '');
            $ctx['existing_params'] = array_values(array_filter(
                $existingParams,
                static fn(array $row): bool => (string)($row['marketplace'] ?? '') === $src
            ));
        }
        unset($ctx);

        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'ozon_category' => $ozonCategory,
            'existing_nonempty' => $existingNonempty,
            'existing_values_by_norm' => $existingValuesByNorm,
            'forced_ozon_fits_for_rows' => array_values($forcedOzonFitsForRows),
            'detected_unit_quantity' => supplier_products_db_detect_unit_quantity_from_product($product, $fields),
            'source_fields' => $fields,
            'standard' => $standardValues,
            'product' => $productPrompt,
            'marketplace_contexts' => $marketplaceContexts,
            'llm_marketplace_contexts' => $llmMarketplaceContexts,
            'category_attributes' => supplier_products_db_merge_category_attrs($llmMarketplaceContexts),
            'existing_params' => $existingParams,
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 250 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log("scan: products_seen={$seenProducts}, jobs=" . count($jobs) . "\n");

    $perOffer = [];
    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $done = 0;
    $firstLlmError = '';
    $gptTotal = max(1, count($jobs));
    $client = count($jobs) > 0 ? LLM::client($cfg, $model) : null;

    foreach ($jobs as $offerId => $job) {
        $done++;
        ops_update_progress($opId, $done, $gptTotal, 'gpt', "GPT {$done}/{$gptTotal} offer={$offerId}");

        $attrLookup = ['ozon' => [], 'wildberries' => []];
        $attrTargetsByKey = [];
        foreach ((array)($job['llm_marketplace_contexts'] ?? []) as $ctx) {
            $src = (string)($ctx['source'] ?? '');
            if (!isset($attrLookup[$src])) {
                continue;
            }
            foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
                $name = trim((string)($attr['name'] ?? ''));
                if ($name === '') {
                    continue;
                }
                foreach (supplier_products_db_attr_candidate_keys($name) as $key) {
                    if ($key !== '' && !isset($attrLookup[$src][$key])) {
                        $attrLookup[$src][$key] = $attr;
                    }
                    if ($key !== '') {
                        $targetKind = $src === 'wildberries' ? 'wb_param' : 'param';
                        $targetKey = $targetKind . "\n" . supplier_products_db_attr_norm($name);
                        $attrTargetsByKey[$key][$targetKey] = [
                            'source' => $src,
                            'kind' => $targetKind,
                            'name' => $name,
                            'attr' => $attr,
                        ];
                    }
                }
            }
        }

        $promptContexts = [];
        foreach ((array)($job['llm_marketplace_contexts'] ?? []) as $ctx) {
            if (is_array($ctx)) {
                $promptContexts[] = $ctx;
            }
        }

        $payload = [
            // Prompt caching works on identical prefixes, so keep the large
            // per-category context before the per-product data.
            'marketplace_contexts' => $promptContexts,
            'category_attributes' => [],
            'product' => $job['product'] ?? [],
            'existing_params' => $job['existing_params'] ?? [],
        ];
        $inputJson = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($inputJson === false) {
            $inputJson = '{"product":{},"marketplace_contexts":[]}';
        }

        $status = 'ok';
        $error = '';
        $accepted = [];
        $vendor = '';
        $usage = ['input' => 0, 'cached_input' => 0, 'output' => 0];
        $rawText = '';

        try {
            $res = $client->generateText($model, "Return a valid JSON object only.\n\n" . $inputJson, $prompt, [
                'prompt_cache_key' => 'fill_offer_params:' . substr(hash('sha256', json_encode(
                    $payload['marketplace_contexts'] ?? [],
                    JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
                ) ?: ''), 0, 48),
                'text' => ['format' => ['type' => 'json_object']],
            ]);
            $rawText = (string)($res['output_text'] ?? '');
            $usage = supplier_products_db_extract_openai_usage(is_array($res['raw'] ?? null) ? $res['raw'] : null);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += openai_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);

            $obj = supplier_products_db_extract_json_object($rawText);
            $vendor = trim((string)($obj['vendor'] ?? ''));
            foreach ((array)($obj['params'] ?? []) as $row) {
                if (!is_array($row)) {
                    continue;
                }
                $source = trim((string)($row['marketplace'] ?? ''));
                if ($source === 'wb') {
                    $source = 'wildberries';
                }
                if ($source !== 'ozon' && $source !== 'wildberries') {
                    continue;
                }
                $name = trim((string)($row['name'] ?? ''));
                $nameKey = supplier_products_db_attr_norm($name);
                if ($nameKey === '' || empty($attrLookup[$source][$nameKey])) {
                    continue;
                }
                $values = [];
                if (isset($row['values']) && is_array($row['values'])) {
                    $values = $row['values'];
                } else {
                    $values = [$row['value'] ?? ''];
                }
                $targets = [];
                foreach (supplier_products_db_attr_candidate_keys($name) as $candidateKey) {
                    foreach ((array)($attrTargetsByKey[$candidateKey] ?? []) as $targetKey => $target) {
                        if (is_array($target)) {
                            $targets[$targetKey] = $target;
                        }
                    }
                }
                if (!$targets) {
                    $attr = $attrLookup[$source][$nameKey];
                    $targetKind = $source === 'wildberries' ? 'wb_param' : 'param';
                    $targets[$targetKind . "\n" . supplier_products_db_attr_norm((string)($attr['name'] ?? $name))] = [
                        'source' => $source,
                        'kind' => $targetKind,
                        'name' => (string)($attr['name'] ?? $name),
                        'attr' => $attr,
                    ];
                }
                foreach ($values as $value) {
                    foreach ($targets as $target) {
                        if (!is_array($target)) {
                            continue;
                        }
                        $targetSource = (string)($target['source'] ?? '');
                        $targetName = (string)($target['name'] ?? '');
                        $targetNameKey = supplier_products_db_attr_norm($targetName);
                        if (supplier_products_db_gpt_offer_params_excluded_attr($targetName)) {
                            continue;
                        }
                        if ($targetSource === '' || $targetNameKey === '' || !empty($job['existing_nonempty'][$targetSource][$targetNameKey])) {
                            continue;
                        }
                        $valueCandidates = [(string)$value];
                        if (supplier_products_db_is_ozon_fits_for_attribute($targetSource, $targetName)) {
                            $valueCandidates = supplier_products_db_normalize_ozon_fits_for_brands(
                                [(string)$value],
                                (array)($job['product'] ?? []),
                                (string)($job['ozon_category'] ?? ''),
                                $vendor
                            );
                            if (!$valueCandidates) {
                                continue;
                            }
                        } elseif (supplier_products_db_is_ozon_compatible_models_attribute($targetSource, $targetName)) {
                            $valueCandidates = [];
                            foreach (preg_split('~\s*(?:;|\||\R)\s*~u', (string)$value, -1, PREG_SPLIT_NO_EMPTY) ?: [(string)$value] as $part) {
                                $cleanModel = supplier_products_db_ozon_clean_compatible_model_value(
                                    (string)$part,
                                    supplier_products_db_normalize_ozon_fits_for_brands([], (array)($job['product'] ?? []), (string)($job['ozon_category'] ?? ''), $vendor)
                                );
                                if ($cleanModel !== '') {
                                    $valueCandidates[] = $cleanModel;
                                }
                            }
                            $valueCandidates = array_values(array_unique($valueCandidates));
                            if (!$valueCandidates) {
                                continue;
                            }
                        }
                        foreach ($valueCandidates as $valueForAttr) {
                            $valueForAttr = (string)$valueForAttr;
                            if (supplier_products_db_is_unit_quantity_attribute($targetName)) {
                                $qtyValue = supplier_products_db_unit_quantity_value_number($valueForAttr);
                                if ($qtyValue === null) {
                                    continue;
                                }
                                if (!supplier_products_db_unit_quantity_allowed_for_product(
                                    (array)($job['product'] ?? []),
                                    (array)($job['source_fields'] ?? []),
                                    $qtyValue
                                )) {
                                    continue;
                                }
                                $valueForAttr = (string)$qtyValue;
                            }
                            foreach (supplier_products_db_values_allowed_for_attr($valueForAttr, (array)($target['attr'] ?? [])) as $valueForTarget) {
                                if ($valueForTarget === '') {
                                    continue;
                                }
                                $acceptedKey = $targetSource . "\n" . $targetNameKey . "\n" . supplier_products_db_attr_norm($valueForTarget);
                                if (isset($accepted[$acceptedKey])) {
                                    continue;
                                }
                                $accepted[$acceptedKey] = [
                                    'marketplace' => $targetSource,
                                    'kind' => (string)($target['kind'] ?? ($targetSource === 'wildberries' ? 'wb_param' : 'param')),
                                    'name' => $targetName,
                                    'value' => $valueForTarget,
                                ];
                            }
                        }
                    }
                }
            }
            $accepted = array_values($accepted);
        } catch (Throwable $e) {
            $status = 'error';
            $error = $e->getMessage();
            if ($firstLlmError === '') {
                $firstLlmError = $error;
            }
        }

        $forcedRows = [];
        $forcedRows = array_merge($forcedRows, (array)($job['forced_ozon_fits_for_rows'] ?? []));
        $acceptedTargetKeys = [];
        foreach ($accepted as $row) {
            $acceptedTargetKeys[(string)($row['marketplace'] ?? '') . "\n" . supplier_products_db_attr_norm((string)($row['name'] ?? ''))] = true;
        }
        foreach ((array)($job['marketplace_contexts'] ?? []) as $ctx) {
            if (!is_array($ctx) || (string)($ctx['source'] ?? '') !== 'ozon') {
                continue;
            }
            foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
                if (!is_array($attr)) {
                    continue;
                }
                $targetName = trim((string)($attr['name'] ?? ''));
                $targetNameKey = supplier_products_db_attr_norm($targetName);
                if ($targetName === '' || $targetNameKey === '' || !supplier_products_db_is_ozon_fits_for_attribute('ozon', $targetName)) {
                    continue;
                }
                if (!empty($job['existing_nonempty']['ozon'][$targetNameKey]) || isset($acceptedTargetKeys["ozon\n" . $targetNameKey])) {
                    continue;
                }
                $fallbackValues = supplier_products_db_normalize_ozon_fits_for_brands(
                    [],
                    (array)($job['product'] ?? []),
                    (string)($job['ozon_category'] ?? ''),
                    $vendor
                );
                $fallbackValue = supplier_products_db_join_ozon_fits_for_values($fallbackValues);
                if ($fallbackValue === '') {
                    continue;
                }
                foreach (supplier_products_db_values_allowed_for_attr($fallbackValue, $attr) as $valueForTarget) {
                    if ($valueForTarget === '') {
                        continue;
                    }
                    $forcedRows[] = [
                        'marketplace' => 'ozon',
                        'kind' => 'param',
                        'name' => $targetName,
                        'value' => $valueForTarget,
                        'ozon_fits_for_fallback' => true,
                    ];
                    break;
                }
            }
        }
        foreach ((array)($job['marketplace_contexts'] ?? []) as $ctx) {
            if (!is_array($ctx) || (string)($ctx['source'] ?? '') !== 'ozon') {
                continue;
            }
            foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
                if (!is_array($attr)) {
                    continue;
                }
                $targetName = trim((string)($attr['name'] ?? ''));
                $targetNameKey = supplier_products_db_attr_norm($targetName);
                if ($targetName === '' || $targetNameKey === '' || !supplier_products_db_is_ozon_compatible_models_attribute('ozon', $targetName)) {
                    continue;
                }
                if (!empty($job['existing_nonempty']['ozon'][$targetNameKey]) || isset($acceptedTargetKeys["ozon\n" . $targetNameKey])) {
                    continue;
                }
                foreach (supplier_products_db_ozon_compatible_models_from_product((array)($job['product'] ?? []), (array)($job['source_fields'] ?? [])) as $modelValue) {
                    foreach (supplier_products_db_values_allowed_for_attr($modelValue, $attr) as $valueForTarget) {
                        if ($valueForTarget === '') {
                            continue;
                        }
                        $forcedRows[] = [
                            'marketplace' => 'ozon',
                            'kind' => 'param',
                            'name' => $targetName,
                            'value' => $valueForTarget,
                            'ozon_compatible_model_fallback' => true,
                        ];
                    }
                }
            }
        }
        foreach ((array)($job['marketplace_contexts'] ?? []) as $ctx) {
            if (!is_array($ctx)) {
                continue;
            }
            foreach (supplier_products_db_template_fixed_rows_for_context(
                (string)($ctx['source'] ?? ''),
                $ctx,
                (array)($job['existing_values_by_norm'] ?? [])
            ) as $row) {
                $row['template_fixed'] = true;
                $row['template_mode'] = (string)($row['mode'] ?? 'fill');
                $forcedRows[] = $row;
            }
        }
        $forcedRows = array_merge(
            $forcedRows,
            supplier_products_db_detected_unit_quantity_param_rows($job),
            supplier_products_db_dimension_param_rows($job)
        );
        if ($forcedRows) {
            $forcedTargetKeys = [];
            foreach ($forcedRows as $row) {
                $forcedTargetKeys[(string)($row['kind'] ?? '') . "\n" . supplier_products_db_attr_norm((string)($row['name'] ?? ''))] = true;
            }
            $accepted = array_values(array_filter($accepted, static function (array $row) use ($forcedTargetKeys): bool {
                $key = (string)($row['kind'] ?? '') . "\n" . supplier_products_db_attr_norm((string)($row['name'] ?? ''));
                return !isset($forcedTargetKeys[$key]);
            }));
            $acceptedSeen = [];
            foreach ($accepted as $row) {
                $acceptedSeen[
                    (string)($row['marketplace'] ?? '') . "\n"
                    . supplier_products_db_attr_norm((string)($row['name'] ?? '')) . "\n"
                    . supplier_products_db_attr_norm((string)($row['value'] ?? ''))
                ] = true;
            }
            foreach ($forcedRows as $row) {
                $key = (string)($row['marketplace'] ?? '') . "\n"
                    . supplier_products_db_attr_norm((string)($row['name'] ?? '')) . "\n"
                    . supplier_products_db_attr_norm((string)($row['value'] ?? ''));
                if (!isset($acceptedSeen[$key])) {
                    $acceptedSeen[$key] = true;
                    $accepted[] = $row;
                }
            }
        }

        $perOffer[$offerId] = [
            'product_id' => (int)($job['product_id'] ?? 0),
            'status' => $status,
            'error' => $error,
            'vendor' => $vendor,
            'params' => $accepted,
            'usage' => $usage,
        ];

        file_put_contents(
            $outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'status' => $status,
                'error' => $error,
                'accepted_params' => $accepted,
                'vendor' => $vendor,
                'payload' => $payload,
                'gpt_output_text' => $rawText,
                'usage' => $usage,
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );
    }

    $pdo = db();
    $changedProducts = [];
    $insertedParams = 0;
    $detectedUnitParams = 0;
    $detectedDimensionParams = 0;
    $templateFixedParams = 0;
    $ozonFitsForFixed = 0;
    $brandFilled = 0;
    $failed = 0;
    foreach ($perOffer as $offerId => $result) {
        $productId = (int)($result['product_id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        if (($result['status'] ?? '') !== 'ok') {
            $failed++;
        }
        foreach ((array)($result['params'] ?? []) as $row) {
            $isDetectedUnit = !empty($row['detected_from_title']);
            $isDetectedDimension = !empty($row['detected_from_dimensions']);
            $isTemplateFixed = !empty($row['template_fixed']);
            $isTemplateForce = $isTemplateFixed && (string)($row['template_mode'] ?? '') === 'force';
            $isOzonFitsForFixed = !empty($row['forced_ozon_fits_for']);
            $changed = ($isDetectedUnit || $isDetectedDimension || $isTemplateForce || $isOzonFitsForFixed) ? supplier_products_db_set_param_value(
                $pdo,
                $supplierId,
                $productId,
                (string)($row['kind'] ?? ''),
                (string)($row['name'] ?? ''),
                (string)($row['value'] ?? '')
            ) : supplier_products_db_add_param_if_missing(
                $pdo,
                $supplierId,
                $productId,
                (string)($row['kind'] ?? ''),
                (string)($row['name'] ?? ''),
                (string)($row['value'] ?? '')
            );
            if ($changed) {
                $insertedParams++;
                if ($isDetectedUnit) {
                    $detectedUnitParams++;
                }
                if ($isDetectedDimension) {
                    $detectedDimensionParams++;
                }
                if ($isTemplateFixed) {
                    $templateFixedParams++;
                }
                if ($isOzonFitsForFixed) {
                    $ozonFitsForFixed++;
                }
                $changedProducts[$productId] = true;
            }
        }
        if (($result['status'] ?? '') !== 'ok') {
            continue;
        }
        $vendor = trim((string)($result['vendor'] ?? ''));
        if ($vendor !== '' && supplier_products_standard_field_value($pdo, $productId, 'brand') === '') {
            if (supplier_products_set_standard_field_value($pdo, $supplierId, $productId, 'brand', $vendor)) {
                $brandFilled++;
                $changedProducts[$productId] = true;
            }
        }
    }

    supplier_products_db_fail_if_llm_unavailable(
        'gpt_fill_offer_params',
        count($jobs),
        $failed,
        $tokensInTotal,
        $tokensOutTotal,
        $firstLlmError
    );

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId);
    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $report = [
        'title' => 'gpt_fill_offer_params',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'failed' => $failed,
            'inserted_params' => $insertedParams,
            'detected_unit_quantity_params' => $detectedUnitParams,
            'detected_dimension_params' => $detectedDimensionParams,
            'template_fixed_params' => $templateFixedParams,
            'ozon_fits_for_fixed' => $ozonFitsForFixed,
            'brand_filled' => $brandFilled,
            'products_changed' => count($changedProducts),
            'tokens_in' => $tokensInTotal,
            'tokens_cached_in' => $tokensCachedTotal,
            'tokens_out' => $tokensOutTotal,
        ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
        'dataset' => $dataset,
    ];
    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_fill_offer_params',
        'items' => [
            'Jobs: ' . count($jobs),
            'Inserted params: ' . $insertedParams,
            'Detected unit quantity params: ' . $detectedUnitParams,
            'Detected dimension params: ' . $detectedDimensionParams,
            'Template fixed params: ' . $templateFixedParams,
            'Ozon Подходит для fixed: ' . $ozonFitsForFixed,
            'Brand filled: ' . $brandFilled,
            'Failed: ' . $failed,
            'Tokens in: ' . $tokensInTotal,
            'Tokens cached in: ' . $tokensCachedTotal,
            'Tokens out: ' . $tokensOutTotal,
            'Cost: ' . $costLabel,
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_gpt_fill_tnved_codes(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '0') !== '' && (string)($params['overwrite'] ?? '0') !== '0');
    $minConfidence = (float)str_replace(',', '.', trim((string)($params['min_confidence'] ?? '0.78')));
    if ($minConfidence <= 0 || $minConfidence > 1) {
        $minConfidence = 0.78;
    }
    $allowedValuesLimit = max(20, min(1000, (int)trim((string)($params['allowed_values_limit'] ?? '32'))));
    $categoryShortlistLimit = max(8, min(30, (int)trim((string)($params['category_shortlist_limit'] ?? '16'))));
    $categoryGroupPlan = ((string)($params['category_group_plan'] ?? '1') !== '0');
    $categoryRepresentativeLimit = max(4, min(24, (int)trim((string)($params['category_representative_limit'] ?? '12'))));
    $analysisPrepass = ((string)($params['analysis_prepass'] ?? '0') !== '0');
    $verifyDecisions = ((string)($params['verify_decisions'] ?? '0') !== '0');
    $forceDecision = ((string)($params['force_decision'] ?? '1') !== '0');
    $forceLowConfidence = ((string)($params['force_low_confidence'] ?? '0') !== '0');
    $verificationConfidence = (float)str_replace(',', '.', trim((string)($params['verification_confidence'] ?? '0.82')));
    $verificationConfidence = max(0.5, min(0.99, $verificationConfidence));
    $signatureReuse = ((string)($params['signature_reuse'] ?? '1') !== '0');
    $groupReuse = ((string)($params['group_reuse'] ?? '1') !== '0');
    $memoryAutoFill = ((string)($params['memory_auto_fill'] ?? '1') !== '0');
    $memoryCategoryAutoFill = ((string)($params['memory_category_auto_fill'] ?? '0') !== '0');
    $memoryMinCount = max(1, min(100, (int)trim((string)($params['memory_min_count'] ?? '3'))));
    $memoryMinShare = (float)str_replace(',', '.', trim((string)($params['memory_min_share'] ?? '0.85')));
    $memoryMinShare = max(0.5, min(1.0, $memoryMinShare));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');
    $resultsJsonlAbs = $outDir . '/tnved_results.jsonl';
    $rawJsonlAbs = $outDir . '/tnved_raw.jsonl';
    $categoryPlansJsonAbs = $outDir . '/tnved_category_shortlists.json';
    file_put_contents($resultsJsonlAbs, '');
    file_put_contents($rawJsonlAbs, '');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'fill_tnved_ru.txt');
    $log("supplier_db gpt_fill_tnved_codes: model={$model}, max_items={$maxItems}, overwrite=" . ($overwrite ? '1' : '0') . ", min_confidence={$minConfidence}, allowed_values_limit={$allowedValuesLimit}, category_shortlist_limit={$categoryShortlistLimit}, category_group_plan=" . ($categoryGroupPlan ? '1' : '0') . ", category_representatives={$categoryRepresentativeLimit}, analysis_prepass=" . ($analysisPrepass ? '1' : '0') . ", verifier=" . ($verifyDecisions ? '1' : '0') . ", force_decision=" . ($forceDecision ? '1' : '0') . ", force_low_confidence=" . ($forceLowConfidence ? '1' : '0') . ", verifier_confidence={$verificationConfidence}, signature_reuse=" . ($signatureReuse ? '1' : '0') . ", group_reuse=" . ($groupReuse ? '1' : '0') . ", memory_auto_fill=" . ($memoryAutoFill ? '1' : '0') . ", memory_category_auto_fill=" . ($memoryCategoryAutoFill ? '1' : '0') . ", memory_min_count={$memoryMinCount}, memory_min_share={$memoryMinShare}\n");
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    if ($maxItems > 0 && count($products) > $maxItems) {
        $products = array_slice($products, 0, $maxItems);
    }
    $totalProducts = count($products);
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');

    $overwriteProductsCleared = 0;
    $overwriteValuesCleared = 0;
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    $overwriteValuesIgnored = 0;
    if ($overwrite) {
        foreach ($fieldsByProduct as $productId => $productFields) {
            $removedValues = 0;
            $fieldsByProduct[$productId] = supplier_products_db_without_tnved_fields((array)$productFields, $removedValues);
            $overwriteValuesIgnored += $removedValues;
        }
        $log("overwrite reset context: ignored_values={$overwriteValuesIgnored}\n");
    }
    $tnvedMemoryBySupplierCategory = supplier_products_db_tnved_existing_memory($products, $fieldsByProduct);

    $jobs = [];
    $missingRealTargetFallback = 0;
    $skippedFilled = 0;
    $skippedDictionaryMissing = 0;
    $dictionaryMissingTargets = 0;
    $fallbackTargetsUsed = 0;
    $categoryEnsureResults = [];
    $categoryEnsureFailed = 0;
    $categoryContextCache = [];
    $seenProducts = 0;
    $preChangedProducts = [];
    $standardTnvedChanged = 0;
    $standardTnvedMigrated = 0;
    $standardTnvedAlreadyFilled = 0;
    $ensureCategoryAttributes = static function (string $source, string $categoryValue) use ($datasetId, $cfg, &$categoryEnsureResults, &$categoryEnsureFailed): array {
        $source = $source === 'wb' ? 'wildberries' : trim($source);
        $categoryValue = trim($categoryValue);
        if (!in_array($source, ['ozon', 'wildberries'], true) || $categoryValue === '') {
            return ['ok' => false, 'error' => 'empty_category'];
        }
        $key = $source . ':' . $categoryValue;
        if (isset($categoryEnsureResults[$key])) {
            return $categoryEnsureResults[$key];
        }
        try {
            $result = supplier_market_row_ensure_category_attributes_for_value($datasetId, $source, $categoryValue, $cfg, 0);
            if (empty($result['ok'])) {
                $categoryEnsureFailed++;
            }
        } catch (Throwable $e) {
            $categoryEnsureFailed++;
            $result = ['ok' => false, 'source' => $source, 'error' => $e->getMessage()];
        }
        $categoryEnsureResults[$key] = is_array($result) ? $result : ['ok' => false, 'source' => $source, 'error' => 'bad_result'];
        return $categoryEnsureResults[$key];
    };
    $loadCategoryContext = static function (string $source, string $categoryValue) use ($cfg, &$categoryContextCache): array {
        $source = $source === 'wb' ? 'wildberries' : trim($source);
        $categoryValue = trim($categoryValue);
        if ($categoryValue === '' || !in_array($source, ['ozon', 'wildberries'], true)) {
            return [];
        }
        $key = $source . ':' . $categoryValue;
        if (!array_key_exists($key, $categoryContextCache)) {
            $categoryContextCache[$key] = supplier_products_db_load_attr_category($source, $categoryValue, $cfg, true);
        }
        return is_array($categoryContextCache[$key]) ? $categoryContextCache[$key] : [];
    };
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $existingStandardTnvedValue = trim(supplier_products_db_standard_field_value_from_rows(
            $fields,
            supplier_products_tnved_standard_field_name()
        ));
        $existingStandardTnvedCode = supplier_products_db_tnved_code_from_text($existingStandardTnvedValue);
        $existingMarketplaceTnvedCode = '';
        $hasExistingMarketplaceTnvedValue = false;
        foreach ($fields as $field) {
            $kind = (string)($field['field_kind'] ?? '');
            if ($kind !== 'param' && $kind !== 'wb_param') {
                continue;
            }
            if (!supplier_products_db_is_tnved_attribute_name((string)($field['field_name'] ?? ''))) {
                continue;
            }
            $candidateValue = trim((string)($field['field_value'] ?? ''));
            if ($candidateValue !== '') {
                $hasExistingMarketplaceTnvedValue = true;
            }
            $candidateCode = supplier_products_db_tnved_code_from_text($candidateValue);
            if ($candidateCode !== '' && supplier_products_db_tnved_non_leaf_reason($candidateCode) === '') {
                $existingMarketplaceTnvedCode = $candidateCode;
                break;
            }
        }
        if (!$overwrite && ($existingStandardTnvedValue !== '' || $hasExistingMarketplaceTnvedValue)) {
            if ($existingStandardTnvedValue !== '') {
                $standardTnvedAlreadyFilled++;
            }
            $skippedFilled++;
            continue;
        }
        $existingProfileText = implode("\n", [
            (string)($product['name'] ?? ''),
            (string)($product['description_html'] ?? ''),
            (string)($product['category_path'] ?? ''),
            implode(' ', array_map(static fn(array $row): string => (string)($row['field_name'] ?? '') . ' ' . (string)($row['field_value'] ?? ''), array_slice($fields, 0, 80))),
        ]);
        $existingStandardReliable = supplier_products_db_tnved_existing_code_matches_product_profile($existingStandardTnvedCode, $existingProfileText);
        $existingMarketplaceReliable = supplier_products_db_tnved_existing_code_matches_product_profile($existingMarketplaceTnvedCode, $existingProfileText);
        if ($existingStandardTnvedCode === ''
            && $existingMarketplaceTnvedCode !== ''
            && $existingMarketplaceReliable) {
            if (supplier_products_set_standard_field_value(db(), $supplierId, $productId, supplier_products_tnved_standard_field_name(), $existingMarketplaceTnvedCode)) {
                $standardTnvedChanged++;
                $standardTnvedMigrated++;
                $preChangedProducts[$productId] = true;
            }
            if (!$overwrite) {
                $skippedFilled++;
                continue;
            }
        }
        $needsStandardRefresh = $overwrite
            || $existingStandardTnvedCode === ''
            || !$existingStandardReliable;
        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');

        $marketplaceContexts = [];
        if ($ozonCategory !== '') {
            $ensureCategoryAttributes('ozon', $ozonCategory);
        }
        $ozonCtx = $loadCategoryContext('ozon', $ozonCategory);
        if ($ozonCtx) {
            $marketplaceContexts[] = $ozonCtx;
        }
        if ($wbCategory !== '') {
            $ensureCategoryAttributes('wildberries', $wbCategory);
        }
        $wbCtx = $loadCategoryContext('wildberries', $wbCategory);
        if ($wbCtx) {
            $marketplaceContexts[] = $wbCtx;
        }

        $detectedTargets = supplier_products_db_tnved_targets_for_contexts($marketplaceContexts);
        if (!$detectedTargets) {
            $missingRealTargetFallback++;
        }
        $targets = array_merge(
            $detectedTargets,
            supplier_products_db_tnved_fallback_targets($marketplaceContexts, $detectedTargets)
        );

        $existingByTarget = [];
        foreach ($fields as $field) {
            $kind = (string)($field['field_kind'] ?? '');
            if ($kind !== 'param' && $kind !== 'wb_param') {
                continue;
            }
            $name = trim((string)($field['field_name'] ?? ''));
            if ($name === '') {
                continue;
            }
            $key = $kind . "\n" . supplier_products_db_attr_norm($name);
            $value = trim((string)($field['field_value'] ?? ''));
            if ($value !== '' && !isset($existingByTarget[$key])) {
                $existingByTarget[$key] = $value;
            }
        }

        $writeTargets = [];
        foreach ($targets as $target) {
            $key = supplier_products_db_tnved_target_key($target);
            $existingValue = (string)($existingByTarget[$key] ?? '');
            if (!$needsStandardRefresh && !$overwrite && supplier_products_db_tnved_existing_target_value_is_valid($target, $existingValue)) {
                continue;
            }
            if (!empty($target['requires_dictionary']) && empty($target['allowed_values'])) {
                $dictionaryMissingTargets++;
            }
            if (!empty($target['fallback_target'])) {
                $fallbackTargetsUsed++;
            }
            $writeTargets[] = $target;
        }
        if (!$writeTargets) {
            $skippedFilled++;
            continue;
        }

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $shortName = supplier_products_db_standard_field_value_from_rows($fields, 'short_name');
        $standard = [
            'length' => trim((string)($product['length'] ?? '')),
            'width' => trim((string)($product['width'] ?? '')),
            'height' => trim((string)($product['height'] ?? '')),
            'weight' => trim((string)($product['weight'] ?? '')),
        ];
        foreach ($fields as $field) {
            if ((string)($field['field_kind'] ?? '') !== 'standard') {
                continue;
            }
            $stdName = trim((string)($field['field_name'] ?? ''));
            if (!array_key_exists($stdName, $standard)) {
                continue;
            }
            $stdValue = trim((string)($field['field_value'] ?? ''));
            if ($stdValue !== '') {
                $standard[$stdName] = $stdValue;
            }
        }
        $marketplaceCategoryPayload = [];
        foreach ($marketplaceContexts as $ctx) {
            if (!is_array($ctx)) {
                continue;
            }
            $marketplaceCategoryPayload[] = [
                'source' => (string)($ctx['source'] ?? ''),
                'code' => (string)($ctx['code'] ?? ''),
                'name' => (string)($ctx['name'] ?? ''),
                'full_path' => (string)($ctx['full_path'] ?? ''),
                'description' => supplier_products_db_description_snippet((string)($ctx['description'] ?? ''), 260),
                'typical_goods' => supplier_products_db_description_snippet((string)($ctx['typical_goods'] ?? ''), 260),
                'features' => supplier_products_db_description_snippet((string)($ctx['features'] ?? ''), 220),
            ];
        }
        $supplierCategoryMemory = supplier_products_db_tnved_compact_memory(
            $tnvedMemoryBySupplierCategory[supplier_products_db_tnved_supplier_category_key($product)] ?? [],
            5
        );
        $signatureTitle = supplier_products_db_tnved_signature_title($shortName !== '' ? $shortName : (string)($product['name'] ?? ''));
        $memoryAutoDecision = [];
        if ($memoryAutoFill) {
            $memoryAutoDecision = supplier_products_db_tnved_signature_memory_decision(
                $supplierCategoryMemory,
                $signatureTitle,
                max(2, $memoryMinCount - 1)
            );
        }
        if (!$memoryAutoDecision && $memoryCategoryAutoFill) {
            $memoryAutoDecision = supplier_products_db_tnved_memory_auto_decision($supplierCategoryMemory, $memoryMinCount, $memoryMinShare);
        }

        $tnvedSearchText = implode("\n", [
            (string)($product['name'] ?? ''),
            $shortName,
            (string)($product['description_html'] ?? ''),
            (string)($product['category_path'] ?? ''),
            implode(' ', array_map(static fn(array $row): string => (string)($row['field_name'] ?? '') . ' ' . (string)($row['field_value'] ?? ''), array_slice($fields, 0, 80))),
            implode(' ', array_map(static fn(array $row): string => (string)($row['full_path'] ?? '') . ' ' . (string)($row['description'] ?? '') . ' ' . (string)($row['typical_goods'] ?? ''), $marketplaceCategoryPayload)),
        ]);
        $classificationHints = supplier_products_db_tnved_classification_hints($tnvedSearchText);
        $tnvedPromptSearchText = supplier_products_db_tnved_search_text_with_analysis(
            [
                'product' => [
                    'name' => (string)($product['name'] ?? ''),
                    'short_name' => $shortName,
                    'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 1600),
                    'supplier_category' => [
                        'id' => (string)($product['category_id'] ?? ''),
                        'path' => (string)($product['category_path'] ?? ''),
                    ],
                    'params' => array_slice(supplier_products_db_product_params_payload($fields), 0, 80),
                ],
                'marketplace_categories' => $marketplaceCategoryPayload,
            ],
            [],
            $classificationHints
        );
        $tnvedProfile = supplier_products_db_tnved_product_profile($tnvedPromptSearchText);

        $payload = [
                'product' => [
                    'offer_id' => $offerId,
                    'vendorCode' => (string)($product['vendor_code'] ?? ''),
                    'name' => (string)($product['name'] ?? ''),
                    'short_name' => $shortName,
                    'brand' => (string)($context['brand'] ?? ($product['brand'] ?? '')),
                    'vendor' => (string)($context['vendor'] ?? ''),
                    'model' => (string)($context['model'] ?? ''),
                    'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 1600),
                    'supplier_category' => [
                        'id' => (string)($product['category_id'] ?? ''),
                        'path' => (string)($product['category_path'] ?? ''),
                    ],
                    'dimensions' => $standard,
                    'params' => array_slice(supplier_products_db_product_params_payload($fields), 0, 80),
                ],
                'marketplace_categories' => $marketplaceCategoryPayload,
                'supplier_category_memory' => $supplierCategoryMemory,
                'classification_hints' => $classificationHints,
                'tnved_profile' => supplier_products_db_tnved_profile_prompt($tnvedProfile),
                'target_attributes' => array_map(
                    static fn(array $target): array => supplier_products_db_tnved_target_prompt($target, $tnvedPromptSearchText, $allowedValuesLimit, $supplierCategoryMemory),
                    $writeTargets
                ),
        ];

        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'targets' => $writeTargets,
            'existing_by_target' => $existingByTarget,
            'signature_key' => supplier_products_db_tnved_signature_key($payload),
            'signature_title' => $signatureTitle,
            'tnved_group_key' => supplier_products_db_tnved_group_key($payload),
            'tnved_group_label' => supplier_products_db_tnved_group_label($payload),
            'memory_auto_decision' => $memoryAutoDecision,
            'tnved_search_text' => $tnvedSearchText,
            'payload' => $payload,
        ];

        if ($seenProducts % 250 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $categoryShortlistPlans = supplier_products_db_tnved_prepare_category_shortlists($jobs, $categoryShortlistLimit);
    file_put_contents(
        $categoryPlansJsonAbs,
        json_encode([
            'generated_at' => date(DATE_ATOM),
            'supplier_id' => $supplierId,
            'dataset_id' => $datasetId,
            'shortlist_limit' => $categoryShortlistLimit,
            'categories' => array_values($categoryShortlistPlans),
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
    );

    $categoryShortlistCodes = 0;
    $categoryAllowedValuesOriginal = 0;
    foreach ($categoryShortlistPlans as $plan) {
        $categoryShortlistCodes += (int)($plan['shortlist_count'] ?? 0);
        $categoryAllowedValuesOriginal += (int)($plan['allowed_values_original'] ?? 0);
    }

    $signatureKeyCounts = [];
    $groupKeyCounts = [];
    $memoryAutoCandidates = 0;
    $memoryStableCandidates = 0;
    $memorySignatureCandidates = 0;
    $allowedValuesTargets = 0;
    $allowedValuesOriginalTotal = 0;
    $allowedValuesPromptTotal = 0;
    $allowedValuesPromptBytes = 0;
    $allowedValuesWeakShortlists = 0;
    $allowedValuesIncompatibleFiltered = 0;
    $allowedValuesMarkingFiltered = 0;
    foreach ($jobs as $job) {
        $signatureKey = (string)($job['signature_key'] ?? '');
        if ($signatureKey !== '') {
            $signatureKeyCounts[$signatureKey] = ($signatureKeyCounts[$signatureKey] ?? 0) + 1;
        }
        $groupKey = (string)($job['tnved_group_key'] ?? '');
        if ($groupKey !== '') {
            $groupKeyCounts[$groupKey] = ($groupKeyCounts[$groupKey] ?? 0) + 1;
        }
        if (!empty($job['memory_auto_decision']['tnved_code'])) {
            $memoryAutoCandidates++;
            if ((string)($job['memory_auto_decision']['source'] ?? '') === 'supplier_category_signature_memory') {
                $memorySignatureCandidates++;
            } else {
                $memoryStableCandidates++;
            }
        }
        foreach ((array)($job['payload']['target_attributes'] ?? []) as $target) {
            if (!is_array($target)) {
                continue;
            }
            $allowedCount = (int)($target['allowed_values_count'] ?? 0);
            $inPrompt = (int)($target['allowed_values_in_prompt'] ?? 0);
            $allowedValuesMarkingFiltered += (int)($target['marking_values_filtered'] ?? 0);
            if ($allowedCount <= 0) {
                continue;
            }
            $allowedValuesTargets++;
            $allowedValuesOriginalTotal += max($allowedCount, (int)($target['allowed_values_original_count'] ?? 0));
            $allowedValuesPromptTotal += $inPrompt;
            $allowedValuesIncompatibleFiltered += (int)($target['allowed_values_incompatible_filtered'] ?? 0);
            $encodedAllowed = json_encode((array)($target['allowed_values'] ?? []), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            $allowedValuesPromptBytes += is_string($encodedAllowed) ? strlen($encodedAllowed) : 0;
            if (!empty($target['allowed_values_are_shortlist']) && (int)($target['allowed_values_top_score'] ?? 0) <= 0) {
                $allowedValuesWeakShortlists++;
            }
        }
    }
    $signatureReusePotential = 0;
    foreach ($signatureKeyCounts as $count) {
        if ($count > 1) {
            $signatureReusePotential += $count - 1;
        }
    }
    $groupReusePotential = 0;
    foreach ($groupKeyCounts as $count) {
        if ($count > 1) {
            $groupReusePotential += $count - 1;
        }
    }

    $log("scan: products_seen={$seenProducts}, jobs=" . count($jobs) . ", categories_checked=" . count($categoryEnsureResults) . ", category_check_failed={$categoryEnsureFailed}, missing_real_target_fallback={$missingRealTargetFallback}, dictionary_missing_targets={$dictionaryMissingTargets}, skipped_dictionary_missing={$skippedDictionaryMissing}, skipped_filled={$skippedFilled}\n");
    $log("category shortlists: scopes=" . count($categoryShortlistPlans) . ", original_dictionary_values={$categoryAllowedValuesOriginal}, shortlist_codes={$categoryShortlistCodes}, artifact={$categoryPlansJsonAbs}\n");
    $log("optimizer: signature_groups=" . count($signatureKeyCounts) . ", signature_reuse_potential={$signatureReusePotential}, tnved_groups=" . count($groupKeyCounts) . ", group_reuse_potential={$groupReusePotential}, memory_auto_candidates={$memoryAutoCandidates}, memory_stable_candidates={$memoryStableCandidates}, memory_signature_candidates={$memorySignatureCandidates}\n");
    $log("allowed shortlist: targets={$allowedValuesTargets}, original_values={$allowedValuesOriginalTotal}, prompt_values={$allowedValuesPromptTotal}, prompt_bytes={$allowedValuesPromptBytes}, weak_shortlists={$allowedValuesWeakShortlists}, incompatible_filtered={$allowedValuesIncompatibleFiltered}, marking_filtered={$allowedValuesMarkingFiltered}\n");

    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costTotal = 0.0;
    $changedProducts = $preChangedProducts;
    $inserted = 0;
    $validatedDictionary = 0;
    $lowConfidence = 0;
    $noCode = 0;
    $notInDictionary = 0;
    $dictionaryMissingFallback = 0;
    $analysisRequests = 0;
    $analysisErrors = 0;
    $verificationRequests = 0;
    $verificationErrors = 0;
    $verificationApproved = 0;
    $verificationRejected = 0;
    $verificationCorrected = 0;
    $forceRequests = 0;
    $forceErrors = 0;
    $forcedNoCode = 0;
    $forcedLowConfidence = 0;
    $forcedVerification = 0;
    $memoryAutoApplied = 0;
    $memoryStableApplied = 0;
    $memorySignatureApplied = 0;
    $signatureReused = 0;
    $signatureCacheWrites = 0;
    $signatureDecisionByKey = [];
    $groupReused = 0;
    $groupReuseRejected = 0;
    $groupCacheWrites = 0;
    $groupDecisionByKey = [];
    $categoryGroupPlanRequests = 0;
    $categoryGroupPlanErrors = 0;
    $categoryGroupPlanAccepted = 0;
    $categoryGroupPlanRejected = 0;
    $categoryGroupPlanProductsCovered = 0;
    $categoryGroupPlanReports = [];
    $memoryAutoRejected = 0;
    $reviewRequiredCount = 0;
    $dictionaryMismatchForced = 0;
    $profileGuardApplied = 0;
    $estimatedRequests = 0;
    $estimatedInputTokensTotal = 0;
    $estimatedExpectedOutputTokensTotal = 0;
    $estimatedMaxOutputTokensTotal = 0;
    $estimatedExpectedCostTotal = 0.0;
    $estimatedMaxCostTotal = 0.0;
    $usageEstimatedRequests = 0;
    $failed = 0;
    $done = 0;
    $firstLlmError = '';
    $client = count($jobs) > 0 ? LLM::client($cfg, $model) : null;
    $addEstimate = static function (array $estimate) use (
        &$estimatedRequests,
        &$estimatedInputTokensTotal,
        &$estimatedExpectedOutputTokensTotal,
        &$estimatedMaxOutputTokensTotal,
        &$estimatedExpectedCostTotal,
        &$estimatedMaxCostTotal
    ): void {
        $estimatedRequests++;
        $estimatedInputTokensTotal += (int)($estimate['input_tokens'] ?? 0);
        $estimatedExpectedOutputTokensTotal += (int)($estimate['expected_output_tokens'] ?? 0);
        $estimatedMaxOutputTokensTotal += (int)($estimate['max_output_tokens'] ?? 0);
        $estimatedExpectedCostTotal += (float)($estimate['expected_cost'] ?? 0.0);
        $estimatedMaxCostTotal += (float)($estimate['max_cost'] ?? 0.0);
    };
    $addUsage = static function (array $usage) use (
        &$tokensInTotal,
        &$tokensOutTotal,
        &$tokensCachedTotal,
        &$costTotal,
        &$usageEstimatedRequests
    ): void {
        $tokensInTotal += (int)($usage['input'] ?? 0);
        $tokensOutTotal += (int)($usage['output'] ?? 0);
        $tokensCachedTotal += (int)($usage['cached_input'] ?? 0);
        $costTotal += (float)($usage['cost'] ?? 0.0);
        if (!empty($usage['estimated'])) {
            $usageEstimatedRequests++;
        }
    };

    if ($categoryGroupPlan && $groupReuse && $client !== null && count($jobs) > 1) {
        $jobsByTnvedGroup = [];
        foreach ($jobs as $offerId => $job) {
            $groupKey = (string)($job['tnved_group_key'] ?? '');
            if ($groupKey !== '') {
                $jobsByTnvedGroup[$groupKey][(string)$offerId] = $job;
            }
        }
        $groupPlanTotal = count(array_filter($jobsByTnvedGroup, static fn(array $rows): bool => count($rows) > 1));
        $groupPlanDone = 0;
        foreach ($jobsByTnvedGroup as $groupKey => $groupJobs) {
            if (count($groupJobs) < 2) {
                continue;
            }
            $groupPlanDone++;
            ops_update_progress($opId, $groupPlanDone, max(1, $groupPlanTotal), 'tnved_category_plan', "Группа ТН ВЭД {$groupPlanDone}/{$groupPlanTotal}");
            $firstJob = reset($groupJobs);
            $firstPayload = is_array($firstJob['payload'] ?? null) ? (array)$firstJob['payload'] : [];
            $groupOffers = array_keys($groupJobs);
            $representativeOffers = [];
            $representativeCount = min($categoryRepresentativeLimit, count($groupOffers));
            for ($idx = 0; $idx < $representativeCount; $idx++) {
                $sourceIndex = $representativeCount >= count($groupOffers)
                    ? $idx
                    : (int)floor($idx * count($groupOffers) / $representativeCount);
                $representativeOffers[] = (string)$groupOffers[$sourceIndex];
            }
            $representativeOffers = array_values(array_unique($representativeOffers));
            $representatives = [];
            foreach ($representativeOffers as $representativeOffer) {
                $representativePayload = (array)($groupJobs[$representativeOffer]['payload'] ?? []);
                $productPayload = (array)($representativePayload['product'] ?? []);
                $representatives[] = [
                    'offer_id' => (string)($productPayload['offer_id'] ?? $representativeOffer),
                    'name' => acp_trunc((string)($productPayload['name'] ?? ''), 220),
                    'short_name' => acp_trunc((string)($productPayload['short_name'] ?? ''), 160),
                    'model' => acp_trunc((string)($productPayload['model'] ?? ''), 100),
                    'description' => supplier_products_db_description_snippet((string)($productPayload['description'] ?? ''), 360),
                    'dimensions' => (array)($productPayload['dimensions'] ?? []),
                ];
            }
            $targetAttributes = [];
            foreach ((array)($firstPayload['target_attributes'] ?? []) as $target) {
                if (!is_array($target)) {
                    continue;
                }
                $targetAttributes[] = [
                    'marketplace' => (string)($target['marketplace'] ?? ''),
                    'attribute_name' => (string)($target['attribute_name'] ?? ''),
                    'category_code' => (string)($target['category_code'] ?? ''),
                    'category_path' => (string)($target['category_path'] ?? ''),
                    'candidate_policy' => (string)($target['candidate_policy'] ?? ''),
                    'allowed_values_count' => (int)($target['allowed_values_count'] ?? 0),
                    'allowed_values' => array_values((array)($target['allowed_values'] ?? [])),
                ];
            }
            $groupRequest = [
                'mode' => 'tnved_category_group',
                'category_scope' => $firstPayload['category_tnved_shortlist'] ?? [],
                'supplier_category' => $firstPayload['product']['supplier_category'] ?? [],
                'marketplace_categories' => $firstPayload['marketplace_categories'] ?? [],
                'tnved_profile' => $firstPayload['tnved_profile'] ?? [],
                'classification_hints' => $firstPayload['classification_hints'] ?? [],
                'supplier_category_memory' => $firstPayload['supplier_category_memory'] ?? [],
                'target_attributes' => $targetAttributes,
                'products_in_group' => count($groupJobs),
                'representative_products' => $representatives,
                'instruction' => 'Выбери один наиболее общий, но конечный 10-значный код из короткого списка категории, который корректно подходит каждому товару этой однородной группы. Не классифицируй по бренду или устройству совместимости. Если единого кода нет, верни uniform=false и не подбирай приблизительный общий код.',
            ];
            $groupJson = json_encode($groupRequest, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            if ($groupJson === false) {
                $groupJson = '{"mode":"tnved_category_group","representative_products":[]}';
            }
            $groupUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $groupJson;
            $groupMaxOutputTokens = 520;
            $groupEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $groupUserMessage, $groupMaxOutputTokens, 0.5);
            $addEstimate($groupEstimate);
            $categoryGroupPlanRequests++;
            $reportRow = [
                'group_key' => $groupKey,
                'group_label' => (string)($firstJob['tnved_group_label'] ?? ''),
                'category_scope_key' => (string)($firstJob['tnved_category_scope_key'] ?? ''),
                'products' => count($groupJobs),
                'representatives' => count($representatives),
                'status' => 'rejected',
                'reason' => '',
            ];
            try {
                $groupRes = $client->generateText($model, $groupUserMessage, $prompt, [
                    'prompt_cache_key' => 'fill_tnved_category_group:' . substr(hash('sha256', json_encode([
                        'category_scope' => $firstJob['tnved_category_scope_key'] ?? '',
                        'group' => $groupKey,
                        'candidates' => array_map(static fn(array $row): string => (string)($row['code'] ?? ''), (array)($firstPayload['category_tnved_shortlist']['candidate_codes'] ?? [])),
                    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                    'text' => ['format' => ['type' => 'json_object']],
                    'max_output_tokens' => $groupMaxOutputTokens,
                ]);
                $groupRaw = is_array($groupRes['raw'] ?? null) ? $groupRes['raw'] : null;
                $groupOutputText = (string)($groupRes['output_text'] ?? '');
                $groupUsage = supplier_products_db_merge_llm_usage_with_estimate(
                    $cfg,
                    $model,
                    $groupRaw,
                    $prompt,
                    $groupUserMessage,
                    $groupOutputText,
                    $groupMaxOutputTokens
                );
                $addUsage($groupUsage);
                if ($groupRaw !== null) {
                    file_put_contents($rawJsonlAbs, json_encode([
                        'step' => 'category_group_plan',
                        'group_key' => $groupKey,
                        'usage' => $groupUsage,
                        'raw' => $groupRaw,
                    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
                }
                $groupDecoded = supplier_products_db_extract_json_object($groupOutputText);
                $uniform = supplier_products_db_tnved_bool($groupDecoded['uniform'] ?? ($groupDecoded['common_code_applies_to_all'] ?? false));
                $decisionRaw = is_array($groupDecoded['decision'] ?? null) ? (array)$groupDecoded['decision'] : $groupDecoded;
                $groupDecision = supplier_products_db_tnved_decision_from_decoded($decisionRaw);
                $reportRow['uniform'] = $uniform ? 1 : 0;
                $reportRow['decision'] = $groupDecision;
                if (!$uniform) {
                    $reportRow['reason'] = acp_trunc((string)($groupDecoded['reason'] ?? 'Нет единого кода для всей группы.'), 300);
                    $categoryGroupPlanRejected++;
                } elseif ((float)($groupDecision['confidence'] ?? 0) < $minConfidence || !empty($groupDecision['review_required'])) {
                    $reportRow['reason'] = 'Недостаточная уверенность общего решения.';
                    $categoryGroupPlanRejected++;
                } else {
                    $validatedDecision = null;
                    $rejectedReason = '';
                    foreach ($groupJobs as $groupJob) {
                        $applicable = supplier_products_db_tnved_group_decision_applicable_to_job(
                            $groupDecision,
                            $groupJob,
                            (array)($groupJob['payload'] ?? []),
                            $minConfidence
                        );
                        if (empty($applicable['ok'])) {
                            $rejectedReason = (string)($applicable['reason'] ?? 'not_applicable');
                            break;
                        }
                        if ($validatedDecision === null) {
                            $validatedDecision = (array)($applicable['decision'] ?? $groupDecision);
                        }
                    }
                    if ($rejectedReason !== '' || $validatedDecision === null) {
                        $reportRow['reason'] = 'Общий код не прошел локальную проверку для всех товаров: ' . ($rejectedReason !== '' ? $rejectedReason : 'empty_decision');
                        $categoryGroupPlanRejected++;
                    } else {
                        $validatedDecision['reason'] = 'Общий код однородной группы по категории поставщика и категории маркетплейса: ' . (string)($firstJob['tnved_group_label'] ?? '');
                        $groupDecisionByKey[$groupKey] = $validatedDecision;
                        $reportRow['status'] = 'accepted';
                        $reportRow['reason'] = (string)$validatedDecision['reason'];
                        $reportRow['decision'] = $validatedDecision;
                        $categoryGroupPlanAccepted++;
                        $categoryGroupPlanProductsCovered += count($groupJobs);
                    }
                }
            } catch (Throwable $e) {
                $categoryGroupPlanErrors++;
                $categoryGroupPlanRejected++;
                $reportRow['status'] = 'error';
                $reportRow['reason'] = acp_trunc($e->getMessage(), 320);
                $log("tnved category group plan failed group={$groupKey}: " . $e->getMessage() . "\n");
            }
            $categoryGroupPlanReports[] = $reportRow;
        }
        $log("category group plans: requests={$categoryGroupPlanRequests}, accepted={$categoryGroupPlanAccepted}, rejected={$categoryGroupPlanRejected}, errors={$categoryGroupPlanErrors}, products_covered={$categoryGroupPlanProductsCovered}\n");
        file_put_contents(
            $categoryPlansJsonAbs,
            json_encode([
                'generated_at' => date(DATE_ATOM),
                'supplier_id' => $supplierId,
                'dataset_id' => $datasetId,
                'shortlist_limit' => $categoryShortlistLimit,
                'categories' => array_values($categoryShortlistPlans),
                'group_decisions' => $categoryGroupPlanReports,
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );
    }

    foreach ($jobs as $offerId => $job) {
        $done++;
        ops_update_progress($opId, $done, max(1, count($jobs)), 'gpt', "TNVED {$done}/" . count($jobs) . " offer={$offerId}");

        $payload = (array)($job['payload'] ?? []);
        $status = 'ok';
        $error = '';
        $rawText = '';
        $usage = ['input' => 0, 'cached_input' => 0, 'output' => 0];
        $mainEstimate = null;
        $analysis = [];
        $analysisError = '';
        $analysisUsage = null;
        $analysisEstimate = null;
        $verification = [];
        $verificationError = '';
        $verificationUsage = null;
        $verificationEstimate = null;
        $forceError = '';
        $forceUsage = null;
        $forceEstimate = null;
        $forceDecoded = [];
        $forceReason = '';
        $reviewRequired = false;
        $reviewReason = '';
        $reviewCounted = false;
        $decoded = [];
        $acceptedRows = [];
        $finalTnvedCode = '';

        try {
            $signatureKey = (string)($job['signature_key'] ?? '');
            $groupKey = (string)($job['tnved_group_key'] ?? '');
            $fastDecision = [];
            $fastSource = '';
            if ($memoryAutoFill && is_array($job['memory_auto_decision'] ?? null) && !empty($job['memory_auto_decision']['tnved_code'])) {
                $fastDecision = (array)$job['memory_auto_decision'];
                $fastSource = (string)($fastDecision['source'] ?? '') === 'supplier_category_signature_memory' ? 'memory_signature' : 'memory_auto';
            } elseif ($signatureReuse && $signatureKey !== '' && isset($signatureDecisionByKey[$signatureKey])) {
                $fastDecision = (array)$signatureDecisionByKey[$signatureKey];
                $fastSource = 'signature_reuse';
                $signatureReused++;
            } elseif ($groupReuse && $groupKey !== '' && isset($groupDecisionByKey[$groupKey])) {
                $groupCandidate = supplier_products_db_tnved_group_decision_applicable_to_job(
                    (array)$groupDecisionByKey[$groupKey],
                    $job,
                    $payload,
                    $minConfidence
                );
                if (!empty($groupCandidate['ok'])) {
                    $fastDecision = (array)($groupCandidate['decision'] ?? $groupDecisionByKey[$groupKey]);
                    $fastSource = 'group_reuse';
                    $groupReused++;
                } else {
                    $groupReuseRejected++;
                }
            }

            if ($fastDecision && ($fastSource === 'memory_signature' || $fastSource === 'memory_auto')) {
                $memoryCandidate = supplier_products_db_tnved_group_decision_applicable_to_job(
                    $fastDecision,
                    $job,
                    $payload,
                    $minConfidence
                );
                if (empty($memoryCandidate['ok'])) {
                    $fastDecision = [];
                    $fastSource = '';
                    $memoryAutoRejected++;
                } else {
                    $fastDecision = (array)($memoryCandidate['decision'] ?? $fastDecision);
                    $memoryAutoApplied++;
                    if ($fastSource === 'memory_signature') {
                        $memorySignatureApplied++;
                    } else {
                        $memoryStableApplied++;
                    }
                }
            }

            if ($fastDecision) {
                $code = supplier_products_db_tnved_code_from_text((string)($fastDecision['tnved_code'] ?? ''));
                $confidence = max(0.0, min(1.0, (float)($fastDecision['confidence'] ?? 0.86)));
                $suggestedValue = trim((string)($fastDecision['marketplace_value'] ?? $code));
                if ($suggestedValue === '') {
                    $suggestedValue = $code;
                }
                $decision = [
                    'tnved_code' => $code,
                    'marketplace_value' => $suggestedValue,
                    'confidence' => $confidence,
                    'review_required' => !empty($fastDecision['review_required']),
                    'reason' => (string)($fastDecision['reason'] ?? ($fastSource === 'signature_reuse' ? 'Переиспользовано решение для похожего товара.' : 'Автовыбор по памяти категории.')),
                    'risk_flags' => (array)($fastDecision['risk_flags'] ?? []),
                    'alternatives' => (array)($fastDecision['alternatives'] ?? []),
                ];
                $guard = supplier_products_db_tnved_apply_profile_guard(
                    $decision,
                    supplier_products_db_tnved_search_text_with_analysis($payload, [], (array)($payload['classification_hints'] ?? [])),
                    []
                );
                $decision = (array)$guard['decision'];
                $code = (string)($decision['tnved_code'] ?? $code);
                $confidence = (float)($decision['confidence'] ?? $confidence);
                $suggestedValue = (string)($decision['marketplace_value'] ?? $suggestedValue);
                $decoded = [
                    'fast_source' => $fastSource,
                    'decision' => $decision,
                    'signature_key' => $signatureKey,
                    'signature_title' => (string)($job['signature_title'] ?? ''),
                ];
                if (!empty($guard['changed'])) {
                    $decoded['system_profile_guard'][] = $guard;
                    $profileGuardApplied++;
                }
            } else {
                if ($analysisPrepass) {
                    try {
                        $analysisTargets = [];
                        foreach ((array)($payload['target_attributes'] ?? []) as $target) {
                            if (!is_array($target)) {
                                continue;
                            }
                            $copy = $target;
                            $copy['allowed_values'] = array_slice((array)($copy['allowed_values'] ?? []), 0, 30);
                            $analysisTargets[] = $copy;
                        }
                        $analysisRequest = [
                            'mode' => 'tnved_analysis',
                            'product' => $payload['product'] ?? [],
                            'marketplace_categories' => $payload['marketplace_categories'] ?? [],
                            'supplier_category_memory' => $payload['supplier_category_memory'] ?? [],
                            'target_attributes' => $analysisTargets,
                            'instruction' => 'Сначала классифицируй товарную роль, объект применения, материал и вероятные группы ТН ВЭД. Не выбирай финальный код на этом шаге.',
                        ];
                        $analysisJson = json_encode($analysisRequest, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                        if ($analysisJson === false) {
                            $analysisJson = '{"mode":"tnved_analysis","product":{}}';
                        }
                        $analysisUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $analysisJson;
                        $analysisMaxOutputTokens = 650;
                        $analysisEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $analysisUserMessage, $analysisMaxOutputTokens, 0.5);
                        $addEstimate($analysisEstimate);
                        $analysisRequests++;

                        $analysisRes = $client->generateText($model, $analysisUserMessage, $prompt, [
                            'prompt_cache_key' => 'fill_tnved_analysis:' . substr(hash('sha256', json_encode([
                                'supplier_category' => $payload['product']['supplier_category'] ?? [],
                                'marketplace_categories' => array_map(static fn(array $row): string => (string)($row['full_path'] ?? ''), (array)($payload['marketplace_categories'] ?? [])),
                                'memory' => array_column((array)($payload['supplier_category_memory'] ?? []), 'code'),
                            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                            'text' => ['format' => ['type' => 'json_object']],
                            'max_output_tokens' => $analysisMaxOutputTokens,
                        ]);
                        $analysisRaw = is_array($analysisRes['raw'] ?? null) ? $analysisRes['raw'] : null;
                        $analysisUsage = supplier_products_db_merge_llm_usage_with_estimate(
                            $cfg,
                            $model,
                            $analysisRaw,
                            $prompt,
                            $analysisUserMessage,
                            (string)($analysisRes['output_text'] ?? ''),
                            $analysisMaxOutputTokens
                        );
                        $addUsage($analysisUsage);
                        if ($analysisRaw !== null) {
                            file_put_contents($rawJsonlAbs, json_encode(['offer_id' => $offerId, 'step' => 'analysis', 'usage' => $analysisUsage, 'raw' => $analysisRaw], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
                        }
                        $analysis = supplier_products_db_tnved_normalize_analysis(supplier_products_db_extract_json_object((string)($analysisRes['output_text'] ?? '')));
	                        if ($analysis['product_role'] !== '' || $analysis['likely_headings'] || $analysis['include_terms']) {
	                            $payload['analysis'] = $analysis;
	                            $analysisSearchText = supplier_products_db_tnved_search_text_with_analysis(
	                                $payload,
	                                $analysis,
	                                (array)($payload['classification_hints'] ?? [])
	                            );
	                            $payload['tnved_profile'] = supplier_products_db_tnved_profile_prompt(
	                                supplier_products_db_tnved_product_profile($analysisSearchText, $analysis)
	                            );
	                            $payload['target_attributes'] = array_map(
	                                static fn(array $target): array => supplier_products_db_tnved_target_prompt(
	                                    $target,
                                    $analysisSearchText,
                                    $allowedValuesLimit,
                                    (array)($payload['supplier_category_memory'] ?? [])
                                ),
                                (array)($job['targets'] ?? [])
                            );
                        }
                    } catch (Throwable $e) {
                        $analysisErrors++;
                        $analysisError = $e->getMessage();
                        $log("tnved analysis skipped offer={$offerId}: " . $e->getMessage() . "\n");
                    }
                }

                $inputJson = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                if ($inputJson === false) {
                    $inputJson = '{"product":{}}';
                }
                $mainUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $inputJson;
                $mainMaxOutputTokens = 620;
                $mainEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $mainUserMessage, $mainMaxOutputTokens, 0.5);
                $addEstimate($mainEstimate);

                $res = $client->generateText($model, $mainUserMessage, $prompt, [
                    'prompt_cache_key' => 'fill_tnved:' . substr(hash('sha256', json_encode([
                        'supplier_category' => $payload['product']['supplier_category'] ?? [],
                        'marketplace_categories' => array_map(static fn(array $row): string => (string)($row['full_path'] ?? ''), (array)($payload['marketplace_categories'] ?? [])),
                        'target_attributes' => array_map(static fn(array $row): string => (string)($row['marketplace'] ?? '') . ':' . (string)($row['attribute_name'] ?? '') . ':' . (string)($row['allowed_values_count'] ?? ''), (array)($payload['target_attributes'] ?? [])),
                        'analysis' => $analysis,
                    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                    'text' => ['format' => ['type' => 'json_object']],
                    'max_output_tokens' => $mainMaxOutputTokens,
                ]);
                $rawText = trim((string)($res['output_text'] ?? ''));
                $raw = is_array($res['raw'] ?? null) ? $res['raw'] : null;
                $usage = supplier_products_db_merge_llm_usage_with_estimate(
                    $cfg,
                    $model,
                    $raw,
                    $prompt,
                    $mainUserMessage,
                    $rawText,
                    $mainMaxOutputTokens
                );
                $addUsage($usage);
                if ($raw !== null) {
                    file_put_contents($rawJsonlAbs, json_encode(['offer_id' => $offerId, 'step' => 'decision', 'usage' => $usage, 'raw' => $raw], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
                }

	                $decoded = supplier_products_db_extract_json_object($rawText);
	                $decision = supplier_products_db_tnved_decision_from_decoded($decoded);
	                $guard = supplier_products_db_tnved_apply_profile_guard(
	                    $decision,
	                    supplier_products_db_tnved_search_text_with_analysis($payload, $analysis, (array)($payload['classification_hints'] ?? [])),
	                    $analysis
	                );
	                $decision = (array)$guard['decision'];
	                if (!empty($guard['changed'])) {
	                    $decoded['system_profile_guard'][] = $guard;
	                    $profileGuardApplied++;
	                }
	                $confidence = (float)($decision['confidence'] ?? 0);
	                $code = (string)($decision['tnved_code'] ?? '');
	                $suggestedValue = (string)($decision['marketplace_value'] ?? $code);

                if ($code === '') {
                    $forceReason = 'no_code';
                    $noCode++;
                    $forcedNoCode++;
                } elseif ($confidence < $minConfidence) {
                    $lowConfidence++;
                    if ($forceLowConfidence) {
                        $forceReason = 'low_confidence';
                        $forcedLowConfidence++;
                    }
                }

                if ($forceReason === '' && $verifyDecisions) {
                    try {
                    $verificationRequest = [
                        'mode' => 'tnved_verify',
                        'product' => $payload['product'] ?? [],
                        'analysis' => $analysis,
                        'marketplace_categories' => $payload['marketplace_categories'] ?? [],
                        'supplier_category_memory' => $payload['supplier_category_memory'] ?? [],
                        'target_attributes' => $payload['target_attributes'] ?? [],
                        'decision' => $decision,
                        'instruction' => 'Проверь выбранный код независимо. Одобряй только если код соответствует именно товарной роли: готовый товар, запчасть, аксессуар, материал, расходник. Если код сомнителен, approved=false.',
                    ];
                    $verificationJson = json_encode($verificationRequest, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                    if ($verificationJson === false) {
                        $verificationJson = '{"mode":"tnved_verify","decision":{}}';
                    }
                    $verificationUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $verificationJson;
                    $verificationMaxOutputTokens = 560;
                    $verificationEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $verificationUserMessage, $verificationMaxOutputTokens, 0.5);
                    $addEstimate($verificationEstimate);
                    $verificationRequests++;

                    $verificationRes = $client->generateText($model, $verificationUserMessage, $prompt, [
                        'prompt_cache_key' => 'fill_tnved_verify:' . substr(hash('sha256', json_encode([
                            'supplier_category' => $payload['product']['supplier_category'] ?? [],
                            'analysis' => $analysis,
                            'code' => $code,
                            'memory' => array_column((array)($payload['supplier_category_memory'] ?? []), 'code'),
                        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                        'text' => ['format' => ['type' => 'json_object']],
                        'max_output_tokens' => $verificationMaxOutputTokens,
                    ]);
                    $verificationRaw = is_array($verificationRes['raw'] ?? null) ? $verificationRes['raw'] : null;
                    $verificationUsage = supplier_products_db_merge_llm_usage_with_estimate(
                        $cfg,
                        $model,
                        $verificationRaw,
                        $prompt,
                        $verificationUserMessage,
                        (string)($verificationRes['output_text'] ?? ''),
                        $verificationMaxOutputTokens
                    );
                    $addUsage($verificationUsage);
                    if ($verificationRaw !== null) {
                        file_put_contents($rawJsonlAbs, json_encode(['offer_id' => $offerId, 'step' => 'verification', 'usage' => $verificationUsage, 'raw' => $verificationRaw], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
                    }
	                    $verification = supplier_products_db_tnved_verification_decision(supplier_products_db_extract_json_object((string)($verificationRes['output_text'] ?? '')));
	                    $decision = supplier_products_db_tnved_apply_verification_to_decision($decision, $verification, $verificationConfidence);
	                    $guard = supplier_products_db_tnved_apply_profile_guard(
	                        $decision,
	                        supplier_products_db_tnved_search_text_with_analysis($payload, $analysis, (array)($payload['classification_hints'] ?? [])),
	                        $analysis
	                    );
	                    $decision = (array)$guard['decision'];
	                    if (!empty($guard['changed'])) {
	                        $decoded['system_profile_guard'][] = $guard;
	                        $profileGuardApplied++;
	                    }
	                    $decoded['verification'] = $decision['verification'] ?? $verification;
	                    if (!empty($decision['verification_rejected'])) {
                        $forceReason = 'verification_rejected';
                        $forcedVerification++;
                        $verificationRejected++;
                    } elseif (!empty($decision['verification_corrected'])) {
                        $verificationCorrected++;
                    } elseif (!empty($decision['verification_approved'])) {
                        $verificationApproved++;
                    }
                    $confidence = (float)($decision['confidence'] ?? 0);
                    $code = (string)($decision['tnved_code'] ?? $code);
                    $suggestedValue = (string)($decision['marketplace_value'] ?? $suggestedValue);
                } catch (Throwable $e) {
                    $verificationErrors++;
                    $verificationError = $e->getMessage();
                    $log("tnved verification skipped offer={$offerId}: " . $e->getMessage() . "\n");
                }
            }

            if ($forceReason !== '' && $forceDecision) {
                try {
                    $forceRequest = [
                        'mode' => 'tnved_force_decision',
                        'product' => $payload['product'] ?? [],
                        'analysis' => $analysis,
                        'marketplace_categories' => $payload['marketplace_categories'] ?? [],
                        'supplier_category_memory' => $payload['supplier_category_memory'] ?? [],
                        'target_attributes' => $payload['target_attributes'] ?? [],
                        'previous_decision' => $decision,
                        'verification' => $verification,
                        'force_reason' => $forceReason,
                        'instruction' => 'Выбери лучший возможный 10-значный код. Не возвращай пустой код. Если есть риск, поставь review_required=true и перечисли risk_flags, но всё равно верни код.',
                    ];
                    $forceJson = json_encode($forceRequest, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                    if ($forceJson === false) {
                        $forceJson = '{"mode":"tnved_force_decision","product":{}}';
                    }
                    $forceUserMessage = "Ниже входной JSON. Верни только JSON-объект ответа.\n\n" . $forceJson;
                    $forceMaxOutputTokens = 620;
                    $forceEstimate = supplier_products_db_estimate_llm_request_usage($cfg, $model, $prompt, $forceUserMessage, $forceMaxOutputTokens, 0.5);
                    $addEstimate($forceEstimate);
                    $forceRequests++;

                    $forceRes = $client->generateText($model, $forceUserMessage, $prompt, [
                        'prompt_cache_key' => 'fill_tnved_force:' . substr(hash('sha256', json_encode([
                            'supplier_category' => $payload['product']['supplier_category'] ?? [],
                            'analysis' => $analysis,
                            'previous_code' => $code,
                            'force_reason' => $forceReason,
                            'memory' => array_column((array)($payload['supplier_category_memory'] ?? []), 'code'),
                        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                        'text' => ['format' => ['type' => 'json_object']],
                        'max_output_tokens' => $forceMaxOutputTokens,
                    ]);
                    $forceRaw = is_array($forceRes['raw'] ?? null) ? $forceRes['raw'] : null;
                    $forceUsage = supplier_products_db_merge_llm_usage_with_estimate(
                        $cfg,
                        $model,
                        $forceRaw,
                        $prompt,
                        $forceUserMessage,
                        (string)($forceRes['output_text'] ?? ''),
                        $forceMaxOutputTokens
                    );
                    $addUsage($forceUsage);
                    if ($forceRaw !== null) {
                        file_put_contents($rawJsonlAbs, json_encode(['offer_id' => $offerId, 'step' => 'force_decision', 'usage' => $forceUsage, 'raw' => $forceRaw], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);
                    }
                    $forceDecoded = supplier_products_db_extract_json_object((string)($forceRes['output_text'] ?? ''));
                    $forcedDecision = supplier_products_db_tnved_decision_from_decoded($forceDecoded);
	                    if ((string)($forcedDecision['tnved_code'] ?? '') !== '') {
	                        $decision = $forcedDecision;
	                        $guard = supplier_products_db_tnved_apply_profile_guard(
	                            $decision,
	                            supplier_products_db_tnved_search_text_with_analysis($payload, $analysis, (array)($payload['classification_hints'] ?? [])),
	                            $analysis
	                        );
	                        $decision = (array)$guard['decision'];
	                        $decoded['forced_decision'] = $forceDecoded;
	                        if (!empty($guard['changed'])) {
	                            $decoded['system_profile_guard'][] = $guard;
	                            $profileGuardApplied++;
	                        }
	                        $code = (string)($decision['tnved_code'] ?? '');
	                        $confidence = (float)($decision['confidence'] ?? 0);
                        $suggestedValue = (string)($decision['marketplace_value'] ?? $code);
                    }
                } catch (Throwable $e) {
                    $forceErrors++;
                    $forceError = $e->getMessage();
                    $log("tnved force decision failed offer={$offerId}: " . $e->getMessage() . "\n");
                }
            }

            if ($code === '') {
                foreach ((array)($payload['supplier_category_memory'] ?? []) as $memoryRow) {
                    if (!is_array($memoryRow)) {
                        continue;
                    }
                    $memoryCode = supplier_products_db_tnved_code_from_text((string)($memoryRow['code'] ?? ''));
                    if ($memoryCode !== '' && supplier_products_db_tnved_non_leaf_reason($memoryCode) === '') {
                        $code = $memoryCode;
                        $suggestedValue = $memoryCode;
                        $confidence = min(0.61, max(0.5, (float)($memoryRow['share'] ?? 0.5)));
                        $decision['tnved_code'] = $code;
                        $decision['marketplace_value'] = $memoryCode;
                        $decision['confidence'] = $confidence;
                        $decision['review_required'] = true;
                        $decision['reason'] = 'Fallback по памяти категории поставщика после неудачного выбора GPT.';
                        $decoded['memory_fallback_decision'] = $decision;
                        break;
                    }
                }
            }
            }

            $reviewRequired = $forceReason !== ''
                || !empty($decision['review_required'])
                || $confidence < $minConfidence
                || !empty($decision['verification_rejected']);
            if ($reviewRequired) {
                $reviewReason = trim(implode('; ', array_filter([
                    $forceReason !== '' ? 'forced: ' . $forceReason : '',
                    (string)($decision['reason'] ?? ''),
                    $verificationError !== '' ? 'verification error: ' . $verificationError : '',
                    $forceError !== '' ? 'force error: ' . $forceError : '',
                ])));
                $reviewRequiredCount++;
                $reviewCounted = true;
            }

            if (!$fastDecision
                && $signatureReuse
                && $signatureKey !== ''
                && $code !== ''
                && !$reviewRequired
                && $confidence >= $minConfidence
                && !isset($signatureDecisionByKey[$signatureKey])
            ) {
                $signatureDecisionByKey[$signatureKey] = [
                    'tnved_code' => $code,
                    'marketplace_value' => $suggestedValue,
                    'confidence' => $confidence,
                    'review_required' => false,
                    'risk_flags' => (array)($decision['risk_flags'] ?? []),
                    'alternatives' => (array)($decision['alternatives'] ?? []),
                    'reason' => 'Переиспользовано решение для сигнатуры товара: ' . (string)($job['signature_title'] ?? ''),
                ];
                $signatureCacheWrites++;
            }

            if ($groupReuse
                && $groupKey !== ''
                && $code !== ''
                && !$reviewRequired
                && $confidence >= $minConfidence
                && !isset($groupDecisionByKey[$groupKey])
            ) {
                $groupCandidate = [
                    'tnved_code' => $code,
                    'marketplace_value' => $suggestedValue,
                    'confidence' => $confidence,
                    'review_required' => false,
                    'risk_flags' => (array)($decision['risk_flags'] ?? []),
                    'alternatives' => (array)($decision['alternatives'] ?? []),
                    'reason' => 'Переиспользовано групповое решение ТН ВЭД: ' . (string)($job['tnved_group_label'] ?? ''),
                ];
                $groupApplicable = supplier_products_db_tnved_group_decision_applicable_to_job(
                    $groupCandidate,
                    $job,
                    $payload,
                    $minConfidence
                );
                if (!empty($groupApplicable['ok'])) {
                    $groupDecisionByKey[$groupKey] = (array)($groupApplicable['decision'] ?? $groupCandidate);
                    $groupCacheWrites++;
                }
            }

            if ($code === '') {
                $status = 'error';
                $error = 'Не удалось получить 10-значный код ТН ВЭД даже в принудительном режиме';
                $failed++;
            } else {
                $finalTnvedCode = $code;
                foreach ((array)($job['targets'] ?? []) as $target) {
                    if (!is_array($target)) {
                        continue;
                    }
                    $resolved = supplier_products_db_tnved_marketplace_value($code, $suggestedValue, $target, (string)($job['tnved_search_text'] ?? ''));
                    if (trim((string)($resolved['value'] ?? '')) === ''
                        && (string)($target['source'] ?? '') === 'ozon'
                        && function_exists('supplier_market_row_characteristic_allowed_values_for_product')) {
                        try {
                            $searchedAllowed = supplier_market_row_characteristic_allowed_values_for_product(
                                (int)$job['product_id'],
                                'ozon',
                                (string)($target['name'] ?? ''),
                                $cfg,
                                0,
                                $code
                            );
                            if ($searchedAllowed) {
                                $target['allowed_values'] = array_values(array_unique(array_merge((array)($target['allowed_values'] ?? []), $searchedAllowed)));
                                $resolved = supplier_products_db_tnved_marketplace_value($code, $suggestedValue, $target, (string)($job['tnved_search_text'] ?? ''));
                            }
                        } catch (Throwable $e) {
                            // Оставим исходную ошибку справочника в отчете.
                        }
                    }
                    $value = trim((string)($resolved['value'] ?? ''));
                    $forcedDictionaryMismatch = false;
                    if ($value === '') {
                        $notInDictionary++;
                        $targetSource = (string)($target['source'] ?? '');
                        $targetRequiresDictionary = !empty($target['requires_dictionary']) || supplier_products_db_tnved_target_requires_dictionary($target);
                        if ((string)($resolved['error'] ?? '') === 'non_leaf_tnved_code') {
                            $reviewRequired = true;
                            if (!$reviewCounted) {
                                $reviewRequiredCount++;
                                $reviewCounted = true;
                            }
                            if ($reviewReason !== '') {
                                $reviewReason .= '; ';
                            }
                            $reviewReason .= $targetSource . ': код ' . $code . ' является родительским/обобщенным, значение не записано';
                            $acceptedRows[] = [
                                'marketplace' => $targetSource,
                                'kind' => (string)($target['kind'] ?? ''),
                                'name' => (string)($target['name'] ?? ''),
                                'value' => '',
                                'tnved_code' => $code,
                                'confidence' => round($confidence, 3),
                                'validated_by_dictionary' => false,
                                'dictionary_missing_fallback' => false,
                                'dictionary_mismatch_forced' => false,
                                'fallback_target' => !empty($target['fallback_target']),
                                'review_required' => true,
                                'review_reason' => acp_trunc($reviewReason, 320),
                                'decision_source' => $fastSource !== '' ? $fastSource : 'llm',
                                'status' => 'skipped_non_leaf',
                            ];
                            continue;
                        }
                        if ($targetRequiresDictionary) {
                            $reviewRequired = true;
                            if (!$reviewCounted) {
                                $reviewRequiredCount++;
                                $reviewCounted = true;
                            }
                            if ($reviewReason !== '') {
                                $reviewReason .= '; ';
                            }
                            $resolvedError = trim((string)($resolved['error'] ?? ''));
                            $reviewReason .= ($targetSource !== '' ? $targetSource : 'target') . ': код не найден в словаре ТН ВЭД этой категории, значение не записано'
                                . ($resolvedError !== '' ? ' (' . $resolvedError . ')' : '');
                            $acceptedRows[] = [
                                'marketplace' => $targetSource,
                                'kind' => (string)($target['kind'] ?? ''),
                                'name' => (string)($target['name'] ?? ''),
                                'value' => '',
                                'tnved_code' => $code,
                                'confidence' => round($confidence, 3),
                                'validated_by_dictionary' => false,
                                'dictionary_missing_fallback' => false,
                                'dictionary_mismatch_forced' => false,
                                'fallback_target' => !empty($target['fallback_target']),
                                'review_required' => true,
                                'review_reason' => acp_trunc($reviewReason, 320),
                                'decision_source' => $fastSource !== '' ? $fastSource : 'llm',
                                'status' => 'skipped_dictionary',
                            ];
                            continue;
                        }
                        $value = $code;
                        $forcedDictionaryMismatch = true;
                        $dictionaryMismatchForced++;
                        $reviewRequired = true;
                        if (!$reviewCounted) {
                            $reviewRequiredCount++;
                            $reviewCounted = true;
                        }
                        if ($reviewReason !== '') {
                            $reviewReason .= '; ';
                        }
                        $reviewReason .= (string)($target['source'] ?? '') . ': код не найден в полном справочнике, записан raw code';
                    }
                    if (!empty($resolved['validated'])) {
                        $validatedDictionary++;
                    }
                    if (!empty($resolved['dictionary_missing_fallback'])) {
                        $dictionaryMissingFallback++;
                    }
                    $acceptedRows[] = [
                        'marketplace' => (string)($target['source'] ?? ''),
                        'kind' => (string)($target['kind'] ?? ''),
                        'name' => (string)($target['name'] ?? ''),
                        'value' => $value,
                        'tnved_code' => $code,
                        'confidence' => round($confidence, 3),
                        'validated_by_dictionary' => !empty($resolved['validated']),
                        'dictionary_missing_fallback' => !empty($resolved['dictionary_missing_fallback']),
                        'dictionary_mismatch_forced' => $forcedDictionaryMismatch,
                        'fallback_target' => !empty($target['fallback_target']),
                        'review_required' => $reviewRequired,
                        'review_reason' => acp_trunc($reviewReason, 320),
                        'decision_source' => $fastSource !== '' ? $fastSource : 'llm',
                        'status' => 'accepted',
                    ];
                }
            }
        } catch (Throwable $e) {
            $status = 'error';
            $error = $e->getMessage();
            $failed++;
            if ($firstLlmError === '') {
                $firstLlmError = $error;
            }
        }

        file_put_contents($outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json', json_encode([
            'offer_id' => $offerId,
            'status' => $status,
            'error' => $error,
            'payload' => $payload,
            'analysis' => $analysis,
            'analysis_error' => $analysisError,
            'gpt_output' => $decoded,
            'verification' => $verification,
            'verification_error' => $verificationError,
            'force_reason' => $forceReason,
            'force_decision_output' => $forceDecoded,
            'force_error' => $forceError,
            'review_required' => $reviewRequired,
            'review_reason' => $reviewReason,
            'accepted_rows' => $acceptedRows,
            'analysis_estimate' => $analysisEstimate,
            'main_estimate' => $mainEstimate,
            'verification_estimate' => $verificationEstimate,
            'force_estimate' => $forceEstimate,
            'analysis_usage' => $analysisUsage,
            'verification_usage' => $verificationUsage,
            'force_usage' => $forceUsage,
            'usage' => $usage,
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT));
        file_put_contents($resultsJsonlAbs, json_encode([
            'offer_id' => $offerId,
            'status' => $status,
            'error' => $error,
            'analysis' => $analysis,
            'gpt_output' => $decoded,
            'verification' => $verification,
            'force_reason' => $forceReason,
            'force_decision_output' => $forceDecoded,
            'review_required' => $reviewRequired,
            'review_reason' => $reviewReason,
            'accepted_rows' => $acceptedRows,
            'usage' => $usage,
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n", FILE_APPEND);

        if ($status !== 'ok') {
            continue;
        }

        $hasOzonTarget = false;
        $hasAcceptedOzonTarget = false;
        foreach ((array)($job['targets'] ?? []) as $target) {
            if (is_array($target) && (string)($target['source'] ?? '') === 'ozon') {
                $hasOzonTarget = true;
                break;
            }
        }
        foreach ($acceptedRows as $acceptedRow) {
            if ((string)($acceptedRow['status'] ?? '') === 'accepted'
                && (string)($acceptedRow['marketplace'] ?? '') === 'ozon') {
                $hasAcceptedOzonTarget = true;
                break;
            }
        }
        $canWriteStandardCode = !$hasOzonTarget || $hasAcceptedOzonTarget;

        if ($canWriteStandardCode
            && $finalTnvedCode !== ''
            && supplier_products_db_tnved_non_leaf_reason($finalTnvedCode) === '') {
            if ($overwrite) {
                $clearedValues = supplier_products_db_clear_tnved_fields_for_product(
                    db(),
                    $supplierId,
                    (int)$job['product_id']
                );
                if ($clearedValues > 0) {
                    $overwriteProductsCleared++;
                    $overwriteValuesCleared += $clearedValues;
                    $changedProducts[(int)$job['product_id']] = true;
                }
            }
            if (supplier_products_set_standard_field_value(db(), $supplierId, (int)$job['product_id'], supplier_products_tnved_standard_field_name(), $finalTnvedCode)) {
                $standardTnvedChanged++;
                $changedProducts[(int)$job['product_id']] = true;
            }
        }

        $targetByKey = [];
        foreach ((array)($job['targets'] ?? []) as $target) {
            if (is_array($target)) {
                $targetByKey[supplier_products_db_tnved_target_key($target)] = $target;
            }
        }

        foreach ($acceptedRows as $row) {
            $targetKey = (string)($row['kind'] ?? '') . "\n" . supplier_products_db_attr_norm((string)($row['name'] ?? ''));
            $target = (array)($targetByKey[$targetKey] ?? []);
            $targetRequiresDictionary = $target && supplier_products_db_tnved_target_requires_dictionary($target);
            $existingTargetValue = trim((string)(($job['existing_by_target'] ?? [])[$targetKey] ?? ''));
            if (($row['status'] ?? '') !== 'accepted') {
                if ($targetRequiresDictionary
                    && $existingTargetValue !== ''
                    && !supplier_products_db_tnved_existing_target_value_is_valid($target, $existingTargetValue)) {
                    $changed = supplier_products_db_delete_param_values(
                        db(),
                        $supplierId,
                        (int)$job['product_id'],
                        (string)$row['kind'],
                        (string)$row['name']
                    );
                    if ($changed) {
                        $changedProducts[(int)$job['product_id']] = true;
                    }
                }
                continue;
            }
            if ($targetRequiresDictionary && empty($row['validated_by_dictionary'])) {
                continue;
            }
            $existingTargetCode = supplier_products_db_tnved_code_from_text($existingTargetValue);
            $replaceExistingInvalid = $targetRequiresDictionary
                ? ($existingTargetValue !== '' && !supplier_products_db_tnved_existing_target_value_is_valid($target, $existingTargetValue))
                : ($existingTargetValue !== '' && ($existingTargetCode === '' || supplier_products_db_tnved_non_leaf_reason($existingTargetCode) !== ''));
            $changed = ($overwrite || $replaceExistingInvalid)
                ? supplier_products_db_set_param_value(db(), $supplierId, (int)$job['product_id'], (string)$row['kind'], (string)$row['name'], (string)$row['value'])
                : supplier_products_db_add_param_if_missing(db(), $supplierId, (int)$job['product_id'], (string)$row['kind'], (string)$row['name'], (string)$row['value']);
            if ($changed) {
                $inserted++;
                $changedProducts[(int)$job['product_id']] = true;
            }
        }
    }

    supplier_products_db_fail_if_llm_unavailable(
        'gpt_fill_tnved_codes',
        count($jobs),
        $failed,
        $tokensInTotal,
        $tokensOutTotal,
        $firstLlmError
    );

    if ($overwrite) {
        $log("overwrite replace: products={$overwriteProductsCleared}, removed_values={$overwriteValuesCleared}\n");
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId);
    $costTotal = round($costTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costTotal);
    $estimatedExpectedCostTotal = round($estimatedExpectedCostTotal, 6);
    $estimatedMaxCostTotal = round($estimatedMaxCostTotal, 6);
    $estimatedExpectedCostLabel = supplier_products_db_cost_label($cfg, $model, $estimatedExpectedCostTotal);
    $estimatedMaxCostLabel = supplier_products_db_cost_label($cfg, $model, $estimatedMaxCostTotal);
    $log("TOTAL usage: input={$tokensInTotal}, cached_input={$tokensCachedTotal}, output={$tokensOutTotal}\n");
    $log("TOTAL cost ({$model}): {$costLabel}\n");
    $log("ESTIMATED requests={$estimatedRequests}, input={$estimatedInputTokensTotal}, expected_output={$estimatedExpectedOutputTokensTotal}, max_output={$estimatedMaxOutputTokensTotal}, expected_cost={$estimatedExpectedCostLabel}, max_cost={$estimatedMaxCostLabel}\n");

    $report = [
        'title' => 'gpt_fill_tnved_codes',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'inserted_values' => $inserted,
            'standard_tnved_changed' => $standardTnvedChanged,
            'standard_tnved_migrated' => $standardTnvedMigrated,
            'standard_tnved_already_filled' => $standardTnvedAlreadyFilled,
            'overwrite_products_cleared' => $overwriteProductsCleared,
            'overwrite_values_cleared' => $overwriteValuesCleared,
            'overwrite_values_ignored_during_calculation' => $overwriteValuesIgnored,
            'products_changed' => count($changedProducts),
            'validated_by_dictionary' => $validatedDictionary,
            'dictionary_missing_fallback' => $dictionaryMissingFallback,
            'dictionary_missing_targets' => $dictionaryMissingTargets,
            'supplier_category_memory_groups' => count($tnvedMemoryBySupplierCategory),
            'analysis_requests' => $analysisRequests,
            'analysis_errors' => $analysisErrors,
