            'estimated_input_tokens' => $estimatedInputTokensTotal,
            'estimated_expected_output_tokens' => $estimatedExpectedOutputTokensTotal,
            'estimated_max_output_tokens' => $estimatedMaxOutputTokensTotal,
            'estimated_expected_cost' => $estimatedExpectedCostTotal,
            'estimated_expected_cost_label' => $estimatedExpectedCostLabel,
            'estimated_max_cost' => $estimatedMaxCostTotal,
            'estimated_max_cost_label' => $estimatedMaxCostLabel,
        ] + supplier_products_db_cost_fields($cfg, $model, $costTotal),
        'dataset' => $dataset,
        'params_effective' => [
            'model' => $model,
            'overwrite' => $overwrite ? 1 : 0,
            'min_confidence' => $minConfidence,
            'analysis_prepass' => $analysisPrepass ? 1 : 0,
            'verify_decisions' => $verifyDecisions ? 1 : 0,
            'force_decision' => $forceDecision ? 1 : 0,
            'force_low_confidence' => $forceLowConfidence ? 1 : 0,
            'verification_confidence' => $verificationConfidence,
            'signature_reuse' => $signatureReuse ? 1 : 0,
            'group_reuse' => $groupReuse ? 1 : 0,
            'memory_auto_fill' => $memoryAutoFill ? 1 : 0,
            'memory_category_auto_fill' => $memoryCategoryAutoFill ? 1 : 0,
