    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['tnved_results_jsonl'] = rel_to_outputs($cfg, $resultsJsonlAbs);
    $outputs['tnved_raw_jsonl'] = rel_to_outputs($cfg, $rawJsonlAbs);
    $outputs['tnved_category_shortlists_json'] = rel_to_outputs($cfg, $categoryPlansJsonAbs);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_fill_tnved_codes',
        'items' => [
            'Jobs: ' . count($jobs),
            'Inserted values: ' . $inserted,
            'Standard TNVED changed: ' . $standardTnvedChanged,
            'Standard TNVED migrated: ' . $standardTnvedMigrated,
            'Standard TNVED already filled: ' . $standardTnvedAlreadyFilled,
            'Validated by dictionary: ' . $validatedDictionary,
            'Dictionary missing fallback: ' . $dictionaryMissingFallback,
            'Dictionary missing targets: ' . $dictionaryMissingTargets,
            'Analysis requests: ' . $analysisRequests,
            'Verification requests: ' . $verificationRequests,
            'Verification approved: ' . $verificationApproved,
            'Verification rejected: ' . $verificationRejected,
            'Verification corrected: ' . $verificationCorrected,
            'Force decision requests: ' . $forceRequests,
            'Force decision errors: ' . $forceErrors,
            'Signature groups: ' . count($signatureKeyCounts),
            'Signature reuse potential: ' . $signatureReusePotential,
            'TNVED groups: ' . count($groupKeyCounts),
            'TNVED group reuse potential: ' . $groupReusePotential,
            'TNVED category scopes: ' . count($categoryShortlistPlans),
            'TNVED category shortlist codes: ' . $categoryShortlistCodes,
            'Category group plan requests: ' . $categoryGroupPlanRequests,
            'Category group plan accepted: ' . $categoryGroupPlanAccepted,
            'Category group plan rejected: ' . $categoryGroupPlanRejected,
            'Category group plan products covered: ' . $categoryGroupPlanProductsCovered,
            'Memory auto candidates: ' . $memoryAutoCandidates,
            'Memory stable candidates: ' . $memoryStableCandidates,
            'Memory signature candidates: ' . $memorySignatureCandidates,
            'Memory auto applied: ' . $memoryAutoApplied,
            'Memory auto rejected: ' . $memoryAutoRejected,
            'Memory stable applied: ' . $memoryStableApplied,
            'Memory signature applied: ' . $memorySignatureApplied,
            'Signature reused: ' . $signatureReused,
            'Signature cache writes: ' . $signatureCacheWrites,
            'TNVED group reused: ' . $groupReused,
            'TNVED group reuse rejected: ' . $groupReuseRejected,
            'TNVED group cache writes: ' . $groupCacheWrites,
            'Allowed values targets: ' . $allowedValuesTargets,
            'Allowed values original/prompt: ' . $allowedValuesOriginalTotal . '/' . $allowedValuesPromptTotal,
            'Allowed values prompt bytes: ' . $allowedValuesPromptBytes,
            'Allowed values weak shortlists: ' . $allowedValuesWeakShortlists,
            'Allowed values incompatible filtered: ' . $allowedValuesIncompatibleFiltered,
	            'Review required: ' . $reviewRequiredCount,
	            'Dictionary mismatch forced: ' . $dictionaryMismatchForced,
	            'System profile guard applied: ' . $profileGuardApplied,
	            'Missing real target fallback: ' . $missingRealTargetFallback,
            'Fallback targets used: ' . $fallbackTargetsUsed,
            'Skipped no target: 0',
            'Skipped dictionary missing: ' . $skippedDictionaryMissing,
            'Skipped already filled: ' . $skippedFilled,
            'Initial no code forced: ' . $noCode,
            'Initial low confidence: ' . $lowConfidence,
            'Initial low confidence forced: ' . $forcedLowConfidence,
            'Skipped no code: 0',
            'Skipped low confidence: 0',
            'Skipped verification: 0',
            'Not in dictionary: ' . $notInDictionary,
            'Failed: ' . $failed,
            'Tokens in: ' . $tokensInTotal,
            'Tokens cached in: ' . $tokensCachedTotal,
            'Tokens out: ' . $tokensOutTotal,
            'Cost: ' . $costLabel,
            'Estimated expected cost: ' . $estimatedExpectedCostLabel,
            'Estimated max cost: ' . $estimatedMaxCostLabel,
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_same_model_is_code_token(string $value): bool
{
    $value = trim($value);
    if ($value === '') {
        return false;
    }
    return (bool)preg_match('~^(?=.*\d)[\p{L}\p{N}][\p{L}\p{N}._#\-]{1,40}$~u', $value);
}

function supplier_products_db_same_model_first_value(string $value): string
{
    $value = trim(preg_replace('/\s+/u', ' ', $value) ?? $value);
    if ($value === '') {
        return '';
    }

    $parts = preg_split('~\s*(?:/|;|\||,|\R|\s+\+\s+|\s+и\s+)\s*~iu', $value, -1, PREG_SPLIT_NO_EMPTY) ?: [];
    if (count($parts) > 1) {
        foreach ($parts as $part) {
            $part = trim((string)$part, " \t\n\r\0\x0B.,;:/|+");
            if ($part !== '') {
                return mb_substr($part, 0, 120, 'UTF-8');
            }
        }
    }

    $tokens = preg_split('/\s+/u', $value, -1, PREG_SPLIT_NO_EMPTY) ?: [];
    if (count($tokens) > 1) {
        $allModelCodes = true;
        foreach ($tokens as $token) {
            if (!supplier_products_db_same_model_is_code_token((string)$token)) {
                $allModelCodes = false;
                break;
            }
        }
        if ($allModelCodes) {
            return mb_substr((string)$tokens[0], 0, 120, 'UTF-8');
        }
    }

    return mb_substr($value, 0, 120, 'UTF-8');
}

function supplier_products_db_same_model_param_candidate(array $job): string
{
    $product = (array)($job['product'] ?? []);
    $params = (array)($product['params'] ?? []);
    $priority = [
        'маркировка аккумулятора',
        'модель аккумулятора',
        'модель товара',
        'название модели',
        'модель',
    ];
    foreach ($priority as $wantedName) {
        foreach ($params as $param) {
            if (!is_array($param)) {
                continue;
            }
            $name = supplier_products_db_attr_norm((string)($param['name'] ?? ''));
            if ($name !== $wantedName) {
                continue;
            }
            $candidate = supplier_products_db_same_model_first_value((string)($param['value'] ?? ''));
            if ($candidate !== '') {
                return $candidate;
            }
        }
    }
    return '';
}

function supplier_products_db_same_model_clean_core(string $core, array $job): string
{
    $paramCandidate = supplier_products_db_same_model_param_candidate($job);
    if ($paramCandidate !== '') {
        return $paramCandidate;
    }
    return supplier_products_db_same_model_first_value($core);
}

function supplier_products_db_op_gpt_fill_same_model(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '1') !== '' && (string)($params['overwrite'] ?? '1') !== '0');
    $minGroup = max(1, (int)trim((string)($params['min_group_size'] ?? '1')));
    $minConfidence = (float)str_replace(',', '.', trim((string)($params['min_confidence'] ?? '0.76')));
    if ($minConfidence <= 0 || $minConfidence > 1) {
        $minConfidence = 0.76;
    }

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'fill_same_model_ru.txt');
    $log("supplier_db gpt_fill_same_model: model={$model}, max_items={$maxItems}, overwrite=" . ($overwrite ? '1' : '0') . ", min_group_size={$minGroup}, min_confidence={$minConfidence}\n");
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $normKey = static function (string $s): string {
        $s = mb_strtolower(trim($s), 'UTF-8');
        $s = str_replace('ё', 'е', $s);
        $s = preg_replace('~[^\p{L}\p{N}]+~u', '_', $s);
        $s = preg_replace('~_+~u', '_', (string)$s);
        $s = trim((string)$s, '_');
        if (mb_strlen($s, 'UTF-8') > 80) {
            $s = trim((string)mb_substr($s, 0, 80, 'UTF-8'), '_');
        }
        return $s;
    };
    $specificTokens = static function (string $s) use ($normKey): array {
        $out = [];
        if (preg_match_all('~[\p{L}]*\d[\p{L}\p{N}._#\/+\-*]*|[\p{L}\p{N}]+(?:[._#\/+\-*][\p{L}\p{N}]+)+~u', $s, $m)) {
            foreach ((array)($m[0] ?? []) as $token) {
                $key = $normKey((string)$token);
                if ($key !== '' && mb_strlen($key, 'UTF-8') >= 2) {
                    $out[$key] = true;
                }
            }
        }
        return array_keys($out);
    };
    $isGenericCore = static function (string $core, string $key, array $job) use ($normKey, $specificTokens): bool {
        $coreNorm = $normKey($core);
        $key = $normKey($key);
        if ($coreNorm === '' || $key === '' || mb_strlen($key, 'UTF-8') < 3) {
            return true;
        }
        $product = (array)($job['product'] ?? []);
        $brandKeys = [];
        foreach (['brand', 'vendor'] as $field) {
            $brandKey = $normKey((string)($product[$field] ?? ''));
            if ($brandKey !== '') {
                $brandKeys[$brandKey] = true;
            }
        }
        if (isset($brandKeys[$key]) || isset($brandKeys[$coreNorm])) {
            return true;
        }
        $generic = [
            'товар' => true,
            'изделие' => true,
            'аксессуар' => true,
            'аксессуары' => true,
            'комплект' => true,
            'набор' => true,
            'упаковка' => true,
            'запчасть' => true,
            'запчасти' => true,
            'деталь' => true,
            'детали' => true,
            'аккумулятор' => true,
            'батарея' => true,
            'зарядное_устройство' => true,
            'квадрокоптер' => true,
            'дрон' => true,
            'камера' => true,
            'объектив' => true,
            'пропеллер' => true,
            'саморезы' => true,
            'винты' => true,
            'кабель' => true,
            'провод' => true,
            'чехол' => true,
            'пульт' => true,
            'мотор' => true,
            'двигатель' => true,
            'плата' => true,
            'модуль' => true,
        ];
        if (isset($generic[$key]) || isset($generic[$coreNorm])) {
            return true;
        }
        $parts = array_values(array_filter(explode('_', $key), static fn($p): bool => $p !== ''));
        $hasSpecific = (bool)$specificTokens($core);
        if (!$hasSpecific) {
            $model = trim((string)($product['model'] ?? ''));
            $hasSpecific = $model !== '' && str_contains($normKey($model), $key);
        }
        if (!$hasSpecific && count($parts) <= 1) {
            return true;
        }
        if (!$hasSpecific && count($parts) <= 2 && count($brandKeys) > 0) {
            foreach (array_keys($brandKeys) as $brandKey) {
                if ($brandKey !== '' && str_starts_with($key, $brandKey . '_')) {
                    return true;
                }
            }
        }
        return false;
    };

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));

    $jobs = [];
    $seenProducts = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }
        $fields = $fieldsByProduct[$productId] ?? [];
        $existing = supplier_products_db_product_tag_value($fields, ['same_model']);
        if (!$overwrite && $existing !== '') {
            continue;
        }

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
        $cat = ft_load_combined_marketplace_category_context($ozonCategory, $wbCategory, false);
        $categoryKeyParts = [];
        foreach ([$ozonCategory, $wbCategory, (string)($product['category_id'] ?? '')] as $categoryPart) {
            $categoryPartKey = $normKey((string)$categoryPart);
            if ($categoryPartKey !== '') {
                $categoryKeyParts[$categoryPartKey] = true;
            }
        }
        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'product' => [
                'offer_id' => $offerId,
                'vendorCode' => (string)($product['vendor_code'] ?? ''),
                'name' => (string)($product['name'] ?? ''),
                'brand' => (string)($context['brand'] ?? ($product['brand'] ?? '')),
                'vendor' => (string)($context['vendor'] ?? ''),
                'model' => (string)($context['model'] ?? ''),
                'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 1800),
                'params' => supplier_products_db_product_params_payload($fields),
            ],
            'category' => $cat ? [
                'code' => (string)($cat['code'] ?? ''),
                'name' => (string)($cat['name'] ?? ''),
                'full_path' => (string)($cat['full_path'] ?? ''),
            ] : new stdClass(),
            'category_key' => implode('_', array_keys($categoryKeyParts)),
        ];
        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
    }

    $log("scan: products_seen={$seenProducts}, jobs=" . count($jobs) . "\n");

    $results = [];
    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $done = 0;
    $jobsInitial = count($jobs);
    $directCandidates = 0;
    foreach ($jobs as $offerId => $job) {
        $directCore = supplier_products_db_same_model_param_candidate($job);
        if ($directCore === '') {
            continue;
        }
        $directCore = supplier_products_db_same_model_first_value($directCore);
        $directKey = $normKey($directCore);
        if ($directCore === '' || $directKey === '' || $isGenericCore($directCore, $directKey, $job)) {
            continue;
        }
        $productPayload = (array)($job['product'] ?? []);
        $brandKey = $normKey((string)(($productPayload['brand'] ?? '') ?: ($productPayload['vendor'] ?? '')));
        $results[$offerId] = [
            'product_id' => (int)($job['product_id'] ?? 0),
            'status' => 'ok',
            'core' => $directCore,
            'key' => $directKey,
            'confidence' => 0.96,
            'type_key' => '',
            'brand_key' => $brandKey,
            'category_key' => (string)($job['category_key'] ?? ''),
            'reason' => 'модель взята из явной характеристики товара',
            'error' => '',
            'usage' => ['input' => 0, 'cached_input' => 0, 'output' => 0],
        ];
        unset($jobs[$offerId]);
        $directCandidates++;
    }
    if ($directCandidates > 0) {
        $log("direct model candidates: {$directCandidates}; gpt_jobs=" . count($jobs) . "\n");
    }
    $gptTotal = max(1, count($jobs));
    $client = count($jobs) > 0 ? LLM::client($cfg, $model) : null;

    foreach ($jobs as $offerId => $job) {
        $done++;
        ops_update_progress($opId, $done, $gptTotal, 'gpt', "GPT {$done}/{$gptTotal} offer={$offerId}");
        $payload = [
            'product' => $job['product'] ?? [],
            'category' => $job['category'] ?? new stdClass(),
        ];
        $inputJson = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($inputJson === false) {
            $inputJson = '{"product":{},"category":{}}';
        }

        $status = 'ok';
        $error = '';
        $core = '';
        $key = '';
        $confidence = 0.0;
        $typeKey = '';
        $brandKey = '';
        $reason = '';
        $usage = ['input' => 0, 'cached_input' => 0, 'output' => 0];
        $rawText = '';
        try {
            $res = $client->generateText($model, "Return a valid JSON object only.\n\n" . $inputJson, $prompt, [
                'prompt_cache_key' => 'fill_same_model:' . substr(hash('sha256', $prompt), 0, 48),
                'text' => ['format' => ['type' => 'json_object']],
            ]);
            $rawText = (string)($res['output_text'] ?? '');
            $usage = supplier_products_db_extract_openai_usage(is_array($res['raw'] ?? null) ? $res['raw'] : null);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += openai_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);

            $obj = supplier_products_db_extract_json_object($rawText);
            $core = trim((string)($obj['core'] ?? ''));
            $key = $normKey((string)($obj['key'] ?? ''));
            if ($key === '' && $core !== '') {
                $key = $normKey($core);
            }
            $confidenceRaw = $obj['confidence'] ?? null;
            if (is_numeric($confidenceRaw)) {
                $confidence = max(0.0, min(1.0, (float)$confidenceRaw));
            }
            $paramCore = supplier_products_db_same_model_param_candidate($job);
            $cleanCore = $paramCore !== '' ? $paramCore : supplier_products_db_same_model_first_value($core);
            if ($cleanCore !== '') {
                $core = $cleanCore;
                $key = $normKey($core);
                if ($paramCore !== '') {
                    $confidence = max($confidence, 0.92);
                    $reason = 'модель взята из явного параметра товара';
                }
            }
            $typeKey = $normKey((string)($obj['type_key'] ?? ($obj['product_type'] ?? '')));
            $brandKey = $normKey((string)($obj['brand_key'] ?? ''));
            if ($brandKey === '') {
                $brandKey = $normKey((string)(($job['product']['brand'] ?? '') ?: ($job['product']['vendor'] ?? '')));
            }
            if ($reason === '') {
                $reason = trim((string)($obj['reason'] ?? ''));
            }
            if ($core === '' || $key === '') {
                $status = 'empty';
            } elseif ($confidence < $minConfidence) {
                $status = 'low_confidence';
                $error = 'confidence ' . round($confidence, 3) . ' ниже порога ' . $minConfidence;
            } elseif ($isGenericCore($core, $key, $job)) {
                $status = 'generic';
                $error = 'слишком общий core/key для безопасной группировки';
            }
        } catch (Throwable $e) {
            $status = 'error';
            $error = $e->getMessage();
        }

        $results[$offerId] = [
            'product_id' => (int)($job['product_id'] ?? 0),
            'status' => $status,
            'core' => $core,
            'key' => $key,
            'confidence' => $confidence,
            'type_key' => $typeKey,
            'brand_key' => $brandKey,
            'category_key' => (string)($job['category_key'] ?? ''),
            'reason' => $reason,
            'error' => $error,
            'usage' => $usage,
        ];
        file_put_contents(
            $outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'status' => $status,
                'core' => $core,
                'key' => $key,
                'confidence' => $confidence,
                'type_key' => $typeKey,
                'brand_key' => $brandKey,
                'category_key' => (string)($job['category_key'] ?? ''),
                'reason' => $reason,
                'error' => $error,
                'payload' => $payload,
                'gpt_output_text' => $rawText,
                'usage' => $usage,
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );
    }

    $llmErrors = 0;
    foreach ($results as $result) {
        if (($result['status'] ?? '') === 'error') {
            $llmErrors++;
        }
    }
    supplier_products_db_fail_if_llm_unavailable('gpt_fill_same_model', count($jobs), $llmErrors, $tokensInTotal, $tokensOutTotal);

    $emptyResults = 0;
    $lowConfidence = 0;
    $genericSkipped = 0;
    foreach ($results as $result) {
        $status = (string)($result['status'] ?? '');
        if ($status === 'empty') {
            $emptyResults++;
        } elseif ($status === 'low_confidence') {
            $lowConfidence++;
        } elseif ($status === 'generic') {
            $genericSkipped++;
        }
    }

    $groups = [];
    foreach ($results as $offerId => $result) {
        if (($result['status'] ?? '') !== 'ok') {
            continue;
        }
        $key = (string)($result['key'] ?? '');
        if ($key === '') {
            continue;
        }
        $groupKey = $key;
        $brandKey = (string)($result['brand_key'] ?? '');
        $typeKey = (string)($result['type_key'] ?? '');
        $categoryKey = (string)($result['category_key'] ?? '');
        if ($brandKey !== '') {
            $groupKey .= '|b:' . $brandKey;
        }
        if ($typeKey !== '') {
            $groupKey .= '|t:' . $typeKey;
        } elseif ($categoryKey !== '') {
            $groupKey .= '|c:' . $categoryKey;
        }
        $groups[$groupKey][$offerId] = $result;
    }

    $pdo = db();
    $changedProducts = [];
    $groupsWritten = 0;
    $offersWritten = 0;
    foreach ($groups as $key => $items) {
        if (count($items) < $minGroup) {
            continue;
        }
        $cores = [];
        foreach ($items as $item) {
            $core = trim((string)($item['core'] ?? ''));
            if ($core !== '') {
                $cores[$core] = ($cores[$core] ?? 0) + 1;
            }
        }
        if (!$cores) {
            continue;
        }
        arsort($cores);
        $sameModel = (string)array_key_first($cores);
        if ($sameModel === '') {
            continue;
        }
        $groupsWritten++;
        foreach ($items as $item) {
            $productId = (int)($item['product_id'] ?? 0);
            if ($productId <= 0) {
                continue;
            }
            if (supplier_products_db_set_tag_field($pdo, $supplierId, $productId, ['same_model'], 'same_model', $sameModel)) {
                $changedProducts[$productId] = true;
                $offersWritten++;
            }
        }
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId);
    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $report = [
        'title' => 'gpt_fill_same_model',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_seen' => $seenProducts,
            'jobs' => $jobsInitial,
            'direct_candidates' => $directCandidates,
            'gpt_jobs' => count($jobs),
            'groups_detected' => count($groups),
            'groups_written' => $groupsWritten,
            'offers_written' => $offersWritten,
            'min_confidence' => $minConfidence,
            'empty_results' => $emptyResults,
            'low_confidence' => $lowConfidence,
            'generic_skipped' => $genericSkipped,
            'tokens_in' => $tokensInTotal,
            'tokens_cached_in' => $tokensCachedTotal,
            'tokens_out' => $tokensOutTotal,
        ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
        'dataset' => $dataset,
    ];
    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_fill_same_model',
        'items' => [
            'Jobs: ' . count($jobs),
            'Groups written: ' . $groupsWritten,
            'Offers written: ' . $offersWritten,
            'Skipped low confidence: ' . $lowConfidence,
            'Skipped generic: ' . $genericSkipped,
            'Tokens in: ' . $tokensInTotal,
            'Tokens cached in: ' . $tokensCachedTotal,
            'Tokens out: ' . $tokensOutTotal,
            'Cost: ' . $costLabel,
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_gpt_generate_description(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '0') !== '' && (string)($params['overwrite'] ?? '0') !== '0');
    $minDescLen = max(0, (int)trim((string)($params['min_desc_len'] ?? '250')));
    $useKeywords = ((string)($params['use_keywords'] ?? '1') !== '' && (string)($params['use_keywords'] ?? '1') !== '0');
    $rewriteExisting = ((string)($params['rewrite_existing'] ?? '1') !== '' && (string)($params['rewrite_existing'] ?? '1') !== '0');

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'generate_description_ru.txt');
    $log(
        "supplier_db gpt_generate_description_ru: model={$model}, max_items={$maxItems}, smart=1, rewrite_existing=" .
        ($rewriteExisting ? '1' : '0') . ", overwrite_legacy=" . ($overwrite ? '1' : '0') .
        ", min_desc_len={$minDescLen}, use_keywords=" . ($useKeywords ? '1' : '0') . "\n"
    );
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));

    $jobs = [];
    $seenProducts = 0;
    $modeCounts = ['generate' => 0, 'rewrite' => 0, 'skipped_rewrite_existing_disabled' => 0];
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
        $cat = null;
        if ($ozonCategory !== '' || $wbCategory !== '') {
            $cat = ft_load_combined_marketplace_category_context($ozonCategory, $wbCategory, $useKeywords);
        }
        if (!$cat) {
            $cat = supplier_products_db_empty_description_category_context();
        }
        $descPlain = supplier_products_db_plain_text((string)($product['description_html'] ?? ''));
        $sourceHtml = trim((string)($product['description_html'] ?? ''));
        $operationMode = supplier_products_db_description_operation_mode($descPlain, $minDescLen);
        $descriptionMode = (string)($operationMode['mode'] ?? 'generate');
        if ($descriptionMode === 'rewrite' && !$rewriteExisting && !$overwrite) {
            $modeCounts['skipped_rewrite_existing_disabled']++;
            continue;
        }
        if (!isset($modeCounts[$descriptionMode])) {
            $modeCounts[$descriptionMode] = 0;
        }
        $modeCounts[$descriptionMode]++;

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $productPayload = [
            'offer_id' => $offerId,
            'vendorCode' => (string)($product['vendor_code'] ?? ''),
            'name' => (string)($product['name'] ?? ''),
            'brand' => (string)($context['brand'] ?? ($product['brand'] ?? '')),
            'vendor' => (string)($context['vendor'] ?? ''),
            'model' => (string)($context['model'] ?? ''),
            'description_existing_html' => supplier_products_db_description_html_snippet($sourceHtml, 9000),
            'description_existing_plain' => supplier_products_db_description_snippet($descPlain, 5000),
            'description_structure' => supplier_products_db_description_structure_meta($sourceHtml),
            'params' => supplier_products_db_product_params_payload($fields),
        ];
        $categoryPayload = [
            'code' => (string)$cat['code'],
            'name' => (string)$cat['name'],
            'full_path' => (string)$cat['full_path'],
            'description' => (string)$cat['description'],
            'typical_goods' => (string)$cat['typical_goods'],
            'features' => (string)$cat['features'],
            'keywords_lines' => $useKeywords ? (string)($cat['keywords_lines'] ?? '') : '',
            'marketplace_contexts' => $cat['marketplace_contexts'] ?? [],
        ];
        $cardBrief = ft_card_brief_build($productPayload, $categoryPayload, [
            'purpose' => 'description',
            'operation_mode' => $descriptionMode,
            'use_keywords' => $useKeywords,
        ]);
        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'ozon_category' => $ozonCategory,
            'wb_category' => $wbCategory,
            'operation' => [
                'mode' => $descriptionMode,
                'reason' => (string)($operationMode['reason'] ?? ''),
                'source_plain_len' => (int)($operationMode['plain_len'] ?? 0),
                'source_latin_share' => (float)($operationMode['latin_share'] ?? 0.0),
                'short_description_threshold' => $minDescLen,
            ],
            'source_description_html' => $sourceHtml,
            'product' => $productPayload,
            'category' => $categoryPayload,
            'card_brief' => $cardBrief,
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 250 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log(
        "scan: products_seen={$seenProducts}, jobs=" . count($jobs) .
        ", generate=" . (int)($modeCounts['generate'] ?? 0) .
        ", rewrite=" . (int)($modeCounts['rewrite'] ?? 0) .
        ", skipped_rewrite_existing_disabled=" . (int)($modeCounts['skipped_rewrite_existing_disabled'] ?? 0) .
        "\n"
    );

    $perOffer = [];
    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $gptDone = 0;
    $gptTotal = max(1, count($jobs));
    $firstLlmError = '';
    $client = count($jobs) > 0 ? LLM::client($cfg, $model) : null;

    foreach ($jobs as $offerId => $payload) {
        $gptDone++;
        ops_update_progress($opId, $gptDone, $gptTotal, 'gpt', "GPT {$gptDone}/{$gptTotal} offer={$offerId}");

        $requestPayload = [
            'operation' => $payload['operation'] ?? [],
            'card_brief' => $payload['card_brief'] ?? [],
            'category' => $payload['category'] ?? [],
            'product' => $payload['product'] ?? [],
        ];
        $inputJson = json_encode($requestPayload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($inputJson === false) {
            $inputJson = '{"product":{},"category":{}}';
        }

        $status = 'ok';
        $err = '';
        $descHtml = '';
        $rawText = '';
        $raw = null;
        $usage = ['input' => 0, 'cached_input' => 0, 'output' => 0];
        $selfCheck = [];
        $descriptionMode = (string)(($payload['operation']['mode'] ?? '') ?: 'generate');

        try {
            $res = $client->generateText(
                $model,
                "Return a json object only.\n\njson:\n" . $inputJson,
                $prompt,
                [
                    'prompt_cache_key' => 'smart_desc:' . substr(hash('sha256', json_encode([
                        'mode' => $descriptionMode,
                        'category' => $requestPayload['category'] ?? [],
                        'structure' => $requestPayload['product']['description_structure'] ?? [],
                    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                    'text' => ['format' => ['type' => 'json_object']],
                ]
            );
            $rawText = (string)($res['output_text'] ?? '');
            $raw = is_array($res['raw'] ?? null) ? $res['raw'] : null;
            $usage = supplier_products_db_extract_openai_usage($raw);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += openai_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);

            $obj = supplier_products_db_extract_json_object($rawText);
            $selfCheck = is_array($obj['self_check'] ?? null) ? $obj['self_check'] : [];
            $descHtml = $descriptionMode === 'rewrite'
                ? supplier_products_db_normalize_description_html_preserve_length((string)($obj['description_html'] ?? ''))
                : supplier_products_db_normalize_description_html((string)($obj['description_html'] ?? ''));
            if ($descHtml === '' || supplier_products_db_plain_text($descHtml) === '') {
                throw new RuntimeException('GPT returned empty description_html');
            }
            if ($descriptionMode === 'rewrite') {
                supplier_products_db_validate_rewritten_description((string)($payload['source_description_html'] ?? ''), $descHtml);
            }
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            if ($firstLlmError === '') {
                $firstLlmError = $err;
            }
        }

        $perOffer[$offerId] = [
            'status' => $status,
            'mode' => $descriptionMode,
            'description_html' => $descHtml,
            'error' => $err,
            'self_check' => $selfCheck,
        ];

        file_put_contents(
            $outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'status' => $status,
                'mode' => $descriptionMode,
                'error' => $err,
                'description_html' => $descHtml,
                'self_check' => $selfCheck,
                'payload' => $payload,
                'gpt_output_text' => $rawText,
                'usage' => $usage,
                'raw' => $raw,
            ], JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT)
        );
    }

    $pdo = db();
    $updateDescription = $pdo->prepare("UPDATE feedtools_supplier_products SET description_html = ? WHERE id = ?");
    $changedProducts = [];
    $offersTouched = 0;
    foreach ($perOffer as $offerId => $result) {
        $description = trim((string)($result['description_html'] ?? ''));
        if (($result['status'] ?? '') !== 'ok' || $description === '') {
            continue;
        }
        $productId = (int)($jobs[$offerId]['product_id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        $updateDescription->execute([$description, $productId]);
        $changedProducts[$productId] = true;
        $offersTouched++;
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    $processedModeCounts = ['generate' => 0, 'rewrite' => 0];
    foreach ($perOffer as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
        $rowMode = (string)(($row['mode'] ?? '') ?: 'generate');
        if (!isset($processedModeCounts[$rowMode])) {
            $processedModeCounts[$rowMode] = 0;
        }
        $processedModeCounts[$rowMode]++;
    }
    supplier_products_db_fail_if_llm_unavailable(
        'gpt_generate_description_ru',
        count($jobs),
        (int)($statusCounts['error'] ?? 0),
        $tokensInTotal,
        $tokensOutTotal,
        $firstLlmError
    );

    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $report = [
        'title' => 'gpt_generate_description_ru',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'card_briefs_built' => count($jobs),
            'jobs_generate' => (int)($processedModeCounts['generate'] ?? 0),
            'jobs_rewrite' => (int)($processedModeCounts['rewrite'] ?? 0),
            'skipped_rewrite_existing_disabled' => (int)($modeCounts['skipped_rewrite_existing_disabled'] ?? 0),
            'gpt_status_counts' => $statusCounts,
            'products_touched' => $offersTouched,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'usage' => [
                'input_tokens' => $tokensInTotal,
                'cached_input_tokens' => $tokensCachedTotal,
                'output_tokens' => $tokensOutTotal,
            ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
        ],
        'params_effective' => [
            'model' => $model,
            'max_items' => (string)$maxItems,
            'overwrite' => $overwrite ? '1' : '0',
            'rewrite_existing' => $rewriteExisting ? '1' : '0',
            'min_desc_len' => (string)$minDescLen,
            'use_keywords' => $useKeywords ? '1' : '0',
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_generate_description_ru',
        'items' => [
            'Jobs: ' . count($jobs),
            'Card briefs built: ' . count($jobs),
            'Generate mode: ' . (int)($processedModeCounts['generate'] ?? 0),
            'Rewrite mode: ' . (int)($processedModeCounts['rewrite'] ?? 0),
            'Products touched: ' . $offersTouched,
            'Skipped rewrite disabled: ' . (int)($modeCounts['skipped_rewrite_existing_disabled'] ?? 0),
            'Tokens in: ' . $tokensInTotal,
            'Tokens cached in: ' . $tokensCachedTotal,
            'Tokens out: ' . $tokensOutTotal,
            'Cost: ' . $costLabel,
        ],
        'metrics' => [
            'jobs' => count($jobs),
            'card_briefs_built' => count($jobs),
            'jobs_generate' => (int)($processedModeCounts['generate'] ?? 0),
            'jobs_rewrite' => (int)($processedModeCounts['rewrite'] ?? 0),
            'offers_touched' => $offersTouched,
            'skipped_rewrite_existing_disabled' => (int)($modeCounts['skipped_rewrite_existing_disabled'] ?? 0),
            'tokens_in' => $tokensInTotal,
            'tokens_cached_in' => $tokensCachedTotal,
            'tokens_out' => $tokensOutTotal,
        ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
    ];
    return $outputs;
}

function supplier_products_db_op_gpt_rewrite_description(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $params['rewrite_existing'] = '1';
    $log("supplier_db gpt_rewrite_description_ru: legacy alias -> gpt_generate_description_ru smart description mode\n");
    return supplier_products_db_op_gpt_generate_description($cfg, $ds, $opId, $params, $log);

    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $minDescLen = max(0, (int)trim((string)($params['min_desc_len'] ?? '120')));
    $useKeywords = ((string)($params['use_keywords'] ?? '1') !== '' && (string)($params['use_keywords'] ?? '1') !== '0');

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'rewrite_description_ru.txt');
    $log(
        "supplier_db gpt_rewrite_description_ru: model={$model}, max_items={$maxItems}, " .
        "min_desc_len={$minDescLen}, use_keywords=" . ($useKeywords ? '1' : '0') . "\n"
    );
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));

    $emptySkipped = 0;
    $shortSkipped = 0;
    $seenProducts = 0;
    $jobs = [];

    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $sourceHtml = trim((string)($product['description_html'] ?? ''));
        $sourcePlain = supplier_products_db_plain_text($sourceHtml);
        $sourceLen = mb_strlen($sourcePlain, 'UTF-8');
        if ($sourcePlain === '') {
            $emptySkipped++;
            continue;
        }
        if ($minDescLen > 0 && $sourceLen < $minDescLen) {
            $shortSkipped++;
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
        $cat = null;
        if ($ozonCategory !== '' || $wbCategory !== '') {
            $cat = ft_load_combined_marketplace_category_context($ozonCategory, $wbCategory, $useKeywords);
        }
        if (!$cat) {
            $cat = [
                'code' => '',
                'name' => '',
                'full_path' => '',
                'description' => '',
                'typical_goods' => '',
                'features' => '',
                'keywords_lines' => '',
                'marketplace_contexts' => [],
            ];
        }

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'source_description_html' => $sourceHtml,
            'source_description_plain_len' => $sourceLen,
            'product' => [
                'offer_id' => $offerId,
                'vendorCode' => (string)($product['vendor_code'] ?? ''),
                'name' => (string)($product['name'] ?? ''),
                'brand' => (string)($context['brand'] ?? ($product['brand'] ?? '')),
                'vendor' => (string)($context['vendor'] ?? ''),
                'model' => (string)($context['model'] ?? ''),
                'description_existing_html' => supplier_products_db_description_html_snippet($sourceHtml, 9000),
                'description_existing_plain' => supplier_products_db_description_snippet($sourcePlain, 6000),
                'description_structure' => supplier_products_db_description_structure_meta($sourceHtml),
                'params' => supplier_products_db_product_params_payload($fields),
            ],
            'category' => [
                'code' => (string)($cat['code'] ?? ''),
                'name' => (string)($cat['name'] ?? ''),
                'full_path' => (string)($cat['full_path'] ?? ''),
                'description' => (string)($cat['description'] ?? ''),
                'typical_goods' => (string)($cat['typical_goods'] ?? ''),
                'features' => (string)($cat['features'] ?? ''),
                'keywords_lines' => $useKeywords ? (string)($cat['keywords_lines'] ?? '') : '',
                'marketplace_contexts' => $cat['marketplace_contexts'] ?? [],
            ],
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 250 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log("scan: products_seen={$seenProducts}, jobs=" . count($jobs) . ", empty_skipped={$emptySkipped}, short_skipped={$shortSkipped}\n");

    $perOffer = [];
    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $gptDone = 0;
    $gptTotal = max(1, count($jobs));
    $firstLlmError = '';
    $client = count($jobs) > 0 ? LLM::client($cfg, $model) : null;

    foreach ($jobs as $offerId => $payload) {
        $gptDone++;
        ops_update_progress($opId, $gptDone, $gptTotal, 'gpt', "GPT {$gptDone}/{$gptTotal} offer={$offerId}");

        $requestPayload = [
            'category' => $payload['category'] ?? [],
            'product' => $payload['product'] ?? [],
        ];
        $inputJson = json_encode($requestPayload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($inputJson === false) {
            $inputJson = '{"product":{},"category":{}}';
        }

        $status = 'ok';
        $err = '';
        $descHtml = '';
        $rawText = '';
        $raw = null;
        $usage = ['input' => 0, 'cached_input' => 0, 'output' => 0];
        $selfCheck = [];

        try {
            $res = $client->generateText(
                $model,
                "Return a json object only.\n\njson:\n" . $inputJson,
                $prompt,
                [
                    'prompt_cache_key' => 'rewrite_desc:' . substr(hash('sha256', json_encode([
                        'category' => $requestPayload['category'] ?? [],
                        'structure' => $requestPayload['product']['description_structure'] ?? [],
                    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                    'text' => ['format' => ['type' => 'json_object']],
                ]
            );
            $rawText = (string)($res['output_text'] ?? '');
            $raw = is_array($res['raw'] ?? null) ? $res['raw'] : null;
            $usage = supplier_products_db_extract_openai_usage($raw);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += openai_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);

            $obj = supplier_products_db_extract_json_object($rawText);
            $selfCheck = is_array($obj['self_check'] ?? null) ? $obj['self_check'] : [];
            $descHtml = supplier_products_db_normalize_description_html_preserve_length((string)($obj['description_html'] ?? ''));
            if ($descHtml === '' || supplier_products_db_plain_text($descHtml) === '') {
                throw new RuntimeException('GPT returned empty description_html');
            }
            supplier_products_db_validate_rewritten_description((string)($payload['source_description_html'] ?? ''), $descHtml);
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            if ($firstLlmError === '') {
                $firstLlmError = $err;
            }
        }

        $perOffer[$offerId] = [
            'status' => $status,
            'description_html' => $descHtml,
            'error' => $err,
            'self_check' => $selfCheck,
        ];

        file_put_contents(
            $outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'status' => $status,
                'error' => $err,
                'description_html' => $descHtml,
                'self_check' => $selfCheck,
                'payload' => $payload,
                'gpt_output_text' => $rawText,
                'usage' => $usage,
                'raw' => $raw,
            ], JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT)
        );
    }

    $pdo = db();
    $updateDescription = $pdo->prepare("UPDATE feedtools_supplier_products SET description_html = ? WHERE id = ?");
    $changedProducts = [];
    $offersTouched = 0;
    foreach ($perOffer as $offerId => $result) {
        $description = trim((string)($result['description_html'] ?? ''));
        if (($result['status'] ?? '') !== 'ok' || $description === '') {
            continue;
        }
        $productId = (int)($jobs[$offerId]['product_id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        $updateDescription->execute([$description, $productId]);
        $changedProducts[$productId] = true;
        $offersTouched++;
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    foreach ($perOffer as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
    }
    supplier_products_db_fail_if_llm_unavailable(
        'gpt_rewrite_description_ru',
        count($jobs),
        (int)($statusCounts['error'] ?? 0),
        $tokensInTotal,
        $tokensOutTotal,
        $firstLlmError
    );

    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $report = [
        'title' => 'gpt_rewrite_description_ru',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'empty_skipped' => $emptySkipped,
            'short_skipped' => $shortSkipped,
            'gpt_status_counts' => $statusCounts,
            'products_touched' => $offersTouched,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'usage' => [
                'input_tokens' => $tokensInTotal,
                'cached_input_tokens' => $tokensCachedTotal,
                'output_tokens' => $tokensOutTotal,
            ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
        ],
        'params_effective' => [
            'model' => $model,
            'max_items' => (string)$maxItems,
            'min_desc_len' => (string)$minDescLen,
            'use_keywords' => $useKeywords ? '1' : '0',
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_rewrite_description_ru',
        'items' => [
            'Jobs: ' . count($jobs),
            'Products touched: ' . $offersTouched,
            'Skipped empty: ' . $emptySkipped,
            'Skipped short: ' . $shortSkipped,
            'Tokens in: ' . $tokensInTotal,
            'Tokens cached in: ' . $tokensCachedTotal,
            'Tokens out: ' . $tokensOutTotal,
            'Cost: ' . $costLabel,
        ],
        'metrics' => [
            'jobs' => count($jobs),
            'offers_touched' => $offersTouched,
            'empty_skipped' => $emptySkipped,
            'short_skipped' => $shortSkipped,
            'tokens_in' => $tokensInTotal,
            'tokens_cached_in' => $tokensCachedTotal,
            'tokens_out' => $tokensOutTotal,
        ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
    ];
    return $outputs;
}

function supplier_products_db_fill_features_input(array $category, array $product): array
{
    $categoryJson = json_encode($category, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($categoryJson === false) {
        $categoryJson = '{}';
    }
    $productJson = json_encode($product, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($productJson === false) {
        $productJson = '{}';
    }

    return [
        [
            'role' => 'user',
            'content' => [[
                'type' => 'input_text',
                'text' => "CATEGORY JSON (static for prompt cache):\n" . $categoryJson,
            ]],
        ],
        [
            'role' => 'user',
            'content' => [[
                'type' => 'input_text',
                'text' => "PRODUCT JSON (dynamic product data):\n" . $productJson,
            ]],
        ],
    ];
}

function supplier_products_db_fill_features_prompt_cache_key(string $model, string $prompt, array $category): string
{
    $json = json_encode([
        'format' => 'fill_features_category_product_messages_v2',
        'model' => $model,
        'prompt_sha256' => hash('sha256', $prompt),
        'category' => $category,
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($json === false) {
        $json = '';
    }
    return 'fill_features:' . substr(hash('sha256', $json), 0, 48);
}

function supplier_products_db_op_gpt_fill_features(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '0') !== '' && (string)($params['overwrite'] ?? '0') !== '0');

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'fill_features_ru.txt');
    $log("supplier_db gpt_fill_features: model={$model}, max_items={$maxItems}, overwrite=" . ($overwrite ? '1' : '0') . "\n");
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));

    $candidates = [];
    $seenProducts = 0;
    $skippedFilled = 0;
    $skippedNoCategory = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $existingFeaturesRaw = supplier_products_db_product_feature_values($fields);
        $qualityRequiredFeatures = supplier_products_db_required_quality_feature_values($fields);

        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
        $supplierCategoryId = trim((string)($product['category_id'] ?? ''));
        $supplierCategoryPath = trim((string)($product['category_path'] ?? ''));
        if ($ozonCategory === '' && $wbCategory === '' && $supplierCategoryId === '' && $supplierCategoryPath === '') {
            $skippedNoCategory++;
            continue;
        }

        $cat = ($ozonCategory !== '' || $wbCategory !== '')
            ? ft_load_combined_marketplace_category_context($ozonCategory, $wbCategory, false)
            : null;
        $attributeHints = [];
        if (is_array($cat)) {
            foreach ((array)($cat['marketplace_contexts'] ?? []) as $ctx) {
                foreach ((array)($ctx['category_attributes'] ?? []) as $attr) {
                    $name = trim((string)($attr['name'] ?? ''));
                    if ($name === '') {
                        continue;
                    }
                    $key = supplier_products_db_attr_norm($name);
                    if ($key === '' || isset($attributeHints[$key])) {
                        continue;
                    }
                    $attributeHints[$key] = $name;
                    if (count($attributeHints) >= 70) {
                        break 2;
                    }
                }
            }
        }

        $categoryPayload = [
            'supplier' => [
                'id' => $supplierCategoryId,
                'path' => $supplierCategoryPath,
            ],
            'marketplace' => is_array($cat) ? [
                'code' => (string)($cat['code'] ?? ''),
                'name' => (string)($cat['name'] ?? ''),
                'full_path' => (string)($cat['full_path'] ?? ''),
                'description' => supplier_products_db_description_snippet((string)($cat['description'] ?? ''), 900),
                'typical_goods' => supplier_products_db_description_snippet((string)($cat['typical_goods'] ?? ''), 900),
                'features' => supplier_products_db_description_snippet((string)($cat['features'] ?? ''), 900),
                'attribute_hints' => array_values($attributeHints),
            ] : null,
            'ozon_category' => $ozonCategory,
            'wildberries_category' => $wbCategory,
        ];

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $roleContext = supplier_products_db_feature_product_role_context($product, $fields, $categoryPayload);
        $featureHints = supplier_products_db_feature_hints($product, $fields, $roleContext);
        $featureCandidates = supplier_products_db_feature_candidates($fields, $roleContext);

        $compatibilityRequiredFeatures = supplier_products_db_required_electronics_spare_compatibility_feature_values(
            $product,
            $fields,
            $categoryPayload
        );
        $requiredFeatures = supplier_products_db_merge_feature_values($qualityRequiredFeatures, $compatibilityRequiredFeatures);
        $existingFeatures = supplier_products_db_filter_features_for_product(
            $existingFeaturesRaw,
            $product,
            $roleContext
        );
        $missingRequiredFeatures = supplier_products_db_features_missing_required($existingFeatures, $requiredFeatures);
        if (!$overwrite && count($existingFeatures) >= SUPPLIER_PRODUCTS_FEATURE_MAX && !$missingRequiredFeatures) {
            $skippedFilled++;
            continue;
        }

        $candidates[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'existing_features' => $existingFeatures,
            'existing_features_raw' => $existingFeaturesRaw,
            'required_features' => $requiredFeatures,
            'quality_required_features' => $qualityRequiredFeatures,
            'compatibility_required_features' => $compatibilityRequiredFeatures,
            'feature_hints' => $featureHints,
            'feature_candidates' => $featureCandidates,
            'product_role' => $roleContext,
            'category' => $categoryPayload,
            'product' => [
                'offer_id' => $offerId,
                'vendorCode' => (string)($product['vendor_code'] ?? ''),
                'name' => (string)($product['name'] ?? ''),
                'brand' => (string)($context['brand'] ?? ($product['brand'] ?? '')),
                'vendor' => (string)($context['vendor'] ?? ''),
                'model' => (string)($context['model'] ?? ''),
                'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 2200),
                'existing_features' => $existingFeatures,
                'existing_features_raw' => $existingFeaturesRaw,
                'product_role' => $roleContext,
                'mandatory_features' => $requiredFeatures,
                'mandatory_features_reason' => $requiredFeatures
                    ? 'Эти значения обязательны для фишек товара: уровень качества запчасти и/или модель совместимости для запчасти электроники.'
                    : '',
                'mandatory_features_detail' => [
                    'quality_part_level' => $qualityRequiredFeatures,
                    'electronics_spare_compatibility_model' => $compatibilityRequiredFeatures,
                ],
                'feature_hints' => array_values(array_map(
                    static fn(array $hint): string => (string)($hint['value'] ?? ''),
                    array_values(array_filter(
                        (array)($featureHints['items'] ?? []),
                        static fn(array $hint): bool => !empty($featureHints['is_battery']) || (string)($hint['type'] ?? '') !== 'capacity'
                    ))
                )),
                'feature_candidates' => $featureCandidates,
                'fields' => supplier_products_db_feature_payload_fields((array)($context['fields'] ?? [])),
                'params' => array_slice(supplier_products_db_feature_payload_params(supplier_products_db_product_params_payload($fields)), 0, 80),
            ],
        ];

        if ($maxItems > 0 && count($candidates) >= $maxItems) {
            break;
        }
        if ($seenProducts % 250 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log(
        "scan: products_seen={$seenProducts}, candidates=" . count($candidates) .
        ", skipped_filled={$skippedFilled}, skipped_no_category={$skippedNoCategory}\n"
    );

    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $gptResults = [];
    $gptDone = 0;
    $gptTotal = max(1, count($candidates));
    $firstLlmError = '';
    $client = count($candidates) > 0 ? LLM::client($cfg, $model) : null;

    foreach ($candidates as $offerId => $cand) {
        $gptDone++;
        ops_update_progress($opId, $gptDone, $gptTotal, 'gpt', "GPT {$gptDone}/{$gptTotal} offer={$offerId}");

        $payload = [
            'category' => $cand['category'],
            'product' => $cand['product'],
        ];
        $inputMessages = supplier_products_db_fill_features_input((array)$cand['category'], (array)$cand['product']);
        $promptCacheKey = supplier_products_db_fill_features_prompt_cache_key($model, $prompt, (array)$cand['category']);

        $status = 'ok';
        $err = '';
        $rawText = '';
        $raw = null;
        $generatedFeatures = [];
        $featuresFinal = [];
        $usage = ['input' => 0, 'cached_input' => 0, 'output' => 0];
        $cachedLocal = false;
        $responseCacheKey = '';

        try {
            $res = $client->generateText(
                $model,
                $inputMessages,
                $prompt,
                [
                    'prompt_cache_key' => $promptCacheKey,
                    'text' => ['format' => ['type' => 'json_object']],
                ]
            );
            $rawText = (string)($res['output_text'] ?? '');
            $raw = is_array($res['raw'] ?? null) ? $res['raw'] : null;
            $cachedLocal = !empty($res['cached_local']);
            $responseCacheKey = (string)($res['cache_key'] ?? '');
            $usage = supplier_products_db_extract_openai_usage($raw);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += openai_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);

            $obj = supplier_products_db_extract_json_object($rawText);
            $rawFeatures = $obj['features'] ?? ($obj['feature'] ?? ($obj['фишки'] ?? []));
            $generatedFeatures = supplier_products_db_feature_values_from_llm($rawFeatures);
            $generatedFeatures = supplier_products_db_feature_refine_with_hints(
                $generatedFeatures,
                (array)($cand['feature_hints'] ?? [])
            );
            $generatedFeatures = supplier_products_db_filter_features_for_product(
                $generatedFeatures,
                (array)($cand['product'] ?? []),
                (array)($cand['product_role'] ?? []),
                [],
                []
            );
            $featuresBase = $overwrite
                ? (array)($cand['required_features'] ?? [])
                : supplier_products_db_merge_feature_values((array)($cand['existing_features'] ?? []), (array)($cand['required_features'] ?? []));
            $featuresFinal = supplier_products_db_merge_feature_values($featuresBase, $generatedFeatures);
            $featuresFinal = supplier_products_db_filter_features_for_product(
                $featuresFinal,
                (array)($cand['product'] ?? []),
                (array)($cand['product_role'] ?? []),
                (array)($cand['required_features'] ?? []),
                (array)($cand['feature_candidates'] ?? [])
            );
            $featuresFinal = supplier_products_db_force_required_feature_values(
                $featuresFinal,
                (array)($cand['required_features'] ?? [])
            );
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            if ($firstLlmError === '') {
                $firstLlmError = $err;
            }
        }

        $gptResults[$offerId] = [
            'status' => $status,
            'error' => $err,
            'generated_features' => $generatedFeatures,
            'features' => $featuresFinal,
        ];

        file_put_contents(
            $outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'status' => $status,
                'error' => $err,
                'payload' => $payload,
                'input_format' => 'category_product_messages_v2',
                'prompt_cache_key' => $promptCacheKey,
                'local_response_cache_hit' => $cachedLocal,
                'response_cache_key' => $responseCacheKey,
                'gpt_output_text' => $rawText,
                'generated_features' => $generatedFeatures,
                'final_features' => $featuresFinal,
                'usage' => $usage,
                'raw' => $raw,
            ], JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT)
        );
    }

    $pdo = db();
    $changedProducts = [];
    $offersTouched = 0;
    $offersWithFeatures = 0;
    foreach ($gptResults as $offerId => $result) {
        $features = (array)($result['features'] ?? []);
        if (($result['status'] ?? '') !== 'ok' || !$features) {
            continue;
        }
        $productId = (int)($candidates[$offerId]['product_id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        if (supplier_products_db_set_feature_fields($pdo, $supplierId, $productId, $features)) {
            $changedProducts[$productId] = true;
            $offersTouched++;
        }
        $offersWithFeatures++;
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    foreach ($gptResults as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
    }
    supplier_products_db_fail_if_llm_unavailable(
        'gpt_fill_features',
        count($candidates),
        (int)($statusCounts['error'] ?? 0),
        $tokensInTotal,
        $tokensOutTotal,
        $firstLlmError
    );

    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $report = [
        'title' => 'gpt_fill_features',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $totalProducts,
            'products_seen' => $seenProducts,
            'candidates' => count($candidates),
            'skipped_filled' => $skippedFilled,
            'skipped_no_category' => $skippedNoCategory,
            'gpt_status_counts' => $statusCounts,
            'products_touched' => $offersTouched,
            'products_with_features' => $offersWithFeatures,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'usage' => [
                'input_tokens' => $tokensInTotal,
                'cached_input_tokens' => $tokensCachedTotal,
                'output_tokens' => $tokensOutTotal,
            ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
        ],
        'params_effective' => [
            'model' => $model,
            'max_items' => (string)$maxItems,
            'overwrite' => $overwrite ? '1' : '0',
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_fill_features',
        'items' => [
            'Candidates: ' . count($candidates),
            'Products touched: ' . $offersTouched,
            'Products with features: ' . $offersWithFeatures,
            'Skipped filled: ' . $skippedFilled,
            'Tokens in: ' . $tokensInTotal,
            'Tokens cached in: ' . $tokensCachedTotal,
            'Tokens out: ' . $tokensOutTotal,
            'Cost: ' . $costLabel,
        ],
        'metrics' => [
            'candidates' => count($candidates),
            'offers_touched' => $offersTouched,
            'offers_with_features' => $offersWithFeatures,
            'skipped_filled' => $skippedFilled,
            'inplace' => 1,
            'updated_dataset_id' => $datasetId,
            'tokens_in' => $tokensInTotal,
            'tokens_cached_in' => $tokensCachedTotal,
            'tokens_out' => $tokensOutTotal,
        ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
    ];
    ops_update_progress($opId, $gptTotal, $gptTotal, 'done', 'DB dataset updated');
    return $outputs;
}

function supplier_products_db_cover_title(string $name, string $fallback = ''): string
{
    $name = supplier_products_db_plain_text($name);
    $fallback = supplier_products_db_plain_text($fallback);
    $title = $name !== '' ? $name : ($fallback !== '' ? $fallback : 'Товар');
    $title = preg_replace('~\s+~u', ' ', $title);
    $title = trim((string)$title);
    if (mb_strlen($title, 'UTF-8') <= 200) {
        return $title;
    }
    $cut = mb_substr($title, 0, 200, 'UTF-8');
    $space = mb_strrpos($cut, ' ', 0, 'UTF-8');
    if ($space !== false && $space >= 150) {
        $cut = mb_substr($cut, 0, $space, 'UTF-8');
    }
    return rtrim($cut, " \t\n\r\0\x0B.,;:-");
}

function supplier_products_db_standard_field_value_from_rows(array $fields, string $fieldName): string
{
    $fieldName = trim($fieldName);
    if ($fieldName === '') {
        return '';
    }
    foreach ($fields as $field) {
        if ((string)($field['field_kind'] ?? '') !== 'standard') {
            continue;
        }
        if (trim((string)($field['field_name'] ?? '')) !== $fieldName) {
            continue;
        }
        $value = trim((string)($field['field_value'] ?? ''));
        if ($value !== '') {
            return $value;
        }
    }
    return '';
}

function supplier_products_db_cover_picture_is_generated(string $url): bool
{
    $relative = supplier_products_local_image_relative_from_url($url);
    if ($relative === '') {
        return false;
    }
    $relative = str_replace('\\', '/', $relative);
    return str_contains($relative, '/gpt_cover/');
}

function supplier_products_db_cover_source_picture(array $pictures): string
{
    $pictures = supplier_products_normalize_picture_urls($pictures);
    if (!$pictures) {
        return '';
    }
    $first = trim((string)($pictures[0] ?? ''));
    if ($first !== '' && !supplier_products_db_cover_picture_is_generated($first)) {
        return $first;
    }
    foreach ($pictures as $picture) {
        $picture = trim((string)$picture);
        if ($picture !== '' && !supplier_products_db_cover_picture_is_generated($picture)) {
            return $picture;
        }
    }
    return $first;
}

function supplier_products_db_cover_source_picture_candidates(array $pictures): array
{
    $pictures = supplier_products_normalize_picture_urls($pictures);
    if (!$pictures) {
        return [];
    }

    $out = [];
    $seen = [];
    $append = static function (string $picture) use (&$out, &$seen): void {
        $picture = trim($picture);
        if ($picture === '' || isset($seen[$picture])) {
            return;
        }
        $seen[$picture] = true;
        $out[] = $picture;
    };

    $append(supplier_products_db_cover_source_picture($pictures));
    foreach ($pictures as $picture) {
        $picture = trim((string)$picture);
        if ($picture !== '' && !supplier_products_db_cover_picture_is_generated($picture)) {
            $append($picture);
        }
    }
    foreach ($pictures as $picture) {
        $append((string)$picture);
    }

    return $out;
}

function supplier_products_db_cover_picture_log_label(string $url): string
{
    $url = trim($url);
    if (strlen($url) <= 180) {
        return $url;
    }
    return substr($url, 0, 177) . '...';
}

function supplier_products_db_cover_pictures_with_new_cover(array $pictures, string $newCoverUrl): array
{
    $newCoverUrl = trim($newCoverUrl);
    if ($newCoverUrl === '') {
        return supplier_products_normalize_picture_urls($pictures);
    }

    $out = [$newCoverUrl];
    $seen = [$newCoverUrl => true];
    foreach (supplier_products_normalize_picture_urls($pictures) as $picture) {
        $picture = trim((string)$picture);
        if ($picture === '' || isset($seen[$picture])) {
            continue;
        }
        if (supplier_products_db_cover_picture_is_generated($picture)) {
            continue;
        }
        $out[] = $picture;
        $seen[$picture] = true;
    }
    return $out;
}

function supplier_products_db_cover_bundle_info(array $product, array $fields): array
{
    $offerId = trim((string)($product['offer_id'] ?? ($product['offer_key'] ?? '')));
    $parsed = function_exists('bundle_offer_parse') ? bundle_offer_parse($offerId) : [];
    $isBundle = !empty($parsed['is_bundle']);
    $qty = $isBundle ? max(1, (int)($parsed['bundle_qty'] ?? 1)) : 1;
    $source = $isBundle ? 'offer_id' : '';

    if ($qty <= 1) {
        foreach ($fields as $field) {
            $kind = (string)($field['field_kind'] ?? '');
            if ($kind !== 'param' && $kind !== 'wb_param') {
                continue;
            }
            $name = trim((string)($field['field_name'] ?? ''));
            if ($name === '' || !supplier_products_db_is_unit_quantity_attribute($name)) {
                continue;
            }
            $value = trim((string)($field['field_value'] ?? ''));
            if ($value === '') {
                continue;
            }
            $candidate = supplier_products_db_unit_quantity_value_number($value);
            if ($candidate !== null
                && $candidate > 1
                && supplier_products_db_unit_quantity_allowed_for_product($product, $fields, $candidate)
            ) {
                $qty = $candidate;
                $source = 'unit_quantity_attribute';
                break;
            }
        }
    }

    if ($qty <= 1) {
        $fromProduct = supplier_products_db_detect_unit_quantity_from_product($product, $fields);
        if ($fromProduct !== null && $fromProduct > 1) {
            $qty = $fromProduct;
            $source = 'confirmed_text';
        }
    }

    $isBundle = $qty > 1;
    return [
        'is_bundle' => $isBundle,
        'quantity' => $isBundle ? $qty : 1,
        'label' => $isBundle ? ('Комплект: ' . $qty . ' шт') : '',
        'source' => $source,
        'base_offer_id' => (string)($parsed['base_offer_id'] ?? ''),
    ];
}

function supplier_products_db_cover_category_payload(array $product, array $fields): array
{
    $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
    $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
    $coverDesign = supplier_products_db_cover_category_design_text($ozonCategory, $wbCategory);

    return [
        'cover_design' => $coverDesign,
        'style_source' => $coverDesign !== '' ? 'taxonomy_category_meta.cover_design' : '',
    ];
}

function supplier_products_db_cover_category_design_text(string $ozonCategory, string $wbCategory): string
{
    $items = [];
    foreach ([
        ['source' => 'ozon', 'label' => 'Ozon', 'value' => $ozonCategory],
        ['source' => 'wildberries', 'label' => 'Wildberries', 'value' => $wbCategory],
    ] as $row) {
        $value = trim((string)$row['value']);
        if ($value === '') {
            continue;
        }
        $meta = supplier_products_taxonomy_meta_for_category_value((string)$row['source'], $value);
        $design = trim((string)($meta['cover_design'] ?? ''));
        if ($design === '') {
            continue;
        }
        $items[] = '[' . (string)$row['label'] . '] ' . supplier_products_db_description_snippet($design, 900);
    }
    if (!$items) {
        return '';
    }
    if (count($items) === 1) {
        return preg_replace('~^\[(?:Ozon|Wildberries)\]\s*~u', '', $items[0]) ?: $items[0];
    }
    return implode("\n\n", array_values(array_unique($items)));
}

function supplier_products_db_cover_image_data_url(string $url, array $cfg): array
{
    $source = supplier_products_bundle_photo_source_path($url, $cfg);
    try {
        $path = (string)$source['path'];
        $bytes = is_file($path) ? file_get_contents($path) : false;
        if (!is_string($bytes) || $bytes === '') {
            throw new RuntimeException('Не удалось прочитать первое фото товара.');
        }
        $info = @getimagesizefromstring($bytes);
        if (!is_array($info)) {
            throw new RuntimeException('Первое фото товара не распознано как изображение.');
        }
        $width = (int)($info[0] ?? 0);
        $height = (int)($info[1] ?? 0);
        $mime = strtolower((string)($info['mime'] ?? ''));
        if ($width <= 0 || $height <= 0 || ($width * $height) > 36_000_000) {
            throw new RuntimeException('Первое фото товара слишком большое для GPT-обложки.');
        }

        if (extension_loaded('gd')) {
            $original = @imagecreatefromstring($bytes);
            if ($original instanceof GdImage) {
                $maxDim = 1536;
                $scale = min(1.0, $maxDim / max(1, $width), $maxDim / max(1, $height));
                $dstW = max(1, (int)round($width * $scale));
                $dstH = max(1, (int)round($height * $scale));
                $canvas = imagecreatetruecolor($dstW, $dstH);
                if (!$canvas instanceof GdImage) {
                    throw new RuntimeException('Не удалось подготовить первое фото товара для GPT.');
                }
                imagealphablending($canvas, true);
                imagesavealpha($canvas, false);
                $white = imagecolorallocate($canvas, 255, 255, 255);
                imagefilledrectangle($canvas, 0, 0, $dstW, $dstH, $white);
                imagecopyresampled($canvas, $original, 0, 0, 0, 0, $dstW, $dstH, $width, $height);
                unset($original);

                ob_start();
                imagejpeg($canvas, null, 91);
                $normalized = ob_get_clean();
                unset($canvas);
                if (is_string($normalized) && $normalized !== '') {
                    $bytes = $normalized;
                    $mime = 'image/jpeg';
                    $width = $dstW;
                    $height = $dstH;
                }
            }
        }

        $maxBytes = max(1, (int)($cfg['llm']['remote_image_max_bytes'] ?? (10 * 1024 * 1024)));
        if (strlen($bytes) > $maxBytes) {
            throw new RuntimeException('Первое фото товара слишком большое для отправки в GPT.');
        }
        if (!in_array($mime, ['image/jpeg', 'image/png', 'image/webp'], true)) {
            throw new RuntimeException('Для GPT-обложки поддерживаются JPG, PNG и WebP.');
        }

        return [
            'image_url' => 'data:' . $mime . ';base64,' . base64_encode($bytes),
            'mime' => $mime,
            'bytes' => strlen($bytes),
            'width' => $width,
            'height' => $height,
        ];
    } finally {
        if (!empty($source['temporary'])) {
            @unlink((string)$source['path']);
        }
    }
}

function supplier_products_db_cover_image_generation_call(array $raw): array
{
    foreach ((array)($raw['output'] ?? []) as $item) {
        if (!is_array($item)) {
            continue;
        }
        if ((string)($item['type'] ?? '') !== 'image_generation_call') {
            continue;
        }
        $result = trim((string)($item['result'] ?? ''));
        if ($result !== '') {
            return $item;
        }
    }
    throw new RuntimeException('OpenAI image_generation не вернул изображение.');
}

function supplier_products_db_cover_image_bytes_from_data_url(string $dataUrl): string
{
    $dataUrl = trim($dataUrl);
    if (!preg_match('/^data:image\/[^;]+;base64,(.*)$/s', $dataUrl, $m)) {
        throw new RuntimeException('Внутренняя ошибка: исходное фото не подготовлено как data URL.');
    }
    $bytes = base64_decode((string)$m[1], true);
    if ($bytes === false || $bytes === '') {
        throw new RuntimeException('Внутренняя ошибка: не удалось декодировать исходное фото.');
    }
    return $bytes;
}

function supplier_products_db_cover_decode_image_api_result(array $raw): string
{
    $data = $raw['data'] ?? [];
    if (!is_array($data) || !$data) {
        throw new RuntimeException('OpenAI Image API не вернул изображение.');
    }
    $first = $data[0] ?? null;
    if (!is_array($first)) {
        throw new RuntimeException('OpenAI Image API вернул некорректный ответ.');
    }
    $b64 = trim((string)($first['b64_json'] ?? ''));
    if ($b64 === '') {
        throw new RuntimeException('OpenAI Image API не вернул b64_json.');
    }
    return supplier_products_db_cover_decode_image_result($b64);
}

function supplier_products_db_cover_decode_image_result(string $result): string
{
    $result = trim($result);
    if (str_starts_with($result, 'data:') && str_contains($result, ',')) {
        $result = substr($result, strpos($result, ',') + 1);
    }
    $bytes = base64_decode($result, true);
    if ($bytes === false || $bytes === '') {
        throw new RuntimeException('OpenAI image_generation вернул поврежденный base64.');
    }
    if (!is_array(@getimagesizefromstring($bytes))) {
        throw new RuntimeException('OpenAI image_generation вернул данные, которые не похожи на изображение.');
    }
    return $bytes;
}

function supplier_products_db_cover_sanitize_openai_response(?array $raw): ?array
{
    if (!is_array($raw)) {
        return null;
    }
    $copy = $raw;
    foreach ((array)($copy['output'] ?? []) as $i => $item) {
        if (!is_array($item) || (string)($item['type'] ?? '') !== 'image_generation_call') {
            continue;
        }
        $result = (string)($item['result'] ?? '');
        if ($result !== '') {
            $copy['output'][$i]['result_length'] = strlen($result);
            $copy['output'][$i]['result_sha256'] = hash('sha256', $result);
            unset($copy['output'][$i]['result']);
        }
    }
    return $copy;
}

function supplier_products_db_cover_sanitize_image_api_response(?array $raw): ?array
{
    if (!is_array($raw)) {
        return null;
    }
    $copy = $raw;
    foreach ((array)($copy['data'] ?? []) as $i => $item) {
        if (!is_array($item)) {
            continue;
        }
        $b64 = (string)($item['b64_json'] ?? '');
        if ($b64 !== '') {
            $copy['data'][$i]['b64_json_length'] = strlen($b64);
            $copy['data'][$i]['b64_json_sha256'] = hash('sha256', $b64);
            unset($copy['data'][$i]['b64_json']);
        }
    }
    return $copy;
}

function supplier_products_db_cover_normalize_image_usage(?array $usage): array
{
    if (!is_array($usage)) {
        return [
            'input_tokens' => 0,
            'cached_input_tokens' => 0,
            'text_input_tokens' => 0,
            'text_cached_input_tokens' => 0,
            'image_input_tokens' => 0,
            'image_cached_input_tokens' => 0,
            'output_tokens' => 0,
            'text_output_tokens' => 0,
            'image_output_tokens' => 0,
            'total_tokens' => 0,
            'input_details_missing' => true,
            'output_details_missing' => true,
        ];
    }

    $inputDetails = $usage['input_tokens_details'] ?? [];
    $inputDetails = is_array($inputDetails) ? $inputDetails : [];
    $outputDetails = $usage['output_tokens_details'] ?? [];
    $outputDetails = is_array($outputDetails) ? $outputDetails : [];

    $inputTokens = max(0, (int)($usage['input_tokens'] ?? 0));
    $outputTokens = max(0, (int)($usage['output_tokens'] ?? 0));
    $totalTokens = max(0, (int)($usage['total_tokens'] ?? ($inputTokens + $outputTokens)));

    $textInputTokens = max(0, (int)($inputDetails['text_tokens'] ?? 0));
    $imageInputTokens = max(0, (int)($inputDetails['image_tokens'] ?? 0));
    $inputDetailsTotal = $textInputTokens + $imageInputTokens;
    $inputDetailsMissing = $inputTokens > 0 && $inputDetailsTotal <= 0;
    if (!$inputDetailsMissing && $inputDetailsTotal < $inputTokens) {
        $textInputTokens += $inputTokens - $inputDetailsTotal;
    }

    $textCachedInputTokens = max(0, (int)($inputDetails['cached_text_tokens'] ?? ($inputDetails['text_cached_tokens'] ?? 0)));
    $imageCachedInputTokens = max(0, (int)($inputDetails['cached_image_tokens'] ?? ($inputDetails['image_cached_tokens'] ?? 0)));
    $cachedInputTokens = max(
        0,
        (int)($usage['cached_input_tokens'] ?? ($usage['cached_tokens'] ?? ($inputDetails['cached_tokens'] ?? ($textCachedInputTokens + $imageCachedInputTokens))))
    );
    $splitCachedTokens = $textCachedInputTokens + $imageCachedInputTokens;
    $inputSplitTotal = $textInputTokens + $imageInputTokens;
    if ($cachedInputTokens > $splitCachedTokens && $inputSplitTotal > 0) {
        $remainingCached = min($cachedInputTokens - $splitCachedTokens, $inputSplitTotal - $splitCachedTokens);
        if ($remainingCached > 0) {
            $imageShare = (int)round($remainingCached * ($imageInputTokens / $inputSplitTotal));
            $imageCachedInputTokens += $imageShare;
            $textCachedInputTokens += $remainingCached - $imageShare;
        }
    }
    $textCachedInputTokens = min($textInputTokens, $textCachedInputTokens);
    $imageCachedInputTokens = min($imageInputTokens, $imageCachedInputTokens);
    $cachedInputTokens = min($inputTokens, $textCachedInputTokens + $imageCachedInputTokens);

    $textOutputTokens = max(0, (int)($outputDetails['text_tokens'] ?? 0));
    $imageOutputTokens = max(0, (int)($outputDetails['image_tokens'] ?? 0));
    $outputDetailsTotal = $textOutputTokens + $imageOutputTokens;
    $outputDetailsMissing = $outputTokens > 0 && $outputDetailsTotal <= 0;
    if ($outputDetailsMissing) {
        $imageOutputTokens = $outputTokens;
    } elseif ($outputDetailsTotal < $outputTokens) {
        $imageOutputTokens += $outputTokens - $outputDetailsTotal;
    }

    return [
        'input_tokens' => $inputTokens,
        'cached_input_tokens' => $cachedInputTokens,
        'text_input_tokens' => $textInputTokens,
        'text_cached_input_tokens' => $textCachedInputTokens,
        'image_input_tokens' => $imageInputTokens,
        'image_cached_input_tokens' => $imageCachedInputTokens,
        'output_tokens' => $outputTokens,
        'text_output_tokens' => $textOutputTokens,
        'image_output_tokens' => $imageOutputTokens,
        'total_tokens' => $totalTokens,
        'input_details_missing' => $inputDetailsMissing,
        'output_details_missing' => $outputDetailsMissing,
        'raw' => $usage,
    ];
}

function supplier_products_db_cover_image_usage(array $imageCall): array
{
    $usage = $imageCall['usage'] ?? null;
    return supplier_products_db_cover_normalize_image_usage(is_array($usage) ? $usage : null);
}

function supplier_products_db_cover_image_api_usage(array $raw): array
{
    $usage = $raw['usage'] ?? null;
    return supplier_products_db_cover_normalize_image_usage(is_array($usage) ? $usage : null);
}

function supplier_products_db_cover_output_size_key(string $requestedSize, string $generatedBytes = ''): string
{
    $requestedSize = strtolower(trim($requestedSize));
    if (in_array($requestedSize, ['1024x1024', '1024x1536', '1536x1024'], true)) {
        return $requestedSize;
    }
    if (preg_match('/^([1-9]\d{1,4})x([1-9]\d{1,4})$/', $requestedSize, $m)) {
        return ((int)$m[1]) . 'x' . ((int)$m[2]);
    }
    if ($generatedBytes !== '') {
        $info = @getimagesizefromstring($generatedBytes);
        if (is_array($info)) {
            $w = max(0, (int)($info[0] ?? 0));
            $h = max(0, (int)($info[1] ?? 0));
            if ($w > 0 && $h > 0) {
                if (abs($w - $h) <= max(8, (int)round(max($w, $h) * 0.03))) {
                    return '1024x1024';
                }
                return $h > $w ? '1024x1536' : '1536x1024';
            }
        }
    }
    return '1024x1024';
}

function supplier_products_db_gpt_image_2_size_is_valid(string $size): bool
{
    $size = strtolower(trim($size));
    if ($size === 'auto') {
        return true;
    }
    if (!preg_match('/^([1-9]\d{1,4})x([1-9]\d{1,4})$/', $size, $m)) {
        return false;
    }

    $w = (int)$m[1];
    $h = (int)$m[2];
    if ($w <= 0 || $h <= 0 || $w > 3840 || $h > 3840) {
        return false;
    }
    if ($w % 16 !== 0 || $h % 16 !== 0) {
        return false;
    }

    $pixels = $w * $h;
    if ($pixels < 655360 || $pixels > 8294400) {
        return false;
    }

    return (max($w, $h) / max(1, min($w, $h))) <= 3.0;
}

function supplier_products_db_normalize_gpt_image_size(string $requestedSize, string $matchedModel, string $gptImage2Default = '1200x1600'): string
{
    $requestedSize = strtolower(trim($requestedSize));
    $matchedModel = strtolower(trim($matchedModel));

    if ($matchedModel === 'gpt-image-2') {
        return supplier_products_db_gpt_image_2_size_is_valid($requestedSize)
            ? $requestedSize
            : $gptImage2Default;
    }

    return in_array($requestedSize, ['1024x1024', '1024x1536', '1536x1024', 'auto'], true)
        ? $requestedSize
        : '1024x1536';
}

function supplier_products_db_image_input_fidelity_config(string $matchedImageModel, string $requestedFidelity): array
{
    $matchedImageModel = strtolower(trim($matchedImageModel));
    $requestedFidelity = strtolower(trim($requestedFidelity));
    if (!in_array($requestedFidelity, ['low', 'high', 'auto'], true)) {
        $requestedFidelity = 'auto';
    }

    if ($matchedImageModel === 'gpt-image-2') {
        return [
            'option' => '',
            'effective' => 'high',
            'label' => 'gpt-image-2-auto-high',
            'requested' => $requestedFidelity,
            'note' => 'gpt-image-2 uses high fidelity automatically',
        ];
    }

    if ($matchedImageModel === 'gpt-image-1-mini') {
        return [
            'option' => '',
            'effective' => 'low',
            'label' => 'not_sent_for_gpt-image-1-mini',
            'requested' => $requestedFidelity,
            'note' => 'gpt-image-1-mini does not support input_fidelity',
        ];
    }

    $option = $requestedFidelity === 'low' ? 'low' : 'high';
    return [
        'option' => $option,
        'effective' => $option,
        'label' => $option,
        'requested' => $requestedFidelity,
        'note' => '',
    ];
}

function supplier_products_db_cover_quality_key(string $quality): string
{
    $quality = strtolower(trim($quality));
    return in_array($quality, ['low', 'medium', 'high'], true) ? $quality : 'medium';
}

