function supplier_products_db_cover_estimated_input_image_tokens(int $width, int $height, string $inputFidelity = 'low'): int
{
    $width = max(0, $width);
    $height = max(0, $height);
    if ($width <= 0 || $height <= 0) {
        return 0;
    }

    $scale = min(1.0, 2048.0 / max($width, $height));
    $w = max(1.0, $width * $scale);
    $h = max(1.0, $height * $scale);
    $shortest = min($w, $h);
    if ($shortest > 0) {
        $secondScale = 512.0 / $shortest;
        $w *= $secondScale;
        $h *= $secondScale;
    }
    $tiles = max(1, (int)ceil($w / 512.0) * (int)ceil($h / 512.0));
    $tokens = 65 + ($tiles * 129);

    if (strtolower(trim($inputFidelity)) === 'high') {
        $ratio = max($width, $height) / max(1, min($width, $height));
        $tokens += $ratio <= 1.2 ? 4160 : 6240;
    }

    return $tokens;
}

function supplier_products_db_cover_estimate_text_tokens(string $text): int
{
    $len = max(0, mb_strlen($text, 'UTF-8'));
    if ($len <= 0) {
        return 0;
    }
    return max(1, (int)ceil($len / 4));
}

function supplier_products_db_cover_estimate_image_usage(
    string $inputText,
    array $sourceMeta,
    string $generatedBytes,
    string $imageModel,
    string $imageQuality,
    string $imageSize,
    array $imagePricing,
    string $inputFidelity = 'low'
): array {
    $textInputTokens = supplier_products_db_cover_estimate_text_tokens($inputText);
    $matchedModel = strtolower(trim((string)($imagePricing['matched_model'] ?? $imageModel)));
    if ($matchedModel === 'gpt-image-2') {
        $inputFidelity = 'high';
    }
    $imageInputTokens = supplier_products_db_cover_estimated_input_image_tokens(
        (int)($sourceMeta['width'] ?? 0),
        (int)($sourceMeta['height'] ?? 0),
        $inputFidelity
    );
    $sizeKey = supplier_products_db_cover_output_size_key($imageSize, $generatedBytes);
    $qualityKey = supplier_products_db_cover_quality_key($imageQuality);
    $outputPrice = supplier_products_db_cover_image_output_price($imageModel, $qualityKey, $sizeKey, $imagePricing);
    $outputRate = max(0.0, (float)($imagePricing['image_output_per_1m'] ?? 0.0));
    $imageOutputTokens = $outputPrice > 0.0 && $outputRate > 0.0
        ? max(1, (int)round(($outputPrice / $outputRate) * 1_000_000))
        : 0;
    $inputTokens = $textInputTokens + $imageInputTokens;
    $outputTokens = $imageOutputTokens;

    return [
        'input_tokens' => $inputTokens,
        'cached_input_tokens' => 0,
        'text_input_tokens' => $textInputTokens,
        'text_cached_input_tokens' => 0,
        'image_input_tokens' => $imageInputTokens,
        'image_cached_input_tokens' => 0,
        'output_tokens' => $outputTokens,
        'text_output_tokens' => 0,
        'image_output_tokens' => $imageOutputTokens,
        'total_tokens' => $inputTokens + $outputTokens,
        'input_details_missing' => true,
        'output_details_missing' => true,
        'estimated' => true,
        'estimation_reason' => 'image_api_usage_missing',
        'estimated_output_price' => $outputPrice,
        'estimated_output_size' => $sizeKey,
        'estimated_quality' => $qualityKey,
    ];
}

function supplier_products_db_cover_refine_image_usage_split(
    array $usage,
    string $inputText,
    array $sourceMeta,
    string $generatedBytes,
    string $imageModel,
    string $imageQuality,
    string $imageSize,
    array $imagePricing,
    string $inputFidelity = 'low'
): array {
    if (empty($usage['input_details_missing'])) {
        return $usage;
    }

    $estimated = supplier_products_db_cover_estimate_image_usage(
        $inputText,
        $sourceMeta,
        $generatedBytes,
        $imageModel,
        $imageQuality,
        $imageSize,
        $imagePricing,
        $inputFidelity
    );

    $reportedInputTokens = max(0, (int)($usage['input_tokens'] ?? 0));
    if ($reportedInputTokens <= 0) {
        return $estimated;
    }

    $reportedOutputTokens = max(0, (int)($usage['output_tokens'] ?? 0));
    $reportedTotalTokens = max(0, (int)($usage['total_tokens'] ?? ($reportedInputTokens + $reportedOutputTokens)));
    $reportedCachedInputTokens = max(0, (int)($usage['cached_input_tokens'] ?? 0));
    if ($reportedCachedInputTokens <= 0) {
        $rawUsage = is_array($usage['raw'] ?? null) ? $usage['raw'] : [];
        $rawInputDetails = is_array($rawUsage['input_tokens_details'] ?? null) ? $rawUsage['input_tokens_details'] : [];
        $reportedCachedInputTokens = max(
            0,
            (int)($rawUsage['cached_input_tokens'] ?? ($rawUsage['cached_tokens'] ?? ($rawInputDetails['cached_tokens'] ?? ($rawInputDetails['cached_input_tokens'] ?? 0))))
        );
    }
    $reportedCachedInputTokens = min($reportedInputTokens, $reportedCachedInputTokens);

    $textInputTokens = max(0, (int)($estimated['text_input_tokens'] ?? 0));
    $imageInputTokens = max(0, (int)($estimated['image_input_tokens'] ?? 0));
    $inputTokens = $textInputTokens + $imageInputTokens;
    if ($inputTokens <= 0) {
        return $usage + [
            'reported_input_tokens' => $reportedInputTokens,
            'reported_cached_input_tokens' => $reportedCachedInputTokens,
            'reported_output_tokens' => $reportedOutputTokens,
            'reported_total_tokens' => $reportedTotalTokens,
        ];
    }

    $textCachedTokens = min($textInputTokens, $reportedCachedInputTokens);
    $imageCachedTokens = 0;
    $cachedInputTokens = $textCachedTokens;

    $estimatedImageOutputTokens = max(0, (int)($estimated['image_output_tokens'] ?? 0));
    $hasReportedOutputSplit = empty($usage['output_details_missing']);
    if ($hasReportedOutputSplit && ((int)($usage['image_output_tokens'] ?? 0) > 0 || (int)($usage['text_output_tokens'] ?? 0) > 0)) {
        $textOutputTokens = max(0, (int)($usage['text_output_tokens'] ?? 0));
        $imageOutputTokens = max(0, (int)($usage['image_output_tokens'] ?? 0));
    } else {
        $textOutputTokens = 0;
        $imageOutputTokens = $estimatedImageOutputTokens > 0 ? $estimatedImageOutputTokens : $reportedOutputTokens;
    }
    $outputTokens = $textOutputTokens + $imageOutputTokens;

    $usage['input_tokens'] = $inputTokens;
    $usage['cached_input_tokens'] = $cachedInputTokens;
    $usage['text_input_tokens'] = $textInputTokens;
    $usage['text_cached_input_tokens'] = $textCachedTokens;
    $usage['image_input_tokens'] = $imageInputTokens;
    $usage['image_cached_input_tokens'] = $imageCachedTokens;
    $usage['output_tokens'] = $outputTokens;
    $usage['text_output_tokens'] = $textOutputTokens;
    $usage['image_output_tokens'] = $imageOutputTokens;
    $usage['total_tokens'] = $inputTokens + $outputTokens;
    $usage['estimated_split'] = true;
    $usage['estimation_reason'] = 'responses_usage_without_text_image_split';
    $usage['reported_input_tokens'] = $reportedInputTokens;
    $usage['reported_cached_input_tokens'] = $reportedCachedInputTokens;
    $usage['reported_output_tokens'] = $reportedOutputTokens;
    $usage['reported_total_tokens'] = $reportedTotalTokens;
    $usage['pricing_usage_source'] = 'estimated_image_generation_usage_from_missing_details';
    if (isset($estimated['estimated_output_price'])) {
        $usage['estimated_output_price'] = $estimated['estimated_output_price'];
        $usage['estimated_output_size'] = $estimated['estimated_output_size'] ?? '';
        $usage['estimated_quality'] = $estimated['estimated_quality'] ?? '';
    }
    return $usage;
}

function supplier_products_db_cover_save_image(int $supplierId, int $productId, string $bytes, array $cfg): string
{
    $info = @getimagesizefromstring($bytes);
    if (!is_array($info)) {
        throw new RuntimeException('Не удалось распознать готовую GPT-обложку.');
    }
    $mime = strtolower((string)($info['mime'] ?? ''));
    $ext = match ($mime) {
        'image/jpeg' => 'jpg',
        'image/png' => 'png',
        'image/webp' => 'webp',
        default => '',
    };
    if ($ext === '') {
        throw new RuntimeException('GPT-обложка вернулась в неподдерживаемом формате.');
    }

    $baseDir = supplier_products_image_storage_dir($cfg);
    $relativeDir = 'supplier_' . $supplierId . '/' . date('Ym') . '/gpt_cover';
    $dir = supplier_products_ensure_writable_dir($baseDir . '/' . $relativeDir, 'Не удалось создать папку для GPT-обложек.');
    $fileName = 'product_' . $productId . '_cover_' . date('Ymd_His') . '_' . bin2hex(random_bytes(5)) . '.' . $ext;
    $path = $dir . '/' . $fileName;
    if (file_put_contents($path, $bytes) === false) {
        throw new RuntimeException('Не удалось сохранить GPT-обложку.');
    }
    @chmod($path, 0664);

    return supplier_products_publish_stored_image($path, $relativeDir . '/' . $fileName, $cfg, true);
}

function supplier_products_db_cover_marketplace_output_image(string $bytes, int $targetW = 1200, int $targetH = 1600, int $jpegQuality = 92): array
{
    $info = @getimagesizefromstring($bytes);
    if (!is_array($info)) {
        throw new RuntimeException('Не удалось распознать готовую GPT-обложку для финального размера.');
    }
    $srcW = (int)($info[0] ?? 0);
    $srcH = (int)($info[1] ?? 0);
    $srcMime = strtolower((string)($info['mime'] ?? ''));
    if ($srcW <= 0 || $srcH <= 0) {
        throw new RuntimeException('GPT-обложка вернулась с некорректным размером.');
    }
    $targetW = max(1, $targetW);
    $targetH = max(1, $targetH);
    $jpegQuality = max(1, min(100, $jpegQuality));
    $targetRatio = $targetW / $targetH;
    $sourceRatio = $srcW / $srcH;
    if (abs($sourceRatio - $targetRatio) > 0.006) {
        throw new RuntimeException(
            "GPT-обложка вернулась не в формате 3:4 ({$srcW}x{$srcH}). " .
            "Перезапусти генерацию с gpt-image-2 и размером 1200x1600."
        );
    }
    if (!extension_loaded('gd')) {
        throw new RuntimeException('Для подготовки финальной обложки 1200x1600 требуется PHP GD.');
    }

    $source = @imagecreatefromstring($bytes);
    if (!$source instanceof GdImage) {
        throw new RuntimeException('Не удалось открыть GPT-обложку для финальной обработки.');
    }

    $fitScale = min($targetW / $srcW, $targetH / $srcH);
    $fgW = max(1, (int)round($srcW * $fitScale));
    $fgH = max(1, (int)round($srcH * $fitScale));

    $canvas = imagecreatetruecolor($fgW, $fgH);
    if (!$canvas instanceof GdImage) {
        unset($source);
        throw new RuntimeException('Не удалось создать холст финальной обложки.');
    }

    imagealphablending($canvas, true);
    imagesavealpha($canvas, false);

    imagecopyresampled($canvas, $source, 0, 0, 0, 0, $fgW, $fgH, $srcW, $srcH);
    imageinterlace($canvas, true);

    ob_start();
    $ok = imagejpeg($canvas, null, $jpegQuality);
    $out = ob_get_clean();
    unset($source, $canvas);
    if (!$ok || !is_string($out) || $out === '') {
        throw new RuntimeException('Не удалось сохранить финальную обложку в JPEG.');
    }

    $outInfo = @getimagesizefromstring($out);
    return [
        'bytes' => $out,
        'meta' => [
            'format' => 'jpeg',
            'jpeg_quality' => $jpegQuality,
            'source_width' => $srcW,
            'source_height' => $srcH,
            'source_mime' => $srcMime,
            'width' => is_array($outInfo) ? (int)($outInfo[0] ?? $targetW) : $targetW,
            'height' => is_array($outInfo) ? (int)($outInfo[1] ?? $targetH) : $targetH,
            'mode' => 'proportional_resize_no_crop_no_padding',
            'max_width' => $targetW,
            'max_height' => $targetH,
            'scale' => $fitScale,
        ],
    ];
}

function supplier_products_db_photo_variant_picture_is_generated(string $url): bool
{
    $relative = supplier_products_local_image_relative_from_url($url);
    if ($relative === '') {
        return false;
    }
    $relative = str_replace('\\', '/', $relative);
    return str_contains($relative, '/gpt_cover/')
        || str_contains($relative, '/gpt_photo_variant/')
        || str_contains($relative, '/photo_collage/')
        || str_contains($relative, '/product_specs_photo/');
}

function supplier_products_db_photo_variant_source_picture(array $pictures): string
{
    $sourcePictures = supplier_products_db_photo_variant_source_pictures($pictures);
    return (string)($sourcePictures[0] ?? '');
}

function supplier_products_db_photo_variant_source_pictures(array $pictures): array
{
    $out = [];
    $seen = [];
    foreach (supplier_products_normalize_picture_urls($pictures) as $picture) {
        $picture = trim((string)$picture);
        if ($picture === '' || isset($seen[$picture]) || supplier_products_db_photo_variant_picture_is_generated($picture)) {
            continue;
        }
        $seen[$picture] = true;
        $out[] = $picture;
    }
    return $out;
}

function supplier_products_db_photo_variant_pictures_with_new_image(array $pictures, string $newUrl): array
{
    $out = supplier_products_normalize_picture_urls($pictures);
    $newUrl = trim($newUrl);
    if ($newUrl === '') {
        return $out;
    }
    $seen = array_fill_keys($out, true);
    if (!isset($seen[$newUrl])) {
        $out[] = $newUrl;
    }
    return array_values($out);
}

