function supplier_products_db_photo_variant_prompt_text(string $prompt, array $payload): array
{
    $staticRules = is_array($payload['rules'] ?? null) ? $payload['rules'] : [];
    $product = is_array($payload['product'] ?? null) ? $payload['product'] : [];
    $category = is_array($payload['category'] ?? null) ? $payload['category'] : [];
    $cardBrief = is_array($payload['card_brief'] ?? null) ? $payload['card_brief'] : [];
    $staticRulesJson = supplier_products_db_cover_prompt_json($staticRules);
    $productJson = supplier_products_db_cover_prompt_json([
        'product' => $product,
        'category' => $category,
        'card_brief' => $cardBrief,
    ]);
    $staticPrefix = $prompt
        . "\n\nSTATIC PHOTO RULES JSON (static for prompt cache):\n"
        . $staticRulesJson;
    $text = $staticPrefix
        . "\n\nPRODUCT JSON (dynamic product data):\n"
        . $productJson;
    return [
        'text' => $text,
        'format' => 'product_photo_variant_static_rules_product_dynamic_v3_card_brief',
        'static_prefix_sha256' => hash('sha256', $staticPrefix),
        'static_rules_sha256' => hash('sha256', $staticRulesJson),
        'payload_sha256' => hash('sha256', $productJson),
    ];
}

function supplier_products_db_photo_variant_prompt_cache_key(string $imageModel, string $imageSize, string $imageQuality, array $promptMeta): string
{
    $staticPrefixHash = trim((string)($promptMeta['static_prefix_sha256'] ?? ''));
    if ($staticPrefixHash === '') {
        $staticPrefixHash = hash('sha256', (string)($promptMeta['format'] ?? 'photo_variant'));
    }

    $payload = [
        'op' => 'gpt_generate_product_photo_variant',
        'endpoint' => 'responses_image_generation',
        'format' => (string)($promptMeta['format'] ?? ''),
        'static_prefix_sha256' => $staticPrefixHash,
        'image_model' => strtolower(trim($imageModel)),
        'image_size' => strtolower(trim($imageSize)),
        'image_quality' => strtolower(trim($imageQuality)),
    ];
    $json = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($json === false) {
        $json = $staticPrefixHash;
    }

    return 'photo_var:' . substr(hash('sha256', $json), 0, 48);
}

function supplier_products_db_photo_collage_picture_is_generated(string $url): bool
{
