function supplier_products_db_photo_collage_source_pictures(array $pictures, int $count = 3): array
{
    $out = [];
    foreach (supplier_products_normalize_picture_urls($pictures) as $picture) {
        $picture = trim((string)$picture);
        if ($picture === '' || supplier_products_db_photo_collage_picture_is_generated($picture)) {
            continue;
        }
        $out[] = $picture;
        if (count($out) >= $count) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_photo_collage_without_existing_collages(array $pictures): array
{
    $out = [];
    foreach (supplier_products_normalize_picture_urls($pictures) as $picture) {
        $relative = supplier_products_local_image_relative_from_url($picture);
        if ($relative !== '' && str_contains(str_replace('\\', '/', $relative), '/photo_collage/')) {
            continue;
        }
        $out[] = $picture;
    }
    return $out;
}

function supplier_products_db_photo_collage_has_generated(array $pictures): bool
{
    foreach (supplier_products_normalize_picture_urls($pictures) as $picture) {
        $relative = supplier_products_local_image_relative_from_url($picture);
        if ($relative !== '' && str_contains(str_replace('\\', '/', $relative), '/photo_collage/')) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_photo_collage_pictures_with_new_image(array $pictures, string $newUrl): array
{
    $out = supplier_products_normalize_picture_urls($pictures);
    $newUrl = trim($newUrl);
    if ($newUrl === '') {
        return $out;
    }
    $seen = array_fill_keys($out, true);
    if (!isset($seen[$newUrl])) {
        $out[] = $newUrl;
    }
    return array_values($out);
}

function supplier_products_db_photo_collage_save_image(int $supplierId, int $productId, string $bytes, array $cfg): string
{
    $info = @getimagesizefromstring($bytes);
    if (!is_array($info)) {
        throw new RuntimeException('Не удалось распознать готовый коллаж.');
    }

    $baseDir = supplier_products_image_storage_dir($cfg);
    $relativeDir = 'supplier_' . $supplierId . '/' . date('Ym') . '/photo_collage';
    $dir = supplier_products_ensure_writable_dir($baseDir . '/' . $relativeDir, 'Не удалось создать папку для коллажей.');
    $fileName = 'product_' . $productId . '_collage_' . date('Ymd_His') . '_' . bin2hex(random_bytes(5)) . '.jpg';
    $path = $dir . '/' . $fileName;
    if (file_put_contents($path, $bytes) === false) {
        throw new RuntimeException('Не удалось сохранить коллаж.');
    }
    @chmod($path, 0664);

    return supplier_products_publish_stored_image($path, $relativeDir . '/' . $fileName, $cfg, true);
}

function supplier_products_db_photo_collage_load_source(string $url, array $cfg): array
{
    $source = supplier_products_bundle_photo_source_path($url, $cfg);
    try {
        $image = supplier_products_bundle_photo_load((string)$source['path']);
        return [
            'image' => $image,
            'url' => $url,
            'width' => imagesx($image),
            'height' => imagesy($image),
        ];
    } finally {
        if (!empty($source['temporary'])) {
            @unlink((string)$source['path']);
        }
    }
}

function supplier_products_db_photo_collage_draw_tile(GdImage $canvas, GdImage $source, int $x, int $y, int $w, int $h, int $padding): array
{
    $w = max(1, $w);
    $h = max(1, $h);
    $padding = max(0, min($padding, max(0, intdiv(min($w, $h), 2) - 4)));
    $border = imagecolorallocate($canvas, 225, 232, 242);
    $card = imagecolorallocate($canvas, 255, 255, 255);
    $inner = imagecolorallocate($canvas, 250, 252, 255);
    $radius = 24;
    supplier_products_bundle_photo_rounded_rect($canvas, $x, $y, $x + $w, $y + $h, $radius, $border);
    supplier_products_bundle_photo_rounded_rect($canvas, $x + 2, $y + 2, $x + $w - 2, $y + $h - 2, max(0, $radius - 2), $card);
    supplier_products_bundle_photo_rounded_rect($canvas, $x + $padding, $y + $padding, $x + $w - $padding, $y + $h - $padding, 12, $inner);

    $srcW = max(1, imagesx($source));
    $srcH = max(1, imagesy($source));
    $fitW = max(1, $w - ($padding * 2));
    $fitH = max(1, $h - ($padding * 2));
    $scale = min($fitW / $srcW, $fitH / $srcH);
    $dstW = max(1, (int)round($srcW * $scale));
    $dstH = max(1, (int)round($srcH * $scale));
    $dstX = $x + (int)floor(($w - $dstW) / 2);
    $dstY = $y + (int)floor(($h - $dstH) / 2);
    if (function_exists('imagesetinterpolation')) {
        @imagesetinterpolation($source, IMG_BICUBIC_FIXED);
    }
    imagecopyresampled($canvas, $source, $dstX, $dstY, 0, 0, $dstW, $dstH, $srcW, $srcH);

    return [
        'x' => $dstX,
        'y' => $dstY,
        'width' => $dstW,
        'height' => $dstH,
        'source_width' => $srcW,
        'source_height' => $srcH,
    ];
}

function supplier_products_db_photo_collage_create(array $sourceUrls, array $cfg, int $targetW = 1200, int $targetH = 1600, int $jpegQuality = 92): array
{
    if (!extension_loaded('gd')) {
        throw new RuntimeException('Для сборки коллажа требуется PHP GD.');
    }
    $sourceUrls = array_values(array_filter(array_map('trim', array_map('strval', $sourceUrls))));
    if (count($sourceUrls) < 2) {
        throw new RuntimeException('Для коллажа нужно минимум 2 фото товара.');
    }
    $sourceCount = min(3, count($sourceUrls));

    $loaded = [];
    try {
        foreach (array_slice($sourceUrls, 0, $sourceCount) as $url) {
            $loaded[] = supplier_products_db_photo_collage_load_source($url, $cfg);
        }

        $targetW = max(1, $targetW);
        $targetH = max(1, $targetH);
        $jpegQuality = max(1, min(100, $jpegQuality));
        $canvas = imagecreatetruecolor($targetW, $targetH);
        if (!$canvas instanceof GdImage) {
            throw new RuntimeException('Не удалось создать холст коллажа.');
        }
        imagealphablending($canvas, true);
        imagesavealpha($canvas, false);

        $bg = imagecolorallocate($canvas, 248, 250, 253);
        imagefilledrectangle($canvas, 0, 0, $targetW, $targetH, $bg);

        $margin = 72;
        $gap = 44;
        $topX = $margin;
        $topY = 72;
        $topW = $targetW - ($margin * 2);
        $topH = 820;
        $bottomY = $topY + $topH + $gap;
        $bottomLeftW = (int)floor(($topW - $gap) / 2);
        $bottomRightW = $topW - $gap - $bottomLeftW;
        $bottomH = max(1, min(520, $targetH - $bottomY - 72));

        $placements = [];
        if ($sourceCount === 2) {
            $twoTileH = (int)floor(($targetH - ($topY * 2) - $gap) / 2);
            $placements[] = supplier_products_db_photo_collage_draw_tile($canvas, $loaded[0]['image'], $topX, $topY, $topW, $twoTileH, 40);
            $placements[] = supplier_products_db_photo_collage_draw_tile($canvas, $loaded[1]['image'], $topX, $topY + $twoTileH + $gap, $topW, $twoTileH, 40);
            $layout = 'two_large_vertical_clean';
        } else {
            $placements[] = supplier_products_db_photo_collage_draw_tile($canvas, $loaded[0]['image'], $topX, $topY, $topW, $topH, 40);
            $placements[] = supplier_products_db_photo_collage_draw_tile($canvas, $loaded[1]['image'], $topX, $bottomY, $bottomLeftW, $bottomH, 34);
            $placements[] = supplier_products_db_photo_collage_draw_tile($canvas, $loaded[2]['image'], $topX + $bottomLeftW + $gap, $bottomY, $bottomRightW, $bottomH, 34);
            $layout = 'large_top_two_bottom_clean';
        }

        imageinterlace($canvas, true);
        ob_start();
        $ok = imagejpeg($canvas, null, $jpegQuality);
        $bytes = ob_get_clean();
        unset($canvas);
        if (!$ok || !is_string($bytes) || $bytes === '') {
            throw new RuntimeException('Не удалось сохранить коллаж в JPEG.');
        }

        return [
            'bytes' => $bytes,
            'meta' => [
                'format' => 'jpeg',
                'jpeg_quality' => $jpegQuality,
                'width' => $targetW,
                'height' => $targetH,
                'layout' => $layout,
                'source_count' => $sourceCount,
                'source_urls' => array_slice($sourceUrls, 0, $sourceCount),
                'placements' => $placements,
            ],
        ];
    } finally {
        foreach ($loaded as $item) {
            if (($item['image'] ?? null) instanceof GdImage) {
                imagedestroy($item['image']);
            }
        }
    }
}

function supplier_products_db_video_cover_picture_is_blocked(string $url): bool
{
    $relative = supplier_products_local_image_relative_from_url($url);
    if ($relative === '') {
        return false;
    }
    $relative = str_replace('\\', '/', $relative);
    return str_contains($relative, '/product_specs_photo/')
        || str_contains($relative, '/photo_collage/');
}

function supplier_products_db_video_cover_source_pictures(array $pictures, int $count = 4): array
{
    $count = max(1, min(6, $count));
    $out = [];
    $seen = [];
    foreach (supplier_products_normalize_picture_urls($pictures) as $picture) {
        $picture = trim((string)$picture);
        if ($picture === '' || isset($seen[$picture]) || supplier_products_db_video_cover_picture_is_blocked($picture)) {
            continue;
        }
        $seen[$picture] = true;
        $out[] = $picture;
        if (count($out) >= $count) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_video_cover_compact_text(string $value, int $maxLen): string
{
    $value = supplier_products_db_plain_text($value);
    $value = preg_replace('~\s+~u', ' ', $value);
    $value = trim((string)$value);
    if ($value === '' || $maxLen <= 0) {
        return $value;
    }
    if (mb_strlen($value, 'UTF-8') <= $maxLen) {
        return $value;
    }
    $cut = mb_substr($value, 0, $maxLen, 'UTF-8');
    $space = mb_strrpos($cut, ' ', 0, 'UTF-8');
    if ($space !== false && $space >= (int)floor($maxLen * 0.65)) {
        $cut = mb_substr($cut, 0, $space, 'UTF-8');
    }
    return rtrim($cut, " \t\n\r\0\x0B.,;:-") . '...';
}

function supplier_products_db_video_cover_param_is_noise(string $name, string $value): bool
{
    $nameNorm = mb_strtolower($name, 'UTF-8');
    $valueNorm = mb_strtolower($value, 'UTF-8');
    if (preg_match('~(?:ссылка|url|link|фото|изображ|картин|видео|video|штрих|barcode|sku|артикул|id|fbo|fbs|tnved|тнвэд|тн вэд)~u', $nameNorm)) {
        return true;
    }
    if (preg_match('~^https?://~iu', $valueNorm)) {
        return true;
    }
    return false;
}

function supplier_products_db_video_cover_param_score(string $name, string $value, int $index): int
{
    $nameNorm = mb_strtolower($name, 'UTF-8');
    $valueNorm = mb_strtolower($value, 'UTF-8');
    $score = max(0, 40 - min(35, $index));
    if (preg_match('~(?:тип|вид|назнач|совмест|модель|бренд|производитель|материал|состав|цвет|размер|габарит|длина|ширина|высота|диаметр|вес|объем|ёмкость|плотность|мощность|напряж|комплект|количество|формат|разрешение|экран|креплен|разъем|разъём|упаков|поверхность|фактура|ткань|наволоч|простын|пододеял)~u', $nameNorm)) {
        $score += 90;
    }
    if (preg_match('~(?:металл|пластик|стекло|силикон|кожа|сатин|хлопок|полиэстер|черн|бел|сер|красн|син|зелен|беж|прозрач|матов|глянц)~u', $valueNorm)) {
        $score += 20;
    }
    $len = mb_strlen($value, 'UTF-8');
    if ($len > 120) {
        $score -= 25;
    } elseif ($len <= 60) {
        $score += 8;
    }
    return $score;
}

function supplier_products_db_video_cover_compact_params(array $fields, int $limit = 14): array
{
    $limit = max(4, min(24, $limit));
    $params = [];
    $seen = [];
    $idx = 0;
    foreach (supplier_products_db_product_params_payload($fields) as $param) {
        $name = supplier_products_db_video_cover_compact_text((string)($param['name'] ?? ''), 70);
        $value = supplier_products_db_video_cover_compact_text((string)($param['value'] ?? ''), 110);
        if ($name === '' || $value === '' || supplier_products_db_video_cover_param_is_noise($name, $value)) {
            $idx++;
            continue;
        }
        $key = supplier_products_db_attr_norm($name . ' ' . $value);
        if ($key === '' || isset($seen[$key])) {
            $idx++;
            continue;
        }
        $seen[$key] = true;
        $params[] = [
            'score' => supplier_products_db_video_cover_param_score($name, $value, $idx),
            'index' => $idx,
            'marketplace' => (string)($param['marketplace'] ?? ''),
            'name' => $name,
            'value' => $value,
        ];
        $idx++;
    }
    usort($params, static function (array $a, array $b): int {
        $scoreCmp = ((int)($b['score'] ?? 0)) <=> ((int)($a['score'] ?? 0));
        if ($scoreCmp !== 0) {
            return $scoreCmp;
        }
        return ((int)($a['index'] ?? 0)) <=> ((int)($b['index'] ?? 0));
    });
    $out = [];
    foreach (array_slice($params, 0, $limit) as $row) {
        unset($row['score'], $row['index']);
        $out[] = $row;
    }
    return $out;
}

function supplier_products_db_video_cover_compact_features(array $features, int $limit = 4): array
{
    $limit = max(0, min(6, $limit));
    $out = [];
    $seen = [];
    foreach ($features as $feature) {
        $value = supplier_products_db_video_cover_compact_text((string)$feature, 80);
        if ($value === '') {
            continue;
        }
        $key = supplier_products_db_attr_norm($value);
        if ($key === '' || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $out[] = $value;
        if (count($out) >= $limit) {
            break;
        }
    }
    return $out;
}

function supplier_products_db_video_cover_product_payload(array $product, array $fields, array $context, string $offerId, string $shortName): array
{
    $name = supplier_products_db_video_cover_compact_text((string)($product['name'] ?? ''), 170);
    $shortName = supplier_products_db_video_cover_compact_text($shortName, 120);
    if ($shortName === '') {
        $shortName = $name;
    }
    return [
        'offer_id' => $offerId,
        'name' => $name,
        'short_name' => $shortName,
        'brand' => supplier_products_db_video_cover_compact_text((string)($context['brand'] ?? ($product['brand'] ?? '')), 70),
        'model' => supplier_products_db_video_cover_compact_text((string)($context['model'] ?? ''), 90),
        'vendor' => supplier_products_db_video_cover_compact_text((string)($context['vendor'] ?? ''), 70),
        'category_path' => supplier_products_db_video_cover_compact_text((string)($product['category_path'] ?? ''), 160),
        'description_hint' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 360),
        'visual_params' => supplier_products_db_video_cover_compact_params($fields, 14),
    ];
}

function supplier_products_db_video_cover_source_photo_context(array $sourcePictures): array
{
    $roles = [];
    foreach ($sourcePictures as $idx => $url) {
        $role = supplier_products_db_cover_picture_is_generated((string)$url) ? 'generated_photo_cover' : 'product_photo';
        $roles[] = [
            'index' => $idx + 1,
            'role' => $role,
            'is_input_reference' => $idx === 0,
        ];
    }
    return [
        'count' => count($roles),
        'input_reference_is_first_image' => true,
        'items' => $roles,
        'note' => 'URLs are intentionally omitted from prompt; only the first image is uploaded to Sora as input_reference.',
    ];
}

function supplier_products_db_video_cover_storyboard_payload(array $categoryPayload, array $productPayload, array $features, string $durationMode, int $soraSeconds, int $finalSeconds): array
{
    $subject = (string)($productPayload['short_name'] ?? '');
    if ($subject === '') {
        $subject = (string)($productPayload['name'] ?? 'товар');
    }
    $subject = supplier_products_db_video_cover_compact_text($subject, 110);
    $category = supplier_products_db_video_cover_compact_text((string)($productPayload['category_path'] ?? ''), 120);
    $accent = supplier_products_db_video_cover_compact_text(implode('; ', array_slice($features, 0, 3)), 180);
    if ($accent === '') {
        $params = [];
        foreach ((array)($productPayload['visual_params'] ?? []) as $param) {
            $paramName = trim((string)($param['name'] ?? ''));
            $paramValue = trim((string)($param['value'] ?? ''));
            if ($paramName !== '' && $paramValue !== '') {
                $params[] = $paramName . ': ' . $paramValue;
            }
            if (count($params) >= 3) {
                break;
            }
        }
        $accent = supplier_products_db_video_cover_compact_text(implode('; ', $params), 180);
    }
    $categoryDesign = supplier_products_db_video_cover_compact_text((string)($categoryPayload['video_cover_design'] ?? ''), 700);
    $pace = $durationMode === 'slow_4_to_8'
        ? 'Generate one continuous 4s motion designed to be slowed to 8s: fewer events, smoother camera, no fast cuts, no static hold at the beginning or end.'
        : 'Use the full duration with 3-4 clear beats, continuous motion, no hard cuts, no static hold at the beginning or end.';

    return [
        'intent' => 'premium marketplace product ad, not a slideshow',
        'subject' => $subject,
        'category' => $category,
        'real_visual_accents' => $accent,
        'category_design' => $categoryDesign,
        'pace' => $pace,
        'beats' => [
            'hook' => 'Begin close to the uploaded cover composition, but motion starts immediately at 0.0s: subtle dolly-in/orbit, parallax and a clean light sweep across the product contour. Do not hold a still cover frame.',
            'hero_motion' => 'Keep the product centered in the 3:4 safe area; create depth with parallax background, soft shadows and controlled camera movement.',
            'detail_reveal' => 'Reveal one or two real product details with macro feel, rim light, subtle scan/glow or layered depth. Do not invent new parts.',
            'final_packshot' => 'Return to a sharp centered packshot with calm premium lighting and readable existing cover text if present, but keep a slow living camera/light motion until the final frame. No static end card.',
        ],
        'negative_direction' => [
            'no photo slideshow',
            'no sequential gallery',
            'no floating photo cards',
            'no frozen cover at start',
            'no static final end card',
            'no new text, prices, discounts, QR, marketplace logos',
            'no people, hands, faces',
        ],
        'sora_generated_seconds' => $soraSeconds,
        'final_video_seconds' => $finalSeconds,
    ];
}

function supplier_products_db_video_cover_field_names(): array
{
    return [
        'Озон.Видеообложка: ссылка',
        'Ozon.VideoCover: link',
        'Видеообложка',
        'Видео-обложка',
    ];
}

function supplier_products_db_video_cover_field_norm(string $name): string
{
    $name = mb_strtolower(trim($name), 'UTF-8');
    $name = preg_replace('~[^\p{L}\p{N}]+~u', ' ', $name) ?: '';
    return trim(preg_replace('~\s+~u', ' ', $name) ?: '');
}

function supplier_products_db_video_cover_existing_url(array $fields): string
{
    $wanted = [];
    foreach (supplier_products_db_video_cover_field_names() as $name) {
        $norm = supplier_products_db_video_cover_field_norm($name);
        if ($norm !== '') {
            $wanted[$norm] = true;
        }
    }
    foreach ($fields as $field) {
        if ((string)($field['field_kind'] ?? '') !== 'param') {
            continue;
        }
        $nameNorm = supplier_products_db_video_cover_field_norm((string)($field['field_name'] ?? ''));
        $value = trim((string)($field['field_value'] ?? ''));
        if ($value !== '' && isset($wanted[$nameNorm])) {
            return $value;
        }
    }
    return '';
}

function supplier_products_db_video_cover_set_url(PDO $pdo, int $supplierId, int $productId, string $url): bool
{
    return supplier_products_db_set_param_value(
        $pdo,
        $supplierId,
        $productId,
        'param',
        'Озон.Видеообложка: ссылка',
        $url
    );
}

function supplier_products_db_video_cover_save_video(int $supplierId, int $productId, string $sourcePath, array $cfg): string
{
    if (!is_file($sourcePath) || (int)@filesize($sourcePath) <= 0) {
        throw new RuntimeException('Не удалось сохранить видео-обложку: готовый MP4 не найден.');
    }

    $baseDir = supplier_products_image_storage_dir($cfg);
    $relativeDir = 'supplier_' . $supplierId . '/' . date('Ym') . '/video_cover';
    $dir = supplier_products_ensure_writable_dir($baseDir . '/' . $relativeDir, 'Не удалось создать папку для видео-обложек.');
    $fileName = 'product_' . $productId . '_video_cover_' . date('Ymd_His') . '_' . bin2hex(random_bytes(5)) . '.mp4';
    $path = $dir . '/' . $fileName;
    if (!@copy($sourcePath, $path)) {
        throw new RuntimeException('Не удалось сохранить видео-обложку.');
    }
    @chmod($path, 0664);

    return supplier_products_publish_stored_image($path, $relativeDir . '/' . $fileName, $cfg, true);
}

function supplier_products_db_video_cover_parse_size(string $size): array
{
    $size = strtolower(trim($size));
    if (!preg_match('/^([1-9]\d{1,4})x([1-9]\d{1,4})$/', $size, $m)) {
        return [720, 1280];
    }
    $w = max(2, min(4096, (int)$m[1]));
    $h = max(2, min(4096, (int)$m[2]));
    if ($w % 2 !== 0) {
        $w++;
    }
    if ($h % 2 !== 0) {
        $h++;
    }
    return [$w, $h];
}

function supplier_products_db_sora_video_size_is_supported(string $model, string $size): bool
{
    $model = strtolower(trim(openai_pricing_normalize_model_for_match($model)));
    $size = strtolower(trim($size));
    $basic = ['720x1280', '1280x720'];
    $pro = ['720x1280', '1280x720', '1024x1792', '1792x1024', '1080x1920', '1920x1080'];
    if (str_starts_with($model, 'sora-2-pro')) {
        return in_array($size, $pro, true);
    }
    if (str_starts_with($model, 'sora-2')) {
        return in_array($size, $basic, true);
    }
    return in_array($size, $pro, true);
}

function supplier_products_db_sora_normalize_video_size(string $model, string $size): string
{
    $size = strtolower(trim($size));
    if (supplier_products_db_sora_video_size_is_supported($model, $size)) {
        return $size;
    }
    $model = strtolower(trim(openai_pricing_normalize_model_for_match($model)));
    return str_starts_with($model, 'sora-2-pro') ? '1024x1792' : '720x1280';
}

function supplier_products_db_sora_normalize_video_seconds(string $seconds): int
{
    $value = (int)trim($seconds);
    $allowed = [4, 8, 12, 16, 20];
    return in_array($value, $allowed, true) ? $value : 8;
}

function supplier_products_db_video_cover_reference_picture(array $pictures): string
{
    $pictures = supplier_products_normalize_picture_urls($pictures);
    if (!$pictures) {
        return '';
    }
    $first = trim((string)($pictures[0] ?? ''));
    if ($first !== '' && supplier_products_db_cover_picture_is_generated($first)) {
        return $first;
    }
    foreach ($pictures as $picture) {
        $picture = trim((string)$picture);
        if ($picture !== '' && supplier_products_db_cover_picture_is_generated($picture)) {
            return $picture;
        }
    }
    foreach ($pictures as $picture) {
        $picture = trim((string)$picture);
        if ($picture !== '' && !supplier_products_db_video_cover_picture_is_blocked($picture)) {
            return $picture;
        }
    }
    return $first;
}

function supplier_products_db_video_cover_category_payload(array $product, array $fields): array
{
    $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
    $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
    $videoCoverDesign = supplier_products_db_video_cover_category_design_text($ozonCategory, $wbCategory, 'video_cover_design');
    $coverDesign = supplier_products_db_video_cover_category_design_text($ozonCategory, $wbCategory, 'cover_design');

    return [
        'video_cover_design' => $videoCoverDesign,
        'video_cover_generation_directive' => 'Сделай цельное рекламное product ad video, а не слайдшоу: hook, hero motion, detail reveal, final packshot; используй движение камеры, свет, глубину, parallax/orbit, category motion graphics и реальные визуальные детали товара. Не показывай исходные фото последовательно и не делай простые crossfade между статичными кадрами.',
        'cover_design' => $coverDesign,
        'style_source' => $videoCoverDesign !== '' ? 'taxonomy_category_meta.video_cover_design' : '',
    ];
}

function supplier_products_db_video_cover_category_design_text(string $ozonCategory, string $wbCategory, string $metaKey): string
{
    $metaKey = trim($metaKey);
    if ($metaKey === '') {
        return '';
    }
    $items = [];
    foreach ([
        ['source' => 'ozon', 'label' => 'Ozon', 'value' => $ozonCategory],
        ['source' => 'wildberries', 'label' => 'Wildberries', 'value' => $wbCategory],
    ] as $row) {
        $value = trim((string)$row['value']);
        if ($value === '') {
            continue;
        }
        $meta = supplier_products_taxonomy_meta_for_category_value((string)$row['source'], $value);
        $design = trim((string)($meta[$metaKey] ?? ''));
        if ($design === '') {
            continue;
        }
        $items[] = '[' . (string)$row['label'] . '] ' . supplier_products_db_description_snippet($design, 900);
    }
    if (!$items) {
        return '';
    }
    if (count($items) === 1) {
        return preg_replace('~^\[(?:Ozon|Wildberries)\]\s*~u', '', $items[0]) ?: $items[0];
    }
    return implode("\n\n", array_values(array_unique($items)));
}

function supplier_products_db_video_cover_prompt_json($value): string
{
    $json = json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    return $json === false ? '{}' : $json;
}

function supplier_products_db_gpt_video_cover_reference_image(string $url, array $cfg, string $videoSize): array
{
    if (!extension_loaded('gd')) {
        throw new RuntimeException('Для подготовки input_reference Sora требуется PHP GD.');
    }
    [$targetW, $targetH] = supplier_products_db_video_cover_parse_size($videoSize);
    $source = supplier_products_bundle_photo_source_path($url, $cfg);
    try {
        $path = (string)$source['path'];
        if ($path === '' || !is_file($path)) {
            throw new RuntimeException('Не удалось подготовить фото-обложку для Sora.');
        }
        $image = supplier_products_bundle_photo_load($path);
        $srcW = max(1, imagesx($image));
        $srcH = max(1, imagesy($image));

        $canvas = imagecreatetruecolor($targetW, $targetH);
        if (!$canvas instanceof GdImage) {
            imagedestroy($image);
            throw new RuntimeException('Не удалось создать input_reference для Sora.');
        }
        imagealphablending($canvas, true);
        imagesavealpha($canvas, false);
        $bgColor = imagecolorallocate($canvas, 248, 250, 253);
        imagefilledrectangle($canvas, 0, 0, $targetW, $targetH, $bgColor);

        if (function_exists('imagesetinterpolation')) {
            @imagesetinterpolation($image, IMG_BICUBIC_FIXED);
        }
        $bgScale = max($targetW / $srcW, $targetH / $srcH) * 1.02;
        $bgW = max(1, (int)round($srcW * $bgScale));
        $bgH = max(1, (int)round($srcH * $bgScale));
        $bgX = (int)floor(($targetW - $bgW) / 2);
        $bgY = (int)floor(($targetH - $bgH) / 2);
        imagecopyresampled($canvas, $image, $bgX, $bgY, 0, 0, $bgW, $bgH, $srcW, $srcH);
        for ($i = 0; $i < 8; $i++) {
            imagefilter($canvas, IMG_FILTER_GAUSSIAN_BLUR);
        }
        imagefilter($canvas, IMG_FILTER_BRIGHTNESS, 8);
        imagefilter($canvas, IMG_FILTER_CONTRAST, -8);
        $veil = imagecolorallocatealpha($canvas, 255, 255, 255, 58);
        imagefilledrectangle($canvas, 0, 0, $targetW, $targetH, $veil);

        $fgScale = min($targetW / $srcW, $targetH / $srcH);
        $fgW = max(1, (int)round($srcW * $fgScale));
        $fgH = max(1, (int)round($srcH * $fgScale));
        $fgX = (int)floor(($targetW - $fgW) / 2);
        $fgY = (int)floor(($targetH - $fgH) / 2);
        imagecopyresampled($canvas, $image, $fgX, $fgY, 0, 0, $fgW, $fgH, $srcW, $srcH);

        imageinterlace($canvas, true);
        ob_start();
        $ok = imagejpeg($canvas, null, 92);
        $bytes = ob_get_clean();
        imagedestroy($image);
        imagedestroy($canvas);
        if (!$ok || !is_string($bytes) || $bytes === '') {
            throw new RuntimeException('Не удалось закодировать input_reference для Sora.');
        }

        return [
            'bytes' => $bytes,
            'mime' => 'image/jpeg',
            'width' => $targetW,
            'height' => $targetH,
            'source_url' => $url,
            'source_width' => $srcW,
            'source_height' => $srcH,
            'size_bytes' => strlen($bytes),
            'mode' => 'fit_cover_on_blurred_background',
        ];
    } finally {
        if (!empty($source['temporary'])) {
            @unlink((string)$source['path']);
        }
    }
}

function supplier_products_db_gpt_video_cover_prompt_text(string $prompt, array $payload): array
{
    $category = is_array($payload['category'] ?? null) ? $payload['category'] : [];
    $rules = is_array($payload['rules'] ?? null) ? $payload['rules'] : [];
    $product = is_array($payload['product'] ?? null) ? $payload['product'] : [];
    $features = is_array($payload['features'] ?? null) ? $payload['features'] : [];
    $sourcePhotos = is_array($payload['source_photo_context'] ?? null) ? $payload['source_photo_context'] : [];
    $storyboard = is_array($payload['storyboard'] ?? null) ? $payload['storyboard'] : [];

    $staticJson = supplier_products_db_video_cover_prompt_json([
        'category' => $category,
        'rules' => $rules,
    ]);
    $dynamicJson = supplier_products_db_video_cover_prompt_json([
        'product' => $product,
        'storyboard' => $storyboard,
        'features' => $features,
        'source_photo_context' => $sourcePhotos,
        'brand' => $payload['brand'] ?? [],
    ]);
    $staticPrefix = $prompt . "\n\nCATEGORY VIDEO STYLE JSON:\n" . $staticJson;
    return [
        'text' => $staticPrefix . "\n\nPRODUCT VIDEO COVER JSON:\n" . $dynamicJson,
        'format' => 'sora_video_cover_compact_storyboard_v3',
        'static_prefix_sha256' => hash('sha256', $staticPrefix),
        'payload_sha256' => hash('sha256', $dynamicJson),
    ];
}

function supplier_products_db_gpt_video_cover_prompt_public_meta(array $promptMeta): array
{
    $text = (string)($promptMeta['text'] ?? '');
    $chars = $text === '' ? 0 : mb_strlen($text, 'UTF-8');
    return [
        'format' => (string)($promptMeta['format'] ?? ''),
        'static_prefix_sha256' => (string)($promptMeta['static_prefix_sha256'] ?? ''),
        'payload_sha256' => (string)($promptMeta['payload_sha256'] ?? ''),
        'prompt_chars' => $chars,
        'estimated_prompt_tokens' => $chars > 0 ? (int)ceil($chars / 4) : 0,
    ];
}

function supplier_products_db_gpt_video_cover_sanitize_response(?array $raw): ?array
{
    if (!is_array($raw)) {
        return null;
    }
    $copy = $raw;
    if (isset($copy['error']) && is_array($copy['error'])) {
        $message = (string)($copy['error']['message'] ?? '');
        if ($message !== '') {
            $copy['error']['message'] = preg_replace('~sk-[A-Za-z0-9_\-*]{6,}~', 'sk-***', $message) ?? $message;
        }
    }
    return $copy;
}

function supplier_products_db_video_cover_ffmpeg_path(array $cfg, array $params = []): string
{
    $candidates = [
        trim((string)($params['ffmpeg_path'] ?? '')),
        trim((string)($cfg['paths']['ffmpeg'] ?? '')),
        '/usr/bin/ffmpeg',
        '/usr/local/bin/ffmpeg',
        '/opt/homebrew/bin/ffmpeg',
    ];
    foreach ($candidates as $candidate) {
        if ($candidate !== '' && is_file($candidate) && is_executable($candidate)) {
            return $candidate;
        }
    }
    $detected = trim((string)@shell_exec('command -v ffmpeg 2>/dev/null'));
    if ($detected !== '' && is_file($detected) && is_executable($detected)) {
        return $detected;
    }
    throw new RuntimeException('Для создания MP4 требуется ffmpeg. Установи ffmpeg на сервере или укажи paths.ffmpeg.');
}

function supplier_products_db_gpt_video_cover_final_size(string $size): string
{
    [$w, $h] = supplier_products_db_video_cover_parse_size($size);
    if ($w <= 0 || $h <= 0 || $h <= $w) {
        return '1080x1440';
    }
    $ratio = $w / max(1, $h);
    if (abs($ratio - 0.75) > 0.02) {
        return '1080x1440';
    }
    if ($w < 720 || $h < 960 || $w > 1920 || $h > 2560) {
        return '1080x1440';
    }
    return $w . 'x' . $h;
}

function supplier_products_db_gpt_video_cover_postprocess_video(string $sourcePath, array $cfg, array $params = []): array
{
    if (!is_file($sourcePath) || (int)@filesize($sourcePath) <= 0) {
        throw new RuntimeException('Не найден исходный MP4 Sora для финальной обработки.');
    }

    $ffmpeg = supplier_products_db_video_cover_ffmpeg_path($cfg, $params);
    $finalSize = supplier_products_db_gpt_video_cover_final_size((string)($params['final_video_size'] ?? '1080x1440'));
    [$targetW, $targetH] = supplier_products_db_video_cover_parse_size($finalSize);
    $fps = max(24, min(30, (int)($params['fps'] ?? ($params['final_video_fps'] ?? 25))));
    $crf = max(18, min(30, (int)($params['crf'] ?? ($params['final_video_crf'] ?? 23))));
    $maxrateKbps = max(1200, min(9000, (int)($params['maxrate_kbps'] ?? ($params['final_video_maxrate_kbps'] ?? 3200))));
    $bufsizeKbps = $maxrateKbps * 2;
    $slowdownFactor = (float)($params['slowdown_factor'] ?? 1.0);
    if ($slowdownFactor < 1.0 || $slowdownFactor > 4.0) {
        $slowdownFactor = 1.0;
    }
    $targetDurationSec = (float)($params['target_duration_sec'] ?? 0.0);
    if ($targetDurationSec < 0.1 || $targetDurationSec > 30.0) {
        $targetDurationSec = 0.0;
    }
    $padToTarget = !empty($params['pad_to_target_duration']);
    $motionStrength = (float)($params['postprocess_motion_strength'] ?? 0.35);
    if ($motionStrength < 0.0 || $motionStrength > 1.0) {
        $motionStrength = 0.0;
    }

    $tmpBase = tempnam(sys_get_temp_dir(), 'ft_sora_video_cover_final_');
    if ($tmpBase === false) {
        throw new RuntimeException('Не удалось создать временный файл финального MP4.');
    }
    $outPath = $tmpBase . '.mp4';
    @unlink($tmpBase);

    $filterParts = [
        "scale={$targetW}:{$targetH}:force_original_aspect_ratio=increase",
        "crop={$targetW}:{$targetH}",
        'setsar=1',
    ];
    if ($motionStrength > 0.001) {
        $overscale = 1.0 + (0.018 + 0.035 * $motionStrength);
        $motionW = (int)(ceil(($targetW * $overscale) / 2) * 2);
        $motionH = (int)(ceil(($targetH * $overscale) / 2) * 2);
        $xAmp = number_format(0.18 + 0.22 * $motionStrength, 4, '.', '');
        $yAmp = number_format(0.12 + 0.16 * $motionStrength, 4, '.', '');
        $filterParts[] = "scale={$motionW}:{$motionH}";
        $filterParts[] = "crop={$targetW}:{$targetH}:x='(in_w-out_w)/2+((in_w-out_w)/2)*{$xAmp}*sin(6.28318530718*t/7.3)':y='(in_h-out_h)/2+((in_h-out_h)/2)*{$yAmp}*cos(6.28318530718*t/6.1)'";
    }
    if (abs($slowdownFactor - 1.0) > 0.001) {
        $filterParts[] = 'setpts=' . number_format($slowdownFactor, 6, '.', '') . '*PTS';
    }
    if ($targetDurationSec > 0.0) {
        $durationText = rtrim(rtrim(number_format($targetDurationSec, 3, '.', ''), '0'), '.');
        if ($padToTarget) {
            $filterParts[] = 'tpad=stop_mode=clone:stop_duration=1';
        }
        $filterParts[] = 'trim=duration=' . $durationText;
        $filterParts[] = 'setpts=PTS-STARTPTS';
    }
    $filterParts[] = "fps={$fps}";
    $filterParts[] = 'format=yuv420p';
    $filter = implode(',', $filterParts);
    $cmd = escapeshellarg($ffmpeg)
        . ' -hide_banner -loglevel error -y'
        . ' -i ' . escapeshellarg($sourcePath)
        . ' -vf ' . escapeshellarg($filter)
        . ' -an -c:v libx264 -preset veryfast -crf ' . (int)$crf
        . ' -maxrate ' . (int)$maxrateKbps . 'k'
        . ' -bufsize ' . (int)$bufsizeKbps . 'k'
        . ' -pix_fmt yuv420p -movflags +faststart -r ' . (int)$fps . ' '
        . escapeshellarg($outPath)
        . ' 2>&1';

    $output = [];
    $code = 0;
    @exec($cmd, $output, $code);
    if ($code !== 0 || !is_file($outPath) || (int)@filesize($outPath) <= 0) {
        @unlink($outPath);
        $message = trim(implode("\n", array_slice($output, -8)));
        throw new RuntimeException('ffmpeg не смог подготовить финальный MP4 Sora' . ($message !== '' ? ': ' . $message : '.'));
    }
    @chmod($outPath, 0664);

    return [
        'path' => $outPath,
        'width' => $targetW,
        'height' => $targetH,
        'size' => $finalSize,
        'fps' => $fps,
        'crf' => $crf,
        'maxrate_kbps' => $maxrateKbps,
        'bufsize_kbps' => $bufsizeKbps,
        'slowdown_factor' => $slowdownFactor,
        'target_duration_sec' => $targetDurationSec,
        'pad_to_target_duration' => $padToTarget,
        'postprocess_motion_strength' => $motionStrength,
        'strip_audio' => true,
        'codec' => 'h264',
        'pixel_format' => 'yuv420p',
        'container' => 'mp4',
        'file_size_bytes' => (int)@filesize($outPath),
        'mode' => 'sora_9x16_to_marketplace_3x4_center_crop',
        'filter' => $filter,
        'ffmpeg' => $ffmpeg,
    ];
}

function supplier_products_db_video_cover_delete_dir(string $dir): void
{
    if ($dir === '' || !is_dir($dir)) {
        return;
    }
    $items = scandir($dir);
    if (!is_array($items)) {
        return;
    }
    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }
        $path = $dir . '/' . $item;
        if (is_dir($path)) {
            supplier_products_db_video_cover_delete_dir($path);
        } else {
            @unlink($path);
        }
    }
    @rmdir($dir);
}

function supplier_products_db_video_cover_smooth(float $value): float
{
    $value = max(0.0, min(1.0, $value));
    return $value * $value * (3.0 - 2.0 * $value);
}

function supplier_products_db_video_cover_prepare_slides(array $loaded, int $targetW, int $targetH): array
{
    $prepared = [];
    $targetW = max(2, $targetW);
    $targetH = max(2, $targetH);
    $smallW = max(160, min(420, (int)round($targetW / 3)));
    $smallH = max(220, min(560, (int)round($targetH / 3)));

    foreach ($loaded as $idx => $item) {
        $source = $item['image'] ?? null;
        if (!$source instanceof GdImage) {
            continue;
        }
        $srcW = max(1, imagesx($source));
        $srcH = max(1, imagesy($source));

        $small = imagecreatetruecolor($smallW, $smallH);
        if (!$small instanceof GdImage) {
            throw new RuntimeException('Не удалось подготовить фон видео-обложки.');
        }
        imagealphablending($small, true);
        imagesavealpha($small, false);
        $smallBg = imagecolorallocate($small, 244, 246, 249);
        imagefilledrectangle($small, 0, 0, $smallW, $smallH, $smallBg);

        $bgScale = max($smallW / $srcW, $smallH / $srcH) * 1.04;
        $bgW = max(1, (int)round($srcW * $bgScale));
        $bgH = max(1, (int)round($srcH * $bgScale));
        $bgX = (int)floor(($smallW - $bgW) / 2);
        $bgY = (int)floor(($smallH - $bgH) / 2);
        if (function_exists('imagesetinterpolation')) {
            @imagesetinterpolation($source, IMG_BICUBIC_FIXED);
        }
        imagecopyresampled($small, $source, $bgX, $bgY, 0, 0, $bgW, $bgH, $srcW, $srcH);
        for ($i = 0; $i < 4; $i++) {
            imagefilter($small, IMG_FILTER_GAUSSIAN_BLUR);
        }
        imagefilter($small, IMG_FILTER_BRIGHTNESS, 8);
        imagefilter($small, IMG_FILTER_CONTRAST, -10);

        $background = imagecreatetruecolor($targetW, $targetH);
        if (!$background instanceof GdImage) {
            imagedestroy($small);
            throw new RuntimeException('Не удалось подготовить холст видео-обложки.');
        }
        imagealphablending($background, true);
        imagesavealpha($background, false);
        imagecopyresampled($background, $small, 0, 0, 0, 0, $targetW, $targetH, $smallW, $smallH);
        imagedestroy($small);
        $veil = imagecolorallocatealpha($background, 255, 255, 255, 66);
        imagefilledrectangle($background, 0, 0, $targetW, $targetH, $veil);

        $prepared[] = [
            'image' => $source,
            'background' => $background,
            'url' => (string)($item['url'] ?? ''),
            'width' => $srcW,
            'height' => $srcH,
            'index' => $idx,
        ];
    }

    if (!$prepared) {
        throw new RuntimeException('Не удалось подготовить фото для видео-обложки.');
    }

    return $prepared;
}

function supplier_products_db_video_cover_destroy_prepared_slides(array $prepared): void
{
    foreach ($prepared as $item) {
        if (($item['background'] ?? null) instanceof GdImage) {
            imagedestroy($item['background']);
        }
    }
}

function supplier_products_db_video_cover_render_slide(array $prepared, int $index, float $progress, int $targetW, int $targetH): GdImage
{
    $item = (array)($prepared[$index] ?? $prepared[0] ?? []);
    $source = $item['image'] ?? null;
    if (!$source instanceof GdImage) {
        throw new RuntimeException('Не удалось открыть кадр для видео-обложки.');
    }

    $targetW = max(2, $targetW);
    $targetH = max(2, $targetH);
    $canvas = imagecreatetruecolor($targetW, $targetH);
    if (!$canvas instanceof GdImage) {
        throw new RuntimeException('Не удалось создать кадр видео-обложки.');
    }
    imagealphablending($canvas, true);
    imagesavealpha($canvas, false);
    $background = $item['background'] ?? null;
    if ($background instanceof GdImage) {
        imagecopy($canvas, $background, 0, 0, 0, 0, $targetW, $targetH);
    } else {
        $bg = imagecolorallocate($canvas, 255, 255, 255);
        imagefilledrectangle($canvas, 0, 0, $targetW, $targetH, $bg);
    }

    $srcW = max(1, (int)($item['width'] ?? imagesx($source)));
    $srcH = max(1, (int)($item['height'] ?? imagesy($source)));
    $progress = supplier_products_db_video_cover_smooth($progress);
    $zoom = 1.0;
    $scale = min($targetW / $srcW, $targetH / $srcH) * $zoom;
    $dstW = max(1, (int)round($srcW * $scale));
    $dstH = max(1, (int)round($srcH * $scale));
    $dstX = (int)floor(($targetW - $dstW) / 2);
    $dstY = (int)floor(($targetH - $dstH) / 2);

    if (function_exists('imagesetinterpolation')) {
        @imagesetinterpolation($source, IMG_BICUBIC_FIXED);
    }
    imagecopyresampled($canvas, $source, $dstX, $dstY, 0, 0, $dstW, $dstH, $srcW, $srcH);
    return $canvas;
}

function supplier_products_db_video_cover_jpeg_bytes(GdImage $frame, int $quality): string
{
    imageinterlace($frame, true);
    ob_start();
    $ok = imagejpeg($frame, null, $quality);
    $bytes = ob_get_clean();
    if (!$ok || !is_string($bytes) || $bytes === '') {
        throw new RuntimeException('Не удалось закодировать кадр видео-обложки.');
    }
    return $bytes;
}

function supplier_products_db_video_cover_write_all($stream, string $bytes): void
{
    $len = strlen($bytes);
    $offset = 0;
    while ($offset < $len) {
        $written = @fwrite($stream, substr($bytes, $offset));
        if ($written === false || $written <= 0) {
            throw new RuntimeException('ffmpeg перестал принимать кадры видео-обложки.');
        }
        $offset += $written;
    }
}

function supplier_products_db_video_cover_encode_pipe(
    string $ffmpeg,
    string $outputPath,
    int $fps,
    int $crf,
    callable $frameProducer
): array {
    if (!function_exists('proc_open')) {
        throw new RuntimeException('Для быстрой сборки видео-обложки требуется proc_open.');
    }
    $cmd = escapeshellarg($ffmpeg)
        . ' -hide_banner -loglevel error -y'
        . ' -f image2pipe -vcodec mjpeg -framerate ' . (int)$fps . ' -i pipe:0'
        . ' -c:v libx264 -preset veryfast -crf ' . (int)$crf
        . ' -pix_fmt yuv420p -movflags +faststart -r ' . (int)$fps . ' '
        . escapeshellarg($outputPath);

    $pipes = [];
    $process = proc_open($cmd, [
        0 => ['pipe', 'r'],
        1 => ['pipe', 'w'],
        2 => ['pipe', 'w'],
    ], $pipes);
    if (!is_resource($process)) {
        throw new RuntimeException('Не удалось запустить ffmpeg для видео-обложки.');
    }

    try {
        $writeFrame = static function (string $bytes) use (&$pipes): void {
            supplier_products_db_video_cover_write_all($pipes[0], $bytes);
        };
        $producerMeta = $frameProducer($writeFrame);
        if (is_resource($pipes[0])) {
            fclose($pipes[0]);
        }
        $stdout = is_resource($pipes[1]) ? (string)stream_get_contents($pipes[1]) : '';
        if (is_resource($pipes[1])) {
            fclose($pipes[1]);
        }
        $stderr = is_resource($pipes[2]) ? (string)stream_get_contents($pipes[2]) : '';
        if (is_resource($pipes[2])) {
            fclose($pipes[2]);
        }
        $code = proc_close($process);
    } catch (Throwable $e) {
        foreach ($pipes as $pipe) {
            if (is_resource($pipe)) {
                @fclose($pipe);
            }
        }
        @proc_terminate($process);
        @proc_close($process);
        throw $e;
    }

    if ($code !== 0 || !is_file($outputPath) || (int)filesize($outputPath) <= 0) {
        $message = trim(implode("\n", array_filter([trim($stderr), trim($stdout)])));
        if ($message !== '') {
            $messageLen = mb_strlen($message, 'UTF-8');
            $message = mb_substr($message, max(0, $messageLen - 1200), 1200, 'UTF-8');
        }
        throw new RuntimeException('ffmpeg не смог собрать MP4 видео-обложку' . ($message !== '' ? ': ' . $message : '.'));
    }

    return is_array($producerMeta) ? $producerMeta : [];
}

function supplier_products_db_video_cover_ffmpeg_number(float $value): string
{
    $out = rtrim(rtrim(sprintf('%.6F', $value), '0'), '.');
    return $out === '' || $out === '-0' ? '0' : $out;
}

function supplier_products_db_video_cover_source_files(array $sourceUrls, array $cfg): array
{
    $files = [];
    try {
        foreach ($sourceUrls as $url) {
            $source = supplier_products_bundle_photo_source_path((string)$url, $cfg);
            $path = (string)($source['path'] ?? '');
            if ($path === '' || !is_file($path) || (int)@filesize($path) <= 0) {
                throw new RuntimeException('Не удалось подготовить исходное фото для видео-обложки.');
            }
            $files[] = [
                'path' => $path,
                'temporary' => !empty($source['temporary']),
                'url' => (string)$url,
            ];
        }
    } catch (Throwable $e) {
        supplier_products_db_video_cover_cleanup_source_files($files);
        throw $e;
    }
    if (!$files) {
        throw new RuntimeException('Не удалось подготовить исходные фото для видео-обложки.');
    }
    return $files;
}

function supplier_products_db_video_cover_cleanup_source_files(array $files): void
{
    foreach ($files as $file) {
        if (!empty($file['temporary'])) {
            $path = (string)($file['path'] ?? '');
            if ($path !== '') {
                @unlink($path);
            }
        }
    }
}

function supplier_products_db_video_cover_filter_script(
    int $slides,
    int $targetW,
    int $targetH,
    int $fps,
    float $targetDuration,
    float $secondsPerPhoto,
    float $transitionSec
): array {
    $slides = max(1, $slides);
    $transitionSec = $slides > 1 ? max(0.05, min(1.2, $transitionSec)) : 0.0;
    $slideDuration = $slides > 1
        ? max(0.9, ($targetDuration + (($slides - 1) * $transitionSec)) / $slides)
        : max(2.5, $targetDuration);
    $slideFrames = max(1, (int)ceil($slideDuration * $fps));
    $actualSlideDuration = $slideFrames / max(1, $fps);
    $exprFrames = max(1, $slideFrames - 1);
    $motionZoom = 0.022;
    $motionZoomText = supplier_products_db_video_cover_ffmpeg_number($motionZoom);
    $progressExpr = "(on/{$exprFrames})";
    $easeExpr = "({$progressExpr})*({$progressExpr})*(3-2*({$progressExpr}))";

    $lines = [];
    for ($i = 0; $i < $slides; $i++) {
        $zoomExpr = "1+{$motionZoomText}*{$easeExpr}";
        $xExpr = "trunc(((iw-iw/zoom)/2)/2)*2";
        $yExpr = "trunc(((ih-ih/zoom)/2)/2)*2";
        $durationText = supplier_products_db_video_cover_ffmpeg_number($actualSlideDuration);
        $lines[] = "[{$i}:v]format=rgba,split=2[bg{$i}src][fg{$i}src]";
        $lines[] = "[bg{$i}src]scale={$targetW}:{$targetH}:force_original_aspect_ratio=increase,crop={$targetW}:{$targetH},gblur=sigma=24,eq=brightness=0.05:contrast=0.9,drawbox=x=0:y=0:w=iw:h=ih:color=white@0.52:t=fill,zoompan=z='{$zoomExpr}':x='{$xExpr}':y='{$yExpr}':d={$slideFrames}:s={$targetW}x{$targetH}:fps={$fps},trim=duration={$durationText},setpts=PTS-STARTPTS,setsar=1[bg{$i}]";
        $lines[] = "[fg{$i}src]scale={$targetW}:{$targetH}:force_original_aspect_ratio=decrease,setsar=1[fg{$i}]";
        $lines[] = "[bg{$i}][fg{$i}]overlay=x=(W-w)/2:y=(H-h)/2:format=auto:repeatlast=1,format=yuv420p,setsar=1[v{$i}]";
    }

    if ($slides === 1) {
        $durationText = supplier_products_db_video_cover_ffmpeg_number($targetDuration);
        $lines[] = "[v0]trim=duration={$durationText},setpts=PTS-STARTPTS,format=yuv420p[vout]";
    } else {
        $prev = 'v0';
        $transitionText = supplier_products_db_video_cover_ffmpeg_number($transitionSec);
        for ($i = 1; $i < $slides; $i++) {
            $offset = max(0.05, ($actualSlideDuration * $i) - ($transitionSec * $i));
            $offsetText = supplier_products_db_video_cover_ffmpeg_number($offset);
            $out = $i === ($slides - 1) ? 'vxfinal' : 'vx' . $i;
            $lines[] = "[{$prev}][v{$i}]xfade=transition=fade:duration={$transitionText}:offset={$offsetText},format=yuv420p[{$out}]";
            $prev = $out;
        }
        $targetDurationText = supplier_products_db_video_cover_ffmpeg_number($targetDuration);
        $lines[] = "[{$prev}]trim=duration={$targetDurationText},setpts=PTS-STARTPTS,format=yuv420p[vout]";
    }

    return [
        'script' => implode(";\n", $lines) . ";\n",
        'slide_duration_sec' => $actualSlideDuration,
        'slide_frames' => $slideFrames,
        'target_duration_sec' => $targetDuration,
        'transition_sec' => $transitionSec,
        'motion_mode' => 'stable_product_soft_background_zoom',
        'motion_zoom' => $motionZoom,
    ];
}

function supplier_products_db_video_cover_encode_native(
    string $ffmpeg,
    array $sourceFiles,
    string $outputPath,
    int $targetW,
    int $targetH,
    int $fps,
    float $secondsPerPhoto,
    float $transitionSec,
    int $crf
): array {
    if (!function_exists('proc_open')) {
        throw new RuntimeException('Для быстрой сборки видео-обложки требуется proc_open.');
    }
    $slides = count($sourceFiles);
    if ($slides <= 0) {
        throw new RuntimeException('Для видео-обложки нужно хотя бы одно фото товара.');
    }
    $targetDuration = max(2.5, $slides * $secondsPerPhoto);
    $targetDuration = max(8.0, $targetDuration);
    if ($slides === 1) {
        $targetDuration = max($targetDuration, 8.0);
    }
    $filter = supplier_products_db_video_cover_filter_script($slides, $targetW, $targetH, $fps, $targetDuration, $secondsPerPhoto, $transitionSec);
    $scriptPath = tempnam(sys_get_temp_dir(), 'ft_video_cover_filter_');
    if ($scriptPath === false) {
        throw new RuntimeException('Не удалось создать временный filter-script для ffmpeg.');
    }
    file_put_contents($scriptPath, (string)$filter['script']);

    $cmd = escapeshellarg($ffmpeg) . ' -hide_banner -loglevel error -y';
    foreach ($sourceFiles as $file) {
        $path = (string)($file['path'] ?? '');
        if ($path === '' || !is_file($path)) {
            @unlink($scriptPath);
            throw new RuntimeException('Исходное фото для видео-обложки не найдено.');
        }
        $cmd .= ' -i ' . escapeshellarg($path);
    }
    $cmd .= ' -filter_complex_script ' . escapeshellarg($scriptPath)
        . ' -map ' . escapeshellarg('[vout]')
        . ' -an -c:v libx264 -preset veryfast -crf ' . (int)$crf
        . ' -pix_fmt yuv420p -movflags +faststart -r ' . (int)$fps . ' '
        . escapeshellarg($outputPath);

    $pipes = [];
    $process = proc_open($cmd, [
        0 => ['pipe', 'r'],
        1 => ['pipe', 'w'],
        2 => ['pipe', 'w'],
    ], $pipes);
    if (!is_resource($process)) {
        @unlink($scriptPath);
        throw new RuntimeException('Не удалось запустить ffmpeg для видео-обложки.');
    }
    if (is_resource($pipes[0])) {
        fclose($pipes[0]);
    }
    $stdout = is_resource($pipes[1]) ? (string)stream_get_contents($pipes[1]) : '';
    if (is_resource($pipes[1])) {
        fclose($pipes[1]);
    }
    $stderr = is_resource($pipes[2]) ? (string)stream_get_contents($pipes[2]) : '';
    if (is_resource($pipes[2])) {
        fclose($pipes[2]);
    }
    $code = proc_close($process);
    @unlink($scriptPath);

    if ($code !== 0 || !is_file($outputPath) || (int)filesize($outputPath) <= 0) {
        $message = trim(implode("\n", array_filter([trim($stderr), trim($stdout)])));
        if ($message !== '') {
            $messageLen = mb_strlen($message, 'UTF-8');
            $message = mb_substr($message, max(0, $messageLen - 1200), 1200, 'UTF-8');
        }
        throw new RuntimeException('ffmpeg не смог собрать MP4 видео-обложку через native renderer' . ($message !== '' ? ': ' . $message : '.'));
    }

    return [
        'rendering_mode' => 'ffmpeg_filter_complex',
        'background_mode' => 'ffmpeg_blurred_source',
        'slide_duration_sec' => (float)($filter['slide_duration_sec'] ?? 0.0),
        'slide_frames' => (int)($filter['slide_frames'] ?? 0),
        'target_duration_sec' => (float)($filter['target_duration_sec'] ?? $targetDuration),
        'transition_sec' => (float)($filter['transition_sec'] ?? $transitionSec),
        'motion_mode' => (string)($filter['motion_mode'] ?? 'stable_product_soft_background_zoom'),
        'motion_zoom' => (float)($filter['motion_zoom'] ?? 0.0),
    ];
}

function supplier_products_db_video_cover_load_sources(array $sourceUrls, array $cfg): array
{
    $loaded = [];
    foreach ($sourceUrls as $url) {
        $source = supplier_products_bundle_photo_source_path((string)$url, $cfg);
        try {
            $image = supplier_products_bundle_photo_load((string)$source['path']);
            $loaded[] = [
                'image' => $image,
                'url' => (string)$url,
                'width' => imagesx($image),
                'height' => imagesy($image),
            ];
        } finally {
            if (!empty($source['temporary'])) {
                @unlink((string)$source['path']);
            }
        }
    }
    return $loaded;
}

function supplier_products_db_video_cover_create(array $sourceUrls, array $cfg, array $params = []): array
{
    if (!extension_loaded('gd')) {
        throw new RuntimeException('Для сборки кадров видео-обложки требуется PHP GD.');
    }
    $sourceUrls = array_values(array_filter(array_map('trim', array_map('strval', $sourceUrls))));
    if (!$sourceUrls) {
        throw new RuntimeException('Для видео-обложки нужно хотя бы одно фото товара.');
    }

    $ffmpeg = supplier_products_db_video_cover_ffmpeg_path($cfg, $params);
    $targetW = max(320, min(1600, (int)($params['width'] ?? 1200)));
    $targetH = max(320, min(2000, (int)($params['height'] ?? 1600)));
    if ($targetW % 2 !== 0) $targetW++;
    if ($targetH % 2 !== 0) $targetH++;
    $fps = max(12, min(30, (int)($params['fps'] ?? 24)));
    $secondsPerPhoto = (float)str_replace(',', '.', (string)($params['seconds_per_photo'] ?? '2.0'));
    $secondsPerPhoto = max(0.8, min(3.0, $secondsPerPhoto));
    $transitionSec = max(0.15, min(1.2, (float)str_replace(',', '.', (string)($params['transition_sec'] ?? '1.0'))));
    $jpegQuality = max(70, min(95, (int)($params['jpeg_quality'] ?? 88)));
    $crf = max(18, min(32, (int)($params['crf'] ?? 22)));

    $outputBase = tempnam(sys_get_temp_dir(), 'ft_video_cover_ready_');
    if ($outputBase === false) {
        throw new RuntimeException('Не удалось создать временный файл готовой видео-обложки.');
    }
    $outputPath = $outputBase . '.mp4';
    @unlink($outputBase);

    $loaded = [];
    $prepared = [];
    $success = false;
    try {
        $nativeError = '';
        if ((string)($params['renderer'] ?? 'native') !== 'php_pipe') {
            $sourceFiles = [];
            try {
                $sourceFiles = supplier_products_db_video_cover_source_files($sourceUrls, $cfg);
                $slides = count($sourceFiles);
                $renderStarted = microtime(true);
                $encoded = supplier_products_db_video_cover_encode_native(
                    $ffmpeg,
                    $sourceFiles,
                    $outputPath,
                    $targetW,
                    $targetH,
                    $fps,
                    $secondsPerPhoto,
                    $transitionSec,
                    $crf
                );
                $renderElapsedMs = (int)round((microtime(true) - $renderStarted) * 1000);
                @chmod($outputPath, 0664);
                $success = true;

                return [
                    'path' => $outputPath,
                    'meta' => [
                        'format' => 'mp4',
                        'codec' => 'h264',
                        'width' => $targetW,
                        'height' => $targetH,
                        'fps' => $fps,
                        'slides' => $slides,
                        'frames' => max(1, (int)ceil(((float)($encoded['target_duration_sec'] ?? ($slides * $secondsPerPhoto))) * $fps)),
                        'duration_sec' => round((float)($encoded['target_duration_sec'] ?? ($slides * $secondsPerPhoto)), 3),
                        'seconds_per_photo' => $secondsPerPhoto,
                        'transition_sec' => (float)($encoded['transition_sec'] ?? $transitionSec),
                        'slide_duration_sec' => (float)($encoded['slide_duration_sec'] ?? 0.0),
                        'slide_frames' => (int)($encoded['slide_frames'] ?? 0),
                        'crf' => $crf,
                        'rendering_mode' => (string)($encoded['rendering_mode'] ?? 'ffmpeg_filter_complex'),
                        'background_mode' => (string)($encoded['background_mode'] ?? 'ffmpeg_blurred_source'),
                        'motion_mode' => (string)($encoded['motion_mode'] ?? 'stable_product_soft_background_zoom'),
                        'motion_zoom' => (float)($encoded['motion_zoom'] ?? 0.0),
                        'render_elapsed_ms' => $renderElapsedMs,
                        'source_urls' => array_values($sourceUrls),
                        'size_bytes' => (int)filesize($outputPath),
                    ],
                ];
            } catch (Throwable $e) {
                $nativeError = $e->getMessage();
                if (is_file($outputPath)) {
                    @unlink($outputPath);
                }
            } finally {
                supplier_products_db_video_cover_cleanup_source_files($sourceFiles);
            }
        }

        $loaded = supplier_products_db_video_cover_load_sources($sourceUrls, $cfg);
        if (!$loaded) {
            throw new RuntimeException('Не удалось загрузить исходные фото для видео-обложки.');
        }
        $prepared = supplier_products_db_video_cover_prepare_slides($loaded, $targetW, $targetH);

        $slides = count($prepared);
        $totalDuration = max(2.5, $slides * $secondsPerPhoto);
        $totalDuration = max(8.0, $totalDuration);
        if ($slides === 1) {
            $totalDuration = max($totalDuration, 8.0);
        }
        $totalFrames = max(1, (int)ceil($totalDuration * $fps));
        $slideSeconds = max(0.001, $totalDuration / max(1, $slides));
        $transitionPart = min(0.65, $transitionSec / $slideSeconds);
        $renderStarted = microtime(true);
        $encoded = supplier_products_db_video_cover_encode_pipe(
            $ffmpeg,
            $outputPath,
            $fps,
            $crf,
            static function (callable $writeFrame) use ($prepared, $slides, $totalFrames, $fps, $slideSeconds, $transitionPart, $targetW, $targetH, $jpegQuality): array {
                $jpegBytesTotal = 0;
                for ($frameNo = 0; $frameNo < $totalFrames; $frameNo++) {
                    $time = $frameNo / $fps;
                    $slideIndex = min($slides - 1, (int)floor($time / $slideSeconds));
                    $local = ($time - ($slideIndex * $slideSeconds)) / $slideSeconds;
                    $local = max(0.0, min(1.0, $local));
                    $frame = supplier_products_db_video_cover_render_slide($prepared, $slideIndex, $local, $targetW, $targetH);

                    if ($slides > 1 && $slideIndex < $slides - 1 && $local >= (1.0 - $transitionPart)) {
                        $rawAlpha = ($local - (1.0 - $transitionPart)) / max(0.001, $transitionPart);
                        $smoothAlpha = supplier_products_db_video_cover_smooth($rawAlpha);
                        $alpha = (int)round($smoothAlpha * 100);
                        if ($alpha > 0) {
                            $next = supplier_products_db_video_cover_render_slide($prepared, $slideIndex + 1, min(0.18, $smoothAlpha * 0.18), $targetW, $targetH);
                            imagecopymerge($frame, $next, 0, 0, 0, 0, $targetW, $targetH, $alpha);
                            imagedestroy($next);
                        }
                    }

                    $jpeg = supplier_products_db_video_cover_jpeg_bytes($frame, $jpegQuality);
                    imagedestroy($frame);
                    $jpegBytesTotal += strlen($jpeg);
                    $writeFrame($jpeg);
                }
                return [
                    'jpeg_frame_bytes_total' => $jpegBytesTotal,
                    'rendering_mode' => 'prepared_background_image2pipe',
                ];
            }
        );
        $renderElapsedMs = (int)round((microtime(true) - $renderStarted) * 1000);
        @chmod($outputPath, 0664);
        $success = true;

        return [
            'path' => $outputPath,
            'meta' => [
                'format' => 'mp4',
                'codec' => 'h264',
                'width' => $targetW,
                'height' => $targetH,
                'fps' => $fps,
                'slides' => $slides,
                'frames' => $totalFrames,
                'duration_sec' => round($totalFrames / $fps, 3),
                'seconds_per_photo' => $secondsPerPhoto,
                'transition_sec' => $transitionSec,
                'crf' => $crf,
                'rendering_mode' => (string)($encoded['rendering_mode'] ?? 'prepared_background_image2pipe'),
                'background_mode' => 'prepared_blurred_source',
                'motion_mode' => 'stable_product_static_fallback',
                'motion_zoom' => 0.0,
                'render_elapsed_ms' => $renderElapsedMs,
                'jpeg_frame_bytes_total' => (int)($encoded['jpeg_frame_bytes_total'] ?? 0),
                'native_fallback_error' => $nativeError,
                'source_urls' => array_values($sourceUrls),
                'size_bytes' => (int)filesize($outputPath),
            ],
        ];
    } finally {
        supplier_products_db_video_cover_destroy_prepared_slides($prepared);
        foreach ($loaded as $item) {
            if (($item['image'] ?? null) instanceof GdImage) {
                imagedestroy($item['image']);
            }
        }
        if (!$success && is_file($outputPath)) {
            @unlink($outputPath);
        }
    }
}

function supplier_products_db_specs_photo_picture_is_generated(string $url): bool
{
    $relative = supplier_products_local_image_relative_from_url($url);
    return $relative !== '' && str_contains(str_replace('\\', '/', $relative), '/product_specs_photo/');
}

function supplier_products_db_specs_photo_has_generated(array $pictures): bool
{
    foreach (supplier_products_normalize_picture_urls($pictures) as $picture) {
        if (supplier_products_db_specs_photo_picture_is_generated($picture)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_specs_photo_without_existing(array $pictures): array
{
    $out = [];
    foreach (supplier_products_normalize_picture_urls($pictures) as $picture) {
        if (supplier_products_db_specs_photo_picture_is_generated($picture)) {
            continue;
        }
        $out[] = $picture;
    }
    return $out;
}

function supplier_products_db_specs_photo_pictures_with_new_image(array $pictures, string $newUrl): array
{
    $out = supplier_products_normalize_picture_urls($pictures);
    $newUrl = trim($newUrl);
    if ($newUrl === '') {
        return $out;
    }
    $seen = array_fill_keys($out, true);
    if (!isset($seen[$newUrl])) {
        $out[] = $newUrl;
    }
    return array_values($out);
}

function supplier_products_db_specs_photo_save_image(int $supplierId, int $productId, string $bytes, array $cfg): string
{
    $info = @getimagesizefromstring($bytes);
    if (!is_array($info)) {
        throw new RuntimeException('Не удалось распознать готовое фото-характеристики.');
    }

    $baseDir = supplier_products_image_storage_dir($cfg);
    $relativeDir = 'supplier_' . $supplierId . '/' . date('Ym') . '/product_specs_photo';
    $dir = supplier_products_ensure_writable_dir($baseDir . '/' . $relativeDir, 'Не удалось создать папку для фото-характеристик.');
    $fileName = 'product_' . $productId . '_specs_' . date('Ymd_His') . '_' . bin2hex(random_bytes(5)) . '.jpg';
    $path = $dir . '/' . $fileName;
    if (file_put_contents($path, $bytes) === false) {
        throw new RuntimeException('Не удалось сохранить фото-характеристики.');
    }
    @chmod($path, 0664);

    return supplier_products_publish_stored_image($path, $relativeDir . '/' . $fileName, $cfg, true);
}

function supplier_products_db_specs_photo_template_for_product(array $product, array $fields, array $cfg): array
{
    foreach (['ozon', 'wildberries'] as $source) {
        $categoryValue = supplier_products_db_product_category_value($product, $fields, $source);
        if ($categoryValue === '') {
            continue;
        }
        $meta = supplier_products_taxonomy_meta_for_category_value($source, $categoryValue);
        $template = is_array($meta['additional_photo_background_template'] ?? null)
            ? $meta['additional_photo_background_template']
            : [];
        $relative = trim((string)($template['relative_path'] ?? ''));
        $url = trim((string)($template['url'] ?? ''));
        if ($url === '' && $relative !== '') {
            $url = supplier_products_image_url($relative, $cfg);
        }
        if ($url === '' && $relative === '') {
            continue;
        }
        return [
            'source' => $source,
            'category_value' => $categoryValue,
            'template' => $template + [
                'url' => $url,
                'relative_path' => $relative,
            ],
        ];
    }
    return [];
}

function supplier_products_db_specs_photo_regular_font_path(array $cfg = []): string
{
    $custom = trim((string)($cfg['paths']['regular_font'] ?? ''));
    $candidates = array_filter([
        $custom,
        '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
        '/usr/share/fonts/dejavu/DejaVuSans.ttf',
        '/System/Library/Fonts/Supplemental/Arial.ttf',
        '/Library/Fonts/Arial.ttf',
        supplier_products_bundle_photo_font_path($cfg),
    ]);
    foreach ($candidates as $path) {
        if (is_file($path) && is_readable($path)) {
            return $path;
        }
    }
    return supplier_products_bundle_photo_font_path($cfg);
}

function supplier_products_db_specs_photo_text_box(string $font, int $fontSize, string $text): array
{
    $box = imagettfbbox($fontSize, 0, $font, $text);
    if (!is_array($box)) {
        return ['width' => 0, 'height' => $fontSize, 'min_x' => 0, 'min_y' => -$fontSize];
    }
    $xs = [$box[0], $box[2], $box[4], $box[6]];
    $ys = [$box[1], $box[3], $box[5], $box[7]];
    return [
        'width' => max($xs) - min($xs),
        'height' => max($ys) - min($ys),
        'min_x' => min($xs),
        'min_y' => min($ys),
    ];
}

function supplier_products_db_specs_photo_text_width(string $font, int $fontSize, string $text): int
{
    return (int)supplier_products_db_specs_photo_text_box($font, $fontSize, $text)['width'];
}

function supplier_products_db_specs_photo_ellipsis(string $font, int $fontSize, string $text, int $maxWidth): string
{
    $text = trim($text);
    if ($text === '' || supplier_products_db_specs_photo_text_width($font, $fontSize, $text) <= $maxWidth) {
        return $text;
    }
    $ellipsis = '...';
    $len = mb_strlen($text, 'UTF-8');
    while ($len > 0) {
        $candidate = rtrim(mb_substr($text, 0, $len, 'UTF-8'), " \t\n\r\0\x0B.,;:-") . $ellipsis;
        if (supplier_products_db_specs_photo_text_width($font, $fontSize, $candidate) <= $maxWidth) {
            return $candidate;
        }
        $len--;
    }
    return $ellipsis;
}

function supplier_products_db_specs_photo_wrap_text(string $font, int $fontSize, string $text, int $maxWidth, int $maxLines = 2): array
{
    $text = trim(preg_replace('~\s+~u', ' ', $text) ?: $text);
    if ($text === '') {
        return [];
    }
    $words = preg_split('~\s+~u', $text) ?: [];
    $lines = [];
    $line = '';
    $truncated = false;
    foreach ($words as $idx => $word) {
        $word = trim((string)$word);
        if ($word === '') {
            continue;
        }
        $candidate = $line === '' ? $word : ($line . ' ' . $word);
        if (supplier_products_db_specs_photo_text_width($font, $fontSize, $candidate) <= $maxWidth) {
            $line = $candidate;
            continue;
        }
        if ($line !== '') {
            $lines[] = $line;
            $line = $word;
        } else {
            $lines[] = supplier_products_db_specs_photo_ellipsis($font, $fontSize, $word, $maxWidth);
            $line = '';
        }
        if (count($lines) >= $maxLines) {
            $truncated = $idx < count($words) - 1 || $line !== '';
            break;
        }
    }
    if ($line !== '' && count($lines) < $maxLines) {
        $lines[] = $line;
    }
    if (count($lines) > $maxLines) {
        $lines = array_slice($lines, 0, $maxLines);
    }
    if ($lines) {
        $last = count($lines) - 1;
        if (count($lines) >= $maxLines && supplier_products_db_specs_photo_text_width($font, $fontSize, $lines[$last]) > $maxWidth) {
            $lines[$last] = supplier_products_db_specs_photo_ellipsis($font, $fontSize, $lines[$last], $maxWidth);
        } elseif ($truncated) {
            $lines[$last] = supplier_products_db_specs_photo_ellipsis($font, $fontSize, $lines[$last], $maxWidth);
        }
    }
    return array_values(array_filter($lines, static fn(string $line): bool => trim($line) !== ''));
}

function supplier_products_db_specs_photo_draw_text_top(GdImage $canvas, string $font, int $fontSize, int $x, int $topY, int $color, string $text): int
{
    $box = supplier_products_db_specs_photo_text_box($font, $fontSize, $text);
    $baseline = $topY - (int)$box['min_y'];
    imagettftext($canvas, $fontSize, 0, $x, $baseline, $color, $font, $text);
    return $topY + (int)$box['height'];
}

function supplier_products_db_specs_photo_draw_text_top_shadow(
    GdImage $canvas,
    string $font,
    int $fontSize,
    int $x,
    int $topY,
    int $color,
    string $text,
    ?int $shadowColor = null
): int {
    $box = supplier_products_db_specs_photo_text_box($font, $fontSize, $text);
    $baseline = $topY - (int)$box['min_y'];
    if ($shadowColor !== null) {
        foreach ([[-2, 0], [2, 0], [0, -2], [0, 2], [-1, -1], [1, 1]] as $offset) {
            imagettftext($canvas, $fontSize, 0, $x + $offset[0], $baseline + $offset[1], $shadowColor, $font, $text);
        }
    }
    imagettftext($canvas, $fontSize, 0, $x, $baseline, $color, $font, $text);
    return $topY + (int)$box['height'];
}

function supplier_products_db_specs_photo_clean_value(string $value): string
{
    $value = html_entity_decode($value, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $value = strip_tags($value);
    $value = str_replace(["\xC2\xA0", "\xE2\x80\x8B"], ' ', $value);
    $value = preg_replace('~\s*;\s*~u', ', ', (string)$value);
    $value = preg_replace('~(?<=\d|[%/])(?=(?:Бренд|Состав|Состав материала|Материал|Назначение|Плотность|Метод окрашивания|Тип простыни|Цвет|Размерность комплекта|Размер простыни|Размер наволоч(?:ки|ек)|Размер пододеяльника)\b)~iu', ' ', (string)$value);
    $value = preg_replace('~\s+~u', ' ', (string)$value);
    $value = trim((string)$value, " \t\n\r\0\x0B,;|");
    if (mb_strlen($value, 'UTF-8') > 130) {
        $value = rtrim(mb_substr($value, 0, 127, 'UTF-8'), " \t\n\r\0\x0B.,;:-") . '...';
    }
    return $value;
}

function supplier_products_db_specs_photo_bedding_dimension_key(string $name): string
{
    $key = supplier_products_db_attr_norm($name);
    if ($key === '') {
        return '';
    }
    $hasSizeSignal = str_contains($key, 'размер')
        || str_contains($key, 'длина')
        || str_contains($key, 'ширина')
        || str_contains($key, 'size')
        || str_contains($key, 'length')
        || str_contains($key, 'width');
    if (!$hasSizeSignal) {
        return '';
    }
    if (str_contains($key, 'наволоч')) {
        return 'размер_наволочки';
    }
    if (str_contains($key, 'пододеял')) {
        return 'размер_пододеяльника';
    }
    if (str_contains($key, 'простын')) {
        return 'размер_простыни';
    }
    return '';
}

function supplier_products_db_specs_photo_name_is_excluded(string $name): bool
{
    $key = supplier_products_db_attr_norm($name);
    if ($key === '') {
        return true;
    }
    if (supplier_products_db_specs_photo_bedding_dimension_key($name) !== '') {
        return false;
    }
    if (supplier_products_db_feature_is_bare_dimension_attribute($name) || supplier_products_db_is_unit_quantity_attribute($name)) {
        return true;
    }
    $exact = [
        'brand', 'бренд', 'vendor', 'производитель',
        'barcode', 'штрихкод', 'артикул', 'vendorcode', 'article',
        'код продавца', 'код поставщика', 'код товара', 'seller code', 'supplier code', 'vendor code',
        'партномер', 'парт номер', 'part number', 'pn', 'p n',
        'model', 'модель', 'same model', 'same model tag', 'название модели', 'название модели для объединения в одну карточку',
        'объединить в похожие товары', 'похожие товары', 'similar products',
        'минимальное количество оптом', 'минимальная партия', 'moq',
        'цена', 'price', 'currencyid', 'available', 'stock', 'остаток',
        'название', 'наименование', 'наименование товара', 'name', 'title', 'product name',
        'description', 'описание', 'hashtag', 'hashtags',
        'категория', 'category', 'ozon category', 'wb category', 'wb subject id',
        'страна производства', 'страна производитель', 'страна изготовитель',
        'комплектация', 'класс опасности товара', 'класс опасности',
        'срок службы', 'срок службы лет',
    ];
    if (in_array($key, $exact, true)) {
        return true;
    }
    $patterns = [
        '~(?:^| )(?:длина|ширина|высота|толщина|глубина|габарит|габариты|размеры|вес|масса)(?: |$)~u',
        '~(?:length|width|height|depth|dimension|dimensions|weight)~u',
        '~гаранти|warranty~u',
        '~тн\s*вэд|тнвэд|код\s*тн|коды\s*еаэс|hs\s*code~u',
        '~срок\s+(?:годности|службы)|годности|expiration|shelf\s*life|service\s*life|lifetime|best\s*before~u',
        '~возраст|age\s*group|minimum\s*age~u',
        '~количество\s+(?:товара\s+)?в\s+единице|количество\s+(?:товара\s+)?в\s+упаковке|штук\s+в\s+упаковке|заводских\s+упаковок~u',
        '~(?:^| )(?:партномер|парт\s*номер|part\s*number|p\s*n|pn)(?: |$)~u',
        '~(?:^| )(?:код\s+продавца|код\s+поставщика|код\s+товара|seller\s+code|supplier\s+code|vendor\s+code)(?: |$)~u',
        '~(?:название\s+модели|model\s+name|same\s+model|объединить.*(?:похож|карточк)|похожие\s+товары|similar\s+products)~u',
        '~(?:^| )(?:наименование|название)(?:\s+товара|\s+изделия|\s+продукта)?(?: |$)~u',
        '~(?:минимальн.*(?:оптом|опт|парт|заказ)|minimum\s+order|moq|min\s+order)~u',
        '~ссылка|url|link|фото|photo|image|картинк~u',
    ];
    foreach ($patterns as $pattern) {
        if (preg_match($pattern, $key)) {
            return true;
        }
    }
    return false;
}

function supplier_products_db_specs_photo_name_is_compatibility(string $name): bool
{
    $key = supplier_products_db_attr_norm($name);
    if ($key === '') {
        return false;
    }
    return str_contains($key, 'совместим')
        || str_contains($key, 'подходит')
        || str_contains($key, 'compatible')
        || preg_match('~(?:^| )(?:для|под)\s+(?:бренд|модел|устройств)(?: |$)~u', $key) === 1;
}

function supplier_products_db_specs_photo_key_has_attribute_signal(string $key): bool
{
    if ($key === '') {
        return false;
    }
    return preg_match(
        '~(?:бренд|цвет|материал|состав|ткань|плотност|назначение|применение|тип|вид|форма|размер|комплект|простын|окраш|емкость|напряжение|мощность|разъем|интерфейс|совместим|подходит|наполнитель|покрытие|фактура|сезон|плотность|высота|ширина|длина)~u',
        $key
    ) === 1;
}

function supplier_products_db_specs_photo_description_name_is_noise(string $name): bool
{
    $name = supplier_products_db_specs_photo_clean_value($name);
    $key = supplier_products_db_attr_norm($name);
    if ($key === '') {
        return true;
    }
    if (supplier_products_db_specs_photo_key_has_attribute_signal($key)) {
        return false;
    }
    if (mb_strlen($name, 'UTF-8') > 34) {
        return true;
    }
    return preg_match('~(?:^| )(?:пододеяльник|простыня|наволочка|комплект|набор|товар|изделие|модель)(?: |$)~u', $key) === 1;
}

function supplier_products_db_specs_photo_name_dedupe_key(string $name): string
{
    $key = supplier_products_db_attr_norm($name);
    if ($key === '') {
        return '';
    }
    $beddingDimensionKey = supplier_products_db_specs_photo_bedding_dimension_key($name);
    if ($beddingDimensionKey !== '') {
        return $beddingDimensionKey;
    }
    if (in_array($key, ['цвет', 'цвет товара', 'color', 'colour'], true)) {
        return 'цвет';
    }
    if (in_array($key, ['материал', 'материал изделия', 'материал товара', 'material'], true)) {
        return 'материал';
    }
    if (str_contains($key, 'состав') || str_contains($key, 'ткань')) {
        return 'состав_материала';
    }
    if (str_contains($key, 'плотност')) {
        return 'плотность';
    }
    if (str_contains($key, 'окраш')) {
        return 'окрашивание';
    }
    if (str_contains($key, 'размерность') && str_contains($key, 'комплект')) {
        return 'размер_комплекта';
    }
    if (str_contains($key, 'простын')) {
        return 'тип_простыни';
    }
    if (in_array($key, ['назначение', 'назначение товара', 'назначение мебели', 'назначение мебельной фурнитуры', 'применение', 'application', 'purpose'], true)) {
        return 'назначение';
    }
    if (supplier_products_db_specs_photo_name_is_compatibility($name)) {
        return 'совместимость';
    }
    return $key;
}

function supplier_products_db_specs_photo_display_name(string $name): string
{
    $name = supplier_products_db_specs_photo_clean_value($name);
    $key = supplier_products_db_attr_norm($name);
    if ($key === '') {
        return '';
    }

    $labels = [
        'цвет' => 'Цвет',
        'цвет товара' => 'Цвет',
        'материал' => 'Материал',
        'материал изделия' => 'Материал',
        'материал товара' => 'Материал',
        'состав' => 'Состав',
        'состав материала' => 'Состав',
        'состав ткани' => 'Состав',
        'плотность' => 'Плотность',
        'метод окрашивания' => 'Окрашивание',
        'тип простыни' => 'Тип простыни',
        'размерность комплекта' => 'Размер комплекта',
        'размер наволочки' => 'Размер наволочки',
        'размер наволочек' => 'Размер наволочки',
        'размер простыни' => 'Размер простыни',
        'размер пододеяльника' => 'Размер пододеяльника',
        'материал фасада' => 'Материал фасада',
        'тип' => 'Тип',
        'тип петель мебели' => 'Тип петли',
        'тип петли' => 'Тип петли',
        'назначение' => 'Назначение',
        'назначение товара' => 'Назначение',
        'назначение мебели' => 'Назначение',
        'назначение мебельной фурнитуры' => 'Назначение',
        'уровень качества запчасти' => 'Качество',
        'качество' => 'Качество',
        'совместим с брендом' => 'Совместимость',
        'совместим с моделью' => 'Совместимость',
        'емкость' => 'Емкость',
        'емкость аккумулятора' => 'Емкость',
        'напряжение' => 'Напряжение',
        'химический тип' => 'Тип аккумулятора',
    ];
    if (isset($labels[$key])) {
        return $labels[$key];
    }
    $beddingDimensionKey = supplier_products_db_specs_photo_bedding_dimension_key($name);
    if ($beddingDimensionKey === 'размер_наволочки') {
        return 'Размер наволочки';
    }
    if ($beddingDimensionKey === 'размер_простыни') {
        return 'Размер простыни';
    }
    if ($beddingDimensionKey === 'размер_пододеяльника') {
        return 'Размер пододеяльника';
    }
    if (str_contains($key, 'угол') && str_contains($key, 'срабаты')) {
        return 'Угол срабатывания';
    }
    if (str_contains($key, 'ответн') && str_contains($key, 'планк')) {
        return 'Ответная планка';
    }
    if (str_contains($key, 'совместим') || str_contains($key, 'подходит')) {
        return 'Совместимость';
    }
    if (str_contains($key, 'назначение')) {
        return 'Назначение';
    }
    if (str_contains($key, 'состав')) {
        return 'Состав';
    }
    if (str_contains($key, 'плотност')) {
        return 'Плотность';
    }
    if (str_contains($key, 'окраш')) {
        return 'Окрашивание';
    }

    $name = preg_replace('~\s*\([^)]*\)\s*~u', ' ', $name) ?? $name;
    $name = preg_replace('~\b(?:товара|изделия|мебели|мебельной\s+фурнитуры)\b~iu', ' ', $name) ?? $name;
    $name = preg_replace('~\s+~u', ' ', (string)$name) ?? $name;
    $name = trim((string)$name);
    if ($name === '') {
        return '';
    }

    return mb_convert_case($name, MB_CASE_TITLE, 'UTF-8');
}

function supplier_products_db_specs_photo_display_value(string $value): string
{
    $value = supplier_products_db_specs_photo_clean_value($value);
    if ($value === '') {
        return '';
    }

    $embeddedLabels = 'Бренд|Состав|Состав материала|Материал|Назначение|Плотность|Метод окрашивания|Тип простыни|Цвет|Размерность комплекта|Размер простыни|Размер наволоч(?:ки|ек)|Размер пододеяльника';
    if (preg_match('~^(.{1,90}(?:\d|%|г/м|гр/м|мм|см|м2|м²).{0,24}?)(?:' . $embeddedLabels . ')\b~iu', $value, $m)) {
        $value = trim((string)$m[1], " \t\n\r\0\x0B,;|:-");
    }

    if (preg_match('~^([^,;:]{1,38})[,;:]\s+(.{8,})$~u', $value, $m)) {
        $first = trim((string)$m[1]);
        $tail = supplier_products_db_attr_norm((string)$m[2]);
        $tailIsDescription = preg_match('~обеспеч|подход|предназнач|использ|рекоменд|совместим|позвол|созда|имеет|для\s+~u', $tail) === 1;
        $firstLooksTechnical = preg_match('~\\d|%|°|в$|mah|мач|li|mm|мм|см|kg|кг|г$~iu', $first) === 1;
        if ($first !== '' && mb_strlen($first, 'UTF-8') >= 2 && ($tailIsDescription || $firstLooksTechnical)) {
            $value = $first;
        }
    }
    $value = preg_replace('~\s+и\s+др\.?$~iu', '', $value) ?? $value;
    $value = preg_replace('~\bпэ\b~iu', 'ПЭ', (string)$value) ?? $value;
    $value = preg_replace('~\s*[|,;]\s*[^|,;:]{1,28}:\s*$~u', '', (string)$value) ?? $value;
    return trim((string)$value);
}

function supplier_products_db_specs_photo_value_is_excluded(string $value): bool
{
    $value = supplier_products_db_specs_photo_clean_value($value);
    if ($value === '') {
        return true;
    }
    $key = supplier_products_db_attr_norm($value);
    if (in_array($key, ['true', 'false', 'yes', 'no', 'да', 'нет', 'не указано', 'не указан', 'n a'], true)) {
        return true;
    }
    if (preg_match('~^(?:https?://|www\.)~iu', $value)) {
        return true;
    }
    if (str_starts_with($value, '#')) {
        return true;
    }
    return false;
}

function supplier_products_db_specs_photo_description_plain(string $raw): string
{
    $raw = str_replace(['<![CDATA[', ']]>'], '', $raw);
    $raw = preg_replace('~<\s*tr\b[^>]*>~iu', "\n", (string)$raw);
    $raw = preg_replace('~<\s*br\s*/?\s*>~iu', "\n", (string)$raw);
    $raw = preg_replace('~<\s*/\s*(li|p|div|tr|h[1-6])\b[^>]*>~iu', "\n", (string)$raw);
    $raw = preg_replace('~<\s*(li|tr)\b[^>]*>~iu', "\n- ", (string)$raw);
    $raw = preg_replace('~<\s*/\s*(td|th)\b[^>]*>~iu', ': ', (string)$raw);
    $raw = strip_tags((string)$raw);
    $raw = html_entity_decode((string)$raw, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $raw = str_replace(["\xC2\xA0", "\xE2\x80\x8B"], ' ', (string)$raw);
    $raw = preg_replace('~[ \t]+~u', ' ', (string)$raw);
    $raw = preg_replace('~\s*\R\s*~u', "\n", (string)$raw);
    return trim((string)$raw);
}

function supplier_products_db_specs_photo_description_characteristics(array $product, int $limit): array
{
    $limit = max(1, min(12, $limit));
    $raw = trim((string)($product['description_html'] ?? ''));
    if ($raw === '') {
        return [];
    }

    $plain = supplier_products_db_specs_photo_description_plain($raw);
    if ($plain === '') {
        return [];
    }

    $headingKeys = [
        'характеристики' => true,
        'основные характеристики' => true,
        'технические характеристики' => true,
        'описание' => true,
        'особенности' => true,
        'преимущества' => true,
        'комплектация' => true,
    ];
    $items = [];
    $seenNames = [];
    $seenPairs = [];
    $lines = preg_split('~\R+~u', $plain) ?: [];
    foreach ($lines as $line) {
        $line = trim((string)$line);
        if ($line === '') {
            continue;
        }
        $line = trim($line, " \t\n\r\0\x0B-–—•*·");
        $line = preg_replace('~\s+~u', ' ', (string)$line);
        $line = trim((string)$line);
        if ($line === '') {
            continue;
        }

        $lineKey = supplier_products_db_attr_norm($line);
        if (isset($headingKeys[$lineKey])) {
            continue;
        }

        $name = '';
        $value = '';
        if (preg_match('~^(.{2,70}?)(?:\s*[:：]\s*|\s+[—–-]\s+)(.{1,180})$~u', $line, $m)) {
            $name = trim((string)$m[1], " \t\n\r\0\x0B-–—•*·:：");
            $value = trim((string)$m[2]);
        }
        if ($name === '' || $value === '') {
            continue;
        }

        $name = supplier_products_db_specs_photo_clean_value($name);
        $value = supplier_products_db_specs_photo_clean_value($value);
        if ($name === '' || mb_strlen($name, 'UTF-8') > 64) {
            continue;
        }
        if (supplier_products_db_specs_photo_description_name_is_noise($name)) {
            continue;
        }
        if (supplier_products_db_specs_photo_name_is_excluded($name) || supplier_products_db_specs_photo_value_is_excluded($value)) {
            continue;
        }

        $nameKey = supplier_products_db_specs_photo_name_dedupe_key($name);
        $pairKey = $nameKey . "\n" . supplier_products_db_attr_norm($value);
        if ($nameKey === '' || isset($seenNames[$nameKey]) || isset($seenPairs[$pairKey])) {
            continue;
        }

        $items[] = [
            'kind' => 'description',
            'name' => $name,
            'value' => $value,
        ];
        $seenNames[$nameKey] = true;
        $seenPairs[$pairKey] = true;
        if (count($items) >= $limit) {
            break;
        }
    }

    return $items;
}

function supplier_products_db_specs_photo_product_brand(array $product, array $fields): string
{
    $candidates = [];
    foreach ($fields as $field) {
        $kind = (string)($field['field_kind'] ?? '');
        $name = trim((string)($field['field_name'] ?? ''));
        if ($kind === 'standard' && in_array($name, ['brand', 'brand_ozon', 'brand_wb'], true)) {
            $candidates[] = trim((string)($field['field_value'] ?? ''));
        }
    }
    $candidates[] = trim((string)($product['brand'] ?? ''));
    foreach ($fields as $field) {
        $kind = (string)($field['field_kind'] ?? '');
        $name = trim((string)($field['field_name'] ?? ''));
        if ($kind === 'tag' && in_array($name, ['brand', 'vendor'], true)) {
            $candidates[] = trim((string)($field['field_value'] ?? ''));
        }
    }
    foreach ($candidates as $candidate) {
        $candidate = trim((string)$candidate);
        if ($candidate !== '' && !supplier_products_db_brand_is_empty_like($candidate)) {
            return $candidate;
        }
    }
    return '';
}

function supplier_products_db_specs_photo_characteristic_score(string $kind, string $name, string $value, int $order): int
{
    $key = supplier_products_db_attr_norm($name);
    $valueKey = supplier_products_db_attr_norm($value);
    $score = 1000 - min(500, $order);
    if ($kind === 'param') {
        $score += 80;
    } elseif ($kind === 'wb_param') {
        $score += 70;
    } elseif ($kind === 'description') {
        $score += 120;
    } elseif ($kind === 'attr') {
        $score += 20;
    }
    $highValuePatterns = [
        '~уровень\s+качества|качество~u',
        '~емкость|capacity|mah|мач~u',
        '~напряжение|voltage|вольт~u',
        '~химический\s+тип|тип\s+аккумулятора|li ion|li-ion|lipo|li po~u',
        '~совместим|назначение|применение~u',
        '~материал|material~u',
        '~мощность|power|watt~u',
        '~разъем|connector|интерфейс|interface~u',
        '~тип|форм[- ]?фактор~u',
        '~цвет|color~u',
    ];
    foreach ($highValuePatterns as $pattern) {
        if (preg_match($pattern, $key . ' ' . $valueKey)) {
            $score += 120;
            break;
        }
    }
    if ((str_contains($key, 'состав') || str_contains($key, 'материал')) && preg_match('~%|хлоп|полиэстер|пэ|сатин|жаккард|ткань~u', $valueKey)) {
        $score += str_contains($key, 'состав') && str_contains($valueKey, '%') ? 300 : 150;
    }
    if (supplier_products_db_specs_photo_bedding_dimension_key($name) !== '' && preg_match('~\d|х|x|×|см|cm~iu', $value)) {
        $score += 430;
    }
    if (str_contains($key, 'состав') && !str_contains($valueKey, '%') && mb_strlen($value, 'UTF-8') <= 14) {
        $score -= 220;
    }
    if (supplier_products_db_specs_photo_name_is_compatibility($name)) {
        $score += 40;
        $looksLikeModelList = preg_match('~[\d()/,\-]|(?:^| )(?:se|pro|max|plus|lite|ultra|mini|note|galaxy|redmi|honor|iphone|ipad|macbook)(?: |$)~iu', $value) === 1;
        $isBrandCompatibility = str_contains($key, 'бренд') || str_contains($key, 'brand');
        if ($looksLikeModelList || str_contains($key, 'модел') || str_contains($key, 'model')) {
            $score += 130;
        }
        if ($isBrandCompatibility && !$looksLikeModelList) {
            $score -= 120;
        }
    }
    $valueLen = mb_strlen($value, 'UTF-8');
    if ($valueLen > 95) {
        $score -= 90;
    } elseif ($valueLen <= 48) {
        $score += 30;
    }
    return $score;
}

function supplier_products_db_specs_photo_characteristics(array $product, array $fields, int $limit): array
{
    $limit = max(1, min(12, $limit));
    $items = [];
    $seenNames = [];
    $seenPairs = [];
    $order = 0;
    $addItem = static function (string $kind, string $name, string $value, int $order, int $bonus = 0) use (&$items, &$seenNames, &$seenPairs): bool {
        $name = trim($name);
        $value = supplier_products_db_specs_photo_clean_value($value);
        if ($name === '' || supplier_products_db_specs_photo_name_is_excluded($name) || supplier_products_db_specs_photo_value_is_excluded($value)) {
            return false;
        }
        $nameKey = supplier_products_db_specs_photo_name_dedupe_key($name);
        $pairKey = $nameKey . "\n" . supplier_products_db_attr_norm($value);
        if ($nameKey === '' || isset($seenPairs[$pairKey])) {
            return false;
        }
        $score = supplier_products_db_specs_photo_characteristic_score($kind, $name, $value, $order) + $bonus;
        if (isset($seenNames[$nameKey]) && $items[$seenNames[$nameKey]]['score'] >= $score) {
            return false;
        }
        $item = [
            'kind' => $kind,
            'name' => $name,
            'value' => $value,
            'score' => $score,
            'order' => $order,
        ];
        if (isset($seenNames[$nameKey])) {
            $items[$seenNames[$nameKey]] = $item;
        } else {
            $seenNames[$nameKey] = count($items);
            $items[] = $item;
        }
        $seenPairs[$pairKey] = true;
        return true;
    };

    foreach (supplier_products_db_specs_photo_description_characteristics($product, $limit) as $descItem) {
        if ($addItem(
            'description',
            (string)($descItem['name'] ?? ''),
            (string)($descItem['value'] ?? ''),
            $order,
            80
        )) {
            $order++;
        }
    }

    foreach ($fields as $field) {
        $kind = (string)($field['field_kind'] ?? '');
        if (!in_array($kind, ['param', 'wb_param', 'attr'], true)) {
            continue;
        }
        $name = trim((string)($field['field_name'] ?? ''));
        $value = (string)($field['field_value'] ?? '');
        if ($addItem($kind, $name, $value, $order)) {
            $order++;
        }
    }

    usort($items, static function (array $a, array $b): int {
        $byScore = (int)($b['score'] ?? 0) <=> (int)($a['score'] ?? 0);
        return $byScore !== 0 ? $byScore : ((int)($a['order'] ?? 0) <=> (int)($b['order'] ?? 0));
    });

    return array_map(static function (array $item): array {
        return [
            'kind' => (string)($item['kind'] ?? ''),
            'name' => (string)($item['name'] ?? ''),
            'value' => (string)($item['value'] ?? ''),
        ];
    }, array_slice($items, 0, $limit));
}

function supplier_products_db_specs_photo_load_background(array $template, array $cfg): GdImage
{
    $relative = trim((string)($template['relative_path'] ?? ''));
    if ($relative !== '') {
        $path = supplier_products_local_image_abs_path($relative, $cfg);
        if ($path !== '' && is_file($path)) {
            return supplier_products_bundle_photo_load($path);
        }
    }

    $url = trim((string)($template['url'] ?? ''));
    if ($url === '') {
        throw new RuntimeException('У категории нет сохраненного фон-шаблона для дополнительных фото.');
    }
    $source = supplier_products_bundle_photo_source_path($url, $cfg);
    try {
        return supplier_products_bundle_photo_load((string)$source['path']);
    } finally {
        if (!empty($source['temporary'])) {
            @unlink((string)$source['path']);
        }
    }
}

function supplier_products_db_specs_photo_create(array $template, string $brand, array $items, array $cfg, int $targetW = 1200, int $targetH = 1600, int $jpegQuality = 92): array
{
    if (!extension_loaded('gd')) {
        throw new RuntimeException('Для создания фото-характеристик требуется PHP GD.');
    }
    if (!$items) {
        throw new RuntimeException('Нет полезных характеристик для фото.');
    }

    $background = supplier_products_db_specs_photo_load_background($template, $cfg);
    $canvas = null;
    try {
        $srcW = max(1, imagesx($background));
        $srcH = max(1, imagesy($background));
        $canvas = imagecreatetruecolor($targetW, $targetH);
        if (!$canvas instanceof GdImage) {
            throw new RuntimeException('Не удалось создать холст фото-характеристик.');
        }
        imagealphablending($canvas, true);
        imagesavealpha($canvas, false);

        $scale = max($targetW / $srcW, $targetH / $srcH);
        $bgW = max(1, (int)ceil($srcW * $scale));
        $bgH = max(1, (int)ceil($srcH * $scale));
        $bgX = (int)floor(($targetW - $bgW) / 2);
        $bgY = (int)floor(($targetH - $bgH) / 2);
        imagecopyresampled($canvas, $background, $bgX, $bgY, 0, 0, $bgW, $bgH, $srcW, $srcH);

        $fontBold = supplier_products_bundle_photo_font_path($cfg);
        $fontRegular = supplier_products_db_specs_photo_regular_font_path($cfg);
        $dark = imagecolorallocate($canvas, 15, 23, 42);
        $labelColor = imagecolorallocate($canvas, 34, 45, 63);
        $rule = imagecolorallocatealpha($canvas, 31, 41, 55, 86);
        $textGlow = imagecolorallocatealpha($canvas, 255, 255, 255, 18);

        $marginX = 116;
        $topY = 162;
        $contentW = $targetW - ($marginX * 2);
        supplier_products_db_specs_photo_draw_text_top_shadow($canvas, $fontBold, 52, $marginX, $topY, $dark, 'Характеристики', $textGlow);
        imagefilledrectangle($canvas, $marginX, $topY + 86, $marginX + $contentW, $topY + 87, $rule);

        $layoutItems = [];
        $brand = trim($brand);
        if ($brand !== '' && !supplier_products_db_brand_is_empty_like($brand)) {
            $layoutItems[] = [
                'name' => 'Бренд',
                'value' => $brand,
                'kind' => 'brand',
            ];
        }
        foreach ($items as $item) {
            $layoutItems[] = $item;
        }

        $drawn = [];
        $columns = count($layoutItems) >= 5 ? 2 : 1;
        $maxLayoutItems = $columns >= 2 ? 8 : 5;
        if (count($layoutItems) > $maxLayoutItems) {
            $layoutItems = array_slice($layoutItems, 0, $maxLayoutItems);
        }
        $columns = count($layoutItems) >= 5 ? 2 : 1;
        $gapX = 64;
        $gapY = 30;
        $columnW = (int)floor(($contentW - (($columns - 1) * $gapX)) / $columns);
        $listY = $topY + 174;
        $maxY = $targetH - 150;
        $rowsNeeded = max(1, (int)ceil(count($layoutItems) / $columns));
        $rowH = (int)floor(($maxY - $listY - (($rowsNeeded - 1) * $gapY)) / $rowsNeeded);
        $rowH = max(138, min(188, $rowH));
        $itemIndex = 0;
        foreach ($layoutItems as $item) {
            $name = supplier_products_db_specs_photo_display_name((string)($item['name'] ?? ''));
            $value = supplier_products_db_specs_photo_display_value((string)($item['value'] ?? ''));
            if ($name === '' || $value === '') {
                continue;
            }
            $labelSize = $columns >= 2 ? 21 : 24;
            $nameLine = supplier_products_db_specs_photo_ellipsis($fontRegular, $labelSize, $name, $columnW);
            $valueSize = $columns >= 2 ? 27 : 32;
            $maxValueLines = $columns >= 2 ? 2 : 3;
            $valueLines = supplier_products_db_specs_photo_wrap_text($fontBold, $valueSize, $value, $columnW, $maxValueLines);
            $valueAreaH = $rowH - 72;
            while ($valueSize > 21) {
                $lineStepTest = (int)ceil($valueSize * 1.22);
                if (count($valueLines) * $lineStepTest <= $valueAreaH) {
                    break;
                }
                $valueSize -= 2;
                $valueLines = supplier_products_db_specs_photo_wrap_text($fontBold, $valueSize, $value, $columnW, $maxValueLines);
            }
            if (!$valueLines) {
                continue;
            }
            $col = $itemIndex % $columns;
            $row = (int)floor($itemIndex / $columns);
            $itemX = $marginX + ($col * ($columnW + $gapX));
            $itemY = $listY + ($row * ($rowH + $gapY));
            if ($itemY + 92 > $maxY) {
                break;
            }
            supplier_products_db_specs_photo_draw_text_top($canvas, $fontRegular, $labelSize, $itemX, $itemY, $labelColor, $nameLine);
            $lineY = $itemY + 36;
            $lineStep = (int)ceil($valueSize * 1.22);
            foreach ($valueLines as $line) {
                supplier_products_db_specs_photo_draw_text_top($canvas, $fontBold, $valueSize, $itemX, $lineY, $dark, $line);
                $lineY += $lineStep;
            }
            imagefilledrectangle($canvas, $itemX, $itemY + $rowH - 12, $itemX + $columnW, $itemY + $rowH - 11, $rule);
            $drawn[] = ['name' => $name, 'value' => $value];
            $itemIndex++;
        }

        if (!$drawn) {
            throw new RuntimeException('Полезные характеристики не поместились на фото.');
        }

        imageinterlace($canvas, true);
        ob_start();
        $ok = imagejpeg($canvas, null, max(1, min(100, $jpegQuality)));
        $bytes = ob_get_clean();
        if (!$ok || !is_string($bytes) || $bytes === '') {
            throw new RuntimeException('Не удалось сохранить фото-характеристики в JPEG.');
        }
        return [
            'bytes' => $bytes,
            'meta' => [
                'format' => 'jpeg',
                'jpeg_quality' => $jpegQuality,
                'width' => $targetW,
                'height' => $targetH,
                'layout' => 'category_background_clean_text',
                'brand_shown' => $brand !== '' && !supplier_products_db_brand_is_empty_like($brand),
                'items_requested' => count($items),
                'items_drawn' => count($drawn),
                'drawn_items' => $drawn,
            ],
        ];
    } finally {
        unset($background);
        if ($canvas instanceof GdImage) {
            unset($canvas);
        }
    }
}

function supplier_products_db_cover_prompt_json($value): string
{
    $json = json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT);
    return $json === false ? '{}' : $json;
}

function supplier_products_db_cover_prompt_parts(array $coverPayload): array
{
    $category = is_array($coverPayload['category'] ?? null) ? $coverPayload['category'] : [];
    $coverRules = is_array($coverPayload['cover_rules'] ?? null) ? $coverPayload['cover_rules'] : [];
    $staticRules = [
        'title_top' => true,
        'product_large' => true,
        'brand_bottom_only_if_show' => true,
        'gpt_must_render_exact_text' => true,
        'server_text_overlay' => false,
        'use_only_exact_text' => true,
        'product_fully_visible' => true,
        'product_safe_margin_percent' => 6,
        'wide_product_may_be_smaller_to_avoid_crop' => true,
        'ozon_badge_safe_zone_soft' => [
            'enabled' => true,
            'avoid_important_text_in_top_left_corner' => true,
            'avoid_important_text_in_top_right_corner' => true,
            'prefer_title_below_top_safe_zone' => true,
            'do_not_block_generation' => true,
        ],
    ];
    foreach (['title_top', 'product_large', 'brand_bottom_only_if_show', 'gpt_must_render_exact_text', 'server_text_overlay'] as $key) {
        if (array_key_exists($key, $coverRules)) {
            $staticRules[$key] = (bool)$coverRules[$key];
        }
    }

    $dynamicRules = [];
    foreach (['features_count', 'bundle_quantity_required'] as $key) {
        if (array_key_exists($key, $coverRules)) {
            $dynamicRules[$key] = $coverRules[$key];
        }
    }

    return [
        'category' => $category,
        'static_rules' => $staticRules,
        'product_cover' => [
            'product' => is_array($coverPayload['product'] ?? null) ? $coverPayload['product'] : [],
            'features' => array_values((array)($coverPayload['features'] ?? [])),
            'brand' => is_array($coverPayload['brand'] ?? null) ? $coverPayload['brand'] : [],
            'bundle' => is_array($coverPayload['bundle'] ?? null) ? $coverPayload['bundle'] : [],
            'exact_text' => is_array($coverPayload['exact_text'] ?? null) ? $coverPayload['exact_text'] : [],
            'cover_rules_dynamic' => $dynamicRules,
        ],
    ];
}

function supplier_products_db_cover_prompt_text(string $prompt, array $coverPayload): array
{
    $parts = supplier_products_db_cover_prompt_parts($coverPayload);
    $staticPrefix = $prompt
        . "\n\nCATEGORY STYLE JSON (static for prompt cache):\n"
        . supplier_products_db_cover_prompt_json($parts['category'])
        . "\n\nSTATIC COVER RULES JSON (static for prompt cache):\n"
        . supplier_products_db_cover_prompt_json($parts['static_rules']);

    $text = $staticPrefix
        . "\n\nPRODUCT COVER JSON (dynamic product data, exact texts, bundle and features):\n"
        . supplier_products_db_cover_prompt_json($parts['product_cover']);

    return [
        'text' => $text,
        'format' => 'cover_category_static_product_dynamic_v2',
        'static_prefix_sha256' => hash('sha256', $staticPrefix),
    ];
}

function supplier_products_db_cover_prompt_cache_key(string $imageModel, string $imageSize, string $imageQuality, array $promptMeta): string
{
    $staticPrefixHash = trim((string)($promptMeta['static_prefix_sha256'] ?? ''));
    if ($staticPrefixHash === '') {
        $staticPrefixHash = hash('sha256', (string)($promptMeta['format'] ?? 'cover'));
    }

    $payload = [
        'op' => 'gpt_generate_cover_image',
        'endpoint' => 'responses_image_generation',
        'format' => (string)($promptMeta['format'] ?? ''),
        'static_prefix_sha256' => $staticPrefixHash,
        'image_model' => strtolower(trim($imageModel)),
        'image_size' => strtolower(trim($imageSize)),
        'image_quality' => strtolower(trim($imageQuality)),
    ];
    $json = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($json === false) {
        $json = $staticPrefixHash;
    }

    return 'cover_img:' . substr(hash('sha256', $json), 0, 48);
}

function supplier_products_db_image_response_model(array $cfg, array $params): string
{
    $model = trim((string)($params['image_response_model'] ?? ''));
    if ($model === '') {
        $model = trim((string)($cfg['openai_image']['response_model'] ?? ''));
    }
    if ($model === '') {
        $model = trim((string)($cfg['openai']['image_response_model'] ?? ''));
    }
    if ($model === '') {
        $model = 'gpt-5.4-mini';
    }
    return $model;
}

function supplier_products_db_op_gpt_generate_cover_image(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '1') !== '' && (string)($params['overwrite'] ?? '1') !== '0');
    $imageQuality = trim((string)($params['image_quality'] ?? 'low'));
    if (!in_array($imageQuality, ['low', 'medium', 'high', 'auto'], true)) {
        $imageQuality = 'low';
    }
    $defaultImageModel = trim((string)($cfg['openai_image']['default_model'] ?? 'gpt-image-1.5'));
    if ($defaultImageModel === '') {
        $defaultImageModel = 'gpt-image-1.5';
    }
    $imageModel = strtolower(trim((string)($params['image_model'] ?? $defaultImageModel)));
    if ($imageModel === '') {
        $imageModel = $defaultImageModel;
    }
    $imageResponseModel = supplier_products_db_image_response_model($cfg, $params);
    $imagePricing = openai_image_pricing_for_model($cfg, $imageModel);
    if ((string)($imagePricing['source'] ?? 'unknown') === 'unknown') {
        throw new RuntimeException('Неизвестная GPT Image модель для расчета стоимости: ' . $imageModel);
    }
    $matchedImageModel = strtolower(trim((string)($imagePricing['matched_model'] ?? $imageModel)));
    $imageSize = supplier_products_db_normalize_gpt_image_size((string)($params['image_size'] ?? '1200x1600'), $matchedImageModel, '1200x1600');
    $inputFidelity = strtolower(trim((string)($params['input_fidelity'] ?? 'auto')));
    $inputFidelityConfig = supplier_products_db_image_input_fidelity_config($matchedImageModel, $inputFidelity);
    $imageOptionsInputFidelity = (string)($inputFidelityConfig['option'] ?? '');
    $imageUsageInputFidelity = (string)($inputFidelityConfig['effective'] ?? 'low');
    $imageInputFidelityLabel = (string)($inputFidelityConfig['label'] ?? ($imageOptionsInputFidelity !== '' ? $imageOptionsInputFidelity : 'auto'));
    $timeoutSec = max(60, min(600, (int)trim((string)($params['timeout_sec'] ?? '180'))));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'cover_image_ru.txt');
    $log("supplier_db gpt_generate_cover_image: image_api=/responses:image_generation, response_model={$imageResponseModel}, image_model={$imageModel}, max_items={$maxItems}, image_size={$imageSize}, target_aspect=3:4, target_size=1200x1600, final_processing=proportional_only_no_crop_no_padding, final_format=jpeg, final_quality=92, input_fidelity={$imageInputFidelityLabel}, text_rendering=gpt_image, overwrite=" . ($overwrite ? '1' : '0') . "\n");
    $log("image pricing: " . openai_image_pricing_debug_string($imagePricing) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');

    $jobs = [];
    $seenProducts = 0;
    $skippedNoPicture = 0;
    $skippedNoFeatures = 0;
    $skippedNoCoverDesign = 0;
    $skippedGenerated = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }
        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        $firstPicture = trim((string)($pictures[0] ?? ''));
        if ($firstPicture === '') {
            $skippedNoPicture++;
            continue;
        }
        $hasGeneratedCover = supplier_products_db_cover_picture_is_generated($firstPicture);
        if (!$overwrite && $hasGeneratedCover) {
            $skippedGenerated++;
            continue;
        }
        $sourcePicture = supplier_products_db_cover_source_picture($pictures);
        if ($sourcePicture === '') {
            $skippedNoPicture++;
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $features = supplier_products_db_product_feature_values($fields);
        if (!$features) {
            $skippedNoFeatures++;
            continue;
        }

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $brand = trim((string)($context['brand'] ?? ($product['brand'] ?? '')));
        $brandShow = !supplier_products_db_brand_is_empty_like($brand);
        $categoryPayload = supplier_products_db_cover_category_payload($product, $fields);
        if (trim((string)($categoryPayload['cover_design'] ?? '')) === '') {
            $skippedNoCoverDesign++;
            continue;
        }
        $categoryName = trim((string)($product['category_path'] ?? ''));
        $bundle = supplier_products_db_cover_bundle_info($product, $fields);
        $shortName = supplier_products_db_standard_field_value_from_rows($fields, 'short_name');
        $coverTitleSource = $shortName !== '' ? 'short_name' : 'product_name_fallback';
        $coverTitle = $shortName !== ''
            ? supplier_products_db_cover_title($shortName, $categoryName)
            : supplier_products_db_cover_title((string)($product['name'] ?? ''), $categoryName);
        $bundleQuantityText = (!empty($bundle['is_bundle']) && (int)($bundle['quantity'] ?? 1) > 1)
            ? ('Комплект: ' . (int)$bundle['quantity'] . ' шт')
            : '';
        $brandText = $brandShow ? $brand : '';

        $coverPayload = [
            'product' => [
                'offer_id' => $offerId,
                'vendorCode' => (string)($product['vendor_code'] ?? ''),
                'name' => $coverTitle,
                'source_name_reference' => (string)($product['name'] ?? ''),
                'cover_title' => $coverTitle,
                'cover_title_source' => $coverTitleSource,
                'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 1400),
                'model' => (string)($context['model'] ?? ''),
                'vendor' => (string)($context['vendor'] ?? ''),
                'params' => array_slice(supplier_products_db_product_params_payload($fields), 0, 60),
            ],
            'category' => $categoryPayload,
            'features' => $features,
            'brand' => [
                'value' => $brand,
                'show' => $brandShow,
            ],
            'bundle' => $bundle,
            'exact_text' => [
                'title' => $coverTitle,
                'features' => $features,
                'brand' => $brandText,
                'bundle_quantity' => $bundleQuantityText,
            ],
            'cover_rules' => [
                'title_top' => true,
                'product_large' => true,
                'features_count' => count($features),
                'brand_bottom_only_if_show' => true,
                'bundle_quantity_required' => !empty($bundle['is_bundle']),
                'gpt_must_render_exact_text' => true,
                'server_text_overlay' => false,
            ],
        ];

        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'pictures' => $pictures,
            'first_picture' => $sourcePicture,
            'source_pictures' => supplier_products_db_cover_source_picture_candidates($pictures),
            'payload' => $coverPayload,
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 100 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log(
        "scan: products_seen={$seenProducts}, jobs=" . count($jobs) .
        ", skipped_no_picture={$skippedNoPicture}, skipped_no_features={$skippedNoFeatures}, " .
        "skipped_no_cover_design={$skippedNoCoverDesign}, skipped_generated={$skippedGenerated}\n"
    );

    $clientConfig = $cfg['llm_providers']['openai'] ?? ($cfg['openai'] ?? []);
    if (!is_array($clientConfig) || trim((string)($clientConfig['api_key'] ?? '')) === '') {
        throw new RuntimeException('OPENAI_API_KEY не настроен для генерации обложек через GPT Image.');
    }
    $clientConfig['provider'] = 'openai';
    $clientConfig['api_format'] = 'responses';
    $clientConfig['model_prefix'] = '';
    $clientConfig['timeout_sec'] = $timeoutSec;
    $clientConfig['response_cache_enabled'] = false;
    $client = count($jobs) > 0 ? new OpenAIClient($clientConfig) : null;

    $results = [];
    $changedProducts = [];
    $imageInputTokensTotal = 0;
    $imageCachedInputTokensTotal = 0;
    $imageTextInputTokensTotal = 0;
    $imageTextCachedInputTokensTotal = 0;
    $imageImageInputTokensTotal = 0;
    $imageImageCachedInputTokensTotal = 0;
    $imageOutputTokensTotal = 0;
    $imageTextOutputTokensTotal = 0;
    $imageImageOutputTokensTotal = 0;
    $imageTotalTokensTotal = 0;
    $imageUsageEstimatedJobs = 0;
    $imageGenerationCostTotal = 0.0;
    $costUsdTotal = 0.0;
    $firstLlmError = '';
    $imagePromptCacheKeys = [];
    $imagePromptStaticPrefixHashes = [];
    $loggedPromptCacheKeys = [];
    $done = 0;
    $totalJobs = max(1, count($jobs));

    foreach ($jobs as $offerId => $job) {
        $jobNo = $done + 1;
        ops_update_progress($opId, $done, $totalJobs, 'gpt_image', "cover {$jobNo}/{$totalJobs} in progress offer={$offerId}");

        $status = 'ok';
        $err = '';
        $newUrl = '';
        $imageUsage = [
            'input_tokens' => 0,
            'cached_input_tokens' => 0,
            'text_input_tokens' => 0,
            'text_cached_input_tokens' => 0,
            'image_input_tokens' => 0,
            'image_cached_input_tokens' => 0,
            'output_tokens' => 0,
            'text_output_tokens' => 0,
            'image_output_tokens' => 0,
            'total_tokens' => 0,
        ];
        $imageCost = ['cost' => 0.0, 'cost_label' => openai_format_cost(0.0, (string)($imagePricing['currency'] ?? 'USD'))];
        $rawSanitized = null;
        $sourceMeta = [];
        $promptMeta = [
            'format' => '',
            'static_prefix_sha256' => '',
            'prompt_cache_key' => '',
        ];
        $promptCacheKey = '';
        $finalImageMeta = [];

        try {
            if (!$client instanceof OpenAIClient) {
                throw new RuntimeException('OpenAI client is not initialized.');
            }
            $sourceAttempts = [];
            foreach ((array)($job['source_pictures'] ?? [$job['first_picture'] ?? '']) as $candidatePicture) {
                $candidatePicture = trim((string)$candidatePicture);
                if ($candidatePicture === '') {
                    continue;
                }
                try {
                    $sourceMeta = supplier_products_db_cover_image_data_url($candidatePicture, $cfg);
                    $sourceMeta['source_url'] = $candidatePicture;
                    if ($candidatePicture !== (string)$job['first_picture']) {
                        $log("GPT COVER source fallback offer={$offerId}: using " . supplier_products_db_cover_picture_log_label($candidatePicture) . "\n");
                    }
                    break;
                } catch (Throwable $e) {
                    $sourceAttempts[] = supplier_products_db_cover_picture_log_label($candidatePicture) . ' => ' . $e->getMessage();
                }
            }
            if (!$sourceMeta) {
                $details = array_slice($sourceAttempts, 0, 5);
                throw new RuntimeException('Не удалось загрузить ни одно фото товара для GPT-обложки' . ($details ? ': ' . implode('; ', $details) : '.'));
            }
            $requestPayload = (array)($job['payload'] ?? []);
            $promptMeta = supplier_products_db_cover_prompt_text($prompt, $requestPayload);
            $promptCacheKey = supplier_products_db_cover_prompt_cache_key($imageModel, $imageSize, $imageQuality, $promptMeta);
            $promptMeta['prompt_cache_key'] = $promptCacheKey;
            $staticPrefixHash = (string)($promptMeta['static_prefix_sha256'] ?? '');
            if ($promptCacheKey !== '') {
                $imagePromptCacheKeys[$promptCacheKey] = true;
                if (!isset($loggedPromptCacheKeys[$promptCacheKey])) {
                    $loggedPromptCacheKeys[$promptCacheKey] = true;
                    $log("image prompt cache: key={$promptCacheKey}, static_prefix_sha256={$staticPrefixHash}\n");
                }
            }
            if ($staticPrefixHash !== '') {
                $imagePromptStaticPrefixHashes[$staticPrefixHash] = true;
            }
            $inputText = (string)($promptMeta['text'] ?? $prompt);

            $imageOptions = [
                'size' => $imageSize,
                'quality' => $imageQuality,
                'output_format' => 'png',
                'background' => 'opaque',
                'moderation' => 'auto',
                'prompt_cache_key' => $promptCacheKey,
            ];
            if ($imageOptionsInputFidelity !== '') {
                $imageOptions['input_fidelity'] = $imageOptionsInputFidelity;
            }

            $sourceImageBytes = supplier_products_db_cover_image_bytes_from_data_url((string)$sourceMeta['image_url']);
            $raw = $client->editImageWithResponsesTool(
                $imageResponseModel,
                $imageModel,
                $inputText,
                $sourceImageBytes,
                (string)($sourceMeta['mime'] ?? 'image/jpeg'),
                $imageOptions
            );

            $imageUsage = supplier_products_db_cover_image_api_usage($raw);
            $rawSanitized = supplier_products_db_cover_sanitize_image_api_response($raw);
            $generatedBytes = supplier_products_db_cover_decode_image_api_result($raw);
            if ((int)$imageUsage['total_tokens'] <= 0) {
                $imageUsage = supplier_products_db_cover_estimate_image_usage(
                    $inputText,
                    $sourceMeta,
                    $generatedBytes,
                    $imageModel,
                    $imageQuality,
                    $imageSize,
                    $imagePricing,
                    $imageUsageInputFidelity
                );
            } elseif (!empty($imageUsage['input_details_missing'])) {
                $imageUsage = supplier_products_db_cover_refine_image_usage_split(
                    $imageUsage,
                    $inputText,
                    $sourceMeta,
                    $generatedBytes,
                    $imageModel,
                    $imageQuality,
                    $imageSize,
                    $imagePricing,
                    $imageUsageInputFidelity
                );
            }
            if (!empty($imageUsage['estimated']) || !empty($imageUsage['estimated_split'])) {
                $imageUsageEstimatedJobs++;
            }
            $imageInputTokensTotal += (int)$imageUsage['input_tokens'];
            $imageCachedInputTokensTotal += (int)$imageUsage['cached_input_tokens'];
            $imageTextInputTokensTotal += (int)$imageUsage['text_input_tokens'];
            $imageTextCachedInputTokensTotal += (int)$imageUsage['text_cached_input_tokens'];
            $imageImageInputTokensTotal += (int)$imageUsage['image_input_tokens'];
            $imageImageCachedInputTokensTotal += (int)$imageUsage['image_cached_input_tokens'];
            $imageOutputTokensTotal += (int)$imageUsage['output_tokens'];
            $imageTextOutputTokensTotal += (int)$imageUsage['text_output_tokens'];
            $imageImageOutputTokensTotal += (int)$imageUsage['image_output_tokens'];
            $imageTotalTokensTotal += (int)$imageUsage['total_tokens'];
            $imageCost = openai_image_generation_cost_breakdown(
                $cfg,
                $imageModel,
                (int)$imageUsage['text_input_tokens'],
                (int)$imageUsage['text_cached_input_tokens'],
                (int)$imageUsage['text_output_tokens'],
                (int)$imageUsage['image_input_tokens'],
                (int)$imageUsage['image_cached_input_tokens'],
                (int)$imageUsage['image_output_tokens']
            );
            $matchedImageModel = strtolower(trim((string)($imagePricing['matched_model'] ?? $imageModel)));
            $outputSizeKey = supplier_products_db_cover_output_size_key($imageSize, $generatedBytes);
            $outputQualityKey = supplier_products_db_cover_quality_key($imageQuality);
            $fixedOutputCost = supplier_products_db_cover_image_output_price($imageModel, $outputQualityKey, $outputSizeKey, $imagePricing);
            if ($matchedImageModel !== 'gpt-image-2' && $fixedOutputCost > 0.0) {
                $tokenOutputCost = (float)($imageCost['image_output_cost'] ?? 0.0);
                $adjustedCost = round(max(0.0, (float)($imageCost['cost'] ?? 0.0) - $tokenOutputCost + $fixedOutputCost), 6);
                $imageCost['image_output_pricing_mode'] = 'fixed_per_image';
                $imageCost['image_output_size'] = $outputSizeKey;
                $imageCost['image_output_quality'] = $outputQualityKey;
                $imageCost['image_output_cost_token_based'] = $tokenOutputCost;
                $imageCost['image_output_cost'] = round($fixedOutputCost, 6);
                $imageCost['cost'] = $adjustedCost;
                $imageCost['cost_usd'] = $adjustedCost;
                $imageCost['cost_label'] = openai_format_cost($adjustedCost, (string)($imageCost['currency'] ?? ($imagePricing['currency'] ?? 'USD')));
            } else {
                $imageCost['image_output_pricing_mode'] = 'token';
                $imageCost['image_output_size'] = $outputSizeKey;
                $imageCost['image_output_quality'] = $outputQualityKey;
            }
            $imageGenerationCostTotal += (float)$imageCost['cost'];
            $finalImage = supplier_products_db_cover_marketplace_output_image($generatedBytes, 1200, 1600, 92);
            $finalImageMeta = (array)($finalImage['meta'] ?? []);
            $finalBytes = (string)($finalImage['bytes'] ?? '');
            $newUrl = supplier_products_db_cover_save_image($supplierId, (int)$job['product_id'], $finalBytes, $cfg);

            $pictures = supplier_products_db_cover_pictures_with_new_cover((array)($job['pictures'] ?? []), $newUrl);
            supplier_products_update_pictures((int)$job['product_id'], $pictures, $cfg);
            $changedProducts[(int)$job['product_id']] = true;
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            if ($firstLlmError === '') {
                $firstLlmError = $err;
            }
            $log("GPT COVER ERROR offer={$offerId}: {$err}\n");
        }

        $results[$offerId] = [
            'status' => $status,
            'error' => $err,
            'new_url' => $newUrl,
            'image_usage' => $imageUsage,
            'image_generation_cost' => $imageCost,
            'prompt_cache_key' => $promptCacheKey,
            'final_image' => $finalImageMeta,
        ];

        file_put_contents(
            $outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'status' => $status,
                'error' => $err,
                'source_picture' => (string)($sourceMeta['source_url'] ?? $job['first_picture']),
                'source_picture_requested' => (string)$job['first_picture'],
                'source_image' => array_diff_key($sourceMeta, ['image_url' => true]),
                'new_url' => $newUrl,
                'payload' => $job['payload'] ?? [],
                'input_format' => (string)($promptMeta['format'] ?? ''),
                'prompt_static_prefix_sha256' => (string)($promptMeta['static_prefix_sha256'] ?? ''),
                'prompt_cache_key' => (string)($promptMeta['prompt_cache_key'] ?? ''),
                'final_image' => $finalImageMeta,
                'image_usage' => $imageUsage,
                'image_generation_cost' => $imageCost,
                'raw_sanitized' => $rawSanitized,
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );

        $done++;
        ops_update_progress($opId, $done, $totalJobs, 'gpt_image', "cover {$done}/{$totalJobs} processed offer={$offerId} status={$status}");
    }

    if (count($jobs) > 0) {
        ops_update_progress($opId, $done, $totalJobs, 'finalize', 'saving product changes');
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    foreach ($results as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
    }
    supplier_products_db_fail_if_llm_unavailable(
        'gpt_generate_cover_image',
        count($jobs),
        (int)($statusCounts['error'] ?? 0),
        $imageInputTokensTotal,
        $imageOutputTokensTotal,
        $firstLlmError
    );
    ops_update_progress(
        $opId,
        count($jobs) > 0 ? $done : 1,
        count($jobs) > 0 ? $totalJobs : 1,
        'done',
        count($jobs) > 0 ? 'cover generation completed' : 'No cover jobs'
    );

    $imageGenerationCostTotal = round($imageGenerationCostTotal, 6);
    $costUsdTotal = $imageGenerationCostTotal;
    $imageCurrency = strtoupper(trim((string)($imagePricing['currency'] ?? 'USD'))) ?: 'USD';
    $costLabel = openai_format_cost($costUsdTotal, $imageCurrency);
    $imageGenerationCostLabel = openai_format_cost($imageGenerationCostTotal, $imageCurrency);
    $imageCostFields = [
        'cost' => $costUsdTotal,
        'cost_currency' => $imageCurrency,
        'cost_label' => $costLabel,
        'cost_usd' => $costUsdTotal,
    ];
    $imagePromptCacheKeyList = array_keys($imagePromptCacheKeys);
    $imagePromptStaticPrefixHashList = array_keys($imagePromptStaticPrefixHashes);
    $report = [
        'title' => 'gpt_generate_cover_image',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $totalProducts,
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'card_briefs_built' => count($jobs),
            'gpt_status_counts' => $statusCounts,
            'products_touched' => count($changedProducts),
            'skipped_no_picture' => $skippedNoPicture,
            'skipped_no_features' => $skippedNoFeatures,
            'skipped_no_cover_design' => $skippedNoCoverDesign,
            'skipped_generated' => $skippedGenerated,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'usage' => [
                'input_tokens' => $imageInputTokensTotal,
                'cached_input_tokens' => $imageCachedInputTokensTotal,
                'output_tokens' => $imageOutputTokensTotal,
                'image_generation_model' => $imageModel,
                'image_api_endpoint' => '/responses:image_generation',
                'image_response_model' => $imageResponseModel,
                'image_input_fidelity' => $imageInputFidelityLabel,
                'image_input_fidelity_requested' => (string)($inputFidelityConfig['requested'] ?? $inputFidelity),
                'image_input_fidelity_note' => (string)($inputFidelityConfig['note'] ?? ''),
                'image_prompt_cache_key_count' => count($imagePromptCacheKeyList),
                'image_prompt_cache_key' => count($imagePromptCacheKeyList) === 1 ? (string)$imagePromptCacheKeyList[0] : '',
                'image_prompt_cache_keys' => $imagePromptCacheKeyList,
                'image_prompt_static_prefix_sha256_count' => count($imagePromptStaticPrefixHashList),
                'image_prompt_static_prefix_sha256' => count($imagePromptStaticPrefixHashList) === 1 ? (string)$imagePromptStaticPrefixHashList[0] : '',
                'image_output_pricing_mode' => strtolower(trim((string)($imagePricing['matched_model'] ?? $imageModel))) === 'gpt-image-2' ? 'token' : 'fixed_per_image',
                'image_usage_estimated_jobs' => $imageUsageEstimatedJobs,
                'image_input_tokens' => $imageInputTokensTotal,
                'image_cached_input_tokens' => $imageCachedInputTokensTotal,
                'image_text_input_tokens' => $imageTextInputTokensTotal,
                'image_text_cached_input_tokens' => $imageTextCachedInputTokensTotal,
                'image_input_image_tokens' => $imageImageInputTokensTotal,
                'image_input_cached_image_tokens' => $imageImageCachedInputTokensTotal,
                'image_output_tokens' => $imageOutputTokensTotal,
                'image_text_output_tokens' => $imageTextOutputTokensTotal,
                'image_output_image_tokens' => $imageImageOutputTokensTotal,
                'image_total_tokens' => $imageTotalTokensTotal,
                'image_generation_cost' => $imageGenerationCostTotal,
                'image_generation_cost_label' => $imageGenerationCostLabel,
                'image_generation_cost_currency' => (string)($imagePricing['currency'] ?? 'USD'),
                'image_generation_pricing' => [
                    'requested_model' => (string)($imagePricing['requested_model'] ?? $imageModel),
                    'matched_model' => (string)($imagePricing['matched_model'] ?? $imageModel),
                    'source' => (string)($imagePricing['source'] ?? 'unknown'),
                    'text_input_per_1m' => (float)($imagePricing['text_input_per_1m'] ?? 0.0),
                    'text_cached_input_per_1m' => (float)($imagePricing['text_cached_input_per_1m'] ?? 0.0),
                    'text_output_per_1m' => (float)($imagePricing['text_output_per_1m'] ?? 0.0),
                    'image_input_per_1m' => (float)($imagePricing['image_input_per_1m'] ?? 0.0),
                    'image_cached_input_per_1m' => (float)($imagePricing['image_cached_input_per_1m'] ?? 0.0),
                    'image_output_per_1m' => (float)($imagePricing['image_output_per_1m'] ?? 0.0),
                ],
            ] + $imageCostFields,
        ],
        'params_effective' => [
            'image_model' => $imageModel,
            'image_response_model' => $imageResponseModel,
            'max_items' => (string)$maxItems,
            'image_size' => $imageSize,
            'image_quality' => $imageQuality,
            'input_fidelity' => $imageInputFidelityLabel,
            'input_fidelity_requested' => (string)($inputFidelityConfig['requested'] ?? $inputFidelity),
            'text_rendering' => 'gpt_image',
            'timeout_sec' => (string)$timeoutSec,
            'overwrite' => $overwrite ? '1' : '0',
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_generate_cover_image',
        'items' => [
            'Jobs: ' . count($jobs),
            'Card briefs built: ' . count($jobs),
            'Products touched: ' . count($changedProducts),
            'Skipped no picture: ' . $skippedNoPicture,
            'Skipped no features: ' . $skippedNoFeatures,
            'Skipped no cover design: ' . $skippedNoCoverDesign,
            'Image model: ' . $imageModel,
            'Image response model: ' . $imageResponseModel,
            'Image API: /responses:image_generation',
            'Input fidelity: ' . $imageInputFidelityLabel,
            'Text rendering: GPT Image',
            'Image prompt cache keys: ' . count($imagePromptCacheKeyList) . (count($imagePromptCacheKeyList) === 1 ? ' (' . $imagePromptCacheKeyList[0] . ')' : ''),
            'Image prompt static prefixes: ' . count($imagePromptStaticPrefixHashList),
            'Image usage estimated jobs: ' . $imageUsageEstimatedJobs,
            'Image generation tokens in: ' . $imageInputTokensTotal . ' (text ' . $imageTextInputTokensTotal . ', image ' . $imageImageInputTokensTotal . ')',
            'Image generation cached tokens in: ' . $imageCachedInputTokensTotal . ' (text ' . $imageTextCachedInputTokensTotal . ', image ' . $imageImageCachedInputTokensTotal . ')',
            'Image generation tokens out: ' . $imageOutputTokensTotal . ' (image ' . $imageImageOutputTokensTotal . ')',
            'Image generation cost: ' . $imageGenerationCostLabel,
            'Total tracked cost: ' . $costLabel,
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_gpt_generate_product_photo_variant(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $onlySingleSourcePhoto = ((string)($params['only_single_source_photo'] ?? '0') !== '' && (string)($params['only_single_source_photo'] ?? '0') !== '0');
    $imageQuality = trim((string)($params['image_quality'] ?? 'low'));
    if (!in_array($imageQuality, ['low', 'medium', 'high', 'auto'], true)) {
        $imageQuality = 'low';
    }
    $defaultImageModel = trim((string)($cfg['openai_image']['default_model'] ?? 'gpt-image-1.5'));
    if ($defaultImageModel === '') {
        $defaultImageModel = 'gpt-image-1.5';
    }
    $imageModel = strtolower(trim((string)($params['image_model'] ?? $defaultImageModel)));
    if ($imageModel === '') {
        $imageModel = $defaultImageModel;
    }
    $imageResponseModel = supplier_products_db_image_response_model($cfg, $params);
    $imagePricing = openai_image_pricing_for_model($cfg, $imageModel);
    if ((string)($imagePricing['source'] ?? 'unknown') === 'unknown') {
        throw new RuntimeException('Неизвестная GPT Image модель для расчета стоимости: ' . $imageModel);
    }
    $matchedImageModel = strtolower(trim((string)($imagePricing['matched_model'] ?? $imageModel)));
    $imageSize = supplier_products_db_normalize_gpt_image_size((string)($params['image_size'] ?? '1200x1600'), $matchedImageModel, '1200x1600');
    $inputFidelity = strtolower(trim((string)($params['input_fidelity'] ?? 'auto')));
    $inputFidelityConfig = supplier_products_db_image_input_fidelity_config($matchedImageModel, $inputFidelity);
    $imageOptionsInputFidelity = (string)($inputFidelityConfig['option'] ?? '');
    $imageUsageInputFidelity = (string)($inputFidelityConfig['effective'] ?? 'low');
    $imageInputFidelityLabel = (string)($inputFidelityConfig['label'] ?? ($imageOptionsInputFidelity !== '' ? $imageOptionsInputFidelity : 'auto'));
    $timeoutSec = max(60, min(600, (int)trim((string)($params['timeout_sec'] ?? '180'))));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'product_photo_variant_ru.txt');
    $log("supplier_db gpt_generate_product_photo_variant: image_api=/responses:image_generation, response_model={$imageResponseModel}, image_model={$imageModel}, max_items={$maxItems}, only_single_source_photo=" . ($onlySingleSourcePhoto ? '1' : '0') . ", image_size={$imageSize}, target_aspect=3:4, target_size=1200x1600, final_processing=proportional_only_no_crop_no_padding, final_format=jpeg, final_quality=92, input_fidelity={$imageInputFidelityLabel}\n");
    $log("image pricing: " . openai_image_pricing_debug_string($imagePricing) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');

    $jobs = [];
    $seenProducts = 0;
    $skippedNoPicture = 0;
    $skippedNotSinglePicture = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }
        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        $sourcePictures = supplier_products_db_photo_variant_source_pictures($pictures);
        $sourcePicture = (string)($sourcePictures[0] ?? '');
        if ($sourcePicture === '') {
            $skippedNoPicture++;
            continue;
        }
        if ($onlySingleSourcePhoto && count($sourcePictures) !== 1) {
            $skippedNotSinglePicture++;
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
        $categoryPayload = ft_load_combined_marketplace_category_context($ozonCategory, $wbCategory, true);
        if (!$categoryPayload) {
            $categoryPayload = supplier_products_db_empty_description_category_context();
        }
        $productPayload = [
            'offer_id' => $offerId,
            'vendorCode' => (string)($product['vendor_code'] ?? ''),
            'name' => (string)($product['name'] ?? ''),
            'category_path' => (string)($product['category_path'] ?? ''),
            'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 900),
            'model' => (string)($context['model'] ?? ''),
            'brand' => (string)($context['brand'] ?? ($product['brand'] ?? '')),
            'vendor' => (string)($context['vendor'] ?? ''),
            'params' => array_slice(supplier_products_db_product_params_payload($fields), 0, 40),
        ];
        $payload = [
            'product' => $productPayload,
            'category' => $categoryPayload,
            'card_brief' => ft_card_brief_build($productPayload, $categoryPayload, [
                'purpose' => 'photo',
                'operation_mode' => 'generate_product_photo_variant',
                'use_keywords' => true,
            ]),
            'rules' => [
                'same_product_required' => true,
                'create_new_photo_not_cover' => true,
                'no_infographic' => true,
                'no_added_text' => true,
                'append_to_photos' => true,
            ],
        ];

        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'pictures' => $pictures,
            'source_picture' => $sourcePicture,
            'source_pictures_count' => count($sourcePictures),
            'payload' => $payload,
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 100 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log("scan: products_seen={$seenProducts}, jobs=" . count($jobs) . ", skipped_no_picture={$skippedNoPicture}, skipped_not_single_picture={$skippedNotSinglePicture}\n");

    $clientConfig = $cfg['llm_providers']['openai'] ?? ($cfg['openai'] ?? []);
    if (!is_array($clientConfig) || trim((string)($clientConfig['api_key'] ?? '')) === '') {
        throw new RuntimeException('OPENAI_API_KEY не настроен для генерации фото-вариаций через GPT Image.');
    }
    $clientConfig['provider'] = 'openai';
    $clientConfig['api_format'] = 'responses';
    $clientConfig['model_prefix'] = '';
    $clientConfig['timeout_sec'] = $timeoutSec;
    $clientConfig['response_cache_enabled'] = false;
    $client = count($jobs) > 0 ? new OpenAIClient($clientConfig) : null;

    $results = [];
    $changedProducts = [];
    $imageInputTokensTotal = 0;
    $imageCachedInputTokensTotal = 0;
    $imageTextInputTokensTotal = 0;
    $imageTextCachedInputTokensTotal = 0;
    $imageImageInputTokensTotal = 0;
    $imageImageCachedInputTokensTotal = 0;
    $imageOutputTokensTotal = 0;
    $imageTextOutputTokensTotal = 0;
    $imageImageOutputTokensTotal = 0;
    $imageTotalTokensTotal = 0;
    $imageUsageEstimatedJobs = 0;
    $imageGenerationCostTotal = 0.0;
    $firstLlmError = '';
    $imagePromptCacheKeys = [];
    $imagePromptStaticPrefixHashes = [];
    $loggedPromptCacheKeys = [];
    $done = 0;
    $totalJobs = max(1, count($jobs));

    foreach ($jobs as $offerId => $job) {
        $jobNo = $done + 1;
        ops_update_progress($opId, $done, $totalJobs, 'gpt_image', "photo variant {$jobNo}/{$totalJobs} in progress offer={$offerId}");

        $status = 'ok';
        $err = '';
        $newUrl = '';
        $imageUsage = [
            'input_tokens' => 0,
            'cached_input_tokens' => 0,
            'text_input_tokens' => 0,
            'text_cached_input_tokens' => 0,
            'image_input_tokens' => 0,
            'image_cached_input_tokens' => 0,
            'output_tokens' => 0,
            'text_output_tokens' => 0,
            'image_output_tokens' => 0,
            'total_tokens' => 0,
        ];
        $imageCost = ['cost' => 0.0, 'cost_label' => openai_format_cost(0.0, (string)($imagePricing['currency'] ?? 'USD'))];
        $rawSanitized = null;
        $sourceMeta = [];
        $promptMeta = ['format' => '', 'static_prefix_sha256' => '', 'payload_sha256' => '', 'prompt_cache_key' => ''];
        $promptCacheKey = '';
        $finalImageMeta = [];

        try {
            if (!$client instanceof OpenAIClient) {
                throw new RuntimeException('OpenAI client is not initialized.');
            }
            $sourceMeta = supplier_products_db_cover_image_data_url((string)$job['source_picture'], $cfg);
            $promptMeta = supplier_products_db_photo_variant_prompt_text($prompt, (array)($job['payload'] ?? []));
            $promptCacheKey = supplier_products_db_photo_variant_prompt_cache_key($imageModel, $imageSize, $imageQuality, $promptMeta);
            $promptMeta['prompt_cache_key'] = $promptCacheKey;
            $staticPrefixHash = (string)($promptMeta['static_prefix_sha256'] ?? '');
            if ($promptCacheKey !== '') {
                $imagePromptCacheKeys[$promptCacheKey] = true;
                if (!isset($loggedPromptCacheKeys[$promptCacheKey])) {
                    $loggedPromptCacheKeys[$promptCacheKey] = true;
                    $log("image prompt cache: key={$promptCacheKey}, static_prefix_sha256={$staticPrefixHash}\n");
                }
            }
            if ($staticPrefixHash !== '') {
                $imagePromptStaticPrefixHashes[$staticPrefixHash] = true;
            }
            $inputText = (string)($promptMeta['text'] ?? $prompt);

            $imageOptions = [
                'size' => $imageSize,
                'quality' => $imageQuality,
                'output_format' => 'png',
                'background' => 'opaque',
                'moderation' => 'auto',
                'prompt_cache_key' => $promptCacheKey,
            ];
            if ($imageOptionsInputFidelity !== '') {
                $imageOptions['input_fidelity'] = $imageOptionsInputFidelity;
            }

            $sourceImageBytes = supplier_products_db_cover_image_bytes_from_data_url((string)$sourceMeta['image_url']);
            $raw = $client->editImageWithResponsesTool(
                $imageResponseModel,
                $imageModel,
                $inputText,
                $sourceImageBytes,
                (string)($sourceMeta['mime'] ?? 'image/jpeg'),
                $imageOptions
            );

            $imageUsage = supplier_products_db_cover_image_api_usage($raw);
            $rawSanitized = supplier_products_db_cover_sanitize_image_api_response($raw);
            $generatedBytes = supplier_products_db_cover_decode_image_api_result($raw);
            if ((int)$imageUsage['total_tokens'] <= 0) {
                $imageUsage = supplier_products_db_cover_estimate_image_usage(
                    $inputText,
                    $sourceMeta,
                    $generatedBytes,
                    $imageModel,
                    $imageQuality,
                    $imageSize,
                    $imagePricing,
                    $imageUsageInputFidelity
                );
            } elseif (!empty($imageUsage['input_details_missing'])) {
                $imageUsage = supplier_products_db_cover_refine_image_usage_split(
                    $imageUsage,
                    $inputText,
                    $sourceMeta,
                    $generatedBytes,
                    $imageModel,
                    $imageQuality,
                    $imageSize,
                    $imagePricing,
                    $imageUsageInputFidelity
                );
            }
            if (!empty($imageUsage['estimated']) || !empty($imageUsage['estimated_split'])) {
                $imageUsageEstimatedJobs++;
            }
            $imageInputTokensTotal += (int)$imageUsage['input_tokens'];
            $imageCachedInputTokensTotal += (int)$imageUsage['cached_input_tokens'];
            $imageTextInputTokensTotal += (int)$imageUsage['text_input_tokens'];
            $imageTextCachedInputTokensTotal += (int)$imageUsage['text_cached_input_tokens'];
            $imageImageInputTokensTotal += (int)$imageUsage['image_input_tokens'];
            $imageImageCachedInputTokensTotal += (int)$imageUsage['image_cached_input_tokens'];
            $imageOutputTokensTotal += (int)$imageUsage['output_tokens'];
            $imageTextOutputTokensTotal += (int)$imageUsage['text_output_tokens'];
            $imageImageOutputTokensTotal += (int)$imageUsage['image_output_tokens'];
            $imageTotalTokensTotal += (int)$imageUsage['total_tokens'];

            $imageCost = openai_image_generation_cost_breakdown(
                $cfg,
                $imageModel,
                (int)$imageUsage['text_input_tokens'],
                (int)$imageUsage['text_cached_input_tokens'],
                (int)$imageUsage['text_output_tokens'],
                (int)$imageUsage['image_input_tokens'],
                (int)$imageUsage['image_cached_input_tokens'],
                (int)$imageUsage['image_output_tokens']
            );
            $matchedImageModel = strtolower(trim((string)($imagePricing['matched_model'] ?? $imageModel)));
            $outputSizeKey = supplier_products_db_cover_output_size_key($imageSize, $generatedBytes);
            $outputQualityKey = supplier_products_db_cover_quality_key($imageQuality);
            $fixedOutputCost = supplier_products_db_cover_image_output_price($imageModel, $outputQualityKey, $outputSizeKey, $imagePricing);
            if ($matchedImageModel !== 'gpt-image-2' && $fixedOutputCost > 0.0) {
                $tokenOutputCost = (float)($imageCost['image_output_cost'] ?? 0.0);
                $adjustedCost = round(max(0.0, (float)($imageCost['cost'] ?? 0.0) - $tokenOutputCost + $fixedOutputCost), 6);
                $imageCost['image_output_pricing_mode'] = 'fixed_per_image';
                $imageCost['image_output_size'] = $outputSizeKey;
                $imageCost['image_output_quality'] = $outputQualityKey;
                $imageCost['image_output_cost_token_based'] = $tokenOutputCost;
                $imageCost['image_output_cost'] = round($fixedOutputCost, 6);
                $imageCost['cost'] = $adjustedCost;
                $imageCost['cost_usd'] = $adjustedCost;
                $imageCost['cost_label'] = openai_format_cost($adjustedCost, (string)($imageCost['currency'] ?? ($imagePricing['currency'] ?? 'USD')));
            } else {
                $imageCost['image_output_pricing_mode'] = 'token';
                $imageCost['image_output_size'] = $outputSizeKey;
                $imageCost['image_output_quality'] = $outputQualityKey;
            }
            $imageGenerationCostTotal += (float)$imageCost['cost'];

            $finalImage = supplier_products_db_photo_variant_marketplace_output_image($generatedBytes, 1200, 1600, 92);
            $finalImageMeta = (array)($finalImage['meta'] ?? []);
            $newUrl = supplier_products_db_photo_variant_save_image($supplierId, (int)$job['product_id'], (string)($finalImage['bytes'] ?? ''), $cfg);
            $pictures = supplier_products_db_photo_variant_pictures_with_new_image((array)($job['pictures'] ?? []), $newUrl);
            supplier_products_update_pictures((int)$job['product_id'], $pictures, $cfg);
            $changedProducts[(int)$job['product_id']] = true;
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            if ($firstLlmError === '') {
                $firstLlmError = $err;
            }
            $log("GPT PHOTO VARIANT ERROR offer={$offerId}: {$err}\n");
        }

        $results[$offerId] = [
            'status' => $status,
            'error' => $err,
            'new_url' => $newUrl,
            'image_usage' => $imageUsage,
            'image_generation_cost' => $imageCost,
            'prompt_cache_key' => $promptCacheKey,
            'final_image' => $finalImageMeta,
        ];

        file_put_contents(
            $outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'status' => $status,
                'error' => $err,
                'source_picture' => (string)$job['source_picture'],
                'source_pictures_count' => (int)($job['source_pictures_count'] ?? 0),
                'source_image' => array_diff_key($sourceMeta, ['image_url' => true]),
                'new_url' => $newUrl,
                'payload' => $job['payload'] ?? [],
                'input_format' => (string)($promptMeta['format'] ?? ''),
                'prompt_static_prefix_sha256' => (string)($promptMeta['static_prefix_sha256'] ?? ''),
                'prompt_static_rules_sha256' => (string)($promptMeta['static_rules_sha256'] ?? ''),
                'payload_sha256' => (string)($promptMeta['payload_sha256'] ?? ''),
                'prompt_cache_key' => (string)($promptMeta['prompt_cache_key'] ?? ''),
                'final_image' => $finalImageMeta,
                'image_usage' => $imageUsage,
                'image_generation_cost' => $imageCost,
                'raw_sanitized' => $rawSanitized,
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );

        $done++;
        ops_update_progress($opId, $done, $totalJobs, 'gpt_image', "photo variant {$done}/{$totalJobs} processed offer={$offerId} status={$status}");
    }

    if (count($jobs) > 0) {
        ops_update_progress($opId, $done, $totalJobs, 'finalize', 'saving product changes');
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    foreach ($results as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
    }
    supplier_products_db_fail_if_llm_unavailable(
        'gpt_generate_product_photo_variant',
        count($jobs),
        (int)($statusCounts['error'] ?? 0),
        $imageInputTokensTotal,
        $imageOutputTokensTotal,
        $firstLlmError
    );
    ops_update_progress(
        $opId,
        count($jobs) > 0 ? $done : 1,
        count($jobs) > 0 ? $totalJobs : 1,
        'done',
        count($jobs) > 0 ? 'photo variants completed' : 'No photo variant jobs'
    );

    $imageGenerationCostTotal = round($imageGenerationCostTotal, 6);
    $imageCurrency = strtoupper(trim((string)($imagePricing['currency'] ?? 'USD'))) ?: 'USD';
    $costLabel = openai_format_cost($imageGenerationCostTotal, $imageCurrency);
    $imageGenerationCostLabel = openai_format_cost($imageGenerationCostTotal, $imageCurrency);
    $imageCostFields = [
        'cost' => $imageGenerationCostTotal,
        'cost_currency' => $imageCurrency,
        'cost_label' => $costLabel,
        'cost_usd' => $imageGenerationCostTotal,
    ];
    $imagePromptCacheKeyList = array_keys($imagePromptCacheKeys);
    $imagePromptStaticPrefixHashList = array_keys($imagePromptStaticPrefixHashes);
    $report = [
        'title' => 'gpt_generate_product_photo_variant',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $totalProducts,
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'gpt_status_counts' => $statusCounts,
            'products_touched' => count($changedProducts),
            'skipped_no_picture' => $skippedNoPicture,
            'skipped_not_single_picture' => $skippedNotSinglePicture,
            'only_single_source_photo' => $onlySingleSourcePhoto,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'usage' => [
                'input_tokens' => $imageInputTokensTotal,
                'cached_input_tokens' => $imageCachedInputTokensTotal,
                'output_tokens' => $imageOutputTokensTotal,
                'image_generation_model' => $imageModel,
                'image_api_endpoint' => '/responses:image_generation',
                'image_response_model' => $imageResponseModel,
                'image_input_fidelity' => $imageInputFidelityLabel,
                'image_input_fidelity_requested' => (string)($inputFidelityConfig['requested'] ?? $inputFidelity),
                'image_input_fidelity_note' => (string)($inputFidelityConfig['note'] ?? ''),
                'image_prompt_cache_key_count' => count($imagePromptCacheKeyList),
                'image_prompt_cache_key' => count($imagePromptCacheKeyList) === 1 ? (string)$imagePromptCacheKeyList[0] : '',
                'image_prompt_cache_keys' => $imagePromptCacheKeyList,
                'image_prompt_static_prefix_sha256_count' => count($imagePromptStaticPrefixHashList),
                'image_prompt_static_prefix_sha256' => count($imagePromptStaticPrefixHashList) === 1 ? (string)$imagePromptStaticPrefixHashList[0] : '',
                'image_output_pricing_mode' => strtolower(trim((string)($imagePricing['matched_model'] ?? $imageModel))) === 'gpt-image-2' ? 'token' : 'fixed_per_image',
                'image_usage_estimated_jobs' => $imageUsageEstimatedJobs,
                'image_input_tokens' => $imageInputTokensTotal,
                'image_cached_input_tokens' => $imageCachedInputTokensTotal,
                'image_text_input_tokens' => $imageTextInputTokensTotal,
                'image_text_cached_input_tokens' => $imageTextCachedInputTokensTotal,
                'image_input_image_tokens' => $imageImageInputTokensTotal,
                'image_input_cached_image_tokens' => $imageImageCachedInputTokensTotal,
                'image_output_tokens' => $imageOutputTokensTotal,
                'image_text_output_tokens' => $imageTextOutputTokensTotal,
                'image_output_image_tokens' => $imageImageOutputTokensTotal,
                'image_total_tokens' => $imageTotalTokensTotal,
                'image_generation_cost' => $imageGenerationCostTotal,
                'image_generation_cost_label' => $imageGenerationCostLabel,
                'image_generation_cost_currency' => (string)($imagePricing['currency'] ?? 'USD'),
            ] + $imageCostFields,
        ],
        'params_effective' => [
            'image_model' => $imageModel,
            'image_response_model' => $imageResponseModel,
            'max_items' => (string)$maxItems,
            'only_single_source_photo' => $onlySingleSourcePhoto ? '1' : '0',
            'image_size' => $imageSize,
            'image_quality' => $imageQuality,
            'input_fidelity' => $imageInputFidelityLabel,
            'input_fidelity_requested' => (string)($inputFidelityConfig['requested'] ?? $inputFidelity),
            'timeout_sec' => (string)$timeoutSec,
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_generate_product_photo_variant',
        'items' => [
            'Jobs: ' . count($jobs),
            'Products touched: ' . count($changedProducts),
            'Skipped no picture: ' . $skippedNoPicture,
            'Skipped not single ordinary photo: ' . $skippedNotSinglePicture,
            'Only single ordinary photo: ' . ($onlySingleSourcePhoto ? 'yes' : 'no'),
            'Image model: ' . $imageModel,
            'Image response model: ' . $imageResponseModel,
            'Image API: /responses:image_generation',
            'Input fidelity: ' . $imageInputFidelityLabel,
            'Image prompt cache keys: ' . count($imagePromptCacheKeyList) . (count($imagePromptCacheKeyList) === 1 ? ' (' . $imagePromptCacheKeyList[0] . ')' : ''),
            'Image prompt static prefixes: ' . count($imagePromptStaticPrefixHashList),
            'Image usage estimated jobs: ' . $imageUsageEstimatedJobs,
            'Image generation tokens in: ' . $imageInputTokensTotal . ' (text ' . $imageTextInputTokensTotal . ', image ' . $imageImageInputTokensTotal . ')',
            'Image generation cached tokens in: ' . $imageCachedInputTokensTotal . ' (text ' . $imageTextCachedInputTokensTotal . ', image ' . $imageImageCachedInputTokensTotal . ')',
            'Image generation tokens out: ' . $imageOutputTokensTotal . ' (image ' . $imageImageOutputTokensTotal . ')',
            'Image generation cost: ' . $imageGenerationCostLabel,
            'Total tracked cost: ' . $costLabel,
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_create_photo_collage(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '1') !== '' && (string)($params['overwrite'] ?? '1') !== '0');

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/collage');

    $log("supplier_db create_photo_collage: max_items={$maxItems}, final_size=1200x1600, final_format=jpeg, final_quality=92, source_photos=2-3, overwrite=" . ($overwrite ? '1' : '0') . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');

    $jobs = [];
    $seenProducts = 0;
    $skippedFewPictures = 0;
    $skippedExisting = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        if (!$overwrite && supplier_products_db_photo_collage_has_generated($pictures)) {
            $skippedExisting++;
            continue;
        }

        $basePictures = $overwrite
            ? supplier_products_db_photo_collage_without_existing_collages($pictures)
            : $pictures;
        $sourcePictures = supplier_products_db_photo_collage_source_pictures($basePictures, 3);
        if (count($sourcePictures) < 2) {
            $skippedFewPictures++;
            continue;
        }

        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'pictures' => $basePictures,
            'source_pictures' => $sourcePictures,
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 100 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log("scan: products_seen={$seenProducts}, jobs=" . count($jobs) . ", skipped_few_pictures={$skippedFewPictures}, skipped_existing={$skippedExisting}\n");

    $results = [];
    $changedProducts = [];
    $done = 0;
    $totalJobs = max(1, count($jobs));
    foreach ($jobs as $offerId => $job) {
        $jobNo = $done + 1;
        ops_update_progress($opId, $done, $totalJobs, 'collage', "collage {$jobNo}/{$totalJobs} in progress offer={$offerId}");

        $status = 'ok';
        $err = '';
        $newUrl = '';
        $meta = [];
        try {
            $created = supplier_products_db_photo_collage_create((array)($job['source_pictures'] ?? []), $cfg, 1200, 1600, 92);
            $meta = (array)($created['meta'] ?? []);
            $newUrl = supplier_products_db_photo_collage_save_image($supplierId, (int)$job['product_id'], (string)($created['bytes'] ?? ''), $cfg);
            $pictures = supplier_products_db_photo_collage_pictures_with_new_image((array)($job['pictures'] ?? []), $newUrl);
            supplier_products_update_pictures((int)$job['product_id'], $pictures, $cfg);
            $changedProducts[(int)$job['product_id']] = true;
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            $log("PHOTO COLLAGE ERROR offer={$offerId}: {$err}\n");
        }

        $results[$offerId] = [
            'status' => $status,
            'error' => $err,
            'new_url' => $newUrl,
            'source_pictures' => array_values((array)($job['source_pictures'] ?? [])),
            'collage' => $meta,
        ];

        file_put_contents(
            $outDir . '/collage/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode($results[$offerId], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );

        $done++;
        ops_update_progress($opId, $done, $totalJobs, 'collage', "collage {$done}/{$totalJobs} processed offer={$offerId} status={$status}");
    }

    if (count($jobs) > 0) {
        ops_update_progress($opId, $done, $totalJobs, 'finalize', 'saving product changes');
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    foreach ($results as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
    }

    ops_update_progress(
        $opId,
        count($jobs) > 0 ? $done : 1,
        count($jobs) > 0 ? $totalJobs : 1,
        'done',
        count($jobs) > 0 ? 'photo collages completed' : 'No collage jobs'
    );

    $report = [
        'title' => 'create_photo_collage',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $totalProducts,
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'status_counts' => $statusCounts,
            'products_touched' => count($changedProducts),
            'skipped_few_pictures' => $skippedFewPictures,
            'skipped_existing' => $skippedExisting,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'cost' => 0.0,
            'cost_currency' => 'USD',
            'cost_label' => openai_format_cost(0.0, 'USD'),
            'cost_usd' => 0.0,
        ],
        'params_effective' => [
            'max_items' => (string)$maxItems,
            'overwrite' => $overwrite ? '1' : '0',
            'source_photos' => '2-3',
            'final_size' => '1200x1600',
            'final_format' => 'jpeg',
            'final_quality' => '92',
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'create_photo_collage',
        'items' => [
            'Jobs: ' . count($jobs),
            'Products touched: ' . count($changedProducts),
            'Skipped few pictures: ' . $skippedFewPictures,
            'Skipped existing: ' . $skippedExisting,
            'Errors: ' . (int)($statusCounts['error'] ?? 0),
            'Cost: ' . openai_format_cost(0.0, 'USD'),
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_create_video_cover(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $sourcePhotos = max(1, min(4, (int)trim((string)($params['source_photos'] ?? '4'))));
    $secondsPerPhoto = (float)str_replace(',', '.', (string)($params['seconds_per_photo'] ?? '2.0'));
    $secondsPerPhoto = max(0.8, min(3.0, $secondsPerPhoto));
    $overwrite = ((string)($params['overwrite'] ?? '1') !== '' && (string)($params['overwrite'] ?? '1') !== '0');

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/video_cover');

    $ffmpeg = supplier_products_db_video_cover_ffmpeg_path($cfg, $params);
    $log(
        "supplier_db create_video_cover: max_items={$maxItems}, source_photos={$sourcePhotos}, " .
        "size=1200x1600, fps=24, duration=8s, seconds_per_photo={$secondsPerPhoto}, transition=1.0, " .
        "format=mp4/h264, rendering=ffmpeg_filter_complex, motion=stable_product_soft_background_zoom, fallback=prepared_background_image2pipe, ozon_field=\"Озон.Видеообложка: ссылка\", overwrite=" . ($overwrite ? '1' : '0') .
        ", ffmpeg={$ffmpeg}\n"
    );

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');

    $jobs = [];
    $seenProducts = 0;
    $skippedNoPictures = 0;
    $skippedExisting = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $fields = (array)($fieldsByProduct[$productId] ?? []);
        $existingVideoCover = supplier_products_db_video_cover_existing_url($fields);
        if (!$overwrite && $existingVideoCover !== '') {
            $skippedExisting++;
            continue;
        }

        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        $sourcePictures = supplier_products_db_video_cover_source_pictures($pictures, $sourcePhotos);
        if (!$sourcePictures) {
            $skippedNoPictures++;
            continue;
        }

        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'source_pictures' => $sourcePictures,
            'existing_video_cover' => $existingVideoCover,
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 100 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log("scan: products_seen={$seenProducts}, jobs=" . count($jobs) . ", skipped_no_pictures={$skippedNoPictures}, skipped_existing={$skippedExisting}\n");

    $pdo = db();
    $results = [];
    $changedProducts = [];
    $done = 0;
    $totalJobs = max(1, count($jobs));
    foreach ($jobs as $offerId => $job) {
        $jobNo = $done + 1;
        ops_update_progress($opId, $done, $totalJobs, 'render', "video cover {$jobNo}/{$totalJobs} in progress offer={$offerId}");

        $status = 'ok';
        $err = '';
        $newUrl = '';
        $meta = [];
        $tmpVideo = '';
        try {
            $created = supplier_products_db_video_cover_create((array)($job['source_pictures'] ?? []), $cfg, [
                'ffmpeg_path' => (string)($params['ffmpeg_path'] ?? ''),
                'width' => 1200,
                'height' => 1600,
                'fps' => 24,
                'seconds_per_photo' => $secondsPerPhoto,
                'transition_sec' => 1.0,
                'jpeg_quality' => 88,
                'crf' => 22,
            ]);
            $tmpVideo = (string)($created['path'] ?? '');
            $meta = (array)($created['meta'] ?? []);
            $newUrl = supplier_products_db_video_cover_save_video($supplierId, (int)$job['product_id'], $tmpVideo, $cfg);
            supplier_products_db_video_cover_set_url($pdo, $supplierId, (int)$job['product_id'], $newUrl);
            $changedProducts[(int)$job['product_id']] = true;
            $log(
                "video cover created offer={$offerId}: renderer=" . (string)($meta['rendering_mode'] ?? '-') .
                ", render_ms=" . (int)($meta['render_elapsed_ms'] ?? 0) .
                ", size_bytes=" . (int)($meta['size_bytes'] ?? 0) . "\n"
            );
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            $log("VIDEO COVER ERROR offer={$offerId}: {$err}\n");
        } finally {
            if ($tmpVideo !== '' && is_file($tmpVideo)) {
                @unlink($tmpVideo);
            }
        }

        $results[$offerId] = [
            'status' => $status,
            'error' => $err,
            'new_url' => $newUrl,
            'ozon_field' => 'Озон.Видеообложка: ссылка',
            'existing_video_cover' => (string)($job['existing_video_cover'] ?? ''),
            'source_pictures' => array_values((array)($job['source_pictures'] ?? [])),
            'video_cover' => $meta,
        ];

        file_put_contents(
            $outDir . '/video_cover/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode($results[$offerId], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );

        $done++;
        ops_update_progress($opId, $done, $totalJobs, 'render', "video cover {$done}/{$totalJobs} processed offer={$offerId} status={$status}");
    }

    if (count($jobs) > 0) {
        ops_update_progress($opId, $done, $totalJobs, 'finalize', 'saving product changes');
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    foreach ($results as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
    }
    $renderElapsedMsTotal = 0;
    $videoSizeBytesTotal = 0;
    $renderingModes = [];
    foreach ($results as $row) {
        $videoMeta = is_array($row['video_cover'] ?? null) ? (array)$row['video_cover'] : [];
        $renderElapsedMsTotal += max(0, (int)($videoMeta['render_elapsed_ms'] ?? 0));
        $videoSizeBytesTotal += max(0, (int)($videoMeta['size_bytes'] ?? 0));
        $mode = trim((string)($videoMeta['rendering_mode'] ?? ''));
        if ($mode !== '') {
            $renderingModes[$mode] = true;
        }
    }
    $renderingMode = $renderingModes
        ? implode(', ', array_keys($renderingModes))
        : 'ffmpeg_filter_complex';

    ops_update_progress(
        $opId,
        count($jobs) > 0 ? $done : 1,
        count($jobs) > 0 ? $totalJobs : 1,
        'done',
        count($jobs) > 0 ? 'video covers completed' : 'No video cover jobs'
    );

    $report = [
        'title' => 'create_video_cover',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $totalProducts,
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'status_counts' => $statusCounts,
            'products_touched' => count($changedProducts),
            'skipped_no_pictures' => $skippedNoPictures,
            'skipped_existing' => $skippedExisting,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'render_elapsed_ms_total' => $renderElapsedMsTotal,
            'video_size_bytes_total' => $videoSizeBytesTotal,
            'rendering_mode' => $renderingMode,
            'cost' => 0.0,
            'cost_currency' => 'USD',
            'cost_label' => openai_format_cost(0.0, 'USD'),
            'cost_usd' => 0.0,
        ],
        'params_effective' => [
            'max_items' => (string)$maxItems,
            'source_photos' => (string)$sourcePhotos,
            'seconds_per_photo' => (string)$secondsPerPhoto,
            'target_duration_sec' => '8',
            'transition_sec' => '1.0',
            'fps' => '24',
            'final_size' => '1200x1600',
            'final_format' => 'mp4',
            'codec' => 'h264',
            'rendering_mode' => 'ffmpeg_filter_complex',
            'fallback_rendering_mode' => 'prepared_background_image2pipe',
            'background_mode' => 'ffmpeg_blurred_source',
            'motion_mode' => 'stable_product_soft_background_zoom',
            'crf' => '22',
            'ozon_field' => 'Озон.Видеообложка: ссылка',
            'plain_video_field_written' => '0',
            'uses_gpt' => '0',
            'overwrite' => $overwrite ? '1' : '0',
            'ffmpeg' => $ffmpeg,
        ],
        'results' => $results,
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'create_video_cover',
        'items' => [
            'Jobs: ' . count($jobs),
            'Products touched: ' . count($changedProducts),
            'Skipped no pictures: ' . $skippedNoPictures,
            'Skipped existing video cover: ' . $skippedExisting,
            'Errors: ' . (int)($statusCounts['error'] ?? 0),
            'Rendering: ' . $renderingMode,
            'Render time: ' . round($renderElapsedMsTotal / 1000, 2) . 's',
            'Ozon field: Озон.Видеообложка: ссылка',
            'Plain video field written: no',
            'Cost: ' . openai_format_cost(0.0, 'USD'),
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_gpt_generate_video_cover(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '1') !== '' && (string)($params['overwrite'] ?? '1') !== '0');
    $sourcePhotosLimit = max(1, min(4, (int)trim((string)($params['source_photos'] ?? '3'))));
    $defaultVideoModel = trim((string)($cfg['openai_video']['default_model'] ?? 'sora-2'));
    if ($defaultVideoModel === '') {
        $defaultVideoModel = 'sora-2';
    }
    $videoModel = strtolower(trim((string)($params['video_model'] ?? $defaultVideoModel)));
    if ($videoModel === '') {
        $videoModel = $defaultVideoModel;
    }
    $videoPricing = openai_video_pricing_for_model($cfg, $videoModel);
    if ((string)($videoPricing['source'] ?? 'unknown') === 'unknown') {
        throw new RuntimeException('Неизвестная Sora модель для расчета стоимости: ' . $videoModel);
    }
    $videoSize = supplier_products_db_sora_normalize_video_size($videoModel, (string)($params['video_size'] ?? '720x1280'));
    $requestedVideoSeconds = supplier_products_db_sora_normalize_video_seconds((string)($params['video_seconds'] ?? '8'));
    $videoDurationMode = trim((string)($params['video_duration_mode'] ?? 'slow_4_to_8'));
    if (!in_array($videoDurationMode, ['full', 'slow_4_to_8'], true)) {
        $videoDurationMode = 'slow_4_to_8';
    }
    $soraVideoSeconds = $requestedVideoSeconds;
    $finalVideoDurationSeconds = $requestedVideoSeconds;
    $slowdownFactor = 1.0;
    if ($videoDurationMode === 'slow_4_to_8') {
        $soraVideoSeconds = 4;
        $finalVideoDurationSeconds = 8;
        $slowdownFactor = 2.0;
    }
    $finalVideoSize = supplier_products_db_gpt_video_cover_final_size((string)($params['final_video_size'] ?? '1080x1440'));
    $finalVideoFps = max(24, min(30, (int)trim((string)($params['final_video_fps'] ?? '25'))));
    $finalVideoCrf = max(18, min(30, (int)trim((string)($params['final_video_crf'] ?? '23'))));
    $finalVideoMaxrateKbps = max(1200, min(9000, (int)trim((string)($params['final_video_maxrate_kbps'] ?? '3200'))));
    $pollIntervalSec = max(2, min(30, (int)trim((string)($params['poll_interval_sec'] ?? '10'))));
    $pollTimeoutSec = max(60, min(3600, (int)trim((string)($params['poll_timeout_sec'] ?? '900'))));
    $timeoutSec = max(30, min(600, (int)trim((string)($params['timeout_sec'] ?? '180'))));

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt_video_cover');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'video_cover_sora_ru.txt');
    $log(
        "supplier_db gpt_generate_video_cover: video_api=/videos, model={$videoModel}, max_items={$maxItems}, " .
        "size={$videoSize}, requested_seconds={$requestedVideoSeconds}, sora_seconds={$soraVideoSeconds}, " .
        "final_duration={$finalVideoDurationSeconds}, duration_mode={$videoDurationMode}, slowdown_factor={$slowdownFactor}, " .
        "input_reference=photo_cover_resized, source_photos={$sourcePhotosLimit}, " .
        "final_format=mp4/h264, final_size={$finalVideoSize}, final_fps={$finalVideoFps}, final_crf={$finalVideoCrf}, " .
        "final_maxrate={$finalVideoMaxrateKbps}k, final_audio=none, ozon_field=\"Озон.Видеообложка: ссылка\", " .
        "plain_video_field_written=0, overwrite=" . ($overwrite ? '1' : '0') . "\n"
    );
    $log("video pricing: " . openai_video_pricing_debug_string($videoPricing) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');

    $jobs = [];
    $seenProducts = 0;
    $skippedNoPictures = 0;
    $skippedNoVideoDesign = 0;
    $skippedExisting = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $fields = (array)($fieldsByProduct[$productId] ?? []);
        $existingVideoCover = supplier_products_db_video_cover_existing_url($fields);
        if (!$overwrite && $existingVideoCover !== '') {
            $skippedExisting++;
            continue;
        }

        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        $referencePicture = supplier_products_db_video_cover_reference_picture($pictures);
        if ($referencePicture === '') {
            $skippedNoPictures++;
            continue;
        }
        $sourcePictures = supplier_products_db_video_cover_source_pictures($pictures, $sourcePhotosLimit);
        if (!$sourcePictures) {
            $sourcePictures = [$referencePicture];
        }

        $categoryPayload = supplier_products_db_video_cover_category_payload($product, $fields);
        if (trim((string)($categoryPayload['video_cover_design'] ?? '')) === '') {
            $skippedNoVideoDesign++;
            continue;
        }

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $brand = trim((string)($context['brand'] ?? ($product['brand'] ?? '')));
        $features = supplier_products_db_video_cover_compact_features(supplier_products_db_product_feature_values($fields), 4);
        $shortName = supplier_products_db_standard_field_value_from_rows($fields, 'short_name');
        $productPayload = supplier_products_db_video_cover_product_payload($product, $fields, $context, $offerId, $shortName);

        $payload = [
            'product' => $productPayload,
            'category' => $categoryPayload,
            'features' => $features,
            'storyboard' => supplier_products_db_video_cover_storyboard_payload($categoryPayload, $productPayload, $features, $videoDurationMode, $soraVideoSeconds, $finalVideoDurationSeconds),
            'brand' => [
                'value' => $brand,
                'show' => !supplier_products_db_brand_is_empty_like($brand),
            ],
            'source_photo_context' => supplier_products_db_video_cover_source_photo_context($sourcePictures),
            'rules' => [
                'first_frame_from_input_reference' => true,
                'do_not_add_text' => true,
                'keep_existing_cover_text_readable' => true,
                'do_not_add_marketplace_logos_prices_discounts_qr_watermarks' => true,
                'do_not_change_product_identity' => true,
                'target_use' => 'marketplace_video_cover',
                'creative_direction' => 'premium_product_ad_not_slideshow',
                'required_storyboard' => ['hook', 'hero_motion', 'detail_reveal', 'final_packshot'],
                'avoid_slideshow' => true,
                'avoid_static_photo_crossfades' => true,
                'motion_required' => ['camera_orbit_or_dolly', 'parallax_depth', 'light_sweep', 'category_motion_graphics', 'detail_reveal'],
                'duration_mode' => $videoDurationMode,
                'sora_generated_seconds' => $soraVideoSeconds,
                'final_video_seconds' => $finalVideoDurationSeconds,
                'postprocess_slowdown_factor' => $slowdownFactor,
            ],
        ];

        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'reference_picture' => $referencePicture,
            'source_pictures' => $sourcePictures,
            'existing_video_cover' => $existingVideoCover,
            'payload' => $payload,
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 100 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log(
        "scan: products_seen={$seenProducts}, jobs=" . count($jobs) .
        ", skipped_no_pictures={$skippedNoPictures}, skipped_no_video_cover_design={$skippedNoVideoDesign}, skipped_existing={$skippedExisting}\n"
    );

    $clientConfig = $cfg['llm_providers']['openai'] ?? ($cfg['openai'] ?? []);
    if (count($jobs) > 0 && (!is_array($clientConfig) || trim((string)($clientConfig['api_key'] ?? '')) === '')) {
        throw new RuntimeException('OPENAI_API_KEY не настроен для генерации видео-обложек через Sora.');
    }
    $clientConfig['provider'] = 'openai';
    $clientConfig['api_format'] = 'responses';
    $clientConfig['model_prefix'] = '';
    $clientConfig['timeout_sec'] = $timeoutSec;
    $clientConfig['response_cache_enabled'] = false;
    $client = count($jobs) > 0 ? new OpenAIClient($clientConfig) : null;

    $pdo = db();
    $results = [];
    $changedProducts = [];
    $done = 0;
    $totalJobs = max(1, count($jobs));
    $videoGenerationCostTotal = 0.0;
    $startedVideoIds = [];
    $promptCount = 0;
    $promptCharsTotal = 0;
    $promptCharsMax = 0;
    $estimatedPromptTokensTotal = 0;
    $referenceImageBytesTotal = 0;

    foreach ($jobs as $offerId => $job) {
        $jobNo = $done + 1;
        ops_update_progress($opId, $done, $totalJobs, 'sora', "video cover {$jobNo}/{$totalJobs} starting offer={$offerId}");

        $status = 'ok';
        $err = '';
        $newUrl = '';
        $videoId = '';
        $rawStart = null;
        $rawFinal = null;
        $referenceMeta = [];
        $promptMeta = [
            'format' => '',
            'static_prefix_sha256' => '',
            'payload_sha256' => '',
            'prompt_chars' => 0,
            'estimated_prompt_tokens' => 0,
        ];
        $videoMeta = [];
        $jobCost = openai_video_generation_cost_breakdown($cfg, $videoModel, 0, $videoSize);
        $tmpVideo = '';
        $tmpFinalVideo = '';

        try {
            if (!$client instanceof OpenAIClient) {
                throw new RuntimeException('OpenAI client is not initialized.');
            }
            if (function_exists('ops_is_cancel_requested') && ops_is_cancel_requested($opId)) {
                throw new RuntimeException('Операция отменена пользователем.');
            }

            $referenceMeta = supplier_products_db_gpt_video_cover_reference_image((string)$job['reference_picture'], $cfg, $videoSize);
            $referenceImageBytesTotal += max(0, (int)($referenceMeta['size_bytes'] ?? 0));
            $promptFullMeta = supplier_products_db_gpt_video_cover_prompt_text($prompt, (array)($job['payload'] ?? []));
            $inputText = (string)($promptFullMeta['text'] ?? $prompt);
            $promptMeta = supplier_products_db_gpt_video_cover_prompt_public_meta($promptFullMeta);
            $promptCount++;
            $promptChars = max(0, (int)($promptMeta['prompt_chars'] ?? 0));
            $estimatedPromptTokens = max(0, (int)($promptMeta['estimated_prompt_tokens'] ?? 0));
            $promptCharsTotal += $promptChars;
            $promptCharsMax = max($promptCharsMax, $promptChars);
            $estimatedPromptTokensTotal += $estimatedPromptTokens;

            $rawStart = $client->createVideo(
                $videoModel,
                $inputText,
                [
                    'size' => $videoSize,
                    'seconds' => (string)$soraVideoSeconds,
                ],
                (string)($referenceMeta['bytes'] ?? ''),
                (string)($referenceMeta['mime'] ?? 'image/jpeg')
            );
            $videoId = trim((string)($rawStart['id'] ?? ''));
            if ($videoId === '') {
                throw new RuntimeException('OpenAI Videos API не вернул video id.');
            }
            $startedVideoIds[] = $videoId;
            $last = $rawStart;
            $pollStartedAt = time();
            while (in_array((string)($last['status'] ?? ''), ['queued', 'in_progress'], true)) {
                $progress = max(0, min(100, (int)($last['progress'] ?? 0)));
                ops_update_progress($opId, $done, $totalJobs, 'sora', "video {$jobNo}/{$totalJobs} {$offerId}: " . (string)($last['status'] ?? '') . " {$progress}%");
                if (function_exists('ops_is_cancel_requested') && ops_is_cancel_requested($opId)) {
                    throw new RuntimeException('Операция отменена пользователем.');
                }
                if ((time() - $pollStartedAt) > $pollTimeoutSec) {
                    throw new RuntimeException("Sora generation timeout after {$pollTimeoutSec}s, video_id={$videoId}");
                }
                sleep($pollIntervalSec);
                $last = $client->retrieveVideo($videoId);
            }
            $rawFinal = $last;
            $finalStatus = (string)($rawFinal['status'] ?? '');
            if ($finalStatus !== 'completed') {
                $apiError = '';
                if (is_array($rawFinal['error'] ?? null)) {
                    $apiError = trim((string)($rawFinal['error']['message'] ?? ''));
                }
                throw new RuntimeException('Sora generation failed status=' . ($finalStatus !== '' ? $finalStatus : 'unknown') . ($apiError !== '' ? ': ' . $apiError : ''));
            }

            $videoBytes = $client->downloadVideoContent($videoId, 'video');
            if ($videoBytes === '' || strlen($videoBytes) < 1024) {
                throw new RuntimeException('OpenAI Videos API вернул пустой MP4.');
            }
            $tmpBase = tempnam(sys_get_temp_dir(), 'ft_sora_video_cover_');
            if ($tmpBase === false) {
                throw new RuntimeException('Не удалось создать временный файл Sora MP4.');
            }
            $tmpVideo = $tmpBase . '.mp4';
            @unlink($tmpBase);
            if (@file_put_contents($tmpVideo, $videoBytes) === false) {
                throw new RuntimeException('Не удалось записать временный Sora MP4.');
            }
            @chmod($tmpVideo, 0664);

            $postprocessed = supplier_products_db_gpt_video_cover_postprocess_video($tmpVideo, $cfg, [
                'final_video_size' => $finalVideoSize,
                'final_video_fps' => $finalVideoFps,
                'final_video_crf' => $finalVideoCrf,
                'final_video_maxrate_kbps' => $finalVideoMaxrateKbps,
                'slowdown_factor' => $slowdownFactor,
                'target_duration_sec' => $finalVideoDurationSeconds,
                'pad_to_target_duration' => false,
                'postprocess_motion_strength' => 0.35,
            ]);
            $tmpFinalVideo = (string)($postprocessed['path'] ?? '');
            if ($tmpFinalVideo === '' || !is_file($tmpFinalVideo)) {
                throw new RuntimeException('Не найден финальный MP4 после обработки Sora.');
            }

            $jobCost = openai_video_generation_cost_breakdown($cfg, $videoModel, $soraVideoSeconds, $videoSize);
            $videoGenerationCostTotal += (float)($jobCost['cost'] ?? 0.0);
            $newUrl = supplier_products_db_video_cover_save_video($supplierId, (int)$job['product_id'], $tmpFinalVideo, $cfg);
            supplier_products_db_video_cover_set_url($pdo, $supplierId, (int)$job['product_id'], $newUrl);
            $changedProducts[(int)$job['product_id']] = true;
            $videoMeta = [
                'video_id' => $videoId,
                'model' => (string)($rawFinal['model'] ?? $videoModel),
                'size' => (string)($rawFinal['size'] ?? $videoSize),
                'seconds' => (string)($rawFinal['seconds'] ?? (string)$soraVideoSeconds),
                'requested_seconds' => $requestedVideoSeconds,
                'sora_generated_seconds' => $soraVideoSeconds,
                'final_video_seconds' => $finalVideoDurationSeconds,
                'duration_mode' => $videoDurationMode,
                'slowdown_factor' => $slowdownFactor,
                'status' => $finalStatus,
                'progress' => (int)($rawFinal['progress'] ?? 100),
                'downloaded_bytes' => strlen($videoBytes),
                'final_file_size_bytes' => (int)($postprocessed['file_size_bytes'] ?? 0),
                'final_processing' => array_diff_key($postprocessed, ['path' => true]),
                'input_reference' => array_diff_key($referenceMeta, ['bytes' => true]),
            ];
            $log(
                "SORA VIDEO COVER OK offer={$offerId}: video_id={$videoId}, sora_size={$videoSize}, final_size={$finalVideoSize}, " .
                "sora_seconds={$soraVideoSeconds}, final_duration={$finalVideoDurationSeconds}, duration_mode={$videoDurationMode}, " .
                "raw_bytes=" . strlen($videoBytes) . ", final_bytes=" . (int)($postprocessed['file_size_bytes'] ?? 0) .
                ", cost=" . (string)($jobCost['cost_label'] ?? '') . "\n"
            );
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            $log("SORA VIDEO COVER ERROR offer={$offerId}: {$err}\n");
        } finally {
            if ($tmpVideo !== '' && is_file($tmpVideo)) {
                @unlink($tmpVideo);
            }
            if ($tmpFinalVideo !== '' && is_file($tmpFinalVideo)) {
                @unlink($tmpFinalVideo);
            }
        }

        $results[$offerId] = [
            'status' => $status,
            'error' => $err,
            'new_url' => $newUrl,
            'ozon_field' => 'Озон.Видеообложка: ссылка',
            'plain_video_field_written' => 0,
            'existing_video_cover' => (string)($job['existing_video_cover'] ?? ''),
            'reference_picture' => (string)($job['reference_picture'] ?? ''),
            'source_pictures' => array_values((array)($job['source_pictures'] ?? [])),
            'prompt' => $promptMeta,
            'video_cover' => $videoMeta,
            'video_generation_cost' => $jobCost,
            'video_id' => $videoId,
        ];

        file_put_contents(
            $outDir . '/gpt_video_cover/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'status' => $status,
                'error' => $err,
                'new_url' => $newUrl,
                'ozon_field' => 'Озон.Видеообложка: ссылка',
                'reference_picture' => (string)($job['reference_picture'] ?? ''),
                'source_pictures' => array_values((array)($job['source_pictures'] ?? [])),
                'payload' => $job['payload'] ?? [],
                'prompt' => $promptMeta,
                'video_cover' => $videoMeta,
                'video_generation_cost' => $jobCost,
                'raw_start' => supplier_products_db_gpt_video_cover_sanitize_response($rawStart),
                'raw_final' => supplier_products_db_gpt_video_cover_sanitize_response($rawFinal),
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );

        $done++;
        ops_update_progress($opId, $done, $totalJobs, 'sora', "video cover {$done}/{$totalJobs} processed offer={$offerId} status={$status}");
    }

    if (count($jobs) > 0) {
        ops_update_progress($opId, $done, $totalJobs, 'finalize', 'saving product changes');
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    $finalFileSizeTotal = 0;
    foreach ($results as $row) {
        $rowStatus = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$rowStatus])) {
            $statusCounts[$rowStatus] = 0;
        }
        $statusCounts[$rowStatus]++;
        $videoRow = is_array($row['video_cover'] ?? null) ? (array)$row['video_cover'] : [];
        $finalFileSizeTotal += max(0, (int)($videoRow['final_file_size_bytes'] ?? 0));
    }

    ops_update_progress(
        $opId,
        count($jobs) > 0 ? $done : 1,
        count($jobs) > 0 ? $totalJobs : 1,
        'done',
        count($jobs) > 0 ? 'Sora video covers completed' : 'No Sora video cover jobs'
    );

    $videoGenerationCostTotal = round($videoGenerationCostTotal, 6);
    $videoCurrency = strtoupper(trim((string)($videoPricing['currency'] ?? 'USD'))) ?: 'USD';
    $costLabel = openai_format_cost($videoGenerationCostTotal, $videoCurrency);
    $report = [
        'title' => 'gpt_generate_video_cover',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $totalProducts,
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'status_counts' => $statusCounts,
            'products_touched' => count($changedProducts),
            'skipped_no_pictures' => $skippedNoPictures,
            'skipped_no_video_cover_design' => $skippedNoVideoDesign,
            'skipped_existing' => $skippedExisting,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'video_model' => $videoModel,
            'video_size' => $videoSize,
            'video_duration_mode' => $videoDurationMode,
            'requested_video_seconds' => $requestedVideoSeconds,
            'sora_generated_seconds' => $soraVideoSeconds,
            'final_video_seconds' => $finalVideoDurationSeconds,
            'slowdown_factor' => $slowdownFactor,
            'final_video_size' => $finalVideoSize,
            'final_video_fps' => $finalVideoFps,
            'final_video_crf' => $finalVideoCrf,
            'final_video_maxrate_kbps' => $finalVideoMaxrateKbps,
            'final_video_audio' => 'none',
            'final_file_size_bytes_total' => $finalFileSizeTotal,
            'final_file_size_mb_total' => round($finalFileSizeTotal / 1048576, 3),
            'input_reference_bytes_total' => $referenceImageBytesTotal,
            'input_reference_mb_total' => round($referenceImageBytesTotal / 1048576, 3),
            'prompt_count' => $promptCount,
            'prompt_chars_total' => $promptCharsTotal,
            'prompt_chars_avg' => $promptCount > 0 ? (int)round($promptCharsTotal / $promptCount) : 0,
            'prompt_chars_max' => $promptCharsMax,
            'estimated_prompt_tokens_total' => $estimatedPromptTokensTotal,
            'estimated_prompt_tokens_avg' => $promptCount > 0 ? (int)round($estimatedPromptTokensTotal / $promptCount) : 0,
            'started_video_ids' => $startedVideoIds,
            'input_tokens' => 0,
            'cached_input_tokens' => 0,
            'output_tokens' => 0,
            'video_generation_cost' => $videoGenerationCostTotal,
            'video_generation_cost_label' => $costLabel,
            'video_generation_cost_currency' => $videoCurrency,
            'cost' => $videoGenerationCostTotal,
            'cost_currency' => $videoCurrency,
            'cost_label' => $costLabel,
            'cost_usd' => $videoGenerationCostTotal,
            'video_generation_pricing' => [
                'requested_model' => (string)($videoPricing['requested_model'] ?? $videoModel),
                'matched_model' => (string)($videoPricing['matched_model'] ?? $videoModel),
                'source' => (string)($videoPricing['source'] ?? 'unknown'),
                'video_per_second' => (float)($videoPricing['video_per_second'] ?? 0.0),
                'video_1024p_per_second' => isset($videoPricing['video_1024p_per_second']) ? (float)$videoPricing['video_1024p_per_second'] : null,
                'video_1080p_per_second' => isset($videoPricing['video_1080p_per_second']) ? (float)$videoPricing['video_1080p_per_second'] : null,
            ],
        ],
        'params_effective' => [
            'video_model' => $videoModel,
            'max_items' => (string)$maxItems,
            'video_size' => $videoSize,
            'video_duration_mode' => $videoDurationMode,
            'requested_video_seconds' => (string)$requestedVideoSeconds,
            'sora_generated_seconds' => (string)$soraVideoSeconds,
            'final_video_seconds' => (string)$finalVideoDurationSeconds,
            'slowdown_factor' => (string)$slowdownFactor,
            'final_video_size' => $finalVideoSize,
            'final_video_fps' => (string)$finalVideoFps,
            'final_video_crf' => (string)$finalVideoCrf,
            'final_video_maxrate_kbps' => (string)$finalVideoMaxrateKbps,
            'final_video_audio' => 'none',
            'source_photos' => (string)$sourcePhotosLimit,
            'poll_interval_sec' => (string)$pollIntervalSec,
            'poll_timeout_sec' => (string)$pollTimeoutSec,
            'timeout_sec' => (string)$timeoutSec,
            'input_reference' => 'photo_cover_resized_to_video_size',
            'ozon_field' => 'Озон.Видеообложка: ссылка',
            'plain_video_field_written' => '0',
            'overwrite' => $overwrite ? '1' : '0',
        ],
        'results' => $results,
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_generate_video_cover',
        'items' => [
            'Jobs: ' . count($jobs),
            'Products touched: ' . count($changedProducts),
            'Skipped no pictures: ' . $skippedNoPictures,
            'Skipped no video cover design: ' . $skippedNoVideoDesign,
            'Skipped existing video cover: ' . $skippedExisting,
            'Errors: ' . (int)($statusCounts['error'] ?? 0),
            'Video API: /videos',
            'Video model: ' . $videoModel,
            'Duration mode: ' . $videoDurationMode,
            'Sora size: ' . $videoSize,
            'Sora generated seconds: ' . $soraVideoSeconds,
            'Final video seconds: ' . $finalVideoDurationSeconds,
            'Slowdown factor: ' . $slowdownFactor,
            'Final MP4 size: ' . $finalVideoSize,
            'Final FPS: ' . $finalVideoFps,
            'Final maxrate: ' . $finalVideoMaxrateKbps . 'k',
            'Final audio: none',
            'Input reference: photo-cover resized to ' . $videoSize,
            'Prompt avg chars: ' . ($promptCount > 0 ? (int)round($promptCharsTotal / $promptCount) : 0),
            'Estimated prompt tokens total: ' . $estimatedPromptTokensTotal,
            'Input reference total: ' . round($referenceImageBytesTotal / 1048576, 3) . ' MB',
            'Ozon field: Озон.Видеообложка: ссылка',
            'Plain video field written: no',
            'Stored MP4 total: ' . round($finalFileSizeTotal / 1048576, 3) . ' MB',
            'Cost: ' . $costLabel,
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_create_product_specs_photo(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $maxChars = max(1, min(12, (int)trim((string)($params['max_chars'] ?? '8'))));
    $overwrite = ((string)($params['overwrite'] ?? '1') !== '' && (string)($params['overwrite'] ?? '1') !== '0');

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/specs_photo');

    $log("supplier_db create_product_specs_photo: max_items={$maxItems}, max_chars={$maxChars}, final_size=1200x1600, final_format=jpeg, final_quality=92, overwrite=" . ($overwrite ? '1' : '0') . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');

    $jobs = [];
    $seenProducts = 0;
    $skippedExisting = 0;
    $skippedNoTemplate = 0;
    $skippedNoCharacteristics = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $pictures = supplier_products_normalize_picture_urls(supplier_products_decode_json_array($product['pictures_json'] ?? null));
        if (!$overwrite && supplier_products_db_specs_photo_has_generated($pictures)) {
            $skippedExisting++;
            continue;
        }
        $basePictures = $overwrite ? supplier_products_db_specs_photo_without_existing($pictures) : $pictures;
        $fields = $fieldsByProduct[$productId] ?? [];
        $templateInfo = supplier_products_db_specs_photo_template_for_product($product, $fields, $cfg);
        if (!$templateInfo) {
            $skippedNoTemplate++;
            continue;
        }
        $items = supplier_products_db_specs_photo_characteristics($product, $fields, $maxChars);
        if (!$items) {
            $skippedNoCharacteristics++;
            continue;
        }

        $brand = supplier_products_db_specs_photo_product_brand($product, $fields);

        $jobs[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'pictures' => $basePictures,
            'brand' => $brand,
            'items' => $items,
            'template_info' => $templateInfo,
        ];

        if ($maxItems > 0 && count($jobs) >= $maxItems) {
            break;
        }
        if ($seenProducts % 100 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log(
        "scan: products_seen={$seenProducts}, jobs=" . count($jobs) .
        ", skipped_existing={$skippedExisting}, skipped_no_template={$skippedNoTemplate}, " .
        "skipped_no_characteristics={$skippedNoCharacteristics}\n"
    );

    $results = [];
    $changedProducts = [];
    $done = 0;
    $totalJobs = max(1, count($jobs));
    foreach ($jobs as $offerId => $job) {
        $jobNo = $done + 1;
        ops_update_progress($opId, $done, $totalJobs, 'render', "specs photo {$jobNo}/{$totalJobs} in progress offer={$offerId}");

        $status = 'ok';
        $err = '';
        $newUrl = '';
        $meta = [];
        try {
            $templateInfo = (array)($job['template_info'] ?? []);
            $template = is_array($templateInfo['template'] ?? null) ? $templateInfo['template'] : [];
            $created = supplier_products_db_specs_photo_create($template, (string)($job['brand'] ?? ''), (array)($job['items'] ?? []), $cfg, 1200, 1600, 92);
            $meta = (array)($created['meta'] ?? []);
            $newUrl = supplier_products_db_specs_photo_save_image($supplierId, (int)$job['product_id'], (string)($created['bytes'] ?? ''), $cfg);
            $pictures = supplier_products_db_specs_photo_pictures_with_new_image((array)($job['pictures'] ?? []), $newUrl);
            supplier_products_update_pictures((int)$job['product_id'], $pictures, $cfg);
            $changedProducts[(int)$job['product_id']] = true;
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            $log("PRODUCT SPECS PHOTO ERROR offer={$offerId}: {$err}\n");
        }

        $results[$offerId] = [
            'status' => $status,
            'error' => $err,
            'new_url' => $newUrl,
            'brand' => (string)($job['brand'] ?? ''),
            'items' => array_values((array)($job['items'] ?? [])),
            'template' => [
                'source' => (string)($job['template_info']['source'] ?? ''),
                'category_value' => (string)($job['template_info']['category_value'] ?? ''),
                'url' => (string)($job['template_info']['template']['url'] ?? ''),
                'relative_path' => (string)($job['template_info']['template']['relative_path'] ?? ''),
            ],
            'specs_photo' => $meta,
        ];

        file_put_contents(
            $outDir . '/specs_photo/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode($results[$offerId], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT)
        );

        $done++;
        ops_update_progress($opId, $done, $totalJobs, 'render', "specs photo {$done}/{$totalJobs} processed offer={$offerId} status={$status}");
    }

    if (count($jobs) > 0) {
        ops_update_progress($opId, $done, $totalJobs, 'finalize', 'saving product changes');
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId, false);
    $statusCounts = ['ok' => 0, 'error' => 0];
    foreach ($results as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
    }

    ops_update_progress(
        $opId,
        count($jobs) > 0 ? $done : 1,
        count($jobs) > 0 ? $totalJobs : 1,
        'done',
        count($jobs) > 0 ? 'product specs photos completed' : 'No specs photo jobs'
    );

    $report = [
        'title' => 'create_product_specs_photo',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $totalProducts,
            'products_seen' => $seenProducts,
            'jobs' => count($jobs),
            'status_counts' => $statusCounts,
            'products_touched' => count($changedProducts),
            'skipped_existing' => $skippedExisting,
            'skipped_no_template' => $skippedNoTemplate,
            'skipped_no_characteristics' => $skippedNoCharacteristics,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'cost' => 0.0,
            'cost_currency' => 'USD',
            'cost_label' => openai_format_cost(0.0, 'USD'),
            'cost_usd' => 0.0,
        ],
        'params_effective' => [
            'max_items' => (string)$maxItems,
            'max_chars' => (string)$maxChars,
            'overwrite' => $overwrite ? '1' : '0',
            'final_size' => '1200x1600',
            'final_format' => 'jpeg',
            'final_quality' => '92',
            'uses_gpt' => '0',
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'create_product_specs_photo',
        'items' => [
            'Jobs: ' . count($jobs),
            'Products touched: ' . count($changedProducts),
            'Skipped existing: ' . $skippedExisting,
            'Skipped no category template: ' . $skippedNoTemplate,
            'Skipped no useful characteristics: ' . $skippedNoCharacteristics,
            'Errors: ' . (int)($statusCounts['error'] ?? 0),
            'Cost: ' . openai_format_cost(0.0, 'USD'),
        ],
        'metrics' => $report['summary'],
    ];
    return $outputs;
}

function supplier_products_db_op_gpt_fill_hashtags(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $model = LLM::modelForOp($cfg, $params);
    $maxItems = max(0, (int)trim((string)($params['max_items'] ?? '0')));
    $overwrite = ((string)($params['overwrite'] ?? '0') !== '' && (string)($params['overwrite'] ?? '0') !== '0');

    $outDir = op_output_dir($cfg, $datasetId, $opId);
    ensure_dir($outDir);
    ensure_dir($outDir . '/gpt');

    $prompt = PromptTemplates::load(__DIR__ . '/llm/prompts', 'fill_hashtags_ru.txt');
    $log("supplier_db gpt_fill_hashtags: model={$model}, max_items={$maxItems}, overwrite=" . ($overwrite ? '1' : '0') . "\n");
    $log("pricing: " . openai_pricing_debug_string(openai_pricing_for_model($cfg, $model)) . "\n");

    $products = supplier_products_db_load_products($supplierId, $params, 0);
    $totalProducts = count($products);
    ops_update_progress($opId, 0, max(1, $totalProducts), 'scan', 'scanning products');
    $fieldsByProduct = supplier_products_db_fields_for_products(supplier_products_db_product_ids($products));

    $candidates = [];
    $seenProducts = 0;
    foreach ($products as $product) {
        $seenProducts++;
        $productId = (int)($product['id'] ?? 0);
        $offerId = trim((string)($product['offer_id'] ?? ''));
        if ($productId <= 0 || $offerId === '') {
            continue;
        }

        $fields = $fieldsByProduct[$productId] ?? [];
        $hashtagsExisting = supplier_products_db_product_tag_value($fields, ['hashtags']);
        if (!$overwrite && trim($hashtagsExisting) !== '') {
            continue;
        }

        $ozonCategory = supplier_products_db_product_category_value($product, $fields, 'ozon');
        $wbCategory = supplier_products_db_product_category_value($product, $fields, 'wildberries');
        if ($ozonCategory === '' && $wbCategory === '') {
            continue;
        }

        $cat = ft_load_combined_marketplace_category_context($ozonCategory, $wbCategory, false);
        if (!$cat) {
            continue;
        }

        $context = supplier_products_db_product_prompt_context_from_fields($fields);
        $candidates[$offerId] = [
            'product_id' => $productId,
            'offer_id' => $offerId,
            'ozon_category' => $ozonCategory,
            'wb_category' => $wbCategory,
            'hashtags_existing' => $hashtagsExisting,
            'product' => [
                'offer_id' => $offerId,
                'vendorCode' => (string)($product['vendor_code'] ?? ''),
                'name' => (string)($product['name'] ?? ''),
                'brand' => (string)($context['brand'] ?? ($product['brand'] ?? '')),
                'vendor' => (string)($context['vendor'] ?? ''),
                'model' => (string)($context['model'] ?? ''),
                'description' => supplier_products_db_description_snippet((string)($product['description_html'] ?? ''), 3500),
                'params' => supplier_products_db_product_params_payload($fields),
            ],
            'category' => [
                'code' => (string)$cat['code'],
                'name' => (string)$cat['name'],
                'full_path' => (string)$cat['full_path'],
                'description' => (string)$cat['description'],
                'typical_goods' => (string)$cat['typical_goods'],
                'features' => (string)$cat['features'],
                'marketplace_contexts' => $cat['marketplace_contexts'] ?? [],
            ],
        ];

        if ($maxItems > 0 && count($candidates) >= $maxItems) {
            break;
        }
        if ($seenProducts % 250 === 0) {
            ops_update_progress($opId, $seenProducts, max(1, $totalProducts), 'scan', 'scanning products');
        }
    }

    $log("scan: products_seen={$seenProducts}, candidates=" . count($candidates) . "\n");

    $tokensInTotal = 0;
    $tokensOutTotal = 0;
    $tokensCachedTotal = 0;
    $costUsdTotal = 0.0;
    $gptResults = [];
    $gptDone = 0;
    $gptTotal = max(1, count($candidates));
    $firstLlmError = '';
    $client = count($candidates) > 0 ? LLM::client($cfg, $model) : null;
    $bannedHashtags = [
        '#цена' => true,
        '#купить' => true,
        '#заказать' => true,
        '#скидка' => true,
        '#акция' => true,
        '#доставка' => true,
    ];

    foreach ($candidates as $offerId => $cand) {
        $gptDone++;
        ops_update_progress($opId, $gptDone, $gptTotal, 'gpt', "GPT {$gptDone}/{$gptTotal} offer={$offerId}");

        $payload = [
            'category' => $cand['category'],
            'product' => $cand['product'],
        ];
        $inputJson = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($inputJson === false) {
            $inputJson = '{"product":{},"category":{}}';
        }

        $status = 'ok';
        $err = '';
        $hashtagsFinal = '';
        $rawText = '';
        $raw = null;
        $usage = ['input' => 0, 'cached_input' => 0, 'output' => 0];

        try {
            $res = $client->generateText(
                $model,
                "Return a json object only.\n\njson:\n" . $inputJson,
                $prompt,
                [
                    'prompt_cache_key' => 'fill_hashtags:' . substr(hash('sha256', json_encode([
                        'category' => $cand['category'],
                    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: ''), 0, 48),
                    'text' => ['format' => ['type' => 'json_object']],
                ]
            );
            $rawText = (string)($res['output_text'] ?? '');
            $raw = is_array($res['raw'] ?? null) ? $res['raw'] : null;
            $usage = supplier_products_db_extract_openai_usage($raw);
            $tokensInTotal += (int)$usage['input'];
            $tokensOutTotal += (int)$usage['output'];
            $tokensCachedTotal += (int)$usage['cached_input'];
            $costUsdTotal += openai_cost_usd($cfg, $model, (int)$usage['input'], (int)$usage['cached_input'], (int)$usage['output']);

            $obj = supplier_products_db_extract_json_object($rawText);
            $rawTags = $obj['hashtags'] ?? [];
            if (is_string($rawTags)) {
                $items = [$rawTags];
            } elseif (is_array($rawTags)) {
                $items = $rawTags;
            } else {
                $items = [];
            }

            $uniq = [];
            $out = [];
            foreach ($items as $item) {
                $s = trim((string)$item);
                if ($s === '') {
                    continue;
                }
                $parts = [];
                if (str_contains($s, '#') && preg_match_all('~#[\p{L}\p{N}_-]+~u', $s, $m)) {
                    $parts = $m[0];
                } else {
                    $parts = preg_split('~[\s,;]+~u', $s) ?: [];
                }
                foreach ($parts as $part) {
                    $tag = supplier_products_db_normalize_hashtag((string)$part);
                    if ($tag === '' || isset($uniq[$tag]) || isset($bannedHashtags[$tag])) {
                        continue;
                    }
                    $uniq[$tag] = true;
                    $out[] = $tag;
                    if (count($out) >= 15) {
                        break 2;
                    }
                }
            }
            $hashtagsFinal = implode(', ', $out);
        } catch (Throwable $e) {
            $status = 'error';
            $err = $e->getMessage();
            if ($firstLlmError === '') {
                $firstLlmError = $err;
            }
        }

        $gptResults[$offerId] = [
            'status' => $status,
            'error' => $err,
            'hashtags' => $hashtagsFinal,
        ];

        file_put_contents(
            $outDir . '/gpt/' . preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $offerId) . '.json',
            json_encode([
                'offer_id' => $offerId,
                'ozon_category' => $cand['ozon_category'],
                'wb_category' => $cand['wb_category'],
                'status' => $status,
                'error' => $err,
                'payload' => $payload,
                'gpt_output_text' => $rawText,
                'final_hashtags' => $hashtagsFinal,
                'usage' => $usage,
                'raw' => $raw,
            ], JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT)
        );
    }

    $pdo = db();
    $changedProducts = [];
    $offersTouched = 0;
    $offersWithHashtags = 0;
    foreach ($gptResults as $offerId => $result) {
        $hashtags = trim((string)($result['hashtags'] ?? ''));
        if (($result['status'] ?? '') !== 'ok' || $hashtags === '') {
            continue;
        }
        $productId = (int)($candidates[$offerId]['product_id'] ?? 0);
        if ($productId <= 0) {
            continue;
        }
        if (supplier_products_db_set_tag_field($pdo, $supplierId, $productId, ['hashtags'], 'hashtags', $hashtags)) {
            $changedProducts[$productId] = true;
            $offersTouched++;
        }
        $offersWithHashtags++;
    }

    $dataset = supplier_products_db_finish_changed_products($supplierId, array_keys($changedProducts), $cfg, $opId);
    $statusCounts = ['ok' => 0, 'error' => 0];
    foreach ($gptResults as $row) {
        $status = (string)($row['status'] ?? '');
        if (!isset($statusCounts[$status])) {
            $statusCounts[$status] = 0;
        }
        $statusCounts[$status]++;
    }
    supplier_products_db_fail_if_llm_unavailable(
        'gpt_fill_hashtags',
        count($candidates),
        (int)($statusCounts['error'] ?? 0),
        $tokensInTotal,
        $tokensOutTotal,
        $firstLlmError
    );

    $costUsdTotal = round($costUsdTotal, 6);
    $costLabel = supplier_products_db_cost_label($cfg, $model, $costUsdTotal);
    $report = [
        'title' => 'gpt_fill_hashtags',
        'storage' => 'supplier_products_db',
        'summary' => [
            'products_total' => $totalProducts,
            'products_seen' => $seenProducts,
            'candidates' => count($candidates),
            'gpt_status_counts' => $statusCounts,
            'products_touched' => $offersTouched,
            'products_with_hashtags' => $offersWithHashtags,
            'scope' => empty($params['offer_ids']) ? 'all' : 'selected',
            'selected_requested' => count((array)($params['offer_ids'] ?? [])),
            'usage' => [
                'input_tokens' => $tokensInTotal,
                'cached_input_tokens' => $tokensCachedTotal,
                'output_tokens' => $tokensOutTotal,
            ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
        ],
        'params_effective' => [
            'model' => $model,
            'max_items' => (string)$maxItems,
            'overwrite' => $overwrite ? '1' : '0',
        ],
        'dataset' => $dataset,
    ];

    $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
    $outputs['summary_json_inline'] = [
        'title' => 'gpt_fill_hashtags',
        'items' => [
            'Candidates: ' . count($candidates),
            'Products touched: ' . $offersTouched,
            'Products with hashtags: ' . $offersWithHashtags,
            'Tokens in: ' . $tokensInTotal,
            'Tokens cached in: ' . $tokensCachedTotal,
            'Tokens out: ' . $tokensOutTotal,
            'Cost: ' . $costLabel,
        ],
        'metrics' => [
            'candidates' => count($candidates),
            'offers_touched' => $offersTouched,
            'offers_with_hashtags' => $offersWithHashtags,
            'inplace' => 1,
            'updated_dataset_id' => $datasetId,
            'tokens_in' => $tokensInTotal,
            'tokens_cached_in' => $tokensCachedTotal,
            'tokens_out' => $tokensOutTotal,
        ] + supplier_products_db_cost_fields($cfg, $model, $costUsdTotal),
    ];
    return $outputs;
}

function supplier_products_db_import_param_bool(array $params, string $key): bool
{
    $value = $params[$key] ?? null;
    if (is_bool($value)) {
        return $value;
    }
    return in_array(strtolower(trim((string)$value)), ['1', 'true', 'yes', 'on'], true);
}

function supplier_products_db_import_selected_ids(array $params): array
{
    $raw = $params['selected_offer_ids'] ?? ($params['offer_ids'] ?? []);
    if (is_string($raw)) {
        $decoded = json_decode(trim($raw), true);
        $raw = is_array($decoded) ? $decoded : preg_split('/[\r\n,]+/', $raw);
    }
    if (!is_array($raw)) {
        return [];
    }
    return array_values(array_unique(array_filter(array_map(
        static fn($value): string => trim((string)$value),
        $raw
    ), static fn($value): bool => $value !== '')));
}

function supplier_products_db_import_source_data(
    int $datasetId,
    int $supplierId,
    array $supplier,
    array $cfg,
    array $params,
    string $action,
    array $selectedIds,
    callable $progress,
    callable $log
): array {
    $source = trim((string)($params['source'] ?? ''));
    if ($source === '' || !in_array($source, supplier_marketplace_import_sources(), true)) {
        throw new RuntimeException('Выбери источник импорта.');
    }

    $sourceUrl = '';
    $sourceData = null;
    $cleanupPaths = [];

    $progress(1, 100, 'source', 'Готовлю источник импорта');

    try {
        if ($source === 'supplier_feed') {
            $sourceUrl = trim((string)($supplier['feed_url'] ?? ''));
            if ($sourceUrl === '') {
                throw new RuntimeException('У поставщика не заполнена ссылка на источник данных.');
            }
            $download = ozon_price_feed_fetch_remote_xml($sourceUrl, (int)($cfg['limits']['max_upload_bytes'] ?? 200_000_000));
            $path = (string)$download['path'];
            $sourceUrl = (string)($download['final_url'] ?? $sourceUrl);
            $cleanupPaths[] = $path;
            $sourceData = supplier_import_source_data_from_file($supplierId, $path, basename(parse_url($sourceUrl, PHP_URL_PATH) ?: 'source.xml'), $cfg);
        } elseif ($source === 'url') {
            $feedUrl = trim((string)($params['feed_url'] ?? ''));
            if ($feedUrl === '') {
                throw new RuntimeException('Укажи ссылку на фид.');
            }
            $download = ozon_price_feed_fetch_remote_xml($feedUrl, (int)($cfg['limits']['max_upload_bytes'] ?? 200_000_000));
            $path = (string)$download['path'];
            $sourceUrl = (string)($download['final_url'] ?? $feedUrl);
            $cleanupPaths[] = $path;
            $sourceData = supplier_import_source_data_from_file($supplierId, $path, basename(parse_url($sourceUrl, PHP_URL_PATH) ?: 'source.xml'), $cfg);
        } elseif ($source === 'upload') {
            $storedFile = trim((string)($params['stored_file'] ?? ''));
            $storedFileName = trim((string)($params['stored_file_name'] ?? ''));
            $path = supplier_import_stored_source_path($storedFile, $cfg);
            $sourceUrl = $storedFileName !== '' ? $storedFileName : $storedFile;
            $sourceData = supplier_import_source_data_from_file($supplierId, $path, $sourceUrl, $cfg);
        } elseif (supplier_marketplace_import_is_marketplace_source($source)) {
            $connectionId = $source === 'ozon_account'
                ? (int)($params['ozon_connection_id'] ?? 0)
                : (int)($params['wb_connection_id'] ?? 0);
            $sourceScope = in_array($action, ['quick_prices_stock', 'quick_dimensions'], true)
                ? trim((string)($params['quick_scope'] ?? 'all'))
                : trim((string)($params['scope'] ?? 'all'));
            if (in_array($action, ['replace_catalog', 'delete_stale'], true)) {
                $sourceScope = 'all';
            }
            if ($action === 'import' && trim((string)($params['mode'] ?? 'add_update')) === 'add_only') {
                $sourceScope = 'all';
            }
            $sourceUrl = supplier_marketplace_import_label($source);
            $sourceData = supplier_marketplace_import_source_data(
                $datasetId,
                $supplierId,
                $source,
                $connectionId,
                $cfg,
                [
                    'scope' => in_array($sourceScope, ['all', 'selected'], true) ? $sourceScope : 'all',
                    'selected_offer_ids' => $selectedIds,
                    'progress' => static function (int $done, int $total, string $stage, string $message) use ($progress): void {
                        $scaled = 1 + (int)round((min($done, max(1, $total)) / max(1, $total)) * 18);
                        $progress($scaled, 100, $stage, $message);
                    },
                ]
            );
        }

        if (!is_array($sourceData)) {
            throw new RuntimeException('Не удалось подготовить источник импорта.');
        }

        $log('source: ' . supplier_marketplace_import_label($source) . ', records=' . count((array)($sourceData['records'] ?? [])) . "\n");
        return [$source, $sourceUrl, $sourceData, $cleanupPaths];
    } catch (Throwable $e) {
        foreach ($cleanupPaths as $pathToClean) {
            if (is_string($pathToClean) && $pathToClean !== '' && is_file($pathToClean)) {
                @unlink($pathToClean);
            }
        }
        throw $e;
    }
}

function supplier_products_db_op_import_catalog(array $cfg, array $ds, int $opId, array $params, callable $log): array
{
    $datasetId = (int)($ds['id'] ?? 0);
    $supplierId = supplier_products_supplier_id_for_dataset($datasetId, $cfg);
    if ($supplierId <= 0) {
        throw new RuntimeException('DB-датасет поставщика не найден.');
    }

    $supplier = suppliers_get($supplierId, $cfg);
    if (!is_array($supplier)) {
        throw new RuntimeException('Поставщик не найден.');
    }

    $action = trim((string)($params['import_action'] ?? 'import'));
    if (!in_array($action, ['import', 'quick_prices_stock', 'quick_dimensions', 'replace_catalog', 'delete_stale', 'remap_offer_ids', 'remap_wb_vendor_codes'], true)) {
        throw new RuntimeException('Неподдерживаемое действие импорта.');
    }

    $progress = static function (int $done, int $total, string $stage, string $message) use ($opId): void {
        ops_update_progress($opId, max(0, min($done, $total)), max(1, $total), $stage, $message);
    };

    $selectedIds = supplier_products_db_import_selected_ids($params);
    $log("supplier_db import_catalog: dataset={$datasetId}, supplier={$supplierId}, action={$action}, selected_offers=" . count($selectedIds) . "\n");
    $progress(0, 100, 'queued', 'Импорт поставлен в очередь');

    if ($action === 'remap_offer_ids') {
        $source = trim((string)($params['source'] ?? ''));
        if ($source !== 'upload') {
            throw new RuntimeException('Для замены артикулов выбери источник «Загрузить файл» и CSV-карту.');
        }
        $storedFile = trim((string)($params['stored_file'] ?? ''));
        $storedFileName = trim((string)($params['stored_file_name'] ?? ''));
        $path = supplier_import_stored_source_path($storedFile, $cfg);
        $sourceUrl = $storedFileName !== '' ? $storedFileName : $storedFile;
        $progress(1, 100, 'source', 'Читаю CSV-карту артикулов');

        $result = supplier_products_remap_offer_ids_from_csv_file(
            $supplierId,
            $path,
            $cfg,
            static function (int $done, int $total, string $stage, string $message) use ($progress): void {
                $ratio = min($done, max(1, $total)) / max(1, $total);
                $scaled = 5 + (int)round($ratio * 90);
                $progress($scaled, 100, $stage, $message);
            },
            $log
        );

        $label = 'Артикулы заменены';
        $progress(100, 100, 'done', $label);
        $result['operation_label'] = $label;
        $result['source'] = $source;
        $result['source_label'] = 'CSV-карта: ' . $sourceUrl;

        $report = [
            'title' => 'supplier_import_catalog',
            'storage' => 'supplier_products_db',
            'summary' => $result,
            'params_effective' => [
                'action' => $action,
                'source' => $source,
                'file' => $sourceUrl,
            ],
        ];
        $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
        $outputs['summary_json_inline'] = [
            'title' => $label,
            'items' => [
                $label,
                'Источник: CSV-карта ' . $sourceUrl,
                'Пар в карте: ' . (int)($result['source_offers'] ?? 0),
                'Заменено: ' . (int)($result['updated'] ?? 0),
                'Не найдено: ' . (int)($result['missing'] ?? 0),
                'Конфликты: ' . (int)($result['conflicts'] ?? 0),
                'Без изменений: ' . (int)($result['noop'] ?? 0),
            ],
            'metrics' => $result,
        ];
        return $outputs;
    }

    if ($action === 'remap_wb_vendor_codes') {
        $source = trim((string)($params['source'] ?? ''));
        if ($source !== 'upload') {
            throw new RuntimeException('Для замены артикулов WB выбери источник «Загрузить файл» и CSV-карту.');
        }
        $storedFile = trim((string)($params['stored_file'] ?? ''));
        $storedFileName = trim((string)($params['stored_file_name'] ?? ''));
        $path = supplier_import_stored_source_path($storedFile, $cfg);
        $sourceUrl = $storedFileName !== '' ? $storedFileName : $storedFile;
        $progress(1, 100, 'source', 'Читаю CSV-карту артикулов WB');

        $result = supplier_push_wb_remap_vendor_codes_from_csv_file(
            $cfg,
            $datasetId,
            $supplierId,
            $opId,
            [
                'connection_id' => (int)($params['wb_connection_id'] ?? 0),
            ] + $params,
            $path,
            $log
        );

        $label = 'Артикулы WB отправлены на замену';
        $progress(100, 100, 'done', $label);
        $result['operation_label'] = $label;
        $result['source'] = $source;
        $result['source_label'] = 'CSV-карта: ' . $sourceUrl;

        $report = [
            'title' => 'supplier_import_catalog',
            'storage' => 'supplier_products_db',
            'summary' => $result,
            'params_effective' => [
                'action' => $action,
                'source' => $source,
                'file' => $sourceUrl,
                'wb_connection_id' => (int)($params['wb_connection_id'] ?? 0),
            ],
        ];
        $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
        $outputs['summary_json_inline'] = [
            'title' => $label,
            'items' => [
                $label,
                'Источник: CSV-карта ' . $sourceUrl,
                'Пар в карте: ' . (int)($result['source_offers'] ?? 0),
                'Принято WB: ' . (int)($result['updated'] ?? 0),
                'Уже были на новых артикулах: ' . (int)($result['already_replaced'] ?? 0),
                'Ошибки отправки: ' . (int)($result['failed'] ?? 0),
                'Не найдено на WB: ' . (int)($result['missing'] ?? 0),
                'Конфликты: ' . (int)($result['conflicts'] ?? 0),
                'Заблокировано из-за остатка/заказов WB: ' . (int)($result['activity_blocked'] ?? 0),
                'Без изменений: ' . (int)($result['noop'] ?? 0),
            ],
            'metrics' => $result,
        ];
        return $outputs;
    }

    $cleanupPaths = [];
    try {
        [$source, $sourceUrl, $sourceData, $cleanupPaths] = supplier_products_db_import_source_data(
            $datasetId,
            $supplierId,
            $supplier,
            $cfg,
            $params,
            $action,
            $selectedIds,
            $progress,
            $log
        );

        $sourceData['progress'] = static function (int $done, int $total, string $stage, string $message) use ($progress): void {
            $ratio = min($done, max(1, $total)) / max(1, $total);
            $scaled = 20 + (int)round($ratio * 75);
            $progress($scaled, 100, $stage, $message);
        };

        $commonOptions = [
            'selected_offer_ids' => $selectedIds,
            'progress' => static function (int $done, int $total, string $stage, string $message) use ($progress): void {
                $ratio = min($done, max(1, $total)) / max(1, $total);
                $scaled = 20 + (int)round($ratio * 75);
                $progress($scaled, 100, $stage, $message);
            },
        ];

        if ($action === 'quick_prices_stock') {
            $result = supplier_products_update_prices_stock_from_source(
                $supplierId,
                $sourceData,
                supplier_products_db_import_param_bool($params, 'zero_missing_stock'),
                $cfg,
                $sourceUrl,
                $commonOptions + [
                    'scope' => in_array((string)($params['quick_scope'] ?? 'all'), ['all', 'selected'], true)
                        ? (string)$params['quick_scope']
                        : 'all',
                ]
            );
            $label = 'Цены и остатки обновлены';
        } elseif ($action === 'quick_dimensions') {
            $result = supplier_products_update_dimensions_from_source(
                $supplierId,
                $sourceData,
                $cfg,
                $sourceUrl,
                $commonOptions + [
                    'scope' => in_array((string)($params['quick_scope'] ?? 'all'), ['all', 'selected'], true)
                        ? (string)$params['quick_scope']
                        : 'all',
                ]
            );
            $label = 'Размеры обновлены';
        } elseif ($action === 'replace_catalog') {
            $result = supplier_products_replace_catalog_from_source($supplierId, $sourceData, $cfg, $sourceUrl);
            $label = 'Каталог товаров полностью заменен';
        } elseif ($action === 'delete_stale') {
            $result = supplier_products_delete_stale_from_source($supplierId, $sourceData, $cfg, $sourceUrl);
            $label = 'Неактуальные товары удалены';
        } else {
            $mode = trim((string)($params['mode'] ?? 'add_update'));
            $scope = trim((string)($params['scope'] ?? 'all'));
            $result = supplier_products_import_source_with_options($supplierId, $sourceData, [
                'mode' => in_array($mode, ['add_only', 'add_update', 'update_only'], true) ? $mode : 'add_update',
                'scope' => in_array($scope, ['all', 'selected'], true) ? $scope : 'all',
                'selected_offer_ids' => $selectedIds,
                'replace_names' => supplier_products_db_import_param_bool($params, 'replace_names'),
                'brand_mode' => trim((string)($params['brand_mode'] ?? 'no_update')),
                'model_mode' => trim((string)($params['model_mode'] ?? 'no_update')),
                'description_mode' => trim((string)($params['description_mode'] ?? 'no_update')),
                'update_supplier_category' => supplier_products_db_import_param_bool($params, 'update_supplier_category'),
                'characteristics_mode' => trim((string)($params['characteristics_mode'] ?? 'no_update')),
                'photos_mode' => trim((string)($params['photos_mode'] ?? 'no_replace')),
                'progress' => $commonOptions['progress'],
            ], $cfg, $sourceUrl);
            $label = 'Импорт выполнен';
        }

        $progress(100, 100, 'done', $label);
        $result['operation_label'] = $label;
        $result['source'] = $source;
        $result['source_label'] = supplier_marketplace_import_label($source);

        $report = [
            'title' => 'supplier_import_catalog',
            'storage' => 'supplier_products_db',
            'summary' => $result,
            'params_effective' => [
                'action' => $action,
                'source' => $source,
                'selected_offers' => count($selectedIds),
            ],
        ];
        $outputs = supplier_products_db_report_output($cfg, $datasetId, $opId, $report);
        $items = [
            $label,
            'Источник: ' . supplier_marketplace_import_label($source),
            'Товаров в источнике: ' . (int)($result['source_offers'] ?? 0),
            'Добавлено: ' . (int)($result['added'] ?? 0),
            'Обновлено: ' . (int)($result['updated'] ?? 0),
        ];
        if (array_key_exists('deleted', $result)) {
            $items[] = 'Удалено: ' . (int)($result['deleted'] ?? 0);
        }
        $items[] = 'Пропущено: ' . ((int)($result['skipped_existing'] ?? 0) + (int)($result['skipped_new'] ?? 0) + (int)($result['skipped_scope'] ?? 0));
        $outputs['summary_json_inline'] = [
            'title' => $label,
            'items' => $items,
            'metrics' => $result,
        ];
        return $outputs;
    } finally {
        foreach ($cleanupPaths as $pathToClean) {
            if (is_string($pathToClean) && $pathToClean !== '' && is_file($pathToClean)) {
                @unlink($pathToClean);
            }
        }
    }
}

function supplier_products_run_db_operation(array $cfg, array $ds, int $opId, array $params, callable $log, string $opType, array $opMeta): array
{
    if ($opType === 'run_pipeline') {
        return supplier_products_db_op_run_pipeline($cfg, $ds, $opId, $params, $log, $opMeta);
    }
    return supplier_products_db_run_registered_handler($cfg, $ds, $opId, $params, $log, $opType, $opMeta);
}
